-- ============================================================
-- 圣经全文（新改訳2017）· 数据文件 1/6
-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5200 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '创世纪', 1, 1, 1, 'はじめに神が天と地を創造された。'),
('JPN', '创世纪', 1, 1, 2, '地は茫漠として何もなく、闇が大水の面の上にあり、神の霊がその水の面を動いていた。'),
('JPN', '创世纪', 1, 1, 3, '神は仰せられた。「光、あれ。」すると光があった。'),
('JPN', '创世纪', 1, 1, 4, '神は光を良しと見られた。神は光と闇を分けられた。'),
('JPN', '创世纪', 1, 1, 5, '神は光を昼と名づけ、闇を夜と名づけられた。夕があり、朝があった。第一日。'),
('JPN', '创世纪', 1, 1, 6, '神は仰せられた。「大空よ、水の真っただ中にあれ。水と水の間を分けるものとなれ。」'),
('JPN', '创世纪', 1, 1, 7, '神は大空を造り、大空の下にある水と大空の上にある水を分けられた。すると、そのようになった。'),
('JPN', '创世纪', 1, 1, 8, '神は大空を天と名づけられた。夕があり、朝があった。第二日。'),
('JPN', '创世纪', 1, 1, 9, '神は仰せられた。「天の下の水は一つの所に集まれ。乾いた所が現れよ。」すると、そのようになった。'),
('JPN', '创世纪', 1, 1, 10, '神は乾いた所を地と名づけ、水の集まった所を海と名づけられた。神はそれを良しと見られた。'),
('JPN', '创世纪', 1, 1, 11, '神は仰せられた。「地は植物を、種のできる草や、種の入った実を結ぶ果樹を、種類ごとに地の上に芽生えさせよ。」すると、そのようになった。'),
('JPN', '创世纪', 1, 1, 12, '地は植物を、すなわち、種のできる草を種類ごとに、また種の入った実を結ぶ木を種類ごとに生じさせた。神はそれを良しと見られた。'),
('JPN', '创世纪', 1, 1, 13, '夕があり、朝があった。第三日。'),
('JPN', '创世纪', 1, 1, 14, '神は仰せられた。「光る物が天の大空にあれ。昼と夜を分けよ。定められた時々のため、日と年のためのしるしとなれ。'),
('JPN', '创世纪', 1, 1, 15, 'また天の大空で光る物となり、地の上を照らすようになれ。」すると、そのようになった。'),
('JPN', '创世纪', 1, 1, 16, '神は二つの大きな光る物を造られた。大きいほうの光る物には昼を治めさせ、小さいほうの光る物には夜を治めさせた。また星も造られた。'),
('JPN', '创世纪', 1, 1, 17, '神はそれらを天の大空に置き、地の上を照らさせ、'),
('JPN', '创世纪', 1, 1, 18, 'また昼と夜を治めさせ、光と闇を分けるようにされた。神はそれを良しと見られた。'),
('JPN', '创世纪', 1, 1, 19, '夕があり、朝があった。第四日。'),
('JPN', '创世纪', 1, 1, 20, '神は仰せられた。「水には生き物が群がれ。鳥は地の上、天の大空を飛べ。」'),
('JPN', '创世纪', 1, 1, 21, '神は、海の巨獣と、水に群がりうごめくすべての生き物を種類ごとに、また翼のあるすべての鳥を種類ごとに創造された。神はそれを良しと見られた。'),
('JPN', '创世纪', 1, 1, 22, '神はそれらを祝福して、「生めよ。増えよ。海の水に満ちよ。鳥は地の上に増えよ」と仰せられた。'),
('JPN', '创世纪', 1, 1, 23, '夕があり、朝があった。第五日。'),
('JPN', '创世纪', 1, 1, 24, '神は仰せられた。「地は生き物を種類ごとに、家畜や、這うもの、地の獣を種類ごとに生じよ。」すると、そのようになった。'),
('JPN', '创世纪', 1, 1, 25, '神は、地の獣を種類ごとに、家畜を種類ごとに、地面を這うすべてのものを種類ごとに造られた。神はそれを良しと見られた。'),
('JPN', '创世纪', 1, 1, 26, '神は仰せられた。「さあ、人をわれわれのかたちとして、われわれの似姿に造ろう。こうして彼らが、海の魚、空の鳥、家畜、地のすべてのもの、地の上を這うすべてのものを支配するようにしよう。」'),
('JPN', '创世纪', 1, 1, 27, '神は人をご自身のかたちとして創造された。神のかたちとして人を創造し、男と女に彼らを創造された。'),
('JPN', '创世纪', 1, 1, 28, '神は彼らを祝福された。神は彼らに仰せられた。「生めよ。増えよ。地に満ちよ。地を従えよ。海の魚、空の鳥、地の上を這うすべての生き物を支配せよ。」'),
('JPN', '创世纪', 1, 1, 29, '神は仰せられた。「見よ。わたしは、地の全面にある、種のできるすべての草と、種の入った実のあるすべての木を、今あなたがたに与える。あなたがたにとってそれは食物となる。'),
('JPN', '创世纪', 1, 1, 30, 'また、生きるいのちのある、地のすべての獣、空のすべての鳥、地の上を這うすべてのもののために、すべての緑の草を食物として与える。」すると、そのようになった。'),
('JPN', '创世纪', 1, 1, 31, '神はご自分が造ったすべてのものを見られた。見よ、それは非常に良かった。夕があり、朝があった。第六日。'),
('JPN', '创世纪', 1, 2, 1, 'こうして天と地とその万象が完成した。'),
('JPN', '创世纪', 1, 2, 2, '神は第七日に、なさっていたわざを完成し、第七日に、なさっていたすべてのわざをやめられた。'),
('JPN', '创世纪', 1, 2, 3, '神は第七日を祝福し、この日を聖なるものとされた。その日に神が、なさっていたすべての創造のわざをやめられたからである。'),
('JPN', '创世纪', 1, 2, 4, 'これは、天と地が創造されたときの経緯である。神である主が、地と天を造られたときのこと。'),
('JPN', '创世纪', 1, 2, 5, '地にはまだ、野の灌木もなく、野の草も生えていなかった。神である主が、地の上に雨を降らせていなかったからである。また、大地を耕す人もまだいなかった。'),
('JPN', '创世纪', 1, 2, 6, 'ただ、豊かな水が地から湧き上がり、大地の全面を潤していた。'),
('JPN', '创世纪', 1, 2, 7, '神である主は、その大地のちりで人を形造り、その鼻にいのちの息を吹き込まれた。それで人は生きるものとなった。'),
('JPN', '创世纪', 1, 2, 8, '神である主は東の方のエデンに園を設け、そこにご自分が形造った人を置かれた。'),
('JPN', '创世纪', 1, 2, 9, '神である主は、その土地に、見るからに好ましく、食べるのに良いすべての木を、そして、園の中央にいのちの木を、また善悪の知識の木を生えさせた。'),
('JPN', '创世纪', 1, 2, 10, '一つの川がエデンから湧き出て、園を潤していた。それは園から分かれて、四つの源流となっていた。'),
('JPN', '创世纪', 1, 2, 11, '第一のものの名はピション。それはハビラの全土を巡って流れていた。そこには金があった。'),
('JPN', '创世纪', 1, 2, 12, 'その地の金は良質で、そこにはベドラハとショハム石もあった。'),
('JPN', '创世纪', 1, 2, 13, '第二の川の名はギホン。それはクシュの全土を巡って流れていた。'),
('JPN', '创世纪', 1, 2, 14, '第三の川の名はティグリス。それはアッシュルの東を流れていた。第四の川、それはユーフラテスである。'),
('JPN', '创世纪', 1, 2, 15, '神である主は人を連れて来て、エデンの園に置き、そこを耕させ、また守らせた。'),
('JPN', '创世纪', 1, 2, 16, '神である主は人に命じられた。「あなたは園のどの木からでも思いのまま食べてよい。'),
('JPN', '创世纪', 1, 2, 17, 'しかし、善悪の知識の木からは、食べてはならない。その木から食べるとき、あなたは必ず死ぬ。」'),
('JPN', '创世纪', 1, 2, 18, 'また、神である主は言われた。「人がひとりでいるのは良くない。わたしは人のために、ふさわしい助け手を造ろう。」'),
('JPN', '创世纪', 1, 2, 19, '神である主は、その土地の土で、あらゆる野の獣とあらゆる空の鳥を形造って、人のところに連れて来られた。人がそれを何と呼ぶかをご覧になるためであった。人がそれを呼ぶと、何であれ、それがその生き物の名となった。'),
('JPN', '创世纪', 1, 2, 20, '人はすべての家畜、空の鳥、すべての野の獣に名をつけた。しかし、アダムには、ふさわしい助け手が見つからなかった。'),
('JPN', '创世纪', 1, 2, 21, '神である主は、深い眠りを人に下された。それで、人は眠った。主は彼のあばら骨の一つを取り、そのところを肉でふさがれた。'),
('JPN', '创世纪', 1, 2, 22, '神である主は、人から取ったあばら骨を一人の女に造り上げ、人のところに連れて来られた。'),
('JPN', '创世纪', 1, 2, 23, '人は言った。「これこそ、ついに私の骨からの骨、私の肉からの肉。これを女と名づけよう。男から取られたのだから。」'),
('JPN', '创世纪', 1, 2, 24, 'それゆえ、男は父と母を離れ、その妻と結ばれ、ふたりは一体となるのである。'),
('JPN', '创世纪', 1, 2, 25, 'そのとき、人とその妻はふたりとも裸であったが、恥ずかしいとは思わなかった。'),
('JPN', '创世纪', 1, 3, 1, 'さて蛇は、神である主が造られた野の生き物のうちで、ほかのどれよりも賢かった。蛇は女に言った。「園の木のどれからも食べてはならないと、神は本当に言われたのですか。」'),
('JPN', '创世纪', 1, 3, 2, '女は蛇に言った。「私たちは園の木の実を食べてもよいのです。'),
('JPN', '创世纪', 1, 3, 3, 'しかし、園の中央にある木の実については、『あなたがたは、それを食べてはならない。それに触れてもいけない。あなたがたが死ぬといけないからだ』と神は仰せられました。」'),
('JPN', '创世纪', 1, 3, 4, 'すると、蛇は女に言った。「あなたがたは決して死にません。'),
('JPN', '创世纪', 1, 3, 5, 'それを食べるそのとき、目が開かれて、あなたがたが神のようになって善悪を知る者となることを、神は知っているのです。」'),
('JPN', '创世纪', 1, 3, 6, 'そこで、女が見ると、その木は食べるのに良さそうで、目に慕わしく、またその木は賢くしてくれそうで好ましかった。それで、女はその実を取って食べ、ともにいた夫にも与えたので、夫も食べた。'),
('JPN', '创世纪', 1, 3, 7, 'こうして、ふたりの目は開かれ、自分たちが裸であることを知った。そこで彼らは、いちじくの葉をつづり合わせて、自分たちのために腰の覆いを作った。'),
('JPN', '创世纪', 1, 3, 8, 'そよ風の吹くころ、彼らは、神である主が園を歩き回られる音を聞いた。それで人とその妻は、神である主の御顔を避けて、園の木の間に身を隠した。'),
('JPN', '创世纪', 1, 3, 9, '神である主は、人に呼びかけ、彼に言われた。「あなたはどこにいるのか。」'),
('JPN', '创世纪', 1, 3, 10, '彼は言った。「私は、あなたの足音を園の中で聞いたので、自分が裸であるのを恐れて、身を隠しています。」'),
('JPN', '创世纪', 1, 3, 11, '主は言われた。「あなたが裸であることを、だれがあなたに告げたのか。あなたは、食べてはならない、とわたしが命じた木から食べたのか。」'),
('JPN', '创世纪', 1, 3, 12, '人は言った。「私のそばにいるようにとあなたが与えてくださったこの女が、あの木から取って私にくれたので、私は食べたのです。」'),
('JPN', '创世纪', 1, 3, 13, '神である主は女に言われた。「あなたは何ということをしたのか。」女は言った。「蛇が私を惑わしたのです。それで私は食べました。」'),
('JPN', '创世纪', 1, 3, 14, '神である主は蛇に言われた。「おまえは、このようなことをしたので、どんな家畜よりも、どんな野の生き物よりものろわれる。おまえは腹這いで動き回り、一生、ちりを食べることになる。'),
('JPN', '创世纪', 1, 3, 15, 'わたしは敵意を、おまえと女の間に、おまえの子孫と女の子孫の間に置く。彼はおまえの頭を打ち、おまえは彼のかかとを打つ。」'),
('JPN', '创世纪', 1, 3, 16, '女にはこう言われた。「わたしは、あなたの苦しみとうめきを大いに増す。あなたは苦しんで子を産む。また、あなたは夫を恋い慕うが、彼はあなたを支配することになる。」'),
('JPN', '创世纪', 1, 3, 17, 'また、人に言われた。「あなたが妻の声に聞き従い、食べてはならないとわたしが命じておいた木から食べたので、大地は、あなたのゆえにのろわれる。あなたは一生の間、苦しんでそこから食を得ることになる。'),
('JPN', '创世纪', 1, 3, 18, '大地は、あなたに対して茨とあざみを生えさせ、あなたは野の草を食べる。'),
('JPN', '创世纪', 1, 3, 19, 'あなたは、顔に汗を流して糧を得、ついにはその大地に帰る。あなたはそこから取られたのだから。あなたは土のちりだから、土のちりに帰るのだ。」'),
('JPN', '创世纪', 1, 3, 20, '人は妻の名をエバと呼んだ。彼女が、生きるものすべての母だからであった。'),
('JPN', '创世纪', 1, 3, 21, '神である主は、アダムとその妻のために、皮の衣を作って彼らに着せられた。'),
('JPN', '创世纪', 1, 3, 22, '神である主はこう言われた。「見よ。人はわれわれのうちのひとりのようになり、善悪を知るようになった。今、人がその手を伸ばして、いのちの木からも取って食べ、永遠に生きることがないようにしよう。」'),
('JPN', '创世纪', 1, 3, 23, '神である主は、人をエデンの園から追い出し、人が自分が取り出された大地を耕すようにされた。'),
('JPN', '创世纪', 1, 3, 24, 'こうして神は人を追放し、いのちの木への道を守るために、ケルビムと、輪を描いて回る炎の剣をエデンの園の東に置かれた。'),
('JPN', '创世纪', 1, 4, 1, '人は、その妻エバを知った。彼女は身ごもってカインを産み、「私は、主によって一人の男子を得た」と言った。'),
('JPN', '创世纪', 1, 4, 2, '彼女はまた、その弟アベルを産んだ。アベルは羊を飼う者となり、カインは大地を耕す者となった。'),
('JPN', '创世纪', 1, 4, 3, 'しばらく時が過ぎて、カインは大地の実りを主へのささげ物として持って来た。'),
('JPN', '创世纪', 1, 4, 4, 'アベルもまた、自分の羊の初子の中から、肥えたものを持って来た。主はアベルとそのささげ物に目を留められた。'),
('JPN', '创世纪', 1, 4, 5, 'しかし、カインとそのささげ物には目を留められなかった。それでカインは激しく怒り、顔を伏せた。'),
('JPN', '创世纪', 1, 4, 6, '主はカインに言われた。「なぜ、あなたは怒っているのか。なぜ顔を伏せているのか。'),
('JPN', '创世纪', 1, 4, 7, 'もしあなたが良いことをしているのなら、受け入れられる。しかし、もし良いことをしていないのであれば、戸口で罪が待ち伏せている。罪はあなたを恋い慕うが、あなたはそれを治めなければならない。」'),
('JPN', '创世纪', 1, 4, 8, 'カインは弟アベルを誘い出した。二人が野にいたとき、カインは弟アベルに襲いかかって殺した。'),
('JPN', '创世纪', 1, 4, 9, '主はカインに言われた。「あなたの弟アベルは、どこにいるのか。」カインは言った。「私は知りません。私は弟の番人なのでしょうか。」'),
('JPN', '创世纪', 1, 4, 10, '主は言われた。「いったい、あなたは何ということをしたのか。声がする。あなたの弟の血が、その大地からわたしに向かって叫んでいる。'),
('JPN', '创世纪', 1, 4, 11, '今や、あなたはのろわれている。そして、口を開けてあなたの手から弟の血を受けた大地から、あなたは追い出される。'),
('JPN', '创世纪', 1, 4, 12, 'あなたが耕しても、大地はもはや、あなたのために作物を生じさせない。あなたは地上をさまよい歩くさすらい人となる。」'),
('JPN', '创世纪', 1, 4, 13, 'カインは主に言った。「私の咎は大きすぎて、負いきれません。'),
('JPN', '创世纪', 1, 4, 14, 'あなたが、今日、私を大地の面から追い出されたので、私はあなたの御顔を避けて隠れ、地上をさまよい歩くさすらい人となります。私を見つけた人は、だれでも私を殺すでしょう。」'),
('JPN', '创世纪', 1, 4, 15, '主は彼に言われた。「それゆえ、わたしは言う。だれであれ、カインを殺す者は七倍の復讐を受ける。」主は、彼を見つけた人が、だれも彼を打ち殺すことのないように、カインに一つのしるしをつけられた。'),
('JPN', '创世纪', 1, 4, 16, 'カインは主の前から出て行って、エデンの東、ノデの地に住んだ。'),
('JPN', '创世纪', 1, 4, 17, 'カインはその妻を知った。彼女は身ごもってエノクを産んだ。カインは町を建てていたので、息子の名にちなんで、その町をエノクと名づけた。'),
('JPN', '创世纪', 1, 4, 18, 'エノクにはイラデが生まれた。イラデはメフヤエルを生み、メフヤエルはメトシャエルを生み、メトシャエルはレメクを生んだ。'),
('JPN', '创世纪', 1, 4, 19, 'レメクは二人の妻を迎えた。一人の名はアダ、もう一人の名はツィラであった。'),
('JPN', '创世纪', 1, 4, 20, 'アダはヤバルを産んだ。ヤバルは天幕に住む者、家畜を飼う者の先祖となった。'),
('JPN', '创世纪', 1, 4, 21, 'その弟の名はユバルであった。彼は竪琴と笛を奏でるすべての者の先祖となった。'),
('JPN', '创世纪', 1, 4, 22, '一方、ツィラはトバル・カインを産んだ。彼は青銅と鉄のあらゆる道具を造る者であった。トバル・カインの妹はナアマであった。'),
('JPN', '创世纪', 1, 4, 23, 'レメクは妻たちに言った。「アダとツィラよ、私の声を聞け。レメクの妻たちよ、私の言うことに耳を傾けよ。私は一人の男を、私が受ける傷のために殺す。一人の子どもを、私が受ける打ち傷のために。'),
('JPN', '创世纪', 1, 4, 24, 'カインに七倍の復讐があるなら、レメクには七十七倍。」'),
('JPN', '创世纪', 1, 4, 25, 'アダムは再び妻を知った。彼女は男の子を産み、その子をセツと名づけた。カインがアベルを殺したので、彼女は「神が、アベルの代わりに別の子孫を私に授けてくださいました」と言った。'),
('JPN', '创世纪', 1, 4, 26, 'セツにもまた、男の子が生まれた。セツは彼の名をエノシュと呼んだ。そのころ、人々は主の名を呼ぶことを始めた。'),
('JPN', '创世纪', 1, 5, 1, 'これはアダムの歴史の記録である。神は、人を創造したとき、神の似姿として人を造り、'),
('JPN', '创世纪', 1, 5, 2, '男と女に彼らを創造された。彼らが創造された日に、神は彼らを祝福して、彼らの名を「人」と呼ばれた。'),
('JPN', '创世纪', 1, 5, 3, 'アダムは百三十年生きて、彼の似姿として、彼のかたちに男の子を生んだ。彼はその子をセツと名づけた。'),
('JPN', '创世纪', 1, 5, 4, 'セツを生んでからのアダムの生涯は八百年で、彼は息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 5, 5, 'アダムが生きた全生涯は九百三十年であった。こうして彼は死んだ。'),
('JPN', '创世纪', 1, 5, 6, 'セツは百五年生きて、エノシュを生んだ。'),
('JPN', '创世纪', 1, 5, 7, 'セツはエノシュを生んでから八百七年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 5, 8, 'セツの全生涯は九百十二年であった。こうして彼は死んだ。'),
('JPN', '创世纪', 1, 5, 9, 'エノシュは九十年生きて、ケナンを生んだ。'),
('JPN', '创世纪', 1, 5, 10, 'エノシュはケナンを生んでから八百十五年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 5, 11, 'エノシュの全生涯は九百五年であった。こうして彼は死んだ。'),
('JPN', '创世纪', 1, 5, 12, 'ケナンは七十年生きて、マハラルエルを生んだ。'),
('JPN', '创世纪', 1, 5, 13, 'ケナンはマハラルエルを生んでから八百四十年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 5, 14, 'ケナンの全生涯は九百十年であった。こうして彼は死んだ。'),
('JPN', '创世纪', 1, 5, 15, 'マハラルエルは六十五年生きて、ヤレデを生んだ。'),
('JPN', '创世纪', 1, 5, 16, 'マハラルエルはヤレデを生んでから八百三十年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 5, 17, 'マハラルエルの全生涯は八百九十五年であった。こうして彼は死んだ。'),
('JPN', '创世纪', 1, 5, 18, 'ヤレデは百六十二年生きて、エノクを生んだ。'),
('JPN', '创世纪', 1, 5, 19, 'ヤレデはエノクを生んでから八百年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 5, 20, 'ヤレデの全生涯は九百六十二年であった。こうして彼は死んだ。'),
('JPN', '创世纪', 1, 5, 21, 'エノクは六十五年生きて、メトシェラを生んだ。'),
('JPN', '创世纪', 1, 5, 22, 'エノクはメトシェラを生んでから三百年、神とともに歩み、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 5, 23, 'エノクの全生涯は三百六十五年であった。'),
('JPN', '创世纪', 1, 5, 24, 'エノクは神とともに歩んだ。神が彼を取られたので、彼はいなくなった。'),
('JPN', '创世纪', 1, 5, 25, 'メトシェラは百八十七年生きて、レメクを生んだ。'),
('JPN', '创世纪', 1, 5, 26, 'メトシェラはレメクを生んでから七百八十二年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 5, 27, 'メトシェラの全生涯は九百六十九年であった。こうして彼は死んだ。'),
('JPN', '创世纪', 1, 5, 28, 'レメクは百八十二年生きて、一人の男の子を生んだ。'),
('JPN', '创世纪', 1, 5, 29, '彼はその子をノアと名づけて言った。「この子は、主がのろわれたこの地での、私たちの働きと手の労苦から、私たちを慰めてくれるだろう。」'),
('JPN', '创世纪', 1, 5, 30, 'レメクはノアを生んでから五百九十五年生きて、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 5, 31, 'レメクの全生涯は七百七十七年であった。こうして彼は死んだ。'),
('JPN', '创世纪', 1, 5, 32, 'ノアは五百歳になった。そしてノアはセム、ハム、ヤフェテを生んだ。'),
('JPN', '创世纪', 1, 6, 1, 'さて、人が大地の面に増え始め、娘たちが彼らに生まれたとき、'),
('JPN', '创世纪', 1, 6, 2, '神の子らは、人の娘たちが美しいのを見て、それぞれ自分が選んだ者を妻とした。'),
('JPN', '创世纪', 1, 6, 3, 'そこで、主は言われた。「わたしの霊は、人のうちに永久にとどまることはない。人は肉にすぎないからだ。だから、人の齢は百二十年にしよう。」'),
('JPN', '创世纪', 1, 6, 4, '神の子らが人の娘たちのところに入り、彼らに子ができたそのころ、またその後も、ネフィリムが地にいた。彼らは昔からの勇士であり、名のある者たちであった。'),
('JPN', '创世纪', 1, 6, 5, '主は、地上に人の悪が増大し、その心に図ることがみな、いつも悪に傾くのをご覧になった。'),
('JPN', '创世纪', 1, 6, 6, 'それで主は、地上に人を造ったことを悔やみ、心を痛められた。'),
('JPN', '创世纪', 1, 6, 7, 'そして主は言われた。「わたしが創造した人を地の面から消し去ろう。人をはじめ、家畜や這うもの、空の鳥に至るまで。わたしは、これらを造ったことを悔やむ。」'),
('JPN', '创世纪', 1, 6, 8, 'しかし、ノアは主の心にかなっていた。'),
('JPN', '创世纪', 1, 6, 9, 'これはノアの歴史である。ノアは正しい人で、彼の世代の中にあって全き人であった。ノアは神とともに歩んだ。'),
('JPN', '创世纪', 1, 6, 10, 'ノアは三人の息子、セム、ハム、ヤフェテを生んだ。'),
('JPN', '创世纪', 1, 6, 11, '地は神の前に堕落し、地は暴虐で満ちていた。'),
('JPN', '创世纪', 1, 6, 12, '神が地をご覧になると、見よ、それは堕落していた。すべての肉なるものが、地上で自分の道を乱していたからである。'),
('JPN', '创世纪', 1, 6, 13, '神はノアに仰せられた。「すべての肉なるものの終わりが、わたしの前に来ようとしている。地は、彼らのゆえに、暴虐で満ちているからだ。見よ、わたしは彼らを地とともに滅ぼし去る。'),
('JPN', '创世纪', 1, 6, 14, 'あなたは自分のために、ゴフェルの木で箱舟を造りなさい。箱舟に部屋を作り、内と外にタールを塗りなさい。'),
('JPN', '创世纪', 1, 6, 15, 'それを次のようにして造りなさい。箱舟の長さは三百キュビト。幅は五十キュビト。高さは三十キュビト。'),
('JPN', '创世纪', 1, 6, 16, '箱舟に天窓を作り、上部から一キュビト以内に天窓を仕上げなさい。また、箱舟の戸口をその側面に設け、箱舟を一階と二階と三階に分けなさい。'),
('JPN', '创世纪', 1, 6, 17, 'わたしは、今、いのちの息のあるすべての肉なるものを天の下から滅ぼし去るために、地上に大水を、大洪水をもたらそうとしている。地上のすべてのものは死に絶える。'),
('JPN', '创世纪', 1, 6, 18, 'しかし、わたしはあなたと契約を結ぶ。あなたは、息子たち、妻、それに息子たちの妻とともに箱舟に入りなさい。'),
('JPN', '创世纪', 1, 6, 19, 'また、すべての生き物、すべての肉なるものの中から、それぞれ二匹ずつを箱舟に連れて入り、あなたとともに生き残るようにしなさい。それらは雄と雌でなければならない。'),
('JPN', '创世纪', 1, 6, 20, '鳥は種類ごとに、動物も種類ごとに、また地面を這うすべてのものも種類ごとに、それぞれ二匹ずつが生き残れるよう、あなたのところに来なければならない。'),
('JPN', '创世纪', 1, 6, 21, 'あなたは、食べられるあらゆるものから採って、自分のところに集め、あなたとそれらの動物のための食物としなさい。」'),
('JPN', '创世纪', 1, 6, 22, 'ノアは、すべて神が命じられたとおりにし、そのように行った。'),
('JPN', '创世纪', 1, 7, 1, '主はノアに言われた。「あなたとあなたの全家は、箱舟に入りなさい。この世代の中にあって、あなたがわたしの前に正しいことが分かったからである。'),
('JPN', '创世纪', 1, 7, 2, 'あなたは、すべてのきよい動物の中から雄と雌を七つがいずつ、きよくない動物の中から雄と雌を一つがいずつ、'),
('JPN', '创世纪', 1, 7, 3, 'また空の鳥の中からも雄と雌を七つがいずつ取りなさい。それらの種類が全地の面で生き残るためである。'),
('JPN', '创世纪', 1, 7, 4, 'あと七日たつと、わたしは、地の上に四十日四十夜、雨を降らせ、わたしが造ったすべての生けるものを大地の面から消し去る。」'),
('JPN', '创世纪', 1, 7, 5, 'ノアは、すべて主が彼に命じられたとおりにした。'),
('JPN', '创世纪', 1, 7, 6, 'ノアは六百歳であったが、そのときに大洪水が起こり、大水は地の上にあった。'),
('JPN', '创世纪', 1, 7, 7, 'ノアは息子たちや自分の妻、それに息子たちの妻とともに、大洪水の大水を避けるために箱舟に入った。'),
('JPN', '创世纪', 1, 7, 8, 'きよい動物、きよくない動物、鳥、地面を這うすべてのものの中から、'),
('JPN', '创世纪', 1, 7, 9, '雄と雌がつがいになって箱舟の中のノアのところにやって来た。神がノアに命じられたとおりであった。'),
('JPN', '创世纪', 1, 7, 10, '七日たつと、大洪水の大水が地の上に生じた。'),
('JPN', '创世纪', 1, 7, 11, 'ノアの生涯の六百年目の第二の月の十七日、その日に、大いなる淵の源がことごとく裂け、天の水門が開かれた。'),
('JPN', '创世纪', 1, 7, 12, '大雨は四十日四十夜、地に降り続いた。'),
('JPN', '创世纪', 1, 7, 13, 'ちょうどその日に、ノアは、息子たちのセム、ハム、ヤフェテ、またノアの妻と、息子たちの三人の妻とともに、箱舟に入った。'),
('JPN', '创世纪', 1, 7, 14, '彼らとともに、種類ごとにあらゆる獣、種類ごとにあらゆる家畜、種類ごとにあらゆる地の上を這うものと、種類ごとにあらゆる飛ぶもの、鳥や翼のあるものすべてが箱舟に入った。'),
('JPN', '创世纪', 1, 7, 15, 'こうして、いのちの息のあるすべての肉なるものが、二匹ずつノアのいる箱舟の中に入った。'),
('JPN', '创世纪', 1, 7, 16, '入ったものは、すべての肉なるものの雄と雌であった。それらは、神がノアに命じられたとおりに入った。それから、主は彼のうしろの戸を閉ざされた。'),
('JPN', '创世纪', 1, 7, 17, '大洪水は四十日間、地の上にあった。水かさが増して箱舟を押し上げたので、それは地から浮き上がった。'),
('JPN', '创世纪', 1, 7, 18, '水がみなぎり、地の上に大いに増し、箱舟は水面を漂った。'),
('JPN', '创世纪', 1, 7, 19, '水は地の上にますますみなぎり、天の下にある高い山々もすべておおわれた。'),
('JPN', '创世纪', 1, 7, 20, '水は、その上さらに十五キュビト増し加わり、山々はおおわれた。'),
('JPN', '创世纪', 1, 7, 21, 'こうして、地の上を動き回るすべての肉なるものは、鳥も家畜も獣も地に群がるすべてのものも、またすべての人も死に絶えた。'),
('JPN', '创世纪', 1, 7, 22, 'いのちの息を吹き込まれたもので、乾いた地の上にいたものは、みな死んだ。'),
('JPN', '创世纪', 1, 7, 23, 'こうして、主は地の上の生けるものすべてを、人をはじめ、動物、這うもの、空の鳥に至るまで消し去られた。それらは地から消し去られ、ただノアと、彼とともに箱舟にいたものたちだけが残った。'),
('JPN', '创世纪', 1, 7, 24, '水は百五十日間、地の上に増し続けた。'),
('JPN', '创世纪', 1, 8, 1, '神は、ノアと、彼とともに箱舟の中にいた、すべての獣およびすべての家畜を覚えておられた。神は地の上に風を吹き渡らせた。すると水は引き始めた。'),
('JPN', '创世纪', 1, 8, 2, '大水の源と天の水門が閉ざされ、天からの大雨がとどめられた。'),
('JPN', '创世纪', 1, 8, 3, '水は、しだいに地の上から引いていった。水は百五十日の終わりに減り始めた。'),
('JPN', '创世纪', 1, 8, 4, '箱舟は、第七の月の十七日にアララテの山地にとどまった。'),
('JPN', '创世纪', 1, 8, 5, '一方、水は第十の月まで減り続け、第十の月の一日に、山々の頂が現れた。'),
('JPN', '创世纪', 1, 8, 6, '四十日の終わりに、ノアは自分の造った箱舟の窓を開き、'),
('JPN', '创世纪', 1, 8, 7, '烏を放った。すると烏は、水が地の上から乾くまで、出たり戻ったりした。'),
('JPN', '创世纪', 1, 8, 8, 'またノアは、水が地の面から引いたかどうかを見ようと、鳩を彼のもとから放った。'),
('JPN', '创世纪', 1, 8, 9, '鳩は、その足を休める場所を見つけられなかったので、箱舟の彼のもとに帰って来た。水が全地の面にあったからである。彼は手を伸ばして鳩を捕らえ、自分がいる箱舟に入れた。'),
('JPN', '创世纪', 1, 8, 10, 'それからさらに七日待って、再び鳩を箱舟から放った。'),
('JPN', '创世纪', 1, 8, 11, '鳩は夕方になって、彼のもとに帰って来た。すると見よ、取ったばかりのオリーブの若葉がそのくちばしにあるではないか。それで、ノアは水が地の上から引いたのを知った。'),
('JPN', '创世纪', 1, 8, 12, 'さらに、もう七日待って、彼は鳩を放った。鳩はもう彼のところに戻って来なかった。'),
('JPN', '创世纪', 1, 8, 13, '六百一年目の第一の月の一日に、水は地の上から干上がった。ノアが箱舟の覆いを取り払って眺めると、見よ、地の面は乾いていた。'),
('JPN', '创世纪', 1, 8, 14, '第二の月の二十七日には、地はすっかり乾いた。'),
('JPN', '创世纪', 1, 8, 15, '神はノアに告げられた。'),
('JPN', '创世纪', 1, 8, 16, '「あなたは、妻と、息子たちと、息子たちの妻たちとともに箱舟から出なさい。'),
('JPN', '创世纪', 1, 8, 17, 'すべての肉なるもののうち、あなたとともにいる生き物すべて、鳥、家畜、地の上を這うすべてのものが、あなたとともに出るようにしなさい。それらが地に群がり、地の上で生み、そして増えるようにしなさい。」'),
('JPN', '创世纪', 1, 8, 18, 'そこでノアは、息子たち、彼の妻、息子たちの妻たちとともに外に出た。'),
('JPN', '创世纪', 1, 8, 19, 'すべての獣、すべての這うもの、すべての鳥、すべて地の上を動くものも、種類ごとに箱舟から出て来た。'),
('JPN', '创世纪', 1, 8, 20, 'ノアは主のために祭壇を築き、すべてのきよい家畜から、また、すべてのきよい鳥からいくつかを取って、祭壇の上で全焼のささげ物を献げた。'),
('JPN', '创世纪', 1, 8, 21, '主は、その芳ばしい香りをかがれた。そして、心の中で主はこう言われた。「わたしは、決して再び人のゆえに、大地にのろいをもたらしはしない。人の心が思い図ることは、幼いときから悪であるからだ。わたしは、再び、わたしがしたように、生き物すべてを打ち滅ぼすことは決してしない。'),
('JPN', '创世纪', 1, 8, 22, 'この地が続くかぎり、種蒔きと刈り入れ、寒さと暑さ、夏と冬、昼と夜がやむことはない。」'),
('JPN', '创世纪', 1, 9, 1, '神はノアとその息子たちを祝福して、彼らに仰せられた。「生めよ。増えよ。地に満ちよ。'),
('JPN', '创世纪', 1, 9, 2, 'あなたがたへの恐れとおののきが、地のすべての獣、空のすべての鳥、地面を動くすべてのもの、海のすべての魚に起こる。あなたがたの手に、これらは委ねられたのだ。'),
('JPN', '创世纪', 1, 9, 3, '生きて動いているものはみな、あなたがたの食物となる。緑の草と同じように、そのすべてのものを、今、あなたがたに与える。'),
('JPN', '创世纪', 1, 9, 4, 'ただし肉は、そのいのちである血のあるままで食べてはならない。'),
('JPN', '创世纪', 1, 9, 5, 'わたしは、あなたがたのいのちのためには、あなたがたの血の価を要求する。いかなる獣にも、それを要求する。また人にも、兄弟である者にも、人のいのちを要求する。'),
('JPN', '创世纪', 1, 9, 6, '人の血を流す者は、人によって血を流される。神は人を神のかたちとして造ったからである。'),
('JPN', '创世纪', 1, 9, 7, 'あなたがたは生めよ。増えよ。地に群がり、地に増えよ。」'),
('JPN', '创世纪', 1, 9, 8, '神は、ノアと、彼とともにいる息子たちに仰せられた。'),
('JPN', '创世纪', 1, 9, 9, '「見よ、わたしは、わたしの契約をあなたがたとの間に立てる。そして、あなたがたの後の子孫との間に。'),
('JPN', '创世纪', 1, 9, 10, 'また、あなたがたとともにいるすべての生き物との間に。鳥、家畜、それに、あなたがたとともにいるすべての地の獣、箱舟から出て来たすべてのものから、地のすべての生き物に至るまで。'),
('JPN', '创世纪', 1, 9, 11, 'わたしは、わたしの契約をあなたがたとの間に立てる。すべての肉なるものが、再び、大洪水の大水によって断ち切られることはない。大洪水が再び起こって地を滅ぼすようなことはない。」'),
('JPN', '创世纪', 1, 9, 12, 'さらに神は仰せられた。「わたしとあなたがたとの間に、また、あなたがたとともにいるすべての生き物との間に、代々にわたり永遠にわたしが与えるその契約のしるしは、これである。'),
('JPN', '创世纪', 1, 9, 13, 'わたしは雲の中に、わたしの虹を立てる。それが、わたしと地との間の契約のしるしである。'),
('JPN', '创世纪', 1, 9, 14, 'わたしが地の上に雲を起こすとき、虹が雲の中に現れる。'),
('JPN', '创世纪', 1, 9, 15, 'そのとき、わたしは、わたしとあなたがたとの間、すべての肉なる生き物との間の、わたしの契約を思い起こす。大水は、再び、すべての肉なるものを滅ぼす大洪水となることはない。'),
('JPN', '创世纪', 1, 9, 16, '虹が雲の中にあるとき、わたしはそれを見て、神と、すべての生き物、地上のすべての肉なるものとの間の永遠の契約を思い起こそう。」'),
('JPN', '创世纪', 1, 9, 17, '神はノアに仰せられた。「これが、わたしと、地上のすべての肉なるものとの間に、わたしが立てた契約のしるしである。」'),
('JPN', '创世纪', 1, 9, 18, '箱舟から出て来たノアの息子たちは、セム、ハム、ヤフェテであった。ハムはカナンの父である。'),
('JPN', '创世纪', 1, 9, 19, 'この三人がノアの息子たちで、彼らから全世界の民が分かれ出た。'),
('JPN', '创世纪', 1, 9, 20, 'さて、ノアは農夫となり、ぶどう畑を作り始めた。'),
('JPN', '创世纪', 1, 9, 21, '彼はぶどう酒を飲んで酔い、自分の天幕の中で裸になった。'),
('JPN', '创世纪', 1, 9, 22, 'カナンの父ハムは、父の裸を見て、外にいた二人の兄弟に告げた。'),
('JPN', '创世纪', 1, 9, 23, 'それで、セムとヤフェテは上着を取って、自分たち二人の肩に掛け、うしろ向きに歩いて行って、父の裸をおおった。彼らは顔を背け、父の裸は見なかった。'),
('JPN', '创世纪', 1, 9, 24, 'ノアは酔いからさめ、末の息子が自分にしたことを知った。'),
('JPN', '创世纪', 1, 9, 25, '彼は言った。「カナンはのろわれよ。兄たちの、しもべのしもべとなるように。」'),
('JPN', '创世纪', 1, 9, 26, 'また言った。「ほむべきかな、セムの神、主。カナンは彼らのしもべとなるように。'),
('JPN', '创世纪', 1, 9, 27, '神がヤフェテを広げ、彼がセムの天幕に住むようになれ。カナンは彼らのしもべとなるように。」'),
('JPN', '创世纪', 1, 9, 28, 'ノアは大洪水の後、三百五十年生きた。'),
('JPN', '创世纪', 1, 9, 29, 'ノアの全生涯は九百五十年であった。こうして彼は死んだ。'),
('JPN', '创世纪', 1, 10, 1, 'これはノアの息子、セム、ハム、ヤフェテの歴史である。大洪水の後、彼らに息子たちが生まれた。'),
('JPN', '创世纪', 1, 10, 2, 'ヤフェテの子らはゴメル、マゴグ、マダイ、ヤワン、トバル、メシェク、ティラス。'),
('JPN', '创世纪', 1, 10, 3, 'ゴメルの子らはアシュケナズ、リファテ、トガルマ。'),
('JPN', '创世纪', 1, 10, 4, 'ヤワンの子らはエリシャ、タルシシュ、キティム、ドダニム。'),
('JPN', '创世纪', 1, 10, 5, 'これらから島々の国民が分かれ出た。それぞれの地に、言語ごとに、その氏族にしたがって、国民となった。'),
('JPN', '创世纪', 1, 10, 6, 'ハムの子らはクシュ、ミツライム、プテ、カナン。'),
('JPN', '创世纪', 1, 10, 7, 'クシュの子らはセバ、ハビラ、サブタ、ラアマ、サブテカ。ラアマの子らはシェバ、デダン。'),
('JPN', '创世纪', 1, 10, 8, 'クシュはニムロデを生んだ。ニムロデは地上で最初の勇士となった。'),
('JPN', '创世纪', 1, 10, 9, '彼は主の前に力ある狩人であった。それゆえ、「主の前に力ある狩人ニムロデのように」と言われるようになった。'),
('JPN', '创世纪', 1, 10, 10, '彼の王国の始まりは、バベル、ウルク、アッカド、カルネで、シンアルの地にあった。'),
('JPN', '创世纪', 1, 10, 11, 'その地から彼はアッシュルに進出し、ニネベ、レホボテ・イル、カルフ、'),
('JPN', '创世纪', 1, 10, 12, 'およびニネベとカルフの間のレセンを建てた。それは大きな町であった。'),
('JPN', '创世纪', 1, 10, 13, 'ミツライムが生んだのは、ルディ人、アナミム人、レハビム人、ナフトヒム人、'),
('JPN', '创世纪', 1, 10, 14, 'パテロス人、カスルヒム人、カフトル人。このカスルヒム人からペリシテ人が出た。'),
('JPN', '创世纪', 1, 10, 15, 'カナンが生んだのは、長子シドン、ヒッタイト、'),
('JPN', '创世纪', 1, 10, 16, 'エブス人、アモリ人、ギルガシ人、'),
('JPN', '创世纪', 1, 10, 17, 'ヒビ人、アルキ人、シニ人、'),
('JPN', '创世纪', 1, 10, 18, 'アルワデ人、ツェマリ人、ハマテ人。その後、カナン人の諸氏族が分かれ出た。'),
('JPN', '创世纪', 1, 10, 19, 'それでカナン人の領土は、シドンからゲラルに向かって、ガザに至り、ソドム、ゴモラ、アデマ、ツェボイムに向かって、ラシャにまで及んだ。'),
('JPN', '创世纪', 1, 10, 20, '以上が、その氏族、その言語、その地、国民ごとの、ハムの子孫である。'),
('JPN', '创世纪', 1, 10, 21, 'セムにも子が生まれた。セムはエベルのすべての子孫の先祖であり、ヤフェテの兄であった。'),
('JPN', '创世纪', 1, 10, 22, 'セムの子らはエラム、アッシュル、アルパクシャデ、ルデ、アラム。'),
('JPN', '创世纪', 1, 10, 23, 'アラムの子らはウツ、フル、ゲテル、マシュ。'),
('JPN', '创世纪', 1, 10, 24, 'アルパクシャデはシェラフを生み、シェラフはエベルを生んだ。'),
('JPN', '创世纪', 1, 10, 25, 'エベルには二人の息子が生まれ、一人の名はペレグであった。その時代に地が分けられたからである。彼の兄弟の名はヨクタンであった。'),
('JPN', '创世纪', 1, 10, 26, 'ヨクタンが生んだのは、アルモダデ、シェレフ、ハツァルマベテ、エラフ、'),
('JPN', '创世纪', 1, 10, 27, 'ハドラム、ウザル、ディクラ、'),
('JPN', '创世纪', 1, 10, 28, 'オバル、アビマエル、シェバ、'),
('JPN', '创世纪', 1, 10, 29, 'オフィル、ハビラ、ヨバブ。これらはみな、ヨクタンの子であった。'),
('JPN', '创世纪', 1, 10, 30, '彼らが住んだ地は、メシャからセファルに及ぶ東の高原地帯であった。'),
('JPN', '创世纪', 1, 10, 31, '以上が、その氏族、その言語、その地、国民ごとの、セムの子孫である。'),
('JPN', '创世纪', 1, 10, 32, '以上が、それぞれの家系による、国民ごとの、ノアの子孫の諸氏族である。大洪水の後、彼らからもろもろの国民が地上に分かれ出たのである。'),
('JPN', '创世纪', 1, 11, 1, 'さて、全地は一つの話しことば、一つの共通のことばであった。'),
('JPN', '创世纪', 1, 11, 2, '人々が東の方へ移動したとき、彼らはシンアルの地に平地を見つけて、そこに住んだ。'),
('JPN', '创世纪', 1, 11, 3, '彼らは互いに言った。「さあ、れんがを作って、よく焼こう。」彼らは石の代わりにれんがを、漆喰の代わりに瀝青を用いた。'),
('JPN', '创世纪', 1, 11, 4, '彼らは言った。「さあ、われわれは自分たちのために、町と、頂が天に届く塔を建てて、名をあげよう。われわれが地の全面に散らされるといけないから。」'),
('JPN', '创世纪', 1, 11, 5, 'そのとき主は、人間が建てた町と塔を見るために降りて来られた。'),
('JPN', '创世纪', 1, 11, 6, '主は言われた。「見よ。彼らは一つの民で、みな同じ話しことばを持っている。このようなことをし始めたのなら、今や、彼らがしようと企てることで、不可能なことは何もない。'),
('JPN', '创世纪', 1, 11, 7, 'さあ、降りて行って、そこで彼らのことばを混乱させ、互いの話しことばが通じないようにしよう。」'),
('JPN', '创世纪', 1, 11, 8, '主が彼らをそこから地の全面に散らされたので、彼らはその町を建てるのをやめた。'),
('JPN', '创世纪', 1, 11, 9, 'それゆえ、その町の名はバベルと呼ばれた。そこで主が全地の話しことばを混乱させ、そこから主が人々を地の全面に散らされたからである。'),
('JPN', '创世纪', 1, 11, 10, 'これはセムの歴史である。セムは百歳のとき、アルパクシャデを生んだ。それは大洪水の二年後のことであった。'),
('JPN', '创世纪', 1, 11, 11, 'セムはアルパクシャデを生んでから五百年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 11, 12, 'アルパクシャデは三十五年生きて、シェラフを生んだ。'),
('JPN', '创世纪', 1, 11, 13, 'アルパクシャデはシェラフを生んでから四百三年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 11, 14, 'シェラフは三十年生きて、エベルを生んだ。'),
('JPN', '创世纪', 1, 11, 15, 'シェラフはエベルを生んでから四百三年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 11, 16, 'エベルは三十四年生きて、ペレグを生んだ。'),
('JPN', '创世纪', 1, 11, 17, 'エベルはペレグを生んでから四百三十年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 11, 18, 'ペレグは三十年生きて、レウを生んだ。'),
('JPN', '创世纪', 1, 11, 19, 'ペレグはレウを生んでから二百九年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 11, 20, 'レウは三十二年生きて、セルグを生んだ。'),
('JPN', '创世纪', 1, 11, 21, 'レウはセルグを生んでから二百七年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 11, 22, 'セルグは三十年生きて、ナホルを生んだ。'),
('JPN', '创世纪', 1, 11, 23, 'セルグはナホルを生んでから二百年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 11, 24, 'ナホルは二十九年生きて、テラを生んだ。'),
('JPN', '创世纪', 1, 11, 25, 'ナホルはテラを生んでから百十九年生き、息子たち、娘たちを生んだ。'),
('JPN', '创世纪', 1, 11, 26, 'テラは七十年生きて、アブラムとナホルとハランを生んだ。'),
('JPN', '创世纪', 1, 11, 27, 'これはテラの歴史である。テラはアブラム、ナホル、ハランを生み、ハランはロトを生んだ。'),
('JPN', '创世纪', 1, 11, 28, 'ハランは父テラに先立って、親族の地であるカルデア人のウルで死んだ。'),
('JPN', '创世纪', 1, 11, 29, 'アブラムとナホルは妻を迎えた。アブラムの妻の名はサライであった。ナホルの妻の名はミルカといって、ハランの娘であった。ハランはミルカの父、またイスカの父であった。'),
('JPN', '创世纪', 1, 11, 30, 'サライは不妊の女で、彼女には子がいなかった。'),
('JPN', '创世纪', 1, 11, 31, 'テラは、その息子アブラムと、ハランの子である孫のロトと、息子アブラムの妻である嫁のサライを伴い、カナンの地に行くために、一緒にカルデア人のウルを出発した。しかし、ハランまで来ると、彼らはそこに住んだ。'),
('JPN', '创世纪', 1, 11, 32, 'テラの生涯は二百五年であった。テラはハランで死んだ。'),
('JPN', '创世纪', 1, 12, 1, '主はアブラムに言われた。「あなたは、あなたの土地、あなたの親族、あなたの父の家を離れて、わたしが示す地へ行きなさい。'),
('JPN', '创世纪', 1, 12, 2, 'そうすれば、わたしはあなたを大いなる国民とし、あなたを祝福し、あなたの名を大いなるものとする。あなたは祝福となりなさい。'),
('JPN', '创世纪', 1, 12, 3, 'わたしは、あなたを祝福する者を祝福し、あなたを呪う者をのろう。地のすべての部族は、あなたによって祝福される。」'),
('JPN', '创世纪', 1, 12, 4, 'アブラムは、主が告げられたとおりに出て行った。ロトも彼と一緒であった。ハランを出たとき、アブラムは七十五歳であった。'),
('JPN', '创世纪', 1, 12, 5, 'アブラムは、妻のサライと甥のロト、また自分たちが蓄えたすべての財産と、ハランで得た人たちを伴って、カナンの地に向かって出発した。こうして彼らはカナンの地に入った。'),
('JPN', '创世纪', 1, 12, 6, 'アブラムはその地を通って、シェケムの場所、モレの樫の木のところまで行った。当時、その地にはカナン人がいた。'),
('JPN', '创世纪', 1, 12, 7, '主はアブラムに現れて言われた。「わたしは、あなたの子孫にこの地を与える。」アブラムは、自分に現れてくださった主のために、そこに祭壇を築いた。'),
('JPN', '创世纪', 1, 12, 8, '彼は、そこからベテルの東にある山の方に移動して、天幕を張った。西にはベテル、東にはアイがあった。彼は、そこに主のための祭壇を築き、主の御名を呼び求めた。'),
('JPN', '创世纪', 1, 12, 9, 'アブラムはなおも進んで、ネゲブの方へと旅を続けた。'),
('JPN', '创世纪', 1, 12, 10, 'その地に飢饉が起こったので、アブラムは、エジプトにしばらく滞在するために下って行った。その地の飢饉が激しかったからである。'),
('JPN', '创世纪', 1, 12, 11, '彼がエジプトに近づいて、その地に入って行こうとしたとき、妻のサライに言った。「聞いてほしい。私には、あなたが見目麗しい女だということがよく分かっている。'),
('JPN', '创世纪', 1, 12, 12, 'エジプト人があなたを見るようになると、『この女は彼の妻だ』と言って、私を殺し、あなたを生かしておくだろう。'),
('JPN', '创世纪', 1, 12, 13, '私の妹だと言ってほしい。そうすれば、あなたのゆえに事がうまく運び、あなたのおかげで私は生き延びられるだろう。」'),
('JPN', '创世纪', 1, 12, 14, 'アブラムがエジプトにやって来たとき、エジプト人はサライを見て、非常に美しいと思った。'),
('JPN', '创世纪', 1, 12, 15, 'ファラオの高官たちが彼女を見て、ファラオに彼女を薦めたので、サライはファラオの宮廷に召し入れられた。'),
('JPN', '创世纪', 1, 12, 16, 'アブラムにとって、物事は彼女のゆえにうまく運んだ。それで彼は、羊の群れ、牛の群れ、ろば、それに男奴隷と女奴隷、雌ろば、らくだを所有するようになった。'),
('JPN', '创世纪', 1, 12, 17, 'しかし、主はアブラムの妻サライのことで、ファラオとその宮廷を大きなわざわいで打たれた。'),
('JPN', '创世纪', 1, 12, 18, 'そこで、ファラオはアブラムを呼び寄せて言った。「あなたは私に何ということをしたのか。彼女があなたの妻であることを、なぜ私に告げなかったのか。'),
('JPN', '创世纪', 1, 12, 19, 'なぜ、『私の妹です』と言ったのか。だから、私は彼女を自分の妻として召し入れたのだ。さあ今、あなたの妻を連れて、立ち去るがよい。」'),
('JPN', '创世纪', 1, 12, 20, 'ファラオがアブラムについて家来に命じたので、彼らは彼を、妻と、所有するすべてのものと一緒に送り出した。'),
('JPN', '创世纪', 1, 13, 1, 'そこで、アブラムはエジプトを出て、ネゲブに上った。妻と、所有するすべてのものと、ロトも一緒であった。'),
('JPN', '创世纪', 1, 13, 2, 'アブラムは家畜と銀と金を非常に豊かに持っていた。'),
('JPN', '创世纪', 1, 13, 3, '彼はネゲブからベテルまで旅を続けて、ベテルとアイの間にある、最初に天幕を張った場所まで来た。'),
('JPN', '创世纪', 1, 13, 4, 'そこは、彼が以前に築いた祭壇の場所であった。アブラムはそこで主の御名を呼び求めた。'),
('JPN', '创世纪', 1, 13, 5, 'アブラムと一緒に来たロトも、羊の群れや牛の群れ、天幕を所有していた。'),
('JPN', '创世纪', 1, 13, 6, 'その地は、彼らが一緒に住むのに十分ではなかった。所有するものが多すぎて、一緒に住めなかったのである。'),
('JPN', '创世纪', 1, 13, 7, 'そのため、争いが、アブラムの家畜の牧者たちと、ロトの家畜の牧者たちの間に起こった。そのころ、その地にはカナン人とペリジ人が住んでいた。'),
('JPN', '创世纪', 1, 13, 8, 'アブラムはロトに言った。「私とあなたの間、また私の牧者たちとあなたの牧者たちの間に、争いがないようにしよう。私たちは親類同士なのだから。'),
('JPN', '创世纪', 1, 13, 9, '全地はあなたの前にあるではないか。私から別れて行ってくれないか。あなたが左なら、私は右に行こう。あなたが右なら、私は左に行こう。」'),
('JPN', '创世纪', 1, 13, 10, 'ロトが目を上げてヨルダンの低地全体を見渡すと、主がソドムとゴモラを滅ぼされる前であったので、その地はツォアルに至るまで、主の園のように、またエジプトの地のように、どこもよく潤っていた。'),
('JPN', '创世纪', 1, 13, 11, 'ロトは、自分のためにヨルダンの低地全体を選んだ。そしてロトは東へ移動した。こうして彼らは互いに別れた。'),
('JPN', '创世纪', 1, 13, 12, 'アブラムはカナンの地に住んだ。一方、ロトは低地の町々に住み、ソドムに天幕を移した。'),
('JPN', '创世纪', 1, 13, 13, 'ところが、ソドムの人々は邪悪で、主に対して甚だしく罪深い者たちであった。'),
('JPN', '创世纪', 1, 13, 14, 'ロトがアブラムから別れて行った後、主はアブラムに言われた。「さあ、目を上げて、あなたがいるその場所から北、南、東、西を見渡しなさい。'),
('JPN', '创世纪', 1, 13, 15, 'わたしは、あなたが見渡しているこの地をすべて、あなたに、そしてあなたの子孫に永久に与えるからだ。'),
('JPN', '创世纪', 1, 13, 16, 'わたしは、あなたの子孫を地のちりのように増やす。もし人が、地のちりを数えることができるなら、あなたの子孫も数えることができる。'),
('JPN', '创世纪', 1, 13, 17, '立って、この地を縦と横に歩き回りなさい。わたしがあなたに与えるのだから。」'),
('JPN', '创世纪', 1, 13, 18, 'そこで、アブラムは天幕を移して、ヘブロンにあるマムレの樫の木のそばに来て住んだ。そして、そこに主のための祭壇を築いた。'),
('JPN', '创世纪', 1, 14, 1, 'さて、シンアルの王アムラフェル、エラサルの王アルヨク、エラムの王ケドルラオメル、ゴイムの王ティデアルの時代のことである。'),
('JPN', '创世纪', 1, 14, 2, 'これらの王たちは、ソドムの王ベラ、ゴモラの王ビルシャ、アデマの王シンアブ、ツェボイムの王シェムエベル、ベラすなわちツォアルの王と戦った。'),
('JPN', '创世纪', 1, 14, 3, 'この五人の王たちは、シディムの谷、すなわち塩の海に結集した。'),
('JPN', '创世纪', 1, 14, 4, '彼らは十二年間ケドルラオメルに仕えていたが、十三年目に背いたのである。'),
('JPN', '创世纪', 1, 14, 5, 'そして十四年目に、ケドルラオメルと彼に味方する王たちがやって来て、アシュタロテ・カルナイムでレファイム人を、ハムでズジム人を、シャベ・キルヤタイムでエミム人を、'),
('JPN', '创世纪', 1, 14, 6, 'セイルの山地でフリ人を打ち破り、荒野の近くのエル・パランまで進んだ。'),
('JPN', '创世纪', 1, 14, 7, 'それから彼らは引き返して、エン・ミシュパテ、すなわちカデシュに至り、アマレク人の全土と、さらにハツェツォン・タマルに住んでいるアモリ人を打ち破った。'),
('JPN', '创世纪', 1, 14, 8, 'そこで、ソドムの王、ゴモラの王、アデマの王、ツェボイムの王、ベラすなわちツォアルの王は出て来て、シディムの谷で戦う備えをし、'),
('JPN', '创世纪', 1, 14, 9, 'エラムの王ケドルラオメル、ゴイムの王ティデアル、シンアルの王アムラフェル、エラサルの王アルヨクと対峙した。この四人の王と、先の五人の王とであった。'),
('JPN', '创世纪', 1, 14, 10, 'シディムの谷には瀝青の穴が多くあり、ソドムの王とゴモラの王は逃げたとき、その穴に落ちた。そして、残りの王たちは山の方に逃げた。'),
('JPN', '创世纪', 1, 14, 11, '四人の王たちは、ソドムとゴモラのすべての財産とすべての食糧を奪って行った。'),
('JPN', '创世纪', 1, 14, 12, 'また彼らは、アブラムの甥のロトとその財産も奪って行った。ロトはソドムに住んでいた。'),
('JPN', '创世纪', 1, 14, 13, '一人の逃亡者が、ヘブル人アブラムのところに来て、そのことを告げた。アブラムは、アモリ人マムレの樫の木のところに住んでいた。マムレはエシュコルとアネルの兄弟で、彼らはアブラムと盟約を結んでいた。'),
('JPN', '创世纪', 1, 14, 14, 'アブラムは、自分の親類の者が捕虜になったことを聞き、彼の家で生まれて訓練された者三百十八人を引き連れて、ダンまで追跡した。'),
('JPN', '创世纪', 1, 14, 15, '夜、アブラムとそのしもべたちは分かれて彼らを攻め、彼らを打ち破り、ダマスコの北にあるホバまで追跡した。'),
('JPN', '创世纪', 1, 14, 16, 'そして、アブラムはすべての財産を取り戻し、親類のロトとその財産、それに女たちやほかの人々も取り戻した。'),
('JPN', '创世纪', 1, 14, 17, 'アブラムが、ケドルラオメルと彼に味方する王たちを打ち破って戻って来たとき、ソドムの王は、シャベの谷すなわち王の谷まで、彼を迎えに出て来た。'),
('JPN', '创世纪', 1, 14, 18, 'また、サレムの王メルキゼデクは、パンとぶどう酒を持って来た。彼はいと高き神の祭司であった。'),
('JPN', '创世纪', 1, 14, 19, '彼はアブラムを祝福して言った。「アブラムに祝福あれ。いと高き神、天と地を造られた方より。'),
('JPN', '创世纪', 1, 14, 20, 'いと高き神に誉れあれ。あなたの敵をあなたの手に渡された方に。」アブラムはすべての物の十分の一を彼に与えた。'),
('JPN', '创世纪', 1, 14, 21, 'ソドムの王はアブラムに言った。「人々は私に返し、財産はあなたが取ってください。」'),
('JPN', '创世纪', 1, 14, 22, 'アブラムはソドムの王に言った。「私は、いと高き神、天と地を造られた方、主に誓う。'),
('JPN', '创世纪', 1, 14, 23, '糸一本、履き物のひも一本さえ、私はあなたの所有物から何一つ取らない。それは、『アブラムを富ませたのは、この私だ』とあなたが言わないようにするためだ。'),
('JPN', '创世纪', 1, 14, 24, 'ただ、若い者たちが食べた物と、私と一緒に行動した人たちの取り分は別だ。アネルとエシュコルとマムレには、彼らの取り分を取らせるように。」'),
('JPN', '创世纪', 1, 15, 1, 'これらの出来事の後、主のことばが幻のうちにアブラムに臨んだ。「アブラムよ、恐れるな。わたしはあなたの盾である。あなたへの報いは非常に大きい。」'),
('JPN', '创世纪', 1, 15, 2, 'アブラムは言った。「神、主よ、あなたは私に何を下さるのですか。私は子がないままで死のうとしています。私の家の相続人は、ダマスコのエリエゼルなのでしょうか。」'),
('JPN', '创世纪', 1, 15, 3, 'さらに、アブラムは言った。「ご覧ください。あなたが子孫を私に下さらなかったので、私の家のしもべが私の跡取りになるでしょう。」'),
('JPN', '创世纪', 1, 15, 4, 'すると見よ、主のことばが彼に臨んだ。「その者があなたの跡を継いではならない。ただ、あなた自身から生まれ出てくる者が、あなたの跡を継がなければならない。」'),
('JPN', '创世纪', 1, 15, 5, 'そして主は、彼を外に連れ出して言われた。「さあ、天を見上げなさい。星を数えられるなら数えなさい。」さらに言われた。「あなたの子孫は、このようになる。」'),
('JPN', '创世纪', 1, 15, 6, 'アブラムは主を信じた。それで、それが彼の義と認められた。'),
('JPN', '创世纪', 1, 15, 7, '主は彼に言われた。「わたしは、この地をあなたの所有としてあなたに与えるために、カルデア人のウルからあなたを導き出した主である。」'),
('JPN', '创世纪', 1, 15, 8, 'アブラムは言った。「神、主よ。私がそれを所有することが、何によって分かるでしょうか。」'),
('JPN', '创世纪', 1, 15, 9, 'すると主は彼に言われた。「わたしのところに、三歳の雌牛と、三歳の雌やぎと、三歳の雄羊と、山鳩と、鳩のひなを持って来なさい。」'),
('JPN', '创世纪', 1, 15, 10, '彼はそれらすべてを持って来て、真っ二つに切り裂き、その半分を互いに向かい合わせにした。ただし、鳥は切り裂かなかった。'),
('JPN', '创世纪', 1, 15, 11, '猛禽がそれらの死体の上に降りて来た。アブラムはそれらを追い払った。'),
('JPN', '创世纪', 1, 15, 12, '日が沈みかけたころ、深い眠りがアブラムを襲った。そして、見よ、大いなる暗闇の恐怖が彼を襲った。'),
('JPN', '创世纪', 1, 15, 13, '主はアブラムに言われた。「あなたは、このことをよく知っておきなさい。あなたの子孫は、自分たちのものでない地で寄留者となり、四百年の間、奴隷となって苦しめられる。'),
('JPN', '创世纪', 1, 15, 14, 'しかし、彼らが奴隷として仕えるその国を、わたしはさばく。その後、彼らは多くの財産とともに、そこから出て来る。'),
('JPN', '创世纪', 1, 15, 15, 'あなた自身は、平安のうちに先祖のもとに行く。あなたは幸せな晩年を過ごして葬られる。'),
('JPN', '创世纪', 1, 15, 16, 'そして、四代目の者たちがここに帰って来る。それは、アモリ人の咎が、その時までに満ちることがないからである。」'),
('JPN', '创世纪', 1, 15, 17, '日が沈んで暗くなったとき、見よ、煙の立つかまどと、燃えているたいまつが、切り裂かれた物の間を通り過ぎた。'),
('JPN', '创世纪', 1, 15, 18, 'その日、主はアブラムと契約を結んで言われた。「あなたの子孫に、わたしはこの地を与える。エジプトの川から、あの大河ユーフラテス川まで。'),
('JPN', '创世纪', 1, 15, 19, 'ケニ人、ケナズ人、カデモニ人、'),
('JPN', '创世纪', 1, 15, 20, 'ヒッタイト人、ペリジ人、レファイム人、'),
('JPN', '创世纪', 1, 15, 21, 'アモリ人、カナン人、ギルガシ人、エブス人の地を。」'),
('JPN', '创世纪', 1, 16, 1, 'アブラムの妻サライは、アブラムに子を産んでいなかった。彼女にはエジプト人の女奴隷がいて、その名をハガルといった。'),
('JPN', '创世纪', 1, 16, 2, 'サライはアブラムに言った。「ご覧ください。主は私が子を産めないようにしておられます。どうぞ、私の女奴隷のところにお入りください。おそらく、彼女によって、私は子を得られるでしょう。」アブラムはサライの言うことを聞き入れた。'),
('JPN', '创世纪', 1, 16, 3, 'アブラムの妻サライは、アブラムがカナンの地に住んでから十年後に、彼女の女奴隷であるエジプト人ハガルを連れて来て、夫アブラムに妻として与えた。'),
('JPN', '创世纪', 1, 16, 4, '彼はハガルのところに入り、彼女は身ごもった。彼女は、自分が身ごもったのを知って、自分の女主人を軽く見るようになった。'),
('JPN', '创世纪', 1, 16, 5, 'サライはアブラムに言った。「私に対するこの横暴なふるまいは、あなたの上に降りかかればよいのです。この私が自分の女奴隷をあなたの懐に与えたのに、彼女は自分が身ごもったのを知って、私を軽く見るようになりました。主が、私とあなたの間をおさばきになりますように。」'),
('JPN', '创世纪', 1, 16, 6, 'アブラムはサライに言った。「見なさい。あなたの女奴隷は、あなたの手の中にある。あなたの好きなようにしなさい。」それで、サライが彼女を苦しめたので、彼女はサライのもとから逃げ去った。'),
('JPN', '创世纪', 1, 16, 7, '主の使いは、荒野にある泉のほとり、シュルへの道にある泉のほとりで、彼女を見つけた。'),
('JPN', '创世纪', 1, 16, 8, 'そして言った。「サライの女奴隷ハガル。あなたはどこから来て、どこへ行くのか。」すると彼女は言った。「私の女主人サライのもとから逃げているのです。」'),
('JPN', '创世纪', 1, 16, 9, '主の使いは彼女に言った。「あなたの女主人のもとに帰りなさい。そして、彼女のもとで身を低くしなさい。」'),
('JPN', '创世纪', 1, 16, 10, 'また、主の使いは彼女に言った。「わたしはあなたの子孫を増し加える。それは、数えきれないほど多くなる。」'),
('JPN', '创世纪', 1, 16, 11, 'さらに、主の使いは彼女に言った。「見よ。あなたは身ごもって男の子を産もうとしている。その子をイシュマエルと名づけなさい。主が、あなたの苦しみを聞き入れられたから。'),
('JPN', '创世纪', 1, 16, 12, '彼は、野生のろばのような人となり、その手は、すべての人に逆らい、すべての人の手も、彼に逆らう。彼は、すべての兄弟に敵対して住む。」'),
('JPN', '创世纪', 1, 16, 13, 'そこで、彼女は自分に語りかけた主の名を「あなたはエル・ロイ」と呼んだ。彼女は、「私を見てくださる方のうしろ姿を見て、なおも私がここにいるとは」と言ったのである。'),
('JPN', '创世纪', 1, 16, 14, 'それゆえ、その井戸はベエル・ラハイ・ロイと呼ばれた。それは、カデシュとベレデの間にある。'),
('JPN', '创世纪', 1, 16, 15, 'ハガルはアブラムに男の子を産んだ。アブラムは、ハガルが産んだその男の子をイシュマエルと名づけた。'),
('JPN', '创世纪', 1, 16, 16, 'ハガルがアブラムにイシュマエルを産んだとき、アブラムは八十六歳であった。'),
('JPN', '创世纪', 1, 17, 1, 'さて、アブラムが九十九歳のとき、主はアブラムに現れ、こう言われた。「わたしは全能の神である。あなたはわたしの前に歩み、全き者であれ。'),
('JPN', '创世纪', 1, 17, 2, 'わたしは、わたしの契約を、わたしとあなたとの間に立てる。わたしは、あなたを大いに増やす。」'),
('JPN', '创世纪', 1, 17, 3, 'アブラムはひれ伏した。神は彼にこう告げられた。'),
('JPN', '创世纪', 1, 17, 4, '「これが、あなたと結ぶわたしの契約である。あなたは多くの国民の父となる。'),
('JPN', '创世纪', 1, 17, 5, 'あなたの名は、もはや、アブラムとは呼ばれない。あなたの名はアブラハムとなる。わたしがあなたを多くの国民の父とするからである。'),
('JPN', '创世纪', 1, 17, 6, 'わたしは、あなたをますます子孫に富ませ、あなたをいくつもの国民とする。王たちが、あなたから出てくるだろう。'),
('JPN', '创世纪', 1, 17, 7, 'わたしは、わたしの契約を、わたしとあなたとの間に、またあなたの後の子孫との間に、代々にわたる永遠の契約として立てる。わたしは、あなたの神、あなたの後の子孫の神となる。'),
('JPN', '创世纪', 1, 17, 8, 'わたしは、あなたの寄留の地、カナンの全土を、あなたとあなたの後の子孫に永遠の所有として与える。わたしは彼らの神となる。」'),
('JPN', '创世纪', 1, 17, 9, 'また神はアブラハムに仰せられた。「あなたは、わたしの契約を守らなければならない。あなたも、あなたの後の子孫も、代々にわたって。'),
('JPN', '创世纪', 1, 17, 10, '次のことが、わたしとあなたがたとの間で、またあなたの後の子孫との間で、あなたがたが守るべきわたしの契約である。あなたがたの中の男子はみな、割礼を受けなさい。'),
('JPN', '创世纪', 1, 17, 11, 'あなたがたは自分の包皮の肉を切り捨てなさい。それが、わたしとあなたがたとの間の契約のしるしとなる。'),
('JPN', '创世纪', 1, 17, 12, 'あなたがたの中の男子はみな、代々にわたり、生まれて八日目に割礼を受けなければならない。家で生まれたしもべも、異国人から金で買い取られた、あなたの子孫ではない者もそうである。'),
('JPN', '创世纪', 1, 17, 13, 'あなたの家で生まれたしもべも、金で買い取った者も、必ず割礼を受けなければならない。わたしの契約は、永遠の契約として、あなたがたの肉に記されなければならない。'),
('JPN', '创世纪', 1, 17, 14, '包皮の肉を切り捨てられていない無割礼の男、そのような者は、自分の民から断ち切られなければならない。わたしの契約を破ったからである。」'),
('JPN', '创世纪', 1, 17, 15, 'また神はアブラハムに仰せられた。「あなたの妻サライは、その名をサライと呼んではならない。その名はサラとなるからだ。'),
('JPN', '创世纪', 1, 17, 16, 'わたしは彼女を祝福し、彼女によって必ずあなたに男の子を与える。わたしは彼女を祝福する。彼女は国々の母となり、もろもろの民の王たちが彼女から出てくる。」'),
('JPN', '创世纪', 1, 17, 17, 'アブラハムはひれ伏して、笑った。そして心の中で言った。「百歳の者に子が生まれるだろうか。サラにしても、九十歳の女が子を産めるだろうか。」'),
('JPN', '创世纪', 1, 17, 18, 'そして、アブラハムは神に言った。「どうか、イシュマエルが御前で生きますように。」'),
('JPN', '创世纪', 1, 17, 19, '神は仰せられた。「いや、あなたの妻サラが、あなたに男の子を産むのだ。あなたはその子をイサクと名づけなさい。わたしは彼と、わたしの契約を立て、それを彼の後の子孫のために永遠の契約とする。'),
('JPN', '创世纪', 1, 17, 20, 'イシュマエルについては、あなたの言うことを聞き入れた。必ず、わたしは彼を祝福し、子孫に富ませ、大いに増やす。彼は十二人の族長たちを生む。わたしは彼を大いなる国民とする。'),
('JPN', '创世纪', 1, 17, 21, 'しかし、わたしがわたしの契約を立てるのは、サラが来年の今ごろあなたに産むイサクとの間にである。」'),
('JPN', '创世纪', 1, 17, 22, '神はアブラハムと語り終えると、彼のもとから上って行かれた。'),
('JPN', '创世纪', 1, 17, 23, 'そこでアブラハムは、その子イシュマエル、彼の家で生まれたすべてのしもべ、また、金で買い取ったすべての者、すなわち、アブラハムの家のすべての男子を集め、神が彼に告げられたとおり、その日のうちに、彼らの包皮の肉を切り捨てた。'),
('JPN', '创世纪', 1, 17, 24, 'アブラハムが包皮の肉を切り捨てられたときは、九十九歳であった。'),
('JPN', '创世纪', 1, 17, 25, 'その子イシュマエルは、包皮の肉に割礼を受けたとき、十三歳であった。'),
('JPN', '创世纪', 1, 17, 26, 'アブラハムとその子イシュマエルは、その日のうちに割礼を受けた。'),
('JPN', '创世纪', 1, 17, 27, '彼の家の男たちはみな、家で生まれた奴隷も、異国人から金で買い取った者も、彼と一緒に割礼を受けた。'),
('JPN', '创世纪', 1, 18, 1, '主は、マムレの樫の木のところで、アブラハムに現れた。彼は、日の暑いころ、天幕の入り口に座っていた。'),
('JPN', '创世纪', 1, 18, 2, '彼が目を上げて見ると、なんと、三人の人が彼に向かって立っていた。アブラハムはそれを見るなり、彼らを迎えようと天幕の入り口から走って行き、地にひれ伏した。'),
('JPN', '创世纪', 1, 18, 3, '彼は言った。「主よ。もしもよろしければ、どうか、しもべのところを素通りなさらないでください。'),
('JPN', '创世纪', 1, 18, 4, '水を少しばかり持って来させますから、足を洗って、この木の下でお休みください。'),
('JPN', '创世纪', 1, 18, 5, '私は食べ物を少し持って参ります。それで元気をつけて、それから旅をお続けください。せっかく、しもべのところをお通りになるのですから。」彼らは答えた。「あなたの言うとおりにしてください。」'),
('JPN', '创世纪', 1, 18, 6, 'アブラハムは、天幕のサラのところに急いで行って、「早く、三セアの上等の小麦粉をこねて、パン菓子を作りなさい」と言った。'),
('JPN', '创世纪', 1, 18, 7, 'そして、アブラハムは牛のところに走って行き、柔らかくて、おいしそうな子牛を取り、若い者に渡した。若い者は手早くそれを料理した。'),
('JPN', '创世纪', 1, 18, 8, 'それからアブラハムは、凝乳と牛乳と、料理した子牛を持って来て、彼らの前に出したので、彼らは食べた。彼自身は木の下で給仕をしていた。'),
('JPN', '创世纪', 1, 18, 9, '彼らはアブラハムに言った。「あなたの妻サラはどこにいますか。」彼は答えた。「天幕の中におります。」'),
('JPN', '创世纪', 1, 18, 10, 'すると、そのうちの一人が言った。「わたしは来年の今ごろ、必ずあなたのところに戻って来ます。そのとき、あなたの妻サラには男の子が生まれています。」サラは、その人のうしろの、天幕の入り口で聞いていた。'),
('JPN', '创世纪', 1, 18, 11, 'アブラハムとサラは年を重ねて老人になっていて、サラには女の月のものがもう止まっていた。'),
('JPN', '创世纪', 1, 18, 12, 'サラは心の中で笑って、こう言った。「年老いてしまったこの私に、何の楽しみがあるでしょう。それに主人も年寄りで。」'),
('JPN', '创世纪', 1, 18, 13, '主はアブラハムに言われた。「なぜサラは笑って、『私は本当に子を産めるだろうか。こんなに年をとっているのに』と言うのか。'),
('JPN', '创世纪', 1, 18, 14, '主にとって不可能なことがあるだろうか。わたしは来年の今ごろ、定めた時に、あなたのところに戻って来る。そのとき、サラには男の子が生まれている。」'),
('JPN', '创世纪', 1, 18, 15, 'サラは打ち消して言った。「私は笑っていません。」恐ろしかったのである。しかし、主は言われた。「いや、確かにあなたは笑った。」'),
('JPN', '创世纪', 1, 18, 16, 'その人たちは、そこから立ち上がって、ソドムの方を見下ろした。アブラハムは彼らを見送りに、彼らと一緒に行った。'),
('JPN', '创世纪', 1, 18, 17, '主はこう考えられた。「わたしは、自分がしようとしていることを、アブラハムに隠しておくべきだろうか。'),
('JPN', '创世纪', 1, 18, 18, 'アブラハムは必ず、強く大いなる国民となり、地のすべての国民は彼によって祝福される。'),
('JPN', '创世纪', 1, 18, 19, 'わたしがアブラハムを選び出したのは、彼がその子どもたちと後の家族に命じて、彼らが主の道を守り、正義と公正を行うようになるためであり、それによって、主がアブラハムについて約束したことを彼の上に成就するためだ。」'),
('JPN', '创世纪', 1, 18, 20, '主は言われた。「ソドムとゴモラの叫びは非常に大きく、彼らの罪はきわめて重い。'),
('JPN', '创世纪', 1, 18, 21, 'わたしは下って行って、わたしに届いた叫びどおり、彼らが滅ぼし尽くされるべきかどうかを、見て確かめたい。」'),
('JPN', '创世纪', 1, 18, 22, 'その人たちは、そこからソドムの方へ進んで行った。アブラハムは、まだ主の前に立っていた。'),
('JPN', '创世纪', 1, 18, 23, 'アブラハムは近づいて言った。「あなたは本当に、正しい者を悪い者とともに滅ぼし尽くされるのですか。'),
('JPN', '创世纪', 1, 18, 24, 'もしかすると、その町の中に正しい者が五十人いるかもしれません。あなたは本当に彼らを滅ぼし尽くされるのですか。その中にいる五十人の正しい者のために、その町をお赦しにならないのですか。'),
('JPN', '创世纪', 1, 18, 25, '正しい者を悪い者とともに殺し、そのため正しい者と悪い者が同じようになる、というようなことを、あなたがなさることは絶対にありません。そんなことは絶対にあり得ないことです。全地をさばくお方は、公正を行うべきではありませんか。」'),
('JPN', '创世纪', 1, 18, 26, '主は言われた。「もしソドムで、わたしが正しい者を五十人、町の中に見つけたら、その人たちのゆえにその町のすべてを赦そう。」'),
('JPN', '创世纪', 1, 18, 27, 'アブラハムは答えた。「ご覧ください。私はちりや灰にすぎませんが、あえて、わが主に申し上げます。'),
('JPN', '创世纪', 1, 18, 28, 'もしかすると、五十人の正しい者に五人不足しているかもしれません。その五人のために、あなたは町のすべてを滅ぼされるのでしょうか。」主は言われた。「いや、滅ぼしはしない。もし、そこに四十五人を見つけたら。」'),
('JPN', '创世纪', 1, 18, 29, '彼は再び尋ねて言った。「もしかすると、そこに見つかるのは四十人かもしれません。」すると言われた。「そうはしない。その四十人のゆえに。」'),
('JPN', '创世纪', 1, 18, 30, 'また彼は言った。「わが主よ。どうかお怒りにならないで、私に言わせてください。もしかすると、そこに見つかるのは三十人かもしれません。」すると言われた。「そうはしない。もし、そこに三十人を見つけたら。」'),
('JPN', '创世纪', 1, 18, 31, '彼は言った。「あえて、わが主に申し上げます。もしかすると、そこに見つかるのは二十人かもしれません。」すると言われた。「滅ぼしはしない。その二十人のゆえに。」'),
('JPN', '创世纪', 1, 18, 32, 'また彼は言った。「わが主よ。どうかお怒りにならないで、もう一度だけ私に言わせてください。もしかすると、そこに見つかるのは十人かもしれません。」すると言われた。「滅ぼしはしない。その十人のゆえに。」'),
('JPN', '创世纪', 1, 18, 33, '主は、アブラハムと語り終えると、去って行かれた。アブラハムも自分の家へ帰って行った。'),
('JPN', '创世纪', 1, 19, 1, 'その二人の御使いは、夕暮れにソドムに着いた。ロトはソドムの門のところに座っていた。ロトは彼らを見ると、立ち上がって彼らを迎え、顔を地に付けて伏し拝んだ。'),
('JPN', '创世纪', 1, 19, 2, 'そして言った。「ご主人がた。どうか、このしもべの家に立ち寄り、足を洗って、お泊まりください。そして、朝早く旅を続けてください。」すると彼らは言った。「いや、私たちは広場に泊まろう。」'),
('JPN', '创世纪', 1, 19, 3, 'しかし、ロトがしきりに勧めたので、彼らは彼のところに立ち寄り、家の中に入った。ロトは種なしパンを焼き、彼らのためにごちそうを作った。こうして彼らは食事をした。'),
('JPN', '创世纪', 1, 19, 4, '彼らが床につかないうちに、その町の男たち、ソドムの男たちが若い者から年寄りまで、その家を取り囲んだ。すべての人が町の隅々からやって来た。'),
('JPN', '创世纪', 1, 19, 5, 'そして、ロトに向かって叫んだ。「今夜おまえのところにやって来た、あの男たちはどこにいるのか。ここに連れ出せ。彼らをよく知りたいのだ。」'),
('JPN', '创世纪', 1, 19, 6, 'ロトは戸口にいる彼らのところへ出て行き、自分の背後の戸を閉めた。'),
('JPN', '创世纪', 1, 19, 7, 'そして言った。「兄弟たちよ、どうか悪いことはしないでください。'),
('JPN', '创世纪', 1, 19, 8, 'お願いですから。私には、まだ男を知らない娘が二人います。娘たちをあなたがたのところに連れて来ますから、好きなようにしてください。けれども、あの人たちには何もしないでください。あの人たちは、私の屋根の下に身を寄せたのですから。」'),
('JPN', '创世纪', 1, 19, 9, 'しかし、彼らは言った。「引っ込んでいろ。」そして言った。「こいつはよそ者のくせに、さばきをするのか。さあ、おまえを、あいつらよりもひどい目にあわせてやろう。」彼らはロトのからだに激しく迫り、戸を破ろうと近づいた。'),
('JPN', '创世纪', 1, 19, 10, 'すると、あの人たちが手を伸ばして、ロトを自分たちのいる家の中に引き入れて、戸を閉めた。'),
('JPN', '创世纪', 1, 19, 11, '家の戸口にいた者たちは、小さい者から大きい者まで目つぶしをくらったので、彼らは戸口を見つけようとする力も萎えた。'),
('JPN', '创世纪', 1, 19, 12, 'その人たちはロトに言った。「ほかにだれか、ここに身内の者がいますか。あなたの婿や、あなたの息子、娘、またこの町にいる身内の者をみな、この場所から連れ出しなさい。'),
('JPN', '创世纪', 1, 19, 13, '私たちは、この場所を滅ぼそうとしています。彼らの叫びが主の前に大きいので、主はこの町を滅ぼそうと、私たちを遣わされたのです。」'),
('JPN', '创世纪', 1, 19, 14, 'そこで、ロトは出て行き、娘たちを妻にしていた婿たちに告げた。「立って、この場所から出て行きなさい。主がこの町を滅ぼそうとしておられるから。」しかし、彼の婿たちには、それは悪い冗談のように思われた。'),
('JPN', '创世纪', 1, 19, 15, '夜が明けるころ、御使いたちはロトをせき立てて言った。「さあ立って、あなたの妻と、ここにいる二人の娘を連れて行きなさい。そうでないと、あなたはこの町の咎のために滅ぼし尽くされてしまいます。」'),
('JPN', '创世纪', 1, 19, 16, '彼はためらっていた。するとその人たちは、彼の手と彼の妻の手と、二人の娘の手をつかんだ。これは、彼に対する主のあわれみによることである。その人たちは彼を連れ出し、町の外で一息つかせた。'),
('JPN', '创世纪', 1, 19, 17, '彼らを外に連れ出したとき、その一人が言った。「いのちがけで逃げなさい。うしろを振り返ってはいけない。この低地のどこにも立ち止まってはならない。山に逃げなさい。そうでないと滅ぼされてしまうから。」'),
('JPN', '创世纪', 1, 19, 18, 'ロトは彼らに言った。「主よ、どうか、そんなことになりませんように。'),
('JPN', '创世纪', 1, 19, 19, 'ご覧ください。このしもべはあなたのご好意を受けました。そしてあなたは私に大きな恵みを施してくださり、私のいのちを生かしてくださいました。しかし、私は山にまで逃げることはできません。おそらく、わざわいが追いついて、私は死ぬでしょう。'),
('JPN', '创世纪', 1, 19, 20, 'ご覧ください。あそこの町は逃れるのに近く、しかもあんなに小さい町です。どうか、あそこに逃げさせてください。あんなに小さいではありませんか。私のいのちを生かしてください。」'),
('JPN', '创世纪', 1, 19, 21, 'その人は彼に言った。「よろしい。わたしはこのことでも、あなたの願いを受け入れ、あなたの言うあの町を滅ぼさない。'),
('JPN', '创世纪', 1, 19, 22, '急いであそこへ逃れなさい。あなたがあそこに着くまでは、わたしは何もできないから。」それゆえ、その町の名はツォアルと呼ばれた。'),
('JPN', '创世纪', 1, 19, 23, '太陽が地の上に昇り、ロトはツォアルに着いた。'),
('JPN', '创世纪', 1, 19, 24, 'そのとき、主は硫黄と火を、天から、主のもとからソドムとゴモラの上に降らせられた。'),
('JPN', '创世纪', 1, 19, 25, 'こうして主は、これらの町々と低地全体と、その町々の全住民と、その地の植物を滅ぼされた。'),
('JPN', '创世纪', 1, 19, 26, 'ロトのうしろにいた彼の妻は、振り返ったので、塩の柱になってしまった。'),
('JPN', '创世纪', 1, 19, 27, '翌朝早く、アブラハムは、かつて主の前に立ったあの場所に行った。'),
('JPN', '创世纪', 1, 19, 28, '彼は、ソドムとゴモラの方、それに低地の全地方を見下ろした。彼が見ると、なんと、まるでかまどの煙のように、その地から煙が立ち上っていた。'),
('JPN', '创世纪', 1, 19, 29, '神が低地の町々を滅ぼしたとき、神はアブラハムを覚えておられた。それで、ロトが住んでいた町々を滅ぼしたとき、神はロトをその滅びの中から逃れるようにされた。'),
('JPN', '创世纪', 1, 19, 30, 'ロトはツォアルから上って、二人の娘と一緒に、山の上に住んだ。ツォアルに住むのを恐れたからである。彼と二人の娘は洞穴の中に住んだ。'),
('JPN', '创世纪', 1, 19, 31, '姉は妹に言った。「父は年をとっています。この地には、私たちのところに、世のしきたりにしたがって来てくれる男の人などいません。'),
('JPN', '创世纪', 1, 19, 32, 'さあ、父にお酒を飲ませ、一緒に寝て、父によって子孫を残しましょう。」'),
('JPN', '创世纪', 1, 19, 33, 'その夜、娘たちは父親に酒を飲ませ、姉が入って行き、一緒に寝た。ロトは、彼女が寝たのも起きたのも知らなかった。'),
('JPN', '创世纪', 1, 19, 34, 'その翌日、姉は妹に言った。「ご覧なさい。私は昨夜、父と寝ました。今夜も父にお酒を飲ませましょう。そして、あなたが行って、一緒に寝なさい。そうして、私たちは父によって子孫を残しましょう。」'),
('JPN', '创世纪', 1, 19, 35, 'その夜も、娘たちは父親に酒を飲ませ、妹が行って、一緒に寝た。ロトは、彼女が寝たのも起きたのも知らなかった。'),
('JPN', '创世纪', 1, 19, 36, 'こうして、ロトの二人の娘は父親によって身ごもった。'),
('JPN', '创世纪', 1, 19, 37, '姉は男の子を産んで、その子をモアブと名づけた。彼は今日のモアブ人の先祖である。'),
('JPN', '创世纪', 1, 19, 38, '妹もまた、男の子を産んで、その子をベン・アミと名づけた。彼は今日のアンモン人の先祖である。'),
('JPN', '创世纪', 1, 20, 1, 'アブラハムは、そこからネゲブの地方へ移り、カデシュとシュルの間に住んだ。ゲラルに寄留していたとき、'),
('JPN', '创世纪', 1, 20, 2, 'アブラハムは、自分の妻サラのことを「これは私の妹です」と言ったので、ゲラルの王アビメレクは、人を遣わしてサラを召し入れた。'),
('JPN', '创世纪', 1, 20, 3, 'その夜、神が夢の中でアビメレクのところに来て、こう仰せられた。「見よ。あなたは、自分が召し入れた女のために死ぬことになる。あの女は夫のある身だ。」'),
('JPN', '创世纪', 1, 20, 4, 'アビメレクは、まだ彼女に近づいていなかった。そこで彼は言った。「主よ、あなたは正しい国民さえも殺されるのですか。'),
('JPN', '创世纪', 1, 20, 5, '彼が私に『これは私の妹です』と言ったのではありませんか。彼女自身も『これは私の兄です』と言いました。私は、全き心と汚れのない手で、このことをしたのです。」'),
('JPN', '创世纪', 1, 20, 6, '神は夢の中で彼に仰せられた。「そのとおりだ。あなたが全き心でこのことをしたのを、わたし自身もよく知っている。それでわたしも、あなたがわたしの前に罪ある者とならないようにした。だからわたしは、あなたが彼女に触れることを許さなかったのだ。'),
('JPN', '创世纪', 1, 20, 7, '今、あの人の妻をあの人に返しなさい。あの人は預言者で、あなたのために祈ってくれるだろう。そして、いのちを得なさい。しかし、返さなければ、あなたも、あなたに属するすべての者も、必ず死ぬことを承知していなさい。」'),
('JPN', '创世纪', 1, 20, 8, '翌朝早く、アビメレクは彼のしもべをみな呼び寄せ、これらのことをすべて語り聞かせたので、人々は非常に恐れた。'),
('JPN', '创世纪', 1, 20, 9, 'アビメレクはアブラハムを呼び寄せて言った。「あなたは何ということを私たちにしたのか。私がいったい、罪となるどんなことをあなたにしたというのか。あなたが、私と私の王国に大きな罪をもたらそうとするとは。あなたは、してはならないことを私にしたのだ。」'),
('JPN', '创世纪', 1, 20, 10, 'また、アビメレクはアブラハムに言った。「あなたはなぜ、こんなことをしたのか。」'),
('JPN', '创世纪', 1, 20, 11, 'アブラハムは答えた。「この地方には、神を恐れることが全くないので、人々が私の妻のゆえに私を殺すと思ったのです。'),
('JPN', '创世纪', 1, 20, 12, 'また、本当に、あれは私の妹、私の父の娘です。でも、私の母の娘ではありません。それが私の妻になったのです。'),
('JPN', '创世纪', 1, 20, 13, '神が私を父の家から、さすらいの旅に出されたとき、私は彼女に、『このようにして、あなたの真実の愛を私に尽くしてほしい。私たちが行くどこででも、私のことを、この人は私の兄です、と言ってほしい』と言ったのです。」'),
('JPN', '创世纪', 1, 20, 14, 'アビメレクは、羊の群れと牛の群れと、男女の奴隷たちを連れて来て、アブラハムに与え、またアブラハムの妻サラを彼に返した。'),
('JPN', '创世纪', 1, 20, 15, 'アビメレクは言った。「見なさい。私の領地があなたの前に広がっている。あなたの良いと思うところに住みなさい。」'),
('JPN', '创世纪', 1, 20, 16, 'サラに対しては、こう言った。「ここに、銀千枚をあなたの兄に与える。これはあなたにとって、また一緒にいるすべての人にとって、あなたを守るものとなるだろう。これであなたは、すべての人の前で正しいとされるだろう。」'),
('JPN', '创世纪', 1, 20, 17, 'そこで、アブラハムは神に祈った。神は、アビメレクとその妻、また女奴隷たちを癒やされたので、彼らは再び子を産むようになった。'),
('JPN', '创世纪', 1, 20, 18, '主が、アブラハムの妻サラのことで、アビメレクの家のすべての胎を堅く閉じておられたのである。'),
('JPN', '创世纪', 1, 21, 1, '主は約束したとおりに、サラを顧みられた。主は告げたとおりに、サラのために行われた。'),
('JPN', '创世纪', 1, 21, 2, 'サラは身ごもり、神がアブラハムに告げられたその時期に、年老いたアブラハムに男の子を産んだ。'),
('JPN', '创世纪', 1, 21, 3, 'アブラハムは、自分に生まれた子、サラが自分に産んだ子をイサクと名づけた。'),
('JPN', '创世纪', 1, 21, 4, 'そしてアブラハムは、神が命じられたとおり、生後八日になった自分の子イサクに割礼を施した。'),
('JPN', '创世纪', 1, 21, 5, 'アブラハムは、その子イサクが彼に生まれたとき、百歳であった。'),
('JPN', '创世纪', 1, 21, 6, 'サラは言った。「神は私に笑いを下さいました。これを聞く人もみな、私のことで笑うでしょう。」'),
('JPN', '创世纪', 1, 21, 7, 'また、彼女は言った。「だれがアブラハムに、『サラが子に乳を飲ませる』と告げたでしょう。ところが私は、主人が年老いてから子を産んだのです。」'),
('JPN', '创世纪', 1, 21, 8, 'その子は育って乳離れした。アブラハムはイサクの乳離れの日に、盛大な宴会を催した。'),
('JPN', '创世纪', 1, 21, 9, 'サラは、エジプトの女ハガルがアブラハムに産んだ子が、イサクをからかっているのを見た。'),
('JPN', '创世纪', 1, 21, 10, 'それで、アブラハムに言った。「この女奴隷とその子を追い出してください。この女奴隷の子は、私の子イサクとともに跡取りになるべきではないのですから。」'),
('JPN', '创世纪', 1, 21, 11, 'このことで、アブラハムは非常に苦しんだ。それが自分の子に関わることだったからである。'),
('JPN', '创世纪', 1, 21, 12, '神はアブラハムに仰せられた。「その少年とあなたの女奴隷のことで苦しんではならない。サラがあなたに言うことはみな、言うとおりに聞き入れなさい。というのは、イサクにあって、あなたの子孫が起こされるからだ。'),
('JPN', '创世纪', 1, 21, 13, 'しかし、あの女奴隷の子も、わたしは一つの国民とする。彼も、あなたの子孫なのだから。」'),
('JPN', '创世纪', 1, 21, 14, '翌朝早く、アブラハムは、パンと、水の皮袋を取ってハガルに与え、彼女の肩に担がせ、その子とともに彼女を送り出した。それで彼女は行って、ベエル・シェバの荒野をさまよった。'),
('JPN', '创世纪', 1, 21, 15, '皮袋の水が尽きると、彼女はその子を一本の灌木の下に放り出し、'),
('JPN', '创世纪', 1, 21, 16, '自分は、弓で届くぐらい離れた向こうに行って座った。「あの子が死ぬのを見たくない」と思ったからである。彼女は向こうに座り、声をあげて泣いた。'),
('JPN', '创世纪', 1, 21, 17, '神は少年の声を聞かれ、神の使いは天からハガルを呼んで言った。「ハガルよ、どうしたのか。恐れてはいけない。神が、あそこにいる少年の声を聞かれたからだ。'),
('JPN', '创世纪', 1, 21, 18, '立って、あの少年を起こし、あなたの腕でしっかり抱きなさい。わたしは、あの子を大いなる国民とする。」'),
('JPN', '创世纪', 1, 21, 19, '神がハガルの目を開かれたので、彼女は井戸を見つけた。それで、行って皮袋を水で満たし、少年に飲ませた。'),
('JPN', '创世纪', 1, 21, 20, '神が少年とともにおられたので、彼は成長し、荒野に住んで、弓を射る者となった。'),
('JPN', '创世纪', 1, 21, 21, '彼はパランの荒野に住んだ。彼の母は、エジプトの地から彼のために妻を迎えた。'),
('JPN', '创世纪', 1, 21, 22, 'そのころ、アビメレクとその軍の長ピコルがアブラハムに言った。「あなたが何をしても、神はあなたとともにおられます。'),
('JPN', '创世纪', 1, 21, 23, 'それで今、ここで神によって私に誓ってください。私と私の子孫を裏切らないと。そして、私があなたに示した誠意にふさわしく、私にも、またあなたが寄留しているこの土地に対しても、誠意を示してください。」'),
('JPN', '创世纪', 1, 21, 24, 'アブラハムは「私は誓います」と言った。'),
('JPN', '创世纪', 1, 21, 25, 'それから、アブラハムは、アビメレクのしもべたちが奪い取った井戸のことで、アビメレクに抗議した。'),
('JPN', '创世纪', 1, 21, 26, 'アビメレクは答えた。「だれがそのようなことをしたのか知りませんでした。それに、あなたも私に告げなかったし、私も今日まで聞いたことがありませんでした。」'),
('JPN', '创世纪', 1, 21, 27, 'そこでアブラハムは羊と牛を取って、アビメレクに与えた。こうして二人は契約を結んだ。'),
('JPN', '创世纪', 1, 21, 28, 'アブラハムは、羊の群れから、七匹の雌の子羊を別にしておいた。'),
('JPN', '创世纪', 1, 21, 29, 'アビメレクはアブラハムに言った。「今、あなたが別にしたこの七匹の雌の子羊は、何のためのものですか。」'),
('JPN', '创世纪', 1, 21, 30, 'アブラハムは言った。「私がこの井戸を掘ったという証拠になるように、七匹の雌の子羊を私の手から受け取ってください。」'),
('JPN', '创世纪', 1, 21, 31, 'それゆえ、その場所はベエル・シェバと呼ばれた。彼ら二人がそこで誓ったからである。'),
('JPN', '创世纪', 1, 21, 32, '彼らはベエル・シェバで契約を結んだ。アビメレクと、その軍の長ピコルは立って、ペリシテ人の地に帰って行った。'),
('JPN', '创世纪', 1, 21, 33, 'アブラハムはベエル・シェバに一本のタマリスクの木を植え、そこで永遠の神、主の御名を呼び求めた。'),
('JPN', '创世纪', 1, 21, 34, 'アブラハムは長い間、ペリシテ人の地に寄留した。'),
('JPN', '创世纪', 1, 22, 1, 'これらの出来事の後、神がアブラハムを試練にあわせられた。神が彼に「アブラハムよ」と呼びかけられると、彼は「はい、ここにおります」と答えた。'),
('JPN', '创世纪', 1, 22, 2, '神は仰せられた。「あなたの子、あなたが愛しているひとり子イサクを連れて、モリヤの地に行きなさい。そして、わたしがあなたに告げる一つの山の上で、彼を全焼のささげ物として献げなさい。」'),
('JPN', '创世纪', 1, 22, 3, '翌朝早く、アブラハムはろばに鞍をつけ、二人の若い者と一緒に息子イサクを連れて行った。アブラハムは全焼のささげ物のための薪を割った。こうして彼は、神がお告げになった場所へ向かって行った。'),
('JPN', '创世纪', 1, 22, 4, '三日目に、アブラハムが目を上げると、遠くの方にその場所が見えた。'),
('JPN', '创世纪', 1, 22, 5, 'それで、アブラハムは若い者たちに、「おまえたちは、ろばと一緒に、ここに残っていなさい。私と息子はあそこに行き、礼拝をして、おまえたちのところに戻って来る」と言った。'),
('JPN', '创世纪', 1, 22, 6, 'アブラハムは全焼のささげ物のための薪を取り、それを息子イサクに背負わせ、火と刃物を手に取った。二人は一緒に進んで行った。'),
('JPN', '创世纪', 1, 22, 7, 'イサクは父アブラハムに話しかけて言った。「お父さん。」彼は「何だ。わが子よ」と答えた。イサクは尋ねた。「火と薪はありますが、全焼のささげ物にする羊は、どこにいるのですか。」'),
('JPN', '创世纪', 1, 22, 8, 'アブラハムは答えた。「わが子よ、神ご自身が、全焼のささげ物の羊を備えてくださるのだ。」こうして二人は一緒に進んで行った。'),
('JPN', '创世纪', 1, 22, 9, '神がアブラハムにお告げになった場所に彼らが着いたとき、アブラハムは、そこに祭壇を築いて薪を並べた。そして息子イサクを縛り、彼を祭壇の上の薪の上に載せた。'),
('JPN', '创世纪', 1, 22, 10, 'アブラハムは手を伸ばして刃物を取り、息子を屠ろうとした。'),
('JPN', '创世纪', 1, 22, 11, 'そのとき、主の使いが天から彼に呼びかけられた。「アブラハム、アブラハム。」彼は答えた。「はい、ここにおります。」'),
('JPN', '创世纪', 1, 22, 12, '御使いは言われた。「その子に手を下してはならない。その子に何もしてはならない。今わたしは、あなたが神を恐れていることがよく分かった。あなたは、自分の子、自分のひとり子さえ惜しむことがなかった。」'),
('JPN', '创世纪', 1, 22, 13, 'アブラハムが目を上げて見ると、見よ、一匹の雄羊が角を藪に引っかけていた。アブラハムは行って、その雄羊を取り、それを自分の息子の代わりに、全焼のささげ物として献げた。'),
('JPN', '创世纪', 1, 22, 14, 'アブラハムは、その場所の名をアドナイ・イルエと呼んだ。今日も、「主の山には備えがある」と言われている。'),
('JPN', '创世纪', 1, 22, 15, '主の使いは再び天からアブラハムを呼んで、'),
('JPN', '创世纪', 1, 22, 16, 'こう言われた。「わたしは自分にかけて誓う──主のことば──。あなたがこれを行い、自分の子、自分のひとり子を惜しまなかったので、'),
('JPN', '创世纪', 1, 22, 17, '確かにわたしは、あなたを大いに祝福し、あなたの子孫を、空の星、海辺の砂のように大いに増やす。あなたの子孫は敵の門を勝ち取る。'),
('JPN', '创世纪', 1, 22, 18, 'あなたの子孫によって、地のすべての国々は祝福を受けるようになる。あなたが、わたしの声に聞き従ったからである。」'),
('JPN', '创世纪', 1, 22, 19, 'アブラハムは若い者たちのところに戻った。彼らは立って、一緒にベエル・シェバに行った。こうしてアブラハムはベエル・シェバに住んだ。'),
('JPN', '创世纪', 1, 22, 20, 'これらの出来事の後、アブラハムに次のことが伝えられた。「ミルカもまた、あなたの兄弟ナホルに子を産みました。'),
('JPN', '创世纪', 1, 22, 21, '長男ウツ、その弟ブズ、アラムの父ケムエル、'),
('JPN', '创世纪', 1, 22, 22, 'ケセデ、ハゾ、ピルダシュ、イデラフ、それにベトエルです。」'),
('JPN', '创世纪', 1, 22, 23, 'このベトエルはリベカを生んだ。ミルカはこれら八人を、アブラハムの兄弟ナホルに産んだのである。'),
('JPN', '创世纪', 1, 22, 24, 'レウマというナホルの側女もまた、テバフ、ガハム、タハシュ、マアカを産んだ。'),
('JPN', '创世纪', 1, 23, 1, 'サラの生涯、サラが生きた年数は百二十七年であった。'),
('JPN', '创世纪', 1, 23, 2, 'サラはカナンの地のキルヤテ・アルバ、すなわちヘブロンで死んだ。アブラハムは来て、サラのために悼み悲しみ、泣いた。'),
('JPN', '创世纪', 1, 23, 3, 'アブラハムは、その亡き人のそばから立ち上がり、ヒッタイト人たちに話した。'),
('JPN', '创世纪', 1, 23, 4, '「私は、あなたがたのところに在住している寄留者ですが、あなたがたのところで私有の墓地を私に譲っていただきたい。そうすれば、死んだ者を私のところから移して、葬ることができます。」'),
('JPN', '创世纪', 1, 23, 5, 'ヒッタイト人たちはアブラハムに答えた。'),
('JPN', '创世纪', 1, 23, 6, '「ご主人、私たちの言うことをお聞き入れください。あなたは、私たちの間にあって神のつかさです。私たちの最上の墓地に、亡くなった方を葬ってください。私たちの中にはだれ一人、亡くなった方を葬る墓地をあなたに差し出さない者はおりません。」'),
('JPN', '创世纪', 1, 23, 7, 'そこで、アブラハムは立って、その土地の人々、ヒッタイト人に礼をして、'),
('JPN', '创世纪', 1, 23, 8, '彼らに告げた。「死んだ者を私のところから移して葬ることが、あなたがたの心にかなうのであれば、私の言うことをお聞き入れくださり、ツォハルの子エフロンに頼んでいただきたいのです。'),
('JPN', '创世纪', 1, 23, 9, '彼の畑地の端にある、彼の所有のマクペラの洞穴を譲っていただけるようにです。十分な価の銀と引き換えに、あなたがたの間での私の所有の墓地として、譲っていただけるようにしてください。」'),
('JPN', '创世纪', 1, 23, 10, 'エフロンはヒッタイト人たちの間に座っていた。ヒッタイト人のエフロンは、その町の門に入るヒッタイト人たち全員が聞いているところで、アブラハムに答えた。'),
('JPN', '创世纪', 1, 23, 11, '「いいえ、ご主人。どうか、私の言うことをお聞き入れください。あの畑地をあなたに差し上げます。そこにある洞穴も差し上げます。私の民の者たちの前で、それをあなたに差し上げます。亡くなった方を葬ってください。」'),
('JPN', '创世纪', 1, 23, 12, 'アブラハムは、その土地の人々に礼をし、'),
('JPN', '创世纪', 1, 23, 13, 'その土地の人々の聞いているところで、エフロンに告げた。「もしあなたが許してくださるなら、私の言うことをお聞き入れください。畑地の価の銀をお支払いします。どうか私から受け取ってください。そうすれば、死んだ者をそこに葬ることができます。」'),
('JPN', '创世纪', 1, 23, 14, 'エフロンはアブラハムに答えた。'),
('JPN', '创世纪', 1, 23, 15, '「では、ご主人、私の言うことをお聞き入れください。銀四百シェケルの土地、それなら、私とあなたの間では、何ほどのこともないでしょう。どうぞ、亡くなった方を葬ってください。」'),
('JPN', '创世纪', 1, 23, 16, 'アブラハムはエフロンの申し出を聞き入れた。アブラハムはエフロンに、彼がヒッタイト人たちの聞いているところでつけた価の銀を支払った。それは商人の間で通用する銀四百シェケルであった。'),
('JPN', '创世纪', 1, 23, 17, 'こうして、マムレに面するマクペラにあるエフロンの畑地、すなわち、その畑と、畑地にある洞穴と、畑地の周りの境界線内にあるすべての木は、'),
('JPN', '创世纪', 1, 23, 18, 'その町の門に入るすべてのヒッタイト人たちの目の前で、アブラハムの所有となった。'),
('JPN', '创世纪', 1, 23, 19, 'その後アブラハムは、マムレに面するマクペラの畑地の洞穴に、妻サラを葬った。マムレはヘブロンにあり、カナンの地にある。'),
('JPN', '创世纪', 1, 23, 20, 'こうして、この畑地とその中にある洞穴は、ヒッタイト人たちの手から離れて、私有の墓地としてアブラハムの所有となった。'),
('JPN', '创世纪', 1, 24, 1, 'アブラハムは年を重ねて、老人になっていた。主は、あらゆる面でアブラハムを祝福しておられた。'),
('JPN', '创世纪', 1, 24, 2, 'アブラハムは、自分の全財産を管理している、家の最年長のしもべに、こう言った。「あなたの手を私のももの下に入れてくれ。'),
('JPN', '创世纪', 1, 24, 3, '私はあなたに、天の神、地の神である主にかけて誓わせる。私はカナン人の間に住んではいるが、あなたは、その娘たちの中から、私の息子の妻を迎えてはならない。'),
('JPN', '创世纪', 1, 24, 4, 'あなたは、私の国、私の親族のところに行って、私の息子イサクに妻を迎えなさい。」'),
('JPN', '创世纪', 1, 24, 5, 'しもべは彼に言った。「もしかしたら、その娘さんが、私についてこの地に来ようとしないかもしれません。その場合、ご子息をあなたの出身地へ連れて戻らなければなりませんか。」'),
('JPN', '创世纪', 1, 24, 6, 'アブラハムは彼に言った。「気をつけて、息子をそこへ連れて戻ることのないようにしなさい。'),
('JPN', '创世纪', 1, 24, 7, '天の神、主は、私の父の家、私の親族の地から私を連れ出し、私に約束して、『あなたの子孫にこの地を与える』と誓われた。その方が、あなたの前に御使いを遣わされるのだ。あなたは、そこから私の息子に妻を迎えなさい。'),
('JPN', '创世纪', 1, 24, 8, 'もし、その娘があなたについて来ようとしないなら、あなたはこの、私との誓いから解かれる。ただ、私の息子をそこに連れて戻ることだけはしてはならない。」'),
('JPN', '创世纪', 1, 24, 9, 'それでしもべは、主人であるアブラハムのももの下に自分の手を入れ、このことについて彼に誓った。'),
('JPN', '创世纪', 1, 24, 10, 'しもべは主人のらくだの中から十頭を連れて出かけた。主人のあらゆる良い品々をその手に携えていた。彼は立って、アラム・ナハライムのナホルの町へ行った。'),
('JPN', '创世纪', 1, 24, 11, '彼は夕暮れ時、水を汲む女たちが出て来るころ、町の外の井戸のそばにらくだを伏させた。'),
('JPN', '创世纪', 1, 24, 12, 'そうして言った。「私の主人アブラハムの神、主よ。どうか今日、私のために取り計らい、私の主人アブラハムに恵みを施してください。'),
('JPN', '创世纪', 1, 24, 13, 'ご覧ください。私は泉のそばに立っています。この町の人々の娘たちが、水を汲みに出て来るでしょう。'),
('JPN', '创世纪', 1, 24, 14, '私が娘に、『どうか、あなたの水がめを傾けて、私に飲ませてください』と言い、その娘が、『お飲みください。あなたのらくだにも水を飲ませましょう』と言ったなら、その娘こそ、あなたが、あなたのしもべイサクのために定めておられた人です。このことで、あなたが私の主人に恵みを施されたことを、私が知ることができますように。」'),
('JPN', '创世纪', 1, 24, 15, 'しもべがまだ言い終わらないうちに、見よ、リベカが水がめを肩に載せて出て来た。リベカはミルカの子ベトエルの娘で、ミルカはアブラハムの兄弟ナホルの妻であった。'),
('JPN', '创世纪', 1, 24, 16, 'この娘は非常に美しく、処女で、男が触れたことがなかった。彼女は泉に下りて行き、水がめを満たして上がって来た。'),
('JPN', '创世纪', 1, 24, 17, 'しもべは彼女の方に走って行って、言った。「どうか、あなたの水がめから、水を少し飲ませてください。」'),
('JPN', '创世纪', 1, 24, 18, 'すると彼女は、「どうぞ、お飲みください。ご主人様」と言って、すばやくその手に水がめを取り降ろし、彼に飲ませた。'),
('JPN', '创世纪', 1, 24, 19, '水を飲ませ終わると、彼女は、「あなたのらくだにも、飲み終わるまで、水を汲みましょう」と言った。'),
('JPN', '创世纪', 1, 24, 20, '彼女は急いで水がめの水を水ぶねにあけ、水を汲みに、再び井戸まで走って行き、すべてのらくだのために水を汲んだ。'),
('JPN', '创世纪', 1, 24, 21, 'この人は、主が自分の旅を成功させてくださったかどうかを知ろうと、黙って彼女を見つめていた。'),
('JPN', '创世纪', 1, 24, 22, 'らくだが水を飲み終わったとき、その人は、重さ一ベカの金の飾り輪と、彼女の腕のために、重さ十シェケルの二つの金の腕輪を取り、'),
('JPN', '创世纪', 1, 24, 23, '尋ねた。「あなたは、どなたの娘さんですか。どうか私に言ってください。あなたの父上の家には、私どもが泊めていただける場所があるでしょうか。」'),
('JPN', '创世纪', 1, 24, 24, '彼女は答えた。「私は、ミルカがナホルに産んだ子ベトエルの娘です。」'),
('JPN', '创世纪', 1, 24, 25, 'また言った。「藁も飼料も、私たちのところには、たくさんあります。それに、お泊まりになる場所も。」'),
('JPN', '创世纪', 1, 24, 26, 'その人は、ひざまずき、主を礼拝して、'),
('JPN', '创世纪', 1, 24, 27, 'こう言った。「私の主人アブラハムの神、主がほめたたえられますように。主は、私の主人に対する恵みとまことをお捨てになりませんでした。主は道中、この私を導いてくださいました。主人の兄弟の家にまで。」'),
('JPN', '创世纪', 1, 24, 28, 'その娘は走って行って、母の家の者に、これらのことを告げた。'),
('JPN', '创世纪', 1, 24, 29, 'リベカには兄がいて、その名をラバンといった。ラバンは外へ出て、泉のそばにいるその人のもとへ走って行った。'),
('JPN', '创世纪', 1, 24, 30, '彼は、飾り輪と、妹の腕にある腕輪を見、また、「あの人が私にこう言われました」と言った妹リベカのことばを聞くとすぐに、その人のところに行った。すると見よ、その人は泉のそば、らくだのそばに立っていた。'),
('JPN', '创世纪', 1, 24, 31, 'そこでラバンは言った。「どうぞ、おいでください。主に祝福された方。なぜ外に立っておられるのですか。私は、お宿と、らくだのための場所を用意しております。」'),
('JPN', '创世纪', 1, 24, 32, 'それで、その人は家の中に入った。らくだの荷が解かれ、らくだに藁と飼料が与えられ、彼の足と、一緒にいた従者たちの足を洗う水も与えられた。'),
('JPN', '创世纪', 1, 24, 33, 'それから、彼の前に食事が出されたが、彼は「私の用件を話すまでは、いただきません」と言った。「お話しください」と言われて、'),
('JPN', '创世纪', 1, 24, 34, '彼は言った。「私はアブラハムのしもべです。'),
('JPN', '创世纪', 1, 24, 35, '主は私の主人を大いに祝福されましたので、主人は富んでおります。主は主人に、羊や牛、銀や金、男女の奴隷、らくだやろばをお与えになりました。'),
('JPN', '创世纪', 1, 24, 36, '私の主人の妻サラは、年をとってから主人に男の子を産み、主人はこの子に自分の全財産を譲っておられます。'),
('JPN', '创世纪', 1, 24, 37, '私の主人は、こう言って、私に誓わせました。『私が住んでいるこの地のカナン人の娘たちの中から、私の息子の妻を迎えてはならない。'),
('JPN', '创世纪', 1, 24, 38, 'あなたは、私の父の家、私の親族のところへ行って、私の息子に妻を迎えなさい。』'),
('JPN', '创世纪', 1, 24, 39, 'そこで私は主人に申しました。『もしかしたら、その娘さんは私について来ないかもしれません。』'),
('JPN', '创世纪', 1, 24, 40, 'すると主人は答えました。『私は主の前に歩んできた。その主が御使いをあなたと一緒に遣わし、あなたの旅を成功させてくださる。あなたは、私の親族、私の父の家から、私の息子に妻を迎えなさい。'),
('JPN', '创世纪', 1, 24, 41, '次のようなときは、あなたは私との誓いから解かれる。あなたが私の親族のところに行ったときに、もし彼らがあなたに娘を与えないなら、そのとき、あなたは私との誓いから解かれる。』'),
('JPN', '创世纪', 1, 24, 42, '今日、私は泉のそばに来て言いました。『私の主人アブラハムの神、主よ。私がここまで来た旅を、もしあなたが成功させてくださるのなら──。'),
('JPN', '创世纪', 1, 24, 43, 'ご覧ください。私は泉のそばに立っています。若い娘が水を汲みに出て来たなら、私は「あなたの水がめから少し水を飲ませてください」と言います。'),
('JPN', '创世纪', 1, 24, 44, 'その人が私に、「どうぞ、お飲みください。あなたのらくだにも水を汲みましょう」と言ったなら、その娘さんこそ、主が私の主人の息子のために定められた方です。』'),
('JPN', '创世纪', 1, 24, 45, '私が心の中で言い終わらないうちに、なんと、リベカさんが水がめを肩に載せて出て来たのです。そして、泉に下りて行き、水を汲みました。それで私が『どうか水を飲ませてください』と言うと、'),
('JPN', '创世纪', 1, 24, 46, '急いで水がめを肩から降ろし、『お飲みください。あなたのらくだにも水を飲ませましょう』と言われたので、私は飲みました。らくだにも水を飲ませてくださいました。'),
('JPN', '创世纪', 1, 24, 47, '私が尋ねて、『あなたは、どなたの娘さんですか』と言いますと、『ミルカがナホルに産んだ子ベトエルの娘です』と答えました。そこで私は、彼女の鼻に飾り輪をつけ、彼女の腕に腕輪をはめました。'),
('JPN', '创世纪', 1, 24, 48, 'そして私はひざまずき、主を礼拝し、私の主人アブラハムの神、主をほめたたえました。主は、私の主人の親族の娘さんを主人の息子に迎えるために、私を確かな道に導いてくださったのです。'),
('JPN', '创世纪', 1, 24, 49, 'それで今、あなたがたが私の主人に恵みとまことを施してくださるのなら、私にそう言ってください。もしそうでなければ、そうでないと私に言ってください。それによって、私は右か左に向かうことになります。」'),
('JPN', '创世纪', 1, 24, 50, 'ラバンとベトエルは答えた。「主からこのことが出たのですから、私たちはあなたに良し悪しを言うことはできません。'),
('JPN', '创世纪', 1, 24, 51, 'ご覧ください。リベカはあなたの前におります。どうぞお連れください。主が言われたとおりに、あなたのご主人の息子さんの妻となりますように。」'),
('JPN', '创世纪', 1, 24, 52, 'アブラハムのしもべは、彼らのことばを聞くやいなや、地にひれ伏して主を礼拝した。'),
('JPN', '创世纪', 1, 24, 53, 'そして、このしもべは銀や金の品物や衣装を取り出して、リベカに与えた。また、彼女の兄や母にも貴重な品々を贈った。'),
('JPN', '创世纪', 1, 24, 54, 'このしもべと、ともにいた従者たちは、食べたり飲んだりして、そこに泊まった。朝になって彼らが起きると、そのしもべは「私の主人のところへ帰らせてください」と言った。'),
('JPN', '创世纪', 1, 24, 55, '彼女の兄と母は、「娘をしばらく、十日間ほど私たちのもとにとどまらせて、その後で行かせるようにしたいのですが」と言った。'),
('JPN', '创世纪', 1, 24, 56, 'しもべは彼らに、「私が遅れないようにしてください。主が私の旅を成功させてくださったのですから。主人のところへ行けるように、私を帰らせてください」と言った。'),
('JPN', '创世纪', 1, 24, 57, '彼らは答えた。「娘を呼び寄せて、娘の言うことを聞いてみましょう。」'),
('JPN', '创世纪', 1, 24, 58, '彼らはリベカを呼び寄せて、「この人と一緒に行くか」と尋ねた。すると彼女は「はい、行きます」と答えた。'),
('JPN', '创世纪', 1, 24, 59, 'そこで彼らは、妹リベカとその乳母を、アブラハムのしもべとその従者たちと一緒に送り出した。'),
('JPN', '创世纪', 1, 24, 60, '彼らはリベカを祝福して言った。「われらの妹よ、あなたは幾千万にも増えるように。あなたの子孫は敵の門を勝ち取るように。」'),
('JPN', '创世纪', 1, 24, 61, 'リベカとその侍女たちは立ち上がり、らくだに乗って、その人の後について行った。こうして、しもべはリベカを連れ帰った。'),
('JPN', '创世纪', 1, 24, 62, '一方イサクは、ベエル・ラハイ・ロイ地方から帰って来ていた。彼はネゲブの地に住んでいたのであった。'),
('JPN', '创世纪', 1, 24, 63, 'イサクは夕暮れ近く、野に散歩に出かけた。彼が目を上げて見ると、ちょうど、らくだが近づいて来ていた。'),
('JPN', '创世纪', 1, 24, 64, 'リベカも目を上げ、イサクを見ると、らくだから降り、'),
('JPN', '创世纪', 1, 24, 65, 'しもべに尋ねた。「野を歩いて私たちを迎えに来る、あの方はどなたですか。」しもべは答えた。「あの方が私の主人です。」そこで、リベカはベールを手に取って、身をおおった。'),
('JPN', '创世纪', 1, 24, 66, 'しもべは、自分がしてきたことを残らずイサクに話した。'),
('JPN', '创世纪', 1, 24, 67, 'イサクは、その母サラの天幕にリベカを連れて行き、リベカを迎えて妻とし、彼女を愛した。イサクは、母の亡き後、慰めを得た。'),
('JPN', '创世纪', 1, 25, 1, 'アブラハムは、再び妻を迎えた。その名はケトラといった。'),
('JPN', '创世纪', 1, 25, 2, '彼女はアブラハムに、ジムラン、ヨクシャン、メダン、ミディアン、イシュバク、シュアハを産んだ。'),
('JPN', '创世纪', 1, 25, 3, 'ヨクシャンはシェバとデダンを生んだ。デダンの子孫は、アッシュル人とレトシム人とレウミム人であった。'),
('JPN', '创世纪', 1, 25, 4, 'ミディアンの子は、エファ、エフェル、ハノク、アビダ、エルダアで、これらはみな、ケトラの子であった。'),
('JPN', '创世纪', 1, 25, 5, 'アブラハムは自分の全財産をイサクに与えた。'),
('JPN', '创世纪', 1, 25, 6, 'しかし、側女たちの子には贈り物を与え、自分が生きている間に、彼らを東の方、東方の国に行かせて、自分の子イサクから遠ざけた。'),
('JPN', '创世纪', 1, 25, 7, '以上がアブラハムの生きた年月で、百七十五年であった。'),
('JPN', '创世纪', 1, 25, 8, 'アブラハムは幸せな晩年を過ごし、年老いて満ち足り、息絶えて死んだ。そして自分の民に加えられた。'),
('JPN', '创世纪', 1, 25, 9, 'その息子、イサクとイシュマエルは、アブラハムを、マムレに面するマクペラの洞穴に葬った。これは、ヒッタイト人ツォハルの子エフロンの畑地にある。'),
('JPN', '创世纪', 1, 25, 10, 'アブラハムがヒッタイト人たちから買ったあの畑地である。アブラハムと彼の妻サラはそこに葬られた。'),
('JPN', '创世纪', 1, 25, 11, 'アブラハムの死後、神は彼の子イサクを祝福された。イサクはベエル・ラハイ・ロイの近くに住んだ。'),
('JPN', '创世纪', 1, 25, 12, 'これは、サラの女奴隷、エジプト人ハガルがアブラハムに産んだ、アブラハムの子イシュマエルの歴史である。'),
('JPN', '创世纪', 1, 25, 13, 'イシュマエルの子は、生まれた順に名を挙げると、イシュマエルの長子ネバヨテ、それからケダル、アデベエル、ミブサム、'),
('JPN', '创世纪', 1, 25, 14, 'ミシュマ、ドマ、マサ、'),
('JPN', '创世纪', 1, 25, 15, 'ハダド、テマ、エトル、ナフィシュ、ケデマである。'),
('JPN', '创世纪', 1, 25, 16, 'これがイシュマエルの子孫である。これらは、集落と宿営ごとにつけられた彼らの名で、十二人の、それぞれの氏族の長である。'),
('JPN', '创世纪', 1, 25, 17, '以上がイシュマエルの生涯で、その年数は百三十七年であった。彼は息絶えて死に、自分の民に加えられた。'),
('JPN', '创世纪', 1, 25, 18, 'イシュマエルの子孫は、ハビラからシュルまでの地域に住んだ。シュルはエジプトに接し、アッシュルへの道にあった。彼らは、すべての兄弟たちに敵対していた。'),
('JPN', '创世纪', 1, 25, 19, 'これはアブラハムの子イサクの歴史である。アブラハムはイサクを生んだ。'),
('JPN', '创世纪', 1, 25, 20, 'イサクが、パダン・アラムのアラム人ベトエルの娘で、アラム人ラバンの妹であるリベカを妻に迎えたときは、四十歳であった。'),
('JPN', '创世纪', 1, 25, 21, 'イサクは、自分の妻のために主に祈った。彼女が不妊の女だったからである。主は彼の祈りを聞き入れ、妻リベカは身ごもった。'),
('JPN', '创世纪', 1, 25, 22, '子どもたちが彼女の腹の中でぶつかり合うようになったので、彼女は「こんなことでは、いったいどうなるのでしょう、私は」と言った。そして、主のみこころを求めに出て行った。'),
('JPN', '创世纪', 1, 25, 23, 'すると主は彼女に言われた。「二つの国があなたの胎内にあり、二つの国民があなたから分かれ出る。一つの国民は、もう一つの国民より強く、兄が弟に仕える。」'),
('JPN', '创世纪', 1, 25, 24, '月日が満ちて出産の時になった。すると見よ、双子が胎内にいた。'),
('JPN', '创世纪', 1, 25, 25, '最初に出て来た子は、赤くて、全身毛衣のようであった。それで、彼らはその子をエサウと名づけた。'),
('JPN', '创世纪', 1, 25, 26, 'その後で弟が出て来たが、その手はエサウのかかとをつかんでいた。それで、その子はヤコブと名づけられた。イサクは、彼らを生んだとき、六十歳であった。'),
('JPN', '创世纪', 1, 25, 27, 'この子どもたちは成長した。エサウは巧みな狩人、野の人であったが、ヤコブは穏やかな人で、天幕に住んでいた。'),
('JPN', '创世纪', 1, 25, 28, 'イサクはエサウを愛していた。猟の獲物を好んでいたからである。しかし、リベカはヤコブを愛していた。'),
('JPN', '创世纪', 1, 25, 29, 'さて、ヤコブが煮物を煮ていると、エサウが野から帰って来た。彼は疲れきっていた。'),
('JPN', '创世纪', 1, 25, 30, 'エサウはヤコブに言った。「どうか、その赤いのを、そこの赤い物を食べさせてくれ。疲れきっているのだ。」それで、彼の名はエドムと呼ばれた。'),
('JPN', '创世纪', 1, 25, 31, 'するとヤコブは、「今すぐ私に、あなたの長子の権利を売ってください」と言った。'),
('JPN', '创世纪', 1, 25, 32, 'エサウは、「見てくれ。私は死にそうだ。長子の権利など、私にとって何になろう」と言った。'),
('JPN', '创世纪', 1, 25, 33, 'ヤコブが「今すぐ、私に誓ってください」と言ったので、エサウはヤコブに誓った。こうして彼は、自分の長子の権利をヤコブに売った。'),
('JPN', '创世纪', 1, 25, 34, 'ヤコブがエサウにパンとレンズ豆の煮物を与えたので、エサウは食べたり飲んだりして、立ち去った。こうしてエサウは長子の権利を侮った。'),
('JPN', '创世纪', 1, 26, 1, 'さて、アブラハムの時代にあった先の飢饉とは別に、この国にまた飢饉が起こった。それでイサクは、ゲラルのペリシテ人の王アビメレクのもとへ行った。'),
('JPN', '创世纪', 1, 26, 2, '主はイサクに現れて言われた。「エジプトへは下ってはならない。わたしがあなたに告げる地に住みなさい。'),
('JPN', '创世纪', 1, 26, 3, 'あなたはこの地に寄留しなさい。わたしはあなたとともにいて、あなたを祝福する。あなたとあなたの子孫に、わたしがこれらの国々をすべて与える。こうしてわたしは、あなたの父アブラハムに誓った誓いを果たす。'),
('JPN', '创世纪', 1, 26, 4, 'そしてわたしは、あなたの子孫を空の星のように増し加え、あなたの子孫に、これらの国々をみな与える。あなたの子孫によって、地のすべての国々は祝福を受けるようになる。'),
('JPN', '创世纪', 1, 26, 5, 'これは、アブラハムがわたしの声に聞き従い、わたしの命令と掟とおしえを守って、わたしへの務めを果たしたからである。」'),
('JPN', '创世纪', 1, 26, 6, 'こうしてイサクはゲラルに住んでいたが、'),
('JPN', '创世纪', 1, 26, 7, 'その土地の人々が彼の妻のことを尋ねた。すると彼は「あれは私の妹です」と答えた。この土地の人々がリベカのことで自分を殺しはしないかと思って、「私の妻です」と言うのを恐れたのであった。彼女が美しかったからである。'),
('JPN', '创世纪', 1, 26, 8, 'イサクは長くそこに滞在していた。ある日のこと、ペリシテ人の王アビメレクが窓から見下ろしていると、なんと、イサクがその妻リベカを愛撫しているのが見えた。'),
('JPN', '创世纪', 1, 26, 9, 'アビメレクは、イサクを呼び寄せて言った。「本当のところ、あの女はあなたの妻ではないか。なぜ、あなたは『あれは私の妹です』と言ったのか。」イサクは「彼女のことで殺されはしないかと思ったからです」と答えた。'),
('JPN', '创世纪', 1, 26, 10, 'アビメレクは言った。「何ということをしてくれたのか。もう少しで、民の一人があなたの妻と寝て、あなたはわれわれに罪責をもたらすところだった。」'),
('JPN', '创世纪', 1, 26, 11, 'そこでアビメレクは、すべての民に命じて言った。「この人と、この人の妻に触れる者は、必ず殺される。」'),
('JPN', '创世纪', 1, 26, 12, 'イサクはその地に種を蒔き、その年に百倍の収穫を見た。主は彼を祝福された。'),
('JPN', '创世纪', 1, 26, 13, 'こうして、この人は富み、ますます栄えて、非常に裕福になった。'),
('JPN', '创世纪', 1, 26, 14, '彼が羊の群れや牛の群れ、それに多くのしもべを持つようになったので、ペリシテ人は彼をねたんだ。'),
('JPN', '创世纪', 1, 26, 15, 'それでペリシテ人は、イサクの父アブラハムの時代に父のしもべたちが掘った井戸を、すべてふさいで土で満たした。'),
('JPN', '创世纪', 1, 26, 16, 'アビメレクはイサクに言った。「さあ、われわれのところから出て行ってほしい。われわれより、はるかに強くなったから。」'),
('JPN', '创世纪', 1, 26, 17, 'イサクはそこを去り、ゲラルの谷間に天幕を張って、そこに住んだ。'),
('JPN', '创世纪', 1, 26, 18, 'イサクは、彼の父アブラハムの時代に掘られて、アブラハムの死後にペリシテ人がふさいだ井戸を掘り返した。イサクは、それらに父がつけていた名と同じ名をつけた。'),
('JPN', '创世纪', 1, 26, 19, 'イサクのしもべたちがその谷間を掘っているとき、そこに湧き水の井戸を見つけた。'),
('JPN', '创世纪', 1, 26, 20, 'ゲラルの羊飼いたちは「この水はわれわれのものだ」と言って、イサクの羊飼いたちと争った。それで、イサクはその井戸の名をエセクと呼んだ。彼らがイサクと争ったからである。'),
('JPN', '创世纪', 1, 26, 21, 'しもべたちは、もう一つの井戸を掘った。それについても彼らが争ったので、その名をシテナと呼んだ。'),
('JPN', '创世纪', 1, 26, 22, 'イサクはそこから移って、もう一つの井戸を掘った。その井戸については争いがなかったので、その名をレホボテと呼んだ。そして彼は言った。「今や、主は私たちに広い所を与えて、この地で私たちが増えるようにしてくださった。」'),
('JPN', '创世纪', 1, 26, 23, '彼はそこからベエル・シェバに上った。'),
('JPN', '创世纪', 1, 26, 24, '主はその夜、彼に現れて言われた。「わたしは、あなたの父アブラハムの神である。恐れてはならない。わたしがあなたとともにいるからだ。わたしはあなたを祝福し、あなたの子孫を増し加える。わたしのしもべアブラハムのゆえに。」'),
('JPN', '创世纪', 1, 26, 25, 'イサクはそこに祭壇を築き、主の御名を呼び求めた。彼はそこに天幕を張り、イサクのしもべたちは、そこに井戸を掘った。'),
('JPN', '创世纪', 1, 26, 26, 'さて、アビメレクがゲラルからイサクのところにやって来た。友人のアフザテと、その軍の長ピコルも一緒であった。'),
('JPN', '创世纪', 1, 26, 27, 'イサクは彼らに言った。「なぜ、あなたがたは私のところに来たのですか。私を憎んで、自分たちのところから私を追い出したのに。」'),
('JPN', '创世纪', 1, 26, 28, '彼らは言った。「私たちは、主があなたとともにおられることを確かに見ました。ですから、こう言います。どうか私たちの間で、私たちとあなたとの間で、誓いを立ててください。あなたと盟約を結びたいのです。'),
('JPN', '创世纪', 1, 26, 29, '私たちがあなたに手出しをせず、ただ良いことだけをして、平和のうちにあなたを送り出したように、あなたも私たちに害を加えないという盟約です。あなたは今、主に祝福されています。」'),
('JPN', '创世纪', 1, 26, 30, 'そこでイサクは彼らのために宴会を催し、食べたり飲んだりした。'),
('JPN', '创世纪', 1, 26, 31, '翌朝早く、両者は互いに誓いを交わした。イサクは彼らを送り出し、彼らは平和のうちに彼のところから去って行った。'),
('JPN', '创世纪', 1, 26, 32, 'ちょうどその日、イサクのしもべたちが帰って来て、自分たちが掘り当てた井戸のことについて告げた。「私どもは水を見つけました。」'),
('JPN', '创世纪', 1, 26, 33, 'そこでイサクは、その井戸をシブアと呼んだ。それゆえ、その町の名は、今日に至るまで、ベエル・シェバという。'),
('JPN', '创世纪', 1, 26, 34, 'エサウは四十歳になって、ヒッタイト人ベエリの娘ユディトと、ヒッタイト人エロンの娘バセマテを妻に迎えた。'),
('JPN', '创世纪', 1, 26, 35, '彼女たちは、イサクとリベカにとって悩みの種となった。'),
('JPN', '创世纪', 1, 27, 1, 'イサクが年をとり、目がかすんでよく見えなくなったときのことである。彼は上の息子エサウを呼び寄せて、「わが子よ」と言った。すると彼は「はい、ここにおります」と答えた。'),
('JPN', '创世纪', 1, 27, 2, 'イサクは言った。「見なさい。私は年老いて、いつ死ぬか分からない。'),
('JPN', '创世纪', 1, 27, 3, 'さあ今、おまえの道具の矢筒と弓を取って野に出て行き、私のために獲物をしとめて来てくれないか。'),
('JPN', '创世纪', 1, 27, 4, 'そして私のために私の好きなおいしい料理を作り、ここに持って来て、私に食べさせてくれ。私が死ぬ前に、私自ら、おまえを祝福できるように。」'),
('JPN', '创世纪', 1, 27, 5, 'リベカは、イサクがその子エサウに話しているのを聞いていた。それで、エサウが獲物をしとめて父のところに持って来ようと野に出かけたとき、'),
('JPN', '创世纪', 1, 27, 6, 'リベカは息子のヤコブに言った。「今私は、父上があなたの兄エサウにこう言っておられるのを聞きました。'),
('JPN', '创世纪', 1, 27, 7, '『獲物を捕って来て、私においしい料理を作ってくれ。食べて、死ぬ前に、主の前でおまえを祝福しよう。』'),
('JPN', '创世纪', 1, 27, 8, 'さあ今、子よ、私があなたに命じることを、よく聞きなさい。'),
('JPN', '创世纪', 1, 27, 9, 'さあ、群れのところに行って、そこから最上の子やぎを二匹取って私のところに来なさい。私はそれで、あなたの父上の好きな、おいしい料理を作りましょう。'),
('JPN', '创世纪', 1, 27, 10, 'あなたが父上のところに持って行けば、食べて、死ぬ前にあなたを祝福してくださるでしょう。」'),
('JPN', '创世纪', 1, 27, 11, 'ヤコブは母リベカに言った。「でも、兄さんのエサウは毛深い人なのに、私の肌は滑らかです。'),
('JPN', '创世纪', 1, 27, 12, 'もしかすると父上は私にさわって、私にからかわれたと思うでしょう。私は祝福どころか、のろいをこの身に招くことになります。」'),
('JPN', '创世纪', 1, 27, 13, '母は彼に言った。「子よ、あなたへののろいは私の身にあるように。ただ私の言うことをよく聞いて、行って子やぎを取って来なさい。」'),
('JPN', '创世纪', 1, 27, 14, 'それでヤコブは行って、取って母のところに持って来た。母は、父の好む、おいしい料理を作った。'),
('JPN', '创世纪', 1, 27, 15, 'それからリベカは、家の中で自分の手もとにあった、上の息子エサウの衣を取って来て、それを下の息子ヤコブに着せ、'),
('JPN', '创世纪', 1, 27, 16, 'また、子やぎの毛皮を、彼の両腕と、首の滑らかなところに巻き付けた。'),
('JPN', '创世纪', 1, 27, 17, 'そうして、自分が作ったおいしい料理とパンを、息子ヤコブの手に渡した。'),
('JPN', '创世纪', 1, 27, 18, 'ヤコブは父のところに行き、「お父さん」と言った。イサクは「おお。おまえはだれかね、わが子よ」と尋ねた。'),
('JPN', '创世纪', 1, 27, 19, 'ヤコブは父に、「長男のエサウです。私はお父さんが言われたとおりにしました。どうぞ、起きて座り、私の獲物を召し上がってください。そうして、自ら私を祝福してください」と答えた。'),
('JPN', '创世纪', 1, 27, 20, 'イサクは、その子に言った。「どうして、こんなに早く見つけることができたのかね、わが子よ。」彼は答えた。「あなたの神、主が私のために、取り計らってくださったのです。」'),
('JPN', '创世纪', 1, 27, 21, 'そこでイサクはヤコブに言った。「近くに寄ってくれ。わが子よ。おまえが本当にわが子エサウなのかどうか、私はおまえにさわってみたい。」'),
('JPN', '创世纪', 1, 27, 22, 'ヤコブが父イサクに近寄ると、イサクは彼にさわり、そして言った。「声はヤコブの声だが、手はエサウの手だ。」'),
('JPN', '创世纪', 1, 27, 23, 'ヤコブの手が、兄エサウの手のように毛深かったので、イサクには見分けがつかなかった。それでイサクは彼を祝福しようとして、'),
('JPN', '创世纪', 1, 27, 24, '「本当におまえは、わが子エサウだね」と言った。するとヤコブは答えた。「そうです。」'),
('JPN', '创世纪', 1, 27, 25, 'そこでイサクは言った。「私のところに持って来なさい。わが子の獲物を食べたい。そうして私自ら、おまえを祝福しよう。」そこでヤコブが持って来ると、イサクはそれを食べた。またぶどう酒を持って来ると、それも飲んだ。'),
('JPN', '创世纪', 1, 27, 26, '父イサクはヤコブに、「近寄って私に口づけしてくれ、わが子よ」と言ったので、'),
('JPN', '创世纪', 1, 27, 27, 'ヤコブは近づいて、彼に口づけした。イサクはヤコブの衣の香りを嗅ぎ、彼を祝福して言った。「ああ、わが子の香り。主が祝福された野の香りのようだ。'),
('JPN', '创世纪', 1, 27, 28, '神がおまえに天の露と地の肥沃、豊かな穀物と新しいぶどう酒を与えてくださるように。'),
('JPN', '创世纪', 1, 27, 29, '諸国の民がおまえに仕え、もろもろの国民がおまえを伏し拝むように。おまえは兄弟たちの主となり、おまえの母の子がおまえを伏し拝むように。おまえを呪う者がのろわれ、おまえを祝福する者が祝福されるように。」'),
('JPN', '创世纪', 1, 27, 30, 'イサクがヤコブを祝福し終わり、ヤコブが父イサクの前から出て行くとすぐに、兄のエサウが猟から戻って来た。'),
('JPN', '创世纪', 1, 27, 31, '彼もまた、おいしい料理を作って、父のところに持って来た。そして父に言った。「お父さん。起きて、息子の獲物を召し上がってください。あなた自ら、私を祝福してくださるために。」'),
('JPN', '创世纪', 1, 27, 32, '父イサクは彼に言った。「だれだね、おまえは。」彼は言った。「私はあなたの子、長男のエサウです。」'),
('JPN', '创世纪', 1, 27, 33, 'イサクは激しく身震いして言った。「では、いったい、あれはだれだったのか。獲物をしとめて、私のところに持って来たのは。おまえが来る前に、私はみな食べてしまい、彼を祝福してしまった。彼は必ず祝福されるだろう。」'),
('JPN', '创世纪', 1, 27, 34, 'エサウは父のことばを聞くと、声の限りに激しく泣き叫び、父に言った。「お父さん、私を祝福してください。私も。」'),
('JPN', '创世纪', 1, 27, 35, '父は言った。「おまえの弟が来て、だましたのだ。そしておまえへの祝福を奪い取ってしまった。」'),
('JPN', '创世纪', 1, 27, 36, 'エサウは言った。「あいつの名がヤコブというのも、このためか。二度までも私を押しのけて。私の長子の権利を奪い取り、今また、私への祝福を奪い取った。」また言った。「私のためには、祝福を取っておかれなかったのですか。」'),
('JPN', '创世纪', 1, 27, 37, 'イサクは答えてエサウに言った。「ああ、私は彼をおまえの主とし、すべての兄弟を彼にしもべとして与えた。また穀物と新しいぶどう酒で彼を養うようにした。わが子よ、おまえのためには、いったい何ができるだろうか。」'),
('JPN', '创世纪', 1, 27, 38, 'エサウは父に言った。「お父さん、祝福は一つしかないのですか。お父さん、私を祝福してください。私も。」エサウは声をあげて泣いた。'),
('JPN', '创世纪', 1, 27, 39, '父イサクは彼に答えた。「見よ。おまえの住む所には地の肥沃がなく、上から天の露もない。'),
('JPN', '创世纪', 1, 27, 40, 'おまえは自分の剣によって生き、自分の弟に仕えることになる。しかし、おまえが奮い立つなら、おまえは自分の首から彼のくびきを解き捨てるだろう。」'),
('JPN', '创世纪', 1, 27, 41, 'エサウは、父がヤコブを祝福した祝福のことで、ヤコブを恨んだ。それでエサウは心の中で言った。「父の喪の日も近づいている。そのとき、弟ヤコブを殺してやろう。」'),
('JPN', '创世纪', 1, 27, 42, '上の息子エサウの言ったことがリベカに伝えられると、彼女は人を送り、下の息子ヤコブを呼び寄せて言った。「兄さんのエサウが、あなたを殺して鬱憤を晴らそうとしています。'),
('JPN', '创世纪', 1, 27, 43, 'さあ今、子よ、私の言うことをよく聞きなさい。すぐに立って、ハランへ、私の兄ラバンのところへ逃げなさい。'),
('JPN', '创世纪', 1, 27, 44, '兄さんの憤りが収まるまで、おじラバンのところにしばらくとどまっていなさい。'),
('JPN', '创世纪', 1, 27, 45, '兄さんの怒りが収まって、あなたが兄さんにしたことを兄さんが忘れたとき、私は人を送って、あなたをそこから呼び戻しましょう。あなたたち二人を一日のうちに失うことなど、どうして私にできるでしょう。」'),
('JPN', '创世纪', 1, 27, 46, 'リベカはイサクに言った。「私はヒッタイト人の娘たちのことで、生きているのがいやになりました。もしヤコブが、この地の娘たちのうちで、このようなヒッタイト人の娘たちのうちから妻を迎えるとしたら、私は何のために生きることになるのでしょう。」'),
('JPN', '创世纪', 1, 28, 1, 'イサクはヤコブを呼び寄せ、彼を祝福し、そして彼に命じた。「カナンの娘たちの中から妻を迎えてはならない。'),
('JPN', '创世纪', 1, 28, 2, 'さあ立って、パダン・アラムの、おまえの母の父ベトエルの家に行き、そこで母の兄ラバンの娘たちの中から妻を迎えなさい。'),
('JPN', '创世纪', 1, 28, 3, '全能の神がおまえを祝福し、多くの子を与え、おまえを増やしてくださるように。そして、おまえが多くの民の群れとなるように。'),
('JPN', '创世纪', 1, 28, 4, '神はアブラハムの祝福をおまえに、すなわち、おまえと、おまえとともにいるおまえの子孫に与え、神がアブラハムに下さった地、おまえが今寄留しているこの地を継がせてくださるように。」'),
('JPN', '创世纪', 1, 28, 5, 'こうしてイサクはヤコブを送り出した。彼はパダン・アラムの、ラバンのところに行った。ヤコブとエサウの母リベカの兄、アラム人ベトエルの子ラバンのところである。'),
('JPN', '创世纪', 1, 28, 6, 'エサウは、イサクがヤコブを祝福したこと、またパダン・アラムから妻を迎えるために彼を送り出したことを知った。イサクが、ヤコブを祝福して送り出したときに、カナンの娘たちから妻を迎えてはならないと命じ、'),
('JPN', '创世纪', 1, 28, 7, 'ヤコブが、父と母の言うことに聞き従って、パダン・アラムへ行ったことも。'),
('JPN', '创世纪', 1, 28, 8, 'さらにエサウは、カナンの娘たちを、父イサクが気に入っていないことを知った。'),
('JPN', '创世纪', 1, 28, 9, 'それでエサウはイシュマエルのところに行き、今いる妻たちのほかに、アブラハムの子イシュマエルの娘で、ネバヨテの妹マハラテを妻として迎えた。'),
('JPN', '创世纪', 1, 28, 10, 'ヤコブはベエル・シェバを出て、ハランへと向かった。'),
('JPN', '创世纪', 1, 28, 11, '彼はある場所にたどり着き、そこで一夜を明かすことにした。ちょうど日が沈んだからである。彼はその場所で石を取って枕にし、その場所で横になった。'),
('JPN', '创世纪', 1, 28, 12, 'すると彼は夢を見た。見よ、一つのはしごが地に立てられていた。その上の端は天に届き、見よ、神の使いたちが、そのはしごを上り下りしていた。'),
('JPN', '创世纪', 1, 28, 13, 'そして、見よ、主がその上に立って、こう言われた。「わたしは、あなたの父アブラハムの神、イサクの神、主である。わたしは、あなたが横たわっているこの地を、あなたとあなたの子孫に与える。'),
('JPN', '创世纪', 1, 28, 14, 'あなたの子孫は地のちりのように多くなり、あなたは、西へ、東へ、北へ、南へと広がり、地のすべての部族はあなたによって、またあなたの子孫によって祝福される。'),
('JPN', '创世纪', 1, 28, 15, '見よ。わたしはあなたとともにいて、あなたがどこへ行っても、あなたを守り、あなたをこの地に連れ帰る。わたしは、あなたに約束したことを成し遂げるまで、決してあなたを捨てない。」'),
('JPN', '创世纪', 1, 28, 16, 'ヤコブは眠りから覚めて、言った。「まことに主はこの場所におられる。それなのに、私はそれを知らなかった。」'),
('JPN', '创世纪', 1, 28, 17, '彼は恐れて言った。「この場所は、なんと恐れ多いところだろう。ここは神の家にほかならない。ここは天の門だ。」'),
('JPN', '创世纪', 1, 28, 18, '翌朝早く、ヤコブは自分が枕にした石を取り、それを立てて石の柱とし、柱の頭に油を注いだ。'),
('JPN', '创世纪', 1, 28, 19, 'そしてその場所の名をベテルと呼んだ。その町の名は、もともとはルズであった。'),
('JPN', '创世纪', 1, 28, 20, 'ヤコブは誓願を立てた。「神が私とともにおられて、私が行くこの旅路を守り、食べるパンと着る衣を下さり、'),
('JPN', '创世纪', 1, 28, 21, '無事に父の家に帰らせてくださるなら、主は私の神となり、'),
('JPN', '创世纪', 1, 28, 22, '石の柱として立てたこの石は神の家となります。私は、すべてあなたが私に下さる物の十分の一を必ずあなたに献げます。」'),
('JPN', '创世纪', 1, 29, 1, 'ヤコブは旅を続けて、東の人々の国へ行った。'),
('JPN', '创世纪', 1, 29, 2, 'ふと彼が見ると、野に井戸があった。ちょうどその傍らに、三つの羊の群れが伏していた。その井戸から群れに水を飲ませることになっていたからである。その井戸の口の上にある石は大きかった。'),
('JPN', '创世纪', 1, 29, 3, '群れがみなそこに集められたら、その石を井戸の口から転がして、羊に水を飲ませ、その石を再び井戸の口の元の場所に戻すことになっていた。'),
('JPN', '创世纪', 1, 29, 4, 'ヤコブがその人たちに「兄弟たちよ、あなたがたはどこの方ですか」と尋ねると、彼らは「私たちはハランの者です」と答えた。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '创世纪', 1, 29, 5, 'それでヤコブが「あなたがたはナホルの子ラバンをご存じですか」と尋ねると、彼らは「よく知っています」と答えた。'),
('JPN', '创世纪', 1, 29, 6, 'ヤコブは彼らに尋ねた。「その人は元気ですか。」すると彼らは、「元気です。ほら、娘のラケルが羊を連れてやって来ます」と言った。'),
('JPN', '创世纪', 1, 29, 7, 'ヤコブは言った。「ご覧なさい。日はまだ高いし、群れを集める時間でもありません。羊に水を飲ませて、草を食べさせに戻ってはどうですか。」'),
('JPN', '创世纪', 1, 29, 8, 'すると彼らは言った。「そうはできません。群れがみな集められて、井戸の口から石を転がすまでは。それから、羊に水を飲ませるのです。」'),
('JPN', '创世纪', 1, 29, 9, 'ヤコブがまだ彼らと話しているとき、ラケルが父の羊の群れを連れてやって来た。彼女は羊を飼っていたのである。'),
('JPN', '创世纪', 1, 29, 10, 'ヤコブは、母の兄ラバンの娘ラケルと、母の兄ラバンの羊の群れを見ると、すぐ近寄って行って、井戸の口の上の石を転がし、母の兄ラバンの羊の群れに水を飲ませた。'),
('JPN', '创世纪', 1, 29, 11, 'そしてヤコブはラケルに口づけし、声をあげて泣いた。'),
('JPN', '创世纪', 1, 29, 12, 'ヤコブはラケルに、自分は彼女の父の甥であり、リベカの子であることを告げた。彼女は走って行って、父にそのことを告げた。'),
('JPN', '创世纪', 1, 29, 13, 'ラバンは妹の子ヤコブのことを聞くとすぐ、彼を迎えに走って行って、彼を抱きしめて口づけした。そして彼を自分の家に連れて帰った。ヤコブはラバンに事の次第をすべて話した。'),
('JPN', '创世纪', 1, 29, 14, 'ラバンは彼に「あなたは本当に私の骨肉だ」と言った。ヤコブは彼のところに一か月滞在した。'),
('JPN', '创世纪', 1, 29, 15, 'ラバンはヤコブに言った。「あなたが私の親類だからといって、ただで私に仕えることもないだろう。どういう報酬が欲しいのか、言ってもらいたい。」'),
('JPN', '创世纪', 1, 29, 16, 'ラバンには二人の娘がいた。姉の名はレア、妹の名はラケルであった。'),
('JPN', '创世纪', 1, 29, 17, 'レアは目が弱々しかったが、ラケルは姿も美しく、顔だちも美しかった。'),
('JPN', '创世纪', 1, 29, 18, 'ヤコブはラケルを愛していた。それで、「私はあなたの下の娘ラケルのために、七年間あなたにお仕えします」と言った。'),
('JPN', '创世纪', 1, 29, 19, 'ラバンは、「娘を他人にやるよりは、あなたにやるほうがよい。私のところにとどまっていなさい」と言った。'),
('JPN', '创世纪', 1, 29, 20, 'ヤコブはラケルのために七年間仕えた。ヤコブは彼女を愛していたので、それもほんの数日のように思われた。'),
('JPN', '创世纪', 1, 29, 21, 'ヤコブはラバンに言った。「私の妻を下さい。約束の日々が満ちたのですから。彼女のところに入りたいのです。」'),
('JPN', '创世纪', 1, 29, 22, 'そこでラバンは、その土地の人たちをみな集めて祝宴を催した。'),
('JPN', '创世纪', 1, 29, 23, '夕方になって、ラバンは娘のレアをヤコブのところに連れて行ったので、ヤコブは彼女のところに入った。'),
('JPN', '创世纪', 1, 29, 24, 'ラバンはまた、娘のレアに、自分の女奴隷ジルパを彼女の女奴隷として与えた。'),
('JPN', '创世纪', 1, 29, 25, '朝になって、見ると、それはレアであった。それで彼はラバンに言った。「あなたは私に何ということをしたのですか。私はラケルのために、あなたに仕えたのではありませんか。なぜ、私をだましたのですか。」'),
('JPN', '创世纪', 1, 29, 26, 'ラバンは答えた。「われわれのところでは、上の娘より先に下の娘を嫁がせるようなことはしないのだ。'),
('JPN', '创世纪', 1, 29, 27, 'この婚礼の一週間を終えなさい。そうすれば、あの娘もあなたにあげよう。その代わり、あなたはもう七年間、私に仕えなければならない。」'),
('JPN', '创世纪', 1, 29, 28, 'そこで、ヤコブはそのようにした。すなわち、その婚礼の一週間を終えた。それでラバンは、その娘ラケルを彼に妻として与えた。'),
('JPN', '创世纪', 1, 29, 29, 'ラバンは娘のラケルに、自分の女奴隷ビルハを彼女の女奴隷として与えた。'),
('JPN', '创世纪', 1, 29, 30, 'ヤコブはこうして、ラケルのところにも入った。ヤコブは、レアよりもラケルを愛していた。それで、もう七年間ラバンに仕えた。'),
('JPN', '创世纪', 1, 29, 31, '主はレアが嫌われているのを見て、彼女の胎を開かれたが、ラケルは不妊の女であった。'),
('JPN', '创世纪', 1, 29, 32, 'レアは身ごもって男の子を産み、その子をルベンと名づけた。彼女が、「主は私の悩みをご覧になった。今こそ夫は私を愛するでしょう」と言ったからである。'),
('JPN', '创世纪', 1, 29, 33, '彼女は再び身ごもって男の子を産み、「主は私が嫌われているのを聞いて、この子も私に授けてくださった」と言って、その子をシメオンと名づけた。'),
('JPN', '创世纪', 1, 29, 34, '彼女はまた身ごもって男の子を産み、「今度こそ、夫は私に結びつくでしょう。私が彼に三人の子を産んだのだから」と言った。それゆえ、その子の名はレビと呼ばれた。'),
('JPN', '创世纪', 1, 29, 35, '彼女はさらに身ごもって男の子を産み、「今度は、私は主をほめたたえます」と言った。それゆえ、彼女はその子をユダと名づけた。その後、彼女は子を産まなくなった。'),
('JPN', '创世纪', 1, 30, 1, 'ラケルは自分がヤコブに子を産んでいないのを見た。ラケルは姉に嫉妬し、ヤコブに言った。「私に子どもを下さい。でなければ、私は死にます。」'),
('JPN', '创世纪', 1, 30, 2, 'ヤコブはラケルに怒りを燃やして言った。「私が神に代われるというのか。胎の実をおまえに宿らせないのは神なのだ。」'),
('JPN', '创世纪', 1, 30, 3, '彼女は言った。「ここに、私の女奴隷のビルハがいます。彼女のところに入り、彼女が私の膝に子を産むようにしてください。そうすれば、彼女によって私も子を得られるでしょう。」'),
('JPN', '创世纪', 1, 30, 4, 'ラケルは彼に女奴隷ビルハを妻として与えたので、ヤコブは彼女のところに入った。'),
('JPN', '创世纪', 1, 30, 5, 'ビルハは身ごもり、ヤコブに男の子を産んだ。'),
('JPN', '创世纪', 1, 30, 6, 'そこでラケルは、「神は私をかばってくださり、私の声を聞き入れて、私に男の子を与えてくださった」と言った。それゆえ、彼女はその子をダンと名づけた。'),
('JPN', '创世纪', 1, 30, 7, 'ラケルの女奴隷ビルハは再び身ごもって、ヤコブに二番目の男の子を産んだ。'),
('JPN', '创世纪', 1, 30, 8, 'そこでラケルは、「私は姉と死に物狂いの争いをして、ついに勝った」と言って、その子をナフタリと名づけた。'),
('JPN', '创世纪', 1, 30, 9, 'レアは自分が子を産まなくなったのを見て、彼女の女奴隷ジルパをヤコブに妻として与えた。'),
('JPN', '创世纪', 1, 30, 10, 'レアの女奴隷ジルパはヤコブに男の子を産んだ。'),
('JPN', '创世纪', 1, 30, 11, 'レアは「幸運が来た」と言って、その子をガドと名づけた。'),
('JPN', '创世纪', 1, 30, 12, 'レアの女奴隷ジルパはヤコブに二番目の男の子を産んだ。'),
('JPN', '创世纪', 1, 30, 13, 'レアは、「なんと幸せなことでしょう。女たちは私を幸せ者と言うでしょう」と言って、その子をアシェルと名づけた。'),
('JPN', '创世纪', 1, 30, 14, 'さて、麦の刈り入れのころ、ルベンは出て行って、野で恋なすびを見つけた。そして、それを母レアのところに持って来た。すると、ラケルはレアに「どうか、あなたの息子の恋なすびを少し私に下さい」と言った。'),
('JPN', '创世纪', 1, 30, 15, 'レアはラケルに言った。「あなたは私の夫を取っても、まだ足りないのですか。私の息子の恋なすびまで取り上げようとするのですか。」ラケルは答えた。「では、あなたの息子の恋なすびと引き替えに、今夜、あの人にあなたと一緒に寝てもらいます。」'),
('JPN', '创世纪', 1, 30, 16, '夕方になって、ヤコブは野から帰って来た。レアは彼を出迎えて言った。「あなたは私のところに来ることになっています。私は、息子の恋なすびで、あなたをようやく手に入れたのですから。」その夜、ヤコブはレアと寝た。'),
('JPN', '创世纪', 1, 30, 17, '神はレアの願いを聞かれたので、彼女は身ごもって、ヤコブに五番目の男の子を産んだ。'),
('JPN', '创世纪', 1, 30, 18, 'そこでレアは、「私が女奴隷を夫に与えたので、神は私に報酬を下さった」と言って、その子をイッサカルと名づけた。'),
('JPN', '创世纪', 1, 30, 19, 'レアはまた身ごもって、ヤコブに六番目の男の子を産んだ。'),
('JPN', '创世纪', 1, 30, 20, 'レアは言った。「神は私に良い賜物を下さった。今度こそ夫は私を尊ぶでしょう。彼に六人の子を産んだのですから。」そしてその子をゼブルンと名づけた。'),
('JPN', '创世纪', 1, 30, 21, 'その後、レアは女の子を産み、その子をディナと名づけた。'),
('JPN', '创世纪', 1, 30, 22, '神はラケルに心を留められた。神は彼女の願いを聞き入れて、その胎を開かれた。'),
('JPN', '创世纪', 1, 30, 23, '彼女は身ごもって男の子を産み、「神は私の汚名を取り去ってくださった」と言った。'),
('JPN', '创世纪', 1, 30, 24, '彼女は、その子をヨセフと名づけ、「主が男の子をもう一人、私に加えてくださるように」と言った。'),
('JPN', '创世纪', 1, 30, 25, 'ラケルがヨセフを産んだころ、ヤコブはラバンに言った。「私を去らせて、故郷の地へ帰らせてください。'),
('JPN', '创世纪', 1, 30, 26, '妻たちや子どもたちを私に下さい。彼女たちのために私はあなたに仕えてきました。行かせてください。あなたに仕えた私の働きは、あなたがよくご存じなのですから。」'),
('JPN', '创世纪', 1, 30, 27, 'ラバンは彼に言った。「私の願いをあなたがかなえてくれるなら──。あなたのおかげで主が私を祝福してくださったことを、私は占いで知っている。」'),
('JPN', '创世纪', 1, 30, 28, 'さらに言った。「あなたの報酬をはっきりと申し出てくれ。私はそれを払おう。」'),
('JPN', '创世纪', 1, 30, 29, 'ヤコブは彼に言った。「私がどのようにあなたに仕え、また、あなたの家畜が私のもとでどのようであったかは、あなた自身がよくご存じです。'),
('JPN', '创世纪', 1, 30, 30, '私が来る前は、あなたの財産はわずかでしたが、増えて多くなりました。私の行く先々で主があなたを祝福されたからです。いったい、いつになったら私は自分の家を持てるのですか。」'),
('JPN', '创世纪', 1, 30, 31, '彼は言った。「あなたに何をあげようか。」ヤコブは言った。「何も下さるには及びません。もし私に次のことをしてくださるなら、私は再びあなたの群れを飼って守りましょう。'),
('JPN', '创世纪', 1, 30, 32, '私は今日、あなたの群れをみな見て回りましょう。その中から、ぶち毛と斑毛の羊をすべて、子羊の中では黒毛のものをすべて、やぎの中では斑毛とぶち毛のものを取り分けて、それらを私の報酬にしてください。'),
('JPN', '创世纪', 1, 30, 33, '後であなたが私の報酬を見に来られたとき、私の正しさが証明されるでしょう。やぎの中に、ぶち毛や斑毛でないものや、子羊の中に、黒毛でないものがあれば、それはすべて、私が盗んだことになります。」'),
('JPN', '创世纪', 1, 30, 34, 'するとラバンは言った。「よろしい。あなたの言うとおりになればよいが。」'),
('JPN', '创世纪', 1, 30, 35, 'ラバンはその日、縞毛と斑毛の雄やぎと、ぶち毛と斑毛の雌やぎのすべて、すなわち身に白いところのあるもののすべて、それに、黒毛の子羊のすべてを取りのけて、息子たちの手に渡した。'),
('JPN', '创世纪', 1, 30, 36, 'そして、自分とヤコブの間に三日分の距離をおいた。ヤコブはラバンの残りの群れを飼った。'),
('JPN', '创世纪', 1, 30, 37, 'ヤコブは、ポプラや、アーモンドや、すずかけの木の若枝を取り、それらの白い筋の皮を剝いで、若枝の白いところをむき出しにし、'),
('JPN', '创世纪', 1, 30, 38, '皮を剝いだ枝を、群れが水を飲みに来る水溜めの水ぶねの中に、群れと差し向かいに置いた。それで群れのやぎたちは、水を飲みに来たとき、さかりがついた。'),
('JPN', '创世纪', 1, 30, 39, 'こうして羊ややぎは枝の前で交尾し、縞毛、ぶち毛、斑毛のものを産んだ。'),
('JPN', '创世纪', 1, 30, 40, 'ヤコブは羊を分けて、その群れが、ラバンの群れの縞毛のものとすべての黒毛のものに、向かい合わせになるようにした。彼は自分の群れを別にまとめておき、ラバンの群れと一緒にしなかった。'),
('JPN', '创世纪', 1, 30, 41, 'また、強い群れにさかりがついたときに、ヤコブはいつも、あの枝を水ぶねの中に、群れの目の前になるように置き、枝のところで交尾させた。'),
('JPN', '创世纪', 1, 30, 42, 'しかし、弱い群れのときには、それを置かなかった。こうして、弱いものはラバンのものとなり、強いものはヤコブのものとなった。'),
('JPN', '创世纪', 1, 30, 43, 'このようにして、この人は大いに富み、多くの群れと、男女の奴隷、それにらくだとろばを持つようになった。'),
('JPN', '创世纪', 1, 31, 1, 'ところで、ヤコブはラバンの息子たちが、「ヤコブはわれわれの父の物をみな取った。父の物で、このすべての富をものにしたのだ」と言っているのを聞いた。'),
('JPN', '创世纪', 1, 31, 2, 'ヤコブがラバンの態度を見ると、はたして、それは彼に対して以前のようではなかった。'),
('JPN', '创世纪', 1, 31, 3, '主はヤコブに言われた。「あなたが生まれた、あなたの父たちの国に帰りなさい。わたしは、あなたとともにいる。」'),
('JPN', '创世纪', 1, 31, 4, 'ヤコブは人を送って、ラケルとレアを自分の群れのいる野に呼び寄せ、'),
('JPN', '创世纪', 1, 31, 5, '彼女たちに言った。「私は、あなたたちの父の態度が以前のようではないのに気づいている。しかし、私の父の神は私とともにおられる。'),
('JPN', '创世纪', 1, 31, 6, 'あなたたちがよく知っているように、私はあなたたちの父に、力を尽くして仕えてきた。'),
('JPN', '创世纪', 1, 31, 7, 'それなのに、あなたたちの父は私を欺き、私の報酬を何度も変えた。しかし神は、彼が私に害を加えることを許されなかった。'),
('JPN', '创世纪', 1, 31, 8, '彼が『ぶち毛のものはあなたの報酬になる』と言えば、群れのすべてがぶち毛のものを産んだ。また、『縞毛のものはあなたの報酬になる』と言えば、群れのすべてが縞毛のものを産んだ。'),
('JPN', '创世纪', 1, 31, 9, 'こうして神は、あなたたちの父の家畜を取り上げて、私に下さったのだ。'),
('JPN', '创世纪', 1, 31, 10, '群れのやぎにさかりがついたとき、私が夢の中で目を上げて見ると、見よ、雌やぎと交尾している雄やぎは、縞毛、ぶち毛、斑毛ばかりであった。'),
('JPN', '创世纪', 1, 31, 11, 'すると、神の使いが夢の中で私に『ヤコブよ』と言われた。私は『はい』と答えた。'),
('JPN', '创世纪', 1, 31, 12, '御使いは言われた。『目を上げて見よ。雌やぎと交尾している雄やぎはみな、縞毛、ぶち毛、斑毛である。ラバンがあなたにしてきたことはみな、わたしが見た。'),
('JPN', '创世纪', 1, 31, 13, 'わたしは、あのベテルの神だ。あなたはそこで、石の柱に油注ぎをし、わたしに誓願を立てた。さあ立って、この土地を出て、あなたの生まれた国に帰りなさい。』」'),
('JPN', '创世纪', 1, 31, 14, 'ラケルとレアは答えた。「私たちの父の家には、相続財産で私たちの取り分がまだあるでしょうか。'),
('JPN', '创世纪', 1, 31, 15, '私たちは父に、よそ者と見なされているのではないでしょうか。あの人は私たちを売り、しかもその代金を食いつぶしたのですから。'),
('JPN', '创世纪', 1, 31, 16, '神が私たちの父から取り上げた富は、すべて私たちのもの、また子どもたちのものです。さあ、神があなたにお告げになったことを、すべてなさってください。」'),
('JPN', '创世纪', 1, 31, 17, 'そこでヤコブは立って、彼の子たち、妻たちをらくだに乗せ、'),
('JPN', '创世纪', 1, 31, 18, 'また、すべての家畜と、彼が得たすべての財産、彼がパダン・アラムで自分のものとした家畜を連れて、カナンの地にいる父イサクのところへ向かった。'),
('JPN', '创世纪', 1, 31, 19, 'そのとき、ラバンは自分の羊の毛を刈りに出ていた。ラケルは、父が所有しているテラフィムを盗み出した。'),
('JPN', '创世纪', 1, 31, 20, 'ヤコブはアラム人ラバンを欺いて、自分が逃げるのを彼に知られないようにした。'),
('JPN', '创世纪', 1, 31, 21, '彼は自分のものをすべて持って逃げた。彼は立ち去ってあの大河を渡り、ギルアデの山地の方へ向かった。'),
('JPN', '创世纪', 1, 31, 22, '三日目に、ヤコブが逃げたことがラバンに知らされた。'),
('JPN', '创世纪', 1, 31, 23, 'ラバンは身内の者たちを率いて、七日の道のりを追って行き、ギルアデの山地でヤコブに追いついた。'),
('JPN', '创世纪', 1, 31, 24, '神は夜、夢でアラム人ラバンに現れて仰せられた。「あなたは気をつけて、ヤコブと事の善悪を論じないようにしなさい。」'),
('JPN', '创世纪', 1, 31, 25, 'ラバンはヤコブに追いついた。そのとき、ヤコブは山地に天幕を張っていたが、ラバンもギルアデの山地に身内の者たちと天幕を張った。'),
('JPN', '创世纪', 1, 31, 26, 'ラバンはヤコブに言った。「何ということをしたのか。私を欺いて、娘たちを、剣で捕らえられた者のように引いて行くとは。'),
('JPN', '创世纪', 1, 31, 27, 'なぜ、あなたは逃げ隠れて私を欺き、私に知らせなかったのか。タンバリンや竪琴で喜び歌って、あなたを送り出しただろうに。'),
('JPN', '创世纪', 1, 31, 28, 'しかもあなたは、私の孫や娘たちに口づけもさせなかった。あなたは全く愚かなことをしたものだ。'),
('JPN', '创世纪', 1, 31, 29, '私には、あなたがたに害を加える力があるが、昨夜、あなたがたの父の神が私に、『あなたは気をつけて、ヤコブと事の善悪を論じないようにせよ』と告げられた。'),
('JPN', '创世纪', 1, 31, 30, 'それはそうと、あなたは、あなたの父の家がどうしても恋しくなって出て行ったのだろうが、なぜ私の神々を盗んだのか。」'),
('JPN', '创世纪', 1, 31, 31, 'ヤコブはラバンに答えた。「あなたがご自分の娘たちを私から奪い取りはしないかと思って、恐れたのです。'),
('JPN', '创世纪', 1, 31, 32, 'あなたがご自分の神々をだれかのところで見つけたら、私はその者を生かしておきません。私のところに何があるか、私たちの一族の前で、ご自分で調べてください。そして持って行ってください。」ヤコブは、ラケルが盗んだことを知らなかったのである。'),
('JPN', '创世纪', 1, 31, 33, 'そこで、ラバンはヤコブの天幕とレアの天幕、また二人の女奴隷の天幕に入って行ったが、見つからなかった。彼はレアの天幕を出て、ラケルの天幕に入った。'),
('JPN', '创世纪', 1, 31, 34, 'ところが、ラケルはすでにテラフィムを取って、それらをらくだの鞍の中に入れ、その上に座っていたので、ラバンが天幕を隅々まで調べても見つからなかった。'),
('JPN', '创世纪', 1, 31, 35, 'ラケルは父に言った。「父上、どうか怒らないでください。私はあなたの前で立ち上がることができません。女の常のことがあるからです。」彼は捜したが、テラフィムは見つからなかった。'),
('JPN', '创世纪', 1, 31, 36, 'するとヤコブは怒って、ラバンをとがめた。ヤコブはラバンに向かって言った。「私にどんな背きがあり、どんな罪があるというのですか。私をここまで追いつめるとは。'),
('JPN', '创世纪', 1, 31, 37, 'あなたは私の物を一つ残らず調べて、何か一つでも、あなたの家の物を見つけましたか。もしあったなら、それを私の一族と、あなたの一族の前に置いて、彼らに私たち二人の間をさばかせましょう。'),
('JPN', '创世纪', 1, 31, 38, '私があなたと一緒にいた二十年間、あなたの雌羊も雌やぎも流産したことはなく、また私はあなたの群れの雄羊も食べませんでした。'),
('JPN', '创世纪', 1, 31, 39, '野獣にかみ裂かれたものは、あなたのもとへ持って行かずに、私が負担しました。それなのに、あなたは昼盗まれたものや夜盗まれたものについてまでも、私に責任を負わせました。'),
('JPN', '创世纪', 1, 31, 40, '私は昼は暑さに、夜は寒さに悩まされて、眠ることもできませんでした。'),
('JPN', '创世纪', 1, 31, 41, '私はこの二十年間、あなたの家で過ごし、十四年間はあなたの二人の娘たちのために、六年間はあなたの群れのために、あなたに仕えてきました。しかも、あなたは何度も私の報酬を変えました。'),
('JPN', '创世纪', 1, 31, 42, 'もし、私の父祖の神、アブラハムの神、イサクの恐れる方が私についておられなかったなら、あなたはきっと何も持たせずに私を去らせたことでしょう。神は私の苦しみとこの手の労苦を顧みられ、昨夜さばきをなさったのです。」'),
('JPN', '创世纪', 1, 31, 43, 'ラバンはヤコブに答えた。「娘たちは私の娘、子どもたちは私の子ども、群れは私の群れ、すべてあなたが見るものは私のもの。この私の娘たちに対して、または、娘たちが産んだ子どもたちに対して、今日、私が何をするというのか。'),
('JPN', '创世纪', 1, 31, 44, 'さあ今、私とあなたは契約を結び、それを私とあなたとの間の証拠としよう。」'),
('JPN', '创世纪', 1, 31, 45, 'そこで、ヤコブは石を取り、それを立てて石の柱とした。'),
('JPN', '创世纪', 1, 31, 46, 'ヤコブは自分の一族に言った。「石を集めなさい。」そこで彼らは石を取り、石塚を作った。彼らは石塚のそばで食事をした。'),
('JPN', '创世纪', 1, 31, 47, 'ラバンはそれをエガル・サハドタと名づけたが、ヤコブはこれをガルエデと名づけた。'),
('JPN', '创世纪', 1, 31, 48, 'そしてラバンは言った。「この石塚は、今日、私とあなたの間の証拠である。」それゆえ、その名はガルエデと呼ばれた。'),
('JPN', '创世纪', 1, 31, 49, 'また、それはミツパとも呼ばれた。彼がこう言ったからである。「われわれが互いに目の届かないところにいるとき、主が私とあなたの間の見張りをされるように。'),
('JPN', '创世纪', 1, 31, 50, 'もし、あなたが私の娘たちをひどい目にあわせたり、娘たちのほかに妻をめとったりするなら、たとえ、だれもわれわれとともにいなくても、見よ、神が私とあなたの間の証人である。」'),
('JPN', '创世纪', 1, 31, 51, 'また、ラバンはヤコブに言った。「見なさい、この石塚を。そして見なさい、あなたと私の間に私が立てた、この石の柱を。'),
('JPN', '创世纪', 1, 31, 52, 'この石塚が証拠であり、この石の柱が証拠である。私は、この石塚を越えてあなたのところに行くことはない。あなたも、敵意をもって、この石塚やこの石の柱を越えて私のところに来てはならない。'),
('JPN', '创世纪', 1, 31, 53, 'どうか、アブラハムの神、ナホルの神、彼らの父祖の神が、われわれの間をさばかれるように。」ヤコブも、父イサクの恐れる方にかけて誓った。'),
('JPN', '创世纪', 1, 31, 54, 'ヤコブは山でいけにえを献げ、一族を食事に招いた。彼らは食事をして、山で一夜を明かした。'),
('JPN', '创世纪', 1, 31, 55, '翌朝早く、ラバンは孫と娘たちに口づけして、彼らを祝福した。それからラバンは去って、自分の所へ帰った。'),
('JPN', '创世纪', 1, 32, 1, 'さて、ヤコブが旅を続けていると、神の使いたちが彼に現れた。'),
('JPN', '创世纪', 1, 32, 2, 'ヤコブは彼らを見たとき、「ここは神の陣営だ」と言って、その場所の名をマハナイムと呼んだ。'),
('JPN', '创世纪', 1, 32, 3, 'ヤコブは、セイルの地、エドムの野にいる兄のエサウに、前もって使いを送った。'),
('JPN', '创世纪', 1, 32, 4, 'ヤコブは彼らに命じた。「私の主人エサウにこう伝えなさい。『あなた様のしもべヤコブがこう申しております。私はラバンのもとに寄留し、今に至るまでとどまっていました。'),
('JPN', '创世纪', 1, 32, 5, '私には牛、ろば、羊、それに男女の奴隷がおります。それで私の主人であるあなた様にお知らせして、ご好意を得ようと使いをお送りしました。』」'),
('JPN', '创世纪', 1, 32, 6, '使者は、ヤコブのもとに帰って来て言った。「兄上エサウ様のもとに行って参りました。あの方も、あなたを迎えにやって来られます。四百人があの方と一緒にいます。」'),
('JPN', '创世纪', 1, 32, 7, 'ヤコブは非常に恐れ、不安になった。それで彼は、一緒にいる人々や、羊や牛やらくだを二つの宿営に分けた。'),
('JPN', '创世纪', 1, 32, 8, '「たとえエサウが一つの宿営にやって来て、それを打っても、もう一つの宿営は逃れられるだろう」と考えたのである。'),
('JPN', '创世纪', 1, 32, 9, 'ヤコブは言った。「私の父アブラハムの神、私の父イサクの神よ。私に『あなたの地、あなたの生まれた地に帰れ。わたしはあなたを幸せにする』と言われた主よ。'),
('JPN', '创世纪', 1, 32, 10, '私は、あなたがこのしもべに与えてくださった、すべての恵みとまことを受けるに値しない者です。私は一本の杖しか持たないで、このヨルダン川を渡りましたが、今は、二つの宿営を持つまでになりました。'),
('JPN', '创世纪', 1, 32, 11, 'どうか、私の兄エサウの手から私を救い出してください。兄が来て、私を、また子どもたちとともにその母親たちまでも打ちはしないかと、私は恐れています。'),
('JPN', '创世纪', 1, 32, 12, 'あなたは、かつて言われました。『わたしは必ずあなたを幸せにし、あなたの子孫を、多くて数えきれない海の砂のようにする』と。」'),
('JPN', '创世纪', 1, 32, 13, 'その夜をそこで過ごしてから、ヤコブは自分が手に入れたものの中から、兄エサウへの贈り物にするものを選び出した。'),
('JPN', '创世纪', 1, 32, 14, '雌やぎ二百匹、雄やぎ二十匹、雌羊二百匹、雄羊二十匹、'),
('JPN', '创世纪', 1, 32, 15, '乳らくだ三十頭とその子、雌牛四十頭、雄牛十頭、雌ろば二十頭、雄ろば十頭。'),
('JPN', '创世纪', 1, 32, 16, '彼は、しもべたちの手にそれぞれ一群れずつを渡し、しもべたちに言った。「私の先を進め。群れと群れの間には距離をおけ。」'),
('JPN', '创世纪', 1, 32, 17, 'また、先頭の者に命じた。「もし私の兄エサウがあなたに会い、『あなたは、だれに属する者か。どこへ行くのか。あなたの前のこれらのものは、だれのものか』と尋ねたら、'),
('JPN', '创世纪', 1, 32, 18, '『これらは、あなた様のしもべヤコブのものでございます。ご主人のエサウ様に差し上げる贈り物でございます。ご覧ください。ヤコブもうしろにおります』と答えよ。」'),
('JPN', '创世纪', 1, 32, 19, '彼は第二の者にも、第三の者にも、群れ群れについて行くすべての者に命じた。「あなたがたがエサウに出会ったら、これと同じことを告げよ。'),
('JPN', '创世纪', 1, 32, 20, 'また、『ご覧ください。あなた様のしもべヤコブは、私どものうしろにおります』と言え。」ヤコブは、「自分の先に行く贈り物で彼をなだめ、その後で彼と顔を合わせよう。もしかすると、私を受け入れてくれるかもしれない」と思ったのである。'),
('JPN', '创世纪', 1, 32, 21, 'こうして贈り物は彼より先に渡って行ったが、彼自身は、その夜、宿営にとどまっていた。'),
('JPN', '创世纪', 1, 32, 22, 'その夜、彼は起き上がり、二人の妻と二人の女奴隷、そして十一人の子どもたちを連れ出し、ヤボクの渡し場を渡った。'),
('JPN', '创世纪', 1, 32, 23, '彼らを連れ出して川を渡らせ、また自分の所有するものも渡らせた。'),
('JPN', '创世纪', 1, 32, 24, 'ヤコブが一人だけ後に残ると、ある人が夜明けまで彼と格闘した。'),
('JPN', '创世纪', 1, 32, 25, 'その人はヤコブに勝てないのを見てとって、彼のももの関節を打った。ヤコブのももの関節は、その人と格闘しているうちに外れた。'),
('JPN', '创世纪', 1, 32, 26, 'すると、その人は言った。「わたしを去らせよ。夜が明けるから。」ヤコブは言った。「私はあなたを去らせません。私を祝福してくださらなければ。」'),
('JPN', '创世纪', 1, 32, 27, 'その人は言った。「あなたの名は何というのか。」彼は言った。「ヤコブです。」'),
('JPN', '创世纪', 1, 32, 28, 'その人は言った。「あなたの名は、もうヤコブとは呼ばれない。イスラエルだ。あなたが神と、また人と戦って、勝ったからだ。」'),
('JPN', '创世纪', 1, 32, 29, 'ヤコブは願って言った。「どうか、あなたの名を教えてください。」すると、その人は「いったい、なぜ、わたしの名を尋ねるのか」と言って、その場で彼を祝福した。'),
('JPN', '创世纪', 1, 32, 30, 'そこでヤコブは、その場所の名をペヌエルと呼んだ。「私は顔と顔を合わせて神を見たのに、私のいのちは救われた」という意味である。'),
('JPN', '创世纪', 1, 32, 31, '彼がペヌエルを通り過ぎたころ、太陽は彼の上に昇ったが、彼はそのもものために足を引きずっていた。'),
('JPN', '创世纪', 1, 32, 32, 'こういうわけで、イスラエルの人々は今日まで、ももの関節の上の、腰の筋を食べない。ヤコブが、ももの関節、腰の筋を打たれたからである。'),
('JPN', '创世纪', 1, 33, 1, 'ヤコブが目を上げて見ると、見よ、エサウがやって来た。四百人の者が一緒であった。そこで、ヤコブは子どもたちを、レアとラケルと二人の女奴隷の群れに分け、'),
('JPN', '创世纪', 1, 33, 2, '女奴隷たちとその子どもたちを先頭に、レアとその子どもたちをその後に、ラケルとヨセフを最後に置いた。'),
('JPN', '创世纪', 1, 33, 3, 'ヤコブは自ら彼らの先に立って進んだ。彼は兄に近づくまで、七回地にひれ伏した。'),
('JPN', '创世纪', 1, 33, 4, 'エサウは迎えに走って来て、彼を抱きしめ、首に抱きついて口づけし、二人は泣いた。'),
('JPN', '创世纪', 1, 33, 5, 'エサウは目を上げ、女たちや子どもたちを見て、「この人たちは、あなたの何なのか」と尋ねた。ヤコブは、「神があなた様のしもべに恵んでくださった子どもたちです」と答えた。'),
('JPN', '创世纪', 1, 33, 6, 'すると、女奴隷とその子どもたちが進み出て、ひれ伏した。'),
('JPN', '创世纪', 1, 33, 7, '次に、レアも、その子どもたちと進み出て、ひれ伏した。最後に、ヨセフとラケルが進み出て、ひれ伏した。'),
('JPN', '创世纪', 1, 33, 8, 'するとエサウは、「私が出会ったあの一群すべては、いったい何のためのものか」と尋ねた。ヤコブは「あなた様のご好意を得るためのものです」と答えた。'),
('JPN', '创世纪', 1, 33, 9, 'エサウは、「私には十分ある。弟よ、あなたのものは、あなたのものにしておきなさい」と言った。'),
('JPN', '创世纪', 1, 33, 10, 'ヤコブは答えた。「いいえ。もしお気に召すなら、どうか私の手から贈り物をお受け取りください。私は兄上のお顔を見て、神の御顔を見ているようです。兄上は私を喜んでくださいましたから。'),
('JPN', '创世纪', 1, 33, 11, 'どうか、兄上のために持参した、この祝いの品をお受け取りください。神が私を恵んでくださったので、私はすべてのものを持っていますから。」ヤコブがしきりに勧めたので、エサウは受け取った。'),
('JPN', '创世纪', 1, 33, 12, 'エサウが、「さあ、旅を続けて行こう。私があなたのすぐ前を行くから」と言うと、'),
('JPN', '创世纪', 1, 33, 13, 'ヤコブは彼に言った。「あなた様もご存じのように、子どもたちは弱く、乳を飲ませている羊や牛は私が世話をしています。一日でも、ひどく追い立てると、この群れはすべて死んでしまいます。'),
('JPN', '创世纪', 1, 33, 14, 'あなた様は、しもべより先にお進みください。私は、前を行く家畜や子どもたちの歩みに合わせて、ゆっくり旅を続け、あなた様のもと、セイルへ参ります。」'),
('JPN', '创世纪', 1, 33, 15, 'それで、エサウは言った。「では、私と一緒にいる者の何人かを、あなたのもとに残しておくことにしよう。」ヤコブは言った。「とんでもないことです。私はご主人様のご好意を十分に受けております。」'),
('JPN', '创世纪', 1, 33, 16, 'エサウは、その日、セイルへ帰って行った。'),
('JPN', '创世纪', 1, 33, 17, '一方、ヤコブはスコテへ移動し、そこで自分のために家を建て、家畜のためには小屋を作った。それゆえ、その場所の名はスコテと呼ばれた。'),
('JPN', '创世纪', 1, 33, 18, 'こうしてヤコブは、パダン・アラムからの帰途、カナンの地にあるシェケムの町に無事に着き、その町の手前で宿営した。'),
('JPN', '创世纪', 1, 33, 19, 'そして、天幕を張った野の一画を、シェケムの父ハモルの息子たちの手から百ケシタで買い取った。'),
('JPN', '创世纪', 1, 33, 20, '彼はそこに祭壇を築き、それをエル・エロヘ・イスラエルと呼んだ。'),
('JPN', '创世纪', 1, 34, 1, 'レアがヤコブに産んだ娘ディナは、その土地の娘たちを訪ねようと出かけて行った。'),
('JPN', '创世纪', 1, 34, 2, 'すると、その土地の族長であるヒビ人ハモルの子シェケムが彼女を見て、これを捕らえ、これと寝て辱めた。'),
('JPN', '创世纪', 1, 34, 3, '彼はヤコブの娘ディナに心を奪われ、この若い娘を愛し、彼女に優しく語りかけた。'),
('JPN', '创世纪', 1, 34, 4, 'シェケムは父のハモルに言った。「この娘を私の妻にしてください。」'),
('JPN', '创世纪', 1, 34, 5, 'ヤコブは、シェケムが自分の娘ディナを汚したことを聞いた。息子たちは、そのとき、家畜を連れて野にいた。それでヤコブは、彼らが帰って来るまで黙っていた。'),
('JPN', '创世纪', 1, 34, 6, 'シェケムの父ハモルは、ヤコブと話し合うためにやって来た。'),
('JPN', '创世纪', 1, 34, 7, 'ヤコブの息子たちは野から帰って来て、このことを聞いた。息子たちは心を痛め、激しく怒った。シェケムがヤコブの娘と寝て、イスラエルの中で恥辱となることを行ったからである。このようなことは、してはならないことである。'),
('JPN', '创世纪', 1, 34, 8, 'ハモルは彼らに語りかけた。「私の息子シェケムは、心からあなたがたの娘さんを恋い慕っています。どうか娘さんを息子の嫁にしてください。'),
('JPN', '创世纪', 1, 34, 9, '私たちは互いに姻戚関係を結びましょう。あなたがたの娘さんを私たちに下さり、私たちの娘をあなたがたが迎えてください。'),
('JPN', '创世纪', 1, 34, 10, 'そうして私たちとともに住んでください。この土地は、あなたがたの前に広がっています。ここに住み、自由に行き来し、ここに土地を得てください。」'),
('JPN', '创世纪', 1, 34, 11, 'シェケムは彼女の父や兄弟たちに言った。「皆さんのご好意を得られるのなら、おっしゃる物を何でも差し上げます。'),
('JPN', '创世纪', 1, 34, 12, 'どんなに高い花嫁料や贈り物であっても、私にお求めください。おっしゃるとおりに差し上げます。ですから、どうか、あの人を私の妻に下さい。」'),
('JPN', '创世纪', 1, 34, 13, 'ヤコブの息子たちは、シェケムが自分たちの妹ディナを汚したので、シェケムとその父ハモルをだまそうとして、'),
('JPN', '创世纪', 1, 34, 14, '答えた。「割礼を受けていない者に私たちの妹をやるような、そんなことは、私たちにはできません。それは、私たちにとって恥辱となることですから。'),
('JPN', '创世纪', 1, 34, 15, 'ただし、次の条件でなら同意しましょう。もし、あなたがたの男たちがみな、割礼を受けて、私たちと同じようになるなら、'),
('JPN', '创世纪', 1, 34, 16, '私たちの娘たちをあなたがたに嫁がせ、あなたがたの娘たちを妻に迎えましょう。そうして私たちはともに住み、一つの民となりましょう。'),
('JPN', '创世纪', 1, 34, 17, 'しかし、もし、あなたがたが私たちの言うことを聞かず、割礼を受けないなら、私たちは娘を連れてここを去ります。」'),
('JPN', '创世纪', 1, 34, 18, '彼らの言ったことは、ハモルと、ハモルの子シェケムの心にかなった。'),
('JPN', '创世纪', 1, 34, 19, 'この若者は、ためらわずにそれを実行した。彼はヤコブの娘を愛していたからである。彼は父の家のだれよりも敬われていた。'),
('JPN', '创世纪', 1, 34, 20, 'ハモルとその子シェケムは自分たちの町の門に行き、町の人々に告げた。'),
('JPN', '创世纪', 1, 34, 21, '「あの人たちは私たちに友好的だ。あの人たちをこの地に住まわせ、この地を自由に行き来させよう。この地は、彼らが来ても十分広いのだから。私たちは彼らの娘たちを妻に迎え、私たちの娘たちを彼らに嫁がせよう。'),
('JPN', '创世纪', 1, 34, 22, '次の条件でなら、あの人たちは、私たちとともに住んで一つの民となることに同意すると言うのだ。それは、彼らが割礼を受けているように、私たちのすべての男たちが割礼を受けることだ。'),
('JPN', '创世纪', 1, 34, 23, 'そうすれば、彼らの群れや財産、それにすべての彼らの家畜も、私たちのものになるではないか。さあ、彼らに同意しよう。そうすれば、彼らは私たちとともに住むことになる。」'),
('JPN', '创世纪', 1, 34, 24, 'その町の門に出入りする者はみな、ハモルとその子シェケムの言うことを聞き入れ、その町の門に出入りする男たちはみな割礼を受けた。'),
('JPN', '创世纪', 1, 34, 25, '三日目になって、彼らの傷が痛んでいるとき、ヤコブの二人の息子、ディナの兄シメオンとレビが、それぞれ剣を取って難なくその町を襲い、すべての男たちを殺した。'),
('JPN', '创世纪', 1, 34, 26, '彼らはハモルとその子シェケムを剣の刃で殺し、シェケムの家からディナを連れ出した。'),
('JPN', '创世纪', 1, 34, 27, 'ヤコブの息子たちは、刺し殺された者のところに来て、その町を略奪した。自分たちの妹が汚されたからである。'),
('JPN', '创世纪', 1, 34, 28, '彼らは、その人たちの羊や牛やろば、それに町にあるもの、野にあるものを奪い、'),
('JPN', '创世纪', 1, 34, 29, 'その人たちの全財産、幼子、妻たち、家にあるすべてのものを捕虜にしたり略奪したりした。'),
('JPN', '创世纪', 1, 34, 30, 'それで、ヤコブはシメオンとレビに言った。「あなたがたは私に困ったことをして、私をこの地の住民カナン人とペリジ人に憎まれるようにしてしまった。私は数では劣っている。彼らが一緒に集まって私を攻め、私を打つなら、私も家の者も根絶やしにされてしまうだろう。」'),
('JPN', '创世纪', 1, 34, 31, '彼らは言った。「私たちの妹が遊女のように扱われてもよいのですか。」'),
('JPN', '创世纪', 1, 35, 1, '神はヤコブに仰せられた。「立って、ベテルに上り、そこに住みなさい。そしてそこに、あなたが兄エサウから逃れたとき、あなたに現れた神のために祭壇を築きなさい。」'),
('JPN', '创世纪', 1, 35, 2, 'それで、ヤコブは自分の家族と、自分と一緒にいるすべての者に言った。「あなたがたの中にある異国の神々を取り除き、身をきよめ、衣を着替えなさい。'),
('JPN', '创世纪', 1, 35, 3, '私たちは立って、ベテルに上って行こう。私はそこに、苦難の日に私に答え、私が歩んだ道でともにいてくださった神に、祭壇を築こう。」'),
('JPN', '创世纪', 1, 35, 4, '彼らは、手にしていたすべての異国の神々と、耳につけていた耳輪をヤコブに渡した。ヤコブはそれらを、シェケムの近くにある樫の木の下に埋めた。'),
('JPN', '创世纪', 1, 35, 5, '彼らが旅立つと、神からの恐怖が周りの町々に下ったので、だれもヤコブの息子たちの後を追わなかった。'),
('JPN', '创世纪', 1, 35, 6, 'ヤコブは、カナンの地にあるルズ、すなわちベテルに来た。彼とともにいた人たちもみな一緒であった。'),
('JPN', '创世纪', 1, 35, 7, '彼はそこに祭壇を築き、その場所をエル・ベテルと呼んだ。それは、彼が兄から逃れたとき、神がそこで彼に現れたからである。'),
('JPN', '创世纪', 1, 35, 8, 'リベカの乳母デボラが死に、ベテルの下手にある樫の木の下に葬られた。それで、その木の名はアロン・バクテと呼ばれた。'),
('JPN', '创世纪', 1, 35, 9, 'ヤコブがパダン・アラムから帰って来たとき、神は再び彼に現れ、彼を祝福された。'),
('JPN', '创世纪', 1, 35, 10, '神は彼に仰せられた。「あなたの名はヤコブである。しかし、あなたの名は、もうヤコブとは呼ばれない。イスラエルが、あなたの名となるからだ。」こうして神は彼の名をイスラエルと呼ばれた。'),
('JPN', '创世纪', 1, 35, 11, '神はまた、彼に仰せられた。「わたしは全能の神である。生めよ。増えよ。一つの国民が、国民の群れが、あなたから出る。王たちがあなたの腰から生まれ出る。'),
('JPN', '创世纪', 1, 35, 12, 'わたしは、アブラハムとイサクに与えた地を、あなたに与える。あなたの後の子孫にも、その地を与えよう。」'),
('JPN', '创世纪', 1, 35, 13, '神は彼に語ったその場所で、彼を離れて上って行かれた。'),
('JPN', '创世纪', 1, 35, 14, 'ヤコブは、神が自分に語られた場所に、柱を、石の柱を立て、その上に注ぎのぶどう酒を注ぎ、さらにその上に油を注いだ。'),
('JPN', '创世纪', 1, 35, 15, 'ヤコブは、神が自分と語られたその場所をベテルと名づけた。'),
('JPN', '创世纪', 1, 35, 16, '彼らはベテルから旅立った。エフラテに着くまでまだかなりの道のりがあるところで、ラケルは出産したが、難産であった。'),
('JPN', '创世纪', 1, 35, 17, '彼女が大変な難産で苦しんでいたとき、助産婦は彼女に、「恐れることはありません。今度も男のお子さんです」と告げた。'),
('JPN', '创世纪', 1, 35, 18, '彼女が死に臨み、たましいが離れ去ろうとしたとき、その子の名をベン・オニと呼んだ。しかし、その子の父はベニヤミンと名づけた。'),
('JPN', '创世纪', 1, 35, 19, 'こうしてラケルは死んだ。彼女はエフラテ、すなわちベツレヘムへの道で葬られた。'),
('JPN', '创世纪', 1, 35, 20, 'ヤコブは彼女の墓の上に石の柱を立てた。それはラケルの墓の石の柱として今日に至っている。'),
('JPN', '创世纪', 1, 35, 21, 'イスラエルは旅を続け、ミグダル・エデルを過ぎたところに天幕を張った。'),
('JPN', '创世纪', 1, 35, 22, 'イスラエルがその地にとどまっていたころ、ルベンが父の側女ビルハのところに行って、彼女と寝た。イスラエルはこのことを聞いた。ヤコブの子は十二人であった。'),
('JPN', '创世纪', 1, 35, 23, 'レアの子はヤコブの長子ルベン、シメオン、レビ、ユダ、イッサカル、ゼブルン。'),
('JPN', '创世纪', 1, 35, 24, 'ラケルの子はヨセフとベニヤミン。'),
('JPN', '创世纪', 1, 35, 25, 'ラケルの女奴隷ビルハの子はダンとナフタリ。'),
('JPN', '创世纪', 1, 35, 26, 'レアの女奴隷ジルパの子はガドとアシェル。これらはパダン・アラムで生まれたヤコブの子である。'),
('JPN', '创世纪', 1, 35, 27, 'ヤコブは、キルヤテ・アルバ、すなわちヘブロンのマムレにいる父イサクのところに着いた。そこは、アブラハムとイサクがかつて寄留していたところである。'),
('JPN', '创世纪', 1, 35, 28, 'イサクの生涯は百八十年であった。'),
('JPN', '创世纪', 1, 35, 29, 'イサクは年老いて満ち足り、息絶えて死に、自分の民に加えられた。息子のエサウとヤコブが彼を葬った。'),
('JPN', '创世纪', 1, 36, 1, 'これはエサウ、すなわちエドムの歴史である。'),
('JPN', '创世纪', 1, 36, 2, 'エサウはカナンの女の中から妻を迎えた。すなわち、ヒッタイト人エロンの娘アダと、ヒビ人ツィブオンの娘アナの娘オホリバマ、'),
('JPN', '创世纪', 1, 36, 3, 'それにイシュマエルの娘でネバヨテの妹バセマテである。'),
('JPN', '创世纪', 1, 36, 4, 'アダはエサウにエリファズを産み、バセマテはレウエルを産み、'),
('JPN', '创世纪', 1, 36, 5, 'オホリバマはエウシュ、ヤラム、コラを産んだ。これらはカナンの地で生まれたエサウの子である。'),
('JPN', '创世纪', 1, 36, 6, 'エサウは、その妻たち、息子と娘たち、その家のすべての者、その群れとすべての家畜、カナンの地で得た全財産を携え、弟ヤコブから離れて別の地へ行った。'),
('JPN', '创世纪', 1, 36, 7, '一緒に住むには所有する物が多すぎて、彼らの群れのために寄留していた地は、彼らを支えることができなかったのである。'),
('JPN', '创世纪', 1, 36, 8, 'それでエサウはセイルの山地に住んだ。エサウとは、エドムのことである。'),
('JPN', '创世纪', 1, 36, 9, 'これは、セイルの山地にいたエドム人の先祖エサウの系図である。'),
('JPN', '创世纪', 1, 36, 10, 'エサウの子の名は次のとおり。エサウの妻アダの子エリファズ、エサウの妻バセマテの子レウエル。'),
('JPN', '创世纪', 1, 36, 11, 'エリファズの子はテマン、オマル、ツェフォ、ガタム、ケナズである。'),
('JPN', '创世纪', 1, 36, 12, 'ティムナはエサウの子エリファズの側女で、エリファズにアマレクを産んだ。これらはエサウの妻アダの子である。'),
('JPN', '创世纪', 1, 36, 13, 'レウエルの子はナハテ、ゼラフ、シャンマ、ミザで、これらはエサウの妻バセマテの子であった。'),
('JPN', '创世纪', 1, 36, 14, 'ツィブオンの娘アナの娘である、エサウの妻オホリバマの子は次のとおり。オホリバマはエサウに、エウシュとヤラムとコラを産んだ。'),
('JPN', '创世纪', 1, 36, 15, 'エサウの子で首長は次のとおり。エサウの長子エリファズの子では、首長テマン、首長オマル、首長ツェフォ、首長ケナズ、'),
('JPN', '创世纪', 1, 36, 16, '首長コラ、首長ガタム、首長アマレクである。これらはエドムの地にいるエリファズから出た首長で、アダの子である。'),
('JPN', '创世纪', 1, 36, 17, 'エサウの子レウエルの子では、次のとおり。首長ナハテ、首長ゼラフ、首長シャンマ、首長ミザ。これらはエドムの地にいるレウエルから出た首長で、エサウの妻バセマテの子である。'),
('JPN', '创世纪', 1, 36, 18, 'エサウの妻オホリバマの子では、次のとおり。首長エウシュ、首長ヤラム、首長コラである。これらは、エサウの妻で、アナの娘であるオホリバマから出た首長である。'),
('JPN', '创世纪', 1, 36, 19, 'これらはエサウ、すなわちエドムの子で、彼らの首長である。'),
('JPN', '创世纪', 1, 36, 20, 'この地の住民フリ人セイルの子は次のとおり。ロタン、ショバル、ツィブオン、アナ、'),
('JPN', '创世纪', 1, 36, 21, 'ディション、エツェル、ディシャンで、これらはエドムの地にいるセイルの子フリ人の首長である。'),
('JPN', '创世纪', 1, 36, 22, 'ロタンの子はホリ、ヘマム。ロタンの妹はティムナであった。'),
('JPN', '创世纪', 1, 36, 23, 'ショバルの子は次のとおり。アルワン、マナハテ、エバル、シェフォ、オナム。'),
('JPN', '创世纪', 1, 36, 24, 'ツィブオンの子は次のとおり。アヤ、アナ。これは、父ツィブオンのろばを飼っていたとき、荒野で温泉を見つけたアナである。'),
('JPN', '创世纪', 1, 36, 25, 'アナの子は次のとおり。ディションと、アナの娘オホリバマ。'),
('JPN', '创世纪', 1, 36, 26, 'ディションの子は次のとおり。ヘムダン、エシュバン、イテラン、ケラン。'),
('JPN', '创世纪', 1, 36, 27, 'エツェルの子は次のとおり。ビルハン、ザアワン、アカン。'),
('JPN', '创世纪', 1, 36, 28, 'ディシャンの子は次のとおり。ウツ、アラン。'),
('JPN', '创世纪', 1, 36, 29, 'フリ人の首長は次のとおり。首長ロタン、首長ショバル、首長ツィブオン、首長アナ、'),
('JPN', '创世纪', 1, 36, 30, '首長ディション、首長エツェル、首長ディシャン。これらは、セイルの地での首長ごとに挙げた、フリ人の首長である。'),
('JPN', '创世纪', 1, 36, 31, 'イスラエルの子らを王が治める以前、エドムの地で王として治めた者は次のとおりである。'),
('JPN', '创世纪', 1, 36, 32, 'ベオルの子ベラはエドムで治めた。彼の町の名はディンハバであった。'),
('JPN', '创世纪', 1, 36, 33, 'ベラが死ぬと、ボツラ出身のゼラフの子ヨバブが代わりに王となった。'),
('JPN', '创世纪', 1, 36, 34, 'ヨバブが死ぬと、テマン人の地から出たフシャムが代わりに王となった。'),
('JPN', '创世纪', 1, 36, 35, 'フシャムが死ぬと、モアブの野でミディアン人を打ち破った、ベダデの子ハダドが代わりに王となった。その町の名はアウィテであった。'),
('JPN', '创世纪', 1, 36, 36, 'ハダドが死ぬと、マスレカ出身のサムラが代わりに王となった。'),
('JPN', '创世纪', 1, 36, 37, 'サムラが死ぬと、レホボテ・ハ・ナハル出身のシャウルが代わりに王となった。'),
('JPN', '创世纪', 1, 36, 38, 'シャウルが死ぬと、アクボルの子バアル・ハナンが代わりに王となった。'),
('JPN', '创世纪', 1, 36, 39, 'アクボルの子バアル・ハナンが死ぬと、ハダルが代わりに王となった。彼の町の名はパウであった。妻の名はメヘタブエルで、メ・ザハブの娘マテレデの娘であった。'),
('JPN', '创世纪', 1, 36, 40, 'エサウから出た首長の名は、その氏族とその場所ごとにその名を挙げると次のとおり。首長ティムナ、首長アルワ、首長エテテ、'),
('JPN', '创世纪', 1, 36, 41, '首長オホリバマ、首長エラ、首長ピノン、'),
('JPN', '创世纪', 1, 36, 42, '首長ケナズ、首長テマン、首長ミブツァル、'),
('JPN', '创世纪', 1, 36, 43, '首長マグディエル、首長イラム。これらはエドムの首長であり、所有地で住んでいた場所ごとに挙げたものである。エドム人の先祖はエサウである。'),
('JPN', '创世纪', 1, 37, 1, 'さて、ヤコブは父の寄留の地、カナンの地に住んでいた。'),
('JPN', '创世纪', 1, 37, 2, 'これはヤコブの歴史である。ヨセフは十七歳のとき、兄たちとともに羊の群れを飼っていた。彼はまだ手伝いで、父の妻ビルハの子らやジルパの子らとともにいた。ヨセフは彼らの悪いうわさを彼らの父に告げた。'),
('JPN', '创世纪', 1, 37, 3, 'イスラエルは、息子たちのだれよりもヨセフを愛していた。ヨセフが年寄り子だったからである。それで彼はヨセフに、あや織りの長服を作ってやっていた。'),
('JPN', '创世纪', 1, 37, 4, 'ヨセフの兄たちは、父が兄弟たちのだれよりも彼を愛しているのを見て、彼を憎み、穏やかに話すことができなかった。'),
('JPN', '创世纪', 1, 37, 5, 'さて、ヨセフは夢を見て、それを兄たちに告げた。すると彼らは、ますます彼を憎むようになった。'),
('JPN', '创世纪', 1, 37, 6, 'ヨセフは彼らに言った。「私が見たこの夢について聞いてください。'),
('JPN', '创世纪', 1, 37, 7, '見ると、私たちは畑で束を作っていました。すると突然、私の束が起き上がり、まっすぐに立ちました。そしてなんと、兄さんたちの束が周りに来て、私の束を伏し拝んだのです。」'),
('JPN', '创世纪', 1, 37, 8, '兄たちは彼に言った。「おまえが私たちを治める王になるというのか。私たちを支配するというのか。」彼らは、夢や彼のことばのことで、ますます彼を憎むようになった。'),
('JPN', '创世纪', 1, 37, 9, '再びヨセフは別の夢を見て、それを兄たちに話した。彼は、「また夢を見ました。見ると、太陽と月と十一の星が私を伏し拝んでいました」と言った。'),
('JPN', '创世纪', 1, 37, 10, 'ヨセフが父や兄たちに話すと、父は彼を叱って言った。「いったい何なのだ、おまえの見た夢は。私や、おまえの母さん、兄さんたちが、おまえのところに進み出て、地に伏しておまえを拝むというのか。」'),
('JPN', '创世纪', 1, 37, 11, '兄たちは彼をねたんだが、父はこのことを心にとどめていた。'),
('JPN', '创世纪', 1, 37, 12, 'その後、兄たちは、シェケムで父の羊の群れを世話するために出かけて行った。'),
('JPN', '创世纪', 1, 37, 13, 'イスラエルはヨセフに言った。「おまえの兄さんたちは、シェケムで群れの世話をしている。さあ、兄さんたちのところに使いに行ってもらいたい。」ヨセフは答えた。「はい、参ります。」'),
('JPN', '创世纪', 1, 37, 14, '父は言った。「さあ、行って、兄さんたちが無事かどうか、羊の群れが無事かどうかを見て、その様子を私に知らせておくれ。」こうして彼をヘブロンの谷から使いに送った。それで彼はシェケムにやって来た。'),
('JPN', '创世纪', 1, 37, 15, '彼が野をさまよっていると、一人の人が彼を見かけた。その人は「何を捜しているのですか」と尋ねた。'),
('JPN', '创世纪', 1, 37, 16, 'ヨセフは言った。「兄たちを捜しています。どこで群れの世話をしているか、どうか教えてください。」'),
('JPN', '创世纪', 1, 37, 17, 'すると、その人は言った。「ここからは、もう行ってしまいました。私は、あの人たちが『さあ、ドタンの方に行こう』と言っているのを聞きました。」そこでヨセフは兄たちの後を追って行き、ドタンで彼らを見つけた。'),
('JPN', '创世纪', 1, 37, 18, '兄たちは遠くにヨセフを見て、彼が近くに来る前に、彼を殺そうと企んだ。'),
('JPN', '创世纪', 1, 37, 19, '彼らは互いに話し合った。「見ろ。あの夢見る者がやって来た。'),
('JPN', '创世纪', 1, 37, 20, 'さあ、今こそあいつを殺し、どこかの穴の一つにでも投げ込んでしまおう。そうして、狂暴な獣が食い殺したと言おう。あいつの夢がどうなるかを見ようではないか。」'),
('JPN', '创世纪', 1, 37, 21, 'しかし、ルベンはこれを聞き、彼らの手から彼を救い出そうとして、「あの子を打ち殺すのはやめよう」と言った。'),
('JPN', '创世纪', 1, 37, 22, 'また、ルベンは言った。「弟の血を流してはいけない。弟を荒野の、この穴に投げ込みなさい。手を下してはいけない。」これは、ヨセフを彼らの手から救い出し、父のもとに帰すためであった。'),
('JPN', '创世纪', 1, 37, 23, 'ヨセフが兄たちのところに来たとき、彼らは、ヨセフの長服、彼が着ていたあや織りの長服をはぎ取り、'),
('JPN', '创世纪', 1, 37, 24, '彼を捕らえて、穴の中に投げ込んだ。その穴は空で、中には水がなかった。'),
('JPN', '创世纪', 1, 37, 25, 'それから、彼らは座って食事をした。彼らが目を上げて見ると、そこに、イシュマエル人の隊商がギルアデからやって来ていた。彼らは、らくだに樹膠と乳香と没薬を背負わせて、エジプトへ下って行くところであった。'),
('JPN', '创世纪', 1, 37, 26, 'すると、ユダが兄弟たちに言った。「弟を殺し、その血を隠しても、何の得になるだろう。'),
('JPN', '创世纪', 1, 37, 27, 'さあ、ヨセフをイシュマエル人に売ろう。われわれが手をかけてはいけない。あいつは、われわれの弟、われわれの肉親なのだから。」兄弟たちは彼の言うことを聞き入れた。'),
('JPN', '创世纪', 1, 37, 28, 'そのとき、ミディアン人の商人たちが通りかかった。それで兄弟たちはヨセフを穴から引き上げ、銀二十枚でヨセフをイシュマエル人に売った。イシュマエル人はヨセフをエジプトへ連れて行った。'),
('JPN', '创世纪', 1, 37, 29, 'さて、ルベンが穴のところに帰って来ると、なんと、ヨセフは穴の中にいなかった。ルベンは自分の衣を引き裂き、'),
('JPN', '创世纪', 1, 37, 30, '兄弟たちのところに戻って来て言った。「あの子がいない。ああ私は、私は、どこへ行けばよいのか。」'),
('JPN', '创世纪', 1, 37, 31, '彼らはヨセフの長服を取り、雄やぎを屠って、長服をその血に浸した。'),
('JPN', '创世纪', 1, 37, 32, 'そして、そのあや織りの長服を父のところに送り届けて、言った。「これを見つけました。あなたの子の長服かどうか、お調べください。」'),
('JPN', '创世纪', 1, 37, 33, '父はそれを調べて言った。「わが子の長服だ。悪い獣が食い殺したのだ。ヨセフは確かに、かみ裂かれたのだ。」'),
('JPN', '创世纪', 1, 37, 34, 'ヤコブは自分の衣を引き裂き、粗布を腰にまとい、何日も、その子のために嘆き悲しんだ。'),
('JPN', '创世纪', 1, 37, 35, '彼の息子、娘たちがみな来て父を慰めたが、彼は慰められるのを拒んで言った。「私は嘆き悲しみながら、わが子のところに、よみに下って行きたい。」こうして父はヨセフのために泣いた。'),
('JPN', '创世纪', 1, 37, 36, 'あのミディアン人たちは、エジプトでファラオの廷臣、侍従長ポティファルにヨセフを売った。'),
('JPN', '创世纪', 1, 38, 1, 'そのころのことであった。ユダは兄弟たちから離れて下って行き、名をヒラというアドラム人の近くで天幕を張った。'),
('JPN', '创世纪', 1, 38, 2, 'そこでユダは、カナン人で名をシュアという人の娘を見そめて妻にし、彼女のところに入った。'),
('JPN', '创世纪', 1, 38, 3, '彼女は身ごもって男の子を産んだ。ユダはその子をエルと名づけた。'),
('JPN', '创世纪', 1, 38, 4, '彼女はまた身ごもって男の子を産み、その子をオナンと名づけた。'),
('JPN', '创世纪', 1, 38, 5, '彼女はまた男の子を産み、その子をシェラと名づけた。彼女がシェラを産んだとき、ユダはケジブにいた。'),
('JPN', '创世纪', 1, 38, 6, 'ユダはその長子エルに妻を迎えた。名前はタマルといった。'),
('JPN', '创世纪', 1, 38, 7, 'しかし、ユダの長子エルは主の目に悪しき者であったので、主は彼を殺された。'),
('JPN', '创世纪', 1, 38, 8, 'ユダはオナンに言った。「兄嫁のところに入って、義弟としての務めを果たしなさい。そして、おまえの兄のために子孫を残すようにしなさい。」'),
('JPN', '创世纪', 1, 38, 9, 'しかしオナンは、生まれる子が自分のものとならないのを知っていたので、兄に子孫を与えないように、兄嫁のところに入ると地に流していた。'),
('JPN', '创世纪', 1, 38, 10, '彼のしたことは主の目に悪しきことであったので、主は彼も殺された。'),
('JPN', '创世纪', 1, 38, 11, 'ユダは嫁のタマルに、「わが子シェラが成人するまで、あなたの父の家でやもめのまま暮らしなさい」と言った。シェラもまた、兄たちのように死ぬといけないと思ったからである。タマルは父の家に行き、そこで暮らした。'),
('JPN', '创世纪', 1, 38, 12, 'かなり日がたって、ユダの妻、すなわちシュアの娘が死んだ。その喪が明けたとき、ユダは、羊の群れの毛を刈る者たちのところ、ティムナへ上って行った。友人でアドラム人のヒラも一緒であった。'),
('JPN', '创世纪', 1, 38, 13, 'そのときタマルに、「ご覧なさい。あなたのしゅうとが羊の群れの毛を刈るために、ティムナに上って来ます」という知らせがあった。'),
('JPN', '创世纪', 1, 38, 14, 'それでタマルは、やもめの服を脱ぎ、ベールをかぶり、着替えをして、ティムナへの道にあるエナイムの入り口に座った。シェラが成人したのに、自分がその妻にされないことが分かったからである。'),
('JPN', '创世纪', 1, 38, 15, 'ユダは彼女を見て、彼女が顔をおおっていたので遊女だと思い、'),
('JPN', '创世纪', 1, 38, 16, '道端の彼女のところに行き、「さあ、あなたのところに入らせてほしい」と言った。彼は、その女が嫁だとは知らなかったのである。彼女は「私のところにお入りになれば、何を私に下さいますか」と言った。'),
('JPN', '创世纪', 1, 38, 17, '彼が「群れの中から子やぎを送ろう」と言うと、彼女は「それを送ってくださるまで、何か、おしるしを下されば」と言った。'),
('JPN', '创世纪', 1, 38, 18, '彼が「しるしとして何をやろうか」と言うと、「あなたの印章とひもと、あなたが手にしている杖を」と答えた。そこで彼はそれを与えて、彼女のところに入った。こうしてタマルはユダのために子を宿した。'),
('JPN', '创世纪', 1, 38, 19, '彼女は立ち去って、そのベールを外し、やもめの服を着た。'),
('JPN', '创世纪', 1, 38, 20, 'ユダは、その女の手からしるしを取り戻そうと、アドラム人の友人に託して子やぎを送ったが、彼はその女を見つけることができなかった。'),
('JPN', '创世纪', 1, 38, 21, 'その友人がその土地の人々に「エナイムの道端にいた娼婦はどこにいますか」と尋ねると、彼らは「ここに娼婦がいたことはありません」と答えた。'),
('JPN', '创世纪', 1, 38, 22, '彼はユダのところに戻って来て言った。「あの女は見つかりませんでした。あの土地の人たちも、ここに娼婦がいたことはない、と言いました。」'),
('JPN', '创世纪', 1, 38, 23, 'ユダは言った。「われわれが笑いぐさにならないように、あの女にそのまま取らせておこう。私はこの子やぎを送ったけれども、あなたはあの女を見つけられなかったのだから。」'),
('JPN', '创世纪', 1, 38, 24, '三か月ほどして、ユダに、「あなたの嫁のタマルが姦淫をし、そのうえ、なんとその姦淫によって身ごもっています」と告げる者があった。そこでユダは言った。「あの女を引き出して、焼き殺せ。」'),
('JPN', '创世纪', 1, 38, 25, '彼女が引き出されたとき、彼女はしゅうとのところに人を送って、「この品々の持ち主によって、私は身ごもったのです」と言った。また彼女は言った。「これらの印章とひもと杖がだれのものか、お調べください。」'),
('JPN', '创世纪', 1, 38, 26, 'ユダはこれを調べて言った。「あの女は私よりも正しい。私が彼女をわが子シェラに与えなかったせいだ。」彼は二度と彼女を知ろうとはしなかった。'),
('JPN', '创世纪', 1, 38, 27, '彼女の出産の時になると、なんと、双子がその胎内にいた。'),
('JPN', '创世纪', 1, 38, 28, '出産の時、一人目が手を出したので、助産婦はそれをつかみ、その手に真っ赤な糸を結び付けて言った。「この子が最初に出て来ました。」'),
('JPN', '创世纪', 1, 38, 29, 'しかし、その子が手を引っ込めたとき、もう一人の兄弟が出て来た。それで彼女は「何という割り込みをするのですか」と言った。それで、その名はペレツと呼ばれた。'),
('JPN', '创世纪', 1, 38, 30, 'その後で、手に真っ赤な糸を付けた、もう一人の兄弟が出て来た。それで、その名はゼラフと呼ばれた。'),
('JPN', '创世纪', 1, 39, 1, '一方、ヨセフはエジプトへ連れて行かれた。ファラオの廷臣で侍従長のポティファルという一人のエジプト人が、ヨセフを連れ下ったイシュマエル人の手からヨセフを買い取った。'),
('JPN', '创世纪', 1, 39, 2, '主がヨセフとともにおられたので、彼は成功する者となり、そのエジプト人の主人の家に住んだ。'),
('JPN', '创世纪', 1, 39, 3, '彼の主人は、主が彼とともにおられ、主が彼のすることすべてを彼に成功させてくださるのを見た。'),
('JPN', '创世纪', 1, 39, 4, 'それでヨセフは主人の好意を得て、彼のそば近くで仕えることになった。主人は彼にその家を管理させ、自分の全財産を彼に委ねた。'),
('JPN', '创世纪', 1, 39, 5, '主人が彼にその家と全財産を管理させたときから、主はヨセフのゆえに、このエジプト人の家を祝福された。それで、主の祝福が、家や野にある全財産の上にあった。'),
('JPN', '创世纪', 1, 39, 6, '主人はヨセフの手に全財産を任せ、自分が食べる食物のこと以外は、何も気を使わなかった。しかもヨセフは体格も良く、顔だちも美しかった。'),
('JPN', '创世纪', 1, 39, 7, 'これらのことの後、主人の妻はヨセフに目をつけて、「一緒に寝ましょう」と言った。'),
('JPN', '创世纪', 1, 39, 8, 'しかし彼は拒んで、主人の妻に言った。「ご覧ください。ご主人は、家の中のことは何でも私に任せ、心配せずに全財産を私に委ねられました。'),
('JPN', '创世纪', 1, 39, 9, 'ご主人は、この家の中で私より大きな権威をふるおうとはせず、私がするどんなことも妨げておられません。ただし、あなたのことは別です。あなたがご主人の奥様だからです。どうして、そのような大きな悪事をして、神に対して罪を犯すことができるでしょうか。」'),
('JPN', '创世纪', 1, 39, 10, '彼女は毎日ヨセフに言い寄ったが、彼は聞き入れず、彼女のそばに寝ることも、一緒にいることもしなかった。'),
('JPN', '创世纪', 1, 39, 11, 'このようなある日のこと、彼が仕事をしようとして家に入ると、家の中には、家の者が一人もいなかった。'),
('JPN', '创世纪', 1, 39, 12, '彼女はヨセフの上着をつかんで、「一緒に寝ましょう」と言った。しかしヨセフはその上着を彼女の手に残し、彼女から逃れて外へ出た。'),
('JPN', '创世纪', 1, 39, 13, '彼が上着を彼女の手に残して外へ逃げたのを見ると、'),
('JPN', '创世纪', 1, 39, 14, '彼女は家の者たちを呼んで、こう言った。「見なさい。私たちに対していたずらをさせるために、主人はヘブル人を私たちのところに連れ込んだのです。あの男が私と寝ようとして入って来たので、私は大声をあげました。'),
('JPN', '创世纪', 1, 39, 15, '私が声をあげて叫んだのを聞いて、あの男は私のそばに上着を残して、外へ逃げて行きました。」'),
('JPN', '创世纪', 1, 39, 16, '彼女は、ヨセフの主人が家に帰って来るまで、その上着を自分のそばに置いておいた。'),
('JPN', '创世纪', 1, 39, 17, '彼女は主人に、このように告げた。「あなたが私たちのところに連れて来た、あのヘブル人の奴隷は、私にいたずらをしようとして私のところに入って来ました。'),
('JPN', '创世纪', 1, 39, 18, '私が声をあげて叫んだので、あの男は私のそばに上着を残して、外へ逃げました。」'),
('JPN', '创世纪', 1, 39, 19, '彼の主人は、「あなたの奴隷がこのようなことを私にしました」と告げた妻のことばを聞いて、怒りに燃えた。'),
('JPN', '创世纪', 1, 39, 20, 'ヨセフの主人は彼を捕らえ、王の囚人が監禁されている監獄に彼を入れた。こうして彼は監獄に置かれた。'),
('JPN', '创世纪', 1, 39, 21, 'しかし、主はヨセフとともにおられ、彼に恵みを施し、監獄の長の心にかなうようにされた。'),
('JPN', '创世纪', 1, 39, 22, '監獄の長は、その監獄にいるすべての囚人をヨセフの手に委ねた。ヨセフは、そこで行われるすべてのことを管理するようになった。'),
('JPN', '创世纪', 1, 39, 23, '監獄の長は、ヨセフの手に委ねたことには何も干渉しなかった。それは、主が彼とともにおられ、彼が何をしても、主がそれを成功させてくださったからである。'),
('JPN', '创世纪', 1, 40, 1, 'これらのことの後、エジプト王の献酌官と料理官が、その主君、エジプト王に対して過ちを犯した。'),
('JPN', '创世纪', 1, 40, 2, 'ファラオは、この献酌官長と料理官長の二人の廷臣に対して怒り、'),
('JPN', '创世纪', 1, 40, 3, '彼らを侍従長の家に拘留した。それは、ヨセフが監禁されているのと同じ監獄であった。'),
('JPN', '创世纪', 1, 40, 4, '侍従長がヨセフを彼らの付き人にしたので、ヨセフは彼らの世話をした。彼らは、しばらく拘留されていた。'),
('JPN', '创世纪', 1, 40, 5, 'さて、監獄に監禁されていた、エジプト王の献酌官と料理官は、二人とも同じ夜にそれぞれ夢を見た。その夢にはそれぞれ意味があった。'),
('JPN', '创世纪', 1, 40, 6, '朝、ヨセフが彼らのところに来て、見ると、彼らは顔色がすぐれなかった。'),
('JPN', '创世纪', 1, 40, 7, 'それで彼は、自分の主人の家に一緒に拘留されている、このファラオの廷臣たちに「なぜ、今日、お二人は顔色がさえないのですか」と尋ねた。'),
('JPN', '创世纪', 1, 40, 8, '二人は答えた。「私たちは夢を見たが、それを解き明かす人がいない。」ヨセフは言った。「解き明かしは、神のなさることではありませんか。さあ、私に話してください。」'),
('JPN', '创世纪', 1, 40, 9, '献酌官長はヨセフに自分の夢を話した。「夢の中で、私の前に一本のぶどうの木があった。'),
('JPN', '创世纪', 1, 40, 10, 'そのぶどうの木には三本のつるがあった。それは、芽を出すと、すぐ花が咲き、房が熟してぶどうの実になった。'),
('JPN', '创世纪', 1, 40, 11, '私の手にはファラオの杯があったので、私はそのぶどうを摘んで、ファラオの杯の中に搾って入れ、その杯をファラオの手に献げた。」'),
('JPN', '创世纪', 1, 40, 12, 'ヨセフは彼に言った。「その解き明かしはこうです。三本のつるとは三日のことです。'),
('JPN', '创世纪', 1, 40, 13, '三日のうちに、ファラオはあなたを呼び出し、あなたを元の地位に戻すでしょう。あなたは、ファラオの献酌官であったときの、以前の定めにしたがって、ファラオの杯をその手に献げるでしょう。'),
('JPN', '创世纪', 1, 40, 14, 'あなたが幸せになったときには、どうか私を思い出してください。私のことをファラオに話して、この家から私が出られるように、私に恵みを施してください。'),
('JPN', '创世纪', 1, 40, 15, '実は私は、ヘブル人の国から、さらわれて来たのです。ここでも私は、投獄されるようなことは何もしていません。」'),
('JPN', '创世纪', 1, 40, 16, '料理官長は、解き明かしが良かったのを見て、ヨセフに言った。「私の夢の中では、頭の上に枝編みのかごが三つあった。'),
('JPN', '创世纪', 1, 40, 17, '一番上のかごには、ファラオのために、ある料理官が作ったあらゆる食べ物が入っていたが、鳥が私の頭の上のかごの中から、それを食べてしまった。」'),
('JPN', '创世纪', 1, 40, 18, 'ヨセフは答えた。「その解き明かしはこうです。三つのかごとは三日のことです。'),
('JPN', '创世纪', 1, 40, 19, '三日のうちに、ファラオはあなたを呼び出し、あなたを木につるし、鳥があなたの肉をついばむでしょう。」'),
('JPN', '创世纪', 1, 40, 20, '三日目はファラオの誕生日であった。それで彼は、すべての家臣たちのために祝宴を催し、献酌官長と料理官長を家臣たちの中に呼び戻した。'),
('JPN', '创世纪', 1, 40, 21, 'そうして献酌官長をその献酌の役に戻したので、彼はその杯をファラオの手に献げた。'),
('JPN', '创世纪', 1, 40, 22, 'しかし、料理官長のほうは木につるした。ヨセフが彼らに解き明かしたとおりであった。'),
('JPN', '创世纪', 1, 40, 23, 'ところが、献酌官長はヨセフのことを思い出さないで、忘れてしまった。'),
('JPN', '创世纪', 1, 41, 1, 'それから二年後、ファラオは夢を見た。見ると、彼はナイル川のほとりに立っていた。'),
('JPN', '创世纪', 1, 41, 2, 'すると、ナイル川から、つやつやした、肉づきの良い雌牛が七頭、上がって来て、葦の中で草をはんだ。'),
('JPN', '创世纪', 1, 41, 3, 'するとまた、その後を追って、醜く痩せ細った別の雌牛が七頭、ナイル川から上がって来て、その川岸にいた雌牛のそばに立った。'),
('JPN', '创世纪', 1, 41, 4, 'そして、醜く痩せ細った雌牛が、つやつやした、よく肥えた七頭の雌牛を食い尽くしてしまった。そのとき、ファラオは目が覚めた。'),
('JPN', '创世纪', 1, 41, 5, '彼はまた眠り、再び夢を見た。見ると、一本の茎に、よく実った七つの良い穂が出て来た。'),
('JPN', '创世纪', 1, 41, 6, 'すると、その後を追って、しなびた、東風に焼けた七つの穂が出て来た。'),
('JPN', '创世纪', 1, 41, 7, 'そして、しなびた穂が、よく実った七つの穂を吞み込んでしまった。そのとき、ファラオは目が覚めた。それは夢だった。'),
('JPN', '创世纪', 1, 41, 8, '朝になって、ファラオは心が騒ぎ、人を遣わして、エジプトのすべての呪法師とすべての知恵のある者たちを呼び寄せた。ファラオは彼らに夢のことを話したが、解き明かすことのできる者はいなかった。'),
('JPN', '创世纪', 1, 41, 9, 'そのとき、献酌官長がファラオに告げた。「私は今日、私の過ちを申し上げなければなりません。'),
('JPN', '创世纪', 1, 41, 10, 'かつて、ファラオがしもべらに対して怒って、私と料理官長を侍従長の家に拘留されました。'),
('JPN', '创世纪', 1, 41, 11, '私と彼は、同じ夜に夢を見ました。それぞれ意味のある夢でした。'),
('JPN', '创世纪', 1, 41, 12, 'そこには、私たちと一緒に、侍従長のしもべで、ヘブル人の若者がいました。私たちが彼に話しましたところ、彼は私たちの夢を解き明かしてくれました。それぞれの夢に応じて、解き明かしてくれたのです。'),
('JPN', '创世纪', 1, 41, 13, 'そして、彼が私たちに解き明かしたとおりになり、ファラオは私を元の地位に戻され、料理官長は木につるされました。」'),
('JPN', '创世纪', 1, 41, 14, 'ファラオは人を遣わして、ヨセフを呼び寄せた。人々は急いで彼を地下牢から連れ出した。ヨセフはひげを剃り、着替えをして、ファラオの前に出た。'),
('JPN', '创世纪', 1, 41, 15, 'ファラオはヨセフに言った。「私は夢を見たが、それを解き明かす者がいない。おまえは夢を聞いて、それを解き明かすと聞いたのだが。」'),
('JPN', '创世纪', 1, 41, 16, 'ヨセフはファラオに答えた。「私ではありません。神がファラオの繁栄を知らせてくださるのです。」'),
('JPN', '创世纪', 1, 41, 17, 'それで、ファラオはヨセフに話した。「夢の中で、見ると、私はナイル川の岸に立っていた。'),
('JPN', '创世纪', 1, 41, 18, 'すると、ナイル川から、肉づきの良い、つやつやした雌牛が七頭上がって来て、葦の中で草をはんでいた。'),
('JPN', '创世纪', 1, 41, 19, 'すると、その後を追って、弱々しい、とても醜く痩せ細った別の雌牛が七頭、上がって来た。私は、このように醜い牛をエジプト全土でまだ見たことがない。'),
('JPN', '创世纪', 1, 41, 20, 'そして、この痩せた醜い雌牛が、先の肥えた七頭の雌牛を食い尽くしてしまった。'),
('JPN', '创世纪', 1, 41, 21, 'ところが、彼らを腹に入れても、腹に入ったのが分からないほど、その姿は初めと同じように醜かった。そのとき、私は目が覚めた。'),
('JPN', '创世纪', 1, 41, 22, 'また、夢の中で私は見た。見ると、一本の茎に、よく実った七つの穂が出て来た。'),
('JPN', '创世纪', 1, 41, 23, 'すると、その後を追って、貧弱で、しなびた、東風に焼けた七つの穂が出て来た。'),
('JPN', '创世纪', 1, 41, 24, 'そして、そのしなびた穂が、あの七つの良い穂を吞み込んでしまった。そこで私は呪法師たちに話したが、だれも私に説明できる者はいなかった。」'),
('JPN', '创世纪', 1, 41, 25, 'ヨセフはファラオに言った。「ファラオの夢は一つです。神が、なさろうとしていることをファラオにお告げになったのです。'),
('JPN', '创世纪', 1, 41, 26, '七頭の立派な雌牛は七年のことで、七つの立派な穂も七年のことです。それは一つの夢なのです。'),
('JPN', '创世纪', 1, 41, 27, 'その後から上がって来た七頭の痩せた醜い雌牛は七年のことで、痩せ細り東風に焼けた七つの穂も同様です。それは飢饉の七年です。'),
('JPN', '创世纪', 1, 41, 28, 'これは、私がファラオに申し上げたとおり、神が、なさろうとしていることをファラオに示されたのです。'),
('JPN', '创世纪', 1, 41, 29, '今すぐ、エジプト全土に七年間の大豊作が訪れようとしています。'),
('JPN', '创世纪', 1, 41, 30, 'その後、七年間の飢饉が起こり、エジプトの地で豊作のことはすべて忘れられます。飢饉が地を荒れ果てさせ、'),
('JPN', '创世纪', 1, 41, 31, 'この地の豊作は、後に来る飢饉のため、跡も分からなくなります。その飢饉が非常に激しいからです。'),
('JPN', '创世纪', 1, 41, 32, '夢が二度ファラオに繰り返されたのは、このことが神によって定められ、神が速やかにこれをなさるからです。'),
('JPN', '创世纪', 1, 41, 33, 'ですから、今、ファラオは、さとくて知恵のある人を見つけ、その者をエジプトの地の上に置かれますように。'),
('JPN', '创世纪', 1, 41, 34, 'ファラオは、国中に監督官を任命するよう、行動を起こされますように。豊作の七年間に、エジプトの地の収穫の五分の一を徴収なさるためです。'),
('JPN', '创世纪', 1, 41, 35, '彼らに、これからの豊作の年のあらゆる食糧をすべて集めさせ、ファラオの権威のもとに、町々に穀物を蓄えさせるのです。彼らは保管し、'),
('JPN', '创世纪', 1, 41, 36, 'その食糧は、エジプトの地に起こる七年の飢饉のために、国の蓄えとなります。そうすれば、この地は飢饉で滅びることがないでしょう。」'),
('JPN', '创世纪', 1, 41, 37, 'このことは、ファラオとすべての家臣たちの心にかなった。'),
('JPN', '创世纪', 1, 41, 38, 'そこで、ファラオは家臣たちに言った。「神の霊が宿っているこのような人が、ほかに見つかるだろうか。」'),
('JPN', '创世纪', 1, 41, 39, 'ファラオはヨセフに言った。「神がこれらすべてのことをおまえに知らされたからには、おまえのように、さとくて知恵のある者は、ほかにはいない。'),
('JPN', '创世纪', 1, 41, 40, 'おまえが私の家を治めるがよい。私の民はみな、おまえの命令に従うであろう。私がまさっているのは王位だけだ。」'),
('JPN', '创世纪', 1, 41, 41, 'ファラオはさらにヨセフに言った。「さあ、私はおまえにエジプト全土を支配させよう。」'),
('JPN', '创世纪', 1, 41, 42, 'そこで、ファラオは自分の指輪を指から外してヨセフの指にはめ、亜麻布の衣服を着せ、その首に金の首飾りを掛けた。'),
('JPN', '创世纪', 1, 41, 43, 'そして、自分の第二の車に彼を乗せた。人々は彼の前で「ひざまずけ」と叫んだ。こうしてファラオは彼にエジプト全土を支配させた。'),
('JPN', '创世纪', 1, 41, 44, 'ファラオはヨセフに言った。「私はファラオだ。しかし、おまえの許しなくしては、エジプトの国中で、だれも何もすることができない。」'),
('JPN', '创世纪', 1, 41, 45, 'ファラオはヨセフにツァフェナテ・パネアハという名を与え、オンの祭司ポティ・フェラの娘アセナテを彼の妻として与えた。こうしてヨセフはエジプトの地を監督するようになった。'),
('JPN', '创世纪', 1, 41, 46, 'エジプトの王ファラオに仕えるようになったとき、ヨセフは三十歳であった。ヨセフはファラオのもとから出発して、エジプト全土を巡った。'),
('JPN', '创世纪', 1, 41, 47, 'さて、豊作の七年間に、地は豊かに実らせた。'),
('JPN', '创世纪', 1, 41, 48, 'ヨセフはエジプトの地で穫れた七年間の食糧をことごとく集め、その食糧を町々に蓄えた。町の周囲にある畑の食糧を、それぞれの町の中に蓄えたのである。'),
('JPN', '创世纪', 1, 41, 49, 'ヨセフは穀物を、海の砂のように非常に多く蓄え、量りきれなくなったので、ついに量るのをやめた。'),
('JPN', '创世纪', 1, 41, 50, '飢饉の年が来る前に、ヨセフに二人の子が生まれた。オンの祭司ポティ・フェラの娘アセナテが産んだ子である。'),
('JPN', '创世纪', 1, 41, 51, 'ヨセフは長子をマナセと名づけた。「神が、私のすべての労苦と、私の父の家のすべてのことを忘れさせてくださった」からである。'),
('JPN', '创世纪', 1, 41, 52, 'また、二番目の子をエフライムと名づけた。「神が、私の苦しみの地で、私を実り多い者としてくださった」からである。'),
('JPN', '创世纪', 1, 41, 53, 'エジプトの地での豊作の七年が終わると、'),
('JPN', '创世纪', 1, 41, 54, 'ヨセフが言ったとおり、七年の飢饉が始まった。その飢饉はすべての国々に臨んだが、エジプト全土には食物があった。'),
('JPN', '创世纪', 1, 41, 55, 'やがて、エジプト全土が飢えると、その民はファラオに食物を求めて叫んだ。ファラオは全エジプトに言った。「ヨセフのもとに行き、ヨセフの言うとおりにせよ。」'),
('JPN', '创世纪', 1, 41, 56, '飢饉は地の全面に及んだ。ヨセフはすべての穀物倉を開けて、エジプト人に売った。その飢饉はエジプトの地でもひどくなった。'),
('JPN', '创世纪', 1, 41, 57, '全地は、穀物を買うためにエジプトのヨセフのところに来た。その飢饉が全地で厳しかったからである。'),
('JPN', '创世纪', 1, 42, 1, 'ヤコブはエジプトに穀物があることを知って、息子たちに言った。「おまえたちは、なぜ互いに顔を見合わせているのか。」'),
('JPN', '创世纪', 1, 42, 2, 'さらに言った。「今、私はエジプトに穀物があると聞いた。おまえたちは下って行って、そこから私たちのために穀物を買って来なさい。そうすれば、私たちは生き延び、死なずにすむだろう。」'),
('JPN', '创世纪', 1, 42, 3, 'そこで、ヨセフの十人の兄弟は、穀物を買うためにエジプトに下って行った。'),
('JPN', '创世纪', 1, 42, 4, 'しかし、ヤコブはヨセフの弟ベニヤミンを兄弟たちと一緒に送らなかった。わざわいが彼に降りかかるといけないと思ったからである。'),
('JPN', '创世纪', 1, 42, 5, 'こうしてイスラエルの息子たちは、人々に混じって、穀物を買いにやって来た。カナンの地に飢饉が起こったからである。'),
('JPN', '创世纪', 1, 42, 6, 'ときに、ヨセフはこの地の権力者であり、この地のすべての人に穀物を売る者であった。ヨセフの兄弟たちはやって来て、顔を地に付けて彼を伏し拝んだ。'),
('JPN', '创世纪', 1, 42, 7, 'ヨセフは兄弟たちを見て、それと分かったが、彼らに対して見知らぬ者のようにふるまい、荒々しいことばで彼らに言った。「おまえたちはどこから来たのか。」すると彼らは答えた。「カナンの地から食糧を買いに参りました。」'),
('JPN', '创世纪', 1, 42, 8, 'ヨセフには兄弟たちだと分かったが、彼らにはヨセフだとは分からなかった。'),
('JPN', '创世纪', 1, 42, 9, 'かつて彼らについて見た夢を思い出して、ヨセフは言った。「おまえたちは回し者だ。この国の隙をうかがいに来たのだろう。」'),
('JPN', '创世纪', 1, 42, 10, '彼らは言った。「いいえ、ご主人様。しもべどもは食糧を買いに参りました。'),
('JPN', '创世纪', 1, 42, 11, '私たちはみな、一人の人の子です。私たちは正直者です。しもべどもは回し者などではございません。」'),
('JPN', '创世纪', 1, 42, 12, 'ヨセフは彼らに言った。「いや、おまえたちは、この国の隙をうかがいにやって来たのだ。」'),
('JPN', '创世纪', 1, 42, 13, '彼らは言った。「しもべどもは十二人兄弟で、カナンの地にいる一人の人の子でございます。末の弟は今、父と一緒にいますが、もう一人はいなくなりました。」'),
('JPN', '创世纪', 1, 42, 14, 'ヨセフは彼らに言った。「私が、おまえたちは回し者だと言ったのは、そのことだ。'),
('JPN', '创世纪', 1, 42, 15, '次のことで、おまえたちを試そう。ファラオのいのちにかけて言うが、おまえたちの末の弟がここに来ないかぎり、おまえたちは決してここから出ることはできない。'),
('JPN', '创世纪', 1, 42, 16, 'おまえたちのうちの一人を送って、弟を連れて来い。それまで、おまえたちを監禁する。おまえたちに誠実さがあるかどうか、おまえたちの言ったことを試すためだ。もし誠実でなかったら、ファラオのいのちにかけて言うが、おまえたちは間違いなく回し者だ。」'),
('JPN', '创世纪', 1, 42, 17, 'こうしてヨセフは三日間、彼らを監獄に入れておいた。'),
('JPN', '创世纪', 1, 42, 18, 'ヨセフは三日目に彼らに言った。「次のようにして、生き延びよ。私も神を恐れる者だから。'),
('JPN', '创世纪', 1, 42, 19, 'もし、おまえたちが正直者なら、おまえたちの兄弟の一人を監獄に監禁したままにせよ。自分たちは飢えている家族に穀物を持って行くがよい。'),
('JPN', '创世纪', 1, 42, 20, 'そして、末の弟を私のところに連れて来るがよい。そうすれば、おまえたちのことばが本当だということが分かり、おまえたちが死ぬことはない。」そこで彼らはそのようにした。'),
('JPN', '创世纪', 1, 42, 21, '彼らは互いに言った。「まったく、われわれは弟のことで罰を受けているのだ。あれが、あわれみを求めたとき、その心の苦しみを見ながら、聞き入れなかった。それで、われわれはこんな苦しみにあっているのだ。」'),
('JPN', '创世纪', 1, 42, 22, 'ルベンが言った。「私はあの子に罪を犯すなと言ったではないか。それなのに、おまえたちは聞き入れなかった。だから今、彼の血の報いを受けているのだ。」'),
('JPN', '创世纪', 1, 42, 23, '彼らは、ヨセフが聞いていることを知らなかった。ヨセフと兄弟たちの間には通訳がいたからである。'),
('JPN', '创世纪', 1, 42, 24, 'ヨセフは彼らから離れて、泣いた。それから彼らのところに戻って来て、彼らに語った。そして彼らの中からシメオンを捕らえて、彼らの目の前で彼を縛った。'),
('JPN', '创世纪', 1, 42, 25, 'ヨセフは彼らの袋に穀物を満たし、それぞれの袋に彼らの銀を戻し、さらに道中の食糧を与えるように命じた。それで、人々はそのとおりにした。'),
('JPN', '创世纪', 1, 42, 26, '彼らは穀物を自分たちのろばに背負わせて、そこを去った。'),
('JPN', '创世纪', 1, 42, 27, 'さて、彼らの一人が、宿泊所で自分のろばに飼料をやろうとして袋を開けると、自分の銀が、見よ、自分の袋の口にあった。'),
('JPN', '创世纪', 1, 42, 28, '彼は兄弟たちに言った。「私の銀が戻されている。しかもこのとおり、私の袋の中に。」彼らは動転し、身を震わせて、互いに言った。「神は私たちにいったい何をなさったのだろう。」'),
('JPN', '创世纪', 1, 42, 29, '彼らはカナンの地にいる父ヤコブのもとに帰って、その身に起こったことをすべて彼に告げた。'),
('JPN', '创世纪', 1, 42, 30, '「あの国の主君である人が私たちに厳しく語り、私たちを、あの国を探る回し者のように扱いました。'),
('JPN', '创世纪', 1, 42, 31, '私たちはその人に、『私たちは正直者で、回し者などではありません。'),
('JPN', '创世纪', 1, 42, 32, '私たちは十二人兄弟で、同じ父の子です。一人はいなくなりましたが、末の弟は今、カナンの地に父と一緒にいます』と申しました。'),
('JPN', '创世纪', 1, 42, 33, 'すると、その国の主君である人が私たちに言いました。『こうすれば、おまえたちが正直者かどうか分かる。おまえたちの兄弟を一人、私のところに残して、飢えているおまえたちの家族に穀物を持って行け。'),
('JPN', '创世纪', 1, 42, 34, 'そして、末の弟を私のところに連れて来い。そうすれば、おまえたちが敵の回し者ではなく、正直者だということが分かる。そこで私はおまえたちの兄弟を渡そう。そうして、おまえたちはこの地に出入りができるようになる』と。」'),
('JPN', '创世纪', 1, 42, 35, 'それから彼らが自分たちの袋を空けると、見よ、一人ひとりの銀の包みが自分の袋の中にあった。彼らも父も、この銀の包みを見て恐れた。'),
('JPN', '创世纪', 1, 42, 36, '父ヤコブは言った。「おまえたちは、すでに私に子を失わせた。ヨセフはいなくなり、シメオンもいなくなった。そして今、ベニヤミンまで取ろうとしている。こんなことがみな、私に降りかかってきたのだ。」'),
('JPN', '创世纪', 1, 42, 37, 'ルベンは父に言った。「もし私がこの弟をあなたのもとに連れ帰らなかったら、私の二人の子を殺してもかまいません。彼を私に任せてください。この私が彼をあなたのもとに連れ戻します。」'),
('JPN', '创世纪', 1, 42, 38, 'するとヤコブは言った。「この子は、おまえたちと一緒には行かせない。この子の兄は死んで、この子だけが残っているのだから。道中で、もし彼にわざわいが降りかかれば、おまえたちは、この白髪頭の私を、悲しみながらよみに下らせることになるのだ。」'),
('JPN', '创世纪', 1, 43, 1, 'さて、その地の飢饉は激しかった。'),
('JPN', '创世纪', 1, 43, 2, '彼らがエジプトから持って来た穀物を食べ尽くしたとき、父は彼らに言った。「また行って、われわれのために食糧を少し買って来てくれ。」'),
('JPN', '创世纪', 1, 43, 3, 'すると、ユダが父に言った。「あの方は私たちを厳しく戒めて、『おまえたちの弟と一緒でなければ、私の顔を見てはならない』と言いました。'),
('JPN', '创世纪', 1, 43, 4, 'もし弟を私たちと一緒に行かせてくださるなら、私たちは下って行って、お父さんのために食糧を買って来ましょう。'),
('JPN', '创世纪', 1, 43, 5, 'しかし、もし彼を行かせてくださらないなら、私たちは下って行きません。あの方は私たちに、『おまえたちの弟と一緒でなければ、私の顔を見てはならない』と言ったのですから。」'),
('JPN', '创世纪', 1, 43, 6, 'イスラエルは言った。「なぜ、おまえたちは、自分たちにもう一人の弟がいるとその方に言って、私を苦しめるようなことをしたのか。」'),
('JPN', '创世纪', 1, 43, 7, '彼らは言った。「あの方が私たちや家族のことについて、『おまえたちの父はまだ生きているのか。おまえたちには弟がいるのか』としきりに尋ねるので、問われるままに言ってしまったのです。『おまえたちの弟を連れて来い』と言われるとは、どうして私たちに分かったでしょうか。」'),
('JPN', '创世纪', 1, 43, 8, 'ユダは父イスラエルに言った。「あの子を私と一緒に行かせてください。私たちは行きます。そうすれば私たちは、お父さんも私たちの子どもたちも、生き延びて、死なずにすむでしょう。'),
('JPN', '创世纪', 1, 43, 9, '私自身があの子の保証人となります。私が責任を負います。もしも、お父さんのもとに連れ帰らず、あなたの前にあの子を立たせなかったら、私は一生あなたの前に罪ある者となります。'),
('JPN', '创世纪', 1, 43, 10, 'もし私たちがためらっていなかったなら、今までに二度は、行って帰れたはずです。」'),
('JPN', '创世纪', 1, 43, 11, '父イスラエルは彼らに言った。「それなら、こうしなさい。この地の名産を袋に入れ、それを贈り物として、その方のところへ下って行きなさい。乳香と蜜を少々、樹膠と没薬、ピスタチオとアーモンド、'),
('JPN', '创世纪', 1, 43, 12, 'また二倍の銀を持って行きなさい。おまえたちの袋の口に返されていた銀も、持って行って返しなさい。おそらく、あれは間違いだったのだろう。'),
('JPN', '创世纪', 1, 43, 13, 'そして、弟を連れて、さあ、その方のところへ出かけて行きなさい。'),
('JPN', '创世纪', 1, 43, 14, '全能の神が、その方の前でおまえたちをあわれんでくださるように。そして、もう一人の兄弟とベニヤミンをおまえたちに渡してくださるように。私も、息子を失うときには失うのだ。」'),
('JPN', '创世纪', 1, 43, 15, 'そこで、一行は贈り物を携え、二倍の銀を持ち、ベニヤミンを伴って出発した。そして、エジプトへ下り、ヨセフの前に立った。'),
('JPN', '创世纪', 1, 43, 16, 'ヨセフは、ベニヤミンが彼らと一緒にいるのを見るや、彼の家を管理する者に言った。「この人たちを家に連れて行き、家畜を屠って料理しなさい。この人たちは私と昼食をともにするから。」'),
('JPN', '创世纪', 1, 43, 17, 'その人は、ヨセフが言ったとおりに、一同をヨセフの家に連れて行った。'),
('JPN', '创世纪', 1, 43, 18, '一同はヨセフの家に連れて行かれたので、怖くなって言った。「われわれが連れて来られたのは、この前のとき、われわれの袋に戻されていた、あの銀のせいだ。われわれを陥れて襲い、奴隷としてろばとともに捕らえるためだ。」'),
('JPN', '创世纪', 1, 43, 19, '彼らはヨセフの家を管理するその人に近づいて、家の入り口のところで話しかけた。'),
('JPN', '创世纪', 1, 43, 20, '「ご主人様、最初のとき、私たちは食糧を買いに下って参りました。'),
('JPN', '创世纪', 1, 43, 21, 'ところが、宿泊所に着いて、袋を開けると、なんと、私たちの一人ひとりの銀がそのまま自分の袋の口にあったのです。それで、私たちはそれを返しに持って参りました。'),
('JPN', '创世纪', 1, 43, 22, 'また、食糧を買うために、別の銀も持って参りました。だれが私たちの銀を袋の中に入れたのかは、私たちには分かりません。」'),
('JPN', '创世纪', 1, 43, 23, '彼は答えた。「安心しなさい。恐れることはありません。あなたがたの神、あなたがたの父の神が、あなたがたのために袋の中に宝を入れてくださったのです。あなたがたの銀は、私が受け取りました。」それから、彼はシメオンを彼らのところに連れて来た。'),
('JPN', '创世纪', 1, 43, 24, 'その人は一同をヨセフの家に連れて行き、水を与え、彼らは足を洗った。また彼は、彼らのろばに餌を与えた。'),
('JPN', '创世纪', 1, 43, 25, '兄弟たちは、ヨセフが昼に帰って来るまでに、贈り物を用意しておいた。自分たちがそこで食事をすることになっていると聞いたからである。'),
('JPN', '创世纪', 1, 43, 26, 'ヨセフが家に帰って来たとき、彼らはその家まで携えて来た贈り物を彼に差し出し、地に伏して彼を拝した。'),
('JPN', '创世纪', 1, 43, 27, 'ヨセフは彼らの安否を尋ねた。「以前に話していた、おまえたちの年老いた父親は元気か。まだ生きているのか。」'),
('JPN', '创世纪', 1, 43, 28, '彼らは答えた。「あなた様のしもべ、私たちの父は元気で、まだ生きております。」そして、彼らはひざまずいて彼を拝した。'),
('JPN', '创世纪', 1, 43, 29, 'ヨセフは目を上げ、同じ母の子である弟のベニヤミンを見て言った。「これが、おまえたちが私に話した末の弟か。」そして言った。「わが子よ、神がおまえを恵まれるように。」'),
('JPN', '创世纪', 1, 43, 30, 'ヨセフは弟なつかしさに、胸が熱くなって泣きたくなり、急いで奥の部屋に入って、そこで泣いた。'),
('JPN', '创世纪', 1, 43, 31, 'やがて、彼は顔を洗って出て来た。そして自分を制して、「食事を出せ」と命じた。'),
('JPN', '创世纪', 1, 43, 32, 'それで、ヨセフにはヨセフ用に、彼らには彼ら用に、ヨセフとともに食事をするエジプト人にはその人たち用に、それぞれ別々に食事が出された。エジプト人は、ヘブル人とはともに食事ができなかったからである。それは、エジプト人が忌み嫌うことであった。'),
('JPN', '创世纪', 1, 43, 33, '彼らはヨセフの前で、年長者は年長の席に、年下の者は年下の席に座らされたので、一同は互いに驚き合った。'),
('JPN', '创世纪', 1, 43, 34, 'また、ヨセフの食卓から彼らの分が与えられたが、ベニヤミンの分は、ほかの者より五倍も多かった。彼らはヨセフとともに酒を飲み、酔い心地になった。'),
('JPN', '创世纪', 1, 44, 1, 'ヨセフは家を管理する者に命じた。「あの者たちの袋を、彼らが運べるかぎりの食糧で満たし、一人ひとりの銀を彼らの袋の口に入れておけ。'),
('JPN', '创世纪', 1, 44, 2, 'それから、私の杯、あの銀の杯は、一番年下の者の袋の口に、穀物の代金と一緒に入れておけ。」彼はヨセフのことばどおりにした。'),
('JPN', '创世纪', 1, 44, 3, '明け方、一行はろばとともに送り出された。'),
('JPN', '创世纪', 1, 44, 4, '彼らが町を出て、まだ遠くへ行かないうちに、ヨセフは家を管理する者に言った。「さあ、あの者たちの後を追え。追いついたら、『なぜ、おまえたちは悪をもって善に報いるのか。'),
('JPN', '创世纪', 1, 44, 5, 'これは、私の主君が、飲んだり占いをしたりするときに、いつも使っておられるものではないか。おまえたちのしたことは悪辣だ』と彼らに言うのだ。」'),
('JPN', '创世纪', 1, 44, 6, '彼は追いついて、このことばを彼らに告げた。'),
('JPN', '创世纪', 1, 44, 7, '彼らは言った。「あなた様は、なぜ、そのようなことをおっしゃるのですか。しもべどもがそんなことをするなど、あり得ないことです。'),
('JPN', '创世纪', 1, 44, 8, '袋の口で見つけた銀でさえ、カナンの地からあなた様のもとへ返しに来たではありませんか。どうして、あなた様のご主人の家から銀や金を盗んだりするでしょう。'),
('JPN', '创世纪', 1, 44, 9, 'しもべどものうちで、それが見つかった者は殺してください。そして、私たちもまた、ご主人の奴隷になります。」'),
('JPN', '创世纪', 1, 44, 10, '彼は言った。「今度も、おまえたちの言うことはもっともだが、それが見つかった者は私の奴隷とし、ほかの者は無罪としよう。」'),
('JPN', '创世纪', 1, 44, 11, '彼らは急いでそれぞれ自分の袋を地面に降ろし、それぞれその袋を開けた。'),
('JPN', '创世纪', 1, 44, 12, '彼は年長の者から調べ始めて、年下の者で終えた。すると、その杯はベニヤミンの袋から見つかった。'),
('JPN', '创世纪', 1, 44, 13, '彼らは自分の衣を引き裂いた。そして、それぞれろばに荷を負わせ、町に引き返した。'),
('JPN', '创世纪', 1, 44, 14, 'ユダと兄弟たちがヨセフの家にやって来たとき、ヨセフはまだ、そこにいた。彼らはヨセフの前で顔を地に伏せた。'),
('JPN', '创世纪', 1, 44, 15, 'ヨセフは彼らに言った。「おまえたちの、このしわざは何だ。私のような者は占いをするということを知らなかったのか。」'),
('JPN', '创世纪', 1, 44, 16, 'ユダが答えた。「あなた様に何を申し上げられるでしょう。何の申し開きができるでしょう。何と言って弁解することができるでしょう。神がしもべどもの咎を暴かれたのです。今このとおり、私たちも、そして、その手に杯が見つかった者も、あなた様の奴隷となります。」'),
('JPN', '创世纪', 1, 44, 17, 'ヨセフは言った。「そんなことをするなど、とんでもないことだ。その手に杯が見つかった者、その者が私の奴隷となるのだ。おまえたちは安心して父のもとへ帰るがよい。」'),
('JPN', '创世纪', 1, 44, 18, 'すると、ユダが彼に近づいて言った。「ご主人様。どうか、しもべが申し上げることに、耳をお貸しください。どうか、しもべを激しくお怒りにならないでください。あなた様はファラオのようなお方です。'),
('JPN', '创世纪', 1, 44, 19, 'あなた様は、以前しもべどもに、おまえたちに父や弟がいるかとお尋ねになりました。'),
('JPN', '创世纪', 1, 44, 20, 'それで私たちは、『私たちには、年老いた父と、年寄り子の末の弟がおります。彼の兄は死に、その母の子としては彼だけが残されましたので、父は彼を愛しています』と申し上げました。'),
('JPN', '创世纪', 1, 44, 21, 'するとあなた様は、『彼を私のところに連れて来い。私はこの目で彼を見たい』とおっしゃいました。'),
('JPN', '创世纪', 1, 44, 22, 'そのとき私たちは、『その子は父親と離れることはできません。離れたら父親は死ぬでしょう』とあなた様に申し上げました。'),
('JPN', '创世纪', 1, 44, 23, 'しかし、あなた様が、『末の弟が一緒に下って来なければ、二度と私の顔を見てはならない』とおっしゃったので、'),
('JPN', '创世纪', 1, 44, 24, '私たちは、あなた様のしもべである私の父のもとに帰ったとき、父にあなた様のおことばを伝えました。'),
('JPN', '创世纪', 1, 44, 25, 'そして父が、『また行って、われわれのために少し食糧を買って来てくれ』と言ったので、'),
('JPN', '创世纪', 1, 44, 26, '私たちは、『下って行くことはできません。もし末の弟が私たちと一緒なら、下って行きます。というのは、末の弟と一緒でなければ、あの方のお顔を見ることはできないからです』と答えました。'),
('JPN', '创世纪', 1, 44, 27, 'すると、あなた様のしもべ、私の父がこう申しました。『おまえたちもよく知っているように、私の妻は二人の子を産んだ。'),
('JPN', '创世纪', 1, 44, 28, '一人は私のところから出て行ったきりで、きっと獣にかみ裂かれてしまったのだ、と私は言った。今に至るまで、私は彼を見ていない。'),
('JPN', '创世纪', 1, 44, 29, 'おまえたちがこの子まで私から奪って、この子にわざわいが降りかかるなら、おまえたちは白髪頭の私を、苦しみながらよみに下らせることになる。』'),
('JPN', '创世纪', 1, 44, 30, '私が今、あなた様のしもべである私の父のもとへ帰ったとき、あの子が私たちと一緒にいなかったら、父のいのちはあの子のいのちに結ばれていますから、'),
('JPN', '创世纪', 1, 44, 31, 'あの子がいないのを見たら、父は死んでしまうでしょう。しもべどもは、あなた様のしもべである白髪頭の父を、悲しみながらよみに下らせることになります。'),
('JPN', '创世纪', 1, 44, 32, 'というのは、このしもべは父に、『もしも、あの子をお父さんのもとに連れ帰らなかったなら、私は一生あなたの前に罪ある者となります』と言って、あの子の保証人となっているからです。'),
('JPN', '创世纪', 1, 44, 33, 'ですから、どうか今、このしもべを、あの子の代わりに、あなた様の奴隷としてとどめ、あの子を兄弟たちと一緒に帰らせてください。'),
('JPN', '创世纪', 1, 44, 34, 'あの子が一緒でなくて、どうして私は父のところへ帰れるでしょう。父に起こるわざわいを見たくありません。」'),
('JPN', '创世纪', 1, 45, 1, 'ヨセフは、そばに立っているすべての人の前で、自分を制することができなくなって、「皆を私のところから出しなさい」と叫んだ。ヨセフが兄弟たちに自分のことを明かしたとき、彼のそばに立っている者はだれもいなかった。'),
('JPN', '创世纪', 1, 45, 2, 'ヨセフは声をあげて泣いた。エジプト人はその声を聞き、ファラオの家の者もそれを聞いた。'),
('JPN', '创世纪', 1, 45, 3, 'ヨセフは兄弟たちに言った。「私はヨセフです。父上はお元気ですか。」兄弟たちはヨセフを前にして、驚きのあまり、答えることができなかった。'),
('JPN', '创世纪', 1, 45, 4, 'ヨセフは兄弟たちに言った。「どうか私に近寄ってください。」彼らが近寄ると、ヨセフは言った。「私は、あなたがたがエジプトに売った弟のヨセフです。'),
('JPN', '创世纪', 1, 45, 5, '私をここに売ったことで、今、心を痛めたり自分を責めたりしないでください。神はあなたがたより先に私を遣わし、いのちを救うようにしてくださいました。'),
('JPN', '创世纪', 1, 45, 6, 'というのは、この二年の間、国中に飢饉が起きていますが、まだあと五年は、耕すことも刈り入れることもないからです。'),
('JPN', '创世纪', 1, 45, 7, '神が私をあなたがたより先にお遣わしになったのは、あなたがたのために残りの者をこの地に残し、また、大いなる救いによって、あなたがたを生き延びさせるためだったのです。'),
('JPN', '创世纪', 1, 45, 8, 'ですから、私をここに遣わしたのは、あなたがたではなく、神なのです。神は私を、ファラオには父とし、その全家には主人とし、またエジプト全土の統治者とされました。'),
('JPN', '创世纪', 1, 45, 9, 'どうか、急いで父上のところに上って行き、言ってください。『息子のヨセフがこう言いました。「神は私をエジプト全土の主とされました。ためらうことなく私のところに下って来てください。'),
('JPN', '创世纪', 1, 45, 10, 'ゴシェンの地に住んで、私の近くにいてください。父上も、子と孫、羊と牛、また父上に属するすべてのものも。'),
('JPN', '创世纪', 1, 45, 11, '飢饉はあと五年続きますから、父上も家族も、また父上に属するすべてのものも、困ることのないように、私が父上をそこで養いましょう」と。』'),
('JPN', '创世纪', 1, 45, 12, 'さあ、あなたがたも、弟のベニヤミンも、自分の目でしっかり見てください。あなたがたに話しているのは、この私の口です。'),
('JPN', '创世纪', 1, 45, 13, 'あなたがたは、エジプトでの私のすべての栄誉と、あなたがたが見た一切のことを父上に告げ、急いで父上をここに連れて来てください。」'),
('JPN', '创世纪', 1, 45, 14, '彼は弟ベニヤミンの首を抱いて泣いた。ベニヤミンも彼の首を抱いて泣いた。'),
('JPN', '创世纪', 1, 45, 15, '彼はまた、兄弟みなに口づけし、彼らを抱いて泣いた。それから兄弟たちは彼と語り合った。'),
('JPN', '创世纪', 1, 45, 16, 'ヨセフの兄弟たちが来たという知らせが、ファラオの家に伝えられると、ファラオもその家臣たちも喜んだ。'),
('JPN', '创世纪', 1, 45, 17, 'ファラオはヨセフに言った。「おまえの兄弟たちに言うがよい。『こうしなさい。家畜に荷を積んで、すぐカナンの地へ行き、'),
('JPN', '创世纪', 1, 45, 18, 'あなたがたの父と家族を連れて、私のもとへ来なさい。私はあなたがたに、エジプトの地の最良のものを与えよう。あなたがたは、地の最も良い物を食べるがよい。』'),
('JPN', '创世纪', 1, 45, 19, 'おまえはこう命じなさい。『子どもたちと妻たちのために、エジプトの地から車を持って行き、あなたがたの父を乗せて来なさい。'),
('JPN', '创世纪', 1, 45, 20, '家財に未練を残してはならない。エジプト全土の最良の物は、あなたがたのものだから』と。」'),
('JPN', '创世纪', 1, 45, 21, 'そこで、イスラエルの息子たちはそのようにした。ヨセフは、ファラオの命により、彼らに車を与え、また道中のための食糧も与えた。'),
('JPN', '创世纪', 1, 45, 22, '彼ら一人ひとりに晴れ着を与えたが、ベニヤミンには銀三百枚と晴れ着五着を与えた。'),
('JPN', '创世纪', 1, 45, 23, '父に贈ったものは、エジプトの最良のものを積んだろば十頭と、穀物とパンと父の道中の食糧を積んだ雌ろば十頭であった。'),
('JPN', '创世纪', 1, 45, 24, 'こうしてヨセフは兄弟たちを送り出し、彼らが出発するとき、彼らに言った。「道中、言い争いをしないでください。」'),
('JPN', '创世纪', 1, 45, 25, '彼らはエジプトから上って、カナンの地、彼らの父ヤコブのもとへ戻って来た。'),
('JPN', '创世纪', 1, 45, 26, '彼らは父に告げた。「ヨセフはまだ生きています。しかも、エジプト全土を支配しているのは彼です。」父は茫然としていた。彼らのことばが信じられなかったからである。'),
('JPN', '创世纪', 1, 45, 27, '彼らは、ヨセフが話したことを残らず彼に話して聞かせた。ヨセフが自分を乗せるために送ってくれた車を見ると、父ヤコブは元気づいた。'),
('JPN', '创世纪', 1, 45, 28, 'イスラエルは言った。「十分だ。息子のヨセフがまだ生きているとは。私は死ぬ前に彼に会いに行こう。」'),
('JPN', '创世纪', 1, 46, 1, 'イスラエルは、彼に属するものすべてと一緒に旅立った。そしてベエル・シェバに来たとき、父イサクの神にいけにえを献げた。'),
('JPN', '创世纪', 1, 46, 2, '神は、夜の幻の中でイスラエルに「ヤコブよ、ヤコブよ」と語りかけられた。彼は答えた。「はい、ここにおります。」'),
('JPN', '创世纪', 1, 46, 3, 'すると神は仰せられた。「わたしは神、あなたの父の神である。エジプトに下ることを恐れるな。わたしはそこで、あなたを大いなる国民とする。'),
('JPN', '创世纪', 1, 46, 4, 'このわたしが、あなたとともにエジプトに下り、また、このわたしが必ずあなたを再び連れ上る。そしてヨセフが、その手であなたの目を閉じてくれるだろう。」'),
('JPN', '创世纪', 1, 46, 5, 'ヤコブはベエル・シェバを出発した。イスラエルの息子たちは、ヤコブを乗せるためにファラオが送った車に、父ヤコブと自分の子どもたちや妻たちを乗せた。'),
('JPN', '创世纪', 1, 46, 6, 'そして、家畜とカナンの地で得た財産を携えて、ヤコブとそのすべての子孫は、一緒にエジプトにやって来た。'),
('JPN', '创世纪', 1, 46, 7, '彼は、自分の息子と孫、娘と孫娘、すなわちすべての子孫を、一緒にエジプトに連れて来た。'),
('JPN', '创世纪', 1, 46, 8, 'エジプトに来たイスラエルの子ら、ヤコブとその子らの名は次のとおりである。ヤコブの長子ルベン。'),
('JPN', '创世纪', 1, 46, 9, 'ルベンの子はハノク、パル、ヘツロン、カルミ。'),
('JPN', '创世纪', 1, 46, 10, 'シメオンの子はエムエル、ヤミン、オハデ、ヤキン、ツォハル、カナンの女による子シャウル。'),
('JPN', '创世纪', 1, 46, 11, 'レビの子はゲルション、ケハテ、メラリ。'),
('JPN', '创世纪', 1, 46, 12, 'ユダの子はエル、オナン、シェラ、ペレツ、ゼラフ。エルとオナンはカナンの地で死んだ。ペレツの子はヘツロンとハムルであった。'),
('JPN', '创世纪', 1, 46, 13, 'イッサカルの子はトラ、プワ、ヨブ、シムロン。'),
('JPN', '创世纪', 1, 46, 14, 'ゼブルンの子はセレデ、エロン、ヤフレエル。'),
('JPN', '创世纪', 1, 46, 15, 'これらは、レアがパダン・アラムでヤコブに産んだ子で、それに娘ディナがいて、彼の息子や娘たちは全部で三十三人。'),
('JPN', '创世纪', 1, 46, 16, 'ガドの子はツィフヨン、ハギ、シュニ、エツボン、エリ、アロディ、アルエリ。'),
('JPN', '创世纪', 1, 46, 17, 'アシェルの子はイムナ、イシュワ、イシュウィ、ベリアと、彼らの妹セラフ。ベリアの子はヘベル、マルキエル。'),
('JPN', '创世纪', 1, 46, 18, 'これらは、ラバンが娘レアに与えたジルパの子である。彼女はヤコブに、これら十六人を産んだ。'),
('JPN', '创世纪', 1, 46, 19, 'ヤコブの妻ラケルの子はヨセフとベニヤミン。'),
('JPN', '创世纪', 1, 46, 20, 'ヨセフにはエジプトの地で子が生まれた。それは、オンの祭司ポティ・フェラの娘アセナテが彼に産んだ、マナセとエフライムである。'),
('JPN', '创世纪', 1, 46, 21, 'ベニヤミンの子はベラ、ベケル、アシュベル、ゲラ、ナアマン、エヒ、ロシュ、ムピム、フピム、アルデ。'),
('JPN', '创世纪', 1, 46, 22, 'これらはヤコブに生まれたラケルの子で、全部で十四人。'),
('JPN', '创世纪', 1, 46, 23, 'ダンの子はフシム。'),
('JPN', '创世纪', 1, 46, 24, 'ナフタリの子はヤフツェエル、グニ、エツェル、シレム。'),
('JPN', '创世纪', 1, 46, 25, 'これらは、ラバンが娘ラケルに与えたビルハの子である。彼女がヤコブに産んだのは全部で七人であった。'),
('JPN', '创世纪', 1, 46, 26, 'ヤコブに属する者、彼の腰から生まれ出た子でエジプトにやって来た者は、ヤコブの息子たちの妻を除いて、全部で六十六人。'),
('JPN', '创世纪', 1, 46, 27, 'エジプトで生まれたヨセフの子は二人である。エジプトに来たヤコブの家族は、全部で七十人であった。'),
('JPN', '创世纪', 1, 46, 28, 'さて、ヤコブはユダを先にヨセフのところに遣わして、ゴシェンへの道を教えてもらった。そうして彼らは、ゴシェンの地にやって来た。'),
('JPN', '创世纪', 1, 46, 29, 'ヨセフは車を整え、父イスラエルを迎えにゴシェンへ上った。そして父に会うなり、父の首に抱きつき、首にすがって泣き続けた。'),
('JPN', '创世纪', 1, 46, 30, 'イスラエルはヨセフに言った。「もう今、私は死んでもよい。おまえがまだ生きていて、そのおまえの顔を見たのだから。」'),
('JPN', '创世纪', 1, 46, 31, 'ヨセフは兄弟たちや父の家の者たちに言った。「私はファラオのところに知らせに上って行き、申しましょう。『カナンの地にいた、私の兄弟たちと父の家の者たちが、私のところにやって来ました。'),
('JPN', '创世纪', 1, 46, 32, 'この人たちは羊飼いです。家畜を飼っていたのです。この人たちは、自分たちの羊と牛と、所有するものすべてを連れて来ました。』'),
('JPN', '创世纪', 1, 46, 33, 'もしファラオがあなたがたを呼び寄せて、『おまえたちの職業は何か』と聞いたら、'),
('JPN', '创世纪', 1, 46, 34, 'こう答えてください。『しもべどもは若いときから今まで、家畜を飼う者でございます。私たちも、また私たちの先祖も』と。そうすれば、あなたがたはゴシェンの地に住めるでしょう。羊を飼う者はみな、エジプト人に忌み嫌われているからです。」'),
('JPN', '创世纪', 1, 47, 1, 'ヨセフはファラオのところに来て、報告した。「私の父と兄弟たち、また、その羊の群れ、牛の群れ、そして、彼らの所有するものすべてが、カナンの地から参りました。今、ゴシェンの地におります。」'),
('JPN', '创世纪', 1, 47, 2, '彼は兄弟の中から五人を連れて来て、ファラオに引き合わせた。'),
('JPN', '创世纪', 1, 47, 3, 'ファラオはヨセフの兄弟たちに尋ねた。「おまえたちの職業は何か。」彼らはファラオに答えた。「しもべどもは羊を飼う者で、私どもも、私どもの先祖もそうでございます。」'),
('JPN', '创世纪', 1, 47, 4, 'また、彼らはファラオに言った。「私たちはこの地に寄留しようとして参りました。カナンの地は飢饉が激しくて、しもべどもの羊のための牧草がございません。どうか、しもべどもをゴシェンの地に住まわせてください。」'),
('JPN', '创世纪', 1, 47, 5, 'ファラオはヨセフに言った。「おまえの父と兄弟たちが、おまえのところに来た。'),
('JPN', '创世纪', 1, 47, 6, 'エジプトの地はおまえの前にある。最も良い地に、おまえの父と兄弟たちを住まわせなさい。彼らをゴシェンの地に住まわせるがよい。彼らの中に有能な者たちがいるのが分かったなら、その者たちを私の家畜の係長としなさい。」'),
('JPN', '创世纪', 1, 47, 7, 'それから、ヨセフは父ヤコブを連れて来て、ファラオの前に立たせた。ヤコブはファラオを祝福した。'),
('JPN', '创世纪', 1, 47, 8, 'ファラオはヤコブに尋ねた。「あなたの生きてきた年月は、どれほどになりますか。」'),
('JPN', '创世纪', 1, 47, 9, 'ヤコブはファラオに答えた。「私がたどってきた年月は百三十年です。私の生きてきた年月はわずかで、いろいろなわざわいがあり、私の先祖がたどった日々、生きた年月には及びません。」'),
('JPN', '创世纪', 1, 47, 10, 'ヤコブはファラオを祝福し、ファラオの前から立ち去った。'),
('JPN', '创世纪', 1, 47, 11, 'ヨセフは、ファラオが命じたとおりに、父と兄弟たちの住まいを定め、彼らにエジプトの地で最も良い地、ラメセスの地に所有地を与えた。'),
('JPN', '创世纪', 1, 47, 12, 'またヨセフは、父と兄弟たちとその一族全員を、扶養すべき者の数に応じて、食物を与えて養った。'),
('JPN', '创世纪', 1, 47, 13, '飢饉が非常に激しかったので、全地で食物がなくなり、エジプトの地もカナンの地も飢饉によって衰え果てた。'),
('JPN', '创世纪', 1, 47, 14, 'ヨセフは、エジプトの地とカナンの地にあった銀をすべて集めた。それは人々が穀物に対して払ったものである。ヨセフはその銀をファラオの家に納めた。'),
('JPN', '创世纪', 1, 47, 15, 'エジプトの地とカナンの地に銀が尽きたとき、エジプト人はみなヨセフのところに来て言った。「私たちに食物を下さい。銀が尽きたからといって、どうして私たちがあなた様の前で死んでよいでしょうか。」'),
('JPN', '创世纪', 1, 47, 16, 'ヨセフは言った。「おまえたちの家畜を差し出しなさい。銀が尽きたのなら、家畜と引き替えに与えよう。」'),
('JPN', '创世纪', 1, 47, 17, '人々がヨセフのところに家畜を引いて来たので、ヨセフは、馬、羊の群れ、牛の群れ、ろばと引き替えに、彼らに食物を与えた。こうして彼はその年、すべての家畜と引き替えに、彼らに食物を分け与えた。'),
('JPN', '创世纪', 1, 47, 18, 'やがてその年も終わり、次の年にも人々はヨセフのところに来て言った。「私たちはあなた様に何も隠しません。銀も尽き、家畜の群れもあなた様のものになったので、自分のからだと土地のほかには、あなた様の前に何も残っておりません。'),
('JPN', '创世纪', 1, 47, 19, 'どうして私たちが、土地と一緒にあなた様の前で死んでよいでしょうか。食物と引き替えに、私たちと私たちの土地を買い取ってください。私たちは土地と一緒にファラオの奴隷となります。どうか種を下さい。そうすれば私たちは生き延び、死なずにすみます。土地も荒れないでしょう。」'),
('JPN', '创世纪', 1, 47, 20, 'それでヨセフは、エジプトのすべての土地をファラオのために買い取った。エジプト人に飢饉が厳しかったので、人々がみな、自分の畑地を売ったからである。こうしてその土地は、ファラオのものとなった。'),
('JPN', '创世纪', 1, 47, 21, 'また民については、エジプトの領土の端から端に至るどこででも、彼らを町々に移動させた。'),
('JPN', '创世纪', 1, 47, 22, 'しかし、祭司たちの土地だけは買い取らなかった。祭司たちにはファラオからの給与があり、ファラオが与える給与によって生活していたからである。そのため、自分たちの土地を売らなかった。'),
('JPN', '创世纪', 1, 47, 23, 'ヨセフは民に言った。「見よ。私は今、おまえたちとおまえたちの土地を買い取って、ファラオのものとした。さあ、ここに、おまえたちのための種がある。これをその土地に蒔きなさい。'),
('JPN', '创世纪', 1, 47, 24, '収穫の時になったら、その五分の一はファラオに納め、五分の四は自分のものとしなさい。畑の種にするため、自分の食糧にするため、家の者のため、また扶養すべき者たちの食糧のために、そうしなさい。」'),
('JPN', '创世纪', 1, 47, 25, 'すると彼らは言った。「あなた様は私たちを生かしてくださいました。私たちは、あなた様のご好意を受けて、ファラオの奴隷となりましょう。」'),
('JPN', '创世纪', 1, 47, 26, 'ヨセフは、エジプトの土地について、五分の一はファラオのものとしなければならないという、一つの掟を定めた。それは今日にまで及んでいる。ただし、祭司の土地だけはファラオのものとならなかった。'),
('JPN', '创世纪', 1, 47, 27, 'さて、イスラエルはエジプトの国でゴシェンの地に住んだ。彼らはそこに所有地を得て、多くの子を生み、大いに数を増やした。'),
('JPN', '创世纪', 1, 47, 28, 'ヤコブはエジプトの地で十七年生きた。ヤコブが生きた年月は百四十七年であった。'),
('JPN', '创世纪', 1, 47, 29, 'イスラエルに死ぬ日が近づいたとき、彼はその子ヨセフを呼び寄せて言った。「もしおまえの心にかなうなら、おまえの手を私のももの下に入れ、私に愛と真実を尽くしてくれ。私をエジプトの地には葬らないでほしい。'),
('JPN', '创世纪', 1, 47, 30, '私が先祖とともに眠りについたら、エジプトから運び出して、先祖の墓に葬ってくれ。」ヨセフは言った。「必ずあなたの言われたとおりにいたします。」'),
('JPN', '创世纪', 1, 47, 31, 'イスラエルは言った。「私に誓ってくれ。」ヨセフは彼に誓った。イスラエルは寝床の枕もとで、ひれ伏した。'),
('JPN', '创世纪', 1, 48, 1, 'これらのことの後、ヨセフに「お父上が、御病気です」と告げる者があったので、彼は二人の息子、マナセとエフライムを連れて行った。'),
('JPN', '创世纪', 1, 48, 2, 'ヤコブに「息子さんのヨセフが、今お見えになりました」との知らせがあった。それで、イスラエルは力を振り絞って床の上に座った。'),
('JPN', '创世纪', 1, 48, 3, 'ヤコブはヨセフに言った。「全能の神はカナンの地ルズで私に現れ、私を祝福して、'),
('JPN', '创世纪', 1, 48, 4, '仰せられた。『見よ、わたしはあなたに多くの子を与える。あなたを増やし、あなたを多くの民の群れとし、この地をあなたの後の子孫に永遠の所有地として与える。』'),
('JPN', '创世纪', 1, 48, 5, '私がエジプトのおまえのところにやって来る前に、エジプトの地でおまえに生まれた、おまえの二人の子は、今、私の子とする。エフライムとマナセは、ルベンやシメオンと同じように私の子となる。'),
('JPN', '创世纪', 1, 48, 6, 'しかし、二人の後でおまえに生まれる子どもたちは、おまえのものになる。しかし、彼らがゆずりとして受け継ぐ地では、彼らは兄たちの名を名乗らなければならない。'),
('JPN', '创世纪', 1, 48, 7, '私のことを言えば、パダンから帰って来たとき、その途上のカナンの地で、悲しいことにラケルが死んだ。エフラテに着くにはまだかなりの道のりがあるところでだった。私は、エフラテ、すなわちベツレヘムへの道にあるその場所に、彼女を葬った。」'),
('JPN', '创世纪', 1, 48, 8, 'イスラエルはヨセフの息子たちに気づいて言った。「この者たちはだれか。」'),
('JPN', '创世纪', 1, 48, 9, 'ヨセフは父に答えた。「神がここで私に授けてくださった息子たちです。」すると、父は「私のところに連れて来なさい。彼らを祝福しよう」と言った。'),
('JPN', '创世纪', 1, 48, 10, 'イスラエルは老齢のために目がかすんでいて、見ることができなかった。それで、ヨセフが彼らを父のところに近寄らせると、父は彼らに口づけして抱き寄せた。'),
('JPN', '创世纪', 1, 48, 11, 'イスラエルはヨセフに言った。「おまえの顔が見られるとは思わなかったのに、今こうして神は、おまえの子孫も私に見させてくださった。」'),
('JPN', '创世纪', 1, 48, 12, 'ヨセフはヤコブの膝から彼らを引き寄せて、顔を地に付けて伏し拝んだ。'),
('JPN', '创世纪', 1, 48, 13, 'それからヨセフは二人を、右手でエフライムをイスラエルの左手側に、左手でマナセをイスラエルの右手側に引き寄せた。そして二人を彼に近寄らせた。'),
('JPN', '创世纪', 1, 48, 14, 'ところがイスラエルは、右手を伸ばして弟であるエフライムの頭に置き、左手をマナセの頭に置いた。マナセが長子なのに、彼は手を交差させたのである。'),
('JPN', '创世纪', 1, 48, 15, '彼はヨセフを祝福して言った。「私の先祖アブラハムとイサクが、その御前に歩んだ神よ。今日のこの日まで、ずっと私の羊飼いであられた神よ。'),
('JPN', '创世纪', 1, 48, 16, 'すべてのわざわいから私を贖われた御使いが、この子どもたちを祝福してくださいますように。私の名が先祖アブラハムとイサクの名とともに、彼らのうちに受け継がれますように。また、彼らが地のただ中で豊かに増えますように。」'),
('JPN', '创世纪', 1, 48, 17, 'ヨセフは、父が右手をエフライムの頭に置いたのを見て、それは間違っていると思い、父の手を取って、それをエフライムの頭からマナセの頭へ移そうとした。'),
('JPN', '创世纪', 1, 48, 18, 'ヨセフは父に言った。「父上、そうではありません。こちらが長子なのですから、右の手を、こちらの頭に置いてください。」'),
('JPN', '创世纪', 1, 48, 19, 'しかし、父は拒んで言った。「分かっている。わが子よ。私には分かっている。彼もまた、一つの民となり、また大いなる者となるであろう。しかし、弟は彼よりも大きくなり、その子孫は国々に満ちるほどになるであろう。」'),
('JPN', '创世纪', 1, 48, 20, '彼はその日、彼らを祝福して言った。「おまえたちによって、イスラエルは祝福のことばを述べる。『神がおまえをエフライムやマナセのようになさるように』と。」こうして彼はエフライムをマナセの先にした。'),
('JPN', '创世纪', 1, 48, 21, 'イスラエルはヨセフに言った。「私は間もなく死ぬだろう。しかし、神はおまえたちとともにおられ、おまえたちを先祖の地に帰してくださる。'),
('JPN', '创世纪', 1, 48, 22, '私は、兄弟たちではなくおまえに、私が剣と弓でアモリ人の手から取った、あのシェケムを与えよう。」'),
('JPN', '创世纪', 1, 49, 1, 'ヤコブは息子たちを呼び寄せて言った。「集まりなさい。私は、終わりの日におまえたちに起こることを告げよう。'),
('JPN', '创世纪', 1, 49, 2, 'ヤコブの子どもたちよ、集まって聞け。おまえたちの父イスラエルに聞け。'),
('JPN', '创世纪', 1, 49, 3, 'ルベンよ、おまえはわが長子。わが力、わが活力の初穂。威厳と力強さでまさる者。'),
('JPN', '创世纪', 1, 49, 4, 'だが、おまえは水のように奔放で、おまえはほかの者にまさることはない。おまえは父の床に上り、そのとき、それを汚した。──彼は私の寝床に上ったのだ。'),
('JPN', '创世纪', 1, 49, 5, 'シメオンとレビとは兄弟、彼らの剣は暴虐の武器。'),
('JPN', '创世纪', 1, 49, 6, 'わがたましいよ、彼らの密議に加わるな。わが栄光よ、彼らの集いに連なるな。彼らは怒りに任せて人を殺し、思いのままに牛の足の筋を切った。'),
('JPN', '创世纪', 1, 49, 7, 'のろわれよ、彼らの激しい怒り、彼らの凄まじい憤りは。私はヤコブの中で彼らを引き裂き、イスラエルの中に散らそう。'),
('JPN', '创世纪', 1, 49, 8, 'ユダよ、兄弟たちはおまえをたたえる。おまえの手は敵の首の上にあり、おまえの父の子らはおまえを伏し拝む。'),
('JPN', '创世纪', 1, 49, 9, 'ユダは獅子の子。わが子よ、おまえは獲物によって成長する。雄獅子のように、雌獅子のように、うずくまり、身を伏せる。だれがこれを起こせるだろうか。'),
('JPN', '创世纪', 1, 49, 10, '王権はユダを離れず、王笏はその足の間を離れない。ついには彼がシロに来て、諸国の民は彼に従う。'),
('JPN', '创世纪', 1, 49, 11, '彼は自分のろばをぶどうの木に、雌ろばの子を良いぶどうの木につなぐ。彼は自分の衣をぶどう酒で、衣服をぶどうの汁で洗う。'),
('JPN', '创世纪', 1, 49, 12, '目はぶどう酒よりも色濃く、歯は乳よりも白い。'),
('JPN', '创世纪', 1, 49, 13, 'ゼブルンは海辺に、船の着く岸辺に住む。その境はシドンにまで至る。'),
('JPN', '创世纪', 1, 49, 14, 'イッサカルは、たくましいろば、二つの鞍袋の間に身を伏せる。'),
('JPN', '创世纪', 1, 49, 15, '彼は、休息の地が快く、その地が麗しいのを見る。しかし、肩は重荷を負ってたわみ、苦役を強いられる奴隷となる。'),
('JPN', '创世纪', 1, 49, 16, 'ダンは自分の民を、イスラエルの部族の一つとしてさばく。'),
('JPN', '创世纪', 1, 49, 17, 'ダンは道の傍らの蛇となれ。通りのわきのまむしとなれ。彼が馬のかかとをかむと、乗り手はうしろに落ちる。'),
('JPN', '创世纪', 1, 49, 18, '主よ、私はあなたの救いを待ち望む。'),
('JPN', '创世纪', 1, 49, 19, 'ガドについては、襲う者が襲うが、彼は、その者たちのかかとを襲う。'),
('JPN', '创世纪', 1, 49, 20, 'アシェルには、その食物が豊かになり、彼は王のごちそうを作り出す。'),
('JPN', '创世纪', 1, 49, 21, 'ナフタリは放たれた雌鹿。美しい子鹿を産む。'),
('JPN', '创世纪', 1, 49, 22, 'ヨセフは実を結ぶ若枝、泉のほとりの、実を結ぶ若枝。その枝は垣を越える。'),
('JPN', '创世纪', 1, 49, 23, '弓を射る者は激しく彼を攻め、彼を射て苦しめた。'),
('JPN', '创世纪', 1, 49, 24, 'しかし、彼の弓はいつも固く張られ、彼の腕はすばやい。ヤコブの力強き方の手から、そこから、イスラエルの岩である牧者が出る。'),
('JPN', '创世纪', 1, 49, 25, 'おまえを助ける、おまえの父の神によって、おまえを祝福する全能者によって、上よりの天の祝福、下に横たわる大水の祝福、乳房と胎の祝福があるように。'),
('JPN', '创世纪', 1, 49, 26, 'おまえの父の祝福は、私の親たちの祝福にまさり、永遠の丘の極みにまで及ぶ。これらがヨセフの頭の上に、兄弟たちの中から選り抜かれた者の頭の頂にあるように。'),
('JPN', '创世纪', 1, 49, 27, 'ベニヤミンは、かみ裂く狼。朝には獲物を食らい、夕には略奪したものを分ける。」'),
('JPN', '创世纪', 1, 49, 28, 'これらはすべてイスラエルの部族で、十二であった。これは、彼らの父が彼らに語ったことである。彼らを祝福したとき、それぞれにふさわしい祝福を与えたのであった。'),
('JPN', '创世纪', 1, 49, 29, 'また、ヤコブは彼らに命じた。「私は、私の民に加えられようとしている。私をヒッタイト人エフロンの畑地にある洞穴に、先祖たちとともに葬ってくれ。'),
('JPN', '创世纪', 1, 49, 30, 'その洞穴は、カナンの地のマムレに面したマクペラの畑地にあり、アブラハムがヒッタイト人エフロンから、私有の墓地とするために、畑地とともに買い取った洞穴だ。'),
('JPN', '创世纪', 1, 49, 31, 'そこにはアブラハムと妻サラが葬られ、そこにイサクと妻リベカも葬られ、そこに私はレアを葬った。'),
('JPN', '创世纪', 1, 49, 32, 'その畑地とその中にある洞穴は、ヒッタイト人たちから買ったものだ。」'),
('JPN', '创世纪', 1, 49, 33, 'ヤコブは息子たちに命じ終えると、足を床の中に入れ、息絶えて、自分の民に加えられた。'),
('JPN', '创世纪', 1, 50, 1, 'ヨセフは父の顔の上に崩れ落ちて、父のそばで泣き、父に別れの口づけをした。'),
('JPN', '创世纪', 1, 50, 2, 'ヨセフは自分のしもべである医者たちに、父をミイラにするように命じたので、医者たちはイスラエルをミイラにした。'),
('JPN', '创世纪', 1, 50, 3, 'そのために四十日を要した。ミイラにするのには、これだけの日数が必要であった。エジプトは彼のために七十日間、泣き悲しんだ。'),
('JPN', '创世纪', 1, 50, 4, '喪の期間が明けたとき、ヨセフはファラオの家の者たちに告げた。「もし私の願いを聞いてもらえるなら、どうかファラオにこう伝えてください。'),
('JPN', '创世纪', 1, 50, 5, '父は私に誓わせて、こう申しました。『私は間もなく死ぬ。私がカナンの地に掘った私の墓の中に、そこに、私を葬らなければならない。』どうか今、父を葬りに上って行かせてください。私はまた帰って参ります、と。」'),
('JPN', '创世纪', 1, 50, 6, 'ファラオは言った。「おまえの父がおまえに誓わせたとおり、上って行って、おまえの父を葬りなさい。」'),
('JPN', '创世纪', 1, 50, 7, 'それで、ヨセフは父を葬るために上って行った。彼とともに、ファラオのすべての家臣たち、ファラオの家の長老たち、エジプトの国のすべての長老たち、'),
('JPN', '创世纪', 1, 50, 8, 'ヨセフの家族全員、彼の兄弟たちとその一族が上って行った。ただし、彼らの子どもたちと羊と牛はゴシェンの地に残した。'),
('JPN', '创世纪', 1, 50, 9, 'また、戦車と騎兵も彼とともに上って行ったので、その一団は非常に大きなものであった。'),
('JPN', '创世纪', 1, 50, 10, '彼らは、ヨルダンの川向こう、ゴレン・ハ・アタデに着いて、そこで、たいへん立派で荘厳な哀悼の式を行った。ヨセフは父のため七日間、葬儀を行った。'),
('JPN', '创世纪', 1, 50, 11, 'その地の住民のカナン人は、ゴレン・ハ・アタデのこの葬儀を見て、「これはエジプトの荘厳な葬儀だ」と言った。それゆえ、その場所の名はアベル・ミツライムと呼ばれた。それはヨルダンの川向こうにある。'),
('JPN', '创世纪', 1, 50, 12, 'ヤコブの息子たちは、父が命じたとおりに父に行った。'),
('JPN', '创世纪', 1, 50, 13, '息子たちは彼をカナンの地に運び、マクペラの畑地の洞穴に葬った。それはマムレに面していて、アブラハムが私有の墓地にしようと、ヒッタイト人エフロンから畑地とともに買ったものである。'),
('JPN', '创世纪', 1, 50, 14, 'ヨセフは父を葬った後、兄弟たち、および、父を葬るために一緒に上って来たすべての者たちとともに、エジプトに戻った。'),
('JPN', '创世纪', 1, 50, 15, 'ヨセフの兄弟たちは、自分たちの父が死んだのを見たとき、「ヨセフはわれわれを恨んで、われわれが彼に犯したすべての悪に対して、仕返しをするかもしれない」と言った。'),
('JPN', '创世纪', 1, 50, 16, 'そこで、彼らはヨセフに言い送った。「あなたの父は死ぬ前に命じられました。'),
('JPN', '创世纪', 1, 50, 17, '『ヨセフにこう言いなさい。おまえの兄弟たちは、実に、おまえに悪いことをしたが、兄弟たちの背きと罪を赦してやりなさい、と。』今、どうか、父の神のしもべたちの背きを赦してください。」ヨセフは彼らのこのことばを聞いて泣いた。'),
('JPN', '创世纪', 1, 50, 18, '彼の兄弟たちも来て、彼の前にひれ伏して言った。「ご覧ください。私たちはあなたの奴隷です。」'),
('JPN', '创世纪', 1, 50, 19, 'ヨセフは言った。「恐れることはありません。どうして、私が神の代わりになることができるでしょうか。'),
('JPN', '创世纪', 1, 50, 20, 'あなたがたは私に悪を謀りましたが、神はそれを、良いことのための計らいとしてくださいました。それは今日のように、多くの人が生かされるためだったのです。'),
('JPN', '创世纪', 1, 50, 21, 'ですから、もう恐れることはありません。私は、あなたがたも、あなたがたの子どもたちも養いましょう。」このように、ヨセフは彼らを安心させ、優しく語りかけた。'),
('JPN', '创世纪', 1, 50, 22, 'ヨセフとその一族はエジプトに住み、ヨセフは百十歳まで生きた。'),
('JPN', '创世纪', 1, 50, 23, 'ヨセフはエフライムの子孫を三代まで見た。マナセの子マキルの子どもたちも生まれて、ヨセフの膝に抱かれた。'),
('JPN', '创世纪', 1, 50, 24, 'ヨセフは兄弟たちに言った。「私は間もなく死にます。しかし、神は必ずあなたがたを顧みて、あなたがたをこの地から、アブラハム、イサク、ヤコブに誓われた地へ上らせてくださいます。」'),
('JPN', '创世纪', 1, 50, 25, 'ヨセフはイスラエルの子らに誓わせて、「神は必ずあなたがたを顧みてくださいます。そのとき、あなたがたは私の遺骸をここから携え上ってください」と言った。'),
('JPN', '创世纪', 1, 50, 26, 'ヨセフは百十歳で死んだ。彼らはヨセフをエジプトでミイラにし、棺に納めた。'),
('JPN', '出埃及记', 2, 1, 1, 'さて、ヤコブとともに、それぞれ自分の家族を連れてエジプトに来た、イスラエルの息子たちの名は次のとおりである。'),
('JPN', '出埃及记', 2, 1, 2, 'ルベン、シメオン、レビ、ユダ。'),
('JPN', '出埃及记', 2, 1, 3, 'イッサカル、ゼブルン、ベニヤミン。'),
('JPN', '出埃及记', 2, 1, 4, 'ダンとナフタリ。ガドとアシェル。'),
('JPN', '出埃及记', 2, 1, 5, 'ヤコブの腰から生まれ出た者の総数は七十名であった。ヨセフはすでにエジプトにいた。'),
('JPN', '出埃及记', 2, 1, 6, 'それから、ヨセフもその兄弟たちも、またその時代の人々もみな死んだ。'),
('JPN', '出埃及记', 2, 1, 7, 'イスラエルの子らは多くの子を生んで、群れ広がり、増えて非常に強くなった。こうしてその地は彼らで満ちた。'),
('JPN', '出埃及记', 2, 1, 8, 'やがて、ヨセフのことを知らない新しい王がエジプトに起こった。'),
('JPN', '出埃及记', 2, 1, 9, '彼は民に言った。「見よ。イスラエルの民はわれわれよりも多く、また強い。'),
('JPN', '出埃及记', 2, 1, 10, 'さあ、彼らを賢く取り扱おう。彼らが多くなり、いざ戦いというときに敵側についてわれわれと戦い、この地から出て行くことがないように。」'),
('JPN', '出埃及记', 2, 1, 11, 'そこで、彼らを重い労役で苦しめようと、彼らの上に役務の監督を任命した。また、ファラオのために倉庫の町ピトムとラメセスを建てた。'),
('JPN', '出埃及记', 2, 1, 12, 'しかし、苦しめれば苦しめるほど、この民はますます増え広がったので、人々はイスラエルの子らに恐怖を抱くようになった。'),
('JPN', '出埃及记', 2, 1, 13, 'それでエジプト人は、イスラエルの子らに過酷な労働を課し、'),
('JPN', '出埃及记', 2, 1, 14, '漆喰やれんが作りの激しい労働や、畑のあらゆる労働など、彼らに課す過酷なすべての労働で、彼らの生活を苦しいものにした。'),
('JPN', '出埃及记', 2, 1, 15, 'また、エジプトの王は、ヘブル人の助産婦たちに命じた。一人の名はシフラ、もう一人の名はプアであった。'),
('JPN', '出埃及记', 2, 1, 16, '彼は言った。「ヘブル人の女の出産を助けるとき、産み台の上を見て、もし男の子なら、殺さなければならない。女の子なら、生かしておけ。」'),
('JPN', '出埃及记', 2, 1, 17, 'しかし、助産婦たちは神を恐れ、エジプトの王が命じたとおりにはしないで、男の子を生かしておいた。'),
('JPN', '出埃及记', 2, 1, 18, 'そこで、エジプトの王はその助産婦たちを呼んで言った。「なぜこのようなことをして、男の子を生かしておいたのか。」'),
('JPN', '出埃及记', 2, 1, 19, '助産婦たちはファラオに答えた。「ヘブル人の女はエジプト人の女とは違います。彼女たちは元気で、助産婦が行く前に産んでしまうのです。」'),
('JPN', '出埃及记', 2, 1, 20, '神はこの助産婦たちに良くしてくださった。そのため、この民は増えて非常に強くなった。'),
('JPN', '出埃及记', 2, 1, 21, '助産婦たちは神を恐れたので、神は彼女たちの家を栄えさせた。'),
('JPN', '出埃及记', 2, 1, 22, 'ファラオは自分のすべての民に次のように命じた。「生まれた男の子はみな、ナイル川に投げ込まなければならない。女の子はみな、生かしておかなければならない。」'),
('JPN', '出埃及记', 2, 2, 1, 'さて、レビの家のある人がレビ人の娘を妻に迎えた。'),
('JPN', '出埃及记', 2, 2, 2, '彼女は身ごもって男の子を産み、その子がかわいいのを見て、三か月間その子を隠しておいた。'),
('JPN', '出埃及记', 2, 2, 3, 'しかし、それ以上隠しきれなくなり、その子のためにパピルスのかごを取り、それに瀝青と樹脂を塗って、その子を中に入れ、ナイル川の岸の葦の茂みの中に置いた。'),
('JPN', '出埃及记', 2, 2, 4, 'その子の姉は、その子がどうなるかと思って、離れたところに立っていた。'),
('JPN', '出埃及记', 2, 2, 5, 'すると、ファラオの娘が水浴びをしようとナイルに下りて来た。侍女たちはナイルの川辺を歩いていた。彼女は葦の茂みの中にそのかごがあるのを見つけ、召使いの女を遣わして取って来させた。'),
('JPN', '出埃及记', 2, 2, 6, 'それを開けて、見ると、子どもがいた。なんと、それは男の子で、泣いていた。彼女はその子をかわいそうに思い、言った。「これはヘブル人の子どもです。」'),
('JPN', '出埃及记', 2, 2, 7, 'その子の姉はファラオの娘に言った。「私が行って、あなた様にヘブル人の中から乳母を一人呼んで参りましょうか。あなた様に代わって、その子に乳を飲ませるために。」'),
('JPN', '出埃及记', 2, 2, 8, 'ファラオの娘が「行って来ておくれ」と言ったので、少女は行き、その子の母を呼んで来た。'),
('JPN', '出埃及记', 2, 2, 9, 'ファラオの娘は母親に言った。「この子を連れて行き、私に代わって乳を飲ませてください。私が賃金を払いましょう。」それで彼女はその子を引き取って、乳を飲ませた。'),
('JPN', '出埃及记', 2, 2, 10, 'その子が大きくなったとき、母はその子をファラオの娘のもとに連れて行き、その子は王女の息子になった。王女はその子をモーセと名づけた。彼女は「水の中から、私がこの子を引き出したから」と言った。'),
('JPN', '出埃及记', 2, 2, 11, 'こうして日がたち、モーセは大人になった。彼は同胞たちのところへ出て行き、その苦役を見た。そして、自分の同胞であるヘブル人の一人を、一人のエジプト人が打っているのを見た。'),
('JPN', '出埃及记', 2, 2, 12, '彼はあたりを見回し、だれもいないのを確かめると、そのエジプト人を打ち殺し、砂の中に埋めた。'),
('JPN', '出埃及记', 2, 2, 13, '次の日、また外に出てみると、見よ、二人のヘブル人が争っていた。モーセは、悪いほうに「どうして自分の仲間を打つのか」と言った。'),
('JPN', '出埃及记', 2, 2, 14, '彼は言った。「だれがおまえを、指導者やさばき人として私たちの上に任命したのか。おまえは、あのエジプト人を殺したように、私も殺そうというのか。」そこでモーセは恐れて、きっとあのことが知られたのだと思った。'),
('JPN', '出埃及记', 2, 2, 15, 'ファラオはこのことを聞いて、モーセを殺そうと捜した。しかし、モーセはファラオのもとから逃れ、ミディアンの地に着き、井戸の傍らに座った。'),
('JPN', '出埃及记', 2, 2, 16, 'さて、ミディアンの祭司に七人の娘がいた。彼女たちは父の羊の群れに水を飲ませに来て、水を汲み、水ぶねに満たしていた。'),
('JPN', '出埃及记', 2, 2, 17, 'そのとき、羊飼いたちが来て、彼女たちを追い払った。するとモーセは立ち上がって、娘たちを助けてやり、羊の群れに水を飲ませた。'),
('JPN', '出埃及记', 2, 2, 18, '彼女たちが父レウエルのところに帰ったとき、父は言った。「どうして今日はこんなに早く帰って来たのか。」'),
('JPN', '出埃及记', 2, 2, 19, '娘たちは答えた。「一人のエジプト人が、私たちを羊飼いたちの手から助けてくれました。そのうえ、その人は私たちのために水汲みまでして、羊の群れに飲ませてくれました。」'),
('JPN', '出埃及记', 2, 2, 20, '父は娘たちに言った。「その人はどこにいるのか。どうして、その人を置いてきてしまったのか。食事を差し上げたいので、その人を呼んで来なさい。」'),
('JPN', '出埃及记', 2, 2, 21, 'モーセは心を決めて、この人のところに住むことにした。そこで、その人は娘のツィポラをモーセに与えた。'),
('JPN', '出埃及记', 2, 2, 22, '彼女は男の子を産んだ。モーセはその子をゲルショムと名づけた。「私は異国にいる寄留者だ」と言ったからである。'),
('JPN', '出埃及记', 2, 2, 23, 'それから何年もたって、エジプトの王は死んだ。イスラエルの子らは重い労働にうめき、泣き叫んだ。重い労働による彼らの叫びは神に届いた。'),
('JPN', '出埃及记', 2, 2, 24, '神は彼らの嘆きを聞き、アブラハム、イサク、ヤコブとの契約を思い起こされた。'),
('JPN', '出埃及记', 2, 2, 25, '神はイスラエルの子らをご覧になった。神は彼らをみこころに留められた。'),
('JPN', '出埃及记', 2, 3, 1, 'モーセは、ミディアンの祭司、しゅうとイテロの羊を飼っていた。彼はその群れを荒野の奥まで導いて、神の山ホレブにやって来た。'),
('JPN', '出埃及记', 2, 3, 2, 'すると主の使いが、柴の茂みのただ中の、燃える炎の中で彼に現れた。彼が見ると、なんと、燃えているのに柴は燃え尽きていなかった。'),
('JPN', '出埃及记', 2, 3, 3, 'モーセは思った。「近寄って、この大いなる光景を見よう。なぜ柴が燃え尽きないのだろう。」'),
('JPN', '出埃及记', 2, 3, 4, '主は、彼が横切って見に来るのをご覧になった。神は柴の茂みの中から彼に「モーセ、モーセ」と呼びかけられた。彼は「はい、ここにおります」と答えた。'),
('JPN', '出埃及记', 2, 3, 5, '神は仰せられた。「ここに近づいてはならない。あなたの履き物を脱げ。あなたの立っている場所は聖なる地である。」'),
('JPN', '出埃及记', 2, 3, 6, 'さらに仰せられた。「わたしはあなたの父祖の神、アブラハムの神、イサクの神、ヤコブの神である。」モーセは顔を隠した。神を仰ぎ見るのを恐れたからである。'),
('JPN', '出埃及记', 2, 3, 7, '主は言われた。「わたしは、エジプトにいるわたしの民の苦しみを確かに見、追い立てる者たちの前での彼らの叫びを聞いた。わたしは彼らの痛みを確かに知っている。'),
('JPN', '出埃及记', 2, 3, 8, 'わたしが下って来たのは、エジプトの手から彼らを救い出し、その地から、広く良い地、乳と蜜の流れる地に、カナン人、ヒッタイト人、アモリ人、ペリジ人、ヒビ人、エブス人のいる場所に、彼らを導き上るためである。'),
('JPN', '出埃及记', 2, 3, 9, '今、見よ、イスラエルの子らの叫びはわたしに届いた。わたしはまた、エジプト人が彼らを虐げている有様を見た。'),
('JPN', '出埃及记', 2, 3, 10, '今、行け。わたしは、あなたをファラオのもとに遣わす。わたしの民、イスラエルの子らをエジプトから導き出せ。」'),
('JPN', '出埃及记', 2, 3, 11, 'モーセは神に言った。「私は、いったい何者なのでしょう。ファラオのもとに行き、イスラエルの子らをエジプトから導き出さなければならないとは。」'),
('JPN', '出埃及记', 2, 3, 12, '神は仰せられた。「わたしが、あなたとともにいる。これが、あなたのためのしるしである。このわたしがあなたを遣わすのだ。あなたがこの民をエジプトから導き出すとき、あなたがたは、この山で神に仕えなければならない。」'),
('JPN', '出埃及记', 2, 3, 13, 'モーセは神に言った。「今、私がイスラエルの子らのところに行き、『あなたがたの父祖の神が、あなたがたのもとに私を遣わされた』と言えば、彼らは『その名は何か』と私に聞くでしょう。私は彼らに何と答えればよいのでしょうか。」'),
('JPN', '出埃及记', 2, 3, 14, '神はモーセに仰せられた。「わたしは『わたしはある』という者である。」また仰せられた。「あなたはイスラエルの子らに、こう言わなければならない。『わたしはある』という方が私をあなたがたのところに遣わされた、と。」'),
('JPN', '出埃及记', 2, 3, 15, '神はさらにモーセに仰せられた。「イスラエルの子らに、こう言え。『あなたがたの父祖の神、アブラハムの神、イサクの神、ヤコブの神、主が、あなたがたのところに私を遣わされた』と。これが永遠にわたしの名である。これが代々にわたり、わたしの呼び名である。'),
('JPN', '出埃及记', 2, 3, 16, '行って、イスラエルの長老たちを集めて言え。『あなたがたの父祖の神、アブラハム、イサク、ヤコブの神、主が私に現れてこう言われた。「わたしは、あなたがたのこと、またエジプトであなたがたに対してなされていることを、必ず顧みる。'),
('JPN', '出埃及记', 2, 3, 17, 'だからわたしは、あなたがたをエジプトでの苦しみから解放して、カナン人、ヒッタイト人、アモリ人、ペリジ人、ヒビ人、エブス人の地へ、乳と蜜の流れる地へ導き上ると言ったのである」と。』'),
('JPN', '出埃及记', 2, 3, 18, '彼らはあなたの声に聞き従う。あなたはイスラエルの長老たちと一緒にエジプトの王のところに行き、彼にこう言え。『ヘブル人の神、主が私たちにお会いくださいました。今、どうか私たちに荒野へ三日の道のりを行かせ、私たちの神、主にいけにえを献げさせてください。』'),
('JPN', '出埃及记', 2, 3, 19, 'しかし、エジプトの王は強いられなければあなたがたを行かせないことを、わたしはよく知っている。'),
('JPN', '出埃及记', 2, 3, 20, 'わたしはこの手を伸ばし、エジプトのただ中であらゆる不思議を行い、エジプトを打つ。その後で、彼はあなたがたを去らせる。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '出埃及记', 2, 3, 21, 'わたしは、エジプトがこの民に好意を持つようにする。あなたがたが出て行くとき、何も持たずに出て行くことはない。'),
('JPN', '出埃及记', 2, 3, 22, '女はみな、近所の女、および自分の家に身を寄せている女に、銀の飾り、金の飾り、そして衣服を求め、それを、自分の息子や娘の身に着けさせなさい。こうしてあなたがたは、エジプト人からはぎ取りなさい。」'),
('JPN', '出埃及记', 2, 4, 1, 'モーセは答えた。「ですが、彼らは私の言うことを信じず、私の声に耳を傾けないでしょう。むしろ、『主はあなたに現れなかった』と言うでしょう。」'),
('JPN', '出埃及记', 2, 4, 2, '主は彼に言われた。「あなたが手に持っているものは何か。」彼は答えた。「杖です。」'),
('JPN', '出埃及记', 2, 4, 3, 'すると言われた。「それを地に投げよ。」彼はそれを地に投げた。すると、それは蛇になった。モーセはそれから身を引いた。'),
('JPN', '出埃及记', 2, 4, 4, '主はモーセに言われた。「手を伸ばして、その尾をつかめ。」彼が手を伸ばしてそれを握ると、それは手の中で杖になった。'),
('JPN', '出埃及记', 2, 4, 5, '「これは、彼らの父祖の神、アブラハムの神、イサクの神、ヤコブの神、主があなたに現れたことを、彼らが信じるためである。」'),
('JPN', '出埃及记', 2, 4, 6, '主はまた、彼に言われた。「手を懐に入れよ。」彼は手を懐に入れた。そして出した。なんと、彼の手はツァラアトに冒され、雪のようになっていた。'),
('JPN', '出埃及记', 2, 4, 7, 'また主は言われた。「あなたの手をもう一度懐に入れよ。」そこで彼はもう一度、手を懐に入れた。そして懐から出した。なんと、それは再び自分の肉のようになっていた。'),
('JPN', '出埃及记', 2, 4, 8, '「たとえ彼らがあなたを信じず、また初めのしるしの声に聞き従わなくても、後のしるしの声は信じるであろう。'),
('JPN', '出埃及记', 2, 4, 9, 'もしも彼らがこの二つのしるしを両方とも信じず、あなたの声に聞き従わないなら、ナイル川の水を汲んで、乾いた地面に注ぎなさい。あなたがナイル川から汲んだその水は、乾いた地面の上で血となる。」'),
('JPN', '出埃及记', 2, 4, 10, 'モーセは主に言った。「ああ、わが主よ、私はことばの人ではありません。以前からそうでしたし、あなたがしもべに語られてからもそうです。私は口が重く、舌が重いのです。」'),
('JPN', '出埃及记', 2, 4, 11, '主は彼に言われた。「人に口をつけたのはだれか。だれが口をきけなくし、耳をふさぎ、目を開け、また閉ざすのか。それは、わたし、主ではないか。'),
('JPN', '出埃及记', 2, 4, 12, '今、行け。わたしがあなたの口とともにあって、あなたが語るべきことを教える。」'),
('JPN', '出埃及记', 2, 4, 13, 'すると彼は言った。「ああ、わが主よ、どうかほかの人を遣わしてください。」'),
('JPN', '出埃及记', 2, 4, 14, 'すると、主の怒りがモーセに向かって燃え上がり、こう言われた。「あなたの兄、レビ人アロンがいるではないか。わたしは彼が雄弁であることをよく知っている。見よ、彼はあなたに会いに出て来ている。あなたに会えば、心から喜ぶだろう。'),
('JPN', '出埃及记', 2, 4, 15, '彼に語り、彼の口にことばを置け。わたしはあなたの口とともにあり、また彼の口とともにあって、あなたがたがなすべきことを教える。'),
('JPN', '出埃及记', 2, 4, 16, '彼があなたに代わって民に語る。彼があなたにとって口となり、あなたは彼にとって神の代わりとなる。'),
('JPN', '出埃及记', 2, 4, 17, 'また、あなたはこの杖を手に取り、これでしるしを行わなければならない。」'),
('JPN', '出埃及记', 2, 4, 18, 'そこでモーセは行って、しゅうとイテロのもとに帰り、彼に言った。「どうか私をエジプトにいる同胞のもとに帰らせ、彼らがまだ生きながらえているかどうか、見させてください。」イテロはモーセに言った。「安心して行きなさい。」'),
('JPN', '出埃及记', 2, 4, 19, '主はミディアンでモーセに言われた。「さあ、エジプトに帰れ。あなたのいのちを取ろうとしていた者は、みな死んだ。」'),
('JPN', '出埃及记', 2, 4, 20, 'そこでモーセは妻や息子たちを連れ、彼らをろばに乗せて、エジプトの地へ帰って行った。モーセは神の杖を手に取った。'),
('JPN', '出埃及记', 2, 4, 21, '主はモーセに言われた。「あなたがエジプトに帰ったら、わたしがあなたの手に授けたすべての不思議を心に留め、それをファラオの前で行え。しかし、わたしが彼の心を頑なにするので、彼は民を去らせない。'),
('JPN', '出埃及记', 2, 4, 22, 'そのとき、あなたはファラオに言わなければならない。主はこう言われる。『イスラエルはわたしの子、わたしの長子である。'),
('JPN', '出埃及记', 2, 4, 23, 'わたしはあなたに言う。わたしの子を去らせて、彼らがわたしに仕えるようにせよ。もし去らせるのを拒むなら、見よ、わたしはあなたの子、あなたの長子を殺す。』」'),
('JPN', '出埃及记', 2, 4, 24, 'さて、途中、一夜を明かす場所でのことだった。主はモーセに会い、彼を殺そうとされた。'),
('JPN', '出埃及记', 2, 4, 25, 'そのとき、ツィポラは火打石を取って、自分の息子の包皮を切り取り、モーセの両足に付けて言った。「まことに、あなたは私には血の花婿です。」'),
('JPN', '出埃及记', 2, 4, 26, 'すると、主はモーセを放された。彼女はそのとき、割礼のゆえに「血の花婿」と言ったのである。'),
('JPN', '出埃及记', 2, 4, 27, 'さて、主はアロンに言われた。「荒野に行って、モーセに会え。」彼は行って、神の山でモーセに会い、口づけした。'),
('JPN', '出埃及记', 2, 4, 28, 'モーセは、自分を遣わすときに主が語られたことばのすべてと、彼に命じられたしるしのすべてを、アロンに告げた。'),
('JPN', '出埃及记', 2, 4, 29, 'それからモーセとアロンは行って、イスラエルの子らの長老たちをみな集めた。'),
('JPN', '出埃及记', 2, 4, 30, 'アロンは、主がモーセに語られたことばをみな語り、民の目の前でしるしを行った。'),
('JPN', '出埃及记', 2, 4, 31, '民は信じた。彼らは、主がイスラエルの子らを顧み、その苦しみをご覧になったことを聞き、ひざまずいて礼拝した。'),
('JPN', '出埃及记', 2, 5, 1, 'その後、モーセとアロンはファラオのところに行き、そして言った。「イスラエルの神、主はこう仰せられます。『わたしの民を去らせ、荒野でわたしのために祭りを行えるようにせよ。』」'),
('JPN', '出埃及记', 2, 5, 2, 'ファラオは答えた。「主とは何者だ。私がその声を聞いて、イスラエルを去らせなければならないとは。私は主を知らない。イスラエルは去らせない。」'),
('JPN', '出埃及记', 2, 5, 3, '彼らは言った。「ヘブル人の神が私たちと会ってくださいました。どうか私たちに荒野へ三日の道のりを行かせて、私たちの神、主にいけにえを献げさせてください。そうでないと、主は疫病か剣で私たちを打たれます。」'),
('JPN', '出埃及记', 2, 5, 4, 'エジプトの王は彼らに言った。「モーセとアロンよ、なぜおまえたちは、民を仕事から引き離そうとするのか。おまえたちの労役に戻れ。」'),
('JPN', '出埃及记', 2, 5, 5, 'ファラオはまた言った。「見よ、今やこの地の民は多い。だからおまえたちは、彼らに労役をやめさせようとしているのだ。」'),
('JPN', '出埃及记', 2, 5, 6, 'その日、ファラオはこの民の監督たちとかしらたちに命じた。'),
('JPN', '出埃及记', 2, 5, 7, '「おまえたちは、れんがを作るために、もはやこれまでのように民に藁を与えてはならない。彼らが行って、自分で藁を集めるようにさせよ。'),
('JPN', '出埃及记', 2, 5, 8, 'しかも、これまでどおりの量のれんがを作らせるのだ。減らしてはならない。彼らは怠け者だ。だから、『私たちの神に、いけにえを献げに行かせてください』などと言って叫んでいるのだ。'),
('JPN', '出埃及记', 2, 5, 9, 'あの者たちの労役を重くしたうえで、その仕事をやらせよ。偽りのことばに目を向けさせるな。」'),
('JPN', '出埃及记', 2, 5, 10, 'そこで、この民の監督たちとかしらたちは出て行って、民に告げた。「ファラオはこう言われる。『もうおまえたちに藁は与えない。'),
('JPN', '出埃及记', 2, 5, 11, 'おまえたちはどこへでも行って、見つけられるところから自分で藁を取って来い。労役は少しも減らすことはしない。』」'),
('JPN', '出埃及记', 2, 5, 12, 'そこで民はエジプト全土に散って、藁の代わりに刈り株を集めた。'),
('JPN', '出埃及记', 2, 5, 13, '監督たちは彼らをせき立てた。「藁があったときのように、その日その日の仕事を仕上げよ。」'),
('JPN', '出埃及记', 2, 5, 14, 'ファラオの監督たちがこの民の上に立てた、イスラエルの子らのかしらたちは、打ちたたかれてこう言われた。「なぜ、おまえたちは決められた量のれんがを、昨日も今日も、今までどおりに仕上げないのか。」'),
('JPN', '出埃及记', 2, 5, 15, 'そこで、イスラエルの子らのかしらたちは、ファラオのところに行って、叫んだ。「なぜ、あなた様はしもべどもに、このようなことをなさるのですか。'),
('JPN', '出埃及记', 2, 5, 16, 'しもべどもには藁が与えられていません。それでも、『れんがを作れ』と言われています。ご覧ください。しもべどもは打たれています。でも、いけないのはあなた様の民のほうです。」'),
('JPN', '出埃及记', 2, 5, 17, 'ファラオは言った。「おまえたちは怠け者だ。怠け者なのだ。だから『私たちの主にいけにえを献げに行かせてください』などと言っているのだ。'),
('JPN', '出埃及记', 2, 5, 18, '今すぐに行って働け。おまえたちに藁は与えない。しかし、おまえたちは決められた分のれんがを納めなければならない。」'),
('JPN', '出埃及记', 2, 5, 19, 'イスラエルの子らのかしらたちは、「おまえたちにその日その日に課せられた、れんがの量を減らしてはならない」と聞かされて、これは悪いことになったと思った。'),
('JPN', '出埃及记', 2, 5, 20, '彼らは、ファラオのところから出て来たとき、迎えに来ていたモーセとアロンに会った。'),
('JPN', '出埃及记', 2, 5, 21, '彼らは二人に言った。「主があなたがたを見て、さばかれますように。あなたがたは、ファラオとその家臣たちの目に私たちを嫌わせ、私たちを殺すため、彼らの手に剣を渡してしまったのです。」'),
('JPN', '出埃及记', 2, 5, 22, 'それでモーセは主のもとに戻り、そして言った。「主よ、なぜ、あなたはこの民をひどい目にあわせられるのですか。いったい、なぜあなたは私を遣わされたのですか。'),
('JPN', '出埃及记', 2, 5, 23, '私がファラオのところに行って、あなたの御名によって語って以来、彼はこの民を虐げています。それなのに、あなたは、あなたの民を一向に救い出そうとはなさいません。」'),
('JPN', '出埃及记', 2, 6, 1, '主はモーセに言われた。「あなたには、わたしがファラオにしようとしていることが今に分かる。彼は強いられてこの民を去らせ、強いられてこの民を自分の国から追い出すからだ。」'),
('JPN', '出埃及记', 2, 6, 2, '神はモーセに語り、彼に仰せられた。「わたしは主である。'),
('JPN', '出埃及记', 2, 6, 3, 'わたしは、アブラハム、イサク、ヤコブに全能の神として現れたが、主という名では、彼らにわたしを知らせなかった。'),
('JPN', '出埃及记', 2, 6, 4, 'わたしはまた、カナンの地、彼らがとどまった寄留の地を彼らに与えるという契約を彼らと立てた。'),
('JPN', '出埃及记', 2, 6, 5, '今わたしは、エジプトが奴隷として仕えさせているイスラエルの子らの嘆きを聞き、わたしの契約を思い起こした。'),
('JPN', '出埃及记', 2, 6, 6, 'それゆえ、イスラエルの子らに言え。『わたしは主である。わたしはあなたがたをエジプトの苦役から導き出す。あなたがたを重い労働から救い出し、伸ばされた腕と大いなるさばきによって贖う。'),
('JPN', '出埃及记', 2, 6, 7, 'わたしはあなたがたを取ってわたしの民とし、わたしはあなたがたの神となる。あなたがたは、わたしがあなたがたの神、主であり、あなたがたをエジプトでの苦役から導き出す者であることを知る。'),
('JPN', '出埃及记', 2, 6, 8, 'わたしは、アブラハム、イサク、ヤコブに与えると誓ったその地にあなたがたを連れて行き、そこをあなたがたの所有地として与える。わたしは主である。』」'),
('JPN', '出埃及记', 2, 6, 9, 'モーセはこのようにイスラエルの子らに語ったが、彼らは失意と激しい労働のために、モーセの言うことを聞くことができなかった。'),
('JPN', '出埃及记', 2, 6, 10, '主はモーセに告げられた。'),
('JPN', '出埃及记', 2, 6, 11, '「エジプトの王ファラオのところへ行って、イスラエルの子らをその国から去らせるように告げよ。」'),
('JPN', '出埃及记', 2, 6, 12, 'しかし、モーセは主の前で訴えた。「ご覧ください。イスラエルの子らは私の言うことを聞きませんでした。どうしてファラオが私の言うことを聞くでしょうか。しかも、私は口べたなのです。」'),
('JPN', '出埃及记', 2, 6, 13, '主はモーセとアロンに語り、イスラエルの子らをエジプトの地から導き出すよう、イスラエルの子らとエジプトの王ファラオについて彼らに命じられた。'),
('JPN', '出埃及记', 2, 6, 14, '彼らの一族のかしらたちは次のとおりである。イスラエルの長子ルベンの子はハノク、パル、ヘツロン、カルミで、これらがルベン族である。'),
('JPN', '出埃及记', 2, 6, 15, 'シメオンの子はエムエル、ヤミン、オハデ、ヤキン、ツォハル、およびカナンの女から生まれたシャウルで、これらがシメオン族である。'),
('JPN', '出埃及记', 2, 6, 16, '家系にしたがって記すと、レビの子の名は次のとおり。ゲルション、ケハテ、メラリ。レビが生きた年月は百三十七年であった。'),
('JPN', '出埃及记', 2, 6, 17, 'ゲルションの子は、氏族ごとに言うと、リブニとシムイである。'),
('JPN', '出埃及记', 2, 6, 18, 'ケハテの子はアムラム、イツハル、ヘブロン、ウジエルである。ケハテが生きた年月は百三十三年であった。'),
('JPN', '出埃及记', 2, 6, 19, 'メラリの子はマフリとムシである。これらが、彼らの家系によるレビ人の諸氏族である。'),
('JPN', '出埃及记', 2, 6, 20, 'アムラムは自分の叔母ヨケベデを妻にした。彼女はアロンとモーセを産んだ。アムラムが生きた年月は百三十七年であった。'),
('JPN', '出埃及记', 2, 6, 21, 'イツハルの子はコラ、ネフェグ、ジクリである。'),
('JPN', '出埃及记', 2, 6, 22, 'ウジエルの子はミシャエル、エルツァファン、シテリである。'),
('JPN', '出埃及记', 2, 6, 23, 'アロンは、アミナダブの娘でナフションの妹であるエリシェバを妻にし、彼女はアロンにナダブとアビフ、エルアザルとイタマルを産んだ。'),
('JPN', '出埃及记', 2, 6, 24, 'コラの子はアシル、エルカナ、アビアサフで、これらがコラ人の諸氏族である。'),
('JPN', '出埃及记', 2, 6, 25, 'アロンの子エルアザルは、プティエルの娘の一人を妻とし、彼女はピネハスを産んだ。これらがレビ人の諸氏族の、一族のかしらたちである。'),
('JPN', '出埃及记', 2, 6, 26, 'このアロンとモーセに主は、「イスラエルの子らを軍団ごとにエジプトの地から導き出せ」と言われたのであった。'),
('JPN', '出埃及记', 2, 6, 27, 'エジプトの王ファラオに向かって、イスラエルの子らをエジプトから導き出すようにと言ったのも、このモーセとアロンである。'),
('JPN', '出埃及记', 2, 6, 28, '主がエジプトの地でモーセに語られたときに、'),
('JPN', '出埃及记', 2, 6, 29, '主はモーセに告げられた。「わたしは主である。わたしがあなたに語ることをみな、エジプトの王ファラオに告げよ。」'),
('JPN', '出埃及记', 2, 6, 30, 'しかし、モーセは主の前で言った。「ご覧ください。私は口べたです。どうしてファラオが私の言うことを聞くでしょうか。」'),
('JPN', '出埃及记', 2, 7, 1, '主はモーセに言われた。「見よ、わたしはあなたをファラオにとって神とする。あなたの兄アロンがあなたの預言者となる。'),
('JPN', '出埃及记', 2, 7, 2, 'あなたはわたしの命じることを、ことごとく告げなければならない。あなたの兄アロンはファラオに、イスラエルの子らをその地から去らせるようにと告げなければならない。'),
('JPN', '出埃及记', 2, 7, 3, 'わたしはファラオの心を頑なにし、わたしのしるしと不思議をエジプトの地で数多く行う。'),
('JPN', '出埃及记', 2, 7, 4, 'しかし、ファラオはあなたがたの言うことを聞き入れない。そこで、わたしはエジプトに手を下し、大いなるさばきによって、わたしの軍団、わたしの民イスラエルの子らをエジプトの地から導き出す。'),
('JPN', '出埃及记', 2, 7, 5, 'わたしが手をエジプトの上に伸ばし、イスラエルの子らを彼らのただ中から導き出すとき、エジプトは、わたしが主であることを知る。」'),
('JPN', '出埃及记', 2, 7, 6, 'そこでモーセとアロンはそのように行った。主が彼らに命じられたとおりに行った。'),
('JPN', '出埃及记', 2, 7, 7, '彼らがファラオに語ったとき、モーセは八十歳、アロンは八十三歳であった。'),
('JPN', '出埃及记', 2, 7, 8, 'また主はモーセとアロンに言われた。'),
('JPN', '出埃及记', 2, 7, 9, '「ファラオがあなたがたに『おまえたちの不思議を行え』と言ったら、あなたはアロンに『その杖を取って、ファラオの前に投げよ』と言え。それは蛇になる。」'),
('JPN', '出埃及记', 2, 7, 10, 'モーセとアロンはファラオのところに行き、主が命じられたとおりに行った。アロンは自分の杖をファラオとその家臣たちの前に投げた。すると、それは蛇になった。'),
('JPN', '出埃及记', 2, 7, 11, 'そこで、ファラオも知恵のある者と呪術者を呼び寄せた。これらエジプトの呪法師たちもまた、彼らの秘術を使って同じことをした。'),
('JPN', '出埃及记', 2, 7, 12, '彼らがそれぞれ自分の杖を投げると、それは蛇になった。しかし、アロンの杖は彼らの杖を吞み込んだ。'),
('JPN', '出埃及记', 2, 7, 13, 'それでもファラオの心は頑なになり、彼らの言うことを聞き入れなかった。主が言われたとおりであった。'),
('JPN', '出埃及记', 2, 7, 14, '主はモーセに言われた。「ファラオの心は硬く、民を去らせることを拒んでいる。'),
('JPN', '出埃及记', 2, 7, 15, 'あなたは朝、ファラオのところへ行け。見よ、彼は水辺に出て来る。あなたはナイル川の岸に立って、彼を迎えよ。そして、蛇に変わったその杖を手に取り、'),
('JPN', '出埃及记', 2, 7, 16, '彼に言え。『ヘブル人の神、主が私をあなたに遣わして言われました。わたしの民を去らせ、彼らが荒野でわたしに仕えるようにせよ、と。しかし、ご覧ください。あなたは今までお聞きになりませんでした。'),
('JPN', '出埃及记', 2, 7, 17, '主はこう言われます。あなたは、次のことによって、わたしが主であることを知る、と。ご覧ください。私は手に持っている杖でナイル川の水を打ちます。すると、水は血に変わり、'),
('JPN', '出埃及记', 2, 7, 18, 'ナイル川の魚は死に、ナイル川は臭くなります。それで、エジプト人はナイル川の水を飲むのに耐えられなくなります。』」'),
('JPN', '出埃及记', 2, 7, 19, '主はモーセに言われた。「アロンに言え。『あなたの杖を取り、手をエジプトの水の上、その川、水路、池、すべての貯水池の上に伸ばしなさい。そうすれば、それらは血となり、エジプト全土で木の器や石の器にも血があるようになる。』」'),
('JPN', '出埃及记', 2, 7, 20, 'モーセとアロンは主が命じられたとおりに行った。モーセはファラオとその家臣たちの目の前で杖を上げ、ナイル川の水を打った。すると、ナイル川の水はすべて血に変わった。'),
('JPN', '出埃及记', 2, 7, 21, 'ナイル川の魚は死に、ナイル川は臭くなり、エジプト人はナイル川の水を飲めなくなった。エジプト全土にわたって血があった。'),
('JPN', '出埃及记', 2, 7, 22, 'しかし、エジプトの呪法師たちも彼らの秘術を使って同じことをした。それで、ファラオの心は頑なになり、彼らの言うことを聞き入れなかった。主が言われたとおりであった。'),
('JPN', '出埃及记', 2, 7, 23, 'ファラオは身を翻して自分の家に入り、このことにも心を向けなかった。'),
('JPN', '出埃及记', 2, 7, 24, '全エジプトは飲み水を求めて、ナイル川の周辺を掘った。ナイル川の水が飲めなかったからである。'),
('JPN', '出埃及记', 2, 7, 25, '主がナイル川を打たれてから七日が満ちた。'),
('JPN', '出埃及记', 2, 8, 1, '主はモーセに言われた。「ファラオのもとに行って言え。主はこう言われる。『わたしの民を去らせ、彼らがわたしに仕えるようにせよ。'),
('JPN', '出埃及记', 2, 8, 2, 'もしあなたが去らせることを拒むなら、見よ、わたしはあなたの全領土を蛙によって打つ。'),
('JPN', '出埃及记', 2, 8, 3, 'ナイル川には蛙が群がり、這い上がって来て、あなたの家に、寝室に入って、寝台に上り、またあなたの家臣の家に、あなたの民の中に、さらに、あなたのかまど、こね鉢に入り込む。'),
('JPN', '出埃及记', 2, 8, 4, 'こうして蛙が、あなたと、あなたの民とすべての家臣の上に這い上がる。』」'),
('JPN', '出埃及记', 2, 8, 5, '主はモーセに言われた。「アロンに言え。『杖を持って、あなたの手を川の上、水路の上、池の上に伸ばせ。そして蛙をエジプトの地に這い上がらせよ』と。」'),
('JPN', '出埃及记', 2, 8, 6, 'アロンが手をエジプトの水の上に伸ばすと、蛙が這い上がって、エジプトの地をおおった。'),
('JPN', '出埃及记', 2, 8, 7, '呪法師たちも彼らの秘術を使って、同じように行った。彼らは蛙をエジプトの地の上に這い上がらせた。'),
('JPN', '出埃及记', 2, 8, 8, 'ファラオはモーセとアロンを呼び寄せて言った。「私と私の民のところから蛙を除くように、主に祈れ。そうすれば、私はこの民を去らせる。主にいけにえを献げるがよい。」'),
('JPN', '出埃及记', 2, 8, 9, 'モーセはファラオに言った。「蛙があなたとあなたの家から断たれ、ナイル川だけに残るようにするため、私が、あなたと、あなたの家臣と民のために祈るので、いつがよいかを指示してください。」'),
('JPN', '出埃及记', 2, 8, 10, 'ファラオが「明日」と言ったので、モーセは言った。「あなたのことばどおりになりますように。それは、あなたが、私たちの神、主のような方はほかにいないことを知るためです。'),
('JPN', '出埃及记', 2, 8, 11, '蛙は、あなたと、あなたの家、家臣、民から離れて、ナイル川だけに残るでしょう。」'),
('JPN', '出埃及记', 2, 8, 12, 'こうしてモーセとアロンはファラオのもとから出て行った。モーセは、自分がファラオに約束した蛙のことで主に叫んだ。'),
('JPN', '出埃及记', 2, 8, 13, '主がモーセのことばどおりにされたので、蛙は家と庭と畑から死に絶えた。'),
('JPN', '出埃及记', 2, 8, 14, '人々はそれらを山のように積み上げたので、地は悪臭で満ちた。'),
('JPN', '出埃及记', 2, 8, 15, 'ところが、ファラオは一息つけると思うと、心を硬くし、彼らの言うことを聞き入れなかった。主が言われたとおりであった。'),
('JPN', '出埃及记', 2, 8, 16, '主はモーセに言われた。「アロンに言え。『あなたの杖を伸ばして、地のちりを打て。そうすれば、ちりはエジプトの全土でブヨとなる』と。」'),
('JPN', '出埃及记', 2, 8, 17, '彼らはそのように行った。アロンは杖を持って手を伸ばし、地のちりを打った。すると、ブヨが人や家畜に付いた。地のちりはみな、エジプト全土でブヨとなった。'),
('JPN', '出埃及记', 2, 8, 18, '呪法師たちも、ブヨを出そうと彼らの秘術を使って同じようにしたが、できなかった。ブヨは人や家畜に付いた。'),
('JPN', '出埃及记', 2, 8, 19, '呪法師たちはファラオに「これは神の指です」と言った。しかし、ファラオの心は頑なになり、彼らの言うことを聞き入れなかった。主が言われたとおりであった。'),
('JPN', '出埃及记', 2, 8, 20, '主はモーセに言われた。「明日の朝早く、ファラオの前に出よ。見よ、彼は水辺に出て来る。彼にこう言え。主はこう言われる。『わたしの民を去らせ、彼らがわたしに仕えるようにせよ。'),
('JPN', '出埃及记', 2, 8, 21, 'もしもわたしの民を去らせないなら、わたしは、あなたと、あなたの家臣と民、そしてあなたの家々にアブの群れを送る。エジプトの家々も、彼らのいる地面も、アブの群れで満ちる。'),
('JPN', '出埃及记', 2, 8, 22, 'わたしはその日、わたしの民がとどまっているゴシェンの地を特別に扱い、そこにはアブの群れがいないようにする。こうしてあなたは、わたしがその地のただ中にあって主であることを知る。'),
('JPN', '出埃及记', 2, 8, 23, 'わたしは、わたしの民をあなたの民と区別して、贖いをする。明日、このしるしが起こる。』」'),
('JPN', '出埃及记', 2, 8, 24, '主はそのようにされた。おびただしいアブの群れが、ファラオの家とその家臣の家に入って来た。エジプトの全土にわたり、地はアブの群れによって荒れ果てた。'),
('JPN', '出埃及记', 2, 8, 25, 'ファラオはモーセとアロンを呼び寄せて言った。「さあ、この国の中でおまえたちの神にいけにえを献げよ。」'),
('JPN', '出埃及记', 2, 8, 26, 'モーセは答えた。「それは、ふさわしいことではありません。なぜなら私たちは、私たちの神、主に、エジプト人の忌み嫌うものを、いけにえとして献げるからです。もし私たちがエジプト人の忌み嫌うものを、彼らの目の前でいけにえとして献げるなら、彼らは私たちを石で打ち殺しはしないでしょうか。'),
('JPN', '出埃及记', 2, 8, 27, '私たちは、主が私たちに言われたとおり、荒野へ三日の道のりを行って、私たちの神、主にいけにえを献げなければなりません。」'),
('JPN', '出埃及记', 2, 8, 28, 'ファラオは言った。「では、おまえたちを去らせよう。おまえたちは荒野で、おまえたちの神、主にいけにえを献げるがよい。ただ、決して遠くへ行ってはならない。私のために祈ってくれ。」'),
('JPN', '出埃及记', 2, 8, 29, 'モーセは言った。「今、私はあなたのもとから出て行き、主に祈ります。明日、アブが、ファラオとその家臣と民から離れます。ただ、ファラオは、民が主にいけにえを献げるために去ることを阻んで、再び欺くことなどありませんように。」'),
('JPN', '出埃及记', 2, 8, 30, 'モーセはファラオのもとから出て行って、主に祈った。'),
('JPN', '出埃及记', 2, 8, 31, '主はモーセのことばどおりにされた。アブは一匹残らず、ファラオとその家臣、および民から離れた。'),
('JPN', '出埃及记', 2, 8, 32, 'しかし、ファラオはまたも心を硬くし、民を去らせなかった。'),
('JPN', '出埃及记', 2, 9, 1, '主はモーセに言われた。「ファラオのところに行って、彼に言え。ヘブル人の神、主はこう言われる。『わたしの民を去らせ、彼らがわたしに仕えるようにせよ。'),
('JPN', '出埃及记', 2, 9, 2, 'もしあなたが去らせることを拒み、なおも彼らをとどめておくなら、'),
('JPN', '出埃及记', 2, 9, 3, '見よ、主の手が、野にいるあなたの家畜、馬、ろば、らくだ、牛、羊の上に下り、非常に重い疫病が起こる。'),
('JPN', '出埃及记', 2, 9, 4, 'しかし、主はイスラエルの家畜とエジプトの家畜を区別するので、イスラエルの子らの家畜は一頭も死なない。』」'),
('JPN', '出埃及记', 2, 9, 5, 'また、主は時を定めて言われた。「明日、主がこの地でこのことを行う。」'),
('JPN', '出埃及记', 2, 9, 6, '主は翌日そのようにされた。エジプトの家畜はことごとく死んだが、イスラエルの子らの家畜は一頭も死ななかった。'),
('JPN', '出埃及记', 2, 9, 7, 'ファラオは使いを送った。すると見よ、イスラエルの家畜は一頭も死んでいなかった。それでもファラオの心は硬く、民を去らせなかった。'),
('JPN', '出埃及记', 2, 9, 8, '主はモーセとアロンに言われた。「あなたがたは、かまどのすすを両手いっぱいに取れ。モーセはファラオの前で、それを天に向けてまき散らせ。'),
('JPN', '出埃及记', 2, 9, 9, 'それはエジプト全土にわたって、ほこりとなり、エジプト全土で人と家畜に付き、うみの出る腫れものとなる。」'),
('JPN', '出埃及记', 2, 9, 10, 'それで彼らは、かまどのすすを取ってファラオの前に立ち、モーセはそれを天に向けてまき散らした。すると、それは人と家畜に付き、うみの出る腫れものとなった。'),
('JPN', '出埃及记', 2, 9, 11, '呪法師たちは、腫れもののためにモーセの前に立てなかった。腫れものが呪法師たちとすべてのエジプト人にできたからである。'),
('JPN', '出埃及记', 2, 9, 12, 'しかし、主はファラオの心を頑なにされたので、ファラオは二人の言うことを聞き入れなかった。主がモーセに言われたとおりであった。'),
('JPN', '出埃及记', 2, 9, 13, '主はモーセに言われた。「明日の朝早く、ファラオの前に立ち、彼に言え。ヘブル人の神、主はこう言われる。『わたしの民を去らせ、彼らがわたしに仕えるようにせよ。'),
('JPN', '出埃及记', 2, 9, 14, '今度、わたしは、あなた自身とあなたの家臣と民に、わたしのすべての災害を送る。わたしのような者が地のどこにもいないことを、あなたが知るようになるためである。'),
('JPN', '出埃及记', 2, 9, 15, '実に今でも、わたしが手を伸ばし、あなたとあなたの民を疫病で打つなら、あなたは地から消し去られる。'),
('JPN', '出埃及记', 2, 9, 16, 'しかし、このことのために、わたしはあなたを立てておいた。わたしの力をあなたに示すため、そうして、わたしの名を全地に知らしめるためである。'),
('JPN', '出埃及记', 2, 9, 17, 'あなたはなお、わたしの民に向かっておごり高ぶり、彼らを去らせようとしない。'),
('JPN', '出埃及记', 2, 9, 18, '見よ。明日の今ごろ、わたしは、国が始まってから今に至るまで、エジプトになかったような非常に激しい雹を降らせる。'),
('JPN', '出埃及记', 2, 9, 19, 'さあ今、使いを送って、あなたの家畜と、野にいるあなたのすべてのものを避難させよ。野に残されて家に連れ戻されなかった人や家畜はみな、雹に打たれて死ぬ。』」'),
('JPN', '出埃及记', 2, 9, 20, 'ファラオの家臣のうちで主のことばを恐れた者は、しもべたちと家畜を家に避難させた。'),
('JPN', '出埃及记', 2, 9, 21, 'しかし、主のことばを心に留めなかった者は、しもべたちと家畜をそのまま野に残しておいた。'),
('JPN', '出埃及记', 2, 9, 22, 'そこで主はモーセに言われた。「あなたの手を天に向けて伸ばせ。そうすれば、エジプト全土にわたって、人にも家畜にも、またエジプトの地のすべての野の草の上にも、雹が降る。」'),
('JPN', '出埃及记', 2, 9, 23, 'モーセが杖を天に向けて伸ばすと、主は雷と雹を送ったので、火が地に向かって走った。こうして主はエジプトの地に雹を降らせた。'),
('JPN', '出埃及记', 2, 9, 24, '雹が降り、火が雹のただ中をひらめき渡った。それは、エジプトの地で国が始まって以来どこにもなかったような、きわめて激しいものであった。'),
('JPN', '出埃及记', 2, 9, 25, '雹はエジプト全土にわたって、人から家畜に至るまで、野にいるすべてのものを打った。またその雹は、あらゆる野の草も打った。野の木もことごとく打ち砕いた。'),
('JPN', '出埃及记', 2, 9, 26, 'ただ、イスラエルの子らが住むゴシェンの地には、雹は降らなかった。'),
('JPN', '出埃及记', 2, 9, 27, 'ファラオは人を遣わしてモーセとアロンを呼び寄せ、彼らに言った。「今度は私が間違っていた。主が正しく、私と私の民が悪かった。'),
('JPN', '出埃及记', 2, 9, 28, '主に祈ってくれ。神の雷と雹は、もうたくさんだ。私はおまえたちを去らせよう。おまえたちはもう、とどまっていてはならない。」'),
('JPN', '出埃及记', 2, 9, 29, 'モーセは彼に言った。「私が町を出たら、すぐに主に向かって手を伸べ広げましょう。雷はやみ、雹はもう降らなくなります。この地が主のものであることをあなたが知るためです。'),
('JPN', '出埃及记', 2, 9, 30, 'しかし、あなたとあなたの家臣はまだ、神である主を恐れていないことを、私はよく知っています。」'),
('JPN', '出埃及记', 2, 9, 31, '亜麻と大麦は打ち倒されていた。大麦は穂を出し、亜麻はつぼみをつけていたからである。'),
('JPN', '出埃及记', 2, 9, 32, 'しかし、小麦と裸麦は打ち倒されていなかった。これらは実るのが遅いからである。'),
('JPN', '出埃及记', 2, 9, 33, 'モーセはファラオのもとを去り、町を出て、主に向かって両手を伸べ広げた。すると雷と雹はやみ、雨はもう地に降らなくなった。'),
('JPN', '出埃及记', 2, 9, 34, 'ファラオは雨と雹と雷がやんだのを見て、またも罪に身を任せ、彼とその家臣たちはその心を硬くした。'),
('JPN', '出埃及记', 2, 9, 35, 'ファラオは心を頑なにし、イスラエルの子らを去らせなかった。主がモーセを通して言われたとおりであった。'),
('JPN', '出埃及记', 2, 10, 1, '主はモーセに言われた。「ファラオのところに行け。わたしは彼とその家臣たちの心を硬くした。それは、わたしが、これらのしるしを彼らの中で行うためである。'),
('JPN', '出埃及记', 2, 10, 2, 'また、わたしがエジプトに対して力を働かせたあのこと、わたしが彼らの中で行ったしるしを、あなたが息子や孫に語って聞かせるためである。こうしてあなたがたは、わたしが主であることを知る。」'),
('JPN', '出埃及记', 2, 10, 3, 'モーセとアロンはファラオのところに行き、彼に向かって言った。「ヘブル人の神、主はこう言われます。『いつまで、わたしの前に身を低くするのを拒むのか。わたしの民を去らせ、彼らがわたしに仕えるようにせよ。'),
('JPN', '出埃及记', 2, 10, 4, 'もしあなたが、わたしの民を去らせることを拒むなら、見よ、わたしは明日、いなごをあなたの領土に送る。'),
('JPN', '出埃及记', 2, 10, 5, 'いなごが地の面をおおい、地は見えなくなる。また、雹の害を免れてあなたがたに残されているものを食い尽くし、野に生えているあなたがたの木をみな食い尽くし、'),
('JPN', '出埃及记', 2, 10, 6, 'あなたの家とすべての家臣の家、および全エジプトの家に満ちる。これは、あなたの先祖も、またその先祖も、彼らがこの土地にあった日から今日に至るまで、見たことがないものである。』」こうして彼は身を翻してファラオのもとから出て行った。'),
('JPN', '出埃及记', 2, 10, 7, '家臣たちはファラオに言った。「この男は、いつまで私たちを陥れるのでしょうか。この者たちを去らせ、彼らの神、主に仕えさせてください。エジプトが滅びるのが、まだお分かりにならないのですか。」'),
('JPN', '出埃及记', 2, 10, 8, 'モーセとアロンはファラオのところに連れ戻された。ファラオは彼らに言った。「行け。おまえたちの神、主に仕えよ。だが、行くのはだれとだれか。」'),
('JPN', '出埃及记', 2, 10, 9, 'モーセは答えた。「若い者も年寄りも一緒に行きます。息子たちも娘たちも、羊の群れも牛の群れも一緒に行きます。私たちは主の祭りをするのですから。」'),
('JPN', '出埃及记', 2, 10, 10, 'ファラオは彼らに言った。「私がおまえたちとおまえたちの妻子を行かせるようなときには、主がおまえたちとともにあるように、とでも言おう。だが、見ろ。悪意がおまえたちの顔に表れている。'),
('JPN', '出埃及记', 2, 10, 11, 'そうはさせない。さあ、壮年の男子だけが行って、主に仕えよ。それが、おまえたちが求めていることではないか。」こうして彼らはファラオの前から追い出された。'),
('JPN', '出埃及记', 2, 10, 12, '主はモーセに言われた。「あなたの手をエジプトの地の上に伸ばし、いなごの大群がエジプトの地を襲い、その国のあらゆる草木、雹の害を免れたすべてのものを食い尽くすようにせよ。」'),
('JPN', '出埃及记', 2, 10, 13, 'モーセはエジプトの地の上に杖を伸ばした。主は終日終夜、その地の上に東風を吹かせた。朝になると東風がいなごの大群を運んで来た。'),
('JPN', '出埃及记', 2, 10, 14, 'いなごの大群はエジプト全土を襲い、エジプト全域にとどまった。これは、かつてなく、この後もないほどおびただしいいなごの大群だった。'),
('JPN', '出埃及记', 2, 10, 15, 'それらが全地の表面をおおったので、地は暗くなり、いなごは地の草と、雹の害を免れた木の実をすべて食い尽くした。エジプト全土で、木や野の草に少しの緑も残らなかった。'),
('JPN', '出埃及记', 2, 10, 16, 'ファラオは急いでモーセとアロンを呼んで言った。「私は、おまえたちの神、主とおまえたちに対して過ちを犯した。'),
('JPN', '出埃及记', 2, 10, 17, 'どうか今、もう一度だけ私の罪を見逃してくれ。おまえたちの神、主に、こんな死だけは取り去ってくれるよう祈ってくれ。」'),
('JPN', '出埃及记', 2, 10, 18, 'モーセはファラオのところから出て、主に祈った。'),
('JPN', '出埃及记', 2, 10, 19, 'すると主は風向きを変え、非常に強い、海からの風とされた。風はいなごを吹き上げ、葦の海に追いやった。エジプト全域に一匹のいなごも残らなかった。'),
('JPN', '出埃及记', 2, 10, 20, 'しかし、主がファラオの心を頑なにされたので、彼はイスラエルの子らを去らせなかった。'),
('JPN', '出埃及记', 2, 10, 21, '主はモーセに言われた。「あなたの手を天に向けて伸ばし、闇がエジプトの地の上に降りて来て、闇にさわれるほどにせよ。」'),
('JPN', '出埃及记', 2, 10, 22, 'モーセが天に向けて手を伸ばすと、エジプト全土は三日間、真っ暗闇となった。'),
('JPN', '出埃及记', 2, 10, 23, '人々は三日間、互いに見ることも、自分のいる場所から立つこともできなかった。しかし、イスラエルの子らのすべてには、住んでいる所に光があった。'),
('JPN', '出埃及记', 2, 10, 24, 'ファラオはモーセを呼んで言った。「行け。主に仕えるがよい。ただ、おまえたちの羊と牛は残しておけ。妻子はおまえたちと一緒に行ってもよい。」'),
('JPN', '出埃及记', 2, 10, 25, 'モーセは言った。「あなた自身が、いけにえと全焼のささげ物を直接私たちに下さって、私たちが、自分たちの神、主にいけにえを献げられるようにしなければなりません。'),
('JPN', '出埃及记', 2, 10, 26, '私たちの家畜も私たちと一緒に行きます。ひづめ一つ残すことはできません。私たちの神、主に仕えるために、家畜の中から選ばなければならないからです。しかも、あちらに着くまでは、どれをもって主に仕えるべきか分からないのです。」'),
('JPN', '出埃及记', 2, 10, 27, 'しかし、主がファラオの心を頑なにされたので、ファラオは彼らを去らせようとはしなかった。'),
('JPN', '出埃及记', 2, 10, 28, 'ファラオは彼に言った。「私のところから出て行け。私の顔を二度と見ないように気をつけろ。おまえが私の顔を見たら、その日に、おまえは死ななければならない。」'),
('JPN', '出埃及记', 2, 10, 29, 'モーセは言った。「けっこうです。私はもう二度とあなたのお顔を見ることはありません。」'),
('JPN', '出埃及记', 2, 11, 1, '主はモーセに言われた。「わたしはファラオとエジプトの上に、もう一つのわざわいを下す。その後で彼は、あなたがたをここから去らせる。彼があなたがたを去らせるときには、本当に一人残らず、あなたがたをここから追い出す。'),
('JPN', '出埃及记', 2, 11, 2, 'さあ、民に言って聞かせよ。男は隣の男に、女は隣の女に、銀の飾りや金の飾りを求めるように。」'),
('JPN', '出埃及记', 2, 11, 3, '主は、エジプトがこの民に好意を持つようにされた。モーセその人も、エジプトの地でファラオの家臣と民にたいへん尊敬された。'),
('JPN', '出埃及记', 2, 11, 4, 'モーセは言った。「主はこう言われます。『真夜中ごろ、わたしはエジプトの中に出て行く。'),
('JPN', '出埃及记', 2, 11, 5, 'エジプトの地の長子は、王座に着いているファラオの長子から、ひき臼のうしろにいる女奴隷の長子、それに家畜の初子に至るまで、みな死ぬ。'),
('JPN', '出埃及记', 2, 11, 6, 'そして、エジプト全土にわたって大きな叫びが起こる。このようなことは、かつてなく、また二度とない。』'),
('JPN', '出埃及记', 2, 11, 7, 'しかし、イスラエルの子らに対しては、犬でさえ、人だけでなく家畜にも、だれに対してもうなりはしません。こうして主がエジプトとイスラエルを区別されることを、あなたがたは知るようになります。'),
('JPN', '出埃及记', 2, 11, 8, 'あなたのこの家臣たちはみな、私のところに下って来て、私にひれ伏し、『あなたもあなたに従う民もみな、出て行ってください』と言うでしょう。その後私は出て行きます。」こうして、モーセは怒りに燃えてファラオのところから出て行った。'),
('JPN', '出埃及记', 2, 11, 9, '主はモーセに言われた。「ファラオはあなたがたの言うことを聞き入れない。わたしの奇跡がエジプトの地で大いなるものとなるためである。」'),
('JPN', '出埃及记', 2, 11, 10, 'モーセとアロンは、ファラオの前でこれらの奇跡をすべて行った。主はファラオの心を頑なにされ、ファラオはイスラエルの子らを自分の国から去らせなかった。'),
('JPN', '出埃及记', 2, 12, 1, '主はエジプトの地でモーセとアロンに言われた。'),
('JPN', '出埃及记', 2, 12, 2, '「この月をあなたがたの月の始まりとし、これをあなたがたの年の最初の月とせよ。'),
('JPN', '出埃及记', 2, 12, 3, 'イスラエルの全会衆に次のように告げよ。この月の十日に、それぞれが一族ごとに羊を、すなわち家ごとに羊を用意しなさい。'),
('JPN', '出埃及记', 2, 12, 4, 'もしその家族が羊一匹の分より少ないのであれば、その人はすぐ隣の家の人と、人数に応じて取り分けなさい。一人ひとりが食べる分量に応じて、その羊を分けなければならない。'),
('JPN', '出埃及记', 2, 12, 5, 'あなたがたの羊は、傷のない一歳の雄でなければならない。それを子羊かやぎのうちから取らなければならない。'),
('JPN', '出埃及记', 2, 12, 6, 'あなたがたは、この月の十四日まで、それをよく見守る。そしてイスラエルの会衆の集会全体は夕暮れにそれを屠り、'),
('JPN', '出埃及记', 2, 12, 7, 'その血を取り、羊を食べる家々の二本の門柱と鴨居に塗らなければならない。'),
('JPN', '出埃及记', 2, 12, 8, 'そして、その夜、その肉を食べる。それを火で焼いて、種なしパンと苦菜を添えて食べなければならない。'),
('JPN', '出埃及记', 2, 12, 9, '生のままで、または、水に入れて煮て食べてはならない。その頭も足も内臓も火で焼かなければならない。'),
('JPN', '出埃及记', 2, 12, 10, 'それを朝まで残してはならない。朝まで残ったものは燃やさなければならない。'),
('JPN', '出埃及记', 2, 12, 11, 'あなたがたは、次のようにしてそれを食べなければならない。腰の帯を固く締め、足に履き物をはき、手に杖を持って、急いで食べる。これは主への過越のいけにえである。'),
('JPN', '出埃及记', 2, 12, 12, 'その夜、わたしはエジプトの地を巡り、人から家畜に至るまで、エジプトの地のすべての長子を打ち、また、エジプトのすべての神々にさばきを下す。わたしは主である。'),
('JPN', '出埃及记', 2, 12, 13, 'その血は、あなたがたがいる家の上で、あなたがたのためにしるしとなる。わたしはその血を見て、あなたがたのところを過ぎ越す。わたしがエジプトの地を打つとき、滅ぼす者のわざわいは、あなたがたには起こらない。'),
('JPN', '出埃及记', 2, 12, 14, 'この日は、あなたがたにとって記念となる。あなたがたはその日を主への祭りとして祝い、代々守るべき永遠の掟として、これを祝わなければならない。'),
('JPN', '出埃及记', 2, 12, 15, '七日間、種なしパンを食べなければならない。その最初の日に、あなたがたの家からパン種を取り除かなければならない。最初の日から七日目までの間に、種入りのパンを食べる者は、みなイスラエルから断ち切られるからである。'),
('JPN', '出埃及记', 2, 12, 16, 'また最初の日に聖なる会合を開き、七日目にも聖なる会合を開く。この期間中は、いかなる仕事もしてはならない。ただし、皆が食べる必要のあるものだけは作ることができる。'),
('JPN', '出埃及记', 2, 12, 17, 'あなたがたは種なしパンの祭りを守りなさい。それは、まさにこの日に、わたしがあなたがたの軍団をエジプトの地から導き出したからである。あなたがたは永遠の掟として代々にわたって、この日を守らなければならない。'),
('JPN', '出埃及记', 2, 12, 18, '最初の月の十四日の夕方から、その月の二十一日の夕方まで、種なしパンを食べる。'),
('JPN', '出埃及记', 2, 12, 19, '七日間はあなたがたの家にパン種があってはならない。すべてパン種の入ったものを食べる者は、寄留者でも、この国に生まれた者でも、イスラエルの会衆から断ち切られる。'),
('JPN', '出埃及记', 2, 12, 20, 'あなたがたは、パン種の入ったものは、いっさい食べてはならない。どこでも、あなたがたが住む所では、種なしパンを食べなければならない。」'),
('JPN', '出埃及记', 2, 12, 21, 'それから、モーセはイスラエルの長老たちをみな呼び、彼らに言った。「さあ、羊をあなたがたの家族ごとに用意しなさい。そして過越のいけにえを屠りなさい。'),
('JPN', '出埃及记', 2, 12, 22, 'ヒソプの束を一つ取って、鉢の中の血に浸し、その鉢の中の血を鴨居と二本の門柱に塗り付けなさい。あなたがたは、朝までだれ一人、自分の家の戸口から出てはならない。'),
('JPN', '出埃及记', 2, 12, 23, '主はエジプトを打つために行き巡られる。しかし、鴨居と二本の門柱にある血を見たら、主はその戸口を過ぎ越して、滅ぼす者があなたがたの家に入って打つことのないようにされる。'),
('JPN', '出埃及记', 2, 12, 24, 'あなたがたはこのことを、あなたとあなたの子孫のための掟として永遠に守りなさい。'),
('JPN', '出埃及记', 2, 12, 25, 'あなたがたは、主が約束どおりに与えてくださる地に入るとき、この儀式を守らなければならない。'),
('JPN', '出埃及记', 2, 12, 26, 'あなたがたの子どもたちが『この儀式には、どういう意味があるのですか』と尋ねるとき、'),
('JPN', '出埃及记', 2, 12, 27, 'あなたがたはこう答えなさい。『それは主の過越のいけにえだ。主がエジプトを打たれたとき、主はエジプトにいたイスラエルの子らの家を過ぎ越して、私たちの家々を救ってくださったのだ。』」すると民はひざまずいて礼拝した。'),
('JPN', '出埃及记', 2, 12, 28, 'こうしてイスラエルの子らは行って、それを行った。主がモーセとアロンに命じられたとおりに行った。'),
('JPN', '出埃及记', 2, 12, 29, '真夜中になったとき、主はエジプトの地のすべての長子を、王座に着いているファラオの長子から、地下牢にいる捕虜の長子に至るまで、また家畜の初子までもみな打たれた。'),
('JPN', '出埃及记', 2, 12, 30, 'その夜、ファラオは彼の全家臣、またエジプト人すべてとともに起き上がった。そして、エジプトには激しく泣き叫ぶ声が起こった。それは死者のいない家がなかったからである。'),
('JPN', '出埃及记', 2, 12, 31, '彼はその夜、モーセとアロンを呼び寄せて言った。「おまえたちもイスラエル人も立って、私の民の中から出て行け。おまえたちが言うとおりに、行って主に仕えよ。'),
('JPN', '出埃及记', 2, 12, 32, 'おまえたちが言ったとおり、羊の群れも牛の群れも連れて出て行け。そして私のためにも祝福を祈れ。」'),
('JPN', '出埃及记', 2, 12, 33, 'エジプト人は民をせき立てて、その地から出て行くように迫った。人々が「われわれはみな死んでしまう」と言ったからである。'),
('JPN', '出埃及记', 2, 12, 34, 'それで民は、パン種を入れないままの生地を取り、こね鉢を衣服に包んで肩に担いだ。'),
('JPN', '出埃及记', 2, 12, 35, 'イスラエルの子らはモーセのことばどおりに行い、エジプトに銀の飾り、金の飾り、そして衣服を求めた。'),
('JPN', '出埃及记', 2, 12, 36, '主はエジプトがこの民に好意を持つようにされたので、エジプト人は彼らの求めを聞き入れた。こうして彼らはエジプトからはぎ取った。'),
('JPN', '出埃及记', 2, 12, 37, 'イスラエルの子らはラメセスからスコテに向かって旅立った。女、子どもを除いて、徒歩の壮年男子は約六十万人であった。'),
('JPN', '出埃及记', 2, 12, 38, 'さらに、入り混じって来た多くの異国人と、羊や牛などおびただしい数の家畜も、彼らとともに上った。'),
('JPN', '出埃及记', 2, 12, 39, '彼らはエジプトから携えて来た生地を焼いて、種なしのパン菓子を作った。それにはパン種が入っていなかった。彼らはエジプトを追い出されてぐずぐずしてはいられず、また自分たちの食糧の準備もできなかったからである。'),
('JPN', '出埃及记', 2, 12, 40, 'イスラエルの子らがエジプトに滞在していた期間は、四百三十年であった。'),
('JPN', '出埃及记', 2, 12, 41, '四百三十年が終わった、ちょうどその日に、主の全軍団がエジプトの地を出た。'),
('JPN', '出埃及记', 2, 12, 42, 'それは、彼らをエジプトの地から導き出すために、主が寝ずの番をされた夜であった。それでこの夜、イスラエルの子らはみな、代々にわたり、主のために寝ずの番をするのである。'),
('JPN', '出埃及记', 2, 12, 43, '主はモーセとアロンに言われた。「過越に関する掟は次のとおりである。異国人はだれも、これにあずかってはならない。'),
('JPN', '出埃及记', 2, 12, 44, 'しかし、金で買われた奴隷はだれでも、あなたが割礼を施せば、これにあずかることができる。'),
('JPN', '出埃及记', 2, 12, 45, '居留者と雇い人は、これにあずかってはならない。'),
('JPN', '出埃及记', 2, 12, 46, 'これは一つの家の中で食べなければならない。あなたは家の外にその肉の一切れでも持ち出してはならない。また、その骨を折ってはならない。'),
('JPN', '出埃及记', 2, 12, 47, 'イスラエルの全会衆はこれを行わなければならない。'),
('JPN', '出埃及记', 2, 12, 48, 'もし、あなたのところに寄留者が滞在していて、主に過越のいけにえを献げようとするなら、その人の家の男子はみな割礼を受けなければならない。そうすれば、その人は近づいてそれを献げることができる。彼はこの国に生まれた者と同じになる。しかし無割礼の者は、だれもそれを食べてはならない。'),
('JPN', '出埃及记', 2, 12, 49, 'このおしえは、この国に生まれた者にも、あなたがたの間に寄留している者にも同じである。」'),
('JPN', '出埃及记', 2, 12, 50, 'イスラエルの子らはみな、そのように行った。主がモーセとアロンに命じられたとおりに行った。'),
('JPN', '出埃及记', 2, 12, 51, 'まさにこの日に、主はイスラエルの子らを、軍団ごとにエジプトの地から導き出された。'),
('JPN', '出埃及记', 2, 13, 1, '主はモーセに告げられた。'),
('JPN', '出埃及记', 2, 13, 2, '「イスラエルの子らの間で最初に胎を開く長子はみな、人であれ家畜であれ、わたしのために聖別せよ。それは、わたしのものである。」'),
('JPN', '出埃及记', 2, 13, 3, 'モーセは民に言った。「奴隷の家、エジプトから出て来た、この日を覚えていなさい。力強い御手で、主があなたがたをそこから導き出されたからである。種入りのパンを食べてはならない。'),
('JPN', '出埃及记', 2, 13, 4, 'アビブの月のこの日、あなたがたは出発する。'),
('JPN', '出埃及记', 2, 13, 5, '主は、カナン人、ヒッタイト人、アモリ人、ヒビ人、エブス人の地、主があなたに与えると父祖たちに誓った地、乳と蜜の流れる地にあなたを連れて行かれる。そのときあなたは、この月に、この儀式を執り行いなさい。'),
('JPN', '出埃及记', 2, 13, 6, '七日間、あなたは種なしパンを食べる。七日目は主への祭りである。'),
('JPN', '出埃及记', 2, 13, 7, '七日間、種なしパンを食べなさい。あなたのところに、種入りのパンがあってはならない。あなたの土地のどこにおいても、あなたのところにパン種があってはならない。'),
('JPN', '出埃及记', 2, 13, 8, 'その日、あなたは自分の息子に告げなさい。『このことは、私がエジプトから出て来たときに、主が私にしてくださったことによるのだ。』'),
('JPN', '出埃及记', 2, 13, 9, 'これをあなたの手の上のしるしとし、あなたの額の上の記念として、主のおしえがあなたの口にあるようにしなさい。力強い御手で、主があなたをエジプトから導き出されたからである。'),
('JPN', '出埃及记', 2, 13, 10, 'あなたは、この掟を毎年その定められた時に守らなければならない。'),
('JPN', '出埃及记', 2, 13, 11, '主が、あなたとあなたの父祖たちに誓われたとおりに、あなたをカナン人の地に導き、そこをあなたに与えられるとき、'),
('JPN', '出埃及记', 2, 13, 12, '最初に胎を開くものはみな、主のものとして献げなければならない。家畜から生まれ、あなたのものとなるすべての初子のうち、雄は主のものである。'),
('JPN', '出埃及记', 2, 13, 13, 'ただし、ろばの初子はみな、羊で贖わなければならない。もし贖わないなら、首を折らなければならない。また、あなたの子どもたちのうち、男子の初子はみな、贖わなければならない。'),
('JPN', '出埃及记', 2, 13, 14, '後になって、あなたの息子があなたに『これは、どういうことですか』と尋ねるときは、こう言いなさい。『主が力強い御手によって、私たちを奴隷の家、エジプトから導き出された。'),
('JPN', '出埃及记', 2, 13, 15, 'ファラオが頑なになって、私たちを解放しなかったとき、主はエジプトの地の長子をみな、人の長子から家畜の初子に至るまで殺された。それゆえ私は、最初に胎を開く雄をみな、いけにえとして主に献げ、私の子どもたちの長子をみな贖うのだ。』'),
('JPN', '出埃及记', 2, 13, 16, 'このことは手の上のしるしとなり、あなたの額の上の記章となる。それは主が力強い御手によって、私たちをエジプトから導き出されたからである。」'),
('JPN', '出埃及记', 2, 13, 17, 'さて、ファラオがこの民を去らせたとき、神は彼らを、近道であっても、ペリシテ人の地への道には導かれなかった。神はこう考えられた。「民が戦いを見て心変わりし、エジプトに引き返すといけない。」'),
('JPN', '出埃及记', 2, 13, 18, 'それで神はこの民を、葦の海に向かう荒野の道に回らせた。イスラエルの子らは隊列を組んでエジプトの地から上った。'),
('JPN', '出埃及记', 2, 13, 19, 'モーセはヨセフの遺骸を携えていた。それはヨセフが、「神は必ずあなたがたを顧みてくださる。そのとき、あなたがたは私の遺骸をここから携え上らなければならない」と言って、イスラエルの子らに堅く誓わせていたからである。'),
('JPN', '出埃及记', 2, 13, 20, '彼らはスコテを旅立ち、荒野の端にあるエタムで宿営した。'),
('JPN', '出埃及记', 2, 13, 21, '主は、昼は、途上の彼らを導くため雲の柱の中に、また夜は、彼らを照らすため火の柱の中にいて、彼らの前を進まれた。彼らが昼も夜も進んで行くためであった。'),
('JPN', '出埃及记', 2, 13, 22, '昼はこの雲の柱が、夜はこの火の柱が、民の前から離れることはなかった。'),
('JPN', '出埃及记', 2, 14, 1, '主はモーセに告げられた。'),
('JPN', '出埃及记', 2, 14, 2, '「イスラエルの子らに言え。引き返して、ミグドルと海の間にあるピ・ハヒロテに面したバアル・ツェフォンの手前で宿営せよ。あなたがたは、それに向かって海辺に宿営しなければならない。'),
('JPN', '出埃及记', 2, 14, 3, 'ファラオはイスラエルの子らについて、『彼らはあの地で迷っている。荒野は彼らを閉じ込めてしまった』と言う。'),
('JPN', '出埃及记', 2, 14, 4, 'わたしはファラオの心を頑なにするので、ファラオは彼らの後を追う。しかし、わたしはファラオとその全軍勢によって栄光を現す。こうしてエジプトは、わたしが主であることを知る。」イスラエルの子らはそのとおりにした。'),
('JPN', '出埃及记', 2, 14, 5, '民が去ったことがエジプトの王に告げられると、ファラオとその家臣たちは民に対する考えを変えて言った。「われわれは、いったい何ということをしたのか。イスラエルをわれわれのための労役から解放してしまったとは。」'),
('JPN', '出埃及记', 2, 14, 6, 'そこでファラオは戦車を整え、自分でその軍勢を率い、'),
('JPN', '出埃及记', 2, 14, 7, '選り抜きの戦車六百、そしてエジプトの全戦車を、それぞれに補佐官をつけて率いて行った。'),
('JPN', '出埃及记', 2, 14, 8, '主がエジプトの王ファラオの心を頑なにされたので、ファラオはイスラエルの子らを追跡した。一方、イスラエルの子らは臆することなく出て行った。'),
('JPN', '出埃及记', 2, 14, 9, 'エジプト人は彼らを追った。ファラオの戦車の馬も、騎兵も軍勢もことごとく、バアル・ツェフォンの前にあるピ・ハヒロテで、海辺に宿営している彼らに追いついた。'),
('JPN', '出埃及记', 2, 14, 10, 'ファラオは間近に迫っていた。イスラエルの子らは目を上げた。すると、なんと、エジプト人が彼らのうしろに迫っているではないか。イスラエルの子らは大いに恐れて、主に向かって叫んだ。'),
('JPN', '出埃及记', 2, 14, 11, 'そしてモーセに言った。「エジプトに墓がないからといって、荒野で死なせるために、あなたはわれわれを連れて来たのか。われわれをエジプトから連れ出したりして、いったい何ということをしてくれたのだ。'),
('JPN', '出埃及记', 2, 14, 12, 'エジプトであなたに『われわれのことにはかまわないで、エジプトに仕えさせてくれ』と言ったではないか。実際、この荒野で死ぬよりは、エジプトに仕えるほうがよかったのだ。」'),
('JPN', '出埃及记', 2, 14, 13, 'モーセは民に言った。「恐れてはならない。しっかり立って、今日あなたがたのために行われる主の救いを見なさい。あなたがたは、今日見ているエジプト人をもはや永久に見ることはない。'),
('JPN', '出埃及记', 2, 14, 14, '主があなたがたのために戦われるのだ。あなたがたは、ただ黙っていなさい。」'),
('JPN', '出埃及记', 2, 14, 15, '主はモーセに言われた。「なぜ、あなたはわたしに向かって叫ぶのか。イスラエルの子らに、前進するように言え。'),
('JPN', '出埃及记', 2, 14, 16, 'あなたは、あなたの杖を上げ、あなたの手を海の上に伸ばし、海を分けなさい。そうすれば、イスラエルの子らは海の真ん中の乾いた地面を行くことができる。'),
('JPN', '出埃及记', 2, 14, 17, '見よ、このわたしがエジプト人の心を頑なにする。彼らは後から入って来る。わたしはファラオとその全軍勢、戦車と騎兵によって、わたしの栄光を現す。'),
('JPN', '出埃及记', 2, 14, 18, 'ファラオとその戦車とその騎兵によって、わたしが栄光を現すとき、エジプトは、わたしが主であることを知る。」'),
('JPN', '出埃及记', 2, 14, 19, 'イスラエルの陣営の前を進んでいた神の使いは、移動して彼らのうしろを進んだ。それで、雲の柱は彼らの前から移動して彼らのうしろに立ち、'),
('JPN', '出埃及记', 2, 14, 20, 'エジプトの陣営とイスラエルの陣営の間に入った。それは真っ暗な雲であった。それは夜を迷い込ませ、一晩中、一方の陣営がもう一方に近づくことはなかった。'),
('JPN', '出埃及记', 2, 14, 21, 'モーセが手を海に向けて伸ばすと、主は一晩中、強い東風で海を押し戻し、海を乾いた地とされた。水は分かれた。'),
('JPN', '出埃及记', 2, 14, 22, 'イスラエルの子らは、海の真ん中の乾いた地面を進んで行った。水は彼らのために右も左も壁になった。'),
('JPN', '出埃及记', 2, 14, 23, 'エジプト人は追跡し、ファラオの馬も戦車も騎兵もみな、イスラエルの子らの後を海の中に入って行った。'),
('JPN', '出埃及记', 2, 14, 24, '朝の見張りのころ、主は火と雲の柱の中からエジプトの陣営を見下ろし、エジプトの陣営を混乱に陥れ、'),
('JPN', '出埃及记', 2, 14, 25, '戦車の車輪を外してその動きを阻んだ。それでエジプト人は言った。「イスラエルの前から逃げよう。主が彼らのためにエジプトと戦っているのだ。」'),
('JPN', '出埃及记', 2, 14, 26, '主はモーセに言われた。「あなたの手を海に向けて伸ばし、エジプト人と、その戦車、その騎兵の上に水が戻るようにせよ。」'),
('JPN', '出埃及记', 2, 14, 27, 'モーセが手を海に向けて伸ばすと、夜明けに海が元の状態に戻った。エジプト人は迫り来る水から逃れようとしたが、主はエジプト人を海のただ中に投げ込まれた。'),
('JPN', '出埃及记', 2, 14, 28, '水は元に戻り、後を追って海に入ったファラオの全軍勢の戦車と騎兵をおおった。残った者は一人もいなかった。'),
('JPN', '出埃及记', 2, 14, 29, 'イスラエルの子らは海の真ん中の乾いた地面を歩いて行った。水は彼らのために右も左も壁になっていた。'),
('JPN', '出埃及记', 2, 14, 30, 'こうして主は、その日、イスラエルをエジプト人の手から救われた。イスラエルは、エジプト人が海辺で死んでいるのを見た。'),
('JPN', '出埃及记', 2, 14, 31, 'イスラエルは、主がエジプトに行われた、この大いなる御力を見た。それで民は主を恐れ、主とそのしもべモーセを信じた。'),
('JPN', '出埃及记', 2, 15, 1, 'そのとき、モーセとイスラエルの子らは、主に向かってこの歌を歌った。彼らはこう言った。「主に向かって私は歌おう。主はご威光を極みまで現され、馬と乗り手を海の中に投げ込まれた。'),
('JPN', '出埃及记', 2, 15, 2, '主は私の力、また、ほめ歌。主は私の救いとなられた。この方こそ、私の神。私はこの方をほめたたえる。私の父の神。この方を私はあがめる。'),
('JPN', '出埃及记', 2, 15, 3, '主はいくさびと。その御名は主。'),
('JPN', '出埃及记', 2, 15, 4, '主はファラオの戦車とその軍勢を海の中に投げ込まれた。選り抜きの補佐官たちは葦の海に沈んだ。'),
('JPN', '出埃及记', 2, 15, 5, '深淵が彼らをおおい、彼らは石のように深みに下った。'),
('JPN', '出埃及记', 2, 15, 6, '主よ、あなたの右の手は力に輝き、主よ、あなたの右の手は敵を打ち砕く。'),
('JPN', '出埃及记', 2, 15, 7, 'あなたは大いなるご威光によって、向かい立つ者たちを打ち破られる。あなたが燃える怒りを発せられると、それが彼らを刈り株のように焼き尽くす。'),
('JPN', '出埃及记', 2, 15, 8, 'あなたの鼻の息で水は積み上げられ、流れは堰のようにまっすぐに立ち、大水は海の真ん中で固まった。'),
('JPN', '出埃及记', 2, 15, 9, '敵は言った。『追いかけ、追いつき、略奪したものを分けよう。わが欲望を彼らによって満たそう。剣を抜いて、この手で彼らを滅ぼそう。』'),
('JPN', '出埃及记', 2, 15, 10, 'あなたが風を吹かせられると、海は彼らをおおい、彼らは鉛のように、大いなる水の中に沈んだ。'),
('JPN', '出埃及记', 2, 15, 11, '主よ、神々のうちに、だれかあなたのような方がいるでしょうか。だれかあなたのように、聖であって輝き、たたえられつつ恐れられ、奇しいわざを行う方がいるでしょうか。'),
('JPN', '出埃及记', 2, 15, 12, 'あなたが右の手を伸ばされると、地は彼らを吞み込んだ。'),
('JPN', '出埃及记', 2, 15, 13, 'あなたが贖われたこの民を、あなたは恵みをもって導き、御力をもって、あなたの聖なる住まいに伴われた。'),
('JPN', '出埃及记', 2, 15, 14, 'もろもろの民は聞いて震え、ペリシテの住民も、もだえ苦しんだ。'),
('JPN', '出埃及记', 2, 15, 15, 'そのとき、エドムの首長らは、おじ惑い、モアブの有力者たちを震えが襲い、カナンの住民の心はみな溶け去った。'),
('JPN', '出埃及记', 2, 15, 16, '恐怖と戦慄が彼らに臨み、あなたの偉大な御腕により、彼らは石のように黙った。主よ、あなたの民が通り過ぎるまで。あなたが買い取られた民が通り過ぎるまで。'),
('JPN', '出埃及记', 2, 15, 17, 'あなたは彼らを導き、あなたのゆずりの山に植えられる。主よ、御住まいのために、あなたがお造りになった場所に。主よ、あなたの御手が堅く建てた聖所に。'),
('JPN', '出埃及记', 2, 15, 18, '主はとこしえまでも統べ治められる。」'),
('JPN', '出埃及记', 2, 15, 19, 'ファラオの馬が戦車や騎兵とともに海の中に入ったとき、主は海の水を彼らの上に戻された。しかし、イスラエルの子らは海の真ん中で乾いた地面を歩いて行った。'),
('JPN', '出埃及记', 2, 15, 20, 'そのとき、アロンの姉、女預言者ミリアムがタンバリンを手に取ると、女たちもみなタンバリンを持ち、踊りながら彼女について出て来た。'),
('JPN', '出埃及记', 2, 15, 21, 'ミリアムは人々に応えて歌った。「主に向かって歌え。主はご威光を極みまで現され、馬と乗り手を海の中に投げ込まれた。」'),
('JPN', '出埃及记', 2, 15, 22, 'モーセはイスラエルを葦の海から旅立たせた。彼らはシュルの荒野へ出て行き、三日間、荒野を歩いた。しかし、彼らには水が見つからなかった。'),
('JPN', '出埃及记', 2, 15, 23, '彼らはマラに来たが、マラの水は苦くて飲めなかった。それで、そこはマラという名で呼ばれた。'),
('JPN', '出埃及记', 2, 15, 24, '民はモーセに向かって「われわれは何を飲んだらよいのか」と不平を言った。'),
('JPN', '出埃及记', 2, 15, 25, 'モーセが主に叫ぶと、主は彼に一本の木を示された。彼がそれを水の中に投げ込むと、水は甘くなった。主はそこで彼に掟と定めを授け、そこで彼を試み、'),
('JPN', '出埃及记', 2, 15, 26, 'そして言われた。「もし、あなたの神、主の御声にあなたが確かに聞き従い、主の目にかなうことを行い、また、その命令に耳を傾け、その掟をことごとく守るなら、わたしがエジプトで下したような病気は何一つあなたの上に下さない。わたしは主、あなたを癒やす者だからである。」'),
('JPN', '出埃及记', 2, 15, 27, 'こうして彼らはエリムに着いた。そこには、十二の水の泉と七十本のなつめ椰子の木があった。そこで、彼らはその水のほとりで宿営した。'),
('JPN', '出埃及记', 2, 16, 1, 'イスラエルの全会衆はエリムから旅立ち、エジプトの地を出て、第二の月の十五日に、エリムとシナイとの間にあるシンの荒野に入った。'),
('JPN', '出埃及记', 2, 16, 2, 'そのとき、イスラエルの全会衆は、この荒野でモーセとアロンに向かって不平を言った。'),
('JPN', '出埃及记', 2, 16, 3, 'イスラエルの子らは彼らに言った。「エジプトの地で、肉鍋のそばに座り、パンを満ち足りるまで食べていたときに、われわれは主の手にかかって死んでいたらよかったのだ。事実、あなたがたは、われわれをこの荒野に導き出し、この集団全体を飢え死にさせようとしている。」'),
('JPN', '出埃及记', 2, 16, 4, '主はモーセに言われた。「見よ、わたしはあなたがたのために天からパンを降らせる。民は外に出て行って、毎日、その日の分を集めなければならない。これは、彼らがわたしのおしえに従って歩むかどうかを試みるためである。'),
('JPN', '出埃及记', 2, 16, 5, '六日目に彼らが持ち帰って調えるものは、日ごとに集める分の二倍である。」'),
('JPN', '出埃及记', 2, 16, 6, 'それでモーセとアロンは、すべてのイスラエルの子らに言った。「あなたがたは、夕方には、エジプトの地からあなたがたを導き出したのが主であったことを知り、'),
('JPN', '出埃及记', 2, 16, 7, '朝には主の栄光を見る。主に対するあなたがたの不平を主が聞かれたからだ。私たちが何だというので、私たちに不平を言うのか。」'),
('JPN', '出埃及记', 2, 16, 8, 'モーセはまた言った。「主は夕方にはあなたがたに食べる肉を与え、朝には満ち足りるほどパンを与えてくださる。それはあなたがたが主に対してこぼした不平を、主が聞かれたからだ。いったい私たちが何だというのか。あなたがたの不平は、この私たちに対してではなく、主に対してなのだ。」'),
('JPN', '出埃及记', 2, 16, 9, 'モーセはアロンに言った。「イスラエルの全会衆に言いなさい。『主の前に近づきなさい。主があなたがたの不平を聞かれたから』と。」'),
('JPN', '出埃及记', 2, 16, 10, 'アロンがイスラエルの全会衆に告げたとき、彼らが荒野の方を振り向くと、見よ、主の栄光が雲の中に現れた。'),
('JPN', '出埃及记', 2, 16, 11, '主はモーセに告げられた。'),
('JPN', '出埃及记', 2, 16, 12, '「わたしはイスラエルの子らの不平を聞いた。彼らに告げよ。『あなたがたは夕暮れには肉を食べ、朝にはパンで満ち足りる。こうしてあなたがたは、わたしがあなたがたの神、主であることを知る。』」'),
('JPN', '出埃及记', 2, 16, 13, 'すると、その夕方、うずらが飛んで来て宿営をおおった。また、朝になると、宿営の周り一面に露が降りた。'),
('JPN', '出埃及记', 2, 16, 14, 'その一面の露が消えると、見よ、荒野の面には薄く細かいもの、地に降りた霜のような細かいものがあった。'),
('JPN', '出埃及记', 2, 16, 15, 'イスラエルの子らはこれを見て、「これは何だろう」と言い合った。それが何なのかを知らなかったからであった。モーセは彼らに言った。「これは主があなたがたに食物として下さったパンだ。'),
('JPN', '出埃及记', 2, 16, 16, '主が命じられたことはこうだ。『自分の食べる分に応じて、一人当たり一オメルずつ、それを集めよ。自分の天幕にいる人数に応じて、それを取れ。』」'),
('JPN', '出埃及记', 2, 16, 17, 'そこで、イスラエルの子らはそのとおりにした。ある者はたくさん、ある者は少しだけ集めた。'),
('JPN', '出埃及记', 2, 16, 18, '彼らが、何オメルあるかそれを量ってみると、たくさん集めた人にも余ることはなく、少しだけ集めた人にも足りないことはなかった。自分が食べる分に応じて集めたのである。'),
('JPN', '出埃及记', 2, 16, 19, 'モーセは彼らに言った。「だれも、それを朝まで残しておいてはならない。」'),
('JPN', '出埃及记', 2, 16, 20, 'しかし、彼らはモーセの言うことを聞かず、ある者は朝までその一部を残しておいた。すると、それに虫がわき、臭くなった。モーセは彼らに向かって怒った。'),
('JPN', '出埃及记', 2, 16, 21, '彼らは朝ごとに、各自が食べる分量を集め、日が高くなると、それは溶けた。'),
('JPN', '出埃及记', 2, 16, 22, '六日目に、彼らは二倍のパンを、一人当たり二オメルずつを集めた。会衆の上に立つ者たちがみなモーセのところに来て、告げると、'),
('JPN', '出埃及记', 2, 16, 23, 'モーセは彼らに言った。「主の語られたことはこうだ。『明日は全き休みの日、主の聖なる安息である。焼きたいものは焼き、煮たいものは煮よ。残ったものはすべて取っておき、朝まで保存せよ。』」'),
('JPN', '出埃及记', 2, 16, 24, 'モーセの命じたとおりに、彼らはそれを朝まで取っておいた。しかし、それは臭くもならず、そこにうじ虫もわかなかった。'),
('JPN', '出埃及记', 2, 16, 25, 'モーセは言った。「今日は、それを食べなさい。今日は主の安息だから。今日は、それを野で見つけることはできない。'),
('JPN', '出埃及记', 2, 16, 26, '六日の間、それを集めなさい。しかし七日目の安息には、それはそこにはない。」'),
('JPN', '出埃及记', 2, 16, 27, '七日目になって、民の中のある者たちが集めに出て行った。しかし、何も見つからなかった。'),
('JPN', '出埃及记', 2, 16, 28, '主はモーセに言われた。「あなたがたは、いつまでわたしの命令とおしえを拒み、守らないのか。'),
('JPN', '出埃及记', 2, 16, 29, '心せよ。主があなたがたに安息を与えたのだ。そのため、六日目には二日分のパンをあなたがたに与えている。七日目には、それぞれ自分のところにとどまれ。だれも自分のところから出てはならない。」'),
('JPN', '出埃及记', 2, 16, 30, 'それで民は七日目に休んだ。'),
('JPN', '出埃及记', 2, 16, 31, 'イスラエルの家は、それをマナと名づけた。それはコエンドロの種のようで、白く、その味は蜜を入れた薄焼きパンのようであった。'),
('JPN', '出埃及记', 2, 16, 32, 'モーセは言った。「主が命じられたことはこうだ。『それを一オメル分、あなたがたの子孫のために保存しなさい。わたしがあなたがたをエジプトの地から導き出したときに、荒野であなたがたに食べさせたパンを、彼らが見ることができるようにするためである。』」'),
('JPN', '出埃及记', 2, 16, 33, 'モーセはアロンに言った。「壺を一つ持って来て、マナを一オメル分その中に入れ、それを主の前に置いて、あなたがたの子孫のために保存しなさい。」'),
('JPN', '出埃及记', 2, 16, 34, '主がモーセに命じられたとおり、アロンはそれを保存するために、さとしの板の前に置いた。'),
('JPN', '出埃及记', 2, 16, 35, 'イスラエルの子らは、人が住んでいる土地に来るまで、四十年の間マナを食べた。彼らはカナンの地の境に来るまでマナを食べた。'),
('JPN', '出埃及记', 2, 16, 36, '一オメルは一エパの十分の一である。'),
('JPN', '出埃及记', 2, 17, 1, 'イスラエルの全会衆は、主の命によりシンの荒野を旅立ち、旅を続けてレフィディムに宿営した。しかし、そこには民の飲み水がなかった。'),
('JPN', '出埃及记', 2, 17, 2, '民はモーセと争い、「われわれに飲む水を与えよ」と言った。モーセは彼らに「あなたがたはなぜ私と争うのか。なぜ主を試みるのか」と言った。'),
('JPN', '出埃及记', 2, 17, 3, '民はそこで水に渇いた。それで民はモーセに不平を言った。「いったい、なぜ私たちをエジプトから連れ上ったのか。私や子どもたちや家畜を、渇きで死なせるためか。」'),
('JPN', '出埃及记', 2, 17, 4, 'そこで、モーセは主に叫んで言った。「私はこの民をどうすればよいのでしょう。今にも、彼らは私を石で打ち殺そうとしています。」'),
('JPN', '出埃及记', 2, 17, 5, '主はモーセに言われた。「民の前を通り、イスラエルの長老たちを何人か連れて、あなたがナイル川を打ったあの杖を手に取り、そして行け。'),
('JPN', '出埃及记', 2, 17, 6, 'さあ、わたしはそこ、ホレブの岩の上で、あなたの前に立つ。あなたはその岩を打て。岩から水が出て、民はそれを飲む。」モーセはイスラエルの長老たちの目の前で、そのとおりに行った。'),
('JPN', '出埃及记', 2, 17, 7, 'それで、彼はその場所をマサ、またメリバと名づけた。それは、イスラエルの子らが争ったからであり、また彼らが「主は私たちの中におられるのか、おられないのか」と言って、主を試みたからである。'),
('JPN', '出埃及记', 2, 17, 8, 'さて、アマレクが来て、レフィディムでイスラエルと戦った。'),
('JPN', '出埃及记', 2, 17, 9, 'モーセはヨシュアに言った。「男たちを選び、出て行ってアマレクと戦いなさい。私は明日、神の杖を手に持って、丘の頂に立ちます。」'),
('JPN', '出埃及记', 2, 17, 10, 'ヨシュアはモーセが言ったとおりにして、アマレクと戦った。モーセとアロンとフルは丘の頂に登った。'),
('JPN', '出埃及记', 2, 17, 11, 'モーセが手を高く上げているときは、イスラエルが優勢になり、手を下ろすとアマレクが優勢になった。'),
('JPN', '出埃及记', 2, 17, 12, 'モーセの手が重くなると、彼らは石を取り、それをモーセの足もとに置いた。モーセはその上に腰掛け、アロンとフルは、一人はこちらから、一人はあちらから、モーセの手を支えた。それで彼の両手は日が沈むまで、しっかり上げられていた。'),
('JPN', '出埃及记', 2, 17, 13, 'ヨシュアは、アマレクとその民を剣の刃で討ち破った。'),
('JPN', '出埃及记', 2, 17, 14, '主はモーセに言われた。「このことを記録として文書に書き記し、ヨシュアに読んで聞かせよ。わたしはアマレクの記憶を天の下から完全に消し去る。」'),
('JPN', '出埃及记', 2, 17, 15, 'モーセは祭壇を築き、それをアドナイ・ニシと呼び、'),
('JPN', '出埃及记', 2, 17, 16, 'そして言った。「主の御座の上にある手。主は代々にわたりアマレクと戦われる。」'),
('JPN', '出埃及记', 2, 18, 1, 'さて、モーセのしゅうと、ミディアンの祭司イテロは、神がモーセと御民イスラエルのためになさったすべてのこと、どのようにして主がイスラエルをエジプトから導き出されたかを聞いた。'),
('JPN', '出埃及记', 2, 18, 2, 'それでモーセのしゅうとイテロは、先に送り返されていたモーセの妻ツィポラと'),
('JPN', '出埃及记', 2, 18, 3, '彼女の二人の息子を連れて行った。その一人の名はゲルショムで、「私は異国にいる寄留者だ」という意味である。'),
('JPN', '出埃及记', 2, 18, 4, 'もう一人の名はエリエゼルで、「私の父の神は私の助けであり、ファラオの剣から私を救い出された」という意味である。'),
('JPN', '出埃及记', 2, 18, 5, 'こうしてモーセのしゅうとイテロは、モーセの息子と妻と一緒に、荒野にいるモーセのところにやって来た。彼はそこの神の山に宿営していた。'),
('JPN', '出埃及记', 2, 18, 6, 'イテロはモーセに伝えた。「あなたのしゅうとである私イテロが、あなたの妻とその二人の息子と一緒に、あなたのところに来ています。」'),
('JPN', '出埃及记', 2, 18, 7, 'モーセはしゅうとを迎えに出て行き、身をかがめ、彼に口づけした。彼らは互いに安否を問い、天幕に入った。'),
('JPN', '出埃及记', 2, 18, 8, 'モーセはしゅうとに、主がイスラエルのために、ファラオとエジプトになさったすべてのこと、道中で自分たちに降りかかったすべての困難、そして主が彼らを救い出された次第を語った。'),
('JPN', '出埃及记', 2, 18, 9, 'イテロは、主がイスラエルのためにしてくださったすべての良いこと、とりわけ、エジプト人の手から救い出してくださったことを喜んだ。'),
('JPN', '出埃及记', 2, 18, 10, 'イテロは言った。「主がほめたたえられますように。主はあなたがたをエジプト人の手とファラオの手から救い出し、この民をエジプトの支配から救い出されました。'),
('JPN', '出埃及记', 2, 18, 11, '今、私は、主があらゆる神々にまさって偉大であることを知りました。彼らがこの民に対して不遜にふるまったことの結末によって。」'),
('JPN', '出埃及记', 2, 18, 12, 'モーセのしゅうとイテロは、神への全焼のささげ物といけにえを携えて来たので、アロンとイスラエルのすべての長老たちは、モーセのしゅうととともに神の前で食事をしようとやって来た。'),
('JPN', '出埃及记', 2, 18, 13, '翌日、モーセは民をさばくために座に着いた。民は朝から夕方までモーセの周りに立っていた。'),
('JPN', '出埃及记', 2, 18, 14, 'モーセのしゅうとは、モーセが民のためにしているすべてのことを見て、こう言った。「あなたが民にしているこのことは、いったい何ですか。なぜ、あなた一人だけがさばきの座に着き、民はみな朝から夕方まであなたの周りに立っているのですか。」'),
('JPN', '出埃及记', 2, 18, 15, 'モーセはしゅうとに答えた。「民は神のみこころを求めて、私のところに来るのです。'),
('JPN', '出埃及记', 2, 18, 16, '彼らは、何か事があると、私のところに来ます。私は双方の間をさばいて、神の掟とおしえを知らせるのです。」'),
('JPN', '出埃及记', 2, 18, 17, 'すると、モーセのしゅうとは言った。「あなたがしていることは良くありません。'),
('JPN', '出埃及记', 2, 18, 18, 'あなたも、あなたとともにいるこの民も、きっと疲れ果ててしまいます。このことは、あなたにとって荷が重すぎるからです。あなたはそれを一人ではできません。'),
('JPN', '出埃及记', 2, 18, 19, 'さあ、私の言うことを聞きなさい。あなたに助言しましょう。どうか神があなたとともにいてくださるように。あなたは神の前で民の代わりとなり、様々な事件をあなたが神のところに持って行くようにしなさい。'),
('JPN', '出埃及记', 2, 18, 20, 'あなたは掟とおしえをもって彼らに警告し、彼らの歩むべき道と、なすべきわざを知らせなさい。'),
('JPN', '出埃及记', 2, 18, 21, 'あなたはまた、民全体の中から、神を恐れる、力のある人たち、不正の利を憎む誠実な人たちを見つけ、千人の長、百人の長、五十人の長、十人の長として民の上に立てなさい。'),
('JPN', '出埃及记', 2, 18, 22, 'いつもは彼らが民をさばくのです。大きな事件のときは、すべてあなたのところに持って来させ、小さな事件はみな、彼らにさばかせて、あなたの重荷を軽くしなさい。こうして彼らはあなたとともに重荷を負うのです。'),
('JPN', '出埃及记', 2, 18, 23, 'もし、あなたがこのことを行い、神があなたにそのように命じるなら、あなたも立ち続けることができ、この民もみな、平安のうちに自分のところに帰ることができるでしょう。」'),
('JPN', '出埃及记', 2, 18, 24, 'モーセはしゅうとの言うことを聞き入れ、すべて彼が言ったとおりにした。'),
('JPN', '出埃及记', 2, 18, 25, 'モーセはイスラエル全体の中から力のある人たちを選び、千人の長、百人の長、五十人の長、十人の長として、民の上にかしらとして任じた。'),
('JPN', '出埃及记', 2, 18, 26, 'いつもは彼らが民をさばき、難しい事件はモーセのところに持って来たが、小さな事件はみな彼ら自身でさばいた。'),
('JPN', '出埃及记', 2, 18, 27, 'それからモーセはしゅうとを送り出した。しゅうとは自分の国へ帰って行った。'),
('JPN', '出埃及记', 2, 19, 1, 'エジプトの地を出たイスラエルの子らは、第三の新月の日にシナイの荒野に入った。'),
('JPN', '出埃及记', 2, 19, 2, '彼らはレフィディムを旅立って、シナイの荒野に入り、その荒野で宿営した。イスラエルはそこで、山を前に宿営した。'),
('JPN', '出埃及记', 2, 19, 3, 'モーセが神のみもとに上って行くと、主が山から彼を呼んで言われた。「あなたは、こうヤコブの家に言い、イスラエルの子らに告げよ。'),
('JPN', '出埃及记', 2, 19, 4, '『あなたがたは、わたしがエジプトにしたこと、また、あなたがたを鷲の翼に乗せて、わたしのもとに連れて来たことを見た。'),
('JPN', '出埃及记', 2, 19, 5, '今、もしあなたがたが確かにわたしの声に聞き従い、わたしの契約を守るなら、あなたがたはあらゆる民族の中にあって、わたしの宝となる。全世界はわたしのものであるから。'),
('JPN', '出埃及记', 2, 19, 6, 'あなたがたは、わたしにとって祭司の王国、聖なる国民となる。』これが、イスラエルの子らにあなたが語るべきことばである。」'),
('JPN', '出埃及记', 2, 19, 7, 'モーセは行って、民の長老たちを呼び寄せ、主が命じられたこれらのことばをすべて、彼らの前に示した。'),
('JPN', '出埃及记', 2, 19, 8, '民はみな口をそろえて答えた。「私たちは主の言われたことをすべて行います。」それでモーセは民のことばを携えて主のもとに帰った。'),
('JPN', '出埃及记', 2, 19, 9, '主はモーセに言われた。「見よ。わたしは濃い雲の中にあって、あなたに臨む。わたしがあなたに語るとき、民が聞いて、あなたをいつまでも信じるためである。」それからモーセは民のことばを主に告げた。'),
('JPN', '出埃及记', 2, 19, 10, '主はモーセに言われた。「あなたは民のところに行き、今日と明日、彼らを聖別し、自分たちの衣服を洗わせよ。'),
('JPN', '出埃及记', 2, 19, 11, '彼らに三日目のために準備させよ。三日目に、主が民全体の目の前でシナイ山に降りて行くからである。'),
('JPN', '出埃及记', 2, 19, 12, 'あなたは民のために周囲に境を設けて言え。『山に登り、その境界に触れないように注意せよ。山に触れる者は、だれでも必ず殺されなければならない。'),
('JPN', '出埃及记', 2, 19, 13, 'その人に手を触れてはならない。その人は必ず石で打ち殺されるか、矢で殺されなければならない。獣でも人でも、生かしておいてはならない。』雄羊の角が長く鳴り響くときは、彼らは山に登ることができる。」'),
('JPN', '出埃及记', 2, 19, 14, 'モーセは山から民のところに下りて行って、民を聖別した。彼らは自分たちの衣服を洗った。'),
('JPN', '出埃及记', 2, 19, 15, 'モーセは民に言った。「三日目のために準備をしなさい。女に近づいてはならない。」'),
('JPN', '出埃及记', 2, 19, 16, '三日目の朝、雷鳴と稲妻と厚い雲が山の上にあって、角笛の音が非常に高く鳴り響いたので、宿営の中の民はみな震え上がった。'),
('JPN', '出埃及记', 2, 19, 17, 'モーセは、神に会わせようと、民を宿営から連れ出した。彼らは山のふもとに立った。'),
('JPN', '出埃及记', 2, 19, 18, 'シナイ山は全山が煙っていた。主が火の中にあって、山の上に降りて来られたからである。煙は、かまどの煙のように立ち上り、山全体が激しく震えた。'),
('JPN', '出埃及记', 2, 19, 19, '角笛の音がいよいよ高くなる中、モーセは語り、神は声を出して彼に答えられた。'),
('JPN', '出埃及记', 2, 19, 20, '主はシナイ山の頂に降りて来られた。主がモーセを山の頂に呼ばれたので、モーセは登って行った。'),
('JPN', '出埃及记', 2, 19, 21, '主はモーセに言われた。「下って行って、民に警告せよ。彼らが見ようとして主の方に押し破って来て、多くの者が滅びることのないように。'),
('JPN', '出埃及记', 2, 19, 22, '主に近づく祭司たちも自分自身を聖別しなければならない。主が彼らに怒りを発することのないように。」'),
('JPN', '出埃及记', 2, 19, 23, 'モーセは主に言った。「民はシナイ山に登ることができません。あなたご自身が私たちに警告して、『山の周りに境を設け、それを聖なるものとせよ』と言われたからです。」'),
('JPN', '出埃及记', 2, 19, 24, '主は彼に言われた。「下りて行け。そして、あなた自身はアロンと一緒に上れ。しかし、祭司たちと民は、主のところに上ろうとして押し破ってはならない。主が彼らに怒りを発することのないように。」'),
('JPN', '出埃及记', 2, 19, 25, 'そこでモーセは民のところに下りて行き、彼らに告げた。'),
('JPN', '出埃及记', 2, 20, 1, 'それから神は次のすべてのことばを告げられた。'),
('JPN', '出埃及记', 2, 20, 2, '「わたしは、あなたをエジプトの地、奴隷の家から導き出したあなたの神、主である。'),
('JPN', '出埃及记', 2, 20, 3, 'あなたには、わたし以外に、ほかの神があってはならない。'),
('JPN', '出埃及记', 2, 20, 4, 'あなたは自分のために偶像を造ってはならない。上の天にあるものでも、下の地にあるものでも、地の下の水の中にあるものでも、いかなる形をも造ってはならない。'),
('JPN', '出埃及记', 2, 20, 5, 'それらを拝んではならない。それらに仕えてはならない。あなたの神、主であるわたしは、ねたみの神。わたしを憎む者には父の咎を子に報い、三代、四代にまで及ぼし、'),
('JPN', '出埃及记', 2, 20, 6, 'わたしを愛し、わたしの命令を守る者には、恵みを千代にまで施すからである。'),
('JPN', '出埃及记', 2, 20, 7, 'あなたは、あなたの神、主の名をみだりに口にしてはならない。主は、主の名をみだりに口にする者を罰せずにはおかない。'),
('JPN', '出埃及记', 2, 20, 8, '安息日を覚えて、これを聖なるものとせよ。'),
('JPN', '出埃及记', 2, 20, 9, '六日間働いて、あなたのすべての仕事をせよ。'),
('JPN', '出埃及记', 2, 20, 10, '七日目は、あなたの神、主の安息である。あなたはいかなる仕事もしてはならない。あなたも、あなたの息子や娘も、それにあなたの男奴隷や女奴隷、家畜、またあなたの町囲みの中にいる寄留者も。'),
('JPN', '出埃及记', 2, 20, 11, 'それは主が六日間で、天と地と海、またそれらの中のすべてのものを造り、七日目に休んだからである。それゆえ、主は安息日を祝福し、これを聖なるものとした。'),
('JPN', '出埃及记', 2, 20, 12, 'あなたの父と母を敬え。あなたの神、主が与えようとしているその土地で、あなたの日々が長く続くようにするためである。'),
('JPN', '出埃及记', 2, 20, 13, '殺してはならない。'),
('JPN', '出埃及记', 2, 20, 14, '姦淫してはならない。'),
('JPN', '出埃及记', 2, 20, 15, '盗んではならない。'),
('JPN', '出埃及记', 2, 20, 16, 'あなたの隣人について、偽りの証言をしてはならない。'),
('JPN', '出埃及记', 2, 20, 17, 'あなたの隣人の家を欲してはならない。あなたの隣人の妻、男奴隷、女奴隷、牛、ろば、すべてあなたの隣人のものを欲してはならない。」'),
('JPN', '出埃及记', 2, 20, 18, '民はみな、雷鳴、稲妻、角笛の音、煙る山を目の前にしていた。民は見て身震いし、遠く離れて立っていた。'),
('JPN', '出埃及记', 2, 20, 19, '彼らはモーセに言った。「あなたが私たちに語ってください。私たちは聞き従います。しかし、神が私たちにお語りになりませんように。さもないと、私たちは死んでしまいます。」'),
('JPN', '出埃及记', 2, 20, 20, 'それでモーセは民に言った。「恐れることはありません。神が来られたのは、あなたがたを試みるためです。これは、あなたがたが罪に陥らないよう、神への恐れがあなたがたに生じるためです。」'),
('JPN', '出埃及记', 2, 20, 21, '民は遠く離れて立ち、モーセは神がおられる黒雲に近づいて行った。'),
('JPN', '出埃及记', 2, 20, 22, '主はモーセに言われた。「あなたはイスラエルの子らにこう言わなければならない。あなたがた自身、わたしが天からあなたがたに語ったのを見た。'),
('JPN', '出埃及记', 2, 20, 23, 'あなたがたは、わたしと並べて銀の神々を造ってはならない。また自分のために、金の神々も造ってはならない。'),
('JPN', '出埃及记', 2, 20, 24, 'あなたは、わたしのために土の祭壇を造りなさい。その上に、あなたの全焼のささげ物と交わりのいけにえとして、羊と牛を献げなさい。わたしが自分の名を覚えられるようにするすべての場所で、わたしはあなたに臨み、あなたを祝福する。'),
('JPN', '出埃及记', 2, 20, 25, 'もしあなたが、わたしのために石で祭壇を造るなら、切り石で築いてはならない。それに、のみを当てることで、それを冒すことになるからである。'),
('JPN', '出埃及记', 2, 20, 26, 'あなたはわたしの祭壇に階段で上るようにしてはならない。その上で、あなたの裸があらわにならないようにするためである。'),
('JPN', '出埃及记', 2, 21, 1, 'これらはあなたが彼らの前に置くべき定めである。'),
('JPN', '出埃及记', 2, 21, 2, 'あなたがヘブル人の男奴隷を買う場合、その人は六年間仕えなければならない。しかし七年目には自由の身として無償で去ることができる。'),
('JPN', '出埃及记', 2, 21, 3, '彼が独身で来たのなら独身で去る。彼に妻があれば、その妻は彼とともに去る。'),
('JPN', '出埃及记', 2, 21, 4, '彼の主人が彼に妻を与えて、その妻が彼に息子あるいは娘を産んでいたなら、この妻とその子どもたちは主人のものとなり、彼は一人で去らなければならない。'),
('JPN', '出埃及记', 2, 21, 5, 'しかし、もしもその奴隷が『私は、ご主人様と、私の妻と子どもたちとを愛しています。自由の身となって去りたくありません』と明言するようなことがあるなら、'),
('JPN', '出埃及记', 2, 21, 6, 'その主人は彼を神のもとに連れて行く。それから戸または門柱のところに連れて行き、きりで彼の耳を刺し通す。彼はいつまでも主人に仕えることができる。'),
('JPN', '出埃及记', 2, 21, 7, '人が娘を女奴隷として売るような場合、その女奴隷は、男奴隷が去る場合のように去ってはならない。'),
('JPN', '出埃及记', 2, 21, 8, '彼女を自分のものと定めた主人が、彼女を気に入らなくなった場合は、その主人は彼女が贖い出されるようにしなければならない。主人が彼女を裏切ったのだから、異国の民に売る権利はない。'),
('JPN', '出埃及记', 2, 21, 9, 'その主人が彼女を自分の息子のものと定めるなら、彼女を自分の娘のように扱わなければならない。'),
('JPN', '出埃及记', 2, 21, 10, 'その主人が別の女を妻とするなら、先の女への食べ物、衣服、夫婦の務めを減らしてはならない。'),
('JPN', '出埃及记', 2, 21, 11, 'もしこれら三つのことを彼女に行わないなら、彼女は金を払わないで無償で出て行くことができる。'),
('JPN', '出埃及记', 2, 21, 12, '人を打って死なせた者は、必ず殺されなければならない。'),
('JPN', '出埃及记', 2, 21, 13, 'ただし、彼に殺意がなく神が御手によって事を起こされた場合、わたしはあなたに、彼が逃れることができる場所を指定する。'),
('JPN', '出埃及记', 2, 21, 14, 'しかし、人が隣人に対して不遜にふるまい、策略をめぐらして殺した場合には、この者を、わたしの祭壇のところからであっても、連れ出して殺さなければならない。'),
('JPN', '出埃及记', 2, 21, 15, '自分の父または母を打つ者は、必ず殺されなければならない。'),
('JPN', '出埃及记', 2, 21, 16, '人を誘拐した者は、その人を売った場合も、自分の手もとに置いている場合も、必ず殺されなければならない。'),
('JPN', '出埃及记', 2, 21, 17, '自分の父や母をののしる者は、必ず殺されなければならない。'),
('JPN', '出埃及记', 2, 21, 18, '人が争い、一人が石か拳で相手を打ち、その相手が死なないで床についた場合、'),
('JPN', '出埃及记', 2, 21, 19, 'もし彼が再び起き上がり、杖によって外を歩けるようになれば、打った者は罰を免れる。ただ彼が休んだ分を弁償し、彼が完全に治るようにしてやらなければならない。'),
('JPN', '出埃及记', 2, 21, 20, '自分の男奴隷あるいは女奴隷を杖で打ち、その場で死なせた場合、その人は必ず復讐されなければならない。'),
('JPN', '出埃及记', 2, 21, 21, 'ただし、もしその奴隷が一日か二日生き延びたなら、その人は復讐されてはならない。奴隷は彼の財産だからである。'),
('JPN', '出埃及记', 2, 21, 22, '人が人と争っていて、身ごもった女に突き当たり、早産させた場合、重大な傷害がなければ、彼はその女の夫が要求するとおりの罰金を必ず科せられなければならない。彼は法廷が定めるところに基づいて支払う。'),
('JPN', '出埃及记', 2, 21, 23, 'しかし、重大な傷害があれば、いのちにはいのちを、'),
('JPN', '出埃及记', 2, 21, 24, '目には目を、歯には歯を、手には手を、足には足を、'),
('JPN', '出埃及记', 2, 21, 25, '火傷には火傷を、傷には傷を、打ち傷には打ち傷をもって償わなければならない。'),
('JPN', '出埃及记', 2, 21, 26, '人が自分の男奴隷の片目あるいは女奴隷の片目を打ち、目をつぶした場合、その目の償いとして、その奴隷を自由の身にしなければならない。'),
('JPN', '出埃及记', 2, 21, 27, 'また、自分の男奴隷の歯一本あるいは女奴隷の歯一本を打ち、折ったなら、その歯の償いとして、その奴隷を自由の身にしなければならない。'),
('JPN', '出埃及记', 2, 21, 28, '牛が男または女を突いて死なせた場合、その牛は必ず石で打ち殺さなければならない。その肉を食べてはならない。しかし、その牛の持ち主は罰を免れる。'),
('JPN', '出埃及记', 2, 21, 29, 'しかし、もし牛に以前から突く癖があり、その持ち主が注意されていたのにそれを監視せず、その牛が男または女を殺したのなら、その牛は石で打ち殺され、その持ち主も殺されなければならない。'),
('JPN', '出埃及记', 2, 21, 30, 'もし彼に償い金が科せられたなら、彼は自分に科せられたとおりに、自分のいのちの贖いの代価を支払わなければならない。'),
('JPN', '出埃及记', 2, 21, 31, '息子を突いても娘を突いても、この規定のとおりに扱われる。'),
('JPN', '出埃及记', 2, 21, 32, 'もしその牛が男奴隷あるいは女奴隷を突いたなら、牛の持ち主はその奴隷の主人に銀貨三十シェケルを支払い、その牛は石で打ち殺されなければならない。'),
('JPN', '出埃及记', 2, 21, 33, '人が水溜めのふたを開けたままにしておくか、あるいは、水溜めを掘って、それにふたをせずにおいて、牛やろばがそこに落ちた場合、'),
('JPN', '出埃及记', 2, 21, 34, 'その水溜めの持ち主は償いをしなければならない。彼は家畜の持ち主に金を支払わなければならない。しかし、その死んだ家畜は彼のものとなる。'),
('JPN', '出埃及记', 2, 21, 35, 'ある人の牛が隣人の牛を突いて、その牛が死んだ場合、両者は生きている牛を売って、その金を分け、また死んだ牛も分けなければならない。'),
('JPN', '出埃及记', 2, 21, 36, 'しかし、もしその牛に以前から突く癖があることが分かっていて、その持ち主が監視しなかったのなら、その人は必ず牛を牛で償わなければならない。しかし、その死んだ牛は彼のものとなる。'),
('JPN', '出埃及记', 2, 22, 1, '人が牛あるいは羊を盗み、これを屠るか売るかした場合、牛一頭を牛五頭で、羊一匹を羊四匹で償わなければならない。'),
('JPN', '出埃及记', 2, 22, 2, 'もし盗人が抜け穴を掘って押し入るところを見つけられ、打たれて死んだなら、打った者に血の責任はない。'),
('JPN', '出埃及记', 2, 22, 3, 'もし日が昇っていれば、血の責任は打った者にある。盗みをした者は必ず償いをしなければならない。もし盗人が何も持っていなければ、盗みの代償としてその人自身が売られなければならない。'),
('JPN', '出埃及记', 2, 22, 4, 'もしも、牛であれ、ろばであれ、羊であれ、盗んだ物が生きたままで彼の手もとにあるのが確認されたなら、それを二倍にして償わなければならない。'),
('JPN', '出埃及记', 2, 22, 5, '人が畑あるいはぶどう畑で家畜に牧草を食べさせるとき、放った家畜が他人の畑を食い荒らした場合、その人は自分の畑の最良の物と、ぶどう畑の最良の物をもって償いをしなければならない。'),
('JPN', '出埃及记', 2, 22, 6, 'また、火が出て茨に燃え移り、積み上げた穀物の束、刈られていない麦穂、あるいは畑を焼き尽くした場合、その火を出した者は必ず償いをしなければならない。'),
('JPN', '出埃及记', 2, 22, 7, '人が金銭あるいは物品を隣人に預けて保管してもらい、それがその人の家から盗まれた場合、もしその盗人が見つかったなら、盗人はそれを二倍にして償わなければならない。'),
('JPN', '出埃及记', 2, 22, 8, 'もし盗人が見つからないなら、その家の主人は神の前に出て、彼が隣人の所有物に決して手を触れなかったと誓わなければならない。'),
('JPN', '出埃及记', 2, 22, 9, '所有をめぐるすべての違反行為に関しては、それが、牛、ろば、羊、上着、またいかなる紛失物についてであれ、一方が『これは自分のものだ』と言うなら、その双方の言い分を神の前に持ち出さなければならない。そして、神が有罪と宣告した者は、それを二倍にして相手に償わなければならない。'),
('JPN', '出埃及记', 2, 22, 10, '人が、ろば、牛、羊、またいかなる家畜でも、隣人に預けてその番をしてもらい、それが死ぬか、負傷するか、連れ去られるかしたが、目撃者がいない場合、'),
('JPN', '出埃及记', 2, 22, 11, '隣人の所有物に決して手を触れなかったという主への誓いが、双方の間になければならない。その持ち主はこれを受け入れなければならない。隣人は償いをする必要はない。'),
('JPN', '出埃及记', 2, 22, 12, 'しかし、もしも、それが確かにその人のところから盗まれたのであれば、その持ち主に償いをしなければならない。'),
('JPN', '出埃及记', 2, 22, 13, 'もしも、それが確かに野獣にかみ裂かれたのであれば、証拠としてそれを差し出さなければならない。かみ裂かれたものの償いをする必要はない。'),
('JPN', '出埃及记', 2, 22, 14, '人が隣人から家畜を借り、それが負傷するか死ぬかして、その持ち主が一緒にいなかった場合は、必ず償いをしなければならない。'),
('JPN', '出埃及记', 2, 22, 15, 'もし持ち主が一緒にいたなら、償いをする必要はない。しかし、それが賃借りした家畜であれば、その借り賃は払わなければならない。'),
('JPN', '出埃及记', 2, 22, 16, '人が、まだ婚約していない処女を誘惑し、彼女と寝た場合、その人は必ず、彼女の花嫁料を払って彼女を自分の妻としなければならない。'),
('JPN', '出埃及记', 2, 22, 17, 'もしその父が彼女をその人に与えることを固く拒むなら、その人は処女の花嫁料に相当する銀を支払わなければならない。'),
('JPN', '出埃及记', 2, 22, 18, '呪術を行う女は生かしておいてはならない。'),
('JPN', '出埃及记', 2, 22, 19, '動物と寝る者はみな、必ず殺されなければならない。'),
('JPN', '出埃及记', 2, 22, 20, 'ただ主ひとりのほかに、神々にいけにえを献げる者は、聖絶されなければならない。'),
('JPN', '出埃及记', 2, 22, 21, '寄留者を苦しめてはならない。虐げてはならない。あなたがたもエジプトの地で寄留の民だったからである。'),
('JPN', '出埃及记', 2, 22, 22, 'やもめ、みなしごはみな、苦しめてはならない。'),
('JPN', '出埃及记', 2, 22, 23, 'もしも、あなたがその人たちを苦しめ、彼らがわたしに向かって切に叫ぶことがあれば、わたしは必ず彼らの叫びを聞き入れる。'),
('JPN', '出埃及记', 2, 22, 24, 'そして、わたしの怒りは燃え上がり、わたしは剣によってあなたがたを殺す。あなたがたの妻はやもめとなり、あなたがたの子どもはみなしごとなる。'),
('JPN', '出埃及记', 2, 22, 25, 'もし、あなたとともにいる、わたしの民の貧しい人に金を貸すなら、彼に対して金貸しのようであってはならない。利息を取ってはならない。'),
('JPN', '出埃及记', 2, 22, 26, 'もしも、隣人の上着を質に取ることがあれば、日没までにそれを返さなければならない。'),
('JPN', '出埃及记', 2, 22, 27, 'それは彼のただ一つの覆い、彼の肌をおおう衣だからである。彼はほかに何を着て寝ることができるだろうか。彼がわたしに向かって叫ぶとき、わたしはそれを聞き入れる。わたしは情け深いからである。'),
('JPN', '出埃及记', 2, 22, 28, '神をののしってはならない。また、あなたの民の族長をのろってはならない。'),
('JPN', '出埃及记', 2, 22, 29, 'あなたの豊かな産物と、あふれる酒とのささげ物を遅らせてはならない。あなたの息子のうち長子は、わたしに献げなければならない。'),
('JPN', '出埃及记', 2, 22, 30, 'あなたの牛と羊についても同様にしなければならない。七日間、その母親のそばに置き、八日目にはわたしに献げなければならない。'),
('JPN', '出埃及记', 2, 22, 31, 'あなたがたは、わたしにとって聖なる者でなければならない。野で獣にかみ裂かれたものの肉を食べてはならない。それは犬に投げ与えなければならない。'),
('JPN', '出埃及记', 2, 23, 1, '偽りのうわさを口にしてはならない。悪者と組んで、悪意のある証人となってはならない。'),
('JPN', '出埃及记', 2, 23, 2, '多数に従って悪の側に立ってはならない。訴訟において、多数に従って道からそれ、ねじ曲げた証言をしてはならない。'),
('JPN', '出埃及记', 2, 23, 3, 'また、訴訟において、弱い者を特に重んじてもいけない。'),
('JPN', '出埃及记', 2, 23, 4, 'あなたの敵の牛やろばが迷っているのに出会った場合、あなたは必ずそれを彼のところに連れ戻さなければならない。'),
('JPN', '出埃及记', 2, 23, 5, 'あなたを憎んでいる者のろばが、重い荷の下敷きになっているのを見た場合、それを見過ごしにせず、必ず彼と一緒に起こしてやらなければならない。'),
('JPN', '出埃及记', 2, 23, 6, '訴訟において、あなたの貧しい者たちへのさばきを曲げてはならない。'),
('JPN', '出埃及记', 2, 23, 7, '偽りの告訴から遠く離れなければならない。咎のない者、正しい者を殺してはならない。わたしが悪者を正しいとすることはない。'),
('JPN', '出埃及记', 2, 23, 8, '賄賂を受け取ってはならない。賄賂は聡明な人を盲目にし、正しい人の言い分をゆがめる。'),
('JPN', '出埃及记', 2, 23, 9, 'あなたは寄留者を虐げてはならない。あなたがたはエジプトの地で寄留の民であったので、寄留者の心をあなたがた自身がよく知っている。'),
('JPN', '出埃及记', 2, 23, 10, '六年間は、あなたは地に種を蒔き、収穫をする。'),
('JPN', '出埃及记', 2, 23, 11, 'しかし、七年目には、その土地をそのまま休ませておかなければならない。民の貧しい人々が食べ、その残りを野の生き物が食べるようにしなければならない。ぶどう畑、オリーブ畑も同様にしなければならない。'),
('JPN', '出埃及记', 2, 23, 12, '六日間は自分の仕事をし、七日目には、それをやめなければならない。あなたの牛やろばが休み、あなたの女奴隷の子や寄留者が息をつくためである。'),
('JPN', '出埃及记', 2, 23, 13, 'わたしがあなたがたに言ったすべてのことを守らなければならない。ほかの神々の名を口にしてはならない。これがあなたの口から聞こえてはならない。'),
('JPN', '出埃及记', 2, 23, 14, '年に三度、わたしのために祭りを行わなければならない。'),
('JPN', '出埃及记', 2, 23, 15, '種なしパンの祭りを守らなければならない。わたしが命じたとおり、アビブの月の定められた時に、七日間、種なしパンを食べなければならない。それは、その月にあなたがエジプトを出たからである。何も持たずにわたしの前に出てはならない。'),
('JPN', '出埃及记', 2, 23, 16, 'また、あなたが畑に種を蒔いて得た勤労の初穂を献げる刈り入れの祭りと、年の終わりに、あなたの勤労の実を畑から取り入れるときの収穫祭を行わなければならない。'),
('JPN', '出埃及记', 2, 23, 17, '年に三度、男子はみな、あなたの主、主の前に出なければならない。'),
('JPN', '出埃及记', 2, 23, 18, 'わたしへのいけにえの血を、種入りのパンと一緒に献げてはならない。また、わたしの祭りのための脂肪を朝まで残しておいてはならない。'),
('JPN', '出埃及记', 2, 23, 19, 'あなたの土地の初穂の最上のものを、あなたの神、主の家に持って来なければならない。あなたは子やぎをその母の乳で煮てはならない。'),
('JPN', '出埃及记', 2, 23, 20, '見よ。わたしは、使いをあなたの前に遣わし、道中あなたを守り、わたしが備えた場所にあなたを導く。'),
('JPN', '出埃及记', 2, 23, 21, 'あなたは、その者に心を留め、その声に聞き従いなさい。彼に逆らってはならない。わたしの名がその者のうちにあるので、彼はあなたがたの背きを赦さない。'),
('JPN', '出埃及记', 2, 23, 22, 'しかし、もしあなたが確かにその声に聞き従い、わたしが告げることをみな行うなら、わたしはあなたの敵には敵となり、あなたの仇には仇となる。'),
('JPN', '出埃及记', 2, 23, 23, 'わたしの使いがあなたの前を行き、あなたをアモリ人、ヒッタイト人、ペリジ人、カナン人、ヒビ人、エブス人のところに導き、わたしが彼らを消し去るとき、'),
('JPN', '出埃及记', 2, 23, 24, 'あなたは彼らの神々を拝んではならない。それらに仕えてはならない。また、彼らの風習に倣ってはならない。それらの神々を徹底的に破壊し、その石の柱を粉々に打ち砕かなければならない。'),
('JPN', '出埃及记', 2, 23, 25, 'あなたがたの神、主に仕えよ。そうすれば、主はあなたのパンと水を祝福する。わたしはあなたの中から病気を取り除く。'),
('JPN', '出埃及记', 2, 23, 26, 'あなたの国には、流産する女も不妊の女もいなくなる。わたしはあなたの日数を満たす。'),
('JPN', '出埃及记', 2, 23, 27, 'わたしは、わたしへの恐れをあなたの先に送り、あなたが入って行く先のすべての民をかき乱し、あなたのすべての敵があなたに背を向けるようにする。'),
('JPN', '出埃及记', 2, 23, 28, 'わたしはまた、スズメバチをあなたの先に遣わす。これが、ヒビ人、カナン人、ヒッタイト人をあなたの前から追い払う。'),
('JPN', '出埃及记', 2, 23, 29, 'しかし、わたしは彼らを一年のうちに、あなたの前から追い払いはしない。土地が荒れ果て、野の生き物が増え、あなたを害することのないようにするためである。'),
('JPN', '出埃及记', 2, 23, 30, 'あなたが増え広がって、その地を相続するまで、少しずつ、わたしは彼らをあなたの前から追い払う。'),
('JPN', '出埃及记', 2, 23, 31, 'わたしは、あなたの領土を、葦の海からペリシテ人の海に至るまで、また荒野からあの大河に至るまでとする。それは、わたしがその地に住んでいる者たちをあなたがたの手に渡し、あなたが彼らを自分の前から追い払うからである。'),
('JPN', '出埃及记', 2, 23, 32, 'あなたは、彼らや、彼らの神々と契約を結んではならない。'),
('JPN', '出埃及记', 2, 23, 33, '彼らはあなたの国に住んではならない。彼らがあなたを、わたしの前に罪ある者としないようにするためである。あなたが彼らの神々に仕え、あなたにとって罠となるからである。」'),
('JPN', '出埃及记', 2, 24, 1, '主はモーセに言われた。「あなたとアロン、ナダブとアビフ、それにイスラエルの長老七十人は、主のもとへ上って来て、遠く離れて伏し拝め。'),
('JPN', '出埃及记', 2, 24, 2, 'モーセだけが主のもとに近づけ。ほかの者は近づいてはならない。民はモーセと一緒に上って来てはならない。」'),
('JPN', '出埃及记', 2, 24, 3, 'モーセは来て、主のすべてのことばと、すべての定めをことごとく民に告げた。すると、民はみな声を一つにして答えた。「主の言われたことはすべて行います。」'),
('JPN', '出埃及记', 2, 24, 4, 'モーセは主のすべてのことばを書き記した。モーセは翌朝早く、山のふもとに祭壇を築き、また、イスラエルの十二部族にしたがって十二の石の柱を立てた。'),
('JPN', '出埃及记', 2, 24, 5, 'それから彼はイスラエルの若者たちを遣わしたので、彼らは全焼のささげ物を献げ、また、交わりのいけにえとして雄牛を主に献げた。'),
('JPN', '出埃及记', 2, 24, 6, 'モーセはその血の半分を取って鉢に入れ、残りの半分を祭壇に振りかけた。'),
('JPN', '出埃及记', 2, 24, 7, 'そして契約の書を取り、民に読んで聞かせた。彼らは言った。「主の言われたことはすべて行います。聞き従います。」'),
('JPN', '出埃及记', 2, 24, 8, 'モーセはその血を取って、民に振りかけ、そして言った。「見よ。これは、これらすべてのことばに基づいて、主があなたがたと結ばれる契約の血である。」'),
('JPN', '出埃及记', 2, 24, 9, 'それからモーセとアロン、ナダブとアビフ、それにイスラエルの長老七十人は登って行った。'),
('JPN', '出埃及记', 2, 24, 10, '彼らはイスラエルの神を見た。御足の下にはサファイアの敷石のようなものがあり、透き通っていて大空そのもののようであった。'),
('JPN', '出埃及记', 2, 24, 11, '神はイスラエルの子らのおもだった者たちに、手を下されなかった。彼らは神ご自身を見て、食べたり飲んだりした。'),
('JPN', '出埃及记', 2, 24, 12, '主はモーセに言われた。「山のわたしのところに上り、そこにとどまれ。わたしはあなたに石の板を授ける。それは、彼らを教えるために、わたしが書き記したおしえと命令である。」'),
('JPN', '出埃及记', 2, 24, 13, 'そこで、モーセとその従者ヨシュアは立ち上がり、モーセは神の山に登った。'),
('JPN', '出埃及记', 2, 24, 14, '彼は長老たちに言った。「私たちがあなたがたのところに戻って来るまで、私たちのために、ここにとどまりなさい。見よ、アロンとフルがあなたがたと一緒にいる。訴え事のある者はだれでも彼らのところに行きなさい。」'),
('JPN', '出埃及记', 2, 24, 15, 'モーセが山に登ると、雲が山をおおった。'),
('JPN', '出埃及记', 2, 24, 16, '主の栄光はシナイ山の上にとどまり、雲は六日間、山をおおっていた。七日目に主は雲の中からモーセを呼ばれた。'),
('JPN', '出埃及记', 2, 24, 17, '主の栄光の現れは、イスラエルの子らの目には、山の頂を焼き尽くす火のようであった。'),
('JPN', '出埃及记', 2, 24, 18, 'モーセは雲の中に入って行き、山に登った。そして、モーセは四十日四十夜、山にいた。'),
('JPN', '出埃及记', 2, 25, 1, '主はモーセに告げられた。'),
('JPN', '出埃及记', 2, 25, 2, '「わたしに奉納物を携えて来るように、イスラエルの子らに告げよ。あなたがたは、すべて、進んで献げる心のある人から、わたしへの奉納物を受け取らなければならない。'),
('JPN', '出埃及记', 2, 25, 3, '彼らから受け取る奉納物は次のものである。金、銀、青銅、'),
('JPN', '出埃及记', 2, 25, 4, '青、紫、緋色の撚り糸、亜麻布、やぎの毛、'),
('JPN', '出埃及记', 2, 25, 5, '赤くなめした雄羊の皮、じゅごんの皮、アカシヤ材、'),
('JPN', '出埃及记', 2, 25, 6, 'ともしび用の油、注ぎの油と、香り高い香のための香料、'),
('JPN', '出埃及记', 2, 25, 7, 'エポデや胸当てにはめ込む、縞めのうや宝石である。'),
('JPN', '出埃及记', 2, 25, 8, '彼らにわたしのための聖所を造らせよ。そうすれば、わたしは彼らのただ中に住む。'),
('JPN', '出埃及记', 2, 25, 9, '幕屋と幕屋のすべての備品は、わたしがあなたに示す型と全く同じように造らなければならない。'),
('JPN', '出埃及记', 2, 25, 10, 'アカシヤ材の箱を作り、その長さを二キュビト半、幅を一キュビト半、高さを一キュビト半とする。'),
('JPN', '出埃及记', 2, 25, 11, 'それに純金をかぶせる。その内側と外側にかぶせ、その周りに金の飾り縁を作る。'),
('JPN', '出埃及记', 2, 25, 12, '箱のために金の環を四つ鋳造し、その四隅の基部に取り付ける。一方の側に二つの環を、もう一方の側にもう二つの環を取り付ける。'),
('JPN', '出埃及记', 2, 25, 13, 'また、アカシヤ材で棒を作り、それに金をかぶせる。'),
('JPN', '出埃及记', 2, 25, 14, 'その箱を棒で担ぐために、その棒を箱の両側の環に通す。'),
('JPN', '出埃及记', 2, 25, 15, 'その棒は箱の環に差し込んだままにする。外してはならない。'),
('JPN', '出埃及记', 2, 25, 16, 'その箱に、わたしが与えるさとしの板を納める。'),
('JPN', '出埃及记', 2, 25, 17, 'また、純金で『宥めの蓋』を作り、その長さを二キュビト半、幅を一キュビト半とする。'),
('JPN', '出埃及记', 2, 25, 18, '二つの金のケルビムを作る。槌で打って、『宥めの蓋』の両端に作る。'),
('JPN', '出埃及记', 2, 25, 19, '一つを一方の端に、もう一つを他方の端に作る。『宥めの蓋』の一部として、ケルビムをその両端に作る。'),
('JPN', '出埃及记', 2, 25, 20, 'ケルビムは両翼を上の方に広げ、その翼で『宥めの蓋』をおおうようにする。互いに向かい合って、ケルビムの顔が『宥めの蓋』の方を向くようにする。'),
('JPN', '出埃及记', 2, 25, 21, 'その『宥めの蓋』を箱の上に載せる。箱の中には、わたしが与えるさとしの板を納める。'),
('JPN', '出埃及记', 2, 25, 22, 'わたしはそこであなたと会見し、イスラエルの子らに向けてあなたに与える命令を、その『宥めの蓋』の上から、あかしの箱の上の二つのケルビムの間から、ことごとくあなたに語る。'),
('JPN', '出埃及记', 2, 25, 23, 'また、アカシヤ材で机を作り、その長さを二キュビト、幅を一キュビト、高さを一キュビト半とする。'),
('JPN', '出埃及记', 2, 25, 24, 'これに純金をかぶせ、その周りに金の飾り縁を作り、'),
('JPN', '出埃及记', 2, 25, 25, 'その周りに一手幅の枠を作り、その枠の周りに金の飾り縁を作る。'),
('JPN', '出埃及记', 2, 25, 26, 'その机のために金の環を四つ作り、四本の脚のところの四隅にその環を取り付ける。'),
('JPN', '出埃及记', 2, 25, 27, '環は枠の脇に付け、そこに机を担ぐ棒を入れる。'),
('JPN', '出埃及记', 2, 25, 28, 'アカシヤ材で机を担ぐための棒を作り、これに金をかぶせる。'),
('JPN', '出埃及记', 2, 25, 29, 'また、注ぎのささげ物を注ぐための皿、ひしゃく、瓶、水差しを作る。これらを純金で作る。'),
('JPN', '出埃及记', 2, 25, 30, '机の上には臨在のパンを置き、絶えずわたしの前にあるようにする。'),
('JPN', '出埃及记', 2, 25, 31, 'また、純金の燭台を作る。その燭台は槌で打って作る。それには、台座と支柱と、がくと節と花弁があるようにする。'),
('JPN', '出埃及记', 2, 25, 32, '六本の枝がその脇の部分から、すなわち燭台の三本の枝が一方の脇から、燭台のもう三本の枝がもう一方の脇から出る。'),
('JPN', '出埃及记', 2, 25, 33, '一方の枝に、アーモンドの花の形をした、節と花弁のある三つのがくを、また、もう一方の枝にも、アーモンドの花の形をした、節と花弁のある三つのがくを付ける。燭台から出る六本の枝はみな、そのようにする。'),
('JPN', '出埃及记', 2, 25, 34, '燭台そのものには、アーモンドの花の形をした、節と花弁のある四つのがくを付ける。'),
('JPN', '出埃及记', 2, 25, 35, 'それから出る一対の枝の下に一つの節、それから出る次の一対の枝の下に一つの節、それから出るその次の一対の枝の下に一つの節。このように六つの枝が燭台から出ていることになる。'),
('JPN', '出埃及记', 2, 25, 36, 'それらの節と枝とは燭台と一体にし、その全体は一つの純金を打って作る。'),
('JPN', '出埃及记', 2, 25, 37, 'また、ともしび皿を七つ作る。ともしび皿は、その前方を照らすように上にあげる。'),
('JPN', '出埃及记', 2, 25, 38, 'その芯切りばさみも芯取り皿も純金である。'),
('JPN', '出埃及记', 2, 25, 39, '純金一タラントで、燭台とこれらのすべての器具を作る。'),
('JPN', '出埃及记', 2, 25, 40, 'よく注意して、山であなたに示された型どおりに作らなければならない。'),
('JPN', '出埃及记', 2, 26, 1, '幕屋を十枚の幕で造らなければならない。幕は、撚り糸で織った亜麻布、青、紫、緋色の撚り糸を用い、意匠を凝らして、それにケルビムを織り出さなければならない。'),
('JPN', '出埃及记', 2, 26, 2, '幕の長さはそれぞれ二十八キュビト、幕の幅はそれぞれ四キュビトで、幕はみな同じ寸法とする。'),
('JPN', '出埃及记', 2, 26, 3, '五枚の幕を互いにつなぎ合わせ、もう五枚の幕も互いにつなぎ合わせる。'),
('JPN', '出埃及记', 2, 26, 4, 'そのつなぎ合わせたものの端にある幕の縁に、青いひもの輪を付ける。もう一つのつなぎ合わせたものの端にある幕の縁にも、そのようにする。'),
('JPN', '出埃及记', 2, 26, 5, 'その一枚の幕に五十個の輪を付け、もう一つのつなぎ合わせた幕の端にも五十個の輪を付け、その輪を互いに向かい合わせにする。'),
('JPN', '出埃及记', 2, 26, 6, '金の留め金を五十個作り、その留め金で幕を互いにつなぎ合わせ、こうして一つの幕屋にする。'),
('JPN', '出埃及记', 2, 26, 7, 'また、あなたは、幕屋の上に掛ける天幕のために、やぎの毛の幕を作らなければならない。その幕を十一枚作る。'),
('JPN', '出埃及记', 2, 26, 8, '幕の長さはそれぞれ三十キュビト、幕の幅はそれぞれ四キュビト、その十一枚の幕は同じ寸法とする。'),
('JPN', '出埃及记', 2, 26, 9, 'そのうち五枚の幕を一つに、もう六枚の幕も一つにつなぎ合わせ、その六枚目の幕を天幕の前で折り重ねる。'),
('JPN', '出埃及记', 2, 26, 10, 'つなぎ合わせたものの端にある幕の縁には五十個の輪を付け、もう一つのつなぎ合わせた幕の縁にも五十個の輪を付ける。'),
('JPN', '出埃及记', 2, 26, 11, '青銅の留め金を五十個作って、その留め金を輪にはめ、天幕をつなぎ合わせて一つとする。'),
('JPN', '出埃及记', 2, 26, 12, '天幕の幕の余って垂れる部分、すなわちその余りの半幕は幕屋のうしろに垂らす。'),
('JPN', '出埃及记', 2, 26, 13, 'そして、このうち一キュビトともう一方の一キュビトの、天幕の幕の長さで余る部分は、幕屋をおおうように、その天幕の両側、手前と奥側に垂らしておく。'),
('JPN', '出埃及记', 2, 26, 14, '天幕のために、赤くなめした雄羊の皮で覆いを作り、その上に掛ける覆いをじゅごんの皮で作る。'),
('JPN', '出埃及记', 2, 26, 15, 'この幕屋のために、アカシヤ材で、まっすぐに立てる板を作る。'),
('JPN', '出埃及记', 2, 26, 16, '一枚の板は、長さ十キュビト、板一枚の幅は一キュビト半。'),
('JPN', '出埃及记', 2, 26, 17, '板一枚ごとに、はめ込みのほぞを二つ作り、幕屋のすべての板にそのようにする。'),
('JPN', '出埃及记', 2, 26, 18, '幕屋のために板を作る。南側に二十枚。'),
('JPN', '出埃及记', 2, 26, 19, 'その二十枚の板の下に銀の台座を四十個作る。一枚の板の下に、その二つのほぞのために二個の台座があり、ほかの板の下にも、二つのほぞのために二個の台座を作る。'),
('JPN', '出埃及记', 2, 26, 20, '幕屋のもう一つの側、北側に板二十枚。'),
('JPN', '出埃及记', 2, 26, 21, '銀の台座四十個。すなわち、一枚の板の下に二個の台座。次の板の下にも二個の台座。'),
('JPN', '出埃及记', 2, 26, 22, '幕屋のうしろ、西側に板六枚を作る。'),
('JPN', '出埃及记', 2, 26, 23, '幕屋のうしろの両隅のために板二枚を作る。'),
('JPN', '出埃及记', 2, 26, 24, 'これらは底部では別々であるが、上部では、一つの環のところで一つに合わさるようにする。二枚とも、そのようにする。これらが両隅となる。'),
('JPN', '出埃及记', 2, 26, 25, '板は八枚、その銀の台座は十六個。すなわち、一枚の板の下に二個の台座、ほかの板の下にも二個ずつの台座となる。'),
('JPN', '出埃及记', 2, 26, 26, 'また、アカシヤ材で横木を作る。すなわち、幕屋の一方の側の板のために五本、'),
('JPN', '出埃及记', 2, 26, 27, '幕屋のもう一方の側の板のために横木五本、幕屋のうしろ、西側の板のために横木を五本作る。'),
('JPN', '出埃及记', 2, 26, 28, '板の中間にある中央横木は、端から端まで通るようにする。'),
('JPN', '出埃及记', 2, 26, 29, 'その板に金をかぶせ、横木を通す環を金で作る。横木にも金をかぶせる。'),
('JPN', '出埃及记', 2, 26, 30, 'こうして、あなたは、山で示された定めのとおりに幕屋を設営しなければならない。'),
('JPN', '出埃及记', 2, 26, 31, 'また、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用いて、垂れ幕を作る。これに意匠を凝らしてケルビムを織り出す。'),
('JPN', '出埃及记', 2, 26, 32, 'この垂れ幕を、金をかぶせたアカシヤ材の四本の柱に付ける。その鉤は金で、柱は四つの銀の台座の上に据えられる。'),
('JPN', '出埃及记', 2, 26, 33, 'その垂れ幕を留め金の下に掛け、垂れ幕の内側に、あかしの箱を運び入れる。その垂れ幕は、あなたがたのために聖所と至聖所との仕切りとなる。'),
('JPN', '出埃及记', 2, 26, 34, '至聖所にあるあかしの箱の上には『宥めの蓋』を置く。'),
('JPN', '出埃及记', 2, 26, 35, '垂れ幕の外側には机を置く。机は幕屋の南側にある燭台と向かい合わせる。その机は北側に置く。'),
('JPN', '出埃及记', 2, 26, 36, 'あなたは天幕の入り口のために、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用い、刺繡を施して垂れ幕を作らなければならない。'),
('JPN', '出埃及记', 2, 26, 37, 'その幕のためにアカシヤ材の柱を五本作り、これに金をかぶせる。その鉤も金である。それらの柱のために青銅の台座を五つ鋳造する。'),
('JPN', '出埃及记', 2, 27, 1, '祭壇をアカシヤ材で作る。その祭壇は長さ五キュビト、幅五キュビトの正方形とし、高さは三キュビトとする。'),
('JPN', '出埃及记', 2, 27, 2, 'その四隅の上に角を作る。その角は祭壇から出ているようにし、青銅をその祭壇にかぶせる。'),
('JPN', '出埃及记', 2, 27, 3, '灰壺、十能、鉢、肉刺し、火皿を作る。祭壇の用具はみな青銅で作る。'),
('JPN', '出埃及记', 2, 27, 4, '祭壇のために青銅の網細工の格子を作る。その網の上の四隅に青銅の環を四個作る。'),
('JPN', '出埃及记', 2, 27, 5, 'その網を下の方、祭壇の張り出した部分の下に取り付け、これが祭壇の高さの半ばに達するようにする。'),
('JPN', '出埃及记', 2, 27, 6, '祭壇のために棒を、アカシヤ材の棒を作り、それらに青銅をかぶせる。'),
('JPN', '出埃及记', 2, 27, 7, 'それらの棒は環に通す。祭壇が担がれるとき、棒が祭壇の両側にあるようにする。'),
('JPN', '出埃及记', 2, 27, 8, '祭壇は、板で、中が空洞になるように作る。山であなたに示されたとおりに作らなければならない。'),
('JPN', '出埃及记', 2, 27, 9, '次に幕屋の庭を造る。南側は、撚り糸で織った長さ百キュビトの亜麻布の庭の掛け幕を、その側に張る。'),
('JPN', '出埃及记', 2, 27, 10, 'その柱は二十本、その台座は二十個で青銅、その柱の鉤と頭つなぎは銀とする。'),
('JPN', '出埃及记', 2, 27, 11, '同じように、北側も長さ百キュビトの掛け幕とする。その柱は二十本、その台座は二十個で青銅、その柱の鉤と頭つなぎは銀とする。'),
('JPN', '出埃及记', 2, 27, 12, 'また、庭の西側は幅五十キュビトの掛け幕、その柱は十本、その台座は十個とする。'),
('JPN', '出埃及记', 2, 27, 13, '正面の、庭の東側の幅も五十キュビト。'),
('JPN', '出埃及记', 2, 27, 14, '門の片側には十五キュビトの掛け幕、その柱は三本、その台座は三個とする。'),
('JPN', '出埃及记', 2, 27, 15, 'もう片方の側も十五キュビトの掛け幕、その柱は三本、その台座は三個とする。'),
('JPN', '出埃及记', 2, 27, 16, '庭の門には、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用いた、長さ二十キュビトの、刺繡した垂れ幕を張る。その柱は四本、その台座は四個とする。'),
('JPN', '出埃及记', 2, 27, 17, '庭の周囲の柱はみな、銀の頭つなぎでつなぎ合わせ、その鉤は銀、台座は青銅とする。'),
('JPN', '出埃及记', 2, 27, 18, 'この庭は長さ百キュビト、幅五十キュビト、そして高さは撚り糸で織った亜麻布の幕の五キュビトとし、その台座は青銅とする。'),
('JPN', '出埃及记', 2, 27, 19, '幕屋の奉仕に用いるすべての備品、すべての杭、庭のすべての杭は青銅とする。'),
('JPN', '出埃及记', 2, 27, 20, 'あなたはイスラエルの子らに命じて、ともしび用の質の良い純粋なオリーブ油を持って来させなさい。ともしびを絶えずともしておくためである。'),
('JPN', '出埃及记', 2, 27, 21, '会見の天幕の中で、さとしの板の前にある垂れ幕の外側で、アロンとその子らは、夕方から朝まで主の前にそのともしびを整える。これはイスラエルの子らが代々守るべき永遠の掟である。'),
('JPN', '出埃及记', 2, 28, 1, 'あなたは、イスラエルの子らの中から、あなたの兄弟アロンと、彼とともにいる彼の息子たちのナダブとアビフ、エルアザルとイタマルをあなたの近くに来させ、祭司としてわたしに仕えさせよ。'),
('JPN', '出埃及记', 2, 28, 2, 'また、あなたの兄弟アロンのために、栄光と美を表す聖なる装束を作れ。'),
('JPN', '出埃及记', 2, 28, 3, 'あなたは、わたしが知恵の霊を満たした、心に知恵ある者たちに告げて、彼らにアロンの装束を作らせなさい。彼を聖別し、祭司としてわたしに仕えさせるためである。'),
('JPN', '出埃及记', 2, 28, 4, '彼らが作る装束は次のとおりである。胸当て、エポデ、青服、市松模様の長服、かぶり物、飾り帯。彼らは、あなたの兄弟アロンとその子らが、祭司としてわたしに仕えるために、聖なる装束を作る。'),
('JPN', '出埃及记', 2, 28, 5, '彼らは、金色、青、紫、緋色の撚り糸、それに亜麻布を受け取る。'),
('JPN', '出埃及记', 2, 28, 6, '彼らに、金色、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用いて、意匠を凝らしてエポデを作らせる。'),
('JPN', '出埃及记', 2, 28, 7, '二つの肩当てが、それぞれエポデの両端に付けられ、エポデは一つに結ばれる。'),
('JPN', '出埃及记', 2, 28, 8, 'エポデの上に来るあや織りの帯はエポデと同じ作りで、金色、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用い、エポデの一部となるようにする。'),
('JPN', '出埃及记', 2, 28, 9, '二つの縞めのうを取り、その上にイスラエルの息子たちの名を刻む。'),
('JPN', '出埃及记', 2, 28, 10, '六つの名を一つの石に、残りの六つの名をもう一つの石に、生まれた順に刻む。'),
('JPN', '出埃及记', 2, 28, 11, '印章を彫る宝石細工を施して、イスラエルの息子たちの名をその二つの石に彫り、それぞれを金縁の細工の中にはめ込む。'),
('JPN', '出埃及记', 2, 28, 12, 'その二つの石をエポデの肩当てに付け、イスラエルの息子たちが覚えられるための石とする。アロンは主の前で、彼らの名が覚えられるように両肩に載せる。'),
('JPN', '出埃及记', 2, 28, 13, 'あなたは金縁の細工を作り、'),
('JPN', '出埃及记', 2, 28, 14, 'また二本の純金の鎖を作り、これを編んでひもとし、このひもの鎖を先の細工に取り付ける。'),
('JPN', '出埃及记', 2, 28, 15, 'あなたはさばきの胸当てを意匠を凝らして作る。それをエポデの細工と同じように作る。すなわち、金色、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用いて作る。'),
('JPN', '出埃及记', 2, 28, 16, 'それは正方形で二重にする。長さ一ゼレト、幅一ゼレト。'),
('JPN', '出埃及记', 2, 28, 17, 'その中に宝石をはめ込み四列にする。第一列は赤めのう、トパーズ、エメラルド。'),
('JPN', '出埃及记', 2, 28, 18, '第二列はトルコ石、サファイア、ダイヤモンド。'),
('JPN', '出埃及记', 2, 28, 19, '第三列はヒヤシンス石、めのう、紫水晶。'),
('JPN', '出埃及记', 2, 28, 20, '第四列は緑柱石、縞めのう、碧玉。これらが金縁の細工の中にはめ込まれる。'),
('JPN', '出埃及记', 2, 28, 21, 'これらの宝石はイスラエルの息子たちの名にちなむもので、彼らの名にしたがい十二個でなければならない。それらは印章のように、それぞれに名が彫られ、十二部族を表す。'),
('JPN', '出埃及记', 2, 28, 22, 'また、胸当てのために、撚ったひものような鎖を純金で作る。'),
('JPN', '出埃及记', 2, 28, 23, '胸当てのために金の環を二個作り、その二個の環を胸当ての両端に付ける。'),
('JPN', '出埃及记', 2, 28, 24, 'その胸当ての両端の二個の環に、二本の金のひもを付ける。'),
('JPN', '出埃及记', 2, 28, 25, 'その二本のひものもう一方の端を、先の二つの金縁の細工と結び、エポデの肩当ての前側に付ける。'),
('JPN', '出埃及记', 2, 28, 26, 'さらに二個の金の環を作り、それらを胸当ての両端に、エポデに接する胸当ての内側の縁に付ける。'),
('JPN', '出埃及记', 2, 28, 27, 'また、さらに二個の金の環を作り、これをエポデの二つの肩当ての下端の前に、エポデのあや織りの帯の上部の継ぎ目に、向かい合うように付ける。'),
('JPN', '出埃及记', 2, 28, 28, '胸当ては、その環からエポデの環に青ひもで結び付け、エポデのあや織りの帯の上にあるようにし、胸当てがエポデから外れないようにしなければならない。'),
('JPN', '出埃及记', 2, 28, 29, 'このようにして、アロンが聖所に入るときには、さばきの胸当てにあるイスラエルの息子たちの名をその胸に担う。それらの名が、絶えず主の前で覚えられるようにするためである。'),
('JPN', '出埃及记', 2, 28, 30, 'さばきの胸当てにはウリムとトンミムを入れ、アロンが主の前に出るときに、それがアロンの胸の上にあるようにする。アロンは絶えず主の前に、イスラエルの息子たちのさばきを胸に担う。'),
('JPN', '出埃及记', 2, 28, 31, 'エポデの下に着る青服を青の撚り糸だけで作る。'),
('JPN', '出埃及记', 2, 28, 32, 'その真ん中に、首を通す口を作る。その口の周りには、ほころびないように織物の技法を凝らして縁を付け、よろいの襟のようにする。'),
('JPN', '出埃及记', 2, 28, 33, 'その裾周りには、青、紫、緋色の撚り糸でざくろを作る。その裾周りのざくろの間には金の鈴を付ける。'),
('JPN', '出埃及记', 2, 28, 34, 'すなわち、青服の裾周りに、金の鈴、ざくろ、金の鈴、ざくろ、となるようにする。'),
('JPN', '出埃及记', 2, 28, 35, 'アロンはこれを、務めを行うために着る。彼が聖所に入って主の前に出るとき、またそこを去るとき、その音が聞こえるようにする。彼が死ぬことのないようにするためである。'),
('JPN', '出埃及记', 2, 28, 36, 'また、純金の札を作り、その上に印章を彫るように『主の聖なるもの』と彫り、'),
('JPN', '出埃及记', 2, 28, 37, 'これを青ひもに付け、それをかぶり物に付ける。それがかぶり物の前面にくるようにする。'),
('JPN', '出埃及记', 2, 28, 38, 'これがアロンの額の上にあって、アロンは、イスラエルの子らが聖別する聖なるもの、彼らのすべての聖なる献上物に関わる咎を負う。これは、彼らが主の前に受け入れられるように、絶えずアロンの額の上になければならない。'),
('JPN', '出埃及记', 2, 28, 39, 'さらに亜麻布で市松模様の長服を作り、亜麻布でかぶり物を作る。飾り帯は刺繡を施して作る。'),
('JPN', '出埃及记', 2, 28, 40, 'あなたはアロンの子らのために長服を作り、また彼らのために飾り帯を作り、彼らのために、栄光と美を表すターバンを作らなければならない。'),
('JPN', '出埃及记', 2, 28, 41, 'これらをあなたの兄弟アロン、および彼とともにいるその子らに着せ、彼らに油注ぎをし、彼らを祭司職に任命し、彼らを聖別し、祭司としてわたしに仕えさせよ。'),
('JPN', '出埃及记', 2, 28, 42, '彼らのために、裸をおおう亜麻布のももひきを作れ。それは腰からももまで届くようにする。'),
('JPN', '出埃及记', 2, 28, 43, 'アロンとその子らは、会見の天幕に入るとき、あるいは聖所で務めを行うために祭壇に近づくとき、これを着る。彼らが咎を負って死ぬことのないようにするためである。これは彼と彼の後の子孫のための永遠の掟である。'),
('JPN', '出埃及记', 2, 29, 1, '彼らを聖別し祭司としてわたしに仕えさせるために、彼らになすべきことは次のことである。若い雄牛一頭、傷のない雄羊二匹を取れ。'),
('JPN', '出埃及记', 2, 29, 2, 'また、種なしパン、油を混ぜた種なしの輪形パン、油を塗った種なしの薄焼きパンを取れ。これらは最良の小麦粉で作る。'),
('JPN', '出埃及记', 2, 29, 3, 'これらを一つのかごに入れ、そのかごと一緒に、先の一頭の雄牛と二匹の雄羊を連れて来る。'),
('JPN', '出埃及记', 2, 29, 4, 'アロンとその子らを会見の天幕の入り口に近づかせ、水で彼らを洗う。'),
('JPN', '出埃及记', 2, 29, 5, '装束を取り、長服と、エポデの下に着る青服と、エポデと胸当てをアロンに着せ、エポデのあや織りの帯を締める。'),
('JPN', '出埃及记', 2, 29, 6, '彼の頭にかぶり物をかぶらせ、そのかぶり物の上に聖なる記章を付ける。'),
('JPN', '出埃及记', 2, 29, 7, '注ぎの油を取って彼の頭に注ぎ、彼に油注ぎをする。'),
('JPN', '出埃及记', 2, 29, 8, 'それから彼の子らを連れて来て、彼らに長服を着せる。'),
('JPN', '出埃及记', 2, 29, 9, 'アロンとその子らに飾り帯を締め、ターバンを巻く。永遠の掟によって、祭司の職は彼らのものとなる。あなたはアロンとその子らを祭司職に任命せよ。'),
('JPN', '出埃及记', 2, 29, 10, 'あなたは雄牛を会見の天幕の前に近づかせ、アロンとその子らはその雄牛の頭に手を置く。'),
('JPN', '出埃及记', 2, 29, 11, 'あなたは会見の天幕の入り口で、主の前で、その雄牛を屠り、'),
('JPN', '出埃及记', 2, 29, 12, 'その雄牛の血を取り、あなたの指でこれを祭壇の四隅の角に塗る。その血はみな祭壇の土台に注ぐ。'),
('JPN', '出埃及记', 2, 29, 13, 'その内臓をおおうすべての脂肪、肝臓の小葉、二つの腎臓とその上の脂肪を取り出し、これらを祭壇の上で焼いて煙にする。'),
('JPN', '出埃及记', 2, 29, 14, 'その雄牛の肉と皮と汚物は宿営の外で火で焼く。これは罪のきよめのささげ物である。'),
('JPN', '出埃及记', 2, 29, 15, 'また、一匹の雄羊を取り、アロンとその子らはその雄羊の頭に手を置く。'),
('JPN', '出埃及记', 2, 29, 16, 'その雄羊を屠り、その血を取り、これを祭壇の側面に振りかける。'),
('JPN', '出埃及记', 2, 29, 17, 'また、その雄羊を各部に切り分け、その内臓とその足を洗い、これらをほかの部位や頭と一緒にし、'),
('JPN', '出埃及记', 2, 29, 18, 'その雄羊を全部、祭壇の上で焼いて煙にする。これは主への全焼のささげ物で、主への芳ばしい香り、食物のささげ物である。'),
('JPN', '出埃及记', 2, 29, 19, 'もう一匹の雄羊を取り、アロンとその子らはその雄羊の頭に手を置く。'),
('JPN', '出埃及记', 2, 29, 20, 'その雄羊を屠り、その血を取って、アロンの右の耳たぶと、その子らの右の耳たぶ、また彼らの右手の親指と右足の親指に塗り、その血を祭壇の側面に振りかける。'),
('JPN', '出埃及记', 2, 29, 21, '祭壇の上の血と、注ぎの油を取って、それをアロンとその装束、彼とともにいるその子らとその装束にかける。こうして、彼とその装束、彼とともにいるその子らとその装束は聖なるものとなる。'),
('JPN', '出埃及记', 2, 29, 22, '次に、その雄羊の脂肪、あぶら尾、内臓をおおう脂肪、肝臓の小葉、二つの腎臓とその上の脂肪、また右のももを取る。これは任職の雄羊である。'),
('JPN', '出埃及记', 2, 29, 23, 'また、主の前にある種なしパンのかごから、円形パン一つと、油を混ぜた輪形パン一つと、薄焼きパン一つを取る。'),
('JPN', '出埃及记', 2, 29, 24, 'そして、そのすべてをアロンの手のひらとその子らの手のひらに載せ、奉献物として主の前で揺り動かす。'),
('JPN', '出埃及记', 2, 29, 25, 'それらを彼らの手から取り、全焼のささげ物とともに、主の前の芳ばしい香りとして祭壇の上で焼いて煙にする。これは主への食物のささげ物である。'),
('JPN', '出埃及记', 2, 29, 26, 'アロンの任職のための雄羊の胸肉を取り、これを奉献物として主に向かって揺り動かす。これは、あなたの受ける分となる。'),
('JPN', '出埃及记', 2, 29, 27, 'アロンとその子らの任職のための雄羊の、奉献物として揺り動かされた胸肉と、奉納物として献げられたもも肉とを聖別する。'),
('JPN', '出埃及记', 2, 29, 28, 'それは、アロンとその子らがイスラエルの子らから受け取る永遠の割り当てとなる。それは奉納物である。それはイスラエルの子らからの交わりのいけにえの奉納物、主への奉納物であるから。'),
('JPN', '出埃及记', 2, 29, 29, 'アロンの聖なる装束は彼の跡を継ぐ子らのものとなり、彼らはこれを着けて油注がれ、これを着けて祭司職に任命される。'),
('JPN', '出埃及记', 2, 29, 30, '彼の子らのうちで、彼に代わって聖所で務めを行うために会見の天幕に入る祭司は、七日間、これを着る。'),
('JPN', '出埃及记', 2, 29, 31, 'あなたは任職のための雄羊を取り、聖なる所でその肉を煮なければならない。'),
('JPN', '出埃及记', 2, 29, 32, 'アロンとその子らは会見の天幕の入り口で、その雄羊の肉と、かごの中のパンを食べる。'),
('JPN', '出埃及记', 2, 29, 33, '彼らは、自分たちを任職し聖別するため、宥めに用いられたものを食べる。一般の者は食べてはならない。これらは聖なるものである。'),
('JPN', '出埃及记', 2, 29, 34, 'もし任職のための肉またはパンが朝まで残ったなら、その残りは火で燃やす。食べてはならない。これは聖なるものである。'),
('JPN', '出埃及记', 2, 29, 35, 'わたしがあなたに命じたすべてにしたがって、このようにアロンとその子らに行え。七日間、任職式を行わなければならない。'),
('JPN', '出埃及记', 2, 29, 36, '毎日、宥めのために、罪のきよめのささげ物として雄牛一頭を献げる。あなたはその上で宥めを行い、その祭壇から罪を除く。聖別するためにそれに油注ぎをする。'),
('JPN', '出埃及记', 2, 29, 37, '七日間、祭壇のために宥めを行い、それを聖別する。祭壇は最も聖なるものとなる。祭壇に触れるものはすべて、聖なるものとなる。'),
('JPN', '出埃及记', 2, 29, 38, '祭壇の上に献げるべき物は次のとおりである。毎日絶やすことなく、一歳の雄の子羊二匹。'),
('JPN', '出埃及记', 2, 29, 39, '朝、一匹の雄の子羊を献げ、夕暮れに、もう一匹の雄の子羊を献げる。'),
('JPN', '出埃及记', 2, 29, 40, '一匹の雄の子羊には、上質のオリーブ油四分の一ヒンを混ぜた最良の小麦粉十分の一エパと、また注ぎのささげ物としてぶどう酒四分の一ヒンが添えられる。'),
('JPN', '出埃及记', 2, 29, 41, 'もう一匹の雄の子羊は夕暮れに献げなければならない。これには、朝の穀物のささげ物や注ぎのささげ物を同じく添えて、献げなければならない。それは芳ばしい香りのためであり、主への食物のささげ物である。'),
('JPN', '出埃及记', 2, 29, 42, 'これは、主の前、会見の天幕の入り口での、あなたがたの代々にわたる常供の全焼のささげ物である。その場所でわたしはあなたがたに会い、その場所であなたと語る。'),
('JPN', '出埃及记', 2, 29, 43, 'その場所でわたしはイスラエルの子らと会う。そこは、わたしの栄光によって聖なるものとされる。'),
('JPN', '出埃及记', 2, 29, 44, 'わたしは会見の天幕と祭壇を聖別する。またアロンとその子らを聖別して、彼らを祭司としてわたしに仕えさせる。'),
('JPN', '出埃及记', 2, 29, 45, 'わたしはイスラエルの子らのただ中に住み、彼らの神となる。'),
('JPN', '出埃及记', 2, 29, 46, '彼らは、わたしが彼らの神、主であり、彼らのただ中に住むために、彼らをエジプトの地から導き出したことを知るようになる。わたしは彼らの神、主である。'),
('JPN', '出埃及记', 2, 30, 1, 'また、香をたくための祭壇を作れ。それをアカシヤ材で作る。'),
('JPN', '出埃及记', 2, 30, 2, '長さ一キュビト、幅一キュビトの正方形で、その高さは二キュビトとする。祭壇から角が出ているようにする。'),
('JPN', '出埃及记', 2, 30, 3, '祭壇の上面と、側面すべて、および角には純金をかぶせ、その周りには金の飾り縁を作る。'),
('JPN', '出埃及记', 2, 30, 4, 'また、その祭壇のために二つの金の環を作る。その飾り縁の下の両側に、相対するように作る。これは祭壇を担ぐ棒を通すところとする。'),
('JPN', '出埃及记', 2, 30, 5, 'その棒はアカシヤ材で作り、それに金をかぶせる。'),
('JPN', '出埃及记', 2, 30, 6, 'それを、あかしの箱をさえぎる垂れ幕の手前、わたしがあなたと会う、あかしの箱の上の『宥めの蓋』の手前に置く。'),
('JPN', '出埃及记', 2, 30, 7, 'アロンはその上で香りの高い香をたく。朝ごとにともしびを整え、煙を立ち上らせる。'),
('JPN', '出埃及记', 2, 30, 8, 'アロンは夕暮れにともしびをともすときにも、煙を立ち上らせる。これは、あなたがたの代々にわたる、主の前の常供の香のささげ物である。'),
('JPN', '出埃及记', 2, 30, 9, 'あなたがたはその上で、異なった香や全焼のささげ物や穀物のささげ物を献げてはならない。また、その上に、注ぎのぶどう酒を注いではならない。'),
('JPN', '出埃及记', 2, 30, 10, 'アロンは年に一度、その角の上で宥めを行う。その祭壇のために、罪のきよめのささげ物の、宥めのための血によって、彼は代々にわたり、年に一度、宥めを行う。これは主にとって最も聖なるものである。」'),
('JPN', '出埃及记', 2, 30, 11, '主はモーセに告げられた。'),
('JPN', '出埃及记', 2, 30, 12, '「あなたがイスラエルの子らの登録のためにその頭数を調べるとき、各人はその登録にあたり、自分のたましいの償い金を主に納めなければならない。これは、彼らの登録にあたり、彼らにわざわいが起こらないようにするためである。'),
('JPN', '出埃及记', 2, 30, 13, '登録される者がそれぞれ納めるのは、これである。聖所のシェケルで半シェケル。一シェケルは二十ゲラで、半シェケルが主への奉納物である。'),
('JPN', '出埃及记', 2, 30, 14, '二十歳またそれ以上の者で、登録される者はみな、主にこの奉納物を納める。'),
('JPN', '出埃及记', 2, 30, 15, 'あなたがたのたましいのために宥めを行おうと、主に奉納物を納めるときには、富む人も半シェケルより多く払ってはならず、貧しい人もそれより少なく払ってはならない。'),
('JPN', '出埃及记', 2, 30, 16, 'イスラエルの子らから償いのための銀を受け取ったなら、それを会見の天幕の用に充てる。こうしてそれは、イスラエルの子らにとって、あなたがたのたましいに宥めがなされたことに対する、主の前での記念となる。」'),
('JPN', '出埃及记', 2, 30, 17, '主はまた、モーセに告げられた。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '出埃及记', 2, 30, 18, '「洗いのために洗盤とその台を青銅で作り、それを会見の天幕と祭壇の間に置き、その中に水を入れよ。'),
('JPN', '出埃及记', 2, 30, 19, 'アロンとその子らは、そこで手と足を洗う。'),
('JPN', '出埃及记', 2, 30, 20, '彼らが会見の天幕に入るときには水を浴びる。彼らが死ぬことのないようにするためである。また、彼らが、主への食物のささげ物を焼いて煙にする務めのために祭壇に近づくときにも、'),
('JPN', '出埃及记', 2, 30, 21, 'その手、その足を洗う。彼らが死ぬことのないようにするためである。これは、彼とその子孫にとって代々にわたる永遠の掟である。」'),
('JPN', '出埃及记', 2, 30, 22, '主はモーセにこう告げられた。'),
('JPN', '出埃及记', 2, 30, 23, '「あなたは最上の香料を取れ。液体の没薬を五百シェケル、香りの良いシナモンをその半分の二百五十シェケル、香りの良い菖蒲を二百五十シェケル、'),
('JPN', '出埃及记', 2, 30, 24, '桂枝を聖所のシェケルで五百シェケル、オリーブ油を一ヒン。'),
('JPN', '出埃及记', 2, 30, 25, 'あなたは調香の技法を凝らしてこれらを調合し、聖なる注ぎの油を作る。これが聖なる注ぎの油となる。'),
('JPN', '出埃及记', 2, 30, 26, 'そして、次のものに油注ぎを行う。会見の天幕、あかしの箱、'),
('JPN', '出埃及记', 2, 30, 27, '机とそのすべての備品、燭台とそのすべての器具、香の祭壇、'),
('JPN', '出埃及记', 2, 30, 28, '全焼のささげ物の祭壇とそのすべての用具、洗盤とその台。'),
('JPN', '出埃及记', 2, 30, 29, 'こうして、これらを聖別するなら、それは最も聖なるものとなる。これらに触れるものはすべて、聖なるものとなる。'),
('JPN', '出埃及记', 2, 30, 30, 'あなたはアロンとその子らに油注ぎを行い、彼らを聖別して、祭司としてわたしに仕えさせなければならない。'),
('JPN', '出埃及记', 2, 30, 31, 'あなたはイスラエルの子らに告げよ。これは、あなたがたの代々にわたり、わたしにとって聖なる注ぎの油となる。'),
('JPN', '出埃及记', 2, 30, 32, 'これを人のからだに注いではならない。また、この割合で、これと似たものを作ってはならない。これは聖なるものであり、あなたがたにとっても聖なるものでなければならない。'),
('JPN', '出埃及记', 2, 30, 33, 'すべて、これと似たものを調合する者、または、これをほかの人に付ける者は、だれでも自分の民から断ち切られる。」'),
('JPN', '出埃及记', 2, 30, 34, '主はモーセに言われた。「あなたは香料のナタフ香、シェヘレテ香、ヘルベナ香と純粋な乳香を取れ。これらは、それぞれ同じ量でなければならない。'),
('JPN', '出埃及记', 2, 30, 35, 'これをもって、調香の技法を凝らして調合された、塩気のある、きよい、聖なる香を作れ。'),
('JPN', '出埃及记', 2, 30, 36, 'また、その一部を打ち砕いて粉にし、その一部を、わたしがあなたと会う会見の天幕の中のあかしの箱の前に供える。これは、あなたがたにとって最も聖なるものである。'),
('JPN', '出埃及记', 2, 30, 37, 'その割合で作る香を自分たちのために作ってはならない。それはあなたにとって、主に対して聖なるものである。'),
('JPN', '出埃及记', 2, 30, 38, 'これと似たものを作って、これを嗅ぐ者は、自分の民の間から断ち切られる。」'),
('JPN', '出埃及记', 2, 31, 1, '主はモーセに次のように告げられた。'),
('JPN', '出埃及记', 2, 31, 2, '「見よ。わたしは、ユダ部族に属する、フルの子ウリの子ベツァルエルを名指して召し、'),
('JPN', '出埃及记', 2, 31, 3, '彼に、知恵と英知と知識とあらゆる務めにおいて、神の霊を満たした。'),
('JPN', '出埃及记', 2, 31, 4, 'それは、彼が金や銀や青銅の細工に意匠を凝らし、'),
('JPN', '出埃及记', 2, 31, 5, 'はめ込みの宝石を彫刻し、木を彫刻し、あらゆる仕事をするためである。'),
('JPN', '出埃及记', 2, 31, 6, '見よ。わたしは、ダン部族に属する、アヒサマクの子オホリアブを彼とともにいるようにする。わたしは、すべて心に知恵ある者の心に知恵を授ける。彼らは、わたしがあなたに命じたすべてのものを作る。'),
('JPN', '出埃及记', 2, 31, 7, 'すなわち、会見の天幕、あかしの箱、その上の『宥めの蓋』、天幕のすべての備品、'),
('JPN', '出埃及记', 2, 31, 8, '机とその備品、きよい燭台とそのすべての器具、香の祭壇、'),
('JPN', '出埃及记', 2, 31, 9, '全焼のささげ物の祭壇とそのすべての用具、洗盤とその台、'),
('JPN', '出埃及记', 2, 31, 10, '式服、すなわち、祭司アロンの聖なる装束と、その子らが祭司として仕えるための装束、'),
('JPN', '出埃及记', 2, 31, 11, '注ぎの油、聖所のための香り高い香である。彼らは、すべて、わたしがあなたに命じたとおりに作らなければならない。」'),
('JPN', '出埃及记', 2, 31, 12, '主はモーセに告げられた。'),
('JPN', '出埃及记', 2, 31, 13, '「あなたはイスラエルの子らに告げよ。あなたがたは、必ずわたしの安息を守らなければならない。これは、代々にわたり、わたしとあなたがたとの間のしるしである。わたしが主であり、あなたがたを聖別する者であることを、あなたがたが知るためである。'),
('JPN', '出埃及记', 2, 31, 14, 'あなたがたは、この安息を守らなければならない。これは、あなたがたにとって聖なるものだからである。これを汚す者は必ず殺されなければならない。この安息中に仕事をする者はだれでも、自分の民の間から断ち切られる。'),
('JPN', '出埃及记', 2, 31, 15, '六日間は仕事をする。しかし、七日目は主の聖なる全き安息である。安息日に仕事をする者は、だれでも必ず殺されなければならない。'),
('JPN', '出埃及记', 2, 31, 16, 'イスラエルの子らはこの安息を守り、永遠の契約として、代々にわたり、この安息を守らなければならない。'),
('JPN', '出埃及记', 2, 31, 17, 'これは永遠に、わたしとイスラエルの子らとの間のしるしである。それは主が六日間で天と地を造り、七日目にやめて、休息したからである。」'),
('JPN', '出埃及记', 2, 31, 18, 'こうして主は、シナイ山でモーセと語り終えたとき、さとしの板を二枚、すなわち神の指で書き記された石の板をモーセにお授けになった。'),
('JPN', '出埃及记', 2, 32, 1, '民はモーセが山から一向に下りて来ようとしないのを見て、アロンのもとに集まり、彼に言った。「さあ、われわれに先立って行く神々を、われわれのために造ってほしい。われわれをエジプトの地から導き上った、あのモーセという者がどうなったのか、分からないから。」'),
('JPN', '出埃及记', 2, 32, 2, 'それでアロンは彼らに言った。「あなたがたの妻や、息子、娘たちの耳にある金の耳輪を外して、私のところに持って来なさい。」'),
('JPN', '出埃及记', 2, 32, 3, '民はみな、その耳にある金の耳輪を外して、アロンのところに持って来た。'),
('JPN', '出埃及记', 2, 32, 4, '彼はそれを彼らの手から受け取ると、のみで鋳型を造り、それを鋳物の子牛にした。彼らは言った。「イスラエルよ、これがあなたをエジプトの地から導き上った、あなたの神々だ。」'),
('JPN', '出埃及记', 2, 32, 5, 'アロンはこれを見て、その前に祭壇を築いた。そして、アロンは呼びかけて言った。「明日は主への祭りである。」'),
('JPN', '出埃及记', 2, 32, 6, '彼らは翌朝早く全焼のささげ物を献げ、交わりのいけにえを供えた。そして民は、座っては食べたり飲んだりし、立っては戯れた。'),
('JPN', '出埃及记', 2, 32, 7, '主はモーセに言われた。「さあ、下りて行け。あなたがエジプトの地から連れ上ったあなたの民は、堕落してしまった。'),
('JPN', '出埃及记', 2, 32, 8, '彼らは早くも、わたしが彼らに命じた道から外れてしまった。彼らは自分たちのために鋳物の子牛を造り、それを伏し拝み、それにいけにえを献げ、『イスラエルよ、これがあなたをエジプトの地から導き上った、あなたの神々だ』と言っている。」'),
('JPN', '出埃及记', 2, 32, 9, '主はまた、モーセに言われた。「わたしはこの民を見た。これは実に、うなじを固くする民だ。'),
('JPN', '出埃及记', 2, 32, 10, '今は、わたしに任せよ。わたしの怒りが彼らに向かって燃え上がり、わたしが彼らを絶ち滅ぼすためだ。しかし、わたしはあなたを大いなる国民とする。」'),
('JPN', '出埃及记', 2, 32, 11, 'しかしモーセは、自分の神、主に嘆願して言った。「主よ。あなたが偉大な力と力強い御手をもって、エジプトの地から導き出されたご自分の民に向かって、どうして御怒りを燃やされるのですか。'),
('JPN', '出埃及记', 2, 32, 12, 'どうしてエジプト人に、『神は、彼らを山地で殺し、地の面から絶ち滅ぼすために、悪意をもって彼らを連れ出したのだ』と言わせてよいでしょうか。どうか、あなたの燃える怒りを収め、ご自身の民へのわざわいを思い直してください。'),
('JPN', '出埃及记', 2, 32, 13, 'あなたのしもべアブラハム、イサク、イスラエルを思い起こしてください。あなたはご自分にかけて彼らに誓い、そして彼らに、『わたしはあなたがたの子孫を空の星のように増し加え、わたしが約束したこの地すべてをあなたがたの子孫に与え、彼らは永久にこれをゆずりとして受け継ぐ』と言われました。」'),
('JPN', '出埃及记', 2, 32, 14, 'すると主は、その民に下すと言ったわざわいを思い直された。'),
('JPN', '出埃及记', 2, 32, 15, 'モーセは向きを変え、山から下りた。彼の手には二枚のさとしの板があった。板は両面に、すなわち表と裏に書かれていた。'),
('JPN', '出埃及记', 2, 32, 16, 'その板は神の作であった。その筆跡は神の筆跡で、その板に刻まれていた。'),
('JPN', '出埃及记', 2, 32, 17, 'ヨシュアは民の叫ぶ大声を聞いて、モーセに言った。「宿営の中に戦の声があります。」'),
('JPN', '出埃及记', 2, 32, 18, 'モーセは言った。「あれは勝利を叫ぶ声でも敗北を嘆く声でもない。私が聞くのは歌いさわぐ声である。」'),
('JPN', '出埃及记', 2, 32, 19, '宿営に近づいて、子牛と踊りを見るなり、モーセの怒りは燃え上がった。そして、手にしていたあの板を投げ捨て、それらを山のふもとで砕いた。'),
('JPN', '出埃及记', 2, 32, 20, 'それから、彼らが造った子牛を取って火で焼き、さらにそれを粉々に砕いて水の上にまき散らし、イスラエルの子らに飲ませた。'),
('JPN', '出埃及记', 2, 32, 21, 'モーセはアロンに言った。「この民はあなたに何をしたのですか。あなたが彼らの上にこのような大きな罪をもたらすとは。」'),
('JPN', '出埃及记', 2, 32, 22, 'アロンは言った。「わが主よ、どうか怒りを燃やさないでください。あなた自身、この民が悪に染まっているのをよくご存じのはずです。'),
('JPN', '出埃及记', 2, 32, 23, '彼らは私に言いました。『われわれに先立って行く神々を、われわれのために造ってほしい。われわれをエジプトの地から連れ上った、あのモーセという者がどうなったのか、分からないから。』'),
('JPN', '出埃及记', 2, 32, 24, 'それで私は彼らに『だれでも金を持っている者は、それを取り外せ』と言いました。彼らはそれを私に渡したので、私がこれを火に投げ入れたところ、この子牛が出て来たのです。」'),
('JPN', '出埃及记', 2, 32, 25, 'モーセは、民が乱れていて、アロンが彼らを放っておいたので、敵の笑いものとなっているのを見た。'),
('JPN', '出埃及记', 2, 32, 26, 'そこでモーセは宿営の入り口に立って、「だれでも主につく者は私のところに来なさい」と言った。すると、レビ族がみな彼のところに集まった。'),
('JPN', '出埃及记', 2, 32, 27, 'そこで、モーセは彼らに言った。「イスラエルの神、主はこう言われる。各自腰に剣を帯びよ。宿営の中を入り口から入り口へ行き巡り、各自、自分の兄弟、自分の友、自分の隣人を殺せ。」'),
('JPN', '出埃及记', 2, 32, 28, 'レビ族はモーセのことばどおりに行った。その日、民のうちの約三千人が倒れた。'),
('JPN', '出埃及记', 2, 32, 29, 'モーセは言った。「あなたがたは各自、その子、その兄弟に逆らっても、今日、主に身を献げた。主があなたがたに、今日、祝福を与えてくださるように。」'),
('JPN', '出埃及记', 2, 32, 30, '翌日になって、モーセは民に言った。「あなたがたは大きな罪を犯した。だから今、私は主のところに上って行く。もしかすると、あなたがたの罪のために宥めをすることができるかもしれない。」'),
('JPN', '出埃及记', 2, 32, 31, 'そこでモーセは主のところに戻って言った。「ああ、この民は大きな罪を犯しました。自分たちのために金の神を造ったのです。'),
('JPN', '出埃及记', 2, 32, 32, '今、もしあなたが彼らの罪を赦してくださるなら──。しかし、もし、かなわないなら、どうかあなたがお書きになった書物から私の名を消し去ってください。」'),
('JPN', '出埃及记', 2, 32, 33, '主はモーセに言われた。「わたしの前に罪ある者はだれであれ、わたしの書物から消し去る。'),
('JPN', '出埃及记', 2, 32, 34, 'しかし、今は行って、わたしがあなたに告げた場所に民を導け。見よ、わたしの使いがあなたの前を行く。だが、わたしが報いる日に、わたしは彼らの上にその罪の報いをする。」'),
('JPN', '出埃及记', 2, 32, 35, 'こうして主は民を打たれた。彼らが子牛を造ったからである。それはアロンが造ったのであった。'),
('JPN', '出埃及记', 2, 33, 1, '主はモーセに言われた。「あなたも、あなたがエジプトの地から連れ上った民も、ここから上って行って、わたしがアブラハム、イサク、ヤコブに誓って、『これをあなたの子孫に与える』と言った地に行け。'),
('JPN', '出埃及记', 2, 33, 2, 'わたしはあなたがたの前に一人の使いを遣わし、カナン人、アモリ人、ヒッタイト人、ペリジ人、ヒビ人、エブス人を追い払い、'),
('JPN', '出埃及记', 2, 33, 3, '乳と蜜の流れる地にあなたがたを行かせる。しかし、わたしは、あなたがたのただ中にあっては上らない。あなたがたはうなじを固くする民なので、わたしが途中であなたがたを絶ち滅ぼしてしまわないようにするためだ。」'),
('JPN', '出埃及记', 2, 33, 4, '民はこの悪い知らせを聞いて嘆き悲しみ、一人も飾り物を身に着ける者はいなかった。'),
('JPN', '出埃及记', 2, 33, 5, '主はモーセに次のように命じておられた。「イスラエルの子らに言え。『あなたがたは、うなじを固くする民だ。一時でも、あなたがたのただ中にあって上って行こうものなら、わたしはあなたがたを絶ち滅ぼしてしまうだろう。今、飾り物を身から取り外しなさい。そうすれば、あなたがたのために何をするべきかを考えよう。』」'),
('JPN', '出埃及记', 2, 33, 6, 'それでイスラエルの子らは、ホレブの山以後、自分の飾り物を外した。'),
('JPN', '出埃及记', 2, 33, 7, 'さて、モーセはいつも天幕を取り、自分のためにこれを宿営の外の、宿営から離れたところに張り、そして、これを会見の天幕と呼んでいた。だれでも主に伺いを立てる者は、宿営の外にある会見の天幕に行くのを常としていた。'),
('JPN', '出埃及记', 2, 33, 8, 'モーセがこの天幕に出て行くときは、民はみな立ち上がり、それぞれ自分の天幕の入り口に立って、モーセが天幕に入るまで彼を見守った。'),
('JPN', '出埃及记', 2, 33, 9, 'モーセがその天幕に入ると、雲の柱が降りて来て、天幕の入り口に立った。こうして主はモーセと語られた。'),
('JPN', '出埃及记', 2, 33, 10, '雲の柱が天幕の入り口に立つのを見ると、民はみな立ち上がって、それぞれ自分の天幕の入り口で伏し拝んだ。'),
('JPN', '出埃及记', 2, 33, 11, '主は、人が自分の友と語るように、顔と顔を合わせてモーセと語られた。モーセが宿営に帰るとき、彼の従者でヌンの子ヨシュアという若者が天幕から離れないでいた。'),
('JPN', '出埃及记', 2, 33, 12, 'さて、モーセは主に言った。「ご覧ください。あなたは私に『この民を連れ上れ』と言われます。しかし、だれを私と一緒に遣わすかを知らせてくださいません。しかも、あなたご自身が、『わたしは、あなたを名指して選び出した。あなたは特にわたしの心にかなっている』と言われました。'),
('JPN', '出埃及记', 2, 33, 13, '今、もしも私がみこころにかなっているのでしたら、どうかあなたの道を教えてください。そうすれば、私があなたを知ることができ、みこころにかなうようになれます。この国民があなたの民であることを心に留めてください。」'),
('JPN', '出埃及记', 2, 33, 14, '主は言われた。「わたしの臨在がともに行き、あなたを休ませる。」'),
('JPN', '出埃及记', 2, 33, 15, 'モーセは言った。「もしあなたのご臨在がともに行かないのなら、私たちをここから導き上らないでください。'),
('JPN', '出埃及记', 2, 33, 16, '私とあなたの民がみこころにかなっていることは、いったい何によって知られるのでしょう。それは、あなたが私たちと一緒に行き、私とあなたの民が地上のすべての民と異なり、特別に扱われることによるのではないでしょうか。」'),
('JPN', '出埃及记', 2, 33, 17, '主はモーセに言われた。「あなたの言ったそのことも、わたしはしよう。あなたはわたしの心にかない、あなたを名指して選び出したのだから。」'),
('JPN', '出埃及记', 2, 33, 18, 'モーセは言った。「どうか、あなたの栄光を私に見せてください。」'),
('JPN', '出埃及记', 2, 33, 19, '主は言われた。「わたし自身、わたしのあらゆる良きものをあなたの前に通らせ、主の名であなたの前に宣言する。わたしは恵もうと思う者を恵み、あわれもうと思う者をあわれむ。」'),
('JPN', '出埃及记', 2, 33, 20, 'また言われた。「あなたはわたしの顔を見ることはできない。人はわたしを見て、なお生きていることはできないからである。」'),
('JPN', '出埃及记', 2, 33, 21, 'また主は言われた。「見よ、わたしの傍らに一つの場所がある。あなたは岩の上に立て。'),
('JPN', '出埃及记', 2, 33, 22, 'わたしの栄光が通り過ぎるときには、わたしはあなたを岩の裂け目に入れる。わたしが通り過ぎるまで、この手であなたをおおっておく。'),
('JPN', '出埃及记', 2, 33, 23, 'わたしが手をのけると、あなたはわたしのうしろを見るが、わたしの顔は決して見られない。」'),
('JPN', '出埃及记', 2, 34, 1, '主はモーセに言われた。「前のものと同じような二枚の石の板を切り取れ。わたしはその石の板の上に、あなたが砕いたこの前の石の板にあった、あのことばを書き記す。'),
('JPN', '出埃及记', 2, 34, 2, '朝までに準備をし、朝シナイ山に登って、その山の頂でわたしの前に立て。'),
('JPN', '出埃及记', 2, 34, 3, 'だれも、あなたと一緒に登ってはならない。また、だれも、山のどこにも人影があってはならない。また、羊でも牛でも、その山のふもとで草を食べていてはならない。」'),
('JPN', '出埃及记', 2, 34, 4, 'そこで、モーセは前のものと同じような二枚の石の板を切り取り、翌朝早く、主が命じられたとおりにシナイ山に登った。彼は手に二枚の石の板を持っていた。'),
('JPN', '出埃及记', 2, 34, 5, '主は雲の中にあって降りて来られ、彼とともにそこに立って、主の名を宣言された。'),
('JPN', '出埃及记', 2, 34, 6, '主は彼の前を通り過ぎるとき、こう宣言された。「主、主は、あわれみ深く、情け深い神。怒るのに遅く、恵みとまことに富み、'),
('JPN', '出埃及记', 2, 34, 7, '恵みを千代まで保ち、咎と背きと罪を赦す。しかし、罰すべき者を必ず罰して、父の咎を子に、さらに子の子に、三代、四代に報いる者である。」'),
('JPN', '出埃及记', 2, 34, 8, 'モーセは急いで地にひざまずき、ひれ伏した。'),
('JPN', '出埃及记', 2, 34, 9, '彼は言った。「ああ、主よ。もし私がみこころにかなっているのでしたら、どうか主が私たちのただ中にいて、進んでくださいますように。確かに、この民はうなじを固くする民ですが、どうか私たちの咎と罪を赦し、私たちをご自分の所有としてくださいますように。」'),
('JPN', '出埃及记', 2, 34, 10, '主は言われた。「今ここで、わたしは契約を結ぼう。わたしは、あなたの民がみないるところで、地のどこにおいても、また、どの国においても、かつてなされたことがない奇しいことを行う。あなたがそのただ中にいるこの民はみな、主のわざを見る。わたしがあなたとともに行うことは恐るべきことである。'),
('JPN', '出埃及记', 2, 34, 11, 'わたしが今日あなたに命じることを守れ。見よ、わたしは、アモリ人、カナン人、ヒッタイト人、ペリジ人、ヒビ人、エブス人を、あなたの前から追い払う。'),
('JPN', '出埃及记', 2, 34, 12, 'あなたは、あなたが入って行くその地の住民と契約を結ばないように注意せよ。それがあなたのただ中で罠とならないようにするためだ。'),
('JPN', '出埃及记', 2, 34, 13, 'いや、あなたがたは彼らの祭壇を打ち壊し、彼らの石の柱を打ち砕き、アシェラ像を切り倒さなければならない。'),
('JPN', '出埃及记', 2, 34, 14, 'あなたは、ほかの神を拝んではならない。主は、その名がねたみであり、ねたみの神であるから。'),
('JPN', '出埃及记', 2, 34, 15, 'あなたはその地の住民と契約を結ばないようにせよ。彼らは自分たちの神々と淫行をし、自分たちの神々にいけにえを献げ、あなたを招く。あなたは、そのいけにえを食べるようになる。'),
('JPN', '出埃及记', 2, 34, 16, '彼らの娘たちをあなたの息子たちの妻とするなら、その娘たちは自分たちの神々と淫行を行い、あなたの息子たちに自分たちの神々と淫行を行わせるようになる。'),
('JPN', '出埃及记', 2, 34, 17, 'あなたは、自分のために鋳物の神々を造ってはならない。'),
('JPN', '出埃及记', 2, 34, 18, 'あなたは種なしパンの祭りを守らなければならない。アビブの月の定められた時に七日間、わたしが命じた種なしパンを食べる。あなたはアビブの月にエジプトを出たからである。'),
('JPN', '出埃及记', 2, 34, 19, '最初に胎を開くものはすべて、わたしのものである。あなたの家畜の雄の初子はみな、牛も羊もそうである。'),
('JPN', '出埃及记', 2, 34, 20, 'ただし、ろばの初子は羊で贖わなければならない。もし贖わないなら、その首を折る。また、あなたの息子のうち長子はみな、贖わなければならない。だれも、何も持たずに、わたしの前に出てはならない。'),
('JPN', '出埃及记', 2, 34, 21, 'あなたは六日間は働き、七日目には休まなければならない。耕作の時にも刈り入れの時にも、休まなければならない。'),
('JPN', '出埃及记', 2, 34, 22, '小麦の刈り入れの初穂のためには七週の祭りを、年の変わり目には収穫祭を行わなければならない。'),
('JPN', '出埃及记', 2, 34, 23, '年に三度、男子はみな、イスラエルの神、主、主の前に出なければならない。'),
('JPN', '出埃及记', 2, 34, 24, 'わたしがあなたの前から異邦の民を追い出し、あなたの国境を広げるので、あなたが年に三度、あなたの神、主の前に出ようとして上って行くときも、あなたの地を欲しがる者はだれもいない。'),
('JPN', '出埃及记', 2, 34, 25, 'わたしへのいけにえの血を、種入りのパンに添えて献げてはならない。また、過越の祭りのいけにえを朝まで残しておいてはならない。'),
('JPN', '出埃及记', 2, 34, 26, 'あなたの土地から取れる初穂の最上のものを、あなたの神、主の家に持って来なければならない。あなたは子やぎをその母の乳で煮てはならない。」'),
('JPN', '出埃及记', 2, 34, 27, '主はモーセに言われた。「これらのことばを書き記せ。わたしは、これらのことばによって、あなたと、そしてイスラエルと契約を結んだからである。」'),
('JPN', '出埃及记', 2, 34, 28, 'モーセはそこに四十日四十夜、主とともにいた。彼はパンも食べず、水も飲まなかった。そして、石の板に契約のことば、十のことばを書き記した。'),
('JPN', '出埃及记', 2, 34, 29, 'それから、モーセはシナイ山から下りて来た。モーセが山を下りて来たとき、その手に二枚のさとしの板を持っていた。モーセは、主と話したために自分の顔の肌が輝きを放っているのを知らなかった。'),
('JPN', '出埃及记', 2, 34, 30, 'アロンと、イスラエルの子らはみなモーセを見た。なんと、彼の顔の肌は輝きを放っていた。それで彼らは彼に近づくのを恐れた。'),
('JPN', '出埃及记', 2, 34, 31, 'モーセが彼らを呼び寄せると、アロンと、会衆の上に立つ族長はみな彼のところに戻って来た。モーセは彼らに話しかけた。'),
('JPN', '出埃及记', 2, 34, 32, 'それから、イスラエルの子らはみな近寄って来た。彼は主がシナイ山で告げられたことを、ことごとく彼らに命じた。'),
('JPN', '出埃及记', 2, 34, 33, 'モーセは彼らと語り終えると、顔に覆いを掛けた。'),
('JPN', '出埃及记', 2, 34, 34, 'モーセが主と語るために主の前に行くとき、彼はその覆いを外に出て来るまで外していた。外に出て来ると、命じられたことをイスラエルの子らに告げた。'),
('JPN', '出埃及记', 2, 34, 35, 'イスラエルの子らがモーセの顔を見ると、モーセの顔の肌は輝きを放っていた。モーセは、主と語るために入って行くまで、自分の顔に再び覆いを掛けるのを常としていた。'),
('JPN', '出埃及记', 2, 35, 1, 'モーセはイスラエルの全会衆を集めて、彼らに言った。「これは、主が行えと命じられたことである。'),
('JPN', '出埃及记', 2, 35, 2, '六日間は仕事をする。しかし、七日目は、あなたがたにとって主の聖なる全き安息である。この日に仕事をする者は、だれでも殺されなければならない。'),
('JPN', '出埃及记', 2, 35, 3, '安息日には、あなたがたの住まいのどこであっても、火をたいてはならない。」'),
('JPN', '出埃及记', 2, 35, 4, 'モーセはイスラエルの全会衆に告げた。「これは主が命じられたことである。'),
('JPN', '出埃及记', 2, 35, 5, 'あなたがたの中から主への奉納物を受け取りなさい。すべて、進んで献げる心のある人に、主への奉納物を持って来させなさい。すなわち、金、銀、青銅、'),
('JPN', '出埃及记', 2, 35, 6, '青、紫、緋色の撚り糸、亜麻布、やぎの毛、'),
('JPN', '出埃及记', 2, 35, 7, '赤くなめした雄羊の皮、じゅごんの皮、アカシヤ材、'),
('JPN', '出埃及记', 2, 35, 8, 'ともしび用の油、注ぎの油と、香り高い香のための香料、'),
('JPN', '出埃及记', 2, 35, 9, 'エポデや胸当てにはめ込む、縞めのうや宝石である。'),
('JPN', '出埃及记', 2, 35, 10, 'あなたがたのうち、心に知恵ある者はみな来て、主が命じられたものをすべて造らなければならない。'),
('JPN', '出埃及记', 2, 35, 11, '幕屋と、その天幕、覆い、留め金、板、横木、柱、台座、'),
('JPN', '出埃及记', 2, 35, 12, '箱と、その棒、『宥めの蓋』、仕切りの垂れ幕、'),
('JPN', '出埃及记', 2, 35, 13, '机と、その棒とそのすべての備品、臨在のパン、'),
('JPN', '出埃及记', 2, 35, 14, 'ともしびのための燭台と、その器具、ともしび皿、ともしび用の油、'),
('JPN', '出埃及记', 2, 35, 15, '香の祭壇と、その棒、注ぎの油、香り高い香、そして幕屋の入り口に付ける入り口の垂れ幕、'),
('JPN', '出埃及记', 2, 35, 16, '全焼のささげ物の祭壇と、それに付属する青銅の格子、その棒とそのすべての用具、洗盤とその台、'),
('JPN', '出埃及记', 2, 35, 17, '庭の掛け幕と、その柱、その台座、庭の門の垂れ幕、'),
('JPN', '出埃及记', 2, 35, 18, '幕屋の杭、庭の杭、そのひも、'),
('JPN', '出埃及记', 2, 35, 19, '聖所で務めを行うための式服、すなわち、祭司アロンの聖なる装束と、祭司として仕える彼の子らの装束である。」'),
('JPN', '出埃及记', 2, 35, 20, 'イスラエルの全会衆はモーセの前から立ち去った。'),
('JPN', '出埃及记', 2, 35, 21, '心を動かされた者、霊に促しを受けた者はみな、会見の天幕の仕事のため、そのあらゆる奉仕のため、また聖なる装束のために、主への奉納物を持って来た。'),
('JPN', '出埃及记', 2, 35, 22, '進んで献げる心のある者はみな、男も女も、飾り輪、耳輪、指輪、首飾り、すべての金の飾り物を持って来た。金の奉献物を主に献げる者はみな、そのようにした。'),
('JPN', '出埃及记', 2, 35, 23, 'また、青、紫、緋色の撚り糸、亜麻布、やぎの毛、赤くなめした雄羊の皮、じゅごんの皮を持っている者はみな、それを持って来た。'),
('JPN', '出埃及记', 2, 35, 24, '銀や青銅の奉納物を献げる者はみな、それを主への奉納物として持って来た。アカシヤ材を持っている者はみな、奉仕のあらゆる仕事のためにそれを持って来た。'),
('JPN', '出埃及记', 2, 35, 25, 'また、心に知恵ある女もみな、自分の手で紡ぎ、その紡いだ青、紫、緋色の撚り糸、それに亜麻布を持って来た。'),
('JPN', '出埃及记', 2, 35, 26, '心を動かされ、知恵を用いたいと思った女たちはみな、やぎの毛を紡いだ。'),
('JPN', '出埃及记', 2, 35, 27, '部族の長たちは、エポデと胸当てにはめ込む、縞めのうや宝石を持って来た。'),
('JPN', '出埃及记', 2, 35, 28, 'また、ともしび、注ぎの油のため、また香りの高い香のために、香料と油を持って来た。'),
('JPN', '出埃及记', 2, 35, 29, 'イスラエルの子らは男も女もみな、主がモーセを通して行うように命じられたすべての仕事のために、心から進んで献げたのであり、それを進んで献げるものとして主に持って来た。'),
('JPN', '出埃及记', 2, 35, 30, 'モーセはイスラエルの子らに言った。「見よ。主は、ユダ部族の、フルの子ウリの子ベツァルエルを名指して召し、'),
('JPN', '出埃及记', 2, 35, 31, '彼に、知恵と英知と知識とあらゆる仕事において、神の霊を満たされた。'),
('JPN', '出埃及记', 2, 35, 32, 'それは、彼が金や銀や青銅の細工に意匠を凝らし、'),
('JPN', '出埃及记', 2, 35, 33, 'はめ込みの宝石を彫刻し、木を彫刻し、意匠を凝らす仕事をするためである。'),
('JPN', '出埃及记', 2, 35, 34, 'また、彼の心に人を教える力をお与えになった。彼と、ダン部族のアヒサマクの子オホリアブに、そのようにされた。'),
('JPN', '出埃及记', 2, 35, 35, '主は彼らをすぐれた知恵で満たされた。それは彼らが、あらゆる仕事と巧みな設計をなす者として、彫刻する者、設計する者、青、紫、緋色の撚り糸と亜麻布で刺繡する者、また機織りをする者の仕事を成し遂げるためである。'),
('JPN', '出埃及记', 2, 36, 1, 'ベツァルエルとオホリアブ、および、聖所の奉仕のあらゆる仕事をする知恵と英知を主に授けられた、心に知恵ある者はみな、すべて主が命じられたとおりに仕事をしなければならない。」'),
('JPN', '出埃及记', 2, 36, 2, 'モーセは、ベツァルエルとオホリアブ、および主が心に知恵を授けられた、すべて心に知恵ある者、またその仕事をするために進み出ようと、心を動かされた者をみな呼び寄せた。'),
('JPN', '出埃及记', 2, 36, 3, '彼らは、聖所を造る奉仕の仕事のためにイスラエルの子らが持って来たすべての奉納物を、モーセから受け取った。しかしイスラエルの子らは、なおも朝ごとに、進んで献げるものを彼のところに持って来た。'),
('JPN', '出埃及记', 2, 36, 4, 'そこで、聖所のすべての仕事をしていた知恵のある者はみな、それぞれ自分がしていた仕事から離れてやって来て、'),
('JPN', '出埃及记', 2, 36, 5, 'モーセに告げて言った。「民は何度も持って来ます。主がせよと命じられた仕事のためには、あり余るほどのことです。」'),
('JPN', '出埃及记', 2, 36, 6, 'それでモーセは命じて、宿営中に告げ知らせた。「男も女も、聖所の奉納物のためにこれ以上の仕事を行わないように。」こうして民は持って来るのをやめた。'),
('JPN', '出埃及记', 2, 36, 7, '手持ちの材料は、すべての仕事をするのに十分であり、あり余るほどであった。'),
('JPN', '出埃及记', 2, 36, 8, '仕事に携わっている者のうち、心に知恵ある者はみな、幕屋を十枚の幕で造った。幕は、撚り糸で織った亜麻布、青、紫、緋色の撚り糸を用い、意匠を凝らしてケルビムを織り出した。'),
('JPN', '出埃及记', 2, 36, 9, '幕の長さはそれぞれ二十八キュビト、幕の幅はそれぞれ四キュビト、幕はみな同じ寸法とした。'),
('JPN', '出埃及记', 2, 36, 10, '五枚の幕を互いにつなぎ合わせ、もう五枚の幕も互いにつなぎ合わせた。'),
('JPN', '出埃及记', 2, 36, 11, 'つなぎ合わせたものの端にある幕の縁に、青いひもの輪を付け、もう一つのつなぎ合わせたものの端にある幕の縁にも、そのようにした。'),
('JPN', '出埃及记', 2, 36, 12, 'その一枚の幕に五十個の輪を付け、もう一つのつなぎ合わせた幕の端にも五十個の輪を付け、その輪を互いに向かい合わせにした。'),
('JPN', '出埃及记', 2, 36, 13, '金の留め金を五十個作り、その留め金で幕を互いにつなぎ合わせ、こうして一つの幕屋にした。'),
('JPN', '出埃及记', 2, 36, 14, 'また、幕屋の上に掛ける天幕のために、やぎの毛の幕を作った。その幕を十一枚作った。'),
('JPN', '出埃及记', 2, 36, 15, '幕の長さはそれぞれ三十キュビト、幕の幅はそれぞれ四キュビト、その十一枚の幕は同じ寸法とした。'),
('JPN', '出埃及记', 2, 36, 16, 'そのうち五枚の幕を一つに、もう六枚の幕も一つにつなぎ合わせ、'),
('JPN', '出埃及记', 2, 36, 17, 'つなぎ合わせたものの端にある幕の縁には五十個の輪を付け、もう一つのつなぎ合わせた幕の縁にも五十個の輪を付けた。'),
('JPN', '出埃及记', 2, 36, 18, '青銅の留め金を五十個作り、天幕をつなぎ合わせて一つにした。'),
('JPN', '出埃及记', 2, 36, 19, '天幕のために、赤くなめした雄羊の皮で覆いを作り、さらに、その上に掛ける覆いをじゅごんの皮で作った。'),
('JPN', '出埃及记', 2, 36, 20, 'さらに幕屋のために、アカシヤ材で、まっすぐに立てる板を作った。'),
('JPN', '出埃及记', 2, 36, 21, '一枚の板は、長さ十キュビト、板一枚の幅は一キュビト半。'),
('JPN', '出埃及记', 2, 36, 22, '板一枚ごとに、はめ込みのほぞを二つ作り、幕屋のすべての板にそのようにした。'),
('JPN', '出埃及记', 2, 36, 23, 'こうして幕屋のために板を作った。南側に二十枚。'),
('JPN', '出埃及记', 2, 36, 24, 'その二十枚の板の下に銀の台座を四十個作った。一枚の板の下に、二つのほぞのために二個の台座、ほかの板の下にも、二つのほぞのために二個の台座を作った。'),
('JPN', '出埃及记', 2, 36, 25, '幕屋のもう一つの側、北側に板二十枚。'),
('JPN', '出埃及记', 2, 36, 26, '銀の台座四十個。すなわち、一枚の板の下に二個の台座。次の板の下にも二個の台座。'),
('JPN', '出埃及记', 2, 36, 27, '幕屋のうしろ、西側に板六枚を作った。'),
('JPN', '出埃及记', 2, 36, 28, '幕屋のうしろの両隅に板二枚を作った。'),
('JPN', '出埃及记', 2, 36, 29, 'これらは底部では別々であるが、上部では、一つの環のところで一つに合わさるようにした。二枚とも、そのように作った。これらが両隅である。'),
('JPN', '出埃及记', 2, 36, 30, '板は八枚、その銀の台座は十六個。すなわち、一枚の板の下に二個ずつの台座があった。'),
('JPN', '出埃及记', 2, 36, 31, 'また、アカシヤ材で横木を作った。すなわち、幕屋の一方の側の板のために五本、'),
('JPN', '出埃及记', 2, 36, 32, '幕屋のもう一方の側の板のために横木五本、幕屋のうしろ、西側の板のために横木を五本作った。'),
('JPN', '出埃及记', 2, 36, 33, 'それから、板の中間を端から端まで通る中央横木を作った。'),
('JPN', '出埃及记', 2, 36, 34, '板には金をかぶせ、横木を通す環を金で作った。横木にも金をかぶせた。'),
('JPN', '出埃及记', 2, 36, 35, 'また、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用いて、垂れ幕を作った。これに意匠を凝らしてケルビムを織り出した。'),
('JPN', '出埃及记', 2, 36, 36, 'その垂れ幕のために、金をかぶせたアカシヤ材の四本の柱を作った。それらの鉤は金であった。また、柱のために四つの銀の台座を鋳造した。'),
('JPN', '出埃及记', 2, 36, 37, '天幕の入り口のために、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用い、刺繡を施して垂れ幕を作った。'),
('JPN', '出埃及记', 2, 36, 38, 'また、五本の柱とその鉤を作り、柱頭と頭つなぎに金をかぶせた。その五つの台座は青銅であった。'),
('JPN', '出埃及记', 2, 37, 1, 'ベツァルエルは、アカシヤ材で、長さ二キュビト半、幅一キュビト半、高さ一キュビト半の箱を作り、'),
('JPN', '出埃及记', 2, 37, 2, 'その内側と外側に純金をかぶせ、その周りに金の飾り縁を作った。'),
('JPN', '出埃及记', 2, 37, 3, '箱のために金の環を四つ鋳造し、その四隅の基部に取り付けた。一方の側に二つの環を、もう一方の側にもう二つの環を取り付けた。'),
('JPN', '出埃及记', 2, 37, 4, 'また、アカシヤ材で棒を作り、それに金をかぶせ、'),
('JPN', '出埃及记', 2, 37, 5, '箱を担ぐために、その棒を箱の両側の環に通した。'),
('JPN', '出埃及记', 2, 37, 6, 'さらに、純金で「宥めの蓋」を作った。その長さは二キュビト半、幅は一キュビト半。'),
('JPN', '出埃及记', 2, 37, 7, 'また、二つの金のケルビムを作った。槌で打って、「宥めの蓋」の両端に作った。'),
('JPN', '出埃及记', 2, 37, 8, '一つを一方の端に、もう一つを他方の端に作った。「宥めの蓋」の一部として、ケルビムをその両端に作った。'),
('JPN', '出埃及记', 2, 37, 9, 'ケルビムは両翼を上の方に広げ、その翼で「宥めの蓋」をおおっていた。互いに向かい合って、ケルビムの顔が「宥めの蓋」の方を向いていた。'),
('JPN', '出埃及记', 2, 37, 10, '彼はアカシヤ材で机を作った。その長さは二キュビト、幅は一キュビト、高さは一キュビト半であった。'),
('JPN', '出埃及记', 2, 37, 11, 'これに純金をかぶせ、その周りに金の飾り縁を作った。'),
('JPN', '出埃及记', 2, 37, 12, 'その周りに一手幅の枠を作り、その枠の周りに金の飾り縁を作った。'),
('JPN', '出埃及记', 2, 37, 13, 'その机のために金の環を四つ鋳造し、四本の脚のところの四隅にその環を取り付けた。'),
('JPN', '出埃及记', 2, 37, 14, 'その環は枠の脇に付け、机を担ぐ棒を入れるところとした。'),
('JPN', '出埃及记', 2, 37, 15, 'アカシヤ材で机を担ぐための棒を作り、これに金をかぶせた。'),
('JPN', '出埃及记', 2, 37, 16, 'また、机の上の備品、すなわち、注ぎのささげ物を注ぐための皿、ひしゃく、水差し、瓶を純金で作った。'),
('JPN', '出埃及记', 2, 37, 17, 'また彼は燭台を純金で作った。その燭台は槌で打って作った。それには、台座と支柱と、がくと節と花弁があった。'),
('JPN', '出埃及记', 2, 37, 18, '六本の枝がその脇の部分から、すなわち燭台の三本の枝が一方の脇から、燭台のもう三本の枝がもう一方の脇から出ていた。'),
('JPN', '出埃及记', 2, 37, 19, '一方の枝には、アーモンドの花の形をした、節と花弁のある三つのがくが、また、もう一方の枝にも、アーモンドの花の形をした、節と花弁のある三つのがくが付いていた。燭台から出る六本の枝はみな、そのようであった。'),
('JPN', '出埃及记', 2, 37, 20, '燭台そのものには、アーモンドの花の形をした、節と花弁のある四つのがくが付いていた。'),
('JPN', '出埃及记', 2, 37, 21, 'それから出る一対の枝の下に一つの節、それから出る次の一対の枝の下に一つの節、それから出るその次の一対の枝の下に一つの節。このように六本の枝が燭台から出ていた。'),
('JPN', '出埃及记', 2, 37, 22, 'それらの節と枝は燭台と一体で、その全体は一つの純金を打って作られていた。'),
('JPN', '出埃及记', 2, 37, 23, 'また、ともしび皿を七つ作った。その芯切りばさみも芯取り皿も純金であった。'),
('JPN', '出埃及记', 2, 37, 24, '純金一タラントで、燭台とそのすべての器具を作った。'),
('JPN', '出埃及记', 2, 37, 25, '彼はアカシヤ材で香の祭壇を作った。長さ一キュビト、幅一キュビトの正方形で、高さは二キュビトであった。祭壇から角が出ているようにした。'),
('JPN', '出埃及记', 2, 37, 26, '祭壇の上面と、側面のすべて、および角には純金をかぶせ、また、その周りには金の飾り縁を作った。'),
('JPN', '出埃及记', 2, 37, 27, 'また、その祭壇のために二つの金の環を作った。その飾り縁の下の両側に、相対するように作り、そこに祭壇を担ぐ棒を通した。'),
('JPN', '出埃及记', 2, 37, 28, 'その棒をアカシヤ材で作り、それに金をかぶせた。'),
('JPN', '出埃及记', 2, 37, 29, 'ベツァルエルはまた、調香の技法を凝らして、聖なる注ぎの油と純粋な香り高い香を作った。'),
('JPN', '出埃及记', 2, 38, 1, 'また彼は、アカシヤ材で全焼のささげ物の祭壇を造った。長さ五キュビト、幅五キュビトの正方形で、高さは三キュビトであった。'),
('JPN', '出埃及记', 2, 38, 2, 'その四隅の上に角を作った。その角は祭壇から出ているようになっていた。彼は祭壇に青銅をかぶせた。'),
('JPN', '出埃及记', 2, 38, 3, '彼は、祭壇のすべての用具、すなわち、壺、十能、鉢、肉刺し、火皿を作った。そのすべての用具を青銅で作った。'),
('JPN', '出埃及记', 2, 38, 4, '祭壇のために、その下の方、すなわち、祭壇の張り出した部分の下に、祭壇の高さの半ばに達する青銅の網細工の格子を作った。'),
('JPN', '出埃及记', 2, 38, 5, '四個の環を鋳造して、青銅の格子の四隅で棒を通すところとした。'),
('JPN', '出埃及记', 2, 38, 6, '彼はアカシヤ材で棒を作り、それらに青銅をかぶせた。'),
('JPN', '出埃及记', 2, 38, 7, 'その棒を祭壇の両側にある環に通して、それを担ぐようにした。祭壇は、板で、中が空洞になるように作った。'),
('JPN', '出埃及记', 2, 38, 8, 'また、青銅で洗盤を、また青銅でその台を作った。会見の天幕の入り口で務めをした女たちの鏡で、それを作った。'),
('JPN', '出埃及记', 2, 38, 9, '彼はまた、庭を造った。南側では、庭の掛け幕は撚り糸で織った百キュビトの亜麻布でできていた。'),
('JPN', '出埃及记', 2, 38, 10, '柱は二十本、その台座は二十個で青銅、柱の鉤と頭つなぎは銀であった。'),
('JPN', '出埃及记', 2, 38, 11, '北側も百キュビトで、柱は二十本、台座は二十個で青銅、その柱の鉤と頭つなぎは銀であった。'),
('JPN', '出埃及记', 2, 38, 12, '西側には五十キュビトの掛け幕があり、柱は十本、その台座は十個、その柱の鉤と頭つなぎは銀であった。'),
('JPN', '出埃及记', 2, 38, 13, '正面の東側も五十キュビト。'),
('JPN', '出埃及记', 2, 38, 14, '門の片側には、十五キュビトの掛け幕と、柱が三本、台座が三個あった。'),
('JPN', '出埃及记', 2, 38, 15, '庭の門の両側をなすもう一方の側にも十五キュビトの掛け幕があり、柱は三本、台座は三個であった。'),
('JPN', '出埃及记', 2, 38, 16, '庭の周囲の掛け幕はみな、撚り糸で織った亜麻布でできていた。'),
('JPN', '出埃及记', 2, 38, 17, '柱のための台座は青銅で、柱の鉤と頭つなぎは銀、柱頭のかぶせ物も銀であった。それで庭の柱はみな、銀の頭つなぎでつなぎ合わされていた。'),
('JPN', '出埃及记', 2, 38, 18, '庭の門の垂れ幕は、刺繡を施したもので、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布でできていた。長さは二十キュビト、高さ、あるいは幅は五キュビトで、庭の掛け幕に対応していた。'),
('JPN', '出埃及记', 2, 38, 19, 'その柱は四本、その台座は四個で青銅であった。その鉤は銀であり、柱頭のかぶせ物と頭つなぎは銀であった。'),
('JPN', '出埃及记', 2, 38, 20, 'ただし、幕屋とその周りの庭の杭は、みな青銅であった。'),
('JPN', '出埃及记', 2, 38, 21, '幕屋、すなわち、あかしの幕屋の記録は次のとおりである。これはモーセの命によって記録されたもので、祭司アロンの子イタマルのもとでレビ人が奉仕したことであった。'),
('JPN', '出埃及记', 2, 38, 22, 'ユダ部族に属する、フルの子ウリの子ベツァルエルは、主がモーセに命じられたことをことごとく行った。'),
('JPN', '出埃及记', 2, 38, 23, '彼とともに、ダン部族の、アヒサマクの子オホリアブがいた。オホリアブは、彫刻をする者、意匠を凝らす者、また青、紫、緋色の撚り糸と亜麻布で刺繡をする者であった。'),
('JPN', '出埃及记', 2, 38, 24, '聖所の設営のすべてにおいて、その仕事のために用いられた金、すなわち奉献物の金の総計は、聖所のシェケルで二十九タラント七百三十シェケルであった。'),
('JPN', '出埃及记', 2, 38, 25, '登録された会衆による銀は、聖所のシェケルで百タラント千七百七十五シェケルであった。'),
('JPN', '出埃及记', 2, 38, 26, '二十歳以上で登録された者が全部で六十万三千五百五十人だったので、これは一人当たり一ベカ、聖所のシェケルで半シェケルである。'),
('JPN', '出埃及记', 2, 38, 27, '聖所の台座と垂れ幕の台座を鋳造するのに用いた銀は百タラントで、百個の台座に百タラント用いた。一タラントで一個の台座である。'),
('JPN', '出埃及记', 2, 38, 28, 'また、千七百七十五シェケルで柱の鉤を作り、柱の頭にかぶせ、頭つなぎで柱をつないだ。'),
('JPN', '出埃及记', 2, 38, 29, '奉献物の青銅は七十タラント二千四百シェケルであった。'),
('JPN', '出埃及记', 2, 38, 30, 'これを用いて、彼は会見の天幕の入り口の台座、青銅の祭壇と、それに付属する青銅の格子、および祭壇のすべての用具、'),
('JPN', '出埃及记', 2, 38, 31, 'また、庭の周りの台座、庭の門の台座、幕屋のすべての杭、庭の周りのすべての杭を作った。'),
('JPN', '出埃及记', 2, 39, 1, '彼らは、青、紫、緋色の撚り糸で、聖所で務めを行うための式服を作った。また、主がモーセに命じられたとおりに、アロンの聖なる装束を作った。'),
('JPN', '出埃及记', 2, 39, 2, '金色、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用いて、エポデを作った。'),
('JPN', '出埃及记', 2, 39, 3, '彼らは金の板を打ち延ばして金箔を作り、これを切って糸とし、青、紫、緋色の撚り糸に撚り込み、それぞれ亜麻布の中に意匠を凝らして織り込んだ。'),
('JPN', '出埃及记', 2, 39, 4, 'エポデに付ける肩当てが作られ、それぞれがエポデの両端に結ばれた。'),
('JPN', '出埃及记', 2, 39, 5, 'エポデの上に来るあや織りの帯はエポデと同じ作りで、金色、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用い、エポデの一部となるようにした。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 39, 6, '彼らは縞めのうを金縁の細工の中にはめ込んだ。それには、イスラエルの息子たちの名が、印章を彫るように刻まれていた。'),
('JPN', '出埃及记', 2, 39, 7, '彼らはそれらをエポデの肩当てに付け、イスラエルの息子たちが覚えられるための石とした。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 39, 8, 'また、意匠を凝らして、エポデの細工と同じように、金色、青、紫、緋色の撚り糸、それに撚り糸で織った亜麻布を用いて、胸当てを作った。'),
('JPN', '出埃及记', 2, 39, 9, '正方形で二重にしてその胸当てを作った。長さは一ゼレト、幅一ゼレトで、二重であった。'),
('JPN', '出埃及记', 2, 39, 10, 'その中に四列の宝石をはめ込んだ。第一列は赤めのう、トパーズ、エメラルド。'),
('JPN', '出埃及记', 2, 39, 11, '第二列はトルコ石、サファイア、ダイヤモンド。'),
('JPN', '出埃及记', 2, 39, 12, '第三列はヒヤシンス石、めのう、紫水晶。'),
('JPN', '出埃及记', 2, 39, 13, '第四列は緑柱石、縞めのう、碧玉。これらが金縁の細工の中にはめ込まれた。'),
('JPN', '出埃及记', 2, 39, 14, 'これらの宝石はイスラエルの息子たちの名にちなむもので、彼らの名にしたがい十二個であった。それらは印章のように、それぞれに名が彫られ、十二部族を表した。'),
('JPN', '出埃及记', 2, 39, 15, 'また、胸当てのために、撚ったひものような鎖を純金で作った。'),
('JPN', '出埃及记', 2, 39, 16, '彼らは金縁の細工二個と金の環二個を作り、二個の環を胸当ての両端に付けた。'),
('JPN', '出埃及记', 2, 39, 17, '胸当ての両端の二個の環には、二本の金のひもを付けた。'),
('JPN', '出埃及记', 2, 39, 18, 'その二本のひものもう一方の端を、先の二つの金縁の細工と結び、エポデの肩当ての前側に付けた。'),
('JPN', '出埃及记', 2, 39, 19, 'さらに二個の金の環を作り、それらを胸当ての両端に、エポデに接する胸当ての内側の縁に付けた。'),
('JPN', '出埃及记', 2, 39, 20, 'また、さらに二個の金の環を作り、これをエポデの二つの肩当ての下端の前に、エポデのあや織りの帯の上部の継ぎ目に、向かい合うように付けた。'),
('JPN', '出埃及记', 2, 39, 21, '胸当ては、その環からエポデの環に青ひもで結び付け、エポデのあや織りの帯の上にあるようにし、胸当てがエポデから外れないようにした。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 39, 22, 'また、エポデの下に着る青服を、織物の技法を凝らして青色の撚り糸だけで作った。'),
('JPN', '出埃及记', 2, 39, 23, '青服の首の穴はその真ん中にあり、よろいの襟のようで、ほころびないようにその周りに縁を付けた。'),
('JPN', '出埃及记', 2, 39, 24, '青服の裾の上に、青、紫、緋色の撚り糸で撚ったざくろを作った。'),
('JPN', '出埃及记', 2, 39, 25, 'また彼らは純金の鈴を作り、その鈴を青服の裾周りの、ざくろとざくろとの間に付けた。'),
('JPN', '出埃及记', 2, 39, 26, 'すなわち、務めを行うための青服の裾周りには、鈴、ざくろ、鈴、ざくろとなるようにした。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 39, 27, '彼らはアロンとその子らのために、織物の技法を凝らして、亜麻布の長服を、'),
('JPN', '出埃及记', 2, 39, 28, '亜麻布のかぶり物、亜麻布の麗しいターバン、そして撚り糸で織った亜麻布のももひきを作った。'),
('JPN', '出埃及记', 2, 39, 29, 'また、撚り糸で織った亜麻布と、青、紫、緋色の撚り糸を用い、刺繡を施して飾り帯を作った。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 39, 30, 'また、聖別の記章の札を純金で作り、その上に印章を彫るように「主の聖なるもの」という文字を記した。'),
('JPN', '出埃及记', 2, 39, 31, 'これに青ひもを付け、それを、かぶり物に上の方から結び付けた。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 39, 32, 'こうして、会見の天幕である幕屋のすべての奉仕が終わった。イスラエルの子らは、すべて主がモーセに命じられたとおりに行い、そのようにした。'),
('JPN', '出埃及记', 2, 39, 33, '彼らは幕屋をモーセのところに運んで来た。天幕とそのすべての備品、留め金、板、横木、柱、台座、'),
('JPN', '出埃及记', 2, 39, 34, '赤くなめした雄羊の皮の覆い、じゅごんの皮の覆い、仕切りの垂れ幕、'),
('JPN', '出埃及记', 2, 39, 35, 'あかしの箱と、その棒、「宥めの蓋」、'),
('JPN', '出埃及记', 2, 39, 36, '机と、そのすべての備品、臨在のパン、'),
('JPN', '出埃及记', 2, 39, 37, 'きよい燭台と、そのともしび皿、すなわち一列に並べるともしび皿、そのすべての道具、ともしび用の油、'),
('JPN', '出埃及记', 2, 39, 38, '金の祭壇、注ぎの油、香り高い香、そして天幕の入り口の垂れ幕、'),
('JPN', '出埃及记', 2, 39, 39, '青銅の祭壇と、それに付属する青銅の格子、その棒、そのすべての用具、洗盤とその台、'),
('JPN', '出埃及记', 2, 39, 40, '庭の掛け幕と、その柱、その台座、庭の門のための垂れ幕と、そのひも、その杭、会見の天幕の幕屋の奉仕に用いるすべての用具、'),
('JPN', '出埃及记', 2, 39, 41, '聖所で務めを行うための式服、すなわち、祭司アロンの聖なる装束と、祭司として仕える彼の子らの装束である。'),
('JPN', '出埃及记', 2, 39, 42, 'イスラエルの子らは、すべて主がモーセに命じられたとおりに、そのとおりに、すべての奉仕を行った。'),
('JPN', '出埃及记', 2, 39, 43, 'モーセがすべての仕事を見ると、彼らは、見よ、主が命じられたとおりに行っていた。そこでモーセは彼らを祝福した。'),
('JPN', '出埃及记', 2, 40, 1, '主はモーセに告げられた。'),
('JPN', '出埃及记', 2, 40, 2, '「第一の月の一日に、あなたは会見の天幕である幕屋を設営しなければならない。'),
('JPN', '出埃及记', 2, 40, 3, 'あなたはその中にあかしの箱を置き、垂れ幕で箱の前をさえぎる。'),
('JPN', '出埃及记', 2, 40, 4, '机を運び入れて備品を並べ、燭台を運び入れて、そのともしび皿を載せる。'),
('JPN', '出埃及记', 2, 40, 5, '香のための金の祭壇をあかしの箱の前に置き、垂れ幕を幕屋の入り口に掛ける。'),
('JPN', '出埃及记', 2, 40, 6, '会見の天幕である幕屋の入り口の前には、全焼のささげ物の祭壇を据え、'),
('JPN', '出埃及记', 2, 40, 7, '会見の天幕と祭壇との間に洗盤を据えて、これに水を入れる。'),
('JPN', '出埃及记', 2, 40, 8, '周りに庭を設け、庭の門に垂れ幕を掛ける。'),
('JPN', '出埃及记', 2, 40, 9, 'あなたは注ぎの油を取って、幕屋とその中にあるすべてのものの油注ぎを行い、それと、そのすべての用具を聖別する。それは聖なるものとなる。'),
('JPN', '出埃及记', 2, 40, 10, '全焼のささげ物の祭壇とそのすべての用具の油注ぎを行い、その祭壇を聖別する。祭壇は最も聖なるものとなる。'),
('JPN', '出埃及记', 2, 40, 11, '洗盤とその台の油注ぎを行い、これを聖別する。'),
('JPN', '出埃及记', 2, 40, 12, 'また、あなたはアロンとその子らを会見の天幕の入り口に近づかせ、水で洗い、'),
('JPN', '出埃及记', 2, 40, 13, 'アロンに聖なる装束を着せ、油注ぎを行って彼を聖別し、祭司としてわたしに仕えさせる。'),
('JPN', '出埃及记', 2, 40, 14, 'また彼の子らを近づかせ、これに長服を着せる。'),
('JPN', '出埃及记', 2, 40, 15, '彼らの父に油注ぎをしたように、彼らにも油注ぎをし、祭司としてわたしに仕えさせる。彼らが油注がれることは、彼らの代々にわたる永遠の祭司職のためである。」'),
('JPN', '出埃及记', 2, 40, 16, 'モーセは、すべて主が彼に命じられたとおりに行い、そのようにした。'),
('JPN', '出埃及记', 2, 40, 17, '第二年の第一の月、その月の一日に幕屋は設営された。'),
('JPN', '出埃及记', 2, 40, 18, 'モーセは幕屋を設営した。まず、その台座を据え、その板を立て、その横木を通し、その柱を立て、'),
('JPN', '出埃及记', 2, 40, 19, '幕屋の上に天幕を広げ、その上に天幕の覆いを掛けた。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 40, 20, 'また、さとしの板を取って箱に納め、棒を箱に付け、「宥めの蓋」を箱の上に置き、'),
('JPN', '出埃及记', 2, 40, 21, '箱を幕屋の中に入れ、仕切りの垂れ幕を掛け、あかしの箱の前をさえぎった。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 40, 22, 'また、会見の天幕の中に、すなわち、幕屋の内部の北側、垂れ幕の外側に机を置いた。'),
('JPN', '出埃及记', 2, 40, 23, 'その上にパンを一列にして、主の前に並べた。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 40, 24, '会見の天幕の中、机の反対側、幕屋の内部の南側に燭台を置き、'),
('JPN', '出埃及记', 2, 40, 25, '主の前にともしび皿を掲げた。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 40, 26, 'それから、会見の天幕の中の垂れ幕の前に、金の祭壇を置き、'),
('JPN', '出埃及记', 2, 40, 27, 'その上で香り高い香をたいた。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 40, 28, 'また、幕屋の入り口に垂れ幕を掛け、'),
('JPN', '出埃及记', 2, 40, 29, '会見の天幕である幕屋の入り口に全焼のささげ物の祭壇を置き、その上に全焼のささげ物と穀物のささげ物を献げた。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 40, 30, 'また、会見の天幕と祭壇との間に洗盤を置き、洗いのために、それに水を入れた。'),
('JPN', '出埃及记', 2, 40, 31, 'モーセとアロンとその子らは、それで手と足を洗った。'),
('JPN', '出埃及记', 2, 40, 32, '会見の天幕に入るとき、また祭壇に近づくとき、彼らはいつも洗った。主がモーセに命じられたとおりである。'),
('JPN', '出埃及记', 2, 40, 33, 'また、幕屋と祭壇の周りに庭を設け、庭の門に垂れ幕を掛けた。こうしてモーセはその仕事を終えた。'),
('JPN', '出埃及记', 2, 40, 34, 'そのとき、雲が会見の天幕をおおい、主の栄光が幕屋に満ちた。'),
('JPN', '出埃及记', 2, 40, 35, 'モーセは会見の天幕に入ることができなかった。雲がその上にとどまり、主の栄光が幕屋に満ちていたからである。'),
('JPN', '出埃及记', 2, 40, 36, 'イスラエルの子らは、旅路にある間、いつも雲が幕屋から上ったときに旅立った。'),
('JPN', '出埃及记', 2, 40, 37, '雲が上らないと、上る日まで旅立たなかった。'),
('JPN', '出埃及记', 2, 40, 38, '旅路にある間、イスラエルの全家の前には、昼は主の雲が幕屋の上に、夜は雲の中に火があった。'),
('JPN', '利未记', 3, 1, 1, '主はモーセを呼び、会見の天幕から彼にこう告げられた。'),
('JPN', '利未记', 3, 1, 2, '「イスラエルの子らに告げよ。あなたがたの中でだれかが主にささげ物を献げるときは、家畜の中から、牛か羊をそのささげ物として献げなければならない。'),
('JPN', '利未记', 3, 1, 3, 'そのささげ物が牛の全焼のささげ物である場合には、傷のない雄を献げなければならない。その人は自分が主の前に受け入れられるように、それを会見の天幕の入り口に連れて行き、'),
('JPN', '利未记', 3, 1, 4, 'その全焼のささげ物の頭に手を置く。それがその人のための宥めとなり、彼は受け入れられる。'),
('JPN', '利未记', 3, 1, 5, 'その若い牛は主の前で屠り、祭司であるアロンの子らがその血を携えて行って、会見の天幕の入り口にある祭壇の側面にその血を振りかける。'),
('JPN', '利未记', 3, 1, 6, 'また、全焼のささげ物はその皮を剝ぎ、各部に切り分ける。'),
('JPN', '利未记', 3, 1, 7, '祭司であるアロンの子らは祭壇の上に火を置き、その火の上に薪を整える。'),
('JPN', '利未记', 3, 1, 8, '祭司であるアロンの子らは、その切り分けた各部と、頭と脂肪を祭壇の火の上の薪の上に整える。'),
('JPN', '利未记', 3, 1, 9, '内臓と足は水で洗う。祭司はこれらすべてを祭壇の上で焼いて煙にする。これは全焼のささげ物、主への食物のささげ物、芳ばしい香りである。'),
('JPN', '利未记', 3, 1, 10, 'そのささげ物が、羊の群れ、すなわち羊またはやぎの中からの全焼のささげ物である場合には、傷のない雄を献げなければならない。'),
('JPN', '利未记', 3, 1, 11, 'それを祭壇の北側で、主の前で屠り、祭司であるアロンの子らが、その血を祭壇の側面に振りかける。'),
('JPN', '利未记', 3, 1, 12, 'また、そのささげ物は各部に切り分ける。祭司はこれを頭と脂肪とともに祭壇の火の上の薪の上に整える。'),
('JPN', '利未记', 3, 1, 13, '内臓と足は水で洗う。祭司はこれらすべてを献げ、祭壇の上で焼いて煙にする。これは全焼のささげ物であり、主への食物のささげ物、芳ばしい香りである。'),
('JPN', '利未记', 3, 1, 14, '主へのささげ物が鳥の全焼のささげ物である場合には、山鳩、または家鳩のひなの中から、自分のささげ物を献げなければならない。'),
('JPN', '利未记', 3, 1, 15, '祭司はそれを祭壇に持って来て、その頭をひねり、祭壇の上で焼いて煙にする。その血は祭壇の側面に絞り出す。'),
('JPN', '利未记', 3, 1, 16, '餌袋はその中身とともに取り除き、祭壇の東側の灰置き場に投げ捨てる。'),
('JPN', '利未记', 3, 1, 17, 'その翼は引き裂くが、切り離してはならない。祭司はそれを祭壇の上、火の上の薪の上で焼いて煙にする。これは全焼のささげ物であり、主への食物のささげ物、芳ばしい香りである。'),
('JPN', '利未记', 3, 2, 1, '人が主に穀物のささげ物を献げるとき、そのささげ物は小麦粉でなければならない。その上に油を注ぎ、その上に乳香を添え、'),
('JPN', '利未记', 3, 2, 2, 'それを祭司であるアロンの子らのところに持って行く。祭司はその中から、ひとつかみの小麦粉と油と乳香すべてを覚えの分として取り出し、祭壇の上で焼いて煙にする。これは主への食物のささげ物、芳ばしい香りである。'),
('JPN', '利未记', 3, 2, 3, 'その穀物のささげ物の残りはアロンとその子らのものとなる。それは主への食物のささげ物のうちの、最も聖なるものである。'),
('JPN', '利未记', 3, 2, 4, 'あなたがかまどで焼いた穀物のささげ物を献げる場合には、油を混ぜた小麦粉の、種なしの輪形パン、あるいは油を塗った、種なしの薄焼きパンとする。'),
('JPN', '利未记', 3, 2, 5, 'また、あなたのささげ物が、平鍋の上で焼いた穀物のささげ物である場合には、油を混ぜた小麦粉の、種なしのものでなければならない。'),
('JPN', '利未记', 3, 2, 6, 'あなたはそれを粉々に砕いて、その上に油を注ぎなさい。これは穀物のささげ物である。'),
('JPN', '利未记', 3, 2, 7, 'また、鍋で作る穀物のささげ物は、油を混ぜた小麦粉で作る。'),
('JPN', '利未记', 3, 2, 8, 'あなたは、これらの物で作られた穀物のささげ物を主のもとに携えて行く。それをあなたが祭司のところに持って行き、祭司はそれを祭壇に献げる。'),
('JPN', '利未记', 3, 2, 9, '祭司は、その穀物のささげ物から一部を覚えの分として取り出し、祭壇の上で焼いて煙にする。これは主への食物のささげ物、芳ばしい香りである。'),
('JPN', '利未记', 3, 2, 10, '穀物のささげ物の残りはアロンとその子らのものとなる。これは主への食物のささげ物のうちの、最も聖なるものである。'),
('JPN', '利未记', 3, 2, 11, 'あなたがたが主に献げる穀物のささげ物はみな、パン種を入れて作ってはならない。パン種や蜜は、少しであっても、主への食物のささげ物として焼いて煙にしてはならない。'),
('JPN', '利未记', 3, 2, 12, 'それらは初物のささげ物として主に献げることができる。しかしそれらを、芳ばしい香りとして祭壇に献げてはならない。'),
('JPN', '利未记', 3, 2, 13, '穀物のささげ物はみな、塩で味をつけなさい。穀物のささげ物に、あなたの神の契約の塩を欠かしてはならない。あなたのどのささげ物も、塩をかけて献げなければならない。'),
('JPN', '利未记', 3, 2, 14, 'あなたが初穂による穀物のささげ物を主に献げる場合には、火にあぶった穀粒、新穀のひき割り麦を、あなたの初穂による穀物のささげ物として献げなさい。'),
('JPN', '利未记', 3, 2, 15, 'あなたはその上に油を加え、その上に乳香を添える。これは穀物のささげ物である。'),
('JPN', '利未记', 3, 2, 16, '祭司は、そのひき割り麦の一部とその油の一部、それにその乳香すべてを覚えの分として焼いて煙にする。これは主への食物のささげ物である。'),
('JPN', '利未记', 3, 3, 1, 'そのささげ物が交わりのいけにえの場合には、献げようとするのが牛であるなら、雄でも雌でも傷のないものを主の前に献げなければならない。'),
('JPN', '利未记', 3, 3, 2, 'まず、ささげ物の頭に手を置き、それを会見の天幕の入り口で屠り、祭司であるアロンの子らがその血を祭壇の側面に振りかける。'),
('JPN', '利未记', 3, 3, 3, '次に交わりのいけにえから、主への食物のささげ物として、内臓をおおう脂肪と、内臓に付いている脂肪すべて、'),
('JPN', '利未记', 3, 3, 4, 'また、二つの腎臓と、それに付いている腰のあたりの脂肪、さらに腎臓とともに取り除いた、肝臓の上の小葉を献げる。'),
('JPN', '利未记', 3, 3, 5, 'アロンの子らは、これを祭壇の上で、火の上の薪の上にある全焼のささげ物に載せて、焼いて煙にする。これは主への食物のささげ物、芳ばしい香りである。'),
('JPN', '利未记', 3, 3, 6, '交わりのいけにえとしての、主へのささげ物が羊であるなら、雄でも雌でも傷のないものを献げなければならない。'),
('JPN', '利未记', 3, 3, 7, 'ささげ物として献げようとするのが子羊であるなら、それを主の前に連れて来る。'),
('JPN', '利未记', 3, 3, 8, 'そして、そのささげ物の頭に手を置き、それを会見の天幕の前で屠る。アロンの子らは、その血を祭壇の側面に振りかける。'),
('JPN', '利未记', 3, 3, 9, 'そして、その交わりのいけにえから、主への食物のささげ物としてその脂肪を献げる。すなわち、背骨に沿って取り除いたあぶら尾すべて、内臓をおおう脂肪、内臓に付いている脂肪すべて、'),
('JPN', '利未记', 3, 3, 10, 'また、二つの腎臓と、それに付いている腰のあたりの脂肪、さらに腎臓とともに取り除いた、肝臓の上の小葉である。'),
('JPN', '利未记', 3, 3, 11, '祭司は祭壇の上で、それを食物として、主への食物のささげ物として焼いて煙にする。'),
('JPN', '利未记', 3, 3, 12, 'そのささげ物がやぎであるなら、それを主の前に連れて行く。'),
('JPN', '利未记', 3, 3, 13, 'そして、ささげ物の頭に手を置き、それを会見の天幕の前で屠る。アロンの子らは、その血を祭壇の側面に振りかける。'),
('JPN', '利未记', 3, 3, 14, 'そして主への食物のささげ物として、そのいけにえから、内臓をおおう脂肪と、内臓に付いている脂肪すべて、'),
('JPN', '利未记', 3, 3, 15, 'また、二つの腎臓と、それに付いている腰のあたりの脂肪、さらに腎臓とともに取り除いた、肝臓の上の小葉を献げる。'),
('JPN', '利未记', 3, 3, 16, '祭司は祭壇の上で、それを食物として、芳ばしい香りのための食物のささげ物として焼いて煙にする。脂肪はすべて主のものである。'),
('JPN', '利未记', 3, 3, 17, 'あなたがたがどこに住んでいても代々守るべき、永遠の掟はこれである。あなたがたは、いかなる脂肪も血も食べてはならない。」'),
('JPN', '利未记', 3, 4, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 4, 2, '「イスラエルの子らに告げよ。人が、主がしてはならないと命じたすべてのことから離れて、気づかずに罪に陥り、その一つでも行ってしまった、以下のような場合には──'),
('JPN', '利未记', 3, 4, 3, '油注がれた祭司が罪に陥って、民が責めを覚える場合には、その祭司は自分が陥った罪のために、傷のない若い雄牛を罪のきよめのささげ物として主に献げる。'),
('JPN', '利未记', 3, 4, 4, '彼はその雄牛を会見の天幕の入り口、主の前に連れて行き、雄牛の頭に手を置き、主の前でその雄牛を屠る。'),
('JPN', '利未记', 3, 4, 5, 'その油注がれた祭司はその雄牛の血を取り、それを会見の天幕に持って入る。'),
('JPN', '利未记', 3, 4, 6, 'その祭司は指を血に浸し、主の前で、聖所の垂れ幕に向けてその血を七度振りまく。'),
('JPN', '利未记', 3, 4, 7, '祭司はその血を、会見の天幕の中にある、主の前にある香り高い香の祭壇の四隅の角に塗り、その雄牛の血をすべて、会見の天幕の入り口にある全焼のささげ物の祭壇の土台に流す。'),
('JPN', '利未记', 3, 4, 8, 'そして、罪のきよめのささげ物であるその雄牛の脂肪をすべて取り除く。すなわち、内臓をおおう脂肪と、内臓に付いている脂肪すべて、'),
('JPN', '利未记', 3, 4, 9, 'また、二つの腎臓と、それに付いている腰のあたりの脂肪、さらに腎臓とともに取り除いた、肝臓の上の小葉を取り除く。'),
('JPN', '利未记', 3, 4, 10, 'これは交わりのいけにえの牛から取り除く場合と同様である。祭司はそれらを全焼のささげ物の祭壇の上で焼いて煙にする。'),
('JPN', '利未记', 3, 4, 11, 'その雄牛の皮とそのすべての肉、頭と足の部分、さらに内臓と汚物、'),
('JPN', '利未记', 3, 4, 12, 'すなわちその雄牛の残りすべてを、宿営の外のきよい所、すなわち灰捨て場に運び出し、薪の火で焼く。これは灰捨て場で焼かれる。'),
('JPN', '利未记', 3, 4, 13, 'イスラエルの会衆すべてが迷い出て、すなわち、あることがその集会の目から隠れていて、主がしてはならないと命じたすべてのことのうち一つでも行い、後になって責めを覚える場合には、'),
('JPN', '利未记', 3, 4, 14, '自らの罪が明らかになったときに、その集会の人々は罪のきよめのささげ物として若い雄牛を献げ、それを会見の天幕の前に連れて行く。'),
('JPN', '利未记', 3, 4, 15, '会衆の長老たちは主の前でその雄牛の頭に手を置き、主の前でその雄牛を屠る。'),
('JPN', '利未记', 3, 4, 16, '油注がれた祭司は、その雄牛の血を会見の天幕に持って入る。'),
('JPN', '利未记', 3, 4, 17, '祭司は指を血に浸し、主の前で、垂れ幕に向けてその血を七度振りまく。'),
('JPN', '利未记', 3, 4, 18, 'そして、その血を会見の天幕の中にある主の前の祭壇の四隅の角に塗る。また、その血はすべて、会見の天幕の入り口にある全焼のささげ物の祭壇の土台に流す。'),
('JPN', '利未记', 3, 4, 19, '脂肪はすべてその雄牛から取り、祭壇の上で焼いて煙にする。'),
('JPN', '利未记', 3, 4, 20, '罪のきよめのささげ物の雄牛に対してしたように、この雄牛に対して行う。こうして祭司は彼らのために宥めを行う。そして彼らは赦される。'),
('JPN', '利未记', 3, 4, 21, 'その雄牛は宿営の外に運び出し、先の雄牛を焼いた場合と同様に、それを焼く。これは集会のための罪のきよめのささげ物である。'),
('JPN', '利未记', 3, 4, 22, '族長が罪に陥って、その神、主がしてはならないと命じたすべてのうちの一つでも、気づかずに行ったが、後になって責めを覚える場合、'),
('JPN', '利未记', 3, 4, 23, 'または、自分が陥っている罪が知らされた場合には、ささげ物として傷のない雄やぎを連れて来る。'),
('JPN', '利未记', 3, 4, 24, 'そして、そのやぎの頭に手を置き、全焼のささげ物を屠る場所で、主の前でそれを屠る。これは罪のきよめのささげ物である。'),
('JPN', '利未记', 3, 4, 25, '祭司は罪のきよめのささげ物の血を指に付け、それを全焼のささげ物の祭壇の四隅の角に塗る。残りの血は全焼のささげ物の祭壇の土台に流す。'),
('JPN', '利未记', 3, 4, 26, 'また、交わりのいけにえの脂肪の場合と同様に、その脂肪はすべて祭壇の上で焼いて煙にする。こうして祭司は彼のために、罪を除いて宥めを行う。そして彼は赦される。'),
('JPN', '利未记', 3, 4, 27, '民衆の一人が、主がしてはならないと命じたことの一つでも行って、気づかずに罪に陥ってしまったが、後になって責めを覚える場合、'),
('JPN', '利未记', 3, 4, 28, 'または、自分が陥っていた罪が知らされた場合には、その人が陥っていた罪のために、ささげ物として傷のない雌やぎを連れて来る。'),
('JPN', '利未记', 3, 4, 29, 'そして、その罪のきよめのささげ物の頭に手を置き、全焼のささげ物の場所で罪のきよめのささげ物を屠る。'),
('JPN', '利未记', 3, 4, 30, '祭司はその血を指に付け、それを全焼のささげ物の祭壇の四隅の角に塗る。その血はすべて祭壇の土台に流す。'),
('JPN', '利未记', 3, 4, 31, '交わりのいけにえから取り除かれる場合と同様に、その脂肪はすべて取り除く。祭司は主への芳ばしい香りとして、それを祭壇の上で焼いて煙にする。こうして祭司はその人のために宥めを行う。そして彼は赦される。'),
('JPN', '利未记', 3, 4, 32, '罪のきよめのささげ物のために、ささげ物として子羊を連れて来る場合には、傷のない雌羊を連れて来る。'),
('JPN', '利未记', 3, 4, 33, 'その罪のきよめのささげ物の頭の上に手を置き、全焼のささげ物を屠る場所で、罪のきよめのささげ物としてそれを屠る。'),
('JPN', '利未记', 3, 4, 34, '祭司は罪のきよめのささげ物の血を指に付け、それを全焼のささげ物の祭壇の四隅の角に塗る。その血はすべて祭壇の土台に流す。'),
('JPN', '利未记', 3, 4, 35, 'また、交わりのいけにえの子羊の脂肪が取り除かれる場合と同様に、その脂肪はすべて取り除く。祭司はそれを祭壇の上で、主への食物のささげ物の上に載せて、焼いて煙にする。こうして祭司は彼のために、陥っていた罪を除いて宥めを行う。そして彼は赦される。'),
('JPN', '利未记', 3, 5, 1, '人が罪に陥ったとき、すなわち、その人自身が見ていたり知っていたりする証人であるのに、証言しなければのろわれるという声を聞きながらも、それをしない場合、その人は咎を負わなければならない。'),
('JPN', '利未记', 3, 5, 2, 'あるいは、汚れた生き物の死骸であれ、汚れた家畜の死骸であれ、汚れた群がるものの死骸であれ、何か汚れたものに触れて汚れていたのに、そのことが彼には隠れていて、後になって責めを覚える場合、'),
('JPN', '利未记', 3, 5, 3, 'または、いかなるものであれ、触れれば汚れると言われる人間の汚れに触れ、そのことを知ってはいたものの彼には隠れていて、後になって責めを覚える場合、'),
('JPN', '利未记', 3, 5, 4, 'また、害になることであれ益になることであれ、誓ったことが何であれ、人が軽々しく口で誓った場合、そのことを知ってはいたものの彼には隠れていて、後になってその一つについて責めを覚える場合──'),
('JPN', '利未记', 3, 5, 5, 'これらの一つについて責めを覚える場合には、自分が陥っていた罪を告白し、'),
('JPN', '利未记', 3, 5, 6, '自分が陥っていた罪のために償いとして、羊の群れの子羊であれ、やぎであれ、雌一匹を主のもとに連れて行き、罪のきよめのささげ物とする。祭司は彼のために、罪を除いて宥めを行う。'),
('JPN', '利未记', 3, 5, 7, 'しかし、もしその人に羊を買う余裕がなければ、自分が陥っていた罪の償いとして、山鳩二羽あるいは家鳩のひな二羽を主のところに持って行く。一羽は罪のきよめのささげ物、もう一羽は全焼のささげ物とする。'),
('JPN', '利未记', 3, 5, 8, '彼はこれらを祭司のところに持って行き、祭司はまず、罪のきよめのささげ物となるものを献げる。彼はその頭の首のところをひねる。しかし、それを切り離してはならない。'),
('JPN', '利未记', 3, 5, 9, 'それから罪のきよめのささげ物の血を祭壇の側面にかけ、血の残りはその祭壇の土台のところに絞り出す。これは罪のきよめのささげ物である。'),
('JPN', '利未记', 3, 5, 10, '祭司はもう一羽のほうも、定めにしたがって全焼のささげ物とする。こうして祭司はその人のために、陥っていた罪を除いて宥めを行う。そして彼は赦される。'),
('JPN', '利未记', 3, 5, 11, 'もしその人が、山鳩二羽あるいは家鳩のひな二羽さえも手に入れることができないのなら、自分の罪のために、ささげ物として、十分の一エパの小麦粉を罪のきよめのささげ物として持って行く。その人はその上に油を加えたり、その上に乳香を添えたりしてはならない。これは罪のきよめのささげ物であるから。'),
('JPN', '利未记', 3, 5, 12, 'その人はそれを祭司のところに持って行く。祭司は、その中からひとつかみを覚えの分として取り、祭壇の上で、主への食物のささげ物とともに焼いて煙にする。これは罪のきよめのささげ物である。'),
('JPN', '利未记', 3, 5, 13, 'こうして、祭司は彼のために、陥っていたこれらの罪の一つのゆえに宥めを行う。そして彼は赦される。その残りは、穀物のささげ物と同様に祭司のものとなる。」'),
('JPN', '利未记', 3, 5, 14, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 5, 15, '「人が信頼を裏切ることをしたとき、すなわち、主の聖なるものに関して気づかずに罪に陥ってしまった場合、羊の群れから傷のない雄羊、それも、聖所のシェケルで数シェケルの償いの銀に相当すると評価される雄羊一匹を、代償のささげ物として主のもとに連れて行く。'),
('JPN', '利未记', 3, 5, 16, 'その人は、その聖なるものに関して罪に陥っていたことの償いをする。それにその五分の一を加えて、祭司に渡す。祭司は、その代償のささげ物の雄羊をもって彼のために宥めを行い、彼は赦される。'),
('JPN', '利未记', 3, 5, 17, 'また、もし人が罪に陥っていて、主がしてはならないと命じたすべてのうち一つでも行いながら自覚がなく、後になって責めを覚えるなら、その人はその咎を負う。'),
('JPN', '利未记', 3, 5, 18, 'その人は羊の群れから、代償として評価された、傷のない雄羊一匹を祭司のところに連れて行く。祭司は彼のために、彼が自覚せずに、また気づかずに犯した過失のゆえに宥めを行う。そして彼は赦される。'),
('JPN', '利未记', 3, 5, 19, 'これは代償のささげ物である。彼は確かに主の前に償いの責めを負っていた。」'),
('JPN', '利未记', 3, 6, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 6, 2, '「人が罪に陥っていて主の信頼を裏切るとき、すなわち、預かり物や担保の物やかすめた物について同胞を欺いたり、あるいは同胞を脅迫してゆすり取ったり、'),
('JPN', '利未记', 3, 6, 3, 'あるいは落とし物を見つけながらも欺いたりするなどして、人が罪に陥っていて行う事柄の一つについて、偽りの誓いをするようなとき、'),
('JPN', '利未记', 3, 6, 4, 'その人が罪に陥り、後になって責めを覚える場合には、そのかすめた品や脅迫してゆすり取った物、自分に託された預かり物、見つけた落とし物、'),
('JPN', '利未记', 3, 6, 5, 'あるいは、それについて偽って誓った物をすべて返さなければならない。元の物を償い、また、それに五分の一を加えなければならない。彼は自分が責めを覚えるときに、その元の所有者にそれを返さなければならない。'),
('JPN', '利未记', 3, 6, 6, 'その人は羊の群れから、傷のない、代償として評価された雄羊一匹を、主への自分のための代償のささげ物として、祭司のところに連れて行く。'),
('JPN', '利未记', 3, 6, 7, '祭司は主の前でその人のために宥めを行う。彼は、自分が行って責めを覚えるようになったどのことについても赦される。」'),
('JPN', '利未记', 3, 6, 8, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 6, 9, '「アロンとその子らに命じよ。全焼のささげ物についてのおしえは次のとおりである。全焼のささげ物そのものは、一晩中、朝まで祭壇の上の炉床にあるようにし、祭壇の火をそこで燃え続けさせる。'),
('JPN', '利未记', 3, 6, 10, '祭司は亜麻布の衣を着て、亜麻布のももひきを身に着ける。そして、祭壇の上で火が焼き尽くした全焼のささげ物の脂肪の灰を取り出し、祭壇のそばに置く。'),
('JPN', '利未记', 3, 6, 11, 'それからその装束を脱ぎ、別の装束を着け、脂肪の灰を宿営の外のきよい所に運び出す。'),
('JPN', '利未记', 3, 6, 12, '祭壇の火はそのまま燃え続けさせ、それを消してはならない。祭司は朝ごとに、その上に薪をくべ、その上に全焼のささげ物を整え、その上で交わりのいけにえの脂肪を焼いて煙にする。'),
('JPN', '利未记', 3, 6, 13, '火は絶えず祭壇の上で燃え続けさせなければならない。消してはならない。'),
('JPN', '利未记', 3, 6, 14, '穀物のささげ物についてのおしえは次のとおりである。アロンの子らは祭壇の前で、それを主の前に献げる。'),
('JPN', '利未记', 3, 6, 15, 'すなわち、その中から穀物のささげ物の小麦粉ひとつかみと油を覚えの分として取り出し、穀物のささげ物の上の乳香すべてと一緒に、主への芳ばしい香りとして祭壇の上で焼いて煙にする。'),
('JPN', '利未记', 3, 6, 16, '残りの分はアロンとその子らが食べる。それを種なしパンにして、聖なる所で食べる。それを会見の天幕の庭で食べる。'),
('JPN', '利未记', 3, 6, 17, 'それにパン種を入れて焼いてはならない。わたしは、それを食物のささげ物のうちから、彼らの取り分として与えた。それは、罪のきよめのささげ物や代償のささげ物と同じように、最も聖なるものである。'),
('JPN', '利未记', 3, 6, 18, 'アロンの子らのうち男子はみな、それを食べることができる。これは、主への食物のささげ物のうちから、あなたがたが代々受け取る永遠の割り当てである。それに触れるものはみな、聖なるものとなる。」'),
('JPN', '利未记', 3, 6, 19, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 6, 20, '「アロンが油注がれる日に、アロンとその子らが主に献げるささげ物は次のとおりである。小麦粉十分の一エパを常供の穀物のささげ物とする。半分は朝、もう半分は夕方の分である。'),
('JPN', '利未记', 3, 6, 21, 'それを油でよくこねて平鍋の上で作り、粉々にして焼いた穀物のささげ物として携えて行き、主への芳ばしい香りとして献げる。'),
('JPN', '利未记', 3, 6, 22, '彼の子らのうち、油注がれて彼の跡を継ぐ祭司がこれを行う。それは主のための永遠の割り当てであり、完全に焼いて煙にしなければならない。'),
('JPN', '利未记', 3, 6, 23, '祭司の穀物のささげ物はすべて完全に焼き尽くすべきであり、食べてはならない。」'),
('JPN', '利未记', 3, 6, 24, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 6, 25, '「アロンとその子らに告げよ。罪のきよめのささげ物についてのおしえは次のとおりである。罪のきよめのささげ物は、全焼のささげ物が屠られる場所、主の前で屠られる。これは最も聖なるものである。'),
('JPN', '利未记', 3, 6, 26, '罪のきよめのささげ物を献げる祭司はそれを食べる。それを聖なる所、会見の天幕の庭で食べる。'),
('JPN', '利未记', 3, 6, 27, 'その肉に触れるものはみな、聖なるものとなる。また、その血が少しでも衣にはねかかったときには、あなたは、そのはねかかった衣を聖なる所で洗う。'),
('JPN', '利未记', 3, 6, 28, 'ささげ物を煮た土の器は砕かなければならない。青銅の器で煮たのであれば、その器は磨き、水ですすぐ。'),
('JPN', '利未记', 3, 6, 29, '祭司の家系に属する男子はみな、これを食べることができる。これは最も聖なるものである。'),
('JPN', '利未记', 3, 6, 30, 'しかし、その血を聖所での宥めのために会見の天幕に持って行った、罪のきよめのささげ物は、食べてはならない。これは火で焼く。'),
('JPN', '利未记', 3, 7, 1, '代償のささげ物についてのおしえは次のとおりである。このささげ物は最も聖なるものである。'),
('JPN', '利未记', 3, 7, 2, '代償のささげ物は、全焼のささげ物を屠る場所で屠る。そして、その血を祭壇の側面に振りかける。'),
('JPN', '利未记', 3, 7, 3, 'その脂肪はすべて献げる。すなわち、あぶら尾と内臓をおおう脂肪、'),
('JPN', '利未记', 3, 7, 4, '二つの腎臓と、それに付いている腰のあたりの脂肪、さらに腎臓とともに取り除いた、肝臓の上の小葉である。'),
('JPN', '利未记', 3, 7, 5, '祭司はそれらを祭壇の上で、主への食物のささげ物として、焼いて煙にしなければならない。これは代償のささげ物である。'),
('JPN', '利未记', 3, 7, 6, '祭司の家系に属する男子はみな、これを食べることができる。それは聖なる所で食べなければならない。これは最も聖なるものである。'),
('JPN', '利未记', 3, 7, 7, '罪のきよめのささげ物と代償のささげ物についてのおしえは一つである。代償のささげ物は、それを用いて宥めを行う祭司のものとなる。'),
('JPN', '利未记', 3, 7, 8, '祭司が、ある人の全焼のささげ物を献げる場合、献げた全焼のささげ物の皮はその祭司のものとなる。'),
('JPN', '利未记', 3, 7, 9, 'さらに、かまどで焼いた穀物のささげ物はすべて、また鍋や平鍋で作られたものはすべて、それを献げる祭司のものとなる。'),
('JPN', '利未记', 3, 7, 10, 'しかし、油を混ぜたものや、乾いたままの穀物のささげ物はすべて、アロンの子ら全員のものとなり、等しく分けることとする。'),
('JPN', '利未记', 3, 7, 11, '主に献げられる交わりのいけにえについてのおしえは、次のとおりである。'),
('JPN', '利未记', 3, 7, 12, 'もし感謝のためにそれを献げるのなら、感謝のいけにえと一緒に、油を混ぜた種なしの輪形パンと、油を塗った種なしの薄焼きパン、さらに、油を混ぜてよくこねた小麦粉の輪形パンを献げる。'),
('JPN', '利未记', 3, 7, 13, '感謝のための交わりのいけにえと一緒に、種入りの輪形パンを献げる。'),
('JPN', '利未记', 3, 7, 14, 'そして、それぞれのささげ物から一つずつを取り、主への奉納物として献げる。これは、交わりのいけにえの血を振りかける祭司のものとなる。'),
('JPN', '利未记', 3, 7, 15, '感謝のための交わりのいけにえの肉は、それが献げられるその日に食べ、少しでも朝まで残しておいてはならない。'),
('JPN', '利未记', 3, 7, 16, 'もしそのささげ物のいけにえが誓願のささげ物、あるいは進んで献げるものであるなら、そのいけにえが献げられた日に食べなければならない。残ったものは翌日食べても差し支えない。'),
('JPN', '利未记', 3, 7, 17, 'いけにえの肉の残ったものは三日目に火で焼く。'),
('JPN', '利未记', 3, 7, 18, 'もしも、三日目にその交わりのいけにえの肉を食べるようなことがあれば、それは受け入れられず、それを献げる人のものとは見なされない。これは不浄のものとなり、これを食べる者はその咎を負わなければならない。'),
('JPN', '利未记', 3, 7, 19, 'また、何であれ汚れたものに触れた肉は食べてはならない。それは火で焼く。そうでない肉は、きよい人であればだれでも、その肉を食べることができる。'),
('JPN', '利未记', 3, 7, 20, 'しかし、その身に汚れがあるのに、人が、主に献げられた交わりのいけにえからの肉を食べるなら、その人は自分の民から断ち切られる。'),
('JPN', '利未记', 3, 7, 21, 'また人が、どんな物でも汚れたもの、すなわち人の汚れや汚れた動物、またあらゆる汚れた忌むべきものに触れていながら、主に献げられた交わりのいけにえの肉を食べるなら、その人は自分の民から断ち切られる。」'),
('JPN', '利未记', 3, 7, 22, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 7, 23, '「イスラエルの子らに告げよ。あなたがたは、牛であれ、羊であれ、やぎであれ、そのどの脂肪も食べてはならない。'),
('JPN', '利未记', 3, 7, 24, '動物の死骸にある脂肪や、野獣にかみ裂かれた動物の脂肪は、何に使っても差し支えない。しかし、決してそれを食べてはならない。'),
('JPN', '利未记', 3, 7, 25, '食物のささげ物として主に献げられた、動物の脂肪を食べる者はみな、自分の民から断ち切られるからである。'),
('JPN', '利未记', 3, 7, 26, 'また、あなたがたは、どこに住んでいても、鳥でも動物でもその血をいっさい食べてはならない。'),
('JPN', '利未记', 3, 7, 27, 'いかなる血でも、これを食べる者はみな、自分の民から断ち切られる。」'),
('JPN', '利未记', 3, 7, 28, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 7, 29, '「イスラエルの子らに告げよ。交わりのいけにえを主に献げる者は、自分の交わりのいけにえのうちから、そのささげ物を主のところに持って行かなければならない。'),
('JPN', '利未记', 3, 7, 30, 'その人は自分の手で主への食物のささげ物を持って行く。その脂肪を胸肉と一緒に持って行き、胸肉を奉献物として主の前で揺り動かす。'),
('JPN', '利未记', 3, 7, 31, '祭司はその脂肪を祭壇の上で焼いて煙にする。その胸肉はアロンとその子らのものとなる。'),
('JPN', '利未记', 3, 7, 32, 'あなたがたは、自分たちの交わりのいけにえのうちから右のもも肉を、奉納物として祭司に与えなければならない。'),
('JPN', '利未记', 3, 7, 33, 'アロンの子らのうち、交わりのいけにえの血と脂肪を献げる者が、その右のもも肉を自分の受ける分とする。'),
('JPN', '利未记', 3, 7, 34, 'それは、わたしが、奉献物の胸肉と奉納物のもも肉をイスラエルの子らから、その交わりのいけにえから取り、それらを祭司アロンとその子らに、イスラエルの子らから受け取るべき永遠の割り当てとして与えたからである。」'),
('JPN', '利未记', 3, 7, 35, 'これは、アロンとその子らが祭司として主に仕えるようになった日に、主への食物のささげ物のうちから彼らが受け取る分となった。'),
('JPN', '利未记', 3, 7, 36, 'それは、イスラエルの子らから取って彼らに与えるようにと、彼らが油注がれた日に主が命じられたもので、代々にわたる永遠の割り当てである。'),
('JPN', '利未记', 3, 7, 37, '以上は、全焼のささげ物、穀物のささげ物、罪のきよめのささげ物、代償のささげ物、任職のためのささげ物と交わりのいけにえについてのおしえである。'),
('JPN', '利未记', 3, 7, 38, 'これは、主がシナイの荒野でイスラエルの子らに、主にささげ物を献げるように命じた日に、主がシナイ山でモーセに命じられたものである。'),
('JPN', '利未记', 3, 8, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 8, 2, '「アロンと、彼とともにいるその子らを連れ、装束、注ぎの油、罪のきよめのささげ物の雄牛、二匹の雄羊、種なしパンのかごを取り、'),
('JPN', '利未记', 3, 8, 3, '全会衆を会見の天幕の入り口に集めよ。」'),
('JPN', '利未记', 3, 8, 4, 'モーセは主が命じられたとおりにした。会衆は会見の天幕の入り口に集まった。'),
('JPN', '利未记', 3, 8, 5, 'モーセは会衆に言った。「これは、主が行うように命じられたことである。」'),
('JPN', '利未记', 3, 8, 6, 'モーセはアロンとその子らを近づかせ、彼らを水で洗った。'),
('JPN', '利未记', 3, 8, 7, 'そしてアロンに長服を着せ、飾り帯を締め、その上に青服をまとわせ、さらにその上にエポデを着せた。すなわち、エポデのあや織りの帯で締めて、彼にエポデを着せた。'),
('JPN', '利未记', 3, 8, 8, '次に、彼に胸当てを着け、その胸当てにウリムとトンミムを入れた。'),
('JPN', '利未记', 3, 8, 9, 'また、彼の頭にかぶり物をかぶらせ、さらに、そのかぶり物の前面に金の札すなわち聖なる記章を付けた。主がモーセに命じられたとおりである。'),
('JPN', '利未记', 3, 8, 10, 'それから、モーセは注ぎの油を取って、幕屋とその中にあるすべてのものに油注ぎを行った。こうしてそれらを聖別した。'),
('JPN', '利未记', 3, 8, 11, 'さらに、それを祭壇の上に七度振りまき、祭壇とそのすべての用具、また洗盤とその台の油注ぎを行い、それらを聖別した。'),
('JPN', '利未记', 3, 8, 12, 'また、注ぎの油をアロンの頭に注いだ。こうして彼に油注ぎを行い、彼を聖別した。'),
('JPN', '利未记', 3, 8, 13, '次に、モーセはアロンの子らを連れて来て、彼らに長服を着せ、飾り帯を締め、ターバンを巻いた。主がモーセに命じられたとおりである。'),
('JPN', '利未记', 3, 8, 14, 'それから彼は罪のきよめのささげ物の雄牛を近寄らせた。そこで、アロンとその子らは、その罪のきよめのささげ物である雄牛の頭に手を置いた。'),
('JPN', '利未记', 3, 8, 15, 'それが屠られると、モーセはその血を取り、指でそれを祭壇の四隅の角に塗り、こうして祭壇から罪を除き、その残りの血を祭壇の土台に注いだ。このようにして祭壇のために宥めを行い、これを聖別した。'),
('JPN', '利未记', 3, 8, 16, 'そして、その内臓に付いている脂肪すべてと肝臓の小葉、二つの腎臓とその脂肪が取り出されると、モーセはそれらを祭壇の上で焼いて煙にした。'),
('JPN', '利未记', 3, 8, 17, 'また、その雄牛の皮と肉と汚物は宿営の外で火で焼いた。主がモーセに命じられたとおりである。'),
('JPN', '利未记', 3, 8, 18, '次に、彼は全焼のささげ物の雄羊を連れて来させた。アロンとその子らはその雄羊の頭に手を置いた。'),
('JPN', '利未记', 3, 8, 19, 'それが屠られると、モーセはその血を祭壇の側面に振りかけた。'),
('JPN', '利未记', 3, 8, 20, 'さらに、その雄羊が各部に切り分けられると、モーセは、その頭とその切り分けたものと内臓の脂肪とを焼いて煙にした。'),
('JPN', '利未记', 3, 8, 21, 'それから、その内臓と足を水で洗うと、モーセはその雄羊を全部、祭壇の上で焼いて煙にした。これは芳ばしい香りとしての全焼のささげ物で、主への食物のささげ物であった。主がモーセに命じられたとおりである。'),
('JPN', '利未记', 3, 8, 22, '次に、彼はもう一匹の雄羊、すなわち任職のための雄羊を連れて来させた。アロンとその子らはその雄羊の頭に手を置いた。'),
('JPN', '利未记', 3, 8, 23, 'それが屠られると、モーセはその血を取り、それをアロンの右の耳たぶと右手の親指と右足の親指に塗った。'),
('JPN', '利未记', 3, 8, 24, 'さらに、モーセはアロンの子らを近づかせ、その血を彼らの右の耳たぶ、また右手の親指と右足の親指に塗った。モーセはその血の残りを祭壇の側面に振りかけた。'),
('JPN', '利未记', 3, 8, 25, 'それから彼はその脂肪、すなわち、あぶら尾、内臓に付いている脂肪すべて、肝臓の小葉、二つの腎臓とその脂肪、また右のもも肉を取った。'),
('JPN', '利未记', 3, 8, 26, 'また主の前にある種なしパンのかごから、種なしの輪形パン一つと、油を混ぜた輪形パン一つと、薄焼きパン一つを取り、それをその脂肪と右のもも肉の上に置いた。'),
('JPN', '利未记', 3, 8, 27, 'それから彼は、そのすべてをアロンの手のひらとその子らの手のひらに載せ、奉献物として主の前で揺り動かした。'),
('JPN', '利未记', 3, 8, 28, 'そしてモーセはそれらを彼らの手のひらから取り、祭壇の上で、全焼のささげ物とともに焼いて煙にした。これらは芳ばしい香りとしての任職のためのささげ物であり、主への食物のささげ物である。'),
('JPN', '利未记', 3, 8, 29, 'モーセはまた、その胸肉を取り、奉献物として主の前で揺り動かした。これは任職のための雄羊のうちからモーセの受ける分となるもので、主がモーセに命じられたとおりである。'),
('JPN', '利未记', 3, 8, 30, 'それから、モーセは注ぎの油と祭壇の上の血を取り、それをアロンとその装束、彼とともにいるその子らとその装束の上にかけた。こうしてアロンとその装束、彼とともにいるその子らとその装束を聖別した。'),
('JPN', '利未记', 3, 8, 31, 'モーセはアロンとその子らに言った。「会見の天幕の入り口で、その肉を煮なさい。そしてそこで、それを任職のささげ物のかごの中にあるパンと一緒に食べなさい。私が、アロンとその子らはそれを食べよ、と命じたとおりに。'),
('JPN', '利未记', 3, 8, 32, '肉やパンの残りは火で焼かなければならない。'),
('JPN', '利未记', 3, 8, 33, 'また、あなたがたの任職の期間が終了する日までの七日間は、会見の天幕の入り口から出てはならない。あなたがたを祭司職に任命するには七日を要するからである。'),
('JPN', '利未记', 3, 8, 34, 'この日行ったように、主は、あなたがたが自分のために宥めを行うように命じられた。'),
('JPN', '利未记', 3, 8, 35, 'あなたがたは会見の天幕の入り口で七日の間、昼も夜もとどまり、主への務めを果たさなければならない。自分たちが死ぬことのないようにするためである。私はそのように命じられたのである。」'),
('JPN', '利未记', 3, 8, 36, 'アロンとその子らは、主がモーセを通して命じられたことすべてを行った。'),
('JPN', '利未记', 3, 9, 1, '八日目になってモーセはアロンとその子ら、およびイスラエルの長老たちを呼び寄せ、'),
('JPN', '利未记', 3, 9, 2, 'アロンに言った。「あなたは自分のために、罪のきよめのささげ物として子牛、すなわち若い雄牛を、また全焼のささげ物として雄羊を、それも傷のないものを取って、主の前に献げなさい。'),
('JPN', '利未记', 3, 9, 3, 'あなたはまた、イスラエルの子らにこう告げなければならない。あなたがたは、罪のきよめのささげ物として雄やぎを、また、全焼のささげ物として傷のない一歳の子牛と子羊を取りなさい。'),
('JPN', '利未记', 3, 9, 4, 'また、主の前でいけにえとするために、交わりのいけにえのための雄牛と雄羊を、また油を混ぜた穀物のささげ物を取りなさい。それは、今日、主があなたがたに現れるからである。」'),
('JPN', '利未记', 3, 9, 5, 'そこで彼らは、モーセが命じたものを会見の天幕の前に連れて来た。全会衆は近づいて来て、主の前に立った。'),
('JPN', '利未记', 3, 9, 6, 'モーセは言った。「これは、あなたがたが行うようにと主が命じられたことである。そのようにすれば、主の栄光があなたがたに現れる。」'),
('JPN', '利未记', 3, 9, 7, 'モーセはアロンに言った。「祭壇に近づきなさい。あなたの罪のきよめのささげ物と全焼のささげ物を献げ、あなた自身のため、またこの民のために宥めを行いなさい。また民のささげ物を献げ、主が命じられたとおりに彼らのために宥めを行いなさい。」'),
('JPN', '利未记', 3, 9, 8, 'そこでアロンは祭壇に近づき、自分のための、罪のきよめのささげ物である子牛を屠った。'),
('JPN', '利未记', 3, 9, 9, 'アロンの子らがその血を彼に差し出すと、アロンは指をその血に浸し、祭壇の四隅の角に塗った。彼はその血を祭壇の土台に注いだ。'),
('JPN', '利未记', 3, 9, 10, 'それから、罪のきよめのささげ物から脂肪と腎臓と肝臓の小葉を、祭壇の上で焼いて煙にした。主がモーセに命じられたとおりである。'),
('JPN', '利未记', 3, 9, 11, 'その肉と皮は宿営の外で火で焼いた。'),
('JPN', '利未记', 3, 9, 12, 'アロンは全焼のささげ物を屠り、アロンの子らがその血を彼に渡すと、彼はそれを祭壇の側面に振りかけた。'),
('JPN', '利未记', 3, 9, 13, 'また彼らが、全焼のささげ物を各部に切り分けたものとその頭を彼に渡すと、それらを祭壇の上で焼いて煙にした。'),
('JPN', '利未记', 3, 9, 14, 'それから内臓と足を洗い、全焼のささげ物とともに、これを祭壇の上で焼いて煙にした。'),
('JPN', '利未记', 3, 9, 15, '次に、彼は民のささげ物を携えて来て、民のための、罪のきよめのささげ物としてやぎを取り、屠って、先と同様にこれを罪のきよめのささげ物とした。'),
('JPN', '利未记', 3, 9, 16, 'それから、彼は全焼のささげ物を献げた。すなわち、規定のとおりにそれを行った。'),
('JPN', '利未记', 3, 9, 17, '次に、穀物のささげ物を献げ、その一部を手のひらいっぱいに取り、朝の全焼のささげ物とは別に祭壇の上で焼いて煙にした。'),
('JPN', '利未记', 3, 9, 18, 'それから、民のための交わりのいけにえの牛と雄羊が屠られた。アロンの子らがその血を渡すと、彼はそれを祭壇の側面に振りかけた。'),
('JPN', '利未记', 3, 9, 19, 'その牛と雄羊の脂肪の各部、すなわち、あぶら尾、内臓をおおう脂肪、腎臓、肝臓の小葉、'),
('JPN', '利未记', 3, 9, 20, 'これらの脂肪を彼らが胸肉の上に置くと、彼はその脂肪を祭壇の上で焼いて煙にした。'),
('JPN', '利未记', 3, 9, 21, '胸肉と右のもも肉は、モーセが命じたとおりに、アロンが奉献物として主の前で揺り動かした。'),
('JPN', '利未记', 3, 9, 22, 'こうして、アロンは民に向かって両手を上げ、彼らを祝福し、罪のきよめのささげ物、全焼のささげ物、交わりのいけにえを献げ終えて壇から降りて来た。'),
('JPN', '利未记', 3, 9, 23, 'モーセとアロンは会見の天幕に入り、そこから出て来て民を祝福した。すると主の栄光が民全体に現れ、'),
('JPN', '利未记', 3, 9, 24, '火が主の前から出て来て、祭壇の上の全焼のささげ物と脂肪を焼き尽くした。民はみな、これを見て喜び叫び、ひれ伏した。'),
('JPN', '利未记', 3, 10, 1, 'さて、アロンの子ナダブとアビフはそれぞれ自分の火皿を取り、中に火を入れ、上に香を盛って、主が彼らに命じたものではない異なる火を主の前に献げた。'),
('JPN', '利未记', 3, 10, 2, 'すると火が主の前から出て来て、彼らを焼き尽くした。それで彼らは主の前で死んだ。'),
('JPN', '利未记', 3, 10, 3, 'モーセはアロンに言った。「主がお告げになったことはこうだ。『わたしに近くある者たちによって、わたしは自分が聖であることを示し、民全体に向けてわたしは自分の栄光を現す。』」アロンは黙っていた。'),
('JPN', '利未记', 3, 10, 4, 'モーセはアロンのおじウジエルの子、ミシャエルとエルツァファンを呼び寄せ、彼らに言った。「近づいて行って、あなたがたの身内の者たちを、聖所の前から宿営の外に運び出しなさい。」'),
('JPN', '利未记', 3, 10, 5, '彼らはモーセが告げたとおり、近づいて行き、長服をつかんで彼らを宿営の外に運び出した。'),
('JPN', '利未记', 3, 10, 6, 'モーセは、アロンとその子エルアザルとイタマルに言った。「あなたがたは髪の毛を乱してはならない。また衣を引き裂いてはならない。あなたがたが死ぬことのないように、また御怒りが全会衆に下らないようにするためである。しかし、あなたがたの身内の者、すなわちイスラエルの全家族は、主が焼き殺した者のことを泣き悲しまなければならない。'),
('JPN', '利未记', 3, 10, 7, 'また、あなたがたは会見の天幕の入り口から外へ出てはならない。あなたがたが死ぬことのないようにするためである。あなたがたの上には主の注ぎの油があるからだ。」それで彼らはモーセのことばどおりにした。'),
('JPN', '利未记', 3, 10, 8, '主はアロンにこう告げられた。'),
('JPN', '利未记', 3, 10, 9, '「会見の天幕に入るときには、あなたも、あなたとともにいる息子たちも、ぶどう酒や強い酒を飲んではならない。あなたがたが死ぬことのないようにするためである。これはあなたがたが代々守るべき永遠の掟である。'),
('JPN', '利未记', 3, 10, 10, 'こうしてあなたがたは、聖なるものと俗なるもの、また汚れたものときよいものとを分け、'),
('JPN', '利未记', 3, 10, 11, 'また、主がモーセを通してイスラエルの子らに告げたすべての掟を、彼らに教えるのである。」'),
('JPN', '利未记', 3, 10, 12, 'モーセは、アロンと、残っている彼の息子、エルアザルとイタマルに言った。「主への食物のささげ物のうちから穀物のささげ物の残りを取り、種なしパンとして祭壇のそばで食べなさい。それは最も聖なるものだからである。'),
('JPN', '利未记', 3, 10, 13, 'それを聖なる所で食べなさい。それは、主への食物のささげ物のうちから、あなたが受ける割り当てであり、あなたの子らの割り当てである。そのように私は命じられている。'),
('JPN', '利未记', 3, 10, 14, 'しかし奉献物の胸肉と奉納物のもも肉は、あなたと、あなたとともにいるあなたの息子、娘たちが、きよい所で食べることが許される。それは、イスラエルの子らの交わりのいけにえから、あなたへの割り当て、またあなたの子らへの割り当てとして与えられている。'),
('JPN', '利未记', 3, 10, 15, '奉納物のもも肉と奉献物の胸肉は、食物のささげ物としての脂肪に添えて持って来て、奉献物として主の前で揺り動かさなければならない。これは主が命じられたとおり、あなたと、あなたとともにいるあなたの子らが永遠に受ける割り当てである。」'),
('JPN', '利未记', 3, 10, 16, 'モーセは罪のきよめのささげ物の雄やぎを懸命に捜した。しかし、なんと、それは焼かれてしまっていた。モーセは、アロンの子で残っているエルアザルとイタマルに怒って言った。'),
('JPN', '利未记', 3, 10, 17, '「どうして、あなたがたは、その罪のきよめのささげ物を聖なる所で食べなかったのか。それは最も聖なるものだ。それは、会衆の咎を負い、主の前で彼らのために宥めを行うために、あなたがたに与えられたのだ。'),
('JPN', '利未记', 3, 10, 18, '見よ、その血は聖所の中に携え入れられなかった。あなたがたは、私が命じたように、それを聖所で食べるべきだったのだ。」'),
('JPN', '利未记', 3, 10, 19, 'アロンはモーセに言った。「見なさい。今日、彼らは自分たちの罪のきよめのささげ物と全焼のささげ物を主の前に献げたが、このようなことが私の身に降りかかったのだ。今日、私が罪のきよめのささげ物を食べていたら、そのことは主の目に良しとされただろうか。」'),
('JPN', '利未记', 3, 10, 20, 'モーセはこれを聞き、それでよいとした。'),
('JPN', '利未记', 3, 11, 1, '主はモーセとアロンに告げて、こう彼らに言われた。'),
('JPN', '利未记', 3, 11, 2, '「イスラエルの子らに告げよ。次のものは、地上のすべての動物のうちで、あなたがたが食べてもよい生き物である。'),
('JPN', '利未记', 3, 11, 3, '動物のうち、すべてひづめが分かれ、完全にひづめが割れているもので、反芻するもの。それは食べてもよい。'),
('JPN', '利未记', 3, 11, 4, 'ただし、反芻するもの、あるいは、ひづめが分かれているものの中でも、次のものは食べてはならない。らくだ。これは反芻はするが、ひづめが分かれていないので、あなたがたには汚れたものである。'),
('JPN', '利未记', 3, 11, 5, '岩だぬき。これも反芻はするが、ひづめが分かれていないので、あなたがたには汚れたものである。'),
('JPN', '利未记', 3, 11, 6, '野うさぎ。これも反芻はするが、ひづめが分かれていないので、あなたがたには汚れたものである。'),
('JPN', '利未记', 3, 11, 7, '豚。これはひづめが分かれていて、完全に割れてはいるが、反芻しないので、あなたがたには汚れたものである。'),
('JPN', '利未记', 3, 11, 8, 'あなたがたは、それらの肉を食べてはならない。また、それらの死骸に触れてもいけない。それらは、あなたがたには汚れたものである。'),
('JPN', '利未记', 3, 11, 9, '水の中にいるすべてのもののうちで次のものを、あなたがたは食べてもよい。海でも川でも水の中にいるもので、ひれと鱗のあるものはすべて食べてもよい。'),
('JPN', '利未记', 3, 11, 10, 'しかし海でも川でも、すべて水に群がるもの、またはすべて水の中にいる生き物のうち、ひれや鱗のないものはすべて、あなたがたには忌むべきものである。'),
('JPN', '利未记', 3, 11, 11, 'これらは、あなたがたには忌むべきものである。それらの肉を食べてはならない。また、それらの死骸を忌むべきものとしなければならない。'),
('JPN', '利未记', 3, 11, 12, '水の中にいるもので、ひれや鱗のないものはすべて、あなたがたには忌むべきものである。'),
('JPN', '利未记', 3, 11, 13, 'また、鳥のうちで次のものを忌むべきものとしなければならない。これらは忌むべきもので、食べることはできない。すなわち、禿鷲、禿鷹、黒禿鷹、'),
('JPN', '利未记', 3, 11, 14, '鳶、隼の類、'),
('JPN', '利未记', 3, 11, 15, '烏の類すべて、'),
('JPN', '利未记', 3, 11, 16, 'だちょう、夜鷹、かもめ、鷹の類、'),
('JPN', '利未记', 3, 11, 17, 'ふくろう、鵜、みみずく、'),
('JPN', '利未记', 3, 11, 18, '白ふくろう、森ふくろう、野雁、'),
('JPN', '利未记', 3, 11, 19, 'こうのとり、鷺の類、やつがしら、こうもりである。'),
('JPN', '利未记', 3, 11, 20, '羽があって群がり、四本の足で歩き回るものはすべて、あなたがたには忌むべきものである。'),
('JPN', '利未记', 3, 11, 21, 'ただし、羽があって群がり、四本の足で歩き回るもののうちで、それらの足より高い二本の跳ね足を持ち、それで地上を飛び跳ねるものは食べてもよい。'),
('JPN', '利未记', 3, 11, 22, 'それらのうち、あなたがたが食べてもよいものは次のとおりである。いなごの類、毛のないいなごの類、コオロギの類、バッタの類。'),
('JPN', '利未记', 3, 11, 23, 'しかし羽があって群がり、足が四本あるものはすべて、あなたがたには忌むべきものである。'),
('JPN', '利未记', 3, 11, 24, '次のことによっても、あなたがたは身を汚すことになる。すなわち、それらのものの死骸に触れる者はだれでも夕方まで汚れる。'),
('JPN', '利未记', 3, 11, 25, 'また、それらの死骸を運ぶ者はみな、自分の衣服を洗わなければならない。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 11, 26, 'ひづめが分かれてはいても完全には割れていないか、あるいは反芻しない動物のことについては、これらはすべて、あなたがたにとって汚れたものである。これらに触れる者はだれでも汚れる。'),
('JPN', '利未记', 3, 11, 27, 'また、四本の足で歩き回るすべての生き物のうち、足の裏のふくらみで歩くものはすべて、あなたがたにとって汚れたものである。その死骸に触れる者はみな夕方まで汚れる。'),
('JPN', '利未记', 3, 11, 28, 'その死骸を運ぶ者は自分の衣服を洗わなければならない。その人は夕方まで汚れる。これらは、あなたがたには汚れたものである。'),
('JPN', '利未记', 3, 11, 29, '地に群がるもののうち次のものは、あなたがたにとって汚れたものである。すなわち、もぐら、跳びねずみ、大トカゲの類、'),
('JPN', '利未记', 3, 11, 30, 'ヤモリ、ワニ、トカゲ、砂トカゲ、カメレオンである。'),
('JPN', '利未记', 3, 11, 31, 'すべて群がるもののうち、これらは、あなたがたにとって汚れたものである。これらが死んだ状態のときに触れる者はだれでも夕方まで汚れる。'),
('JPN', '利未记', 3, 11, 32, 'また、それらのうちのあるものが死んで何かの上に落ち、それが木の器、衣服、皮、袋など、何かに用いる物である場合、それは汚れる。それは水の中に入れなければならず、夕方まで汚れ、その後きよくなる。'),
('JPN', '利未记', 3, 11, 33, 'また、それらのうちの一つが、どのような土の器の中に落ちても、その中にあるものはすべて汚れる。その器は砕かなければならない。'),
('JPN', '利未记', 3, 11, 34, 'また食べられる物で、それに水がかかっていれば、それはみな汚れる。また飲める物で、そのような器の中にあるものはみな汚れる。'),
('JPN', '利未记', 3, 11, 35, 'さらに、どのようなものでも、その上にこれらの死骸の一つが落ちたものは汚れる。それがかまどであれ炉であれ、打ち壊されなければならない。それは汚れていて、あなたがたには汚れたものとなる。'),
('JPN', '利未记', 3, 11, 36, 'ただし泉、あるいは水のたまっている水溜めだけはきよい。しかし、それらの死骸に触れる者は汚れる。'),
('JPN', '利未记', 3, 11, 37, 'また、蒔かれる種の上にそれらの死骸のどの一つが落ちても、それはきよい。'),
('JPN', '利未记', 3, 11, 38, 'しかし、種の上に水がかけられていて、その上にそれらの死骸のあるものが落ちたなら、それはあなたがたには汚れたものである。'),
('JPN', '利未记', 3, 11, 39, 'あなたがたが食用として飼っている動物の一匹が死んだとき、その死骸に触れる者は夕方まで汚れる。'),
('JPN', '利未记', 3, 11, 40, 'その死骸を食べる者は自分の衣服を洗わなければならない。その人は夕方まで汚れる。また、その死骸を運ぶ者も自分の衣服を洗わなければならない。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 11, 41, '地に群がるものはすべて忌むべきもので、食べることはできない。'),
('JPN', '利未记', 3, 11, 42, '地に群がるもののうち、腹で這うもの、また四本の足で歩くもの、あるいは多くの足のあるもの、これらのどれも、あなたがたは食べてはならない。それらは忌むべきものである。'),
('JPN', '利未记', 3, 11, 43, 'あなたがたは、いかなる群がるものによっても、自分自身を忌むべきものとしてはならない。また、それによって身を汚し、それによって汚れてはならない。'),
('JPN', '利未记', 3, 11, 44, 'わたしはあなたがたの神、主であるからだ。あなたがたは自分の身を聖別して、聖なる者とならなければならない。わたしが聖だからである。あなたがたは、地の上を這ういかなる群がるものによっても、自分自身を汚してはならない。'),
('JPN', '利未记', 3, 11, 45, 'わたしは、あなたがたの神となるために、あなたがたをエジプトの地から導き出した主であるからだ。あなたがたは聖なる者とならなければならない。わたしが聖だからである。」'),
('JPN', '利未记', 3, 11, 46, '以上が、動物と鳥、また水の中にうごめくすべての生き物と、地に群がるすべての生き物についてのおしえであり、'),
('JPN', '利未记', 3, 11, 47, 'それによって、汚れたものときよいもの、食べてよい生き物と食べてはならない生き物とが分けられるのである。'),
('JPN', '利未记', 3, 12, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 12, 2, '「イスラエルの子らに告げよ。女が身重になり、男の子を産んだとき、その女は七日の間汚れ、月のさわりの不浄の期間と同じように汚れる。'),
('JPN', '利未记', 3, 12, 3, '八日目には、その子の包皮の肉に割礼を施す。'),
('JPN', '利未记', 3, 12, 4, '彼女は血のきよめのために、さらに三十三日間こもる。そのきよめの期間が満ちるまでは、いかなる聖なるものにも触れてはならない。また聖所に入ってはならない。'),
('JPN', '利未记', 3, 12, 5, '女の子を産んだ場合は、月のさわりの時と同じように二週間汚れる。彼女は、血のきよめがなされる必要があるので、さらに六十六日間こもる。'),
('JPN', '利未记', 3, 12, 6, '彼女のきよめの期間が満ちたら、息子の場合であっても娘の場合であっても、全焼のささげ物として一歳の子羊一匹と、罪のきよめのささげ物として家鳩のひなか山鳩を一羽、会見の天幕の入り口にいる祭司のところに持って行く。'),
('JPN', '利未记', 3, 12, 7, '祭司はこれを主の前に献げ、彼女のために宥めを行い、彼女はその出血の汚れからきよくなる。これが、男の子であれ女の子であれ、子を産む女についてのおしえである。'),
('JPN', '利未记', 3, 12, 8, 'しかし、もし彼女に羊を買う余裕がなければ、二羽の山鳩か、二羽の家鳩のひなを取り、一羽は全焼のささげ物、もう一羽は罪のきよめのささげ物とする。祭司は彼女のために宥めを行い、彼女はきよくなる。」'),
('JPN', '利未记', 3, 13, 1, '主はモーセとアロンにこう告げられた。'),
('JPN', '利未记', 3, 13, 2, '「ある人のからだの皮膚に腫れもの、あるいはかさぶた、あるいは斑点ができて、からだの皮膚にツァラアトに冒された患部が現れたときは、彼を祭司アロンのところか、アロンの子らで祭司の一人のところに連れて来なければならない。'),
('JPN', '利未记', 3, 13, 3, '祭司は、そのからだの皮膚の患部を調べる。その患部の毛が白く変わり、患部がそのからだの皮膚よりも深いところに見えているなら、それはツァラアトに冒された患部である。祭司はそれを調べ、彼を汚れていると宣言する。'),
('JPN', '利未记', 3, 13, 4, 'もしそのからだの皮膚の斑点が白く、皮膚よりも深くは見えず、そこの毛も白く変わっていなければ、祭司はその患者を七日間隔離する。'),
('JPN', '利未记', 3, 13, 5, '祭司は七日目に彼を調べる。もしその患部が祭司の目にはそのままに見えて、その患部が皮膚に広がっていなければ、祭司は彼をさらに七日間隔離する。'),
('JPN', '利未记', 3, 13, 6, '祭司は七日目に再び彼を調べる。もし患部が薄れ、その患部が皮膚に広がっていなければ、祭司は彼をきよいと宣言する。それは、かさぶたである。彼は自分の衣服を洗う。こうして彼はきよくなる。'),
('JPN', '利未记', 3, 13, 7, 'しかし、もしも彼が祭司にその身を見せてきよいと宣言された後で、かさぶたが皮膚に広がってくるようなことがあるなら、再び祭司にその身を見せる。'),
('JPN', '利未记', 3, 13, 8, '祭司が調べて、かさぶたが皮膚に広がっているなら、祭司は彼を汚れていると宣言する。それはツァラアトである。'),
('JPN', '利未记', 3, 13, 9, '人にツァラアトに冒された患部があるときは、祭司のところに連れて来る。'),
('JPN', '利未记', 3, 13, 10, '祭司が調べ、もし皮膚に白い腫れものがあり、その毛も白く変わり、腫れものにむき出しの肉が盛り上がっているなら、'),
('JPN', '利未记', 3, 13, 11, 'それは、そのからだの皮膚にできた慢性のツァラアトである。祭司は彼を汚れていると宣言する。彼を隔離する必要はない。彼はすでに汚れている。'),
('JPN', '利未记', 3, 13, 12, 'しかし、もしも、そのツァラアトが皮膚に生じて、祭司が目で見るかぎり、ツァラアトが頭から足まで患者の皮膚全体をおおうようなことがあるなら、'),
('JPN', '利未记', 3, 13, 13, '祭司がそれを調べる。もし、そのツァラアトがその人のからだ全体をおおっているなら、祭司はその患者をきよいと宣言する。すべてが白く変わったので、彼はきよい。'),
('JPN', '利未记', 3, 13, 14, 'しかし肉がむき出しになったときは、彼は汚れた者となる。'),
('JPN', '利未记', 3, 13, 15, '祭司はそのむき出しの肉を調べて、彼を汚れていると宣言する。そのむき出しの肉は汚れている。それはツァラアトである。'),
('JPN', '利未记', 3, 13, 16, 'しかし、もしそのむき出しの肉が再び白く変われば、彼は祭司のところに来る。'),
('JPN', '利未记', 3, 13, 17, '祭司は彼を調べる。もしその患部が白く変わっているなら、祭司はその患部をきよいと宣言する。彼はきよい。'),
('JPN', '利未记', 3, 13, 18, 'からだの皮膚にできものができ、それが治った後、'),
('JPN', '利未记', 3, 13, 19, 'そのできものの局所に白色の腫れもの、または赤みがかった白い斑点があれば、それを祭司に見せる。'),
('JPN', '利未记', 3, 13, 20, '祭司が調べて、もしそれが皮膚よりも深いところに見え、そこの毛が白く変わっているなら、祭司は彼を汚れていると宣言する。それはそのできものに生じた、ツァラアトに冒された患部である。'),
('JPN', '利未记', 3, 13, 21, 'もし祭司がこれを調べて、そこに白い毛がなく、それが皮膚よりも深くはなく、それが薄れているなら、祭司は彼を七日間隔離する。'),
('JPN', '利未记', 3, 13, 22, 'もしも、それが皮膚に広がってくるようなことがあるなら、祭司はその人を汚れていると宣言する。それは患部である。'),
('JPN', '利未记', 3, 13, 23, 'もしその斑点が元のままであり、広がっていなければ、それはできものの跡である。祭司は彼をきよいと宣言する。'),
('JPN', '利未记', 3, 13, 24, 'あるいは、からだの皮膚に火傷があって、その火傷の生肉が赤みがかった白色、または白色の斑点であれば、'),
('JPN', '利未记', 3, 13, 25, '祭司はこれを調べる。もし斑点の上の毛が白く変わり、それが皮膚よりも深いところに見えるなら、それは火傷に生じたツァラアトである。祭司は彼を汚れていると宣言する。それはツァラアトに冒された患部である。'),
('JPN', '利未记', 3, 13, 26, 'しかし、もし祭司がこれを調べて、その斑点に白い毛がなく、それが皮膚より深くはなく薄れているなら、祭司は彼を七日間隔離する。'),
('JPN', '利未记', 3, 13, 27, 'それから七日目に祭司は彼を調べる。もしも、それが皮膚に広がってくるようなことがあるなら、祭司は彼を汚れていると宣言する。これはツァラアトに冒された患部である。'),
('JPN', '利未记', 3, 13, 28, 'もしその斑点が元のままであり、その皮膚に広がっておらず、薄れているなら、それは火傷による腫れである。祭司は彼をきよいと宣言する。これは火傷の跡である。'),
('JPN', '利未记', 3, 13, 29, '男あるいは女で、頭か、ひげに疾患があるとき、'),
('JPN', '利未记', 3, 13, 30, '祭司はその患部を調べる。もしそれが皮膚よりも深いところに見え、そこに細い黄色の毛があるなら、祭司は彼を汚れていると宣言する。これは疥癬で、頭またはひげのツァラアトである。'),
('JPN', '利未记', 3, 13, 31, '祭司が疥癬の部分を調べ、もしそれが皮膚よりも深いところに見えず、そこに黒い毛がないなら、祭司はその疥癬の患者を七日間隔離する。'),
('JPN', '利未记', 3, 13, 32, '七日目に祭司は患部を調べる。もしその疥癬が広がっておらず、またそこに黄色い毛もなく、疥癬が皮膚よりも深いところに見えていなければ、'),
('JPN', '利未记', 3, 13, 33, 'その人は毛を剃り落とす。ただし、その疥癬を剃り落としてはならない。祭司はその疥癬の患者をさらに七日間隔離する。'),
('JPN', '利未记', 3, 13, 34, '七日目に祭司はその疥癬を調べる。もし疥癬が皮膚に広がっておらず、それが皮膚よりも深いところに見えていなければ、祭司はその人をきよいと宣言する。彼は自分の衣服を洗う。こうして彼はきよくなる。'),
('JPN', '利未记', 3, 13, 35, 'しかし、もしも、その人がきよいと宣言された後に、その疥癬が皮膚に広がってくるようなことがあれば、'),
('JPN', '利未记', 3, 13, 36, '祭司は彼を調べる。もしその疥癬が皮膚に広がっていれば、祭司は黄色の毛を見分ける必要はない。その人は汚れている。'),
('JPN', '利未记', 3, 13, 37, 'もし祭司が見て、その疥癬が元のままであり、黒い毛がそこに生えているなら、その疥癬は治っていて、その人はきよい。祭司は彼をきよいと宣言する。'),
('JPN', '利未记', 3, 13, 38, '男あるいは女で、そのからだの皮膚に斑点、すなわち白い斑点があるとき、'),
('JPN', '利未记', 3, 13, 39, '祭司はこれを調べる。もしそのからだの皮膚にある斑点が淡い白色であるなら、これは皮膚に生じた湿疹で、彼はきよい。'),
('JPN', '利未记', 3, 13, 40, '男の髪の毛が抜け落ちるとき、それははげであって、彼はきよい。'),
('JPN', '利未记', 3, 13, 41, 'もし顔の生えぎわから髪の毛が抜けても、それは額のはげであって、彼はきよい。'),
('JPN', '利未记', 3, 13, 42, 'もしその頭のはげか額のはげに、赤みがかった白い部分があるなら、それは頭のはげに、あるいは額のはげに生じたツァラアトである。'),
('JPN', '利未记', 3, 13, 43, '祭司は彼を調べる。患部の腫れものが、頭のはげ、あるいは額のはげの部分で、からだの皮膚にあるツァラアトに見られるような、赤みがかった白色であれば、'),
('JPN', '利未记', 3, 13, 44, '彼はツァラアトに冒された者であって、この者は汚れている。祭司は彼を汚れていると必ず宣言する。その患部が頭にあるからである。'),
('JPN', '利未记', 3, 13, 45, '患部があるツァラアトに冒された者は自分の衣服を引き裂き、髪の毛を乱し、口ひげをおおって、『汚れている、汚れている』と叫ぶ。'),
('JPN', '利未记', 3, 13, 46, 'その患部が彼にある間、その人は汚れたままである。彼は汚れているので、ひとりで住む。宿営の外が彼の住まいとなる。'),
('JPN', '利未记', 3, 13, 47, '衣服にツァラアトに冒された箇所が生じた場合は、羊毛の衣服でも、亜麻布の衣服でも、'),
('JPN', '利未记', 3, 13, 48, '亜麻または羊毛の織物でも、編物でも、皮でも、また皮で作ったいかなるものでも、'),
('JPN', '利未记', 3, 13, 49, '冒された箇所が緑がかっていたり赤みを帯びたりしているなら、衣服でも皮でも織物でも編物でも、またいかなる皮製品でも、それはツァラアトに冒された箇所である。それを祭司に見せる。'),
('JPN', '利未记', 3, 13, 50, '祭司はその箇所を調べる。そして、冒された箇所がある物を七日間隔離する。'),
('JPN', '利未记', 3, 13, 51, '七日目に彼は、冒された箇所がある物を調べる。それが衣服でも織物でも編物でも皮でも、また皮が何に用いられていても、それらに冒された箇所が広がっているとき、その箇所は悪性のツァラアトで、それは汚れている。'),
('JPN', '利未记', 3, 13, 52, '羊毛のものであれ亜麻のものであれ、衣服、あるいは織物でも編物でも、またいかなる皮製品でも、冒された箇所がある物は焼く。これは悪性のツァラアトであるから、火で焼かなければならない。'),
('JPN', '利未记', 3, 13, 53, 'もし祭司が調べて、衣服、織物、編物、またいかなる皮製品でも、その箇所が広がっていなければ、'),
('JPN', '利未记', 3, 13, 54, '祭司は命じて、冒された箇所がある物を洗わせ、さらに七日間それを隔離する。'),
('JPN', '利未记', 3, 13, 55, '冒された箇所がある物が洗われてから、祭司がそれを調べて、もしその部分が変化したように見えないなら、その部分が広がっていなくても、それは汚れている。それは火で焼かなければならない。それが内側にあっても外側にあっても、それは腐食である。'),
('JPN', '利未记', 3, 13, 56, 'しかし、もし祭司が調べて、冒された箇所が洗われた後に薄れていたら、彼はそれを衣服や皮や織物や編物から切り取る。'),
('JPN', '利未记', 3, 13, 57, 'もし、その衣服、織物、編物、またいかなる皮製品でも、再びそれが現れたなら、それは再発である。冒された箇所のある物は火で焼かなければならない。'),
('JPN', '利未记', 3, 13, 58, 'しかし、洗った衣服、織物、編物、またいかなる皮製品でも、冒された箇所がそれから消えていたら、もう一度これを洗う。こうして、それはきよくなる。」'),
('JPN', '利未记', 3, 13, 59, '以上は、羊毛または亜麻布の衣服、織物、編物、すべての皮製品の、ツァラアトに冒された箇所についてのおしえであり、それをきよい、あるいは汚れていると宣言するためである。'),
('JPN', '利未记', 3, 14, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 14, 2, '「ツァラアトに冒された者がきよめられるときのおしえは、次のとおりである。彼が祭司のところに連れて来られたら、'),
('JPN', '利未记', 3, 14, 3, '祭司は宿営の外に出て行く。祭司が調べて、もしツァラアトに冒された者の、その患部が治っているなら、'),
('JPN', '利未记', 3, 14, 4, '祭司はそのきよめられる者のために、二羽の生きているきよい小鳥と、杉の枝と緋色の撚り糸とヒソプを取り寄せるように命じる。'),
('JPN', '利未记', 3, 14, 5, '祭司は、その小鳥のうちの一羽を、新鮮な水を入れた土の器の上で殺すように命じる。'),
('JPN', '利未记', 3, 14, 6, 'そして、生きている小鳥を、杉の枝と緋色の撚り糸とヒソプとともに取り、それらをその生きている小鳥と一緒に、新鮮な水の上で殺された小鳥の血の中に浸す。'),
('JPN', '利未记', 3, 14, 7, 'それを、ツァラアトからきよめられる者の上に七度かけ、彼をきよいと宣言し、さらにその生きている小鳥を野に放す。'),
('JPN', '利未记', 3, 14, 8, 'きよめられる者は自分の衣服を洗い、その毛をみな剃り落とし、水を浴びる。こうしてその人はきよくなる。その後で、宿営に入ることができる。しかし、七日間は自分の天幕の外にとどまる。'),
('JPN', '利未记', 3, 14, 9, '七日目になって、彼は髪の毛、口ひげ、眉毛など自分のすべての毛を剃り落とす。すべての毛を剃り落とし、自分の衣服を洗い、からだに水を浴びる。こうしてその人はきよくなる。'),
('JPN', '利未记', 3, 14, 10, '八日目に彼は、傷のない雄の子羊二匹と、傷のない一歳の雌の子羊一匹と、穀物のささげ物としての、油を混ぜた小麦粉十分の三エパと、油一ログを持って来る。'),
('JPN', '利未记', 3, 14, 11, 'きよめを宣言する祭司は、これらのものとともに、きよめられる者を主の前、会見の天幕の入り口に立たせる。'),
('JPN', '利未记', 3, 14, 12, '祭司は雄の子羊一匹を取り、それを油一ログと一緒に献げて代償のささげ物とし、それを奉献物として主の前で揺り動かす。'),
('JPN', '利未记', 3, 14, 13, 'その雄の子羊を、罪のきよめのささげ物と全焼のささげ物を屠る場所、すなわち聖なる所で屠る。罪のきよめのささげ物と同様に、代償のささげ物も祭司のものだからである。これは最も聖なるものである。'),
('JPN', '利未记', 3, 14, 14, '祭司は代償のささげ物の血を取り、それを、きよめられる者の右の耳たぶと右手の親指と右足の親指に塗る。'),
('JPN', '利未记', 3, 14, 15, '祭司は油一ログからいくらかを取って、自分の左の手のひらに注ぎ、'),
('JPN', '利未记', 3, 14, 16, '右の指を左の手のひらの油に浸し、その指で油を主の前に七度振りまく。'),
('JPN', '利未记', 3, 14, 17, '祭司はその手のひらの中の残りの油を、きよめられる者の右の耳たぶと右手の親指と右足の親指に、すなわち先の代償のささげ物の血の上に付ける。'),
('JPN', '利未记', 3, 14, 18, '祭司はその手のひらの中の残りの油を、きよめられる者の頭に塗る。こうして祭司は主の前でその人のために宥めを行う。'),
('JPN', '利未记', 3, 14, 19, '祭司は罪のきよめのささげ物を献げ、きよめられる者のために、汚れを除いて宥めを行う。その後で全焼のささげ物が屠られる。'),
('JPN', '利未记', 3, 14, 20, '祭司は祭壇の上で、全焼のささげ物と穀物のささげ物を献げる。祭司はその人のために宥めを行い、彼はきよくなる。'),
('JPN', '利未记', 3, 14, 21, 'もしその人が貧しくて、それらのものを手に入れることができなければ、自分のための宥めとなる奉献物とするために、代償のささげ物として雄の子羊一匹を、また穀物のささげ物として油を混ぜた小麦粉十分の一エパと、油一ログを取り、'),
('JPN', '利未记', 3, 14, 22, 'また、手に入れることのできる山鳩二羽か家鳩のひな二羽を取り、その一羽を罪のきよめのささげ物、もう一羽を全焼のささげ物とする。'),
('JPN', '利未记', 3, 14, 23, '八日目に自分のきよめのために、それらを会見の天幕の入り口の祭司のところに、主の前に持って行く。'),
('JPN', '利未记', 3, 14, 24, '祭司はその代償のささげ物の子羊と油一ログを取って、これを奉献物として主の前で揺り動かし、'),
('JPN', '利未记', 3, 14, 25, '代償のささげ物の子羊を屠る。祭司はその代償のささげ物の血を取って、それを、きよめられる者の右の耳たぶと右手の親指と右足の親指に塗る。'),
('JPN', '利未记', 3, 14, 26, '祭司はその油を自分の左の手のひらに注ぎ、'),
('JPN', '利未记', 3, 14, 27, '右手の指で、左の手のひらの油を主の前に七度振りまく。'),
('JPN', '利未记', 3, 14, 28, 'そして、その手のひらにある油を、きよめられる者の右の耳たぶと右手の親指と右足の親指に、すなわち代償のささげ物の血と同じところに付ける。'),
('JPN', '利未记', 3, 14, 29, '祭司はその手のひらにある残りの油を、きよめられる者の頭に塗り、主の前で彼のために宥めを行う。'),
('JPN', '利未记', 3, 14, 30, 'また彼は、手に入れることのできた、山鳩か、家鳩のひなのうちから献げる。'),
('JPN', '利未记', 3, 14, 31, 'すなわち、手に入れることのできるもののうち、罪のきよめのささげ物として一羽を、全焼のささげ物としてもう一羽を、穀物のささげ物とともに献げる。祭司は主の前で、きよめられる者のために宥めを行う。」'),
('JPN', '利未记', 3, 14, 32, '以上が、ツァラアトに冒された患部がある者で、きよめに必要なものを手に入れることのできない者のためのおしえである。'),
('JPN', '利未记', 3, 14, 33, '主はモーセとアロンにこう告げられた。'),
('JPN', '利未记', 3, 14, 34, '「わたしがあなたがたに所有地として与えようとしているカナンの地に、あなたがたが入り、わたしがその所有地にある家に、ツァラアトに冒された箇所を生じさせたとき、'),
('JPN', '利未记', 3, 14, 35, 'その家の所有者は来て、祭司に、何か冒された箇所のようなものが家に現れたと言って、報告する。'),
('JPN', '利未记', 3, 14, 36, '祭司は、彼がその箇所を調べに入る前に、その家を片付けるように命じる。すべて家にあるものが汚れることのないようにするためである。その後で祭司はその家を調べに入る。'),
('JPN', '利未记', 3, 14, 37, '冒された箇所を調べ、もしその箇所がその家の壁に出ていて、それが緑がかった、または赤みがかったくぼみであって、壁の表面よりも深いところに見えるなら、'),
('JPN', '利未记', 3, 14, 38, '祭司はその家から戸口に出て来て、七日間その家を閉ざしておく。'),
('JPN', '利未记', 3, 14, 39, '祭司は七日目にまた来て調べる。もし冒された箇所がその家の壁に広がっているなら、'),
('JPN', '利未记', 3, 14, 40, '祭司は、冒された箇所がある石を取り出し、それらを町の外の汚れた場所に投げ捨てるように命じる。'),
('JPN', '利未记', 3, 14, 41, 'また、家の内側のすべての面を削り落とさせ、削り落とした漆喰を町の外の汚れた場所に捨てさせる。'),
('JPN', '利未记', 3, 14, 42, 'さらに、別の石を取って前の石の代わりに入れ、また別の漆喰を取ってその家を塗り直させる。'),
('JPN', '利未记', 3, 14, 43, 'もし石を取り出し、家の壁を削り落とし、また塗り直した後に、再び冒された箇所が家に生じたなら、'),
('JPN', '利未记', 3, 14, 44, '祭司は入って調べる。もしその箇所が家に広がっていたら、それは家に付く悪性のツァラアトであり、それは汚れている。'),
('JPN', '利未记', 3, 14, 45, 'その家はその石材と木材と漆喰のすべてを取り壊し、それを町の外の汚れた場所に運び出す。'),
('JPN', '利未记', 3, 14, 46, 'その家が閉ざされている期間中にそこに入る者は、夕方まで汚れる。'),
('JPN', '利未记', 3, 14, 47, 'その家で寝る者は自分の衣服を洗う。その家で食事をする者も自分の衣服を洗う。'),
('JPN', '利未记', 3, 14, 48, 'しかし、もしも、祭司が入って行くことがあり、調べて、家が塗り直された後にその冒された箇所が家に広がっていないなら、祭司はその家はきよいと宣言する。冒された箇所が治ったからである。'),
('JPN', '利未记', 3, 14, 49, '祭司はその家の汚れを除くために、小鳥二羽と杉の木と緋色の撚り糸とヒソプを取り、'),
('JPN', '利未记', 3, 14, 50, 'その小鳥のうちの一羽を、新鮮な水を入れた土の器の上で殺す。'),
('JPN', '利未记', 3, 14, 51, '杉の木とヒソプと緋色の撚り糸と、生きている小鳥を取って、殺された小鳥の血と新鮮な水の中にそれらを浸し、その家に七度振りまく。'),
('JPN', '利未记', 3, 14, 52, '祭司は、小鳥の血と新鮮な水と、生きた小鳥と杉の木とヒソプと緋色の撚り糸とによって、家の汚れを除き、'),
('JPN', '利未记', 3, 14, 53, 'その生きている小鳥を町の外の野に放つ。こうして彼はその家のために宥めを行い、その家はきよくなる。」'),
('JPN', '利未记', 3, 14, 54, '以上が、ツァラアトに冒されたあらゆる患部、疥癬、'),
('JPN', '利未记', 3, 14, 55, '衣服と家のツァラアト、'),
('JPN', '利未记', 3, 14, 56, '腫れもの、かさぶた、斑点についてのおしえであり、'),
('JPN', '利未记', 3, 14, 57, 'どのようなときにそれが汚れていて、また、どのようなときにそれがきよいのかを教えるためのもので、ツァラアトについてのおしえである。'),
('JPN', '利未记', 3, 15, 1, '主はモーセとアロンにこう告げられた。'),
('JPN', '利未记', 3, 15, 2, '「イスラエルの子らに告げよ。だれでも、隠しどころから漏出があったなら、その漏出物は汚れている。'),
('JPN', '利未记', 3, 15, 3, 'その漏出物による汚れは次のとおりである。その隠しどころが漏出物を漏らしても、あるいは、その隠しどころが漏出物をとどめていても、そのことはその人の汚れである。'),
('JPN', '利未记', 3, 15, 4, '漏出を病む者が寝た床は全体が汚れる。またその人が座った物もすべて汚れる。'),
('JPN', '利未记', 3, 15, 5, 'その床に触れた者はだれでも自分の衣服を洗い、水を浴びる。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 6, '漏出を病む者が座った物の上に座った者は、自分の衣服を洗い、水を浴びる。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 7, '漏出を病む者の隠しどころに触れた者も、自分の衣服を洗い、水を浴びる。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 8, '漏出を病む者が、きよい人に唾をかけたなら、唾をかけられた人は自分の衣服を洗い、水を浴びる。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 9, '漏出を病む者が乗った鞍は全体が汚れる。'),
('JPN', '利未记', 3, 15, 10, 'また、何であれ、その人の下にあった物に触れた人はだれでも夕方まで汚れる。また、それを運んだ者も自分の衣服を洗い、水を浴びる。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 11, 'また、漏出を病む者が水で手を洗わずに触れた人はみな、自分の衣服を洗い、水を浴びる。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 12, '漏出を病む者が触れた土の器は砕く。木の器はどれも水で洗う。'),
('JPN', '利未记', 3, 15, 13, '漏出を病む者が漏出からきよめられたときは、自分のきよめのために七日を数え、自分の衣服を洗い、自分のからだに新鮮な水を浴びる。こうしてその人はきよくなる。'),
('JPN', '利未记', 3, 15, 14, '八日目に彼は自分のために山鳩二羽か家鳩のひな二羽を取り、主の前、会見の天幕の入り口に行って、それらを祭司に渡す。'),
('JPN', '利未记', 3, 15, 15, '祭司はそれらのうち、一羽を罪のきよめのささげ物とし、もう一羽を全焼のささげ物とする。こうして祭司はその人のために、主の前で漏出物のゆえに宥めを行う。'),
('JPN', '利未记', 3, 15, 16, '男が精を漏らしたときは全身に水を浴びる。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 17, '精が付いた衣服と皮はすべて、水で洗う。それは夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 18, '男が女と寝て交わったなら、二人はともに水を浴びる。彼らは夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 19, '女に漏出があり、漏出物がからだからの血であるなら、彼女は七日間、月のさわりの状態になる。だれでも彼女に触れる者は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 20, '彼女の月のさわりの時に使った寝床は全体が汚れる。また、彼女が座った物もすべて汚れる。'),
('JPN', '利未记', 3, 15, 21, '彼女の床に触れた者はだれでも自分の衣服を洗い、水を浴びなければならない。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 22, 'また、何であれ、彼女が座った物に触れた人はだれでも自分の衣服を洗い、水を浴びる。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 23, '彼女の床であれ座った物であれ、それに触れたなら、その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 24, 'また、もしも男が彼女と寝るようなことがあるなら、彼女の月のさわりが移って、その人は七日間汚れる。彼が寝る床も全体が汚れる。'),
('JPN', '利未记', 3, 15, 25, '女に、月のさわりの期間ではないのに、長い日数にわたって血の漏出があるか、あるいは月のさわりの期間が過ぎても漏出があるなら、その汚れた漏出がある間中、彼女は月のさわりの期間と同じように汚れる。'),
('JPN', '利未记', 3, 15, 26, 'その漏出の間は、彼女の寝た床はすべて、月のさわりの時の床と同じようになる。彼女が座った物はすべて、月のさわりの間の汚れのように汚れる。'),
('JPN', '利未记', 3, 15, 27, 'だれでも、これらの物に触れた人は汚れる。その人は衣服を洗い、水を浴びる。その人は夕方まで汚れる。'),
('JPN', '利未记', 3, 15, 28, '女が漏出からきよくなったら七日を数え、その後、彼女はきよくなる。'),
('JPN', '利未记', 3, 15, 29, '八日目に彼女は自分のために山鳩二羽か家鳩のひな二羽を取り、それらを会見の天幕の入り口の祭司のところに持って行く。'),
('JPN', '利未记', 3, 15, 30, '祭司は一羽を罪のきよめのささげ物とし、もう一羽を全焼のささげ物とする。祭司は彼女のために、主の前で汚れた漏出のゆえに宥めを行う。'),
('JPN', '利未记', 3, 15, 31, 'あなたがたは、イスラエルの子らをその汚れから離れさせなさい。彼らが、彼らのただ中にあるわたしの幕屋を汚し、自分たちの汚れで死ぬことのないようにするためである。」')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '利未记', 3, 15, 32, '以上が、漏出のある者、精を漏らして汚れた者、'),
('JPN', '利未记', 3, 15, 33, '月のさわりで不浄な女、男か女で漏出のある者、また汚れている女と寝た男についてのおしえである。'),
('JPN', '利未记', 3, 16, 1, 'アロンの二人の息子の死後、すなわち、彼らが主の前に近づいて死んだ後、主はモーセに告げられた。'),
('JPN', '利未记', 3, 16, 2, '主はモーセに言われた。「あなたの兄アロンに告げよ。垂れ幕の内側の聖所、すなわち箱の上の『宥めの蓋』の前に、時をわきまえずに入ることがないようにせよ。死ぬことのないようにするためである。『宥めの蓋』の上で、わたしは雲の中に現れるからである。'),
('JPN', '利未记', 3, 16, 3, 'アロンは次のようにして聖所に入る。罪のきよめのささげ物として若い雄牛、また全焼のささげ物として雄羊を携え、'),
('JPN', '利未记', 3, 16, 4, '聖なる亜麻布の長服を着て、亜麻布のももひきを履き、亜麻布の飾り帯を締め、亜麻布のかぶり物をかぶる。これらが聖なる装束であり、彼はからだに水を浴びて、それらを着ける。'),
('JPN', '利未记', 3, 16, 5, '彼はまた、イスラエルの会衆から、雄やぎ二匹を罪のきよめのささげ物として、雄羊一匹を全焼のささげ物として取る。'),
('JPN', '利未记', 3, 16, 6, 'アロンは、自分のための罪のきよめのささげ物である雄牛を献げ、自分と自分の家族のために宥めを行う。'),
('JPN', '利未记', 3, 16, 7, '雄やぎ二匹を取り、それを主の前、会見の天幕の入り口に立たせ、'),
('JPN', '利未记', 3, 16, 8, '雄やぎ二匹のためにアロンがくじを引く。一つのくじは主のため、一つのくじはアザゼルのためである。'),
('JPN', '利未记', 3, 16, 9, 'アロンは主のためのくじに当たった雄やぎを連れて来て、それを罪のきよめのささげ物とする。'),
('JPN', '利未记', 3, 16, 10, 'アザゼルのためのくじに当たった雄やぎは、主の前に生きたままで立たせる。これは、それの上で宥めを行い、荒野のアザゼルのもとへ追いやるためである。'),
('JPN', '利未记', 3, 16, 11, 'アロンは自分のために、罪のきよめのささげ物である雄牛を献げ、自分と家族のために宥めを行う。彼は自分のために、罪のきよめのささげ物である雄牛を屠る。'),
('JPN', '利未记', 3, 16, 12, '彼は主の前の祭壇から炭火を火皿いっぱいに、また、粉にした香り高い香を両手いっぱいに取り、垂れ幕の内側に持って入る。'),
('JPN', '利未记', 3, 16, 13, 'その香を主の前の火にくべ、香から出る雲が、あかしの箱の上の『宥めの蓋』をおおうようにする。彼が死ぬことのないようにするためである。'),
('JPN', '利未记', 3, 16, 14, 'それから、雄牛の血を取り、指で『宥めの蓋』の東側に振りまき、また、指で七度その血を『宥めの蓋』の前に振りまく。'),
('JPN', '利未记', 3, 16, 15, 'アロンは民のために、罪のきよめのささげ物である雄やぎを屠り、その血を垂れ幕の内側に持って入り、この血を、先の雄牛の血にしたように、『宥めの蓋』の上と『宥めの蓋』の前にかける。'),
('JPN', '利未记', 3, 16, 16, '彼はイスラエルの子らの汚れと背き、すなわちそのすべての罪を除いて、聖所のための宥めを行う。彼らの汚れのただ中に、彼らとともにある会見の天幕にも、このようにする。'),
('JPN', '利未记', 3, 16, 17, '彼が宥めを行うために聖所に入って、再び出て来るまで、だれも会見の天幕の中にいてはならない。彼は自分と自分の家族、それにイスラエルの集会全体のために宥めを行う。'),
('JPN', '利未记', 3, 16, 18, 'そして、主の前にある祭壇のところに出て行き、そのために宥めを行う。すなわち、彼はその雄牛の血と雄やぎの血を取り、それを祭壇の四隅の角に塗る。'),
('JPN', '利未记', 3, 16, 19, 'また、その残りの血を、その祭壇の上に指で七度振りまく。こうして彼はイスラエルの子らの汚れからそれをきよめ、聖別する。'),
('JPN', '利未记', 3, 16, 20, '彼は、聖所と会見の天幕と祭壇のための宥めを行い終えたら、先の生きている雄やぎを連れて来る。'),
('JPN', '利未记', 3, 16, 21, 'アロンは生きている雄やぎの頭に両手を置き、それの上で、イスラエルの子らのすべての咎とすべての背き、すなわちすべての罪を告白する。これらをその雄やぎの頭の上に載せ、係りの者の手でこれを荒野に追いやる。'),
('JPN', '利未记', 3, 16, 22, '雄やぎは彼らのすべての咎を負って、不毛の地へ行く。その人は雄やぎを荒野に追いやる。'),
('JPN', '利未记', 3, 16, 23, 'アロンは会見の天幕に戻り、聖所に入ったときに着けていた亜麻布の装束を脱いで、そこに残しておき、'),
('JPN', '利未记', 3, 16, 24, '聖なる所でからだに水を浴び、自分の衣服を着て外に出て、自分の全焼のささげ物と民の全焼のささげ物を献げ、自分のため、民のために宥めを行う。'),
('JPN', '利未记', 3, 16, 25, '罪のきよめのささげ物の脂肪は、祭壇の上で焼いて煙にする。'),
('JPN', '利未记', 3, 16, 26, 'アザゼルの雄やぎを追いやった者は衣服を洗い、からだに水を浴びる。その後で、宿営に入ることができる。'),
('JPN', '利未记', 3, 16, 27, '罪のきよめのささげ物の雄牛と、罪のきよめのささげ物の雄やぎで、その血が宥めのために聖所に持って行かれたものは、宿営の外に運び出し、皮と肉と汚物を火で焼く。'),
('JPN', '利未记', 3, 16, 28, 'これを焼く者は自分の衣服を洗い、からだに水を浴びる。その後で、宿営に入ることができる。'),
('JPN', '利未记', 3, 16, 29, '次のことは、あなたがたにとって永遠の掟となる。第七の月の十日には、あなたがたは自らを戒めなければならない。この国に生まれた者も、あなたがたの中に寄留している者も、いかなる仕事もしてはならない。'),
('JPN', '利未记', 3, 16, 30, 'この日は、あなたがたをきよめようと、あなたがたのために宥めが行われるからである。あなたがたは主の前ですべての罪からきよくなる。'),
('JPN', '利未记', 3, 16, 31, 'これがあなたがたの全き休みのための安息日であり、あなたがたは自らを戒める。これは永遠の掟である。'),
('JPN', '利未记', 3, 16, 32, '油注がれ、父に代わって祭司として仕えるために任命された祭司が、宥めを行う。彼は亜麻布の装束、すなわち聖なる装束を着ける。'),
('JPN', '利未记', 3, 16, 33, '彼は至聖所のための宥めを行い、また会見の天幕と祭壇のための宥めを行う。彼はまた、祭司たちと集会のすべての民のための宥めを行う。'),
('JPN', '利未记', 3, 16, 34, '以上のことは、あなたがたにとって永遠の掟となる。これは年に一度イスラエルの子らのために行われる、彼らのすべての罪を除く宥めである。」モーセは主が命じられたとおりに行った。'),
('JPN', '利未记', 3, 17, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 17, 2, '「アロンとその子ら、またすべてのイスラエルの子らに告げよ。主が命じられたことは次のとおりである。'),
('JPN', '利未记', 3, 17, 3, 'イスラエルの家の者のだれかが、牛か子羊かやぎを宿営の中で屠るか、あるいは宿営の外で屠るかして、'),
('JPN', '利未记', 3, 17, 4, '主の幕屋の前で主へのささげ物として献げようと、会見の天幕の入り口に持って来ることがなかったなら、血の責任はその人に帰せられる。彼は血を流した。その人は自分の民の間から断ち切られる。'),
('JPN', '利未记', 3, 17, 5, 'これは、イスラエルの子らが、野外で屠っていたいけにえを持って来るようにするためであり、主のところに、会見の天幕の入り口の祭司のところに持って来て、それらを交わりのいけにえとして主に献げるためである。'),
('JPN', '利未记', 3, 17, 6, 'また、祭司がその血を会見の天幕の入り口にある主の祭壇に振りかけ、その脂肪を主への芳ばしい香りとして焼いて煙にするためであり、'),
('JPN', '利未记', 3, 17, 7, 'また、彼らが慕って淫行をしていた雄やぎの偶像に、もういけにえを献げなくするためである。これは彼らにとって代々守るべき永遠の掟となる。'),
('JPN', '利未记', 3, 17, 8, 'また、彼らに言え。だれでも、イスラエルの家の者、あるいは彼らの間に寄留している者が、全焼のささげ物か、いけにえを献げるとき、'),
('JPN', '利未记', 3, 17, 9, 'それを主に献げようと会見の天幕の入り口に持って来ないなら、そのような者は自分の民から断ち切られる。'),
('JPN', '利未记', 3, 17, 10, 'イスラエルの家の者、あるいは彼らの間に寄留している者のだれであっても、どんな血でも食べるなら、わたしはその血を食べた者に敵対してわたしの顔を向け、その人をその民の間から断ち切る。'),
('JPN', '利未记', 3, 17, 11, '実に、肉のいのちは血の中にある。わたしは、祭壇の上であなたがたのたましいのために宥めを行うよう、これをあなたがたに与えた。いのちとして宥めを行うのは血である。'),
('JPN', '利未记', 3, 17, 12, 'それゆえ、わたしはイスラエルの子らに言う。あなたがたはだれも血を食べてはならない。あなたがたの間に寄留している者も血を食べてはならない。'),
('JPN', '利未记', 3, 17, 13, 'イスラエルの子らや彼らの間に寄留している者のだれでも、食べることができる獣や鳥を狩りで捕らえた人は、その血を注ぎ出し、土でおおう。'),
('JPN', '利未记', 3, 17, 14, 'すべての肉のいのちは、その血がいのちそのものである。それゆえ、わたしはイスラエルの子らに言ったのである。『あなたがたは、いかなる肉の血も食べてはならない。すべての肉のいのちは、その血そのものであるからだ。それを食べる者はだれでも断ち切られる』と。'),
('JPN', '利未记', 3, 17, 15, 'だれでも、死んだ動物や野獣にかみ裂かれたものを食べるなら、この国に生まれた者であれ寄留者であれ、自分の衣服を洗い、水を浴びなければならない。その人は夕方まで汚れる。それから彼はきよくなる。'),
('JPN', '利未记', 3, 17, 16, 'もし自分の衣服を洗わず、身に水を浴びないなら、その人は自分の咎を負う。」'),
('JPN', '利未记', 3, 18, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 18, 2, '「イスラエルの子らに告げよ。わたしはあなたがたの神、主である。'),
('JPN', '利未记', 3, 18, 3, 'あなたがたは、自分たちが住んでいたエジプトの地の風習をまねてはならない。また、わたしがあなたがたを導き入れようとしているカナンの地の風習をまねてはならない。彼らの掟に従って歩んではならない。'),
('JPN', '利未记', 3, 18, 4, 'わたしの定めを行い、わたしの掟を守り、それらの中にあって歩まなければならない。わたしがあなたがたの神、主である。'),
('JPN', '利未记', 3, 18, 5, 'あなたがたは、わたしの掟とわたしの定めを守りなさい。人がそれらを行うなら、それらによって生きる。わたしは主である。'),
('JPN', '利未记', 3, 18, 6, 'だれも、自分の肉親の者に近づき、相手の裸をあらわにして交わってはならない。わたしは主である。'),
('JPN', '利未记', 3, 18, 7, '父の裸をあらわにすること、すなわちあなたの母の裸をあらわにすることをしてはならない。彼女はあなたの母である。彼女の裸をあらわにしてはならない。'),
('JPN', '利未记', 3, 18, 8, 'あなたの父の妻の裸をあらわにしてはならない。それは、あなたの父の裸をあらわにすることである。'),
('JPN', '利未记', 3, 18, 9, 'あなたの姉妹は、あなたの父の娘でも母の娘でも、あるいは、家で生まれた女でも外で生まれた女でも、その裸をあらわにしてはならない。'),
('JPN', '利未记', 3, 18, 10, 'あなたの息子の娘、あるいはあなたの娘の娘の裸をあらわにしてはならない。彼女たちの裸は、あなた自身の裸だからである。'),
('JPN', '利未记', 3, 18, 11, 'あなたの父の妻があなたの父に産んだ娘は、あなたの姉妹なのだから、彼女の裸をあらわにしてはならない。'),
('JPN', '利未记', 3, 18, 12, 'あなたの父の姉妹の裸をあらわにしてはならない。その人はあなたの父の肉親である。'),
('JPN', '利未记', 3, 18, 13, 'あなたの母の姉妹の裸をあらわにしてはならない。その人はあなたの母の肉親だからである。'),
('JPN', '利未记', 3, 18, 14, 'あなたの父の兄弟の裸をあらわにしてはならない。その妻に近づいてはならない。その人はあなたのおばである。'),
('JPN', '利未记', 3, 18, 15, 'あなたの嫁の裸をあらわにしてはならない。その人はあなたの息子の妻である。彼女の裸をあらわにしてはならない。'),
('JPN', '利未记', 3, 18, 16, 'あなたの兄弟の妻の裸をあらわにしてはならない。彼女の裸は、あなたの兄弟自身の裸である。'),
('JPN', '利未记', 3, 18, 17, 'あなたは女とその娘の裸をあらわにしてはならない。また、その女の息子の娘、あるいはその娘の娘を妻として、その裸をあらわにしてはならない。彼女たちはあなたの肉親であり、これは淫らな行為である。'),
('JPN', '利未记', 3, 18, 18, 'あなたは、妻が生きている間にその姉妹を妻とし、その裸をあらわにして妻を苦しめてはならない。'),
('JPN', '利未记', 3, 18, 19, 'あなたは、月のさわりで汚れている女に近づいて、彼女の裸をあらわにしてはならない。'),
('JPN', '利未记', 3, 18, 20, 'また、自分の同胞の妻と寝て交わり、彼女によって自分を汚してはならない。'),
('JPN', '利未记', 3, 18, 21, 'また、自分の子どもを一人でも、火の中を通らせてモレクに渡してはならない。あなたの神の名を汚してはならない。わたしは主である。'),
('JPN', '利未记', 3, 18, 22, 'あなたは、女と寝るように男と寝てはならない。それは忌み嫌うべきことである。'),
('JPN', '利未记', 3, 18, 23, '動物と寝て、動物によって身を汚してはならない。女も、動物の前に立って、これと交わってはならない。それは道ならぬことである。'),
('JPN', '利未记', 3, 18, 24, 'あなたがたは、これらの何によっても身を汚してはならない。わたしがあなたがたの前から追い出そうとしている異邦の民は、これらのすべてのことによって汚れていて、'),
('JPN', '利未记', 3, 18, 25, 'その地も汚れている。それで、わたしはその地をその咎のゆえに罰し、その地はそこに住む者を吐き出す。'),
('JPN', '利未记', 3, 18, 26, 'あなたがたは、わたしの掟とわたしの定めを守らなければならない。この国に生まれた者も、あなたがたの間に寄留している者も、これらの忌み嫌うべきことを一つも行わないようにするためである。'),
('JPN', '利未记', 3, 18, 27, 'それは、あなたがたより前にいたその地の人々が、これらすべての忌み嫌うべきことを行い、その地が汚れたからであり、'),
('JPN', '利未记', 3, 18, 28, 'あなたがたがその地を汚し、その地が、あなたがたより前にいた異邦の民を吐き出したように、あなたがたを吐き出すことのないようにするためである。'),
('JPN', '利未记', 3, 18, 29, 'だれであれ、これらの忌み嫌うべきことの一つでも行う者、それを行う者は自分の民の間から断ち切られる。'),
('JPN', '利未记', 3, 18, 30, 'あなたがたは、わたしへの務めを果たし、あなたがたより前に行われていた忌み嫌うべき掟を決して行わないように、またそれによって身を汚さないようにしなさい。わたしはあなたがたの神、主である。」'),
('JPN', '利未记', 3, 19, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 19, 2, '「イスラエルの全会衆に告げよ。あなたがたは聖なる者でなければならない。あなたがたの神、主であるわたしが聖だからである。'),
('JPN', '利未记', 3, 19, 3, 'それぞれ、自分の母と父を恐れなければならない。また、わたしの安息日を守らなければならない。わたしはあなたがたの神、主である。'),
('JPN', '利未记', 3, 19, 4, 'あなたがたは偶像の神々に心を移してはならない。また、自分たちのために鋳物の神々を造ってはならない。わたしはあなたがたの神、主である。'),
('JPN', '利未记', 3, 19, 5, 'あなたがたが交わりのいけにえを主に献げるときは、自分が受け入れられるように献げなければならない。'),
('JPN', '利未记', 3, 19, 6, 'それを献げた日と、その翌日に、それを食べなければならない。三日目まで残ったものは火で焼かなければならない。'),
('JPN', '利未记', 3, 19, 7, 'もしも、三日目にそれを食べるようなことがあれば、それは不浄なものとなり、受け入れられない。'),
('JPN', '利未记', 3, 19, 8, 'それを食べる者は咎を負う。主の聖なるものを冒したからである。その人は自分の民から断ち切られる。'),
('JPN', '利未记', 3, 19, 9, 'あなたがたが自分の土地の収穫を刈り入れるときは、畑の隅々まで刈り尽くしてはならない。収穫した後の落ち穂を拾い集めてはならない。'),
('JPN', '利未记', 3, 19, 10, 'また、あなたのぶどう畑の実を取り尽くしてはならない。あなたのぶどう畑に落ちた実を拾い集めてはならない。それらを貧しい人と寄留者のために残しておかなければならない。わたしはあなたがたの神、主である。'),
('JPN', '利未记', 3, 19, 11, '盗んではならない。欺いてはならない。互いに偽ってはならない。'),
('JPN', '利未记', 3, 19, 12, 'あなたがたは、わたしの名によって偽って誓ってはならない。そのようにして、あなたの神の名を汚してはならない。わたしは主である。'),
('JPN', '利未记', 3, 19, 13, 'あなたの隣人を虐げてはならない。かすめてはならない。日雇い人の賃金を朝まで自分のもとにとどめておいてはならない。'),
('JPN', '利未记', 3, 19, 14, 'あなたは耳の聞こえない人を軽んじてはならない。目の見えない人の前につまずく物を置いてはならない。あなたの神を恐れよ。わたしは主である。'),
('JPN', '利未记', 3, 19, 15, '不正な裁判をしてはならない。弱い者をひいきしたり強い者にへつらったりしてはならない。あなたの同胞を正しくさばかなければならない。'),
('JPN', '利未记', 3, 19, 16, 'あなたは、民の中で人を中傷して回り、隣人のいのちを危険にさらすことがあってはならない。わたしは主である。'),
('JPN', '利未记', 3, 19, 17, '心の中で自分の兄弟を憎んではならない。同胞をよく戒めなければならない。そうすれば、彼のゆえに罪責を負うことはない。'),
('JPN', '利未记', 3, 19, 18, 'あなたは復讐してはならない。あなたの民の人々に恨みを抱いてはならない。あなたの隣人を自分自身のように愛しなさい。わたしは主である。'),
('JPN', '利未记', 3, 19, 19, 'あなたがたは、わたしの掟を守らなければならない。あなたの家畜を種類の異なった家畜と交わらせてはならない。あなたの畑に二種類の種を蒔いてはならない。また、あなたは二種類の糸で織った布地の衣服を身に着けてはならない。'),
('JPN', '利未记', 3, 19, 20, '男が女と寝て交わり、その女が別の男に決まっている女奴隷であって、まだ贖われていないか、あるいは自由を与えられていない場合は考慮する。女が自由の身でないので、彼らは殺されない。'),
('JPN', '利未记', 3, 19, 21, 'その男は、主への償いとして、代償のささげ物の雄羊を会見の天幕の入り口に持って行く。'),
('JPN', '利未记', 3, 19, 22, '祭司は彼が犯した罪のために、その代償のささげ物の雄羊によって、主の前で彼のために宥めを行う。彼はその犯した罪を赦される。'),
('JPN', '利未记', 3, 19, 23, 'あなたがたが、かの地に入り、どんな果樹を植えても、その実はまだ禁断のものと見なさなければならない。三年の間、それはあなたがたにとって禁断のものであり、食べてはならない。'),
('JPN', '利未记', 3, 19, 24, '四年目に、その実はすべて聖なるものとなり、主への賛美のささげ物となる。'),
('JPN', '利未记', 3, 19, 25, '五年目に、あなたがたはその実を食べることができる。あなたがたの収穫を増すためである。わたしはあなたがたの神、主である。'),
('JPN', '利未记', 3, 19, 26, 'あなたがたは何でも血が付いたままで食べてはならない。まじないをしてはならない。占いをしてはならない。'),
('JPN', '利未记', 3, 19, 27, 'あなたがたの頭のもみあげを剃り落としてはならない。ひげの両隅を損なってはならない。'),
('JPN', '利未记', 3, 19, 28, 'あなたがたは、死人のために自分のからだに傷をつけてはならない。また自分の身に入れ墨をしてはならない。わたしは主である。'),
('JPN', '利未记', 3, 19, 29, 'あなたの娘に淫行をさせて汚してはならない。地が淫行に走り、地が淫らな行為で満ちることのないようにするためである。'),
('JPN', '利未记', 3, 19, 30, 'あなたがたはわたしの安息日を守り、わたしの聖所を恐れなければならない。わたしは主である。'),
('JPN', '利未记', 3, 19, 31, 'あなたがたは霊媒や口寄せを頼りにしてはならない。彼らに尋ね、彼らによって汚されてはならない。わたしはあなたがたの神、主である。'),
('JPN', '利未记', 3, 19, 32, 'あなたは白髪の老人の前では起立し、老人を敬い、またあなたの神を恐れなければならない。わたしは主である。'),
('JPN', '利未记', 3, 19, 33, 'あなたがたの国、あなたのところに寄留者が滞在しているなら、その人を虐げてはならない。'),
('JPN', '利未记', 3, 19, 34, 'あなたがたとともにいる寄留者は、あなたがたにとって、自分たちの国で生まれた一人のようにしなければならない。あなたはその人を自分自身のように愛さなければならない。あなたがたも、かつてエジプトの地では寄留の民だったからである。わたしはあなたがたの神、主である。'),
('JPN', '利未记', 3, 19, 35, 'あなたがたは、さばきにおいて不正をしてはならない。物差しにおいても、秤においても、分量においても。'),
('JPN', '利未记', 3, 19, 36, '正しい天秤、正しい重り石、正しい升、正しい容器を使わなければならない。わたしは、あなたがたをエジプトの地から導き出した、あなたがたの神、主である。'),
('JPN', '利未记', 3, 19, 37, 'あなたがたは、わたしのすべての掟とすべての定めを守り、それらを行いなさい。わたしは主である。」'),
('JPN', '利未记', 3, 20, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 20, 2, '「あなたはイスラエルの子らに言え。イスラエルの子ら、あるいはイスラエルに寄留している者のうちで、自分の子どもを取ってモレクに与える者は、だれであれ必ず殺されなければならない。民衆がその者を石で打ち殺さなければならない。'),
('JPN', '利未记', 3, 20, 3, 'わたしはその人に敵対してわたしの顔を向け、彼をその民の間から断ち切る。彼がモレクに自分の子どもを与え、そのためわたしの聖所を汚し、わたしの聖なる名を汚したからである。'),
('JPN', '利未记', 3, 20, 4, 'もしも、人がモレクに自分の子どもを与えるときに、民衆がそれを見て見ぬふりをし、彼を殺さないことがあれば、'),
('JPN', '利未记', 3, 20, 5, 'わたし自身が彼とその家族に顔を向け、彼と、彼に倣いモレクを慕って淫行を行う淫らな者をみな、その民の間から断ち切る。'),
('JPN', '利未记', 3, 20, 6, '霊媒や口寄せのところに赴き、彼らを慕って淫行を行う者があれば、わたしはその人に敵対してわたしの顔を向け、彼をその民の間から断ち切る。'),
('JPN', '利未记', 3, 20, 7, 'あなたがたは自分の身を聖別し、聖なる者とならなければならない。わたしがあなたがたの神、主であるからだ。'),
('JPN', '利未记', 3, 20, 8, 'あなたがたはわたしの掟を守り、それを行わなければならない。わたしはあなたがたを聖なる者とする主である。'),
('JPN', '利未记', 3, 20, 9, 'だれでも自分の父や母をののしる者は、必ず殺されなければならない。その人は自分の父あるいは母をののしったのだから、その血の責任は彼にある。'),
('JPN', '利未记', 3, 20, 10, '人が他人の妻と姦淫したなら、すなわち自分の隣人の妻と姦淫したなら、その姦淫した男も女も必ず殺されなければならない。'),
('JPN', '利未记', 3, 20, 11, '人がもし父の妻と寝たなら、父の裸をあらわにしたのである。二人とも必ず殺されなければならない。その血の責任は彼らにある。'),
('JPN', '利未记', 3, 20, 12, '人がもし息子の妻と寝たなら、その二人は必ず殺されなければならない。その人たちは道ならぬことをした。その血の責任は彼らにある。'),
('JPN', '利未记', 3, 20, 13, '男がもし女と寝るように男と寝たなら、二人は忌み嫌うべきことをしたのである。彼らは必ず殺されなければならない。その血の責任は彼らにある。'),
('JPN', '利未记', 3, 20, 14, '人がもし女をその母とともに妻としたなら、それは淫らなことである。その人もその女たちもともに、火で焼かれなければならない。あなたがたの間で淫らな行為がないようにするためである。'),
('JPN', '利未记', 3, 20, 15, '人がもし動物と寝るなら、その人は必ず殺されなければならない。その動物も殺さなければならない。'),
('JPN', '利未记', 3, 20, 16, '女がもし、いかなる動物にであれ近づいてそれとともに交わるなら、あなたはその女と動物を殺さなければならない。その両者は必ず殺されなければならない。その血の責任はその両者にある。'),
('JPN', '利未记', 3, 20, 17, '人がもし自分の姉妹、すなわち父の娘か母の娘を妻とし、自分の姉妹の裸を見て、女もその人の裸を見たなら、これは恥ずべきことである。同族の目の前でその人たちは断ち切られる。その人は自分の姉妹の裸をあらわにしたのである。その咎を負わなければならない。'),
('JPN', '利未记', 3, 20, 18, '人がもし月のさわりのある女と寝て、彼女の裸をあらわにしたなら、男は女の泉を暴き、女は自分の血の泉をあらわにしたのである。二人は自分の民の間から断ち切られる。'),
('JPN', '利未记', 3, 20, 19, '母の姉妹や父の姉妹の裸をあらわにしてはならない。これは自分の肉親を裸にすることである。彼らは咎を負わなければならない。'),
('JPN', '利未记', 3, 20, 20, '人がもし自分のおばと寝たなら、おじの裸をあらわにしたのである。その人たちはその罪責を負わなければならない。彼らは子を残さずに死ぬ。'),
('JPN', '利未记', 3, 20, 21, '人がもし、自分の兄弟の妻をめとるなら、それは忌まわしいことだ。彼はその兄弟の裸をあらわにしたのである。彼らは子のいない者となる。'),
('JPN', '利未记', 3, 20, 22, 'あなたがたが、わたしのすべての掟とすべての定めを守り、これを行うなら、わたしがあなたがたを住まわせようと導き入れるその地は、あなたがたを吐き出さない。'),
('JPN', '利未记', 3, 20, 23, 'あなたがたは、わたしがあなたがたの前から追い出そうとしている異邦の民の掟に従って歩んではならない。彼らがこれらすべてのことを行ったので、わたしは彼らを甚だしく嫌った。'),
('JPN', '利未记', 3, 20, 24, 'それゆえ、わたしはあなたがたに言った。『あなたがたは彼らの土地を所有するようになる。わたしが乳と蜜の流れる地をあなたがたに与えて所有させる。わたしは、あなたがたを諸民族の中から選り分けた、あなたがたの神、主である。'),
('JPN', '利未记', 3, 20, 25, 'あなたがたは、きよい動物と汚れた動物、また汚れた鳥ときよい鳥をより分けなければならない。わたしがあなたがたのために、汚れているとして区別した動物や鳥や地面を這うすべてのものによって、あなたがた自身を忌むべきものとしてはならない。'),
('JPN', '利未记', 3, 20, 26, 'あなたがたは、わたしにとって聖でなければならない。主であるわたしが聖だからである。わたしは、あなたがたをわたしのものにしようと、諸民族の中から選り分けたのである。』'),
('JPN', '利未记', 3, 20, 27, '男でも女でも、彼らの間に霊媒や口寄せがいるなら、必ず殺されなければならない。彼らは石で打ち殺されなければならない。その血の責任は彼らにある。」'),
('JPN', '利未记', 3, 21, 1, '主はモーセに言われた。「アロンの子である祭司たちに言え。彼らに言え。親族のうちの死人によって自分の身を汚してはならない。'),
('JPN', '利未记', 3, 21, 2, 'ただし近親の者、すなわち、母や父、息子や娘、兄弟の場合は例外である。'),
('JPN', '利未记', 3, 21, 3, 'また近親の、結婚したことがない処女である姉妹の場合は、彼女によって自分の身を汚してもよい。'),
('JPN', '利未记', 3, 21, 4, '一族の中で主人が自分の身を汚し、自分を冒瀆することになってはならない。'),
('JPN', '利未记', 3, 21, 5, '頭を剃ってはならない。ひげの両隅を切り落としてもいけない。からだにいかなる傷もつけてはならない。'),
('JPN', '利未记', 3, 21, 6, '彼らは自分の神に対して聖でなければならない。また自分の神の名を汚してはならない。彼らは、主への食物のささげ物、すなわち彼らの神のパンを献げるからである。彼らは聖でなければならない。'),
('JPN', '利未记', 3, 21, 7, '彼らは淫行で汚れている女を妻としてはならない。また夫から離縁された女を妻としてはならない。祭司は神に対して聖だからである。'),
('JPN', '利未记', 3, 21, 8, 'あなたは彼を聖別しなければならない。彼はあなたの神のパンを献げるからである。彼はあなたにとって聖でなければならない。あなたがたを聖別する主であるわたしが聖だからである。'),
('JPN', '利未记', 3, 21, 9, '祭司の娘が淫行で身を汚すなら、その父を汚すことになる。その女は火で焼かれなければならない。'),
('JPN', '利未记', 3, 21, 10, '兄弟たちのうち大祭司で、頭に注ぎの油が注がれ、任職されて装束を着けている者は、その髪の毛を乱したり、その装束を引き裂いたりしてはならない。'),
('JPN', '利未记', 3, 21, 11, 'いかなる死人のところにも入って行ってはならない。自分の父のためにも母のためにも自分の身を汚してはならない。'),
('JPN', '利未记', 3, 21, 12, '聖所から出て行って神の聖所を冒してはならない。神の注ぎの油による記章を身に着けているからである。わたしは主である。'),
('JPN', '利未记', 3, 21, 13, '彼は処女である女を妻としなければならない。'),
('JPN', '利未记', 3, 21, 14, 'やもめ、離縁された女、あるいは淫行で汚れている女、これらを妻としてはならない。彼はただ、自分の民の中から処女を妻としなければならない。'),
('JPN', '利未记', 3, 21, 15, '一族のうちで子孫を汚すことのないようにするためである。わたしは彼を聖別する主だからである。」'),
('JPN', '利未记', 3, 21, 16, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 21, 17, '「アロンに告げよ。あなたの代々の子孫のうち、身に欠陥のある者はだれも、神のパンを献げるために近づいてはならない。'),
('JPN', '利未记', 3, 21, 18, 'だれでも、身に欠陥のある者は近づいてはならない。目の見えない者、足の萎えた者、あるいは手足が短すぎたり長すぎたりしている者、'),
('JPN', '利未记', 3, 21, 19, '足や手の折れた者、'),
('JPN', '利未记', 3, 21, 20, '背の曲がった者、背のきわめて低い者、目に濁りのある者、湿疹のある者、かさぶたのある者、睾丸のつぶれた者などである。'),
('JPN', '利未记', 3, 21, 21, '祭司アロンの子孫のうち、身に欠陥のある者はだれも、主への食物のささげ物を献げようと近寄ってはならない。彼の身には欠陥があるから、神のパンを献げるために近寄ってはならない。'),
('JPN', '利未记', 3, 21, 22, 'しかし神のパンは、最も聖なるものであっても、聖なるものであっても食べることが許される。'),
('JPN', '利未记', 3, 21, 23, 'ただし、垂れ幕のところに行ってはならない。祭壇に近寄ってはならない。身に欠陥があるからである。彼はわたしの聖所を汚してはならない。わたしがそれらを聖別する主だからである。」'),
('JPN', '利未记', 3, 21, 24, 'モーセはこのことを、アロンとその子らとすべてのイスラエルの子らに告げた。'),
('JPN', '利未记', 3, 22, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 22, 2, '「アロンとその子らに告げよ。イスラエルの子らの聖なるものは慎重に扱え。わたしの聖なる名を汚してはならない。それは彼らがわたしのために聖別したものである。わたしは主である。'),
('JPN', '利未记', 3, 22, 3, '彼らに言え。代々にわたり、あなたがたの子孫のだれかが、イスラエルの子らが主に対して聖別した聖なるものに、汚れたままで近づくなら、その人はわたしの前から断ち切られる。わたしは主である。'),
('JPN', '利未记', 3, 22, 4, 'アロンの子孫のうち、ツァラアトに冒された者、または漏出のある者はみな、きよくなるまで聖なるものを食べてはならない。また汚れている者、精を漏らす者、'),
('JPN', '利未记', 3, 22, 5, 'あるいはすべて人を汚す群がるものに触れる者、または、いかなる汚れであれ人を汚れさせる人間に触れる者もそうである。'),
('JPN', '利未记', 3, 22, 6, 'これに触れた者は夕方まで汚れる。その人は、からだに水を浴びずに聖なるものを食べてはならない。'),
('JPN', '利未记', 3, 22, 7, 'しかし、日が沈めば彼はきよくなり、その後で、聖なるものを食べることが許される。それは彼の食物だからである。'),
('JPN', '利未记', 3, 22, 8, '死んだ動物や野獣にかみ裂かれたものを食べて汚れてはならない。わたしは主である。'),
('JPN', '利未记', 3, 22, 9, '彼らがわたしへの務めを果たすなら、彼らが聖なるものを冒し、そのために罪責を負って死ぬようなことはない。わたしは彼らを聖別する主である。'),
('JPN', '利未记', 3, 22, 10, '一般の者はだれも、聖なるものを食べてはならない。祭司の居留者や雇い人は、聖なるものを食べてはならない。'),
('JPN', '利未记', 3, 22, 11, 'しかし、祭司に金で買われた者はこれを食べることが許される。また、その家で生まれた者も祭司のパンを食べることが許される。'),
('JPN', '利未记', 3, 22, 12, '祭司の娘は、一般の者と結婚したなら、聖なる奉納物を食べてはならない。'),
('JPN', '利未记', 3, 22, 13, '祭司の娘が、やもめあるいは離縁された者となり、子もなく、娘のときのように再びその父の家に戻っているなら、父の食物を食べることが許される。しかし、一般の者はだれもそれを食べてはならない。'),
('JPN', '利未记', 3, 22, 14, 'だれかが誤って聖なるものを食べるなら、それにその五分の一を加えて、その聖なるものを祭司に渡す。'),
('JPN', '利未记', 3, 22, 15, 'イスラエルの子らに、主に献げる聖なるものを冒し、'),
('JPN', '利未记', 3, 22, 16, '聖なるものを食べて、その罪過の咎を負わせてはならない。わたしは彼らを聖別する主だからである。」'),
('JPN', '利未记', 3, 22, 17, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 22, 18, '「アロンとその子ら、またすべてのイスラエルの子らに告げよ。だれでも、イスラエルの家の者、またはイスラエルにいる寄留者がささげ物を献げ、誓願のささげ物あるいは進んで献げるものとして、全焼のささげ物を主に献げる場合、'),
('JPN', '利未记', 3, 22, 19, 'あなたがたが受け入れられるには、それは牛、羊、あるいはやぎのうちの、傷のない雄でなければならない。'),
('JPN', '利未记', 3, 22, 20, '欠陥のあるものは、どのようなものでも献げてはならない。あなたがたの代わりにそれが受け入れられることはないからである。'),
('JPN', '利未记', 3, 22, 21, 'また、人が特別の誓願を果たすため、あるいは進んで献げるものとして、牛か羊の中から交わりのいけにえを主に献げるときは、それが受け入れられるためには傷のないものでなければならない。それにはどのような欠陥もあってはならない。'),
('JPN', '利未记', 3, 22, 22, '盲目のもの、折れたところのあるもの、傷のあるもの、あるいは、うみの出るもの、湿疹のあるもの、かさぶたのあるもの、あなたがたはこれらのものを、主に献げてはならない。また、これらのものを主への食物のささげ物として祭壇の上に献げてはならない。'),
('JPN', '利未记', 3, 22, 23, '牛や羊で、足が伸びすぎているか、または萎え縮んだものは、進んで献げるものとすることはできるが、誓願のささげ物としては受け入れられない。'),
('JPN', '利未记', 3, 22, 24, 'あなたがたは、睾丸の押しつぶされたもの、砕けたもの、裂かれたもの、切り取られたものを主に献げてはならない。あなたがたの地でそのようなことをしてはならない。'),
('JPN', '利未记', 3, 22, 25, 'また、あなたがたは、異国人の手から何かこのようなものを受けて、あなたがたの神のパンとして献げてはならない。これらのものは損なわれていて欠陥があるから、あなたがたは受け入れられない。」'),
('JPN', '利未记', 3, 22, 26, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 22, 27, '「牛か羊かやぎが生まれたときは、七日間、その母親のもとに置いておく。八日目以後、それは主への食物のささげ物として受け入れられる。'),
('JPN', '利未记', 3, 22, 28, 'しかし、牛でも羊でも、それをその子と同じ日に屠ってはならない。'),
('JPN', '利未记', 3, 22, 29, '主に感謝のいけにえを献げるときは、あなたがたが受け入れられるように、それを献げなければならない。'),
('JPN', '利未记', 3, 22, 30, 'その同じ日にこれを食べ、朝までそれを残しておいてはならない。わたしは主である。'),
('JPN', '利未记', 3, 22, 31, 'あなたがたはわたしの命令を守り、これを行わなければならない。わたしは主である。'),
('JPN', '利未记', 3, 22, 32, 'わたしの聖なる名を汚してはならない。イスラエルの子らの間で、わたしは聖であることが示されなければならない。わたしはあなたがたを聖別する主である。'),
('JPN', '利未记', 3, 22, 33, 'わたしは、あなたがたの神となるために、あなたがたをエジプトの地から導き出した。わたしは主である。」'),
('JPN', '利未记', 3, 23, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 23, 2, '「イスラエルの子らに告げよ。あなたがたが聖なる会合として召集する主の例祭、すなわちわたしの例祭は次のとおりである。'),
('JPN', '利未记', 3, 23, 3, '六日間は仕事をする。しかし、七日目は全き休みのための安息日、聖なる会合の日である。あなたがたは、いかなる仕事もしてはならない。この日は、あなたがたがどこに住んでいても主の安息日である。'),
('JPN', '利未记', 3, 23, 4, 'あなたがたが定期的に召集しなければならない聖なる会合、主の例祭は次のとおりである。'),
('JPN', '利未记', 3, 23, 5, '第一の月の十四日には夕暮れに過越のいけにえを主に献げる。'),
('JPN', '利未记', 3, 23, 6, 'この月の十五日は主への種なしパンの祭りである。七日間、あなたがたは種なしパンを食べる。'),
('JPN', '利未记', 3, 23, 7, '最初の日に、あなたがたは聖なる会合を開く。いかなる労働もしてはならない。'),
('JPN', '利未记', 3, 23, 8, '七日間、食物のささげ物を主に献げる。七日目に聖なる会合を開く。あなたがたは、いかなる労働もしてはならない。」'),
('JPN', '利未记', 3, 23, 9, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 23, 10, '「イスラエルの子らに告げよ。あなたがたがわたしが与えようとしている地に入り、収穫を刈り入れたなら、収穫の初穂の束を祭司のところに持って行きなさい。'),
('JPN', '利未记', 3, 23, 11, 'その束は主の前で揺り動かす。あなたがたが受け入れられるためである。祭司は安息日の翌日、それを揺り動かさなければならない。'),
('JPN', '利未记', 3, 23, 12, 'あなたがたは、束を揺り動かすその日に、主への全焼のささげ物として傷のない一歳の雄の子羊を献げる。'),
('JPN', '利未记', 3, 23, 13, 'その穀物のささげ物は油を混ぜた小麦粉十分の二エパであり、主への食物のささげ物、芳ばしい香りである。その注ぎのささげ物はぶどう酒で、一ヒンの四分の一である。'),
('JPN', '利未记', 3, 23, 14, 'あなたがたは、神へのささげ物を持って行くその日まで、パンも炒り麦も新穀も食べてはならない。これは、あなたがたがどこに住んでいても代々守るべき永遠の掟である。'),
('JPN', '利未记', 3, 23, 15, 'あなたがたは、安息日の翌日から、奉献物の束を持って行った日から満七週間を数える。'),
('JPN', '利未记', 3, 23, 16, '七回目の安息日の翌日まで五十日を数え、あなたがたは新しい穀物のささげ物を主に献げる。'),
('JPN', '利未记', 3, 23, 17, 'あなたがたの住まいから、十分の二エパの小麦粉にパン種を入れて焼いたものを二つ、奉献物としてのパンとして持って行く。これは主への初物である。'),
('JPN', '利未记', 3, 23, 18, 'そのパンと一緒に、主への全焼のささげ物として、傷のない一歳の雄の子羊七匹、若い雄牛一頭、雄羊二匹、また、主への食物のささげ物、芳ばしい香りとして、彼らの穀物のささげ物と注ぎのささげ物とを献げる。'),
('JPN', '利未记', 3, 23, 19, 'また、雄やぎ一匹を罪のきよめのささげ物とし、一歳の雄の子羊二匹を交わりのいけにえとする。'),
('JPN', '利未记', 3, 23, 20, '祭司はこれら二匹の雄の子羊を、初穂のパンと一緒に、奉献物として主の前で揺り動かす。これらは主の聖なるものであり、祭司のものとなる。'),
('JPN', '利未记', 3, 23, 21, 'その同じ日に、あなたがたは聖なる会合を召集する。それは、あなたがたのためである。いかなる労働もしてはならない。これは、あなたがたがどこに住んでいても、代々守るべき永遠の掟である。'),
('JPN', '利未记', 3, 23, 22, 'あなたがたの土地の収穫を刈り入れるときは、刈るときに畑の隅まで刈り尽くしてはならない。あなたの収穫の落ち穂も集めてはならない。貧しい人と寄留者のために、それらを残しておかなければならない。わたしはあなたがたの神、主である。」'),
('JPN', '利未记', 3, 23, 23, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 23, 24, '「イスラエルの子らに告げよ。第七の月の一日はあなたがたの全き休みの日であり、角笛を吹き鳴らして記念する聖なる会合を開く。'),
('JPN', '利未记', 3, 23, 25, 'あなたがたは、いかなる労働もしてはならない。食物のささげ物を主に献げなさい。」'),
('JPN', '利未记', 3, 23, 26, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 23, 27, '「特にこの第七の月の十日は宥めの日であり、あなたがたのために聖なる会合を開く。あなたがたは自らを戒め、食物のささげ物を主に献げなければならない。'),
('JPN', '利未记', 3, 23, 28, 'その日のうちは、いかなる仕事もしてはならない。その日が宥めの日であり、あなたがたの神、主の前であなたがたのために宥めがなされるからである。'),
('JPN', '利未记', 3, 23, 29, 'その日に自らを戒めない者はだれでも、自分の民から断ち切られる。'),
('JPN', '利未记', 3, 23, 30, 'だれでも、その日に少しでも仕事をする者は、わたしはその人をその民の間から滅ぼす。'),
('JPN', '利未记', 3, 23, 31, 'いかなる仕事もしてはならない。これは、あなたがたがどこに住んでいても代々守るべき永遠の掟である。'),
('JPN', '利未记', 3, 23, 32, 'これは、あなたがたの全き休みのための安息日である。あなたがたは自らを戒める。その月の九日の夕暮れには、その夕暮れから次の夕暮れまで、あなたがたの安息を守らなければならない。」'),
('JPN', '利未记', 3, 23, 33, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 23, 34, '「イスラエルの子らに告げよ。この第七の月の十五日には、七日間にわたる主の仮庵の祭りが始まる。'),
('JPN', '利未记', 3, 23, 35, '最初の日には、聖なる会合を開く。あなたがたは、いかなる労働もしてはならない。'),
('JPN', '利未记', 3, 23, 36, '七日間、あなたがたは食物のささげ物を主に献げなければならない。八日目も、あなたがたは聖なる会合を開かなければならない。あなたがたは食物のささげ物を主に献げる。これはきよめの集会であり、いかなる労働もしてはならない。'),
('JPN', '利未记', 3, 23, 37, '以上が主の例祭である。あなたがたは聖なる会合を召集して、全焼のささげ物、穀物のささげ物、交わりのいけにえ、注ぎのささげ物を、食物のささげ物として、それぞれ定められた日に主に献げなければならない。'),
('JPN', '利未记', 3, 23, 38, 'このほかに主の安息日、また、あなたがたが主に献げる献上物、あらゆる誓願のささげ物、あらゆる進んで献げるものがある。'),
('JPN', '利未记', 3, 23, 39, '特に、あなたがたがその土地の収穫をし終える第七の月の十五日には、七日間にわたる主の祭りを祝わなければならない。最初の日は全き休みの日であり、八日目も全き休みの日である。'),
('JPN', '利未记', 3, 23, 40, '最初の日に、あなたがたは自分たちのために、美しい木の実、なつめ椰子の葉と茂った木の大枝、また川辺の柳を取り、七日間、あなたがたの神、主の前で喜び楽しむ。'),
('JPN', '利未记', 3, 23, 41, '年に七日間、主の祭りとしてこれを祝う。これはあなたがたが代々守るべき永遠の掟であり、第七の月に祝わなければならない。'),
('JPN', '利未记', 3, 23, 42, 'あなたがたは七日間、仮庵に住まなければならない。イスラエルで生まれた者はみな仮庵に住まなければならない。'),
('JPN', '利未记', 3, 23, 43, 'これは、あなたがたの後の世代が、わたしがエジプトの地からイスラエルの子らを導き出したとき、彼らを仮庵に住まわせたことを知るためである。わたしはあなたがたの神、主である。」'),
('JPN', '利未记', 3, 23, 44, 'こうしてモーセはイスラエルの子らに主の例祭のことを告げた。'),
('JPN', '利未记', 3, 24, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 24, 2, '「あなたはイスラエルの子らに命じて、ともしび用の、質の良い純粋なオリーブ油を持って来させなさい。ともしびを絶えずともしておくためである。'),
('JPN', '利未记', 3, 24, 3, 'アロンは会見の天幕の中、あかしの箱の垂れ幕の外側で、夕方から朝まで主の前に絶えずそのともしびを整えておく。これはあなたがたが代々守るべき永遠の掟である。'),
('JPN', '利未记', 3, 24, 4, '彼はきよい燭台の上に、そのともしびを主の前に絶えず整えておく。'),
('JPN', '利未记', 3, 24, 5, 'あなたは小麦粉を取り、それで輪形パン十二個を焼く。一つの輪形パンは十分の二エパである。'),
('JPN', '利未记', 3, 24, 6, 'それを主の前のきよい机の上に一列六つずつ、二列に置く。'),
('JPN', '利未记', 3, 24, 7, 'それぞれの列に純粋な乳香を添え、覚えの分のパンとし、主への食物のささげ物とする。'),
('JPN', '利未记', 3, 24, 8, '彼は安息日ごとに、これを主の前に絶えず整えておく。これはイスラエルの子らによるささげ物であって、永遠の契約である。'),
('JPN', '利未记', 3, 24, 9, 'これはアロンとその子らのものとなり、彼らはこれを聖なる所で食べる。これは最も聖なるものであり、主への食物のささげ物のうちから、永遠の定めにより彼に与えられた割り当てだからである。」'),
('JPN', '利未记', 3, 24, 10, 'さて、イスラエル人を母とし、エジプト人を父とする者がイスラエルの子らのうちに出たが、このイスラエルの女の息子と、あるイスラエル人とが宿営の中で争った。'),
('JPN', '利未记', 3, 24, 11, 'そのとき、イスラエルの女の息子が御名を汚し、ののしったので、人々はこの者をモーセのところに連れて行った。彼の母の名はシェロミテで、ダン部族のディブリの娘であった。'),
('JPN', '利未记', 3, 24, 12, '人々は主の命が彼らにはっきりと示されるまで、この者を留置しておいた。'),
('JPN', '利未记', 3, 24, 13, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 24, 14, '「あの、ののしった者を宿営の外に連れ出し、それを聞いたすべての人がその人の頭に手を置き、全会衆が彼に石を投げて殺すようにしなさい。'),
('JPN', '利未记', 3, 24, 15, 'あなたはイスラエルの子らに告げよ。自分の神をののしる者はだれでも罪責を負う。'),
('JPN', '利未记', 3, 24, 16, '主の御名を汚す者は必ず殺されなければならない。全会衆は必ずその人に石を投げて殺さなければならない。寄留者でも、この国に生まれた者でも、御名を汚すなら殺される。'),
('JPN', '利未记', 3, 24, 17, '人間を打ち殺す者は必ず殺されなければならない。'),
('JPN', '利未记', 3, 24, 18, '動物を打ち殺す者は、いのちにはいのちをもって償わなければならない。'),
('JPN', '利未记', 3, 24, 19, '人がその同胞に傷を負わせるなら、その人は自分がしたのと同じようにされなければならない。'),
('JPN', '利未记', 3, 24, 20, '骨折には骨折を、目には目を、歯には歯を。人に傷を負わせたのと同じように、自分もそうされなければならない。'),
('JPN', '利未记', 3, 24, 21, '家畜を打ち殺す者は償いをしなければならず、人間を打ち殺す者は殺されなければならない。'),
('JPN', '利未记', 3, 24, 22, 'このさばきは、寄留者であれ、この国に生まれた者であれ、あなたがたには同一である。わたしがあなたがたの神、主だからである。」'),
('JPN', '利未记', 3, 24, 23, 'モーセがイスラエルの子らに告げたので、彼らはののしった者を宿営の外に連れ出し、彼に石を投げて殺した。こうしてイスラエルの人々は、主がモーセに命じられたとおりに行った。'),
('JPN', '利未记', 3, 25, 1, '主はシナイ山でモーセにこう告げられた。'),
('JPN', '利未记', 3, 25, 2, '「イスラエルの子らに告げよ。わたしが与えようとしている地にあなたがたが入ったとき、その地は主の安息を守らなければならない。'),
('JPN', '利未记', 3, 25, 3, '六年間はあなたの畑に種を蒔き、六年間ぶどう畑の刈り込みをして収穫をする。'),
('JPN', '利未记', 3, 25, 4, '七年目は地の全き休みのための安息、主の安息となる。あなたの畑に種を蒔いたり、ぶどう畑の刈り込みをしたりしてはならない。'),
('JPN', '利未记', 3, 25, 5, 'あなたの落ち穂から生えたものを刈り入れてはならない。あなたが手入れをしなかったぶどうの木のぶどうも集めてはならない。これは地のための全き休みの年である。'),
('JPN', '利未记', 3, 25, 6, '地の安息はあなたがたに食物をもたらす。すなわち、あなたと、あなたの男奴隷と女奴隷、あなたの雇い人と、あなたのところに在住している居留者のため、'),
('JPN', '利未记', 3, 25, 7, 'また、あなたの家畜と、あなたの地にいる獣のために、その地の収穫はすべて食物となる。'),
('JPN', '利未记', 3, 25, 8, 'あなたは安息の年を七回、すなわち、七年の七倍を数える。安息の年が七回で四十九年である。'),
('JPN', '利未记', 3, 25, 9, 'あなたはその第七の月の十日に角笛を鳴り響かせる。宥めの日に、あなたがたの全土に角笛を鳴り響かせる。'),
('JPN', '利未记', 3, 25, 10, 'あなたがたは五十年目を聖別し、国中のすべての住民に解放を宣言する。これはあなたがたのヨベルの年である。あなたがたはそれぞれ自分の所有地に帰り、それぞれ自分の家族のもとに帰る。'),
('JPN', '利未记', 3, 25, 11, 'この五十年目はあなたがたのヨベルの年である。種を蒔いてはならないし、落ち穂から生えたものを刈り入れてもならない。また手入れをしなかったぶどうの木のぶどうを集めてはならない。'),
('JPN', '利未记', 3, 25, 12, 'これはヨベルの年であって、あなたがたには聖である。あなたがたは野の収穫物を食べる。'),
('JPN', '利未记', 3, 25, 13, 'このヨベルの年には、あなたがたはそれぞれ自分の所有地に帰る。'),
('JPN', '利未记', 3, 25, 14, 'もしあなたがたが、同胞に土地を売ったり同胞から買ったりするときは、互いに損失を与えないようにしなさい。'),
('JPN', '利未记', 3, 25, 15, 'ヨベルの後の年数にしたがって、あなたの同胞から買い、収穫年数にしたがって相手もあなたに売る。'),
('JPN', '利未记', 3, 25, 16, '年数が多ければ、それに応じてあなたはその買い値を増し、年数が少なければ、それに応じてその買い値を減らさなければならない。彼があなたに売るのは収穫の回数だからである。'),
('JPN', '利未记', 3, 25, 17, 'あなたがたはそれぞれ同胞に損失を与えてはならない。あなたの神を恐れよ。わたしはあなたがたの神、主だからである。'),
('JPN', '利未记', 3, 25, 18, 'あなたがたはわたしの掟を行い、わたしの定めを守らなければならない。それを行うなら、その地に安らかに住むことができる。'),
('JPN', '利未记', 3, 25, 19, '地は実りをもたらし、あなたがたは満ち足りるまで食べ、安らかにそこに住むことができる。'),
('JPN', '利未记', 3, 25, 20, 'あなたがたは、『もし私たちが種を蒔かず、また収穫もしないなら、七年目には何を食べればよいのか』と言うであろうが、'),
('JPN', '利未记', 3, 25, 21, 'わたしは六年目に、あなたがたのためにわたしの祝福を命じ、三年分の収穫を生じさせる。'),
('JPN', '利未记', 3, 25, 22, 'あなたがたが八年目に種を蒔くときにも、前の収穫をなお食べている。九年目まで、その収穫があるまで、なお前のものを食べることができる。'),
('JPN', '利未记', 3, 25, 23, '土地は、買い戻しの権利を放棄して売ってはならない。土地はわたしのものである。あなたがたは、わたしのもとに在住している寄留者だからである。'),
('JPN', '利未记', 3, 25, 24, 'あなたがたの所有するどの土地においても、土地を買い戻す権利を認めなければならない。'),
('JPN', '利未记', 3, 25, 25, 'もしあなたの兄弟が落ちぶれて、その所有地を売ったときは、買い戻しの権利のある近親者が来て、兄弟の売ったものを買い戻さなければならない。'),
('JPN', '利未记', 3, 25, 26, 'その人に買い戻しの権利のある親類がいないときは、彼の暮らし向きが良くなり、それを買い戻す余裕ができたなら、'),
('JPN', '利未记', 3, 25, 27, '売ってからの年数を計算し、なお残る分を買い主に返し、自分の所有地に帰ることができる。'),
('JPN', '利未记', 3, 25, 28, 'もしその人に返す余裕がないなら、その売ったものはヨベルの年まで買い主の手にとどまる。しかし、ヨベルの年にはその手を離れ、彼は自分の所有地に帰ることができる。'),
('JPN', '利未记', 3, 25, 29, '人が、城壁を巡らした町の住居を売るときは、それを売ってからの一年間は買い戻す権利がある。買い戻しはこの期間に限る。'),
('JPN', '利未记', 3, 25, 30, 'もし満一年になるまでに買い戻されないなら、城壁を巡らした町の中のその家は、買い戻しの権利の喪失により、代々にわたってそれを買い取った人のものとなり、ヨベルの年にも彼の手を離れない。'),
('JPN', '利未记', 3, 25, 31, '周りに城壁のない村々の家は、その土地の畑と見なされて買い戻すことができ、ヨベルの年に彼の手を離れる。'),
('JPN', '利未记', 3, 25, 32, 'レビ人の町々、すなわち彼らが所有している町々の家については、レビ人にいつでも買い戻す権利がある。'),
('JPN', '利未记', 3, 25, 33, 'レビ人が買い戻すものに関しては、彼の所有地の町で売られた家はヨベルの年には手放される。レビ人の町々の家は、イスラエルの子らの間にあって彼らが所有するものだからである。'),
('JPN', '利未记', 3, 25, 34, '彼らの町々の放牧用の畑は売ってはならない。それは彼らの永遠の所有地だからである。'),
('JPN', '利未记', 3, 25, 35, 'もしあなたの同胞が落ちぶれて、あなたのもとで暮らしが立たなくなったなら、彼をあなたのところに在住している寄留者のように扶養し、あなたのもとで生活できるようにしなさい。'),
('JPN', '利未记', 3, 25, 36, '彼から利息も利益も得てはならない。あなたの神を恐れよ。同胞があなたのもとで生活できるようにしなさい。'),
('JPN', '利未记', 3, 25, 37, '彼に金を貸して利息を取ってはならない。また食物を与えて利益を得てはならない。'),
('JPN', '利未记', 3, 25, 38, 'わたしはあなたがたの神、主である。わたしは、あなたがたにカナンの地を与えてあなたがたの神となるために、あなたがたをエジプトの地から導き出したのである。'),
('JPN', '利未记', 3, 25, 39, 'もし、あなたのもとにいるあなたの兄弟が落ちぶれて、あなたに身売りしても、彼を奴隷として仕えさせてはならない。'),
('JPN', '利未记', 3, 25, 40, '彼はあなたのもとでは雇い人か居留者のようでなければならず、ヨベルの年まであなたのもとで仕える。'),
('JPN', '利未记', 3, 25, 41, 'こうして彼とその子らはあなたのもとから出て行き、自分の一族のもと、自分の先祖の所有地に帰る。'),
('JPN', '利未记', 3, 25, 42, '彼らは、わたしがエジプトの地から導き出した、わたしのしもべである。奴隷の身分として売られてはならない。'),
('JPN', '利未记', 3, 25, 43, 'あなたは彼を酷使してはならない。あなたの神を恐れよ。'),
('JPN', '利未记', 3, 25, 44, 'あなたのものとなる男女の奴隷は、あなたがたの周囲の国々から来た者であり、彼らの中から男女の奴隷を買い取ることができる。'),
('JPN', '利未记', 3, 25, 45, 'あるいは、あなたがたのところに在住している居留者たちの子どもの中からも、または、あなたがたの間にいる彼らの家族で、あなたがたの国で生まれた者からも買い取ることができる。彼らはあなたがたの所有とすることができる。'),
('JPN', '利未记', 3, 25, 46, 'あなたがたは彼らを、あなたがたの後の子孫にゆずりとして与え、永遠に所有として受け継がせ、奴隷とすることができる。しかし、あなたがたの同胞であるイスラエルの子らは、互いに酷使し合ってはならない。'),
('JPN', '利未记', 3, 25, 47, 'もし、あなたのところに在住している寄留者の暮らし向きが良くなり、その人のところにいるあなたの兄弟が落ちぶれて、あなたのところに在住している寄留者に、あるいはその寄留者の氏族の子孫に身を売ったときは、'),
('JPN', '利未记', 3, 25, 48, '身を売った後でも、その人には買い戻される権利がある。彼の兄弟の一人が彼を買い戻すことができる。'),
('JPN', '利未记', 3, 25, 49, 'または、その人のおじや、おじの息子が買い戻すこともできる。または、一族の近親者の一人が買い戻すこともできる。あるいは、もし暮らし向きが良くなれば、自分で自分自身を買い戻すこともできる。'),
('JPN', '利未记', 3, 25, 50, '買い主とともに、自分が身を売った年からヨベルの年までを計算する。身代金は、その年数に応じて、雇い人の場合の期間にしたがって決める。'),
('JPN', '利未记', 3, 25, 51, 'もしまだ多くの年数が残っているなら、その年数に応じて、自分が買われた金額のうちから買い戻し金となる分を払う。'),
('JPN', '利未记', 3, 25, 52, 'ヨベルの年までわずかの年数しか残っていなくても、彼はそのように計算し、その年数に応じて買い戻し金となる分を払う。'),
('JPN', '利未记', 3, 25, 53, '彼は年ごとに雇われる者のように扱われなければならない。あなたの目の前で酷使されてはならない。'),
('JPN', '利未记', 3, 25, 54, 'たとえ、これらの方法によって買い戻されなかった場合でも、ヨベルの年には、その子らと一緒に出て行くことができる。'),
('JPN', '利未记', 3, 25, 55, 'イスラエルの子らは、このわたしのしもべだからである。彼らは、わたしがエジプトの地から導き出した、わたしのしもべである。わたしはあなたがたの神、主である。'),
('JPN', '利未记', 3, 26, 1, 'あなたがたは自分のために偶像を造ってはならない。また自分のために彫像や石の柱を立ててはならない。あなたがたの地に石像を立てて、それを拝んではならない。わたしがあなたがたの神、主だからである。'),
('JPN', '利未记', 3, 26, 2, 'あなたがたはわたしの安息日を守り、わたしの聖所を恐れなければならない。わたしは主である。'),
('JPN', '利未记', 3, 26, 3, 'もし、あなたがたがわたしの掟に従って歩み、わたしの命令を守り、それらを行うなら、'),
('JPN', '利未记', 3, 26, 4, 'わたしは時にかなってあなたがたに雨を与える。それにより地は産物を出し、畑の木々はその実を結ぶ。'),
('JPN', '利未记', 3, 26, 5, 'あなたがたの麦打ちはぶどうの取り入れ時まで続き、ぶどうの取り入れは種蒔きの時まで続く。あなたがたは満ち足りるまでパンを食べ、安らかに自分たちの地に住む。'),
('JPN', '利未记', 3, 26, 6, 'また、わたしはその地に平和を与える。あなたがたはだれにも脅かされずに寝る。また、わたしは悪い獣をその国から除く。剣があなたがたの地を行き巡ることはない。'),
('JPN', '利未记', 3, 26, 7, 'あなたがたは敵を追い、彼らはあなたがたの前に剣で倒れる。'),
('JPN', '利未记', 3, 26, 8, 'あなたがたの五人は百人を追い、百人は一万人を追う。あなたがたの敵はあなたがたの前に剣によって倒れる。'),
('JPN', '利未记', 3, 26, 9, 'わたしはあなたがたを顧み、多くの子を与えてあなたがたを増やし、あなたがたとのわたしの契約を確かなものにする。'),
('JPN', '利未记', 3, 26, 10, 'あなたがたは長く蓄えられた古いものを食べ、新しいものを前にして、古いものを片付けるようになる。'),
('JPN', '利未记', 3, 26, 11, 'わたしは、あなたがたのただ中にわたしの住まいを建てる。わたしの心は、あなたがたを嫌って退けたりはしない。'),
('JPN', '利未记', 3, 26, 12, 'わたしはあなたがたの間を歩み、あなたがたの神となり、あなたがたはわたしの民となる。'),
('JPN', '利未记', 3, 26, 13, 'わたしはあなたがたの神、主である。わたしはあなたがたを奴隷の身分から救い出すために、エジプトの地から導き出した。わたしは、あなたがたのくびきの横木を砕き、あなたがたが自立して歩めるようにした。'),
('JPN', '利未记', 3, 26, 14, 'しかし、もし、あなたがたがわたしに聞き従わず、これらすべての命令を行わないなら、'),
('JPN', '利未记', 3, 26, 15, 'また、わたしの掟を拒み、あなたがた自身がわたしの定めを嫌って退け、わたしのすべての命令を行わず、わたしの契約を破るなら、'),
('JPN', '利未记', 3, 26, 16, 'わたしもあなたがたに次のことを行う。わたしはあなたがたの上に恐怖を臨ませ、肺病と熱病で目を衰えさせ、心をすり減らさせる。あなたがたは種を蒔いても無駄である。あなたがたの敵がそれを食べる。'),
('JPN', '利未记', 3, 26, 17, 'わたしはあなたがたに敵対してわたしの顔を向ける。あなたがたは自分の敵に打ち負かされ、あなたがたを憎む者があなたがたを踏みつける。あなたがたを追う者がいないのに、あなたがたは逃げる。'),
('JPN', '利未记', 3, 26, 18, 'もし、これらのことが起こっても、あなたがたがなおもわたしに聞かないなら、わたしはさらに、あなたがたの罪に対して七倍重く懲らしめる。'),
('JPN', '利未记', 3, 26, 19, 'わたしは、自分の力を頼むあなたがたの思い上がりを打ち砕き、あなたがたの天を鉄のように、あなたがたの地を青銅のようにする。'),
('JPN', '利未记', 3, 26, 20, 'あなたがたの力は無駄に費やされる。あなたがたの地は産物を出さず、地の木々も実を結ばない。'),
('JPN', '利未记', 3, 26, 21, 'また、もしあなたがたがわたしに逆らって歩み、わたしに聞こうとしないなら、わたしはさらに、あなたがたの罪にふさわしく、七倍激しくあなたがたを打ちたたく。'),
('JPN', '利未记', 3, 26, 22, 'わたしはまた、あなたがたの間に野の獣を放つ。これはあなたがたから子を奪い、家畜を絶えさせ、あなたがたの数を減らす。こうして、あなたがたの道は荒れ果てる。'),
('JPN', '利未记', 3, 26, 23, 'もし、それでも、わたしのこの懲らしめをあなたがたが受け入れず、わたしに逆らって歩むなら、'),
('JPN', '利未记', 3, 26, 24, 'わたしもあなたがたに逆らって歩む。また、わたしは、あなたがたの罪に対して七倍重くあなたがたを打つ。'),
('JPN', '利未记', 3, 26, 25, 'わたしはあなたがたの上に剣を臨ませ、契約による復讐を果たす。あなたがたは自分たちの町々に集まるが、わたしがあなたがたの間に疫病を送り込むので、あなたがたは敵の手に落ちる。'),
('JPN', '利未记', 3, 26, 26, 'わたしがあなたがたのパンの蓄えをなくすとき、十人の女が一つのかまどでパンを焼き、秤にかけてパンを配る。あなたがたは食べても満ち足りない。'),
('JPN', '利未记', 3, 26, 27, 'これにもかかわらず、なおもあなたがたが、わたしに聞こうとせず、わたしに逆らって歩むなら、'),
('JPN', '利未记', 3, 26, 28, 'わたしは激怒をもってあなたがたに逆らって歩み、あなたがたの罪に対して七倍重くあなたがたを懲らしめる。'),
('JPN', '利未记', 3, 26, 29, 'あなたがたは自分の息子の肉を食べ、自分の娘の肉を食べる。'),
('JPN', '利未记', 3, 26, 30, 'わたしはあなたがたの高き所を打ち壊し、香の台を切り倒し、偶像の残骸の上にあなたがたの死体を積み上げる。わたしの心は、あなたがたを嫌って退ける。'),
('JPN', '利未记', 3, 26, 31, 'わたしはあなたがたの町々を廃墟とし、あなたがたの聖所を荒れ果てさせる。わたしはあなたがたの芳ばしい香りをかぐことはしない。'),
('JPN', '利未记', 3, 26, 32, 'わたしはその地を荒れ果てさせ、そこに住むあなたがたの敵はそれを見て啞然とする。'),
('JPN', '利未记', 3, 26, 33, 'わたしはあなたがたを国々の間に散らし、剣を抜いてあなたがたの後を追う。あなたがたの地は荒れ果て、あなたがたの町々は廃墟となる。'),
('JPN', '利未记', 3, 26, 34, 'そのとき、その地が荒れ果て、あなたがたが敵の国にいる間、その地は休む。そのとき地はその安息を享受する。'),
('JPN', '利未记', 3, 26, 35, '地は、荒れ果てている間、休むことができる。それは、あなたがたがそこに住んでいたとき、あなたがたの安息のときには得られなかったものである。'),
('JPN', '利未记', 3, 26, 36, 'あなたがたのうちで生き残る者にも、敵の国にいる間、彼らの心の中に臆病を送り込む。吹き散らされる木の葉の音にさえ彼らは追い立てられ、剣から逃れる者のように逃げ、追いかける者もいないのに倒れる。'),
('JPN', '利未记', 3, 26, 37, '追いかける者もいないのに、剣から逃れるかのように折り重なってつまずき倒れる。あなたがたは敵の前に立つこともできない。'),
('JPN', '利未记', 3, 26, 38, 'あなたがたは国々の間で滅び、あなたがたの敵の地はあなたがたを食い尽くす。'),
('JPN', '利未记', 3, 26, 39, 'あなたがたのうちの生き残る者も、敵の地で自分の咎のために朽ち果てる。さらに先祖の咎のために朽ち果てる。'),
('JPN', '利未记', 3, 26, 40, '彼らは、自分たちの咎と先祖の咎を、つまり、わたしの信頼を裏切って、わたしに逆らって歩んだことを告白するが、'),
('JPN', '利未记', 3, 26, 41, 'このわたしが彼らに逆らって歩み、彼らを敵の国へ送り込むのである。もしそのとき、彼らの無割礼の心がへりくだるなら、そのとき自分たちの咎の償いをすることになる。'),
('JPN', '利未记', 3, 26, 42, 'わたしはヤコブとのわたしの契約を思い起こす。またイサクとのわたしの契約を、さらにはアブラハムとのわたしの契約をも思い起こす。わたしはその地を思い起こす。'),
('JPN', '利未记', 3, 26, 43, 'その地は彼らに捨て置かれ、彼らがいなくなって荒れ果てている間、安息を享受する。彼らは自分たちの咎の償いをすることになるが、それはただ、彼ら自身がわたしの定めを退け、わたしの掟を嫌って退けたゆえである。'),
('JPN', '利未记', 3, 26, 44, 'それにもかかわらず、彼らがその敵の国にいるとき、わたしは彼らを退けず、彼らを嫌って絶ち滅ぼさず、彼らとのわたしの契約を破ることはない。わたしが彼らの神、主だからである。'),
('JPN', '利未记', 3, 26, 45, 'わたしは彼らのために、彼らの父祖たちと結んだ契約を思い起こす。わたしは彼らを国々の目の前で、彼らの神となるためにエジプトの地から導き出したのだ。わたしは主である。」'),
('JPN', '利未记', 3, 26, 46, '以上は、主がシナイ山でモーセを通して、ご自分とイスラエルの子らとの間に立てられた、掟と定めとおしえである。'),
('JPN', '利未记', 3, 27, 1, '主はモーセにこう告げられた。'),
('JPN', '利未记', 3, 27, 2, '「イスラエルの子らに告げよ。人が人間の評価額にしたがって主に特別な誓願を立てるときには、'),
('JPN', '利未记', 3, 27, 3, 'その評価額を次のとおりにする。二十歳から六十歳までの男子なら、その評価額は聖所のシェケルで銀五十シェケル。'),
('JPN', '利未记', 3, 27, 4, '女子なら、その評価額は三十シェケル。'),
('JPN', '利未记', 3, 27, 5, '五歳から二十歳までなら、その男子の評価額は二十シェケル、女子は十シェケル。'),
('JPN', '利未记', 3, 27, 6, '一か月から五歳までなら、男子の評価額は銀五シェケル、女子の評価額は銀三シェケル。'),
('JPN', '利未记', 3, 27, 7, '六十歳以上なら、男子の評価額は十五シェケル、女子は十シェケル。'),
('JPN', '利未记', 3, 27, 8, 'その人が落ちぶれていて評価額を払えないなら、その人を祭司の前に立たせ、祭司が彼の評価をする。祭司は誓願をする者の能力に応じて彼を評価する。'),
('JPN', '利未记', 3, 27, 9, '献げることのできる家畜を主へのささげ物とする場合、すべて主に献げられたものは聖なるものとなる。'),
('JPN', '利未记', 3, 27, 10, 'それをほかのもので代用したり、良いものを悪いものに、あるいは悪いものを良いものに取り替えたりしてはならない。もしも家畜をほかの家畜と取り替えることがあれば、それも代わりのものも聖なるものとなる。'),
('JPN', '利未记', 3, 27, 11, '献げることのできない、汚れた家畜を主へのささげ物とする場合には、その家畜を祭司の前に立たせる。'),
('JPN', '利未记', 3, 27, 12, '祭司はその良し悪しを評価する。それは祭司が評価したとおりとなる。'),
('JPN', '利未记', 3, 27, 13, 'もしも、その人がそれを買い戻したいのであれば、その評価額にその五分の一を加える。'),
('JPN', '利未记', 3, 27, 14, '人が自分の家を主に聖なるものとして聖別するときは、祭司がその良し悪しを評価する。祭司がそれを評価したとおり、そのようになる。'),
('JPN', '利未记', 3, 27, 15, '家を聖別した人がそれを買い戻したい場合は、評価額に五分の一を加えれば、それは彼のものとなる。'),
('JPN', '利未记', 3, 27, 16, '人が自分の所有の畑の一部を主に聖別する場合には、評価額はそこに蒔く種の量による。大麦の種一ホメルごとに銀五十シェケルである。'),
('JPN', '利未记', 3, 27, 17, 'もしヨベルの年からその畑を聖別するなら、評価額どおりである。'),
('JPN', '利未记', 3, 27, 18, 'しかし、ヨベルの年の後にその畑を聖別するなら、祭司は次のヨベルの年までにまだ残っている年数によって、その金額を計算する。そのようにして評価額から差し引かれる。'),
('JPN', '利未记', 3, 27, 19, 'もし、その畑を聖別した人がそれを買い戻したいのであれば、評価額にその五分の一を加える。それは彼のものとして残る。'),
('JPN', '利未记', 3, 27, 20, 'もし彼がその畑を買い戻さず、また、その畑がほかの人に売られているなら、もはやそれを買い戻すことはできない。'),
('JPN', '利未记', 3, 27, 21, 'その畑がヨベルの年に渡されるとき、それは聖絶された畑として主の聖なるものとなり、祭司の所有地となる。'),
('JPN', '利未记', 3, 27, 22, 'また人が、自分の所有の畑の一部ではない、買い取った畑を主に聖別する場合は、'),
('JPN', '利未记', 3, 27, 23, '祭司はヨベルの年までの評価の総額を計算し、その人はその日に、その評価額を主の聖なるものとして献げなければならない。'),
('JPN', '利未记', 3, 27, 24, 'ヨベルの年には、その畑は、その売り主であるその地の所有主に戻る。'),
('JPN', '利未记', 3, 27, 25, '評価はすべて聖所のシェケルによる。一シェケルは二十ゲラである。'),
('JPN', '利未记', 3, 27, 26, 'ただし、家畜の初子は主のものである。初子として生まれたのだから、だれもこれを聖別することはできない。牛であれ羊であれ、それは主のものである。'),
('JPN', '利未记', 3, 27, 27, 'それが汚れた家畜のものであれば、それの評価額にその五分の一を加えて贖うことができる。しかし、買い戻されないなら、その評価額で売られる。'),
('JPN', '利未记', 3, 27, 28, 'ただし、人であれ家畜であれ、自分の所有の畑であれ、自分の持っているすべてのもののうちで、主に対して聖絶したものは、何であろうとそれを売ることはできない。また買い戻すこともできない。すべて聖絶の物は最も聖なるものであり、主のものである。'),
('JPN', '利未记', 3, 27, 29, '人であって、聖絶された者はみな、贖われることがない。その人は必ず殺されなければならない。'),
('JPN', '利未记', 3, 27, 30, '地の十分の一は、地の産物であれ木の実であれ、すべて主のものである。それは主の聖なるものである。'),
('JPN', '利未记', 3, 27, 31, 'しかし、もしも人がその十分の一の一部を買い戻したいのであれば、それにその五分の一を加える。'),
('JPN', '利未记', 3, 27, 32, '牛や羊の十分の一については、牧者の杖の下を通る十番目ごとのものが主の聖なるものとなる。'),
('JPN', '利未记', 3, 27, 33, 'その良し悪しを見てはならない。また、それを取り替えてはならない。もしも、それを取り替えることがあれば、それも代わりのものも、ともに聖なるものとなる。それを買い戻すことはできない。」'),
('JPN', '利未记', 3, 27, 34, '以上は、主がシナイ山で、イスラエルの子らに向けてモーセに命じられた命令である。'),
('JPN', '民数记', 4, 1, 1, 'エジプトの地を出て二年目の第二の月の一日に、主は、シナイの荒野の会見の天幕でモーセに告げられた。'),
('JPN', '民数记', 4, 1, 2, '「イスラエルの全会衆を、氏族ごと、一族ごとに調べ、すべての男子を一人ひとり名を数えて、その頭数を調べよ。'),
('JPN', '民数记', 4, 1, 3, 'あなたとアロンは、イスラエルにおいて、二十歳以上で戦に出ることができる者をすべて、その軍団ごとに登録しなければならない。'),
('JPN', '民数记', 4, 1, 4, 'また部族ごとに一人ずつ、一族のかしらである者が、あなたがたとともにいなければならない。'),
('JPN', '民数记', 4, 1, 5, 'あなたがたの助手となるはずの者の名は次のとおりである。ルベンからはシェデウルの子エリツル。'),
('JPN', '民数记', 4, 1, 6, 'シメオンからはツリシャダイの子シェルミエル。'),
('JPN', '民数记', 4, 1, 7, 'ユダからはアミナダブの子ナフション。'),
('JPN', '民数记', 4, 1, 8, 'イッサカルからはツアルの子ネタンエル。'),
('JPN', '民数记', 4, 1, 9, 'ゼブルンからはヘロンの子エリアブ。'),
('JPN', '民数记', 4, 1, 10, 'ヨセフの子らからは、エフライムからアミフデの子エリシャマ、マナセからペダツルの子ガムリエル。'),
('JPN', '民数记', 4, 1, 11, 'ベニヤミンからはギデオニの子アビダン。'),
('JPN', '民数记', 4, 1, 12, 'ダンからはアミシャダイの子アヒエゼル。'),
('JPN', '民数记', 4, 1, 13, 'アシェルからはオクランの子パグイエル。'),
('JPN', '民数记', 4, 1, 14, 'ガドからはデウエルの子エルヤサフ。'),
('JPN', '民数记', 4, 1, 15, 'ナフタリからはエナンの子アヒラ。」'),
('JPN', '民数记', 4, 1, 16, 'これらの者が会衆から召し出された者で、その父祖の部族の長たちである。彼らがイスラエルの分団のかしらたちである。'),
('JPN', '民数记', 4, 1, 17, 'さて、モーセとアロンは、これら指名された者たちを伴い、'),
('JPN', '民数记', 4, 1, 18, '第二の月の一日に全会衆を召集した。そこで氏族ごと、一族ごとに、二十歳以上の者の名を一人ひとり数えて、その家族表で本人を確認した。'),
('JPN', '民数记', 4, 1, 19, '主がモーセに命じられたように、モーセはシナイの荒野で彼らを登録した。'),
('JPN', '民数记', 4, 1, 20, 'イスラエルの長子ルベンの子孫は、氏族ごと、一族ごとに分かれたその家系に属する者たちで、一人ひとり名を数えられた、二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 21, 'このルベン部族で登録された者は、四万六千五百人であった。'),
('JPN', '民数记', 4, 1, 22, 'シメオンの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者たちで、一人ひとり名を数えられた、二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 23, 'このシメオン部族で登録された者は、五万九千三百人であった。'),
('JPN', '民数记', 4, 1, 24, 'ガドの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者たちで、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 25, 'このガド部族で登録された者は、四万五千六百五十人であった。'),
('JPN', '民数记', 4, 1, 26, 'ユダの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者たちで、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 27, 'このユダ部族で登録された者は、七万四千六百人であった。'),
('JPN', '民数记', 4, 1, 28, 'イッサカルの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者たちで、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 29, 'このイッサカル部族で登録された者は、五万四千四百人であった。'),
('JPN', '民数记', 4, 1, 30, 'ゼブルンの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者たちで、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 31, 'このゼブルン部族で登録された者は、五万七千四百人であった。'),
('JPN', '民数记', 4, 1, 32, 'ヨセフの子孫では、エフライムの子孫で、氏族ごと、一族ごとに分かれたその家系に属する者たちで、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 33, 'このエフライム部族で登録された者は、四万五百人であった。'),
('JPN', '民数记', 4, 1, 34, 'マナセの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者たちで、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 35, 'このマナセ部族で登録された者は、三万二千二百人であった。'),
('JPN', '民数记', 4, 1, 36, 'ベニヤミンの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者たちで、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 37, 'このベニヤミン部族で登録された者は、三万五千四百人であった。'),
('JPN', '民数记', 4, 1, 38, 'ダンの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者たちで、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 39, 'このダン部族で登録された者は、六万二千七百人であった。'),
('JPN', '民数记', 4, 1, 40, 'アシェルの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者たちで、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 41, 'このアシェル部族で登録された者は、四万一千五百人であった。'),
('JPN', '民数记', 4, 1, 42, 'ナフタリの子孫では、氏族ごと、一族ごとに分かれたその家系に属する者で、名を数えられた二十歳以上で戦に出ることができる者すべて。'),
('JPN', '民数记', 4, 1, 43, 'このナフタリ部族で登録された者は、五万三千四百人であった。'),
('JPN', '民数记', 4, 1, 44, '以上がモーセとアロン、またイスラエルの族長たちが登録した者たちである。この族長たち十二人は、それぞれ、自分の一族を代表していた。'),
('JPN', '民数记', 4, 1, 45, '一族ごとに登録された二十歳以上のイスラエルの子らで、イスラエルで戦に出ることができる者すべて、'),
('JPN', '民数记', 4, 1, 46, '登録された者の総数は、六十万三千五百五十人であった。'),
('JPN', '民数记', 4, 1, 47, 'しかしレビ人は、彼らとともに父祖の部族ごとに登録されることはなかった。'),
('JPN', '民数记', 4, 1, 48, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 1, 49, '「レビ部族だけは、ほかのイスラエルの子らとともに登録してはならない。また、その頭数を調べてはならない。'),
('JPN', '民数记', 4, 1, 50, 'あなたは、レビ人に、あかしの幕屋とそのすべての用具、およびすべてそれに付属するものを管理させよ。彼らは幕屋とそのすべての用具を運び、これに仕え、幕屋の周りに宿営しなければならない。'),
('JPN', '民数记', 4, 1, 51, '幕屋が進むときはレビ人がそれを取り外し、幕屋が張られるときはレビ人がこれを組み立てなければならない。資格なしにこれに近づく者は殺されなければならない。'),
('JPN', '民数记', 4, 1, 52, 'イスラエルの子らは、軍団ごとに、それぞれ自分の宿営、自分の旗のもとに天幕を張るが、'),
('JPN', '民数记', 4, 1, 53, 'レビ人は、あかしの幕屋の周りに宿営しなければならない。わたしの怒りがイスラエルの会衆の上に臨むことがあってはならない。レビ人はあかしの幕屋に関わる任務に当たる。」'),
('JPN', '民数记', 4, 1, 54, 'イスラエルの子らは、このようにし、すべて主がモーセに命じられたとおりに行った。'),
('JPN', '民数记', 4, 2, 1, '主はモーセとアロンに告げられた。'),
('JPN', '民数记', 4, 2, 2, '「イスラエルの子らは、それぞれ自分たちの旗のもと、自分の一族の旗じるしのもとに宿営しなければならない。会見の天幕の周りに、距離をおいて宿営しなければならない。'),
('JPN', '民数记', 4, 2, 3, '前方、すなわち東側に宿営する者は、軍団ごとのユダの宿営の旗の者でなければならない。ユダ族の族長はアミナダブの子ナフションである。'),
('JPN', '民数记', 4, 2, 4, '彼の軍団は、登録された者が七万四千六百人である。'),
('JPN', '民数记', 4, 2, 5, 'その隣に宿営するのはイッサカル部族であり、イッサカル族の族長はツアルの子ネタンエルである。'),
('JPN', '民数记', 4, 2, 6, '彼の軍団は、登録された者が五万四千四百人である。'),
('JPN', '民数记', 4, 2, 7, 'その次はゼブルン部族で、ゼブルン族の族長はヘロンの子エリアブである。'),
('JPN', '民数记', 4, 2, 8, '彼の軍団は、登録された者が五万七千四百人である。'),
('JPN', '民数记', 4, 2, 9, 'ユダの宿営に属し、その軍団ごとに登録された者の総数は、十八万六千四百人。彼らが先頭を進まなければならない。'),
('JPN', '民数记', 4, 2, 10, '南側は、軍団ごとのルベンの宿営の旗の者たちである。ルベン族の族長はシェデウルの子エリツルである。'),
('JPN', '民数记', 4, 2, 11, '彼の軍団は、登録された者が四万六千五百人である。'),
('JPN', '民数记', 4, 2, 12, 'その隣に宿営するのはシメオン部族で、シメオン族の族長はツリシャダイの子シェルミエルである。'),
('JPN', '民数记', 4, 2, 13, '彼の軍団は、登録された者が五万九千三百人である。'),
('JPN', '民数记', 4, 2, 14, 'その次はガド部族で、ガド族の族長はデウエルの子エルヤサフである。'),
('JPN', '民数记', 4, 2, 15, '彼の軍団は、登録された者が四万五千六百五十人である。'),
('JPN', '民数记', 4, 2, 16, 'ルベンの宿営に属し、その軍団ごとに登録された者の総数は、十五万一千四百五十人。彼らは二番目に進まなければならない。'),
('JPN', '民数记', 4, 2, 17, '次に会見の天幕、すなわちレビ人の宿営が、これらの宿営の中央にあって進まなければならない。宿営する場合と同じように、彼らはそれぞれ自分の場に就いて、自分の旗に従って進まなければならない。'),
('JPN', '民数记', 4, 2, 18, '西側は、軍団ごとのエフライムの宿営の旗の者たちである。エフライム族の族長はアミフデの子エリシャマである。'),
('JPN', '民数记', 4, 2, 19, '彼の軍団は、登録された者が四万五百人である。'),
('JPN', '民数记', 4, 2, 20, 'その隣はマナセ部族で、マナセ族の族長はペダツルの子ガムリエルである。'),
('JPN', '民数记', 4, 2, 21, '彼の軍団は、登録された者が三万二千二百人である。'),
('JPN', '民数记', 4, 2, 22, 'その次はベニヤミン部族で、ベニヤミン族の族長はギデオニの子アビダンである。'),
('JPN', '民数记', 4, 2, 23, '彼の軍団は、登録された者が三万五千四百人である。'),
('JPN', '民数记', 4, 2, 24, 'エフライムの宿営に属し、その軍団ごとに登録された者の総数は、十万八千百人。彼らは三番目に進まなければならない。'),
('JPN', '民数记', 4, 2, 25, '北側は、軍団ごとのダンの宿営の旗の者たちである。ダン族の族長はアミシャダイの子アヒエゼルである。'),
('JPN', '民数记', 4, 2, 26, '彼の軍団は、登録された者が六万二千七百人である。'),
('JPN', '民数记', 4, 2, 27, 'その隣に宿営するのはアシェル部族で、アシェル族の族長はオクランの子パグイエルである。'),
('JPN', '民数记', 4, 2, 28, '彼の軍団は、登録された者が四万一千五百人である。'),
('JPN', '民数记', 4, 2, 29, 'その次はナフタリ部族で、ナフタリ族の族長はエナンの子アヒラである。'),
('JPN', '民数记', 4, 2, 30, '彼の軍団は、登録された者が五万三千四百人である。'),
('JPN', '民数记', 4, 2, 31, 'ダンの宿営に属する、登録された者の総数は、十五万七千六百人。彼らはその旗に従って、最後に進まなければならない。」'),
('JPN', '民数记', 4, 2, 32, '以上が、イスラエルの子らで、その一族ごとに登録された者たちであり、全宿営の軍団ごとに登録された者の総数は、六十万三千五百五十人であった。'),
('JPN', '民数记', 4, 2, 33, 'しかしレビ人は、主がモーセに命じられたように、ほかのイスラエルの子らとともに登録されることはなかった。'),
('JPN', '民数记', 4, 2, 34, 'イスラエルの子らは、すべて主がモーセに命じられたとおりに行い、それぞれの旗ごとに宿営し、それぞれその氏族ごと、一族ごとに進んで行った。'),
('JPN', '民数记', 4, 3, 1, 'これは、主がシナイ山でモーセと語られたときの、アロンとモーセの系図である。'),
('JPN', '民数记', 4, 3, 2, 'アロンの息子たちの名は、長子ナダブ、アビフ、エルアザル、イタマル。'),
('JPN', '民数记', 4, 3, 3, 'これらはアロンの息子たちの名で、彼らは油注がれて祭司職に任じられた祭司であった。'),
('JPN', '民数记', 4, 3, 4, 'ナダブとアビフは、シナイの荒野で主の前に異なる火を献げたときに、主の前で死んだ。彼らには子がいなかった。それでエルアザルとイタマルが父アロンの生存中から祭司として仕えた。'),
('JPN', '民数记', 4, 3, 5, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 3, 6, '「レビ部族を進み出させ、彼らを祭司アロンに付き添わせて、仕えさせよ。'),
('JPN', '民数记', 4, 3, 7, '彼らは会見の天幕の前で、アロンに関わる任務と全会衆に関わる任務に当たり、幕屋の奉仕をしなければならない。'),
('JPN', '民数记', 4, 3, 8, '彼らは会見の天幕のすべての用具を守り、またイスラエルの子らに関わる任務に当たり、幕屋の奉仕をしなければならない。'),
('JPN', '民数记', 4, 3, 9, 'あなたは、レビ人をアロンとその子らに付けなさい。彼らはイスラエルの子らの中から、正式にアロンに付けられた者たちである。'),
('JPN', '民数记', 4, 3, 10, 'あなたは、アロンとその子らを任命して、その祭司の職を守らせなければならない。資格なしにこれに近づく者は殺されなければならない。」'),
('JPN', '民数记', 4, 3, 11, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 3, 12, '「見よ。わたしは、イスラエルの子らのうちで最初に胎を開いたすべての長子の代わりに、イスラエルの子らの中からレビ人を取ることにした。レビ人はわたしのものとなる。'),
('JPN', '民数记', 4, 3, 13, '長子はすべて、わたしのものだからである。エジプトの地でわたしがすべての長子を打った日に、わたしは、人から家畜に至るまで、イスラエルのうちのすべての長子をわたしのものとして聖別した。彼らはわたしのものである。わたしは主である。」'),
('JPN', '民数记', 4, 3, 14, '主はシナイの荒野でモーセに告げられた。'),
('JPN', '民数记', 4, 3, 15, '「レビ族をその一族ごと、氏族ごとに登録せよ。あなたは生後一か月以上のすべての男子を登録しなければならない。」'),
('JPN', '民数记', 4, 3, 16, 'そこでモーセは、主の命により、命じられたとおりに彼らを登録した。'),
('JPN', '民数记', 4, 3, 17, 'レビ族の名は次のとおりである。ゲルション、ケハテ、メラリ。'),
('JPN', '民数记', 4, 3, 18, 'ゲルション族の諸氏族の名は次のとおりである。リブニとシムイ。'),
('JPN', '民数记', 4, 3, 19, 'ケハテ族の諸氏族は、それぞれ、アムラムとイツハル、ヘブロンとウジエル。'),
('JPN', '民数记', 4, 3, 20, 'メラリ族の諸氏族は、それぞれ、マフリとムシ。これらが父祖の家ごとのレビ人の諸氏族である。'),
('JPN', '民数记', 4, 3, 21, 'リブニ族とシムイ族はゲルションに属し、これらがゲルション人諸氏族であった。'),
('JPN', '民数记', 4, 3, 22, '数を数えて登録された者は、一か月以上のすべての男子であり、この登録された者は、七千五百人であった。'),
('JPN', '民数记', 4, 3, 23, 'ゲルション人諸氏族は、幕屋のうしろ、西側に宿営することになっていた。'),
('JPN', '民数记', 4, 3, 24, 'ゲルション人の一族の長は、ラエルの子エルヤサフであった。'),
('JPN', '民数记', 4, 3, 25, '会見の天幕でのゲルション族の任務は、幕屋すなわち天幕と、その覆い、会見の天幕の入り口の垂れ幕、'),
('JPN', '民数记', 4, 3, 26, '庭の掛け幕、それに幕屋と祭壇の周りを取り巻く庭の入り口の垂れ幕およびそのひも──そしてそれに関わるすべての奉仕であった。'),
('JPN', '民数记', 4, 3, 27, 'アムラム族、イツハル族、ヘブロン族、ウジエル族はケハテに属し、これらがケハテ人諸氏族であった。'),
('JPN', '民数记', 4, 3, 28, 'これらの一か月以上のすべての男子を数えると、八千六百人であった。彼らが聖所の任務に当たる者たちである。'),
('JPN', '民数记', 4, 3, 29, 'ケハテ人諸氏族は、幕屋の南側に沿って宿営することになっていた。'),
('JPN', '民数记', 4, 3, 30, 'ケハテ人諸氏族の、一族の長は、ウジエルの子エリツァファンであった。'),
('JPN', '民数记', 4, 3, 31, '彼らの任務は、契約の箱、机、燭台、祭壇、務めに用いる聖所の用具、さらに垂れ幕とそれに関わるすべての奉仕を含んでいた。'),
('JPN', '民数记', 4, 3, 32, 'レビ人の長の長は祭司アロンの子エルアザルで、聖所の任務に当たる者たちの監督であった。'),
('JPN', '民数记', 4, 3, 33, 'マフリ族とムシ族はメラリに属し、これらがメラリ人諸氏族であった。'),
('JPN', '民数记', 4, 3, 34, '数を数えて登録された者は、一か月以上のすべての男子であり、六千二百人であった。'),
('JPN', '民数记', 4, 3, 35, 'メラリ人諸氏族の一族の長は、アビハイルの子ツリエルであった。彼らは幕屋の北側に沿って宿営することになっていた。'),
('JPN', '民数记', 4, 3, 36, 'メラリ族の任務は、幕屋の板、その横木、その柱と台座、そのすべての用具、およびそれに関わるすべての奉仕、'),
('JPN', '民数记', 4, 3, 37, '庭の周りの柱とその台座、その杭とそのひもについてであった。'),
('JPN', '民数记', 4, 3, 38, '幕屋の正面、すなわち会見の天幕の前方に当たる東側に宿営するのは、モーセとアロンまたその子らで、イスラエルの子らの任務に代わって、聖所の任務に当たる者たちであった。資格なしにこれに近づく者は殺されなければならない。'),
('JPN', '民数记', 4, 3, 39, 'モーセとアロンが主の命により氏族ごとに登録した、すべての登録されたレビ人は、一か月以上のすべての男子であり、二万二千人であった。'),
('JPN', '民数记', 4, 3, 40, '主はモーセに言われた。「イスラエルの子らの、一か月以上の男子の長子をすべて登録し、その名を数えよ。'),
('JPN', '民数记', 4, 3, 41, 'わたしは主である。あなたはイスラエルの子らのうちのすべての長子の代わりとしてレビ人を、またイスラエルの子らの家畜のうちのすべての初子の代わりとしてレビ人の家畜を取り、わたしのものにしなさい。」'),
('JPN', '民数记', 4, 3, 42, 'モーセは主が彼に命じられたとおりに、イスラエルの子らのうちのすべての長子を登録した。'),
('JPN', '民数记', 4, 3, 43, 'その登録による、名を数えられた、一か月以上のすべての男子の長子は、二万二千二百七十三人であった。'),
('JPN', '民数记', 4, 3, 44, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 3, 45, '「イスラエルの子らのすべての長子の代わりにレビ人を、また彼らの家畜の代わりにレビ人の家畜を取れ。レビ人はわたしのものでなければならない。わたしは主である。'),
('JPN', '民数记', 4, 3, 46, 'レビ人の数より多い、二百七十三人のイスラエルの子らの長子の贖いの代金として、'),
('JPN', '民数记', 4, 3, 47, '一人当たり五シェケルを取りなさい。これを、一シェケル二十ゲラの、聖所のシェケルで取らなければならない。'),
('JPN', '民数记', 4, 3, 48, 'そしてこの代金を、多い分の者たちの贖いの代金として、アロンとその子らに渡しなさい。」'),
('JPN', '民数记', 4, 3, 49, 'モーセは、レビ人によって贖われた者より多い分の者たちから、贖いの代金を取った。'),
('JPN', '民数记', 4, 3, 50, 'すなわち、イスラエルの子らの長子から、聖所のシェケルで千三百六十五シェケルの代金を取ったのである。'),
('JPN', '民数记', 4, 3, 51, 'モーセは主の命により、この贖いの代金をアロンとその子らに渡した。主がモーセに命じられたとおりである。'),
('JPN', '民数记', 4, 4, 1, '主はモーセとアロンに告げられた。'),
('JPN', '民数记', 4, 4, 2, '「レビ人のうち、ケハテ族の頭数を、その氏族ごと、一族ごとに調べよ。'),
('JPN', '民数记', 4, 4, 3, 'それは会見の天幕で任務に当たり、仕事をすることのできる三十歳以上五十歳までのすべての者である。'),
('JPN', '民数记', 4, 4, 4, 'ケハテ族の会見の天幕での奉仕は、最も聖なるものに関わることで、次のとおりである。'),
('JPN', '民数记', 4, 4, 5, '宿営が出発するときは、アロンとその子らが入って行って、仕切りの垂れ幕を取り降ろし、あかしの箱をそれでおおい、'),
('JPN', '民数记', 4, 4, 6, 'その上にじゅごんの皮の覆いを掛け、またその上に真っ青の布を広げ、担ぎ棒を通す。'),
('JPN', '民数记', 4, 4, 7, 'また、臨在の机の上に青色の布を広げ、その上に皿、ひしゃく、水差し、注ぎのささげ物のための瓶を載せ、またその上に常供のパンを置く。'),
('JPN', '民数记', 4, 4, 8, 'これらのものの上に緋色の撚り糸の布を広げ、じゅごんの皮の覆いでこれをおおい、担ぎ棒を通す。'),
('JPN', '民数记', 4, 4, 9, '青色の布を取って、燭台とともしび皿、芯切りばさみ、芯取り皿、また、燭台のために用いる、油のためのすべての器具をおおい、'),
('JPN', '民数记', 4, 4, 10, 'この燭台とそのすべての器具をじゅごんの皮の覆いの中に入れ、これを担ぎ台に載せる。'),
('JPN', '民数记', 4, 4, 11, 'また金の祭壇の上に青色の布を広げ、それをじゅごんの皮の覆いでおおい、担ぎ棒を通す。'),
('JPN', '民数记', 4, 4, 12, '聖所で務めに用いる用具をみな取り、青色の布の中に入れ、じゅごんの皮の覆いでそれをおおい、これを担ぎ台に載せ、'),
('JPN', '民数记', 4, 4, 13, '祭壇から灰を除き、紫色の布をその上に広げる。'),
('JPN', '民数记', 4, 4, 14, 'その上に、祭壇で用いるすべての用具、すなわち火皿、肉刺し、十能、鉢、これら祭壇のすべての用具を載せ、じゅごんの皮の覆いをその上に広げ、担ぎ棒を通す。'),
('JPN', '民数记', 4, 4, 15, '宿営が移動する際には、アロンとその子らが聖所と聖所のすべての用具をおおい終わってから、その後でケハテ族が入って行って、これらを運ばなければならない。彼らが聖なるものに触れて死ぬことのないようにするためである。これらは、会見の天幕でケハテ族が運ぶ物である。'),
('JPN', '民数记', 4, 4, 16, '祭司アロンの子エルアザルの責任は、ともしび用の油、香りの高い香、常供の穀物のささげ物、注ぎの油についてであり、幕屋全体とその中にあるすべての物、聖所とその用具についての責任である。」'),
('JPN', '民数记', 4, 4, 17, '主はモーセとアロンにこう告げられた。'),
('JPN', '民数记', 4, 4, 18, '「あなたがたは、ケハテ人諸氏族の部族をレビ人のうちから絶えさせてはならない。'),
('JPN', '民数记', 4, 4, 19, 'あなたがたは彼らに次のようにして、彼らが最も聖なるものに近づくときに、死なずに生きているようにせよ。アロンとその子らが入って行き、彼らにそれぞれの奉仕と、運ぶ物を指定しなければならない。'),
('JPN', '民数记', 4, 4, 20, '彼らが入って行って、一目でも聖なるものを見て死ぬことのないようにするためである。」'),
('JPN', '民数记', 4, 4, 21, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 4, 22, '「あなたはまた、ゲルション族の頭数を、その一族ごと、氏族ごとに調べ、'),
('JPN', '民数记', 4, 4, 23, '三十歳以上五十歳までの者で会見の天幕で任務に当たり、奉仕をすることのできる者をすべて登録しなければならない。'),
('JPN', '民数记', 4, 4, 24, 'ゲルション人諸氏族のなすべき奉仕と運ぶ物は次のとおりである。'),
('JPN', '民数记', 4, 4, 25, '幕屋の幕、会見の天幕とその覆い、その上に掛けるじゅごんの皮の覆い、会見の天幕の入り口の垂れ幕を運び、'),
('JPN', '民数记', 4, 4, 26, 'また庭の掛け幕、幕屋と祭壇の周りを取り巻く庭の門の入り口の垂れ幕、それらのひも、およびそれらに用いるすべての用具を運び、これらに関係するすべての奉仕をしなければならない。'),
('JPN', '民数记', 4, 4, 27, 'ゲルション族のすべての奉仕、すなわち、彼らが運ぶすべての物と彼らのすべての仕事は、アロンとその子らの命令によらなければならない。あなたがたは彼らに、任務として、彼らが運ぶ物をすべて割り当てなければならない。'),
('JPN', '民数记', 4, 4, 28, '以上がゲルション人諸氏族の会見の天幕における奉仕で、彼らの任務は祭司アロンの子イタマルの指揮下にある。'),
('JPN', '民数记', 4, 4, 29, 'メラリ族について、あなたはその氏族ごと、一族ごとに、彼らを登録しなければならない。'),
('JPN', '民数记', 4, 4, 30, '三十歳以上五十歳までの者で、務めに就き、会見の天幕の奉仕をすることができる者たちをすべて、登録しなければならない。'),
('JPN', '民数记', 4, 4, 31, '会見の天幕での彼らのすべての奉仕の中で、彼らが任務として運ぶ物は次のとおりである。幕屋の板、その横木、その柱とその台座、'),
('JPN', '民数记', 4, 4, 32, '庭の周りの柱と、その台座、杭、ひも、これらの備品と、その奉仕に使うすべての物である。あなたがたは、彼らが任務として運ぶ備品を、名を挙げて割り当てなければならない。'),
('JPN', '民数记', 4, 4, 33, 'これが会見の天幕でのすべての仕事に関するメラリ人諸氏族の奉仕で、これは祭司アロンの子イタマルの指揮下にある。」'),
('JPN', '民数记', 4, 4, 34, 'そこでモーセとアロンと会衆の上に立つ族長たちは、ケハテ族をその氏族ごと、一族ごとに、'),
('JPN', '民数记', 4, 4, 35, '三十歳以上五十歳までの者で、会見の天幕での奉仕の務めに就くことのできる者を、すべて登録した。'),
('JPN', '民数记', 4, 4, 36, 'その氏族ごとに登録された者は、二千七百五十人であった。'),
('JPN', '民数记', 4, 4, 37, 'これはケハテ人諸氏族で登録された者であって、会見の天幕で奉仕する者の全員であり、モーセを通して示された主の命によって、モーセとアロンが登録した者たちである。'),
('JPN', '民数记', 4, 4, 38, 'ゲルション族で、その氏族ごと、一族ごとに登録され、'),
('JPN', '民数记', 4, 4, 39, '三十歳以上五十歳までの者で、会見の天幕での奉仕の務めに就くことのできる者の全員、'),
('JPN', '民数记', 4, 4, 40, 'その氏族ごと、一族ごとに登録された者は、二千六百三十人であった。'),
('JPN', '民数记', 4, 4, 41, 'これはゲルション人諸氏族で登録された者たちで、会見の天幕で奉仕する者の全員であり、主の命により、モーセとアロンが登録した者たちである。'),
('JPN', '民数记', 4, 4, 42, 'メラリ人諸氏族で、その氏族ごと、一族ごとに登録され、'),
('JPN', '民数记', 4, 4, 43, '三十歳以上五十歳までの者で、会見の天幕での奉仕の務めに就くことのできる者の全員、'),
('JPN', '民数记', 4, 4, 44, 'その氏族ごとに登録された者は、三千二百人であった。'),
('JPN', '民数记', 4, 4, 45, 'これはメラリ人諸氏族で登録された者であり、モーセを通して示された主の命により、モーセとアロンが登録した者たちである。'),
('JPN', '民数记', 4, 4, 46, 'モーセとアロンとイスラエルの族長たちが、レビ人を、その氏族ごと、一族ごとに登録した登録者の全員、'),
('JPN', '民数记', 4, 4, 47, '三十歳以上五十歳までの者で、会見の天幕で労働の奉仕と運搬の奉仕をする者の全員、'),
('JPN', '民数记', 4, 4, 48, 'その登録された者は、八千五百八十人であった。'),
('JPN', '民数记', 4, 4, 49, '彼らは主の命により、モーセを通して任じられ、それぞれその奉仕とその運ぶ物を受け持った。主がモーセに命じた、主によって登録された者たちである。'),
('JPN', '民数记', 4, 5, 1, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 5, 2, '「イスラエルの子らに命じて、ツァラアトに冒された者、漏出を病む者、死体によって身を汚している者をすべて宿営の外に追い出せ。'),
('JPN', '民数记', 4, 5, 3, '男でも女でも追い出し、彼らを宿営の外に追い出し、わたしがそのただ中に住む宿営を、彼らが汚さないようにしなければならない。」'),
('JPN', '民数记', 4, 5, 4, 'イスラエルの子らはそのようにして、彼らを宿営の外に追い出した。主がモーセに告げられたとおりにイスラエルの子らは行った。'),
('JPN', '民数记', 4, 5, 5, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 5, 6, '「イスラエルの子らに告げよ。男にせよ、女にせよ、他人に何か一つでも罪となることを行って主の信頼を裏切り、後になって、その人自身がその責めを覚えたときは、'),
('JPN', '民数记', 4, 5, 7, '自分が行った罪を告白しなければならない。その人は償いとして総額を弁償し、それにその五分の一を加えて、償いの責めを果たすべき相手に支払わなければならない。'),
('JPN', '民数记', 4, 5, 8, 'もしその相手の人に、償いを受け取る権利のある親類がいなければ、その咎のために弁償されたものは主のものであり、祭司のものとなる。そのほか、その人のために宥めを行うための、宥めの雄羊もそうなる。'),
('JPN', '民数记', 4, 5, 9, 'こうして、イスラエルの子らが祭司のところに携えて来るすべての聖なるものは、どの奉納物も祭司のものとなる。'),
('JPN', '民数记', 4, 5, 10, '聖なるささげ物は、人のもとにあればその人のものであるが、人が祭司に与えるものは祭司のものとなる。」'),
('JPN', '民数记', 4, 5, 11, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 5, 12, '「イスラエルの子らに告げよ。もし人の妻が道を外して夫の信頼を裏切り、'),
('JPN', '民数记', 4, 5, 13, 'ほかの男が彼女と寝て交わり、そのことが夫の目から隠れていて、彼女が身を汚したことが見つからず、証人もなく、彼女が捕らえられないままであるが、'),
('JPN', '民数记', 4, 5, 14, '妻が身を汚していて、夫にねたみの心が起こり、妻に対して憤る場合、あるいは妻が身を汚していないのに、夫にねたみの心が起こり、妻に対して憤る場合、'),
('JPN', '民数记', 4, 5, 15, '夫は妻を祭司のところに連れて行き、彼女のために大麦の粉十分の一エパをささげ物として携えて行きなさい。この上に油を注いでも乳香を加えてもいけない。これはねたみのためのささげ物、咎を思い出させる、覚えの分としての穀物のささげ物だからである。'),
('JPN', '民数记', 4, 5, 16, '祭司は、その女を進み出させ、主の前に立たせる。'),
('JPN', '民数记', 4, 5, 17, '祭司は聖なる水を土の器に取る。そして祭司は幕屋の床にある土のちりを取って、その水に入れる。'),
('JPN', '民数记', 4, 5, 18, '祭司は女を主の前に立たせ、その女の髪の毛を乱れさせて、その両方の手のひらに、覚えの分としての穀物のささげ物、すなわち、ねたみのためのささげ物を置く。一方、祭司の手には、のろいをもたらす苦みの水があるようにする。'),
('JPN', '民数记', 4, 5, 19, '祭司は女に誓わせて、この女に言う。『もし、ほかの男があなたと寝たことがなく、またあなたが夫のもとにあるのに、道ならぬことをして身を汚したことがないなら、あなたは、のろいをもたらすこの苦みの水の害を受けないように。'),
('JPN', '民数记', 4, 5, 20, 'しかし、もしあなたが夫のもとにあるのに、道ならぬことをして身を汚し、夫以外の男があなたと寝たのであれば──』'),
('JPN', '民数记', 4, 5, 21, 'ここで祭司はその女にのろいの誓いを立てさせて、その女に言う。『主があなたのももを痩せ衰えさせ、あなたの腹をふくれさせ、あなたの民のうちにあって、主があなたをのろいと非難の的とされるように。'),
('JPN', '民数记', 4, 5, 22, 'また、のろいをもたらすこの水があなたのからだに入って腹をふくれさせ、ももを痩せ衰えさせるように。』そしてその女は、『アーメン、アーメン』と言う。'),
('JPN', '民数记', 4, 5, 23, '祭司はこののろいを書き物に書き、それを苦みの水の中に洗い落とす。'),
('JPN', '民数记', 4, 5, 24, 'のろいをもたらすこの苦みの水を彼女に飲ませると、のろいをもたらす水が彼女の中に入って、苦くなる。'),
('JPN', '民数记', 4, 5, 25, '祭司は女の手から、ねたみのためのささげ物を取り、この穀物のささげ物を主に向かって揺り動かし、それを祭壇に近づける。'),
('JPN', '民数记', 4, 5, 26, '祭司は、穀物のささげ物から、覚えの分としてひとつかみを取り、それを祭壇で焼いて煙にする。その後で女に先の水を飲ませる。'),
('JPN', '民数记', 4, 5, 27, 'その水を飲ませたとき、もし、その女が夫の信頼を裏切って身を汚していれば、のろいをもたらす水はその女の中に入って苦くなり、その腹はふくれて、そのももは痩せ衰える。その女はその民の間で、のろいの的となる。'),
('JPN', '民数记', 4, 5, 28, 'しかし、もし女が身を汚しておらず、きよければ、罰を免れて、子を宿すようになる。'),
('JPN', '民数记', 4, 5, 29, 'これが、ねたみについてのおしえである。女が夫のもとにあるのに、道ならぬことをして身を汚したり、'),
('JPN', '民数记', 4, 5, 30, 'または夫にねたみの心が起こって、自分の妻に対して憤ったりする場合には、その妻を主の前に立たせる。そして祭司は彼女にこのおしえのすべてを行う。'),
('JPN', '民数记', 4, 5, 31, '夫に咎はなく、妻が自分の咎を負うのである。」'),
('JPN', '民数记', 4, 6, 1, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 6, 2, '「イスラエルの子らに告げよ。男または女が、主のものとして身を聖別するため特別な誓いをして、ナジル人の誓願を立てる場合、'),
('JPN', '民数记', 4, 6, 3, 'その人は、ぶどう酒や強い酒を断たなければならない。ぶどう酒の酢や強い酒の酢を飲んではならない。また、ぶどう汁をいっさい飲んではならない。ぶどうの実の生のものも、干したものも食べてはならない。'),
('JPN', '民数记', 4, 6, 4, 'ナジル人としての聖別の全期間、彼はぶどうの木から生じるものはすべて、種も皮も食べてはならない。'),
('JPN', '民数记', 4, 6, 5, '彼がナジル人としての聖別の誓願を立てている間は、頭にかみそりを当ててはならない。主のものとして身を聖別している期間が満ちるまで、彼は聖なるものであり、頭の髪の毛を伸ばしておかなければならない。'),
('JPN', '民数记', 4, 6, 6, '主のものとして身を聖別している間は、死人のところに入って行ってはならない。'),
('JPN', '民数记', 4, 6, 7, '父、母、兄弟、姉妹が死んだ場合でも、彼らとの関わりで身を汚してはならない。彼の頭には神への聖別のしるしがあるからである。'),
('JPN', '民数记', 4, 6, 8, 'ナジル人としての聖別の全期間、彼は主に対して聖なるものである。'),
('JPN', '民数记', 4, 6, 9, 'だれかが突然、彼のそばで死んで、その聖別された頭を汚した場合には、身をきよめる日に頭を剃る。すなわち七日目に剃る。'),
('JPN', '民数记', 4, 6, 10, 'そして八日目に、山鳩二羽か家鳩のひな二羽を、会見の天幕の入り口にいる祭司のところに持って行く。'),
('JPN', '民数记', 4, 6, 11, '祭司はその一羽を罪のきよめのささげ物とし、もう一羽を全焼のささげ物として献げ、死体によって招いた罪を除いて彼のために宥めを行い、その日に彼の頭を聖なるものとする。'),
('JPN', '民数记', 4, 6, 12, 'その人は、ナジル人としての聖別の期間を、改めて主のものとして聖別する。そして一歳の雄の子羊を携えて行き、代償のささげ物とする。それ以前の日数は、彼の聖別が汚されたので無効になる。'),
('JPN', '民数记', 4, 6, 13, 'これはナジル人についてのおしえである。ナジル人としての聖別の期間が満ちたときは、彼を会見の天幕の入り口に連れて行く。'),
('JPN', '民数记', 4, 6, 14, '彼は次のささげ物を主に献げる。すなわち、全焼のささげ物として傷のない一歳の雄の子羊一匹、罪のきよめのささげ物として傷のない一歳の雌の子羊一匹、交わりのいけにえとして傷のない雄羊一匹、'),
('JPN', '民数记', 4, 6, 15, 'さらに穀物のささげ物として、種なしパン一かご、油を混ぜた小麦粉の輪形パン、油を塗った種なしの薄焼きパンを、それぞれに添える注ぎのささげ物とともに献げる。'),
('JPN', '民数记', 4, 6, 16, '祭司はこれらのものを主の前に近づけ、罪のきよめのささげ物と全焼のささげ物を献げる。'),
('JPN', '民数记', 4, 6, 17, '交わりのいけにえとして雄羊を、一かごの種なしパンとともに主に献げ、さらに祭司は穀物のささげ物と注ぎのささげ物を献げる。'),
('JPN', '民数记', 4, 6, 18, 'ナジル人は会見の天幕の入り口で、聖別した頭を剃り、その聖別した頭の髪の毛を取って、交わりのいけにえの下にある火にくべる。'),
('JPN', '民数记', 4, 6, 19, 'ナジル人がその聖別した髪の毛を剃った後、祭司は煮えた雄羊の肩と、かごの中の種なしの輪形パン一つと、種なしの薄焼きパン一つを取って、ナジル人の手の上に載せる。'),
('JPN', '民数记', 4, 6, 20, '祭司はこれらを奉献物として主の前で揺り動かす。これは聖なるものであって、奉献物の胸肉、奉納物のもも肉とともに祭司のものとなる。その後で、このナジル人はぶどう酒を飲むことができる。'),
('JPN', '民数记', 4, 6, 21, 'これがナジル人についてのおしえである。ナジル人としての聖別に加えて、その人の力の及ぶ以上に主へのささげ物を誓う者は、ナジル人としての聖別のおしえに加えて、その誓った誓いのことばどおりにしなければならない。」'),
('JPN', '民数记', 4, 6, 22, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 6, 23, '「アロンとその子らに告げよ。『あなたがたはイスラエルの子らに言って、彼らをこのように祝福しなさい。'),
('JPN', '民数记', 4, 6, 24, '主があなたを祝福し、あなたを守られますように。'),
('JPN', '民数记', 4, 6, 25, '主が御顔をあなたに照らし、あなたを恵まれますように。'),
('JPN', '民数记', 4, 6, 26, '主が御顔をあなたに向け、あなたに平安を与えられますように。』'),
('JPN', '民数记', 4, 6, 27, 'アロンとその子らが、わたしの名をイスラエルの子らの上に置くなら、わたしが彼らを祝福する。」'),
('JPN', '民数记', 4, 7, 1, 'モーセは幕屋を設営し終えた日に、これに油注ぎをして、聖別した。そのすべての器具と、祭壇およびそのすべての用具にもそうした。彼がそれらに油注ぎをして聖別したとき、'),
('JPN', '民数记', 4, 7, 2, 'イスラエルの族長たち、すなわち一族のかしらたちが近づいた。彼らは部族の長たちで、登録に当たった者たちである。'),
('JPN', '民数记', 4, 7, 3, '彼らは自分たちのささげ物を主の前に持って来た。それは覆いのある台車六台と雄牛十二頭で、族長二人につき車一台、一人につき牛一頭であった。彼らはこれを幕屋の前に引いて来た。'),
('JPN', '民数记', 4, 7, 4, 'すると主はモーセに告げられた。'),
('JPN', '民数记', 4, 7, 5, '「会見の天幕の奉仕に使うために彼らからこれらを受け取り、レビ人にそれぞれの奉仕に応じて渡せ。」'),
('JPN', '民数记', 4, 7, 6, 'そこでモーセは台車と雄牛を受け取り、それをレビ人に与えた。'),
('JPN', '民数记', 4, 7, 7, 'ゲルション族には、その奉仕に応じて台車二台と雄牛四頭を与え、'),
('JPN', '民数记', 4, 7, 8, 'メラリ族には、祭司アロンの子イタマルの監督のもとにある彼らの奉仕に応じて、台車四台と雄牛八頭を与えた。'),
('JPN', '民数记', 4, 7, 9, 'しかしケハテ族には何も与えなかった。彼らの聖なるものに関わる奉仕は、肩に担いで運ぶことだったからである。'),
('JPN', '民数记', 4, 7, 10, '祭壇に油注ぎが行われた日に、族長たちは祭壇奉献のためのささげ物を献げた。族長たちが自分たちのささげ物を祭壇の前に近づけたとき、'),
('JPN', '民数记', 4, 7, 11, '主はモーセに言われた。「族長たちは一日に一人ずつの割合で、祭壇奉献のために彼らのささげ物を献げなければならない。」'),
('JPN', '民数记', 4, 7, 12, '最初の日にささげ物を献げたのは、ユダ部族のアミナダブの子ナフションであった。'),
('JPN', '民数记', 4, 7, 13, 'そのささげ物は、聖所のシェケルで重さ百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 14, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 15, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 16, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 17, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがアミナダブの子ナフションのささげ物であった。'),
('JPN', '民数记', 4, 7, 18, '二日目にはイッサカルの族長、ツアルの子ネタンエルが献げた。'),
('JPN', '民数记', 4, 7, 19, '彼は、ささげ物として聖所のシェケルで重さ百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つを献げた。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 20, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 21, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 22, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 23, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがツアルの子ネタンエルのささげ物であった。'),
('JPN', '民数记', 4, 7, 24, '三日目は、ゼブルン族の族長、ヘロンの子エリアブ。'),
('JPN', '民数记', 4, 7, 25, 'そのささげ物は、聖所のシェケルで重さ百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 26, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 27, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 28, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 29, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがヘロンの子エリアブのささげ物であった。'),
('JPN', '民数记', 4, 7, 30, '四日目は、ルベン族の族長、シェデウルの子エリツル。'),
('JPN', '民数记', 4, 7, 31, 'そのささげ物は、聖所のシェケルで百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 32, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 33, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 34, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 35, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがシェデウルの子エリツルのささげ物であった。'),
('JPN', '民数记', 4, 7, 36, '五日目は、シメオン族の族長、ツリシャダイの子シェルミエル。'),
('JPN', '民数记', 4, 7, 37, 'そのささげ物は、聖所のシェケルで百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 38, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 39, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 40, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 41, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがツリシャダイの子シェルミエルのささげ物であった。'),
('JPN', '民数记', 4, 7, 42, '六日目は、ガド族の族長、デウエルの子エルヤサフ。'),
('JPN', '民数记', 4, 7, 43, 'そのささげ物は、聖所のシェケルで百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 44, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 45, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 46, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 47, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがデウエルの子エルヤサフのささげ物であった。'),
('JPN', '民数记', 4, 7, 48, '七日目は、エフライム族の族長、アミフデの子エリシャマ。'),
('JPN', '民数记', 4, 7, 49, 'そのささげ物は、聖所のシェケルで百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 50, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 51, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 52, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 53, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがアミフデの子エリシャマのささげ物であった。'),
('JPN', '民数记', 4, 7, 54, '八日目は、マナセ族の族長、ペダツルの子ガムリエル。'),
('JPN', '民数记', 4, 7, 55, 'そのささげ物は、聖所のシェケルで百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 56, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 57, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 58, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 59, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがペダツルの子ガムリエルのささげ物であった。'),
('JPN', '民数记', 4, 7, 60, '九日目は、ベニヤミン族の族長、ギデオニの子アビダン。'),
('JPN', '民数记', 4, 7, 61, 'そのささげ物は、聖所のシェケルで百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 62, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 63, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 64, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 65, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがギデオニの子アビダンのささげ物であった。'),
('JPN', '民数记', 4, 7, 66, '十日目は、ダン族の族長、アミシャダイの子アヒエゼル。'),
('JPN', '民数记', 4, 7, 67, 'そのささげ物は、聖所のシェケルで百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 68, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 69, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 70, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 71, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがアミシャダイの子アヒエゼルのささげ物であった。'),
('JPN', '民数记', 4, 7, 72, '十一日目は、アシェル族の族長、オクランの子パグイエル。'),
('JPN', '民数记', 4, 7, 73, 'そのささげ物は、聖所のシェケルで百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 74, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 75, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 76, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 77, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがオクランの子パグイエルのささげ物であった。'),
('JPN', '民数记', 4, 7, 78, '十二日目は、ナフタリ族の族長、エナンの子アヒラ。'),
('JPN', '民数记', 4, 7, 79, 'そのささげ物は、聖所のシェケルで百三十シェケルの銀の皿一枚、七十シェケルの銀の鉢一つ。この二つには穀物のささげ物として、油を混ぜた小麦粉がいっぱいに入れてあった。'),
('JPN', '民数记', 4, 7, 80, 'また香を満たした十シェケルの金のひしゃく一つ。'),
('JPN', '民数记', 4, 7, 81, '全焼のささげ物として若い雄牛一頭、雄羊一匹、一歳の雄の子羊一匹。'),
('JPN', '民数记', 4, 7, 82, '罪のきよめのささげ物として雄やぎ一匹。'),
('JPN', '民数记', 4, 7, 83, '交わりのいけにえとして雄牛二頭、雄羊五匹、雄やぎ五匹、一歳の雄の子羊五匹。これがエナンの子アヒラのささげ物であった。'),
('JPN', '民数记', 4, 7, 84, '以上が、祭壇に油注ぎが行われた日に、イスラエルの族長たちから献げられた、祭壇奉献のささげ物であった。すなわち、銀の皿十二、銀の鉢十二、金のひしゃく十二。'),
('JPN', '民数记', 4, 7, 85, '銀の皿はそれぞれ百三十シェケル、鉢はそれぞれ七十シェケル。これらの器の銀は、合わせて、聖所のシェケルで二千四百シェケル。'),
('JPN', '民数记', 4, 7, 86, '香を満たした十二の金のひしゃくは、聖所のシェケルでそれぞれ十シェケル。ひしゃくの金は、合わせて百二十シェケル。'),
('JPN', '民数记', 4, 7, 87, '全焼のささげ物として、家畜は合わせて、雄牛十二頭、雄羊十二匹、一歳の雄の子羊十二匹、それに、それらに添える穀物のささげ物。また罪のきよめのささげ物として雄やぎ十二匹。'),
('JPN', '民数记', 4, 7, 88, '交わりのいけにえとして、家畜は合わせて、雄牛二十四頭、雄羊六十匹、雄やぎ六十匹、一歳の雄の子羊六十匹。これが祭壇に油注ぎが行われた後の、祭壇奉献のためのささげ物であった。'),
('JPN', '民数记', 4, 7, 89, 'モーセは、主と語るために会見の天幕に入ると、あかしの箱の上にある「宥めの蓋」の上から、すなわち二つのケルビムの間から、彼に語られる御声を聞いた。主は彼に語られた。'),
('JPN', '民数记', 4, 8, 1, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 8, 2, '「アロンに告げよ。『あなたがともしび皿を載せるとき、七つのともしび皿が燭台の前を照らすようにしなさい』と。」'),
('JPN', '民数记', 4, 8, 3, 'アロンはそのようにした。主がモーセに命じられたとおりに、燭台の前に向けてともしび皿を載せた。'),
('JPN', '民数记', 4, 8, 4, '燭台の作りは次のとおりであった。それは金の打ち物で、その台座から花弁に至るまで打ち物であった。主がモーセに示された型のとおりに、この燭台は作られていた。'),
('JPN', '民数记', 4, 8, 5, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 8, 6, '「レビ人をイスラエルの子らの中から取って、彼らをきよめよ。'),
('JPN', '民数记', 4, 8, 7, 'あなたは次のようにして彼らをきよめなければならない。罪のきよめの水を彼らにかける。彼らは全身にかみそりを当て、その衣服を洗い、身をきよめる。'),
('JPN', '民数记', 4, 8, 8, 'そして若い雄牛と油を混ぜた小麦粉の穀物のささげ物を取る。あなたはまた別の若い雄牛を罪のきよめのささげ物として取る。'),
('JPN', '民数记', 4, 8, 9, 'あなたはレビ人を会見の天幕の前に近づかせ、イスラエルの全会衆を集め、'),
('JPN', '民数记', 4, 8, 10, 'レビ人を主の前に進ませる。イスラエルの子らは手をレビ人の上に置く。'),
('JPN', '民数记', 4, 8, 11, 'アロンはレビ人を、イスラエルの子らからの奉献物として主の前に献げる。これは彼らが主の奉仕をするためである。'),
('JPN', '民数记', 4, 8, 12, 'レビ人は、雄牛の頭に手を置く。そこであなたは一頭を罪のきよめのささげ物として、また一頭を全焼のささげ物として主に献げ、レビ人のために宥めを行う。'),
('JPN', '民数记', 4, 8, 13, 'あなたはレビ人をアロンとその子らの前に立たせ、彼らを奉献物として主に献げる。'),
('JPN', '民数记', 4, 8, 14, 'こうして、あなたはレビ人をイスラエルの子らのうちから分け、レビ人はわたしのものとなる。'),
('JPN', '民数记', 4, 8, 15, 'この後、レビ人は会見の天幕に入って奉仕をすることができる。あなたは彼らをきよめ、彼らを奉献物として献げなければならない。'),
('JPN', '民数记', 4, 8, 16, '彼らはイスラエルの子らのうちから正式にわたしに与えられたものだからである。すべてのイスラエルの子らのうちで、最初に胎を開いた、すべての長子の代わりに、わたしは彼らをわたしのものとして取ったのである。'),
('JPN', '民数记', 4, 8, 17, 'イスラエルの子らのうちでは、人でも家畜でも、すべての長子はわたしのものだからである。エジプトの地で、わたしがすべての長子を打った日に、わたしは彼らを聖別してわたしのものとした。'),
('JPN', '民数记', 4, 8, 18, 'わたしは、イスラエルの子らのうちのすべての長子の代わりにレビ人を取った。'),
('JPN', '民数记', 4, 8, 19, 'わたしは、イスラエルの子らのうちからレビ人をアロンとその子らに正式に付け、会見の天幕でイスラエルの子らの奉仕をし、イスラエルの子らのために宥めを行うようにした。それは、イスラエルの子らが聖所に近づいて、彼らにわざわいが及ぶことのないようにするためである。」'),
('JPN', '民数记', 4, 8, 20, 'モーセとアロンとイスラエルの全会衆は、レビ人に対してそのようにした。主がレビ人についてモーセに命じられたことすべてにしたがって、イスラエルの子らは彼らに行った。'),
('JPN', '民数记', 4, 8, 21, 'レビ人は身の汚れを除き、その衣服を洗った。そうしてアロンは彼らを奉献物として主の前に献げた。またアロンは彼らのために宥めを行い、彼らをきよめた。'),
('JPN', '民数记', 4, 8, 22, 'この後、レビ人は会見の天幕に入って、アロンとその子らの前で自分たちの奉仕をした。人々は主がレビ人についてモーセに命じられたとおりに、レビ人に行った。'),
('JPN', '民数记', 4, 8, 23, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 8, 24, '「これはレビ人に関わることである。二十五歳以上の者は、会見の天幕の奉仕の務めを果たさなければならない。'),
('JPN', '民数记', 4, 8, 25, 'しかし、五十歳からは奉仕の務めから退き、もう奉仕してはならない。'),
('JPN', '民数记', 4, 8, 26, 'その人はただ、会見の天幕で、自分の同族の者が任務に当たるのを助けることはできるが、自分で奉仕をしてはならない。あなたはレビ人に、彼らの任務に関してこのようにしなければならない。」'),
('JPN', '民数记', 4, 9, 1, 'エジプトの地を出て二年目の第一の月に、主はシナイの荒野でモーセに告げられた。'),
('JPN', '民数记', 4, 9, 2, '「イスラエルの子らは、定められた時に、過越のいけにえを献げよ。'),
('JPN', '民数记', 4, 9, 3, 'あなたがたはこの月の十四日の夕暮れ、その定められた時に、それを献げなければならない。それについてのすべての掟とすべての定めにしたがって、それをしなければならない。」'),
('JPN', '民数记', 4, 9, 4, 'モーセがイスラエルの子らに、過越のいけにえを献げるように告げたので、'),
('JPN', '民数记', 4, 9, 5, '彼らはシナイの荒野で第一の月の十四日の夕暮れに過越のいけにえを献げた。イスラエルの子らは、すべて主がモーセに命じられたとおりに行った。'),
('JPN', '民数记', 4, 9, 6, 'しかし、人の死体によって汚れていて、その日に過越のいけにえを献げることができなかった人たちがいた。彼らはその日、モーセとアロンの前に進み出た。'),
('JPN', '民数记', 4, 9, 7, 'その人たちは彼に言った。「私たちは、人の死体によって汚れていますが、なぜ、イスラエルの子らの中で、定められた時に主へのささげ物を献げることを禁じられているのでしょうか。」'),
('JPN', '民数记', 4, 9, 8, 'モーセは彼らに言った。「待っていなさい。私は主があなたがたについてどのように命じられるかを聞こう。」'),
('JPN', '民数记', 4, 9, 9, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 9, 10, '「イスラエルの子らに告げよ。あなたがたのうち、またはあなたがたの子孫のうちで、人の死体によって身を汚している者、あるいは、遠い旅路にある者はみな、過越のいけにえを主に献げることができる。'),
('JPN', '民数记', 4, 9, 11, 'その人たちは、第二の月の十四日の夕暮れに、それを献げなければならない。種なしパンと苦菜と一緒にそれを食べなければならない。'),
('JPN', '民数记', 4, 9, 12, 'そのうちの少しでも朝まで残してはならない。また、その骨は折ってはならない。すべて過越のいけにえの掟のとおり、それを献げなければならない。'),
('JPN', '民数记', 4, 9, 13, '身がきよく、また旅にも出ていない者が、過越のいけにえを献げることをしないなら、その人は自分の民から断ち切られる。その人は定められた時に主へのささげ物を献げなかったので、自分の罪責を負う。'),
('JPN', '民数记', 4, 9, 14, 'もし、あなたがたのところに寄留者が滞在していて、主に過越のいけにえを献げようとするなら、過越のいけにえの掟と、その定めとにしたがって献げなければならない。寄留者でも、この国に生まれた者でも、あなたがたには掟は一つである。」'),
('JPN', '民数记', 4, 9, 15, '幕屋が設営された日、雲が、あかしの天幕である幕屋をおおった。それは、夕方には幕屋の上にあって朝まで火のようであった。'),
('JPN', '民数记', 4, 9, 16, 'いつもこのようであって、昼は雲がそれをおおい、夜は火のように見えた。'),
('JPN', '民数记', 4, 9, 17, 'いつでも雲が天幕から上るときには、その後でイスラエルの子らは旅立った。また、雲がとどまるその場所で、イスラエルの子らは宿営した。'),
('JPN', '民数记', 4, 9, 18, '主の命によりイスラエルの子らは旅立ち、主の命により宿営した。雲が幕屋の上にとどまっている間、彼らは宿営した。'),
('JPN', '民数记', 4, 9, 19, '雲が長い間、幕屋の上にとどまるときには、イスラエルの子らは主への務めを守って、旅立たなかった。'),
('JPN', '民数记', 4, 9, 20, 'また、雲がわずかの間しか幕屋の上にとどまらないことがあっても、彼らは主の命により宿営し、主の命により旅立った。'),
('JPN', '民数记', 4, 9, 21, '雲が夕方から朝までとどまるようなときがあっても、朝になって雲が上れば、彼らは旅立った。昼でも夜でも、雲が上れば旅立った。'),
('JPN', '民数记', 4, 9, 22, '二日でも、一月でも、あるいは一年でも、雲が幕屋の上にとどまって、去らなければ、イスラエルの子らは宿営を続けて旅立たなかった。しかし、雲が上ったときは旅立った。'),
('JPN', '民数记', 4, 9, 23, '彼らは主の命により宿営し、主の命により旅立った。彼らはモーセを通して示された主の命により、主への務めを守った。'),
('JPN', '民数记', 4, 10, 1, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 10, 2, '「銀のラッパを二本作りなさい。それを打ち物作りとしなさい。あなたはそれを用いて会衆を召し出したり、宿営を出発させたりしなければならない。'),
('JPN', '民数记', 4, 10, 3, 'これらが長く吹き鳴らされると、全会衆が会見の天幕の入り口の、あなたのところに集まる。'),
('JPN', '民数记', 4, 10, 4, 'もしその一つが吹き鳴らされると、イスラエルの分団のかしらである族長たちがあなたのところに集まる。'),
('JPN', '民数记', 4, 10, 5, 'また、短く吹き鳴らすと、東側に宿っている宿営が出発する。'),
('JPN', '民数记', 4, 10, 6, '二度目に短く吹き鳴らすと、南側に宿っている宿営が出発する。彼らが出発するためには、短く吹き鳴らさなければならない。'),
('JPN', '民数记', 4, 10, 7, '集会を召集するときには、長く吹き鳴らさなければならない。短く大きく吹き鳴らしてはならない。'),
('JPN', '民数记', 4, 10, 8, '祭司であるアロンの子らがラッパを吹かなければならない。これはあなたがたにとって、代々にわたる永遠の掟である。'),
('JPN', '民数记', 4, 10, 9, 'また、あなたがたの地で、自分たちを襲う侵略者との戦いに出るときには、ラッパを短く大きく吹き鳴らす。あなたがたが、自分たちの神、主の前に覚えられ、敵から救われるためである。'),
('JPN', '民数记', 4, 10, 10, 'また、あなたがたの喜びの日、あなたがたの例祭と新月の日に、自分たちの全焼のささげ物と交わりのいけにえの上にラッパを吹き鳴らすなら、あなたがたは自分たちの神の前に覚えられる。わたしはあなたがたの神、主である。」'),
('JPN', '民数记', 4, 10, 11, '二年目の第二の月の二十日に、雲があかしの幕屋の上から離れて上った。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '民数记', 4, 10, 12, 'それでイスラエルの子らはシナイの荒野を旅立った。雲はパランの荒野でとどまった。'),
('JPN', '民数记', 4, 10, 13, '彼らは、モーセを通して示された主の命により初めて旅立った。'),
('JPN', '民数记', 4, 10, 14, 'まず初めにユダ族の宿営の旗が、その軍団ごとに出発した。軍団長はアミナダブの子ナフション。'),
('JPN', '民数记', 4, 10, 15, 'イッサカル部族の軍団長はツアルの子ネタンエル。'),
('JPN', '民数记', 4, 10, 16, 'ゼブルン部族の軍団長はヘロンの子エリアブ。'),
('JPN', '民数记', 4, 10, 17, '幕屋が取り外され、幕屋を運ぶゲルション族、メラリ族が出発。'),
('JPN', '民数记', 4, 10, 18, 'ルベンの宿営の旗が、その軍団ごとに出発。軍団長はシェデウルの子エリツル。'),
('JPN', '民数记', 4, 10, 19, 'シメオン部族の軍団長はツリシャダイの子シェルミエル。'),
('JPN', '民数记', 4, 10, 20, 'ガド部族の軍団長はデウエルの子エルヤサフ。'),
('JPN', '民数记', 4, 10, 21, '聖なるものを運ぶケハテ人が出発。なお、幕屋は、彼らが着くまでに建て終えられることになっていた。'),
('JPN', '民数记', 4, 10, 22, 'また、エフライム族の宿営の旗が、その軍団ごとに出発。軍団長はアミフデの子エリシャマ。'),
('JPN', '民数记', 4, 10, 23, 'マナセ部族の軍団長はペダツルの子ガムリエル。'),
('JPN', '民数记', 4, 10, 24, 'ベニヤミン部族の軍団長はギデオニの子アビダンであった。'),
('JPN', '民数记', 4, 10, 25, 'ダン部族の宿営の旗が、全宿営のしんがりとして軍団ごとに出発。軍団長はアミシャダイの子アヒエゼル。'),
('JPN', '民数记', 4, 10, 26, 'アシェル部族の軍団長はオクランの子パグイエル。'),
('JPN', '民数记', 4, 10, 27, 'ナフタリ部族の軍団長はエナンの子アヒラ。'),
('JPN', '民数记', 4, 10, 28, '以上がイスラエルの子らの軍団ごとの出発順序であり、彼らはそのように出発した。'),
('JPN', '民数记', 4, 10, 29, 'さて、モーセは、彼のしゅうとミディアン人レウエルの子ホバブに言った。「私たちは、主が与えると言われた場所へ旅立つところです。私たちと一緒に行きましょう。私たちはあなたを幸せにします。主がイスラエルに良いことを約束しておられるからです。」'),
('JPN', '民数记', 4, 10, 30, '彼はモーセに答えた。「私は行きません。私の国に、私の親族のもとに帰ります。」'),
('JPN', '民数记', 4, 10, 31, 'するとモーセは言った。「どうか私たちを見捨てないでください。というのは、あなたは、私たちが荒野のどこで宿営したらよいかご存じで、私たちにとっては目なのですから。'),
('JPN', '民数记', 4, 10, 32, '私たちと一緒に行ってくだされば、主が私たちに下さるはずのどんな良きものも、あなたにお分かちできます。」'),
('JPN', '民数记', 4, 10, 33, 'こうして、彼らは主の山を旅立ち、三日の道のりを進んだ。主の契約の箱は三日の道のりの間、彼らの先に立って進み、彼らが休息する場所を探した。'),
('JPN', '民数记', 4, 10, 34, '彼らが宿営から出発する際、昼間は主の雲が彼らの上にあった。'),
('JPN', '民数记', 4, 10, 35, '契約の箱が出発するときには、モーセはこう言った。「主よ、立ち上がってください。あなたの敵が散らされ、あなたを憎む者が、御前から逃げ去りますように。」'),
('JPN', '民数记', 4, 10, 36, 'またそれがとどまるときには、彼は言った。「主よ、お帰りください。イスラエルの幾千幾万もの民のもとに。」'),
('JPN', '民数记', 4, 11, 1, 'さて、民は主に対して、繰り返し激しく不平を言った。主はこれを聞いて怒りを燃やし、主の火が彼らに向かって燃え上がり、宿営の端をなめ尽くした。'),
('JPN', '民数记', 4, 11, 2, 'すると民はモーセに向かってわめき叫んだ。それで、モーセが主に祈ると、その火は消えた。'),
('JPN', '民数记', 4, 11, 3, 'その場所の名はタブエラと呼ばれた。主の火が、彼らに向かって燃え上がったからである。'),
('JPN', '民数记', 4, 11, 4, '彼らのうちに混じって来ていた者たちは激しい欲望にかられ、イスラエルの子らは再び大声で泣いて、言った。「ああ、肉が食べたい。'),
('JPN', '民数记', 4, 11, 5, 'エジプトで、ただで魚を食べていたことを思い出す。きゅうりも、すいか、にら、玉ねぎ、にんにくも。'),
('JPN', '民数记', 4, 11, 6, 'だが今や、私たちの喉はからからだ。全く何もなく、ただ、このマナを見るだけだ。」'),
('JPN', '民数记', 4, 11, 7, 'マナはコエンドロの種のようで、一見、ベドラハのようであった。'),
('JPN', '民数记', 4, 11, 8, '民は歩き回ってそれを集め、ひき臼でひくか臼でつき、これを鍋で煮てパン菓子を作った。その味は、油で揚げた菓子のような味であった。'),
('JPN', '民数记', 4, 11, 9, '夜、宿営に露が降りるとき、マナもそれと一緒に降りて来た。'),
('JPN', '民数记', 4, 11, 10, 'モーセは、民がその家族ごとに、それぞれ自分の天幕の入り口で泣くのを聞いた。主の怒りは激しく燃え上がった。このことは、モーセにとって辛いことであった。'),
('JPN', '民数记', 4, 11, 11, 'それで、モーセは主に言った。「なぜ、あなたはしもべを苦しめられるのですか。なぜ、私はあなたのご好意を受けられないのですか。なぜ、この民全体の重荷を私に負わされるのですか。'),
('JPN', '民数记', 4, 11, 12, '私がこのすべての民をはらんだのでしょうか。私が彼らを産んだのでしょうか。それなのになぜ、あなたは私に、『乳母が乳飲み子を抱きかかえるように、彼らをあなたの胸に抱き、わたしが彼らの父祖たちに誓った地に連れて行け』と言われるのですか。'),
('JPN', '民数记', 4, 11, 13, 'どこから私は肉を得て、この民全体に与えられるでしょうか。彼らは私に泣き叫び、『肉を与えて食べさせてくれ』と言うのです。'),
('JPN', '民数记', 4, 11, 14, '私一人で、この民全体を負うことはできません。私には重すぎます。'),
('JPN', '民数记', 4, 11, 15, '私をこのように扱われるのなら、お願いです、どうか私を殺してください。これ以上、私を悲惨な目にあわせないでください。」'),
('JPN', '民数记', 4, 11, 16, '主はモーセに言われた。「イスラエルの長老たちのうちから、民の長老で、あなたが民のつかさと認める者七十人をわたしのために集めよ。そして、彼らを会見の天幕に連れて来て、そこであなたのそばに立たせよ。'),
('JPN', '民数记', 4, 11, 17, 'わたしは降りて行って、そこであなたと語り、あなたの上にある霊から一部を取って彼らの上に置く。それで彼らも民の重荷をあなたとともに負い、あなたがたった一人で負うことはなくなる。'),
('JPN', '民数记', 4, 11, 18, 'あなたは民に言わなければならない。明日に備えて身を聖別しなさい。あなたがたは肉を食べられる。あなたがたが泣いて、主に対して『ああ、肉が食べたい。エジプトは良かった』と言ったからだ。主が肉を下さる。あなたがたは肉を食べられるのだ。'),
('JPN', '民数记', 4, 11, 19, 'あなたがたが食べるのは、ほんの一日や二日や五日や十日や二十日ではなく、'),
('JPN', '民数记', 4, 11, 20, '一か月もであって、ついには、あなたがたの鼻から出て来て、吐き気をもよおすほどになる。それは、あなたがたのうちにおられる主をないがしろにして、その御前で泣き、『いったい、なぜ、われわれはエジプトから出て来たのか』と言ったからだ。」'),
('JPN', '民数记', 4, 11, 21, 'しかしモーセは言った。「私と一緒にいる民は、徒歩の男子だけで六十万人です。しかもあなたは、彼らに肉を与え、一か月の間食べさせる、と言われます。'),
('JPN', '民数记', 4, 11, 22, '彼らのために羊の群れ、牛の群れが屠られても、それは彼らに十分でしょうか。彼らのために海の魚が全部集められても、彼らに十分でしょうか。」'),
('JPN', '民数记', 4, 11, 23, '主はモーセに答えられた。「この主の手が短いというのか。わたしのことばが実現するかどうかは、今に分かる。」'),
('JPN', '民数记', 4, 11, 24, 'モーセは出て行って、主のことばを民に語った。そして民の長老たちのうちから七十人を集め、彼らを天幕の周りに立たせた。'),
('JPN', '民数记', 4, 11, 25, 'すると主は雲の中にあって降りて来て、モーセと語り、彼の上にある霊から一部を取って、その七十人の長老に与えられた。その霊が彼らの上にとどまると、彼らは預言した。しかし、重ねてそれをすることはなかった。'),
('JPN', '民数记', 4, 11, 26, 'そのとき、二人の者が宿営に残っていた。一人の名はエルダデ、もう一人の名はメダデであった。彼らの上にも霊がとどまった。彼らは長老として登録された者たちだったが、天幕へは出て行かなかったのである。彼らは宿営の中で預言した。'),
('JPN', '民数记', 4, 11, 27, 'それで、一人の若者が走って来て、モーセに告げた。「エルダデとメダデが宿営の中で預言しています。」'),
('JPN', '民数记', 4, 11, 28, '若いときからモーセの従者であったヌンの子ヨシュアは答えて言った。「わが主、モーセよ。彼らをやめさせてください。」'),
('JPN', '民数记', 4, 11, 29, 'モーセは彼に言った。「あなたは私のためを思って、ねたみを起こしているのか。主の民がみな、預言者となり、主が彼らの上にご自分の霊を与えられるとよいのに。」'),
('JPN', '民数记', 4, 11, 30, 'それから、モーセとイスラエルの長老たちは、宿営に戻った。'),
('JPN', '民数记', 4, 11, 31, 'さて、主のもとから風が吹き、海からうずらを運んで来て、宿営の近くに落とした。それは宿営の周り、どちらの側にも約一日の道のりの範囲で、地面から約二キュビトの高さになった。'),
('JPN', '民数记', 4, 11, 32, '民は、その日は終日終夜、次の日も終日出て行ってうずらを集めた。集めたのが最も少なかった者でも、十ホメルほど集めた。彼らはそれらを自分たちのために、宿営の周囲に広げておいた。'),
('JPN', '民数记', 4, 11, 33, '肉が彼らの歯の間にあって、まだかみ終わらないうちに、主の怒りが民に向かって燃え上がり、主は非常に激しい疫病で民を打たれた。'),
('JPN', '民数记', 4, 11, 34, 'その場所の名はキブロテ・ハ・タアワと呼ばれた。欲望にかられた民が、そこに埋められたからである。'),
('JPN', '民数记', 4, 11, 35, 'キブロテ・ハ・タアワから、民はハツェロテに進んで行った。そしてハツェロテにとどまった。'),
('JPN', '民数记', 4, 12, 1, 'そのとき、ミリアムとアロンは、モーセが妻としていたクシュ人の女のことで彼を非難した。モーセがクシュ人の女を妻としていたからである。'),
('JPN', '民数记', 4, 12, 2, '彼らは言った。「主はただモーセとだけ話されたのか。われわれとも話されたのではないか。」主はこれを聞かれた。'),
('JPN', '民数记', 4, 12, 3, 'モーセという人は、地の上のだれにもまさって柔和であった。'),
('JPN', '民数记', 4, 12, 4, '主は突然、モーセとアロンとミリアムに、「あなたがた三人は会見の天幕のところへ出よ」と言われた。そこで彼ら三人は出て行った。'),
('JPN', '民数记', 4, 12, 5, '主は雲の柱の中にあって降りて来られ、天幕の入り口に立って、アロンとミリアムを呼ばれた。二人が出て行くと、'),
('JPN', '民数记', 4, 12, 6, '主は言われた。「聞け、わたしのことばを。もし、あなたがたの間に預言者がいるなら、主であるわたしは、幻の中でその人にわたし自身を知らせ、夢の中でその人と語る。'),
('JPN', '民数记', 4, 12, 7, 'だがわたしのしもべモーセとはそうではない。彼はわたしの全家を通じて忠実な者。'),
('JPN', '民数记', 4, 12, 8, '彼とは、わたしは口と口で語り、明らかに語って、謎では話さない。彼は主の姿を仰ぎ見ている。なぜあなたがたは、わたしのしもべ、モーセを恐れず、非難するのか。」'),
('JPN', '民数记', 4, 12, 9, '主の怒りが彼らに向かって燃え上がり、主は去って行かれた。'),
('JPN', '民数记', 4, 12, 10, '雲が天幕の上から離れ去ると、見よ、ミリアムは皮膚がツァラアトに冒され、雪のようになっていた。アロンがミリアムの方を振り向くと、見よ、彼女はツァラアトに冒されていた。'),
('JPN', '民数记', 4, 12, 11, 'アロンはモーセに言った。「わが主よ。どうか、私たちが愚かにも陥ってしまった罪の罰を、私たちに負わせないでください。'),
('JPN', '民数记', 4, 12, 12, 'どうか、彼女を、肉が半ば腐って母の胎から出て来る死人のようにしないでください。」'),
('JPN', '民数记', 4, 12, 13, 'モーセは主に叫んだ。「神よ、どうか彼女を癒やしてください。」'),
('JPN', '民数记', 4, 12, 14, 'しかし主はモーセに言われた。「もし彼女の父が彼女の顔に唾したら、彼女は七日間、恥をかかされることにならないか。彼女を七日間、宿営の外に締め出しておかなければならない。その後で彼女は戻ることができる。」'),
('JPN', '民数记', 4, 12, 15, 'それでミリアムは七日間、宿営の外に締め出された。民はミリアムが戻るまで旅立たなかった。'),
('JPN', '民数记', 4, 12, 16, 'それから民はハツェロテを旅立ち、パランの荒野に宿営した。'),
('JPN', '民数记', 4, 13, 1, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 13, 2, '「人々を遣わして、わたしがイスラエルの子らに与えようとしているカナンの地を偵察させよ。父祖の部族ごとに一人ずつ、族長を遣わさなければならない。」'),
('JPN', '民数记', 4, 13, 3, 'モーセは、主の命により、パランの荒野から彼らを遣わした。彼らはみな、イスラエルの子らのかしらであった。'),
('JPN', '民数记', 4, 13, 4, '彼らの名は次のとおりである。ルベン部族からはザクルの子シャムア。'),
('JPN', '民数记', 4, 13, 5, 'シメオン部族からはホリの子シャファテ。'),
('JPN', '民数记', 4, 13, 6, 'ユダ部族からはエフンネの子カレブ。'),
('JPN', '民数记', 4, 13, 7, 'イッサカル部族からはヨセフの子イグアル。'),
('JPN', '民数记', 4, 13, 8, 'エフライム部族からはヌンの子ホセア。'),
('JPN', '民数记', 4, 13, 9, 'ベニヤミン部族からはラフの子パルティ。'),
('JPN', '民数记', 4, 13, 10, 'ゼブルン部族からはソディの子ガディエル。'),
('JPN', '民数记', 4, 13, 11, 'ヨセフ部族、すなわちマナセ部族からはスシの子ガディ。'),
('JPN', '民数记', 4, 13, 12, 'ダン部族からはゲマリの子アンミエル。'),
('JPN', '民数记', 4, 13, 13, 'アシェル部族からはミカエルの子セトル。'),
('JPN', '民数记', 4, 13, 14, 'ナフタリ部族からはボフシの子ナフビ。'),
('JPN', '民数记', 4, 13, 15, 'ガド部族からはマキの子ゲウエル。'),
('JPN', '民数记', 4, 13, 16, '以上が、モーセがその地の偵察のために遣わした者の名である。モーセはヌンの子ホセアをヨシュアと名づけた。'),
('JPN', '民数记', 4, 13, 17, 'モーセは、カナンの地の偵察のために彼らを遣わして言った。「向こうに上って行ってネゲブに入り、山地に行き、'),
('JPN', '民数记', 4, 13, 18, 'その地がどんなであるか、調べてきなさい。そこに住んでいる民が強いか弱いか、少ないか多いか、'),
('JPN', '民数记', 4, 13, 19, 'また彼らが住んでいる土地はどうか、それが良いか悪いか、彼らが住んでいる町々はどうか、それらは宿営か、それとも城壁の町か、'),
('JPN', '民数记', 4, 13, 20, '土地はどうか、それは肥えているか痩せているか、そこには木があるかないか。勇気を出して、その地の果物を取って来なさい。」その季節は初ぶどうの熟すころであった。'),
('JPN', '民数记', 4, 13, 21, 'それで、彼らは上って行き、ツィンの荒野からレボ・ハマテのレホブまで、その地を偵察した。'),
('JPN', '民数记', 4, 13, 22, '彼らは上って行ってネゲブに入り、ヘブロンまで行った。そこにはアナクの子孫であるアヒマンと、シェシャイと、タルマイがいた。ヘブロンはエジプトのツォアンより七年前に建てられていた。'),
('JPN', '民数记', 4, 13, 23, '彼らはエシュコルの谷まで来て、そこでぶどうが一房ついた枝を切り取り、二人で棒で担いだ。また、ざくろやいちじくの木からも切り取った。'),
('JPN', '民数记', 4, 13, 24, 'その場所は、イスラエルの子らがそこで切り取ったぶどうの房にちなんで、エシュコルの谷と呼ばれた。'),
('JPN', '民数记', 4, 13, 25, '四十日の終わりに、彼らはその地の偵察から戻った。'),
('JPN', '民数记', 4, 13, 26, '彼らは、パランの荒野のカデシュにいるモーセとアロンおよびイスラエルの全会衆のところにやって来て、二人と全会衆に報告をし、その地の果物を見せた。'),
('JPN', '民数记', 4, 13, 27, '彼らはモーセに語った。「私たちは、あなたがお遣わしになった地に行きました。そこには確かに乳と蜜が流れています。そして、これがそこの果物です。'),
('JPN', '民数记', 4, 13, 28, 'ただ、その地に住む民は力が強く、その町々は城壁があって非常に大きく、そのうえ、そこでアナクの子孫を見ました。'),
('JPN', '民数记', 4, 13, 29, 'アマレク人がネゲブの地方に住んでいて、ヒッタイト人、エブス人、アモリ人が山地に、カナン人が海岸とヨルダンの川岸に住んでいます。」'),
('JPN', '民数记', 4, 13, 30, 'そのとき、カレブがモーセの前で、民を静めて言った。「私たちはぜひとも上って行って、そこを占領しましょう。必ず打ち勝つことができます。」'),
('JPN', '民数记', 4, 13, 31, 'しかし、彼と一緒に上って行った者たちは言った。「あの民のところには攻め上れない。あの民は私たちより強い。」'),
('JPN', '民数记', 4, 13, 32, '彼らは偵察して来た地について、イスラエルの子らに悪く言いふらして言った。「私たちが行き巡って偵察した地は、そこに住む者を食い尽くす地で、そこで見た民はみな、背の高い者たちだ。'),
('JPN', '民数记', 4, 13, 33, '私たちは、そこでネフィリムを、ネフィリムの末裔アナク人を見た。私たちの目には自分たちがバッタのように見えたし、彼らの目にもそう見えただろう。」'),
('JPN', '民数记', 4, 14, 1, 'すると、全会衆は大声をあげて叫び、民はその夜、泣き明かした。'),
('JPN', '民数记', 4, 14, 2, 'イスラエルの子らはみな、モーセとアロンに不平を言った。全会衆は彼らに言った。「われわれはエジプトの地で死んでいたらよかった。あるいは、この荒野で死んでいたらよかったのだ。'),
('JPN', '民数记', 4, 14, 3, 'なぜ主は、われわれをこの地に導いて来て、剣に倒れるようにされるのか。妻や子どもは、かすめ奪われてしまう。エジプトに帰るほうが、われわれにとって良くはないか。」'),
('JPN', '民数记', 4, 14, 4, 'そして互いに言った。「さあ、われわれは、かしらを一人立ててエジプトに帰ろう。」'),
('JPN', '民数记', 4, 14, 5, 'そこで、モーセとアロンは、イスラエルの会衆の集会全体の前でひれ伏した。'),
('JPN', '民数记', 4, 14, 6, 'すると、その地を偵察して来た者のうち、ヌンの子ヨシュアとエフンネの子カレブが、自分たちの衣を引き裂き、'),
('JPN', '民数记', 4, 14, 7, 'イスラエルの全会衆に向かって次のように言った。「私たちが巡り歩いて偵察した地は、すばらしく、良い地だった。'),
('JPN', '民数记', 4, 14, 8, 'もし主が私たちを喜んでおられるなら、私たちをあの地に導き入れ、それを私たちに下さる。あの地は乳と蜜が流れる地だ。'),
('JPN', '民数记', 4, 14, 9, 'ただ、主に背いてはならない。その地の人々を恐れてはならない。彼らは私たちの餌食となる。彼らの守りは、すでに彼らから取り去られている。主が私たちとともにおられるのだ。彼らを恐れてはならない。」'),
('JPN', '民数记', 4, 14, 10, 'しかし全会衆は、二人を石で打ち殺そうと言い出した。すると、主の栄光が会見の天幕からすべてのイスラエルの子らに現れた。'),
('JPN', '民数记', 4, 14, 11, '主はモーセに言われた。「この民はいつまでわたしを侮るのか。わたしがこの民の間で行ったすべてのしるしにもかかわらず、いつまでわたしを信じようとしないのか。'),
('JPN', '民数记', 4, 14, 12, 'わたしは彼らを疫病で打ち、ゆずりの地を剝奪する。しかし、わたしはあなたを彼らよりも強く大いなる国民にする。」'),
('JPN', '民数记', 4, 14, 13, 'モーセは主に言った。「エジプトは、あなたが御力によって、自分たちのうちからこの民を導き出されたことを聞いて、'),
('JPN', '民数记', 4, 14, 14, 'この地の住民に告げるでしょう。事実、住民たちは聞いています。あなた、主がこの民のうちにおられ、あなた、主が目の当たりにご自身を現されること、またあなたの雲が彼らの上に立ち、あなたが昼は雲の柱、夜は火の柱の内にあって、彼らの前を歩んでおられることを。'),
('JPN', '民数记', 4, 14, 15, 'もし、あなたがこの民を一人残らず殺すなら、あなたのうわさを聞いた異邦の民は、このように言うに違いありません。'),
('JPN', '民数记', 4, 14, 16, '『主はこの民を、彼らに誓った地に導き入れることができなかったので、荒野で殺したのだ』と。'),
('JPN', '民数记', 4, 14, 17, 'どうか今、あなたが語られたように、わが主の大きな力を現してください。あなたは言われました。'),
('JPN', '民数记', 4, 14, 18, '『主は怒るのに遅く、恵み豊かであり、咎と背きを赦す。しかし、罰すべき者を必ず罰し、父の咎を子に報い、三代、四代に及ぼす』と。'),
('JPN', '民数记', 4, 14, 19, 'この民をエジプトから今に至るまで耐え忍んでくださったように、どうかこの民の咎をあなたの大きな恵みによって赦してください。」'),
('JPN', '民数记', 4, 14, 20, '主は言われた。「あなたのことばどおりに、わたしは赦す。'),
('JPN', '民数记', 4, 14, 21, 'しかし、わたしが生きていて、主の栄光が全地に満ちている以上、'),
('JPN', '民数记', 4, 14, 22, 'わたしの栄光と、わたしがエジプトとこの荒野で行ったしるしとを見ながら、十度もこのようにわたしを試み、わたしの声に聞き従わなかった者たちは、だれ一人、'),
('JPN', '民数记', 4, 14, 23, 'わたしが彼らの父祖たちに誓った地を見ることはない。わたしを侮った者たちは、だれ一人、それを見ることはない。'),
('JPN', '民数记', 4, 14, 24, 'ただし、わたしのしもべカレブは、ほかの者とは違った霊を持ち、わたしに従い通したので、わたしは、彼が行って来た地に彼を導き入れる。彼の子孫はその地を所有するようになる。'),
('JPN', '民数记', 4, 14, 25, '平地にはアマレク人とカナン人が住んでいるので、あなたがたは、明日、向きを変えてここを旅立ち、葦の海の道を通って荒野へ行け。」'),
('JPN', '民数记', 4, 14, 26, '主はモーセとアロンに告げられた。'),
('JPN', '民数记', 4, 14, 27, '「いつまで、この悪い会衆は、わたしに不平を言い続けるのか。わたしは、イスラエルの子らがわたしにつぶやく不平を聞いた。'),
('JPN', '民数记', 4, 14, 28, '彼らに言え。わたしは生きている──主のことば──。わたしは必ず、おまえたちがわたしの耳に語ったとおりに、おまえたちに行う。'),
('JPN', '民数记', 4, 14, 29, 'この荒野におまえたちは、屍をさらす。わたしに不平を言った者で、二十歳以上の、登録され数えられた者たち全員である。'),
('JPN', '民数记', 4, 14, 30, 'エフンネの子カレブと、ヌンの子ヨシュアのほかは、おまえたちを住まわせるとわたしが誓った地に、だれ一人入ることはできない。'),
('JPN', '民数记', 4, 14, 31, 'おまえたちが『かすめ奪われてしまう』と言った、おまえたちの子どもについては、わたしは彼らを導き入れる。彼らはおまえたちが拒んだ地を知るようになる。'),
('JPN', '民数记', 4, 14, 32, 'しかし、おまえたちはこの荒野に屍をさらす。'),
('JPN', '民数记', 4, 14, 33, 'おまえたちの子どもは、この荒野で四十年の間羊を飼う者となり、おまえたちがみな、屍となるまで、おまえたちの背信の責めを負わなければならない。'),
('JPN', '民数记', 4, 14, 34, 'おまえたちが、あの地を偵察した日数は四十日であった。その一日を一年と数えて、四十年の間おまえたちは自分の咎を負わなければならない。こうして、わたしへの反抗が何であるかを思い知ることになる。'),
('JPN', '民数记', 4, 14, 35, '主であるこのわたしが言う。一つになってわたしに逆らったこの悪い会衆のすべてに対して、わたしは必ずこうする。この荒野で彼らは死に絶える。'),
('JPN', '民数记', 4, 14, 36, 'また、モーセがあの地の偵察のために遣わした者で、帰って来て、その地について悪く言いふらし、全会衆にモーセに対する不平を言わせた者たちもだ。」'),
('JPN', '民数记', 4, 14, 37, 'こうして、その地を悪く言いふらした者たちは、主の前に疫病で死んだ。'),
('JPN', '民数记', 4, 14, 38, 'しかし、あの地を偵察しに行った者のうち、ヌンの子ヨシュアと、エフンネの子カレブは生き残った。'),
('JPN', '民数记', 4, 14, 39, 'モーセがこれらのことばを、すべてのイスラエルの子らに告げると、民は嘆き悲しんだ。'),
('JPN', '民数记', 4, 14, 40, '翌朝早く、彼らは山地の峰の方に上って行こうとして言った。「われわれはここにいるが、とにかく主が言われた場所へ上って行ってみよう。われわれは罪を犯してしまったのだ。」'),
('JPN', '民数记', 4, 14, 41, 'モーセは言った。「あなたがたはいったいなぜ、主の命令を破ろうとするのか。それは成功しない。'),
('JPN', '民数记', 4, 14, 42, '上って行ってはならない。主があなたがたのうちにおられないのだから。あなたがたは敵に打ち負かされてはならない。'),
('JPN', '民数记', 4, 14, 43, 'そこには、あなたがたの前にアマレク人とカナン人がいて、あなたがたは剣で倒される。あなたがたが主に背いたから、主はあなたがたとともにはおられない。」'),
('JPN', '民数记', 4, 14, 44, 'しかし、彼らはかまわずに山地の峰の方に上って行った。主の契約の箱とモーセは、宿営の中から動かなかった。'),
('JPN', '民数记', 4, 14, 45, '山地に住んでいたアマレク人とカナン人は、下って来て彼らを討ち、ホルマまで彼らを追い散らした。'),
('JPN', '民数记', 4, 15, 1, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 15, 2, '「イスラエルの子らに告げよ。わたしがあなたがたに与えて住まわせる地にあなたがたが入り、'),
('JPN', '民数记', 4, 15, 3, '食物のささげ物を主に献げるとき、すなわち、特別な誓願を果たすためであれ、進んで献げるものとしてであれ、例祭としてであれ、牛か羊の群れから全焼のささげ物かいけにえをもって、主に芳ばしい香りを献げるとき、'),
('JPN', '民数记', 4, 15, 4, 'そのささげ物をする者は、穀物のささげ物として、油四分の一ヒンを混ぜた小麦粉十分の一エパを、主に献げなければならない。'),
('JPN', '民数记', 4, 15, 5, 'また全焼のささげ物、またはいけにえに添えて、子羊一匹のための注ぎのささげ物として、四分の一ヒンのぶどう酒を献げなければならない。'),
('JPN', '民数记', 4, 15, 6, '雄羊の場合には、穀物のささげ物として、油三分の一ヒンを混ぜた小麦粉十分の二エパを献げ、'),
('JPN', '民数记', 4, 15, 7, 'さらに注ぎのささげ物として、ぶどう酒三分の一ヒンを献げなければならない。これは、主への芳ばしい香りである。'),
('JPN', '民数记', 4, 15, 8, 'また、あなたが特別な誓願を果たすために、若い牛を全焼のささげ物、もしくはいけにえとする場合、あるいは交わりのいけにえとして主に献げる場合は、'),
('JPN', '民数记', 4, 15, 9, 'その若い牛に添えて、油二分の一ヒンを混ぜた小麦粉十分の三エパの穀物のささげ物を献げ、'),
('JPN', '民数记', 4, 15, 10, 'また注ぎのささげ物として、ぶどう酒二分の一ヒンを献げなければならない。これは主への食物のささげ物、芳ばしい香りである。'),
('JPN', '民数记', 4, 15, 11, '牛一頭、雄羊一匹、いかなる羊、やぎについても、このようにしなければならない。'),
('JPN', '民数记', 4, 15, 12, 'あなたがたが献げる数に応じて、それらの数にしたがって、一頭、一匹ごとにこのようにしなければならない。'),
('JPN', '民数记', 4, 15, 13, 'すべてこの国に生まれた者が、主への芳ばしい香りの、食物のささげ物を献げるには、このようにこれらのことを行わなければならない。'),
('JPN', '民数记', 4, 15, 14, 'また、あなたがたのところに寄留している者、あるいは、あなたがたのうちに代々住んでいる者が、主への芳ばしい香りである、食物のささげ物を献げる場合には、あなたがたがするようにその人もしなければならない。'),
('JPN', '民数记', 4, 15, 15, '一つの集会として、掟はあなたがたにも、寄留している者にも同一であり、代々にわたる永遠の掟である。主の前には、あなたがたも寄留者も同じである。'),
('JPN', '民数记', 4, 15, 16, 'あなたがたにも、あなたがたのところに寄留している者にも、同一のおしえ、同一のさばきが適用されなければならない。」'),
('JPN', '民数记', 4, 15, 17, '主はモーセにこう告げられた。'),
('JPN', '民数记', 4, 15, 18, '「イスラエルの子らに告げよ。わたしがあなたがたを導き入れようとする地にあなたがたが入り、'),
('JPN', '民数记', 4, 15, 19, 'その地のパンを食べるようになったら、あなたがたは主に奉納物を献げなければならない。'),
('JPN', '民数记', 4, 15, 20, '初物の麦粉で作った輪形パンを奉納物として献げ、打ち場からの奉納物として献げなければならない。'),
('JPN', '民数记', 4, 15, 21, '初物の麦粉のうちから、あなたがたは代々にわたり、主に奉納物を献げなければならない。'),
('JPN', '民数记', 4, 15, 22, 'あなたがたが迷い出て、主がモーセに告げたこれらすべての命令、'),
('JPN', '民数记', 4, 15, 23, 'すなわち、主が命じた日以後、代々にわたって、主がモーセを通してあなたがたに命じたすべてのことを行わないとき、'),
('JPN', '民数记', 4, 15, 24, 'もしそのことが、会衆が気づかずになされたのなら、全会衆は、主への芳ばしい香りのための全焼のささげ物として若い雄牛一頭、また、定めにかなう穀物のささげ物と注ぎのささげ物、さらに罪のきよめのささげ物として雄やぎ一匹を献げなければならない。'),
('JPN', '民数记', 4, 15, 25, '祭司がイスラエルの全会衆のために宥めを行うなら、彼らは赦される。それは過失であり、彼らが自分たちの過失のために、自分たちのささげ物、すなわち主への食物のささげ物と罪のきよめのささげ物を、主の前に持って来たからである。'),
('JPN', '民数记', 4, 15, 26, 'イスラエルの全会衆も、あなたがたの間に寄留している者も赦される。それは民全体の過ちだからである。'),
('JPN', '民数记', 4, 15, 27, 'もし個人が気づかずに罪に陥ってしまったのなら、一歳の雌やぎ一匹を罪のきよめのささげ物として献げなければならない。'),
('JPN', '民数记', 4, 15, 28, '祭司は、気づかずに罪に陥ってしまった者のために、主の前で宥めを行う。彼のために宥めを行い、その人は赦される。'),
('JPN', '民数记', 4, 15, 29, 'イスラエルの子らのうちのこの国に生まれた者でも、あなたがたの間に寄留している者でも、気づかずに罪を行ってしまった者には、あなたがたと同一のおしえが適用されなければならない。'),
('JPN', '民数记', 4, 15, 30, 'この国に生まれた者でも、寄留者でも、故意に違反する者は主を冒瀆する者であり、その人は自分の民の間から断ち切られる。'),
('JPN', '民数记', 4, 15, 31, '主のことばを侮り、その命令を破ったのであるから、必ず断ち切られ、その咎を負う。」'),
('JPN', '民数记', 4, 15, 32, 'イスラエルの子らが荒野にいたとき、安息日に薪を集めている男が見つかった。'),
('JPN', '民数记', 4, 15, 33, '薪を集めている者を見つけた人たちは、その人をモーセとアロンおよび全会衆のところに連れて来た。'),
('JPN', '民数记', 4, 15, 34, 'しかし、その人をどうすべきか、はっきりと示されていなかったので、彼を留置しておいた。'),
('JPN', '民数记', 4, 15, 35, 'すると、主はモーセに言われた。「この者は必ず殺されなければならない。全会衆は宿営の外で、彼を石で打ち殺さなければならない。」'),
('JPN', '民数记', 4, 15, 36, 'そこで、全会衆は主がモーセに命じられたように、その人を宿営の外に連れ出し、石で打ち殺した。'),
('JPN', '民数记', 4, 15, 37, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 15, 38, '「イスラエルの子らに告げて、彼らが代々にわたり、衣服の裾の四隅に房を作り、その隅の房に青いひもを付けるように言え。'),
('JPN', '民数记', 4, 15, 39, 'その房はあなたがたのためであって、あなたがたがそれを見て、主のすべての命令を思い起こしてそれを行うためであり、淫らなことをする自分の心と目の欲にしたがって、さまよい歩くことのないようにするためである。'),
('JPN', '民数记', 4, 15, 40, 'こうしてあなたがたが、わたしのすべての命令を思い起こして、これを行い、あなたがたの神に対して聖なる者となるためである。'),
('JPN', '民数记', 4, 15, 41, 'わたしが、あなたがたの神、主であり、わたしがあなたがたの神となるために、あなたがたをエジプトの地から導き出したのである。わたしはあなたがたの神、主である。」'),
('JPN', '民数记', 4, 16, 1, 'レビの子であるケハテの子イツハルの子コラは、ルベンの子孫であるエリアブの子ダタンとアビラム、およびペレテの子オンと共謀して、'),
('JPN', '民数记', 4, 16, 2, 'モーセに立ち向かった。イスラエルの子らで、会衆の上に立つ族長たち、会合から召し出された名のある者たち二百五十人も、彼らと一緒であった。'),
('JPN', '民数记', 4, 16, 3, '彼らはモーセとアロンに逆らって結集し、二人に言った。「あなたがたは分を超えている。全会衆残らず聖なる者であって、主がそのうちにおられるのに、なぜ、あなたがたは主の集会の上に立つのか。」'),
('JPN', '民数记', 4, 16, 4, 'モーセはこれを聞いてひれ伏した。'),
('JPN', '民数记', 4, 16, 5, 'それから、コラとそのすべての仲間とに告げた。「明日の朝、主は、だれがご自分に属する者か、だれが聖なる者かを示し、その人をご自分に近寄せられる。主は、ご自分が選ぶ者をご自分に近寄せられるのだ。'),
('JPN', '民数记', 4, 16, 6, 'こうしなさい。コラとそのすべての仲間よ。あなたがたは火皿を取り、'),
('JPN', '民数记', 4, 16, 7, '明日、主の前でその中に火を入れ、その上に香を盛りなさい。主がお選びになるその人が、聖なる者である。レビの子たちよ、あなたがたが分を超えているのだ。」'),
('JPN', '民数记', 4, 16, 8, 'モーセはコラに言った。「レビの子たちよ、よく聞きなさい。'),
('JPN', '民数记', 4, 16, 9, 'あなたがたは、何か不足があるのか。イスラエルの神が、あなたがたをイスラエルの会衆から分けて、主の幕屋の奉仕をするように、また会衆の前に立って彼らに仕えるように、ご自分に近寄せてくださったのだ。'),
('JPN', '民数记', 4, 16, 10, 'こうしてあなたを、そして、あなたの同族であるレビ族をみな、あなたと一緒に近寄せてくださったのだ。それなのに、あなたがたは祭司の職まで要求するのか。'),
('JPN', '民数记', 4, 16, 11, '事実、一つになって主に逆らっているのは、あなたとあなたの仲間全員だ。アロンが何だからといって、彼に対して不平を言うのか。」'),
('JPN', '民数记', 4, 16, 12, 'モーセは人を遣わして、エリアブの子のダタンとアビラムとを呼び寄せようとしたが、彼らは言った。「われわれは行かない。'),
('JPN', '民数记', 4, 16, 13, 'あなたは、われわれを乳と蜜の流れる地から連れ上って、荒野で死なせようとし、そのうえ、われわれの上に君臨している。それでも不足があるのか。'),
('JPN', '民数记', 4, 16, 14, 'しかも、あなたは、乳と蜜の流れる地にわれわれを導き入れず、畑とぶどう畑を、受け継ぐべき財産としてわれわれに与えてもいない。あなたは、この人たちの目をくらまそうとするのか。われわれは行かない。」'),
('JPN', '民数记', 4, 16, 15, 'モーセは激しく怒った。そして主に言った。「どうか、彼らのささげ物を顧みないでください。私は彼らから、ろば一頭も取り上げたことはなく、彼らのうちのだれも傷つけたことがありません。」'),
('JPN', '民数记', 4, 16, 16, 'それからモーセはコラに言った。「明日、あなたとあなたの仲間はみな、主の前に出なさい。あなたも彼らも、そしてアロンも。'),
('JPN', '民数记', 4, 16, 17, 'あなたがたは、それぞれ自分の火皿を取り、その上に香を盛り、それぞれ主の前に持って行きなさい。二百五十の火皿を、あなたもアロンも、それぞれ自分の火皿を持って行きなさい。」'),
('JPN', '民数记', 4, 16, 18, '彼らはそれぞれ自分の火皿を取り、それに火を入れて、その上に香を盛った。そしてモーセとアロンと一緒に会見の天幕の入り口に立った。'),
('JPN', '民数记', 4, 16, 19, 'コラは、二人に逆らわせようとして、全会衆を会見の天幕の入り口に集めた。そのとき、主の栄光が全会衆に現れた。'),
('JPN', '民数记', 4, 16, 20, '主はモーセとアロンに告げられた。'),
('JPN', '民数记', 4, 16, 21, '「あなたがたはこの会衆から離れよ。わたしは彼らをたちどころに滅ぼし尽くす。」'),
('JPN', '民数记', 4, 16, 22, '二人はひれ伏して言った。「神よ、すべての肉なるものの霊をつかさどる神よ。一人の人が罪ある者となれば、全会衆に御怒りを下されるのですか。」'),
('JPN', '民数记', 4, 16, 23, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 16, 24, '「会衆に告げて、コラとダタンとアビラムの住まいの周辺から引き下がるように言え。」'),
('JPN', '民数记', 4, 16, 25, 'モーセは立ち上がり、ダタンとアビラムのところへ行った。イスラエルの長老たちもついて行った。'),
('JPN', '民数记', 4, 16, 26, 'そして会衆に告げた。「さあ、この悪い者どもの天幕から離れなさい。彼らのものには何もさわってはならない。彼らのすべての罪のゆえに、あなたがたが滅ぼし尽くされるといけないから。」'),
('JPN', '民数记', 4, 16, 27, 'それでみなは、コラとダタンとアビラムの住まいの周辺から離れ去った。ダタンとアビラムは、妻子、幼子たちと一緒に出て来て、自分たちの天幕の入り口に立った。'),
('JPN', '民数记', 4, 16, 28, 'モーセは言った。「私を遣わして、これらのわざを行わせたのは主であり、私自身の考えからではないことが、次のことによってあなたがたに分かる。'),
('JPN', '民数记', 4, 16, 29, 'もしこの者たちが、すべての人が死ぬように死に、すべての人の定めにあうなら、私を遣わしたのは主ではない。'),
('JPN', '民数记', 4, 16, 30, 'しかし、もし主がこれまでにないことを行われるなら、すなわち、地がその口を開けて、彼らと彼らに属する者たちをことごとく吞み込み、彼らが生きたままよみに下るなら、あなたがたはこれらの者たちが主を侮ったことを知らなければならない。」'),
('JPN', '民数记', 4, 16, 31, 'モーセがこれらのことばをみな言い終えるやいなや、彼らの足もとの地面が割れた。'),
('JPN', '民数记', 4, 16, 32, '地は口を開けて、彼らとその家族、またコラに属するすべての者と、すべての所有物を吞み込んだ。'),
('JPN', '民数记', 4, 16, 33, '彼らと彼らに属する者はみな、生きたまま、よみに下った。地は彼らを包み、彼らは集会の中から滅び失せた。'),
('JPN', '民数记', 4, 16, 34, '彼らの周りにいたイスラエル人はみな、彼らの叫び声を聞いて逃げた。「地がわれわれも吞み込んでしまわないか」と人々は思ったのである。'),
('JPN', '民数记', 4, 16, 35, 'また、火が主のところから出て、香を献げていた二百五十人を焼き尽くした。'),
('JPN', '民数记', 4, 16, 36, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 16, 37, '「あなたは、祭司アロンの子エルアザルに命じて、炎の中から火皿を取り出し、火を遠くにまき散らさせよ。それらは聖なるものとなっているから。'),
('JPN', '民数记', 4, 16, 38, 'いのちを失うことになったこれらの罪人たちの火皿は、打ちたたいて延べ板とし、祭壇のためのかぶせ物とせよ。それらは、主の前に献げられたので、聖なるものとなっているからである。これらはイスラエルの子らに対するしるしとなる。」'),
('JPN', '民数记', 4, 16, 39, 'そこで祭司エルアザルは、焼き殺された者たちが献げた青銅の火皿を取り、それを打ち延ばして祭壇のためのかぶせ物とし、'),
('JPN', '民数记', 4, 16, 40, 'そのことがイスラエルの子らに覚えられるようにした。これは、アロンの子孫以外の資格のない者が、主の前に進み出て香をたくことのないようにするため、その人が、コラやその仲間のような目にあわないようにするためである。主がモーセを通してエルアザルに言われたとおりである。'),
('JPN', '民数记', 4, 16, 41, 'その翌日、イスラエルの全会衆は、モーセとアロンに向かって不平を言った。「あなたがたは主の民を殺した。」'),
('JPN', '民数记', 4, 16, 42, '会衆がモーセとアロンに逆らって結集したとき、二人が会見の天幕の方を振り向くと、見よ、雲がそれをおおい、主の栄光が現れた。'),
('JPN', '民数记', 4, 16, 43, 'モーセとアロンは会見の天幕の前に来た。'),
('JPN', '民数记', 4, 16, 44, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 16, 45, '「あなたがたはこの会衆から離れ去れ。わたしはこの者どもをたちどころに絶ち滅ぼす。」二人はひれ伏した。'),
('JPN', '民数记', 4, 16, 46, 'モーセはアロンに言った。「火皿を取り、祭壇から火を取ってそれに入れ、その上に香を盛りなさい。そして急いで会衆のところへ持って行き、彼らのために宥めを行いなさい。主の前から激しい御怒りが出て来て、神からの罰がもう始まっている。」'),
('JPN', '民数记', 4, 16, 47, 'モーセが命じたとおり、アロンが火皿を取って集会のただ中に走って行くと、見よ、神の罰はすでに民のうちに始まっていた。彼は香をたいて、民のために宥めを行った。'),
('JPN', '民数记', 4, 16, 48, '彼が死んだ者たちと生きている者たちとの間に立ったとき、主の罰は終わった。'),
('JPN', '民数记', 4, 16, 49, 'コラの事件で死んだ者とは別に、この主の罰で死んだ者は、一万四千七百人であった。'),
('JPN', '民数记', 4, 16, 50, 'アロンが会見の天幕の入り口にいるモーセのところへ戻ったときに、主の罰は終わっていた。'),
('JPN', '民数记', 4, 17, 1, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 17, 2, '「イスラエルの子らに告げ、彼らから杖を、部族ごとに一本ずつ、彼らの部族のすべての族長から十二本の杖を取れ。その杖に各自の名を書き記さなければならない。'),
('JPN', '民数记', 4, 17, 3, 'レビの杖にはアロンの名を書き記さなければならない。彼らの部族のかしらにそれぞれ一本の杖とするからだ。'),
('JPN', '民数记', 4, 17, 4, 'あなたはそれらを、会見の天幕の中の、わたしがそこであなたがたに会うあかしの箱の前に置け。'),
('JPN', '民数记', 4, 17, 5, 'わたしが選ぶ人の杖は芽を出す。こうしてわたしは、イスラエルの子らがあなたがたに向かって言い立てている不平を、わたし自身から遠ざけ、鎮める。」'),
('JPN', '民数记', 4, 17, 6, 'モーセがイスラエルの子らにこのように告げたので、彼らの族長たちはみな、部族ごとに、族長一人に一本ずつの杖、十二本を彼に渡した。アロンの杖も彼らの杖の中にあった。'),
('JPN', '民数记', 4, 17, 7, 'モーセはそれらの杖を、主の前、すなわちあかしの天幕の中に置いた。'),
('JPN', '民数记', 4, 17, 8, 'その翌日、モーセはあかしの天幕に入って行った。すると見よ。レビの家のためのアロンの杖が芽を出し、つぼみをつけ、花を咲かせて、アーモンドの実を結んでいた。'),
('JPN', '民数记', 4, 17, 9, 'モーセがそれらの杖をみな、主の前からすべてのイスラエルの子らのところに持って来たので、彼らは見て、それぞれ自分の杖を取った。'),
('JPN', '民数记', 4, 17, 10, '主はモーセに言われた。「アロンの杖をあかしの箱の前に戻して、逆らう者たちへの戒めのために、しるしとせよ。彼らの不平をわたしから全くなくせ。彼らが死ぬことのないようにするためである。」'),
('JPN', '民数记', 4, 17, 11, 'モーセはそのようにした。主が命じられたとおりにしたのである。'),
('JPN', '民数记', 4, 17, 12, 'しかし、イスラエルの子らはモーセに言った。「ああ、われわれは死んでしまう。われわれは滅びる。全員が滅びるのだ。'),
('JPN', '民数记', 4, 17, 13, 'すべて近づく者、主の幕屋に近づく者が死ななければならないとは。ああ、われわれはみな、死に絶えなければならないのか。」'),
('JPN', '民数记', 4, 18, 1, 'そこで、主はアロンに言われた。「あなたと、あなたとともにいるあなたの子たちと、あなたの父の家の者たちは、聖所に関わる咎を負わなければならない。また、あなたと、あなたとともにいるあなたの子たちは、あなたがたの祭司職に関わる咎を負わなければならない。'),
('JPN', '民数记', 4, 18, 2, 'また、あなたの父祖の部族であるレビ部族の、あなたの身内の者たちも、あなたの近くに来させよ。彼らがあなたに連なり、あかしの天幕の前で、あなたと、あなたとともにいるあなたの子たちに仕えるためである。'),
('JPN', '民数记', 4, 18, 3, '彼らはあなたのための任務と、天幕全体の任務に当たる。しかし彼らは、聖なる用具と祭壇に近づいてはならない。彼らも、あなたがたも、死ぬことのないようにするためである。'),
('JPN', '民数记', 4, 18, 4, '彼らはあなたに連なり、天幕の奉仕のすべてに関わる、会見の天幕の任務に当たる。資格のない者があなたがたに近づいてはならない。'),
('JPN', '民数记', 4, 18, 5, 'あなたがたは、聖所の任務と祭壇の任務を果たしなさい。そうすれば、イスラエルの子らに再びわたしの激しい怒りが下ることはない。'),
('JPN', '民数记', 4, 18, 6, '今ここに、わたしは、あなたがたの同族レビ人をイスラエルの子らの中から取り、会見の天幕の奉仕をするために主に献げられた者として、あなたがたへの贈り物とする。'),
('JPN', '民数记', 4, 18, 7, 'あなたと、あなたとともにいるあなたの子たちは、祭壇に関するすべてのことや、垂れ幕の内側のことについて自分の祭司職を守り、奉仕しなければならない。わたしはあなたがたの祭司職の奉仕を賜物として与える。資格なしにこれに近づく者は殺されなければならない。」'),
('JPN', '民数记', 4, 18, 8, '主はまたアロンに言われた。「今わたしは、わたしへの奉納物に関わる任務をあなたに与える。わたしはイスラエルの子らのすべての聖なるささげ物について、これをあなたが受け取る分とし、またあなたの子たちへの永遠の割り当てとする。'),
('JPN', '民数记', 4, 18, 9, '火による最も聖なるもののうちで、あなたのものとなるのは次のとおりである。わたしに納めるすべてのささげ物、すなわち穀物のささげ物、罪のきよめのささげ物、代償のささげ物、これらすべては、あなたとあなたの子たちにとって最も聖なるものである。'),
('JPN', '民数记', 4, 18, 10, 'あなたはそれを最も聖なるものとして食べなければならない。すべての男子は、それを食べることができる。それはあなたにとって聖なるものである。'),
('JPN', '民数记', 4, 18, 11, 'また次の物もあなたのものとなる。イスラエルの子らの贈り物である奉納物、彼らのすべての奉献物、これをわたしはあなたと、あなたとともにいる息子たちと娘たちに与え、永遠の割り当てとする。あなたの家にいるきよい者はだれでも、それを食べることができる。'),
('JPN', '民数记', 4, 18, 12, '最良の新しい油、新しいぶどう酒の最良のものと穀物、人々が主に供えるこれらの初物すべてをあなたに与える。'),
('JPN', '民数记', 4, 18, 13, '彼らの地のすべてのものの初なりで、彼らが主に携えて来る物は、あなたのものになる。あなたの家にいるきよい者はだれでも、それを食べることができる。'),
('JPN', '民数记', 4, 18, 14, 'イスラエルのうちで聖絶の物はみな、あなたのものになる。'),
('JPN', '民数记', 4, 18, 15, '人でも家畜でも、主に献げられるすべての肉なるもので、最初に胎を開くものはみな、あなたのものとなる。ただし、人の長子は、必ず贖わなければならない。また、汚れた家畜の初子も贖わなければならない。'),
('JPN', '民数记', 4, 18, 16, 'その贖いの代金として、生後一か月たってから、一シェケル二十ゲラの聖所のシェケルで、銀五シェケルを払わなければならない。'),
('JPN', '民数记', 4, 18, 17, 'ただし、牛の初子、または羊の初子、あるいはやぎの初子は贖ってはならない。これらは聖なるものだからである。あなたはそれらの血を祭壇に振りかけ、脂肪を食物のささげ物、主への芳ばしい香りとして、焼いて煙にしなければならない。'),
('JPN', '民数记', 4, 18, 18, 'その肉はあなたのものとなる。それは奉献物の胸肉や右のもも肉と同様にあなたのものとなる。'),
('JPN', '民数记', 4, 18, 19, 'イスラエルの子らが主に献げる聖なる奉納物をみな、わたしは、あなたと、あなたとともにいる息子たちと娘たちに与えて、永遠の割り当てとする。それは、主の前にあって、あなたとあなたの子孫に対する永遠の塩の契約となる。」'),
('JPN', '民数记', 4, 18, 20, '主はまたアロンに言われた。「あなたは彼らの地で相続地を持ってはならない。彼らのうちに何の割り当て地も所有してはならない。イスラエルの子らの中にあって、わたしがあなたへの割り当てであり、あなたへのゆずりである。'),
('JPN', '民数记', 4, 18, 21, 'さらに、レビ族には、わたしは今、彼らが行う奉仕、会見の天幕での奉仕に報い、イスラエルのうちの十分の一をみな、ゆずりのものとして与える。'),
('JPN', '民数记', 4, 18, 22, 'これからはもう、イスラエルの子らは、会見の天幕に近づいてはならない。彼らが罪責を負って死ぬことのないようにするためである。'),
('JPN', '民数记', 4, 18, 23, '会見の天幕の奉仕をするのはレビ人であり、レビ人が彼らの咎を負う。これは代々にわたる永遠の掟である。彼らはイスラエルの子らの中にあって相続地を受け継いではならない。'),
('JPN', '民数记', 4, 18, 24, 'それは、イスラエルの子らが奉納物として主に献げる十分の一を、わたしが相続のものとしてレビ人に与えるからである。それゆえわたしは、彼らがイスラエルの子らの中で相続地を受け継いではならない、と彼らに言ったのである。」'),
('JPN', '民数记', 4, 18, 25, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 18, 26, '「あなたはレビ人に告げなければならない。わたしがあなたがたに相続のものとして与えた十分の一をイスラエルの子らから受け取るとき、あなたがたはその十分の一の十分の一を、主への奉納物として献げなさい。'),
('JPN', '民数记', 4, 18, 27, 'これは、打ち場からの穀物や、踏み場からの豊かなぶどう酒と同じように、あなたがたの奉納物と見なされる。'),
('JPN', '民数记', 4, 18, 28, 'こうして、あなたがたもまた、イスラエルの子らから受け取るすべての十分の一の中から、主への奉納物を献げなさい。その中から主への奉納物を祭司アロンに与えなさい。'),
('JPN', '民数记', 4, 18, 29, 'あなたがたへのすべての贈り物のうち、それぞれの最上の部分で聖別される分から主へのすべての奉納物を献げなさい。'),
('JPN', '民数记', 4, 18, 30, 'また、あなたは彼らに言え。あなたがたが、その中からその最上の部分を献げるとき、それはレビ人にとって打ち場からの収穫、踏み場からの収穫と見なされる。'),
('JPN', '民数记', 4, 18, 31, 'あなたがたとその家族は、どこででもそれを食べてよい。これは会見の天幕でのあなたがたの奉仕に対する報酬だからである。'),
('JPN', '民数记', 4, 18, 32, 'あなたがたが、その最上の部分を献げるとき、そのことで罪責を負うことはない。ただし、イスラエルの子らの聖なるささげ物を汚して、死ぬようなことがあってはならない。」'),
('JPN', '民数记', 4, 19, 1, '主はモーセとアロンに告げられた。'),
('JPN', '民数记', 4, 19, 2, '「主が命じるおしえの定めは、こうである。イスラエルの子らに告げよ。まだくびきを負わせたことがなく、傷のない完全な、赤い雌牛をあなたのところに引いて来るようにと。'),
('JPN', '民数记', 4, 19, 3, 'あなたがたはそれを祭司エルアザルに渡す。そして宿営の外に引き出し、彼の前で屠る。'),
('JPN', '民数记', 4, 19, 4, '祭司エルアザルは指で血を取り、会見の天幕の正面に向かってこの血を七度振りまく。'),
('JPN', '民数记', 4, 19, 5, 'その雌牛は彼の目の前で焼き、皮と肉と血を汚物とともに焼く。'),
('JPN', '民数记', 4, 19, 6, '祭司は、杉の木とヒソプと緋色の撚り糸を取り、雌牛が焼かれている中に投げ入れる。'),
('JPN', '民数记', 4, 19, 7, '祭司は自分の衣服を洗い、からだに水を浴びる。その後、宿営に入ることができる。しかし、この祭司は夕方まで汚れる。'),
('JPN', '民数记', 4, 19, 8, 'これを焼いた者も、自分の衣服を水で洗い、からだに水を浴びる。彼は夕方まで汚れる。'),
('JPN', '民数记', 4, 19, 9, 'それから、きよい人がその雌牛の灰を集め、宿営の外のきよい所に置く。そして、イスラエルの会衆のために、汚れを除く水を作るために保存しておく。これは罪のきよめのささげ物である。'),
('JPN', '民数记', 4, 19, 10, 'この雌牛の灰を集めた者は、自分の衣服を洗う。彼は夕方まで汚れている。これは、イスラエルの子らと、あなたがたの間に寄留している者にとって永遠の掟となる。'),
('JPN', '民数记', 4, 19, 11, '死人に触れる者は、それがどの人のものであれ、七日間汚れる。'),
('JPN', '民数记', 4, 19, 12, 'その者は三日目と七日目に、先の水で身の汚れを除いて、きよくなる。三日目と七日目に身の汚れを除かなければ、きよくならない。'),
('JPN', '民数记', 4, 19, 13, '死人、すなわち死んだ人間のたましいに触れ、身の汚れを除かない者はみな、主の幕屋を汚す。その者はイスラエルから断ち切られる。その者は汚れを除く水を振りかけられていないので汚れていて、その者の中になお汚れがあるからである。'),
('JPN', '民数记', 4, 19, 14, '人が天幕の中で死んだ場合のおしえは次のとおりである。その天幕に入る者と、天幕の中にいる者はみな、七日間汚れる。'),
('JPN', '民数记', 4, 19, 15, 'ふたをしていない口の開いた器もみな、汚れる。'),
('JPN', '民数记', 4, 19, 16, 'また、野外で、剣で刺し殺された者、死人、人の骨、墓に触れる者はみな、七日間汚れる。'),
('JPN', '民数记', 4, 19, 17, 'この汚れた者のためには、罪のきよめのために焼いて作った灰を取り、器に入れ、それに新鮮な水を加える。'),
('JPN', '民数记', 4, 19, 18, 'きよい人がヒソプを取ってこの水に浸し、それを天幕に、すべての器の上に、そこにいた者の上に、また骨、刺し殺された者、死人、墓に触れた者の上にかける。'),
('JPN', '民数记', 4, 19, 19, 'そのきよい人が、それを汚れた者に三日目と七日目に振りかけ、七日目にその人の汚れを除くことになる。その人は衣服を洗い、水を浴びる。その人は夕方にはきよくなる。'),
('JPN', '民数记', 4, 19, 20, '汚れた者が身の汚れを除かなければ、その人は集会の中から断ち切られる。主の聖所を汚したからである。汚れを除く水がその人に振りかけられなかったので、その人は汚れている。'),
('JPN', '民数记', 4, 19, 21, 'これは彼らに対する永遠の掟となる。汚れを除く水をかけた者は、その衣服を洗わなければならない。汚れを除く水に触れた者は夕方まで汚れる。'),
('JPN', '民数记', 4, 19, 22, '汚れた者が触れるものは、すべて汚れる。それに触れた者も夕方まで汚れる。」'),
('JPN', '民数记', 4, 20, 1, 'イスラエルの全会衆は、第一の月にツィンの荒野に入った。民はカデシュにとどまった。ミリアムはそこで死んで葬られた。'),
('JPN', '民数记', 4, 20, 2, 'そこには、会衆のための水がなかった。彼らは集まってモーセとアロンに逆らった。'),
('JPN', '民数记', 4, 20, 3, '民はモーセと争って言った。「ああ、われわれの兄弟たちが主の前で死んだとき、われわれも死んでいたらよかったのに。'),
('JPN', '民数记', 4, 20, 4, 'なぜ、あなたがたは主の集会をこの荒野に引き入れ、われわれと、われわれの家畜をここで死なせようとするのか。'),
('JPN', '民数记', 4, 20, 5, 'なぜ、あなたがたはわれわれをエジプトから連れ上り、このひどい場所に引き入れたのか。ここは穀物も、いちじくも、ぶどうも、ざくろも育つような場所ではない。そのうえ、飲み水さえない。」'),
('JPN', '民数记', 4, 20, 6, 'モーセとアロンは集会の前から去り、会見の天幕の入り口にやって来て、ひれ伏した。すると主の栄光が彼らに現れた。'),
('JPN', '民数记', 4, 20, 7, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 20, 8, '「杖を取れ。あなたとあなたの兄弟アロンは、会衆を集めよ。あなたがたが彼らの目の前で岩に命じれば、岩は水を出す。彼らのために岩から水を出して、会衆とその家畜に飲ませよ。」'),
('JPN', '民数记', 4, 20, 9, 'そこでモーセは、主が彼に命じられたとおりに、主の前から杖を取った。'),
('JPN', '民数记', 4, 20, 10, 'モーセとアロンは岩の前に集会を召集し、彼らに言った。「逆らう者たちよ。さあ、聞け。この岩から、われわれがあなたがたのために水を出さなければならないのか。」'),
('JPN', '民数记', 4, 20, 11, 'モーセは手を上げ、彼の杖で岩を二度打った。すると、豊かな水が湧き出たので、会衆もその家畜も飲んだ。'),
('JPN', '民数记', 4, 20, 12, 'しかし、主はモーセとアロンに言われた。「あなたがたはわたしを信頼せず、イスラエルの子らの見ている前でわたしが聖であることを現さなかった。それゆえ、あなたがたはこの集会を、わたしが彼らに与えた地に導き入れることはできない。」'),
('JPN', '民数记', 4, 20, 13, 'これがメリバの水である。イスラエルの子らが主と争った場所であり、主はご自分が聖であることを彼らのうちに示されたのである。'),
('JPN', '民数记', 4, 20, 14, 'さて、モーセはカデシュからエドムの王のもとに使者たちを遣わして言った。「あなたの兄弟、イスラエルはこう申します。あなたは私たちに降りかかったすべての困難をご存じです。'),
('JPN', '民数记', 4, 20, 15, '私たちの先祖はエジプトに下り、私たちはエジプトに長年住んでいました。しかしエジプトは私たちや先祖を虐待しました。'),
('JPN', '民数记', 4, 20, 16, '私たちが主に叫ぶと、主は私たちの声を聞いて、一人の御使いを遣わし、私たちをエジプトから導き出されました。今、私たちはあなたの領土の境界にある町、カデシュにおります。'),
('JPN', '民数记', 4, 20, 17, 'どうか、あなたの土地を通らせてください。私たちは、畑もぶどう畑も通りません。井戸の水も飲みません。私たちは『王の道』を行き、あなたの領土を通過するまでは、右にも左にもそれません。」'),
('JPN', '民数记', 4, 20, 18, 'しかし、エドムはモーセに言った。「私のところを通ってはならない。通るなら、私は剣をもっておまえを迎え撃つ。」'),
('JPN', '民数记', 4, 20, 19, 'イスラエルの子らはエドムに言った。「私たちは大路を上って行きます。私たちと私たちの家畜があなたの水を飲むことがあれば、その代価を払います。歩いて通り過ぎるだけですから、何事でもないでしょう。」'),
('JPN', '民数记', 4, 20, 20, 'しかし、エドムは、「通ってはならない」と言って、強力な大軍勢を率いて彼らを迎え撃つために出て来た。'),
('JPN', '民数记', 4, 20, 21, 'こうして、エドムはイスラエルにその領土を通らせることを拒んだので、イスラエルは彼のところから向きを変えた。'),
('JPN', '民数记', 4, 20, 22, 'イスラエルの全会衆はカデシュを旅立ち、ホル山に着いた。'),
('JPN', '民数记', 4, 20, 23, '主は、エドムの国境に近いホル山で、モーセとアロンにお告げになった。'),
('JPN', '民数记', 4, 20, 24, '「アロンは自分の民に加えられる。彼は、わたしがイスラエルの子らに与えた地に入ることはできない。それはメリバの水のことで、あなたがたがわたしの命に逆らったからである。'),
('JPN', '民数记', 4, 20, 25, 'あなたはアロンと、その子エルアザルを連れてホル山に登れ。'),
('JPN', '民数记', 4, 20, 26, 'アロンの衣服を脱がせ、それをその子エルアザルに着せよ。アロンは自分の民に加えられ、そこで死ぬ。」'),
('JPN', '民数记', 4, 20, 27, 'モーセは、主が命じられたとおりに行った。彼らは、全会衆の見ている前でホル山に登って行った。'),
('JPN', '民数记', 4, 20, 28, 'モーセはアロンの衣服を脱がせ、それをその子エルアザルに着せた。アロンはその山の頂で死んだ。モーセとエルアザルが山から下りて来たとき、'),
('JPN', '民数记', 4, 20, 29, '全会衆はアロンが息絶えたのを知った。そのためイスラエルの全家は三十日の間、アロンのために泣き悲しんだ。'),
('JPN', '民数记', 4, 21, 1, 'ネゲブに住んでいたカナン人アラドの王は、イスラエルがアタリムの道を進んで来たと聞いた。彼はイスラエルと戦い、その何人かを捕虜として捕らえた。'),
('JPN', '民数记', 4, 21, 2, 'そこでイスラエルは主に誓願をして言った。「もし、確かにあなたが私の手に、この民を渡してくださるなら、私は彼らの町々を聖絶いたします。」'),
('JPN', '民数记', 4, 21, 3, '主はイスラエルの願いを聞き入れ、カナン人を渡されたので、イスラエルはカナン人とその町々を聖絶した。そしてその場所の名をホルマと呼んだ。'),
('JPN', '民数记', 4, 21, 4, '彼らはホル山から、エドムの地を迂回しようとして、葦の海の道に旅立った。しかし民は、途中で我慢ができなくなり、'),
('JPN', '民数记', 4, 21, 5, '神とモーセに逆らって言った。「なぜ、あなたがたはわれわれをエジプトから連れ上って、この荒野で死なせようとするのか。パンもなく、水もない。われわれはこのみじめな食べ物に飽き飽きしている。」'),
('JPN', '民数记', 4, 21, 6, 'そこで主は民の中に燃える蛇を送られた。蛇は民にかみついたので、イスラエルのうちの多くの者が死んだ。'),
('JPN', '民数记', 4, 21, 7, '民はモーセのところに来て言った。「私たちは主とあなたを非難したりして、罪を犯しました。どうか、蛇を私たちから取り去ってくださるよう主に祈ってください。」モーセは民のために祈った。'),
('JPN', '民数记', 4, 21, 8, 'すると主はモーセに言われた。「あなたは燃える蛇を作り、それを旗ざおの上に付けよ。かまれた者はみな、それを仰ぎ見れば生きる。」'),
('JPN', '民数记', 4, 21, 9, 'モーセは一つの青銅の蛇を作り、それを旗ざおの上に付けた。蛇が人をかんでも、その人が青銅の蛇を仰ぎ見ると生きた。'),
('JPN', '民数记', 4, 21, 10, 'イスラエルの子らは旅立って、オボテで宿営した。'),
('JPN', '民数记', 4, 21, 11, '彼らはオボテを旅立ち、日の昇る方、モアブに面した荒野にあるイエ・ハ・アバリムに宿営した。'),
('JPN', '民数记', 4, 21, 12, '彼らはそこを旅立ち、ゼレデの谷に宿営し、'),
('JPN', '民数记', 4, 21, 13, 'さらにそこを旅立って、アモリ人の国境から広がっている荒野にある、アルノン川の対岸に宿営した。アルノン川は、モアブとアモリ人との間にあるモアブの国境だったからである。'),
('JPN', '民数记', 4, 21, 14, 'それで、『主の戦いの書』にもこう言われている。「スパのワヘブとアルノンの谷川とともに、'),
('JPN', '民数记', 4, 21, 15, 'アルの定住地に達する谷川の支流は、モアブの領土を支えている。」'),
('JPN', '民数记', 4, 21, 16, '彼らはそこからベエルに向かった。それは主がモーセに、「民を集めよ。わたしが彼らに水を与える」と言われた井戸である。'),
('JPN', '民数记', 4, 21, 17, 'そのとき、イスラエルはこの歌を歌った。「井戸よ、湧きいでよ。あなたがたは、これに向かって歌え。'),
('JPN', '民数记', 4, 21, 18, '笏をもって、杖をもって、君主たちが掘り、民の尊き者たちが掘り下げたその井戸に。」彼らは荒野からマタナに進み、'),
('JPN', '民数记', 4, 21, 19, 'マタナからナハリエルに、ナハリエルからバモテに、'),
('JPN', '民数记', 4, 21, 20, 'バモテからモアブの野にある谷に行き、荒れ野を見下ろすピスガの頂に着いた。'),
('JPN', '民数记', 4, 21, 21, 'イスラエルは、アモリ人の王シホンに使者たちを遣わして言った。'),
('JPN', '民数记', 4, 21, 22, '「あなたの土地を通らせてください。私たちは畑にもぶどう畑にもそれて入りません。井戸の水も飲みません。あなたの領土を通過するまで、私たちは『王の道』を通ります。」'),
('JPN', '民数记', 4, 21, 23, 'しかし、シホンはイスラエルが自分の領土を通ることを許さなかった。シホンはその兵をみな集めて、イスラエルを迎え撃つために荒野に出て来た。そしてヤハツに来てイスラエルと戦った。'),
('JPN', '民数记', 4, 21, 24, 'イスラエルは剣の刃でシホンを討ち、その地をアルノン川からヤボク川まで、アンモン人の国境まで占領した。アンモン人の国境は堅固だった。'),
('JPN', '民数记', 4, 21, 25, 'イスラエルはこれらの町々をすべて取った。そしてイスラエルは、アモリ人のすべての町、ヘシュボンとそれに属するすべての村に住んだ。'),
('JPN', '民数记', 4, 21, 26, 'ヘシュボンはアモリ人の王シホンの町であった。彼はモアブの以前の王と戦って、その手からその全土をアルノンまで奪っていた。'),
('JPN', '民数记', 4, 21, 27, 'それで、詩のことばを語る者たちも言っている。「来たれ、ヘシュボンに。シホンの町は建てられ、堅くされている。'),
('JPN', '民数记', 4, 21, 28, 'ヘシュボンから火が出た。シホンの町から炎が。それはモアブのアルを、アルノンにそびえる高地を焼き尽くした。'),
('JPN', '民数记', 4, 21, 29, 'モアブよ、おまえはわざわいだ。ケモシュの民よ、おまえは滅び失せる。その息子たちは逃亡者、娘たちは捕らわれの身。アモリ人の王シホンの手によって。'),
('JPN', '民数记', 4, 21, 30, 'しかし、われわれは彼らを投げ倒し、ヘシュボンはディボンに至るまで滅び失せた。われわれはノファフまで荒らし、それはメデバにまで至った。」'),
('JPN', '民数记', 4, 21, 31, 'こうしてイスラエルはアモリ人の地に住んだ。'),
('JPN', '民数记', 4, 21, 32, 'そのとき、モーセは人を遣わしてヤゼルを探り、ついにそれに属する村々を攻め取り、そこにいたアモリ人を追い出した。'),
('JPN', '民数记', 4, 21, 33, 'さらに彼らが向きを変えてバシャンへの道を上って行くと、バシャンの王オグが、エデレイで戦うために、そのすべての兵とともに彼らの方に出て来た。'),
('JPN', '民数记', 4, 21, 34, '主はモーセに言われた。「彼を恐れてはならない。わたしは彼とそのすべての兵とその地をあなたの手に与えた。あなたがヘシュボンに住んでいたアモリ人の王シホンに行ったように、彼にも行え。」'),
('JPN', '民数记', 4, 21, 35, 'そこで彼らは、彼とその子たちとそのすべての兵を討ち、一人の生存者も残さなかった。こうして彼らはその地を占領した。'),
('JPN', '民数记', 4, 22, 1, 'イスラエルの子らは旅を続け、ヨルダンのエリコの対岸にあるモアブの草原に宿営した。'),
('JPN', '民数记', 4, 22, 2, 'ツィポルの子バラクは、イスラエルがアモリ人に行ったすべてのことを見た。'),
('JPN', '民数记', 4, 22, 3, 'モアブは、イスラエルの民の数が多かったので非常におびえた。それでモアブはイスラエル人に恐怖を抱いた。'),
('JPN', '民数记', 4, 22, 4, 'モアブはミディアンの長老たちに言った。「今、この集会は、牛が野の青草をなめ尽くすように、われわれの周りのすべてのものをなめ尽くそうとしている。」ツィポルの子バラクは当時、モアブの王であったが、'),
('JPN', '民数记', 4, 22, 5, '同族の国にある、あの大河のほとりのペトルにいるベオルの子バラムを招こうと、使者たちを遣わして言った。「見なさい。一つの民がエジプトから出て来た。今や、彼らは地の面をおおい、私の目の前にいる。'),
('JPN', '民数记', 4, 22, 6, '今来て、私のためにこの民をのろってもらいたい。この民は私より強い。そうしてくれれば、おそらく私は彼らを討って、この地から追い出すことができるだろう。あなたが祝福する者は祝福され、あなたがのろう者はのろわれることを、私はよく知っている。」'),
('JPN', '民数记', 4, 22, 7, 'モアブの長老たちとミディアンの長老たちは、占い料を手にしてバラムのところに行き、バラクのことばを告げた。'),
('JPN', '民数记', 4, 22, 8, 'バラムは彼らに言った。「今夜はここに泊まりなさい。主が私に告げられるとおりに、あなたがたに返答しましょう。」モアブの長たちはバラムのもとにとどまった。'),
('JPN', '民数记', 4, 22, 9, '神はバラムのところに来て言われた。「あなたと一緒にいるこの者たちは何者か。」'),
('JPN', '民数记', 4, 22, 10, 'バラムは神に言った。「モアブの王ツィポルの子バラクが、私のところに使いをよこし、'),
('JPN', '民数记', 4, 22, 11, '『今ここに、エジプトから出て来た民がいて、地の面をおおっている。さあ来て、私のためにこの民に呪いをかけてくれ。そうしたら、おそらく私は彼らと戦って、追い出すことができるだろう』と申しました。」'),
('JPN', '民数记', 4, 22, 12, '神はバラムに言われた。「あなたは彼らと一緒に行ってはならない。また、その民をのろってもいけない。その民は祝福されているのだから。」'),
('JPN', '民数记', 4, 22, 13, '朝になると、バラムは起きてバラクの長たちに言った。「あなたがたの国に帰りなさい。主は私があなたがたと一緒に行くことをお許しにならないから。」'),
('JPN', '民数记', 4, 22, 14, 'モアブの長たちは立ってバラクのところに帰り、そして言った。「バラムは私たちと一緒に来ることを拒みました。」'),
('JPN', '民数记', 4, 22, 15, 'バラクはもう一度、先の者たちよりも大勢の、しかも位の高い長たちを遣わした。'),
('JPN', '民数记', 4, 22, 16, '彼らはバラムのところに来て彼に言った。「ツィポルの子バラクはこう申しました。『どうか私のところに来るのを断らないでください。'),
('JPN', '民数记', 4, 22, 17, '私はあなたを手厚くもてなします。また、あなたが私に言いつけられることは何でもします。どうか来て、私のためにこの民に呪いをかけてください。』」'),
('JPN', '民数记', 4, 22, 18, 'しかし、バラムはバラクの家臣たちに答えた。「たとえバラクが銀や金で満ちた彼の家をくれても、私は私の神、主の命を破ることは、事の大小にかかわらず、断じてできません。'),
('JPN', '民数记', 4, 22, 19, 'ですから、あなたがたもまた、今晩ここにとどまりなさい。主が私に何かほかのことをお告げくださるかどうか、確かめましょう。」'),
('JPN', '民数记', 4, 22, 20, '夜、神はバラムのところに来て、彼に言われた。「この者たちがあなたを招きに来たのなら、立って彼らと一緒に行け。だが、あなたはただ、わたしがあなたに告げることだけを行え。」'),
('JPN', '民数记', 4, 22, 21, 'バラムは朝起きて、自分のろばに鞍をつけ、モアブの長たちと一緒に行った。'),
('JPN', '民数记', 4, 22, 22, 'しかし、彼が行こうとすると、神の怒りが燃え上がり、主の使いが彼に敵対して道に立ちはだかった。バラムはろばに乗っていて、二人の若者がそばにいた。'),
('JPN', '民数记', 4, 22, 23, 'ろばは、主の使いが抜き身の剣を手に持って、道に立ちはだかっているのを見た。ろばは道からそれて畑に入って行ったので、バラムはろばを打って道に戻そうとした。'),
('JPN', '民数记', 4, 22, 24, 'すると主の使いは、両側に石垣のある、ぶどう畑の間の狭い道に立った。'),
('JPN', '民数记', 4, 22, 25, 'ろばは主の使いを見て、石垣にからだを押しつけ、バラムの足を石垣に押しつけたので、バラムはさらにろばを打った。'),
('JPN', '民数记', 4, 22, 26, '主の使いはさらに進んで行って、狭くて、右にも左にもよける余地のない場所に立った。'),
('JPN', '民数记', 4, 22, 27, 'ろばは主の使いを見て、バラムを乗せたまま、うずくまってしまった。バラムは怒りを燃やし、杖でろばを打った。'),
('JPN', '民数记', 4, 22, 28, 'すると、主がろばの口を開かれたので、ろばはバラムに言った。「私があなたに何をしたというのですか。私を三度も打つとは。」'),
('JPN', '民数记', 4, 22, 29, 'バラムはろばに言った。「おまえが私をばかにしたからだ。もし私の手に剣があれば、今、おまえを殺してしまうところだ。」'),
('JPN', '民数记', 4, 22, 30, 'ろばはバラムに言った。「私は、あなたが今日この日までずっと乗ってこられた、あなたのろばではありませんか。私がかつて、あなたにこのようなことをしたことがあったでしょうか。」バラムは答えた。「いや、なかった。」'),
('JPN', '民数记', 4, 22, 31, 'そのとき、主はバラムの目の覆いを除かれた。すると彼は、主の使いが道に立ちはだかり、抜き身の剣を手に持っているのを見た。彼はひざまずき、伏し拝んだ。'),
('JPN', '民数记', 4, 22, 32, '主の使いは彼に言った。「何のために、あなたは自分のろばを三度も打ったのか。わたしが敵対者として出て来ていたのだ。あなたがわたしの道を踏み外していたからだ。'),
('JPN', '民数记', 4, 22, 33, 'ろばはわたしを見て、三度もわたしから身を避けた。もし、ろばがわたしから身を避けていなかったなら、わたしは今すでに、あなたを殺して、ろばを生かしていたことだろう。」'),
('JPN', '民数记', 4, 22, 34, 'バラムは主の使いに言った。「私は罪を犯していました。あなたが私をとどめようと道に立ちはだかっておられたのを、私は知りませんでした。今、もし、あなたのお気に召さなければ、私は引き返します。」'),
('JPN', '民数记', 4, 22, 35, '主の使いはバラムに言った。「その人たちと一緒に行け。しかし、わたしがあなたに告げることばだけを告げよ。」そこでバラムはバラクの長たちと一緒に行った。'),
('JPN', '民数记', 4, 22, 36, 'バラクはバラムが来たことを聞いて、彼を迎えに、国境の端にあるアルノンの国境のイル・モアブまで出て来た。'),
('JPN', '民数记', 4, 22, 37, 'バラクはバラムに言った。「私はあなたを迎えようと、人を遣わさなかったでしょうか。なぜ、私のところに来てくださらなかったのですか。私には、あなたをおもてなしすることが、本当にできないのでしょうか。」'),
('JPN', '民数记', 4, 22, 38, 'バラムはバラクに言った。「ご覧なさい。私は今あなたのところに来ているではありませんか。私に何が言えるでしょう。神が私の口に置かれることば、それを私は告げなければなりません。」'),
('JPN', '民数记', 4, 22, 39, 'バラムはバラクと一緒に行き、キルヤテ・フツォテに着いた。'),
('JPN', '民数记', 4, 22, 40, 'バラクは牛と羊をいけにえとして献げ、それをバラムおよび彼とともにいた長たちにも贈った。'),
('JPN', '民数记', 4, 22, 41, '朝になると、バラクはバラムを連れ出し、彼をバモテ・バアルに上らせた。バラムはそこからイスラエルの民の一部を見た。'),
('JPN', '民数记', 4, 23, 1, 'バラムはバラクに言った。「私のためにここに七つの祭壇を築き、七頭の雄牛と七匹の雄羊をここに用意してください。」'),
('JPN', '民数记', 4, 23, 2, 'バラクはバラムの言ったとおりにした。そしてバラクとバラムは、祭壇の上で雄牛一頭と雄羊一匹を献げた。'),
('JPN', '民数记', 4, 23, 3, 'バラムはバラクに言った。「あなたは、あなたの全焼のささげ物のそばに立っていてください。私は行って来ます。おそらく、主は私に会ってくださるでしょう。主が私にお示しになることを、あなたに知らせましょう。」そして彼は裸の丘に行った。'),
('JPN', '民数记', 4, 23, 4, '神がバラムに会われたので、バラムは神に言った。「私は七つの祭壇を整え、それぞれの祭壇の上で雄牛一頭と雄羊一匹を献げました。」'),
('JPN', '民数记', 4, 23, 5, '主はバラムの口にことばを置き、そして言われた。「バラクのところに帰って、こう告げなければならない。」'),
('JPN', '民数记', 4, 23, 6, '彼がバラクのところに帰ると、見よ、バラクはモアブのすべての長たちと一緒に、自分の全焼のささげ物のそばに立っていた。'),
('JPN', '民数记', 4, 23, 7, 'バラムは彼の詩のことばを口にして言った。「バラクは、アラムから、モアブの王は、東の山々から私を連れて来た。『来て、私のためにヤコブをのろえ。来て、イスラエルを責めよ』と。'),
('JPN', '民数记', 4, 23, 8, '私はどうして呪いをかけられるだろうか。神が呪いをかけない者に。私はどうして責めることができるだろうか。主が責めない者を。'),
('JPN', '民数记', 4, 23, 9, '岩山の頂から私はこれを見、丘の上から私はこれを見つめる。見よ、この民はひとり離れて住み、自分を国々と同じだと見なさない。'),
('JPN', '民数记', 4, 23, 10, 'だれがヤコブのちりを数え、イスラエルの四分の一さえ数えられるだろうか。私が心の直ぐな人たちの死を遂げますように。私の最期が彼らと同じようになりますように。」'),
('JPN', '民数记', 4, 23, 11, 'バラクはバラムに言った。「あなたは私に何ということをしたのですか。私の敵に呪いをかけてもらうためにあなたを連れて来たのに、今、あなたはただ祝福しただけです。」'),
('JPN', '民数记', 4, 23, 12, 'バラムは答えた。「主が私の口に置かれること、それを忠実に語ってはいけないのですか。」'),
('JPN', '民数记', 4, 23, 13, 'バラクは彼に言った。「では、私と一緒に彼らを見ることができる別の場所へ行ってください。その一部を見るだけで、全体を見ることはできませんが。そこから私のために彼らに呪いをかけてください。」'),
('JPN', '民数记', 4, 23, 14, 'バラクはバラムを、セデ・ツォフィムのピスガの頂に連れて行き、そこで七つの祭壇を築き、どの祭壇にも雄牛一頭と雄羊一匹を献げた。'),
('JPN', '民数记', 4, 23, 15, 'バラムはバラクに言った。「あなたはここで、自分の全焼のささげ物のそばに立っていてください。私はあちらで主にお会いします。」'),
('JPN', '民数记', 4, 23, 16, '主はバラムに会い、その口にことばを置き、そして言われた。「バラクのところに帰って、こう告げなければならない。」'),
('JPN', '民数记', 4, 23, 17, 'それで、彼はバラクのところに帰った。すると、彼はモアブの長たちと一緒に、自分の全焼のささげ物のそばに立っていた。バラクは言った。「主は何をお告げになりましたか。」'),
('JPN', '民数记', 4, 23, 18, 'バラムは彼の詩のことばを口にして言った。「立て、バラクよ。そして聞け。私に耳を傾けよ。ツィポルの子よ。'),
('JPN', '民数记', 4, 23, 19, '神は人ではないから、偽りを言うことがない。人の子ではないから、悔いることがない。神が仰せられたら、実行されないだろうか。語られたら、成し遂げられないだろうか。'),
('JPN', '民数记', 4, 23, 20, '見よ、私は、祝福せよとの命を受けた。神が祝福されたのだ。私はそれをくつがえすことはできない。'),
('JPN', '民数记', 4, 23, 21, 'ヤコブの中に不法は見出されず、イスラエルの中に邪悪さは見られない。彼らの神、主は彼らとともにおられ、王をたたえる声が彼らの中にある。'),
('JPN', '民数记', 4, 23, 22, '彼らをエジプトから導き出された神は、彼らにとって野牛の角のようだ。'),
('JPN', '民数记', 4, 23, 23, 'まことに、ヤコブのうちにまじないはなく、イスラエルのうちに占いはない。神が何をなさるかは、時に応じてヤコブに、すなわちイスラエルに告げられる。'),
('JPN', '民数记', 4, 23, 24, '見よ、一つの民を。それは雌獅子のように起き上がり、雄獅子のように身を持ち上げ、休むことはない。獲物を食らい、殺されたものの血を飲むまでは。」'),
('JPN', '民数记', 4, 23, 25, 'バラクはバラムに言った。「彼らに呪いをかけることも祝福することも、決してしないでください。」'),
('JPN', '民数记', 4, 23, 26, 'バラムはバラクに答えた。「私は、主が告げられることはみな、しなければならない、とあなたに言ったではありませんか。」'),
('JPN', '民数记', 4, 23, 27, 'バラクはバラムに言った。「では、私はあなたを、もう一つ別の場所へ連れて行きましょう。もしかしたら、それが神の御目にかなって、あなたは私のために、そこから彼らに呪いをかけることができるかもしれません。」'),
('JPN', '民数记', 4, 23, 28, 'バラクはバラムを、荒れ野を見下ろすペオルの頂上に連れて行った。'),
('JPN', '民数记', 4, 23, 29, 'バラムはバラクに言った。「私のためにここに七つの祭壇を築き、七頭の雄牛と七匹の雄羊をここに用意してください。」'),
('JPN', '民数记', 4, 23, 30, 'バラクはバラムが言ったとおりにして、祭壇に雄牛と雄羊を献げた。'),
('JPN', '民数记', 4, 24, 1, 'バラムはイスラエルを祝福することが主の目にかなうのを見て、これまでのようにまじないを求めに行くことをせず、その顔を荒野に向けた。'),
('JPN', '民数记', 4, 24, 2, 'バラムが目を上げると、イスラエルがその部族ごとに宿っているのが見えた。すると、神の霊が彼の上に臨んだ。'),
('JPN', '民数记', 4, 24, 3, '彼は、彼の詩のことばを口にして言った。「ベオルの子バラムの告げたことば。目の開かれた者の告げたことば。'),
('JPN', '民数记', 4, 24, 4, '神の御告げを聞く者、全能者の幻を見る者、ひれ伏し、目の開かれた者の告げたことば。'),
('JPN', '民数记', 4, 24, 5, 'なんとすばらしいことよ。ヤコブよ、あなたの天幕は。イスラエルよ、あなたの住まいは。'),
('JPN', '民数记', 4, 24, 6, 'それは、広がる谷のよう、また川のほとりの園のようだ。主が植えたアロエのよう、また水辺の杉の木のようだ。'),
('JPN', '民数记', 4, 24, 7, 'その手桶からは水があふれ、種は豊かな水に潤う。王はアガグよりも高くなり、王国は高く上げられる。'),
('JPN', '民数记', 4, 24, 8, '彼をエジプトから導き出された神は、彼にとっては野牛の角のようだ。彼は自分の敵の国々を食い尽くし、彼らの骨をかみ砕き、矢をもって撃ち砕く。'),
('JPN', '民数记', 4, 24, 9, '雄獅子のように、また雌獅子のように、彼は身を伏せ、横たわる。だれがこれを起こせるだろう。あなたを祝福する者は祝福され、あなたをのろう者はのろわれる。」'),
('JPN', '民数记', 4, 24, 10, 'バラクはバラムに対して怒りを燃やし、手を打ち鳴らした。バラクはバラムに言った。「私の敵に呪いをかけてもらうためにおまえを招いたのに、かえっておまえは三度までも彼らを祝福した。'),
('JPN', '民数记', 4, 24, 11, '今、おまえは自分のところに引き下がれ。私は手厚くもてなすつもりでいたが、主がもう、そのもてなしを拒まれたのだ。」'),
('JPN', '民数记', 4, 24, 12, 'バラムはバラクに言った。「私は、あなたが遣わした使者たちにも、こう言ったではありませんか。'),
('JPN', '民数记', 4, 24, 13, '『たとえバラクが私に銀や金で満ちた彼の家をくれても、主のことばに背くことは、良いことでも悪いことでも、私の心のままにすることはできません。主が告げられること、それを私は告げなければなりません。』'),
('JPN', '民数记', 4, 24, 14, '今、私は自分の民のところに帰ります。さあ、私は、この民が終わりの日にあなたの民に行おうとしていることについて、あなたに助言を与えます。」'),
('JPN', '民数记', 4, 24, 15, 'そして彼の詩のことばを口にして言った。「ベオルの子バラムの告げたことば。目の開かれた者の告げたことば。'),
('JPN', '民数记', 4, 24, 16, '神の御告げを聞く者、いと高き方の知識を知る者、全能者の幻を見る者、ひれ伏し、目の開かれた者の告げたことば。'),
('JPN', '民数记', 4, 24, 17, '私には彼が見える。しかし今のことではない。私は彼を見つめる。しかし近くのことではない。ヤコブから一つの星が進み出る。イスラエルから一本の杖が起こり、モアブのこめかみを、すべてのセツの子らの脳天を打ち砕く。'),
('JPN', '民数记', 4, 24, 18, 'その敵、エドムは所有地となり、セイルも所有地となる。イスラエルは力ある働きをする。'),
('JPN', '民数记', 4, 24, 19, 'ヤコブから出る者が治め、残った者たちを町から絶やす。」'),
('JPN', '民数记', 4, 24, 20, '彼はアマレクを見渡して、彼の詩のことばを口にして言った。「アマレクは国々の中で最高のもの。しかし、その終わりは滅びに至る。」'),
('JPN', '民数记', 4, 24, 21, '彼はケニ人を見渡して、彼の詩のことばを口にして言った。「あなたの住みかは堅固で、あなたの巣は岩間に置かれている。'),
('JPN', '民数记', 4, 24, 22, 'しかし、カインは滅ぼし尽くされ、ついにはアッシュルがあなたを捕虜とする。」'),
('JPN', '民数记', 4, 24, 23, 'また彼は、彼の詩のことばを口にして言った。「ああ、神が定められたなら、だれが生き延びられるだろう。'),
('JPN', '民数记', 4, 24, 24, '船がキティムの岸から来て、アッシュルを苦しめ、エベルを苦しめる。これもまた、滅びに至る。」'),
('JPN', '民数记', 4, 24, 25, 'バラムは立って自分のところへ帰って行った。バラクも帰途についた。'),
('JPN', '民数记', 4, 25, 1, 'イスラエルはシティムにとどまっていたが、民はモアブの娘たちと淫らなことをし始めた。'),
('JPN', '民数记', 4, 25, 2, 'その娘たちが、自分たちの神々のいけにえの食事に民を招くと、民は食し、娘たちの神々を拝んだ。'),
('JPN', '民数记', 4, 25, 3, 'こうしてイスラエルはバアル・ペオルとくびきをともにした。すると、主の怒りがイスラエルに対して燃え上がった。'),
('JPN', '民数记', 4, 25, 4, '主はモーセに言われた。「この民のかしらたちをみな捕らえて、主の前で、白日の下にさらし者にせよ。そうすれば、主の燃える怒りはイスラエルから離れ去る。」'),
('JPN', '民数记', 4, 25, 5, 'そこでモーセはイスラエルのさばき人たちに言った。「あなたがたは、それぞれ自分の配下でバアル・ペオルとくびきをともにした者たちを殺せ。」'),
('JPN', '民数记', 4, 25, 6, 'ちょうどそのとき、一人のイスラエル人の男がやって来た。彼は、モーセと、会見の天幕の入り口で泣いているイスラエルの全会衆の目の前で、一人のミディアン人の女を自分の兄弟たちに近づかせた。'),
('JPN', '民数记', 4, 25, 7, '祭司アロンの子エルアザルの子ピネハスはそれを見るや、会衆の中から立ち上がり、槍を手に取り、'),
('JPN', '民数记', 4, 25, 8, 'そのイスラエル人の男の後を追ってテントの奥の部屋に入り、イスラエル人の男とその女の二人を、腹を刺して殺した。するとイスラエルの子らへの主の罰が終わった。'),
('JPN', '民数记', 4, 25, 9, 'この主の罰で死んだ者は、二万四千人であった。'),
('JPN', '民数记', 4, 25, 10, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 25, 11, '「祭司アロンの子エルアザルの子ピネハスは、イスラエルの子らに対するわたしの憤りを押しとどめた。彼がイスラエルの子らのただ中で、わたしのねたみを自分のねたみとしたからである。それでわたしは、わたしのねたみによって、イスラエルの子らを絶ち滅ぼすことはしなかった。'),
('JPN', '民数记', 4, 25, 12, 'それゆえ、言え。『見よ、わたしは彼にわたしの平和の契約を与える。'),
('JPN', '民数记', 4, 25, 13, 'これは、彼とその後の彼の子孫にとって、永遠にわたる祭司職の契約となる。それは、彼が神のねたみを自分のものとし、イスラエルの子らのために宥めを行ったからである。』」'),
('JPN', '民数记', 4, 25, 14, 'その殺されたイスラエル人の男、すなわちミディアン人の女と一緒に殺された者の名は、シメオン人の一族の長サルの子ジムリであった。'),
('JPN', '民数记', 4, 25, 15, 'また殺されたミディアン人の女の名はツルの娘コズビであった。ツルはミディアンの父の家の諸氏族のかしらであった。'),
('JPN', '民数记', 4, 25, 16, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 25, 17, '「ミディアン人を襲い、彼らを討て。'),
('JPN', '民数记', 4, 25, 18, '彼らは巧妙に仕組んだ企みによって、ペオルの事件であなたがたを襲ったからだ。ペオルの事件の主の罰の日に殺された彼らの同族の女、ミディアンの族長の娘コズビの一件だ。」'),
('JPN', '民数记', 4, 26, 1, 'この主の罰の後のことであった。主はモーセと祭司アロンの子エルアザルに告げられた。'),
('JPN', '民数记', 4, 26, 2, '「イスラエルの全会衆について、一族ごとに、二十歳以上で、イスラエルで戦に出ることができる者すべての頭数を調べなさい。」'),
('JPN', '民数记', 4, 26, 3, 'そこでモーセと祭司エルアザルは、エリコをのぞむヨルダン川のほとりのモアブの草原で、彼らに告げた。'),
('JPN', '民数记', 4, 26, 4, '「主がモーセに命じられたように、二十歳以上の者を数えなさい。」エジプトの地から出て来たイスラエルの子らは、'),
('JPN', '民数记', 4, 26, 5, 'イスラエルの長子ルベン。ルベン族は、ハノクからはハノク族、パルからはパル族、'),
('JPN', '民数记', 4, 26, 6, 'ヘツロンからはヘツロン族、カルミからはカルミ族。'),
('JPN', '民数记', 4, 26, 7, 'これらがルベン人諸氏族で、登録された者は、四万三千七百三十人であった。'),
('JPN', '民数记', 4, 26, 8, 'パルの子孫はエリアブ。'),
('JPN', '民数记', 4, 26, 9, 'エリアブの子はネムエル、ダタン、アビラム。このダタンとアビラムは会衆から召し出された者であったが、コラの仲間としてモーセとアロンに逆らい、主に逆らった。'),
('JPN', '民数记', 4, 26, 10, 'そのとき、地は口を開けて、コラとともに彼らを吞み込んだ。それは、その仲間たちが死んだときのこと、火が二百五十人の男を食い尽くしたときのことである。こうして彼らは警告のしるしとなった。'),
('JPN', '民数记', 4, 26, 11, 'ただし、コラの子たちは死ななかった。'),
('JPN', '民数记', 4, 26, 12, 'シメオン族の諸氏族は、それぞれ、ネムエルからはネムエル族、ヤミンからはヤミン族、ヤキンからはヤキン族、'),
('JPN', '民数记', 4, 26, 13, 'ゼラフからはゼラフ族、シャウルからはシャウル族。'),
('JPN', '民数记', 4, 26, 14, 'これらがシメオン人諸氏族で、登録された者は、二万二千二百人であった。'),
('JPN', '民数记', 4, 26, 15, 'ガド族の諸氏族は、それぞれ、ツェフォンからはツェフォン族、ハギからはハギ族、シュニからはシュニ族、'),
('JPN', '民数记', 4, 26, 16, 'オズニからはオズニ族、エリからはエリ族、'),
('JPN', '民数记', 4, 26, 17, 'アロデからはアロデ族、アルエリからはアルエリ族。'),
('JPN', '民数记', 4, 26, 18, 'これらがガド人諸氏族で、登録された者は、四万五百人であった。'),
('JPN', '民数记', 4, 26, 19, 'ユダの子はエルとオナン。エルとオナンはカナンの地で死んだ。'),
('JPN', '民数记', 4, 26, 20, 'ユダ族の諸氏族は、それぞれ、シェラからはシェラ族、ペレツからはペレツ族、ゼラフからはゼラフ族。'),
('JPN', '民数记', 4, 26, 21, 'ペレツ族は、ヘツロンからはヘツロン族、ハムルからはハムル族であった。'),
('JPN', '民数记', 4, 26, 22, 'これらがユダ諸氏族で、登録された者は、七万六千五百人であった。'),
('JPN', '民数记', 4, 26, 23, 'イッサカル族の諸氏族は、それぞれ、トラからはトラ族、プワからはプワ族、'),
('JPN', '民数记', 4, 26, 24, 'ヤシュブからはヤシュブ族、シムロンからはシムロン族。'),
('JPN', '民数记', 4, 26, 25, 'これらがイッサカル諸氏族で、登録された者は、六万四千三百人であった。'),
('JPN', '民数记', 4, 26, 26, 'ゼブルン族の諸氏族は、それぞれ、セレデからはセレデ族、エロンからはエロン族、ヤフレエルからはヤフレエル族。'),
('JPN', '民数记', 4, 26, 27, 'これらがゼブルン人諸氏族で、登録された者は、六万五百人であった。'),
('JPN', '民数记', 4, 26, 28, 'ヨセフ族の諸氏族は、それぞれ、マナセとエフライム。'),
('JPN', '民数记', 4, 26, 29, 'マナセ族は、マキルからはマキル族。マキルはギルアデを生んだ。ギルアデからはギルアデ族。'),
('JPN', '民数记', 4, 26, 30, 'ギルアデ族は次のとおりである。イエゼルからはイエゼル族、ヘレクからはヘレク族、'),
('JPN', '民数记', 4, 26, 31, 'アスリエルからはアスリエル族、シェケムからはシェケム族、'),
('JPN', '民数记', 4, 26, 32, 'シェミダからはシェミダ族、ヘフェルからはヘフェル族。'),
('JPN', '民数记', 4, 26, 33, 'ヘフェルの子ツェロフハデには息子がなく、娘だけであった。ツェロフハデの娘の名は、マフラ、ノア、ホグラ、ミルカ、ティルツァであった。'),
('JPN', '民数记', 4, 26, 34, 'これらがマナセ諸氏族で、登録された者は、五万二千七百人であった。'),
('JPN', '民数记', 4, 26, 35, 'エフライム族の諸氏族は、それぞれ、次のとおりである。シュテラフからはシュテラフ族、ベケルからはベケル族、タハンからはタハン族。'),
('JPN', '民数记', 4, 26, 36, 'シュテラフ族は次のとおりである。エランからはエラン族。'),
('JPN', '民数记', 4, 26, 37, 'これらがエフライム人諸氏族で、登録された者は、三万二千五百人であった。これがヨセフ族の諸氏族である。'),
('JPN', '民数记', 4, 26, 38, 'ベニヤミン族の諸氏族は、それぞれ、ベラからはベラ族、アシュベルからはアシュベル族、アヒラムからはアヒラム族、'),
('JPN', '民数记', 4, 26, 39, 'シュファムからはシュファム族、フファムからはフファム族。'),
('JPN', '民数记', 4, 26, 40, 'ベラの子はアルデとナアマン。アルデからはアルデ族、ナアマンからはナアマン族。'),
('JPN', '民数记', 4, 26, 41, 'これらがベニヤミン族の諸氏族で、登録された者は、四万五千六百人であった。'),
('JPN', '民数记', 4, 26, 42, 'ダン族の諸氏族は次のとおりである。シュハムからはシュハム族。これらがダン族の諸氏族である。'),
('JPN', '民数记', 4, 26, 43, 'シュハム人の全諸氏族で、登録された者は、六万四千四百人であった。'),
('JPN', '民数记', 4, 26, 44, 'アシェル族の諸氏族は、それぞれ、イムナからはイムナ族、イシュウィからはイシュウィ族、ベリアからはベリア族。'),
('JPN', '民数记', 4, 26, 45, 'ベリア族のうち、ヘベルからはヘベル族、マルキエルからはマルキエル族。'),
('JPN', '民数记', 4, 26, 46, 'アシェルの娘の名はセラフであった。'),
('JPN', '民数记', 4, 26, 47, 'これらがアシェル人諸氏族で、登録された者は、五万三千四百人であった。'),
('JPN', '民数记', 4, 26, 48, 'ナフタリ族の諸氏族は、それぞれ、ヤフツェエルからはヤフツェエル族、グニからはグニ族、'),
('JPN', '民数记', 4, 26, 49, 'エツェルからはエツェル族、シレムからはシレム族。'),
('JPN', '民数记', 4, 26, 50, 'これらがナフタリ族の諸氏族で、登録された者は、四万五千四百人であった。'),
('JPN', '民数记', 4, 26, 51, '以上が、イスラエルの子らの登録された者で、六十万一千七百三十人であった。'),
('JPN', '民数记', 4, 26, 52, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 26, 53, '「これらの者たちに、その名の数にしたがって、地を相続地として割り当てなければならない。'),
('JPN', '民数记', 4, 26, 54, '大きい部族にはその相続地を大きくし、小さい部族にはその相続地を小さくしなければならない。それぞれ登録された者に応じて、その相続地は与えられる。'),
('JPN', '民数记', 4, 26, 55, 'ただし、その地はくじで割り当てられ、彼らの父祖の部族の名にしたがって受け継がれなければならない。'),
('JPN', '民数记', 4, 26, 56, 'その相続地は、大部族と小部族の間で、くじによって決められなければならない。」'),
('JPN', '民数记', 4, 26, 57, 'さて、レビ人で氏族ごとに登録された者は、次のとおりである。ゲルションからはゲルション族、ケハテからはケハテ族、メラリからはメラリ族。'),
('JPN', '民数记', 4, 26, 58, 'レビ諸氏族は次のとおりである。すなわち、リブニ族、ヘブロン族、マフリ族、ムシ族、およびコラ族。ケハテはアムラムを生んだ。'),
('JPN', '民数记', 4, 26, 59, 'アムラムの妻の名はヨケベデで、レビの娘であった。彼女はエジプトでレビに生まれた者で、アムラムにアロンとモーセと彼らの姉ミリアムを産んだ。'),
('JPN', '民数记', 4, 26, 60, 'アロンにはナダブとアビフとエルアザルとイタマルが生まれた。'),
('JPN', '民数记', 4, 26, 61, 'ナダブとアビフは主の前に異なる火を献げたときに死んだ。'),
('JPN', '民数记', 4, 26, 62, '登録された者は、生後一か月以上の男子すべてで、二万三千人であった。彼らは、イスラエルの子らとともには登録されなかった。イスラエルの子らの中に相続地が与えられていなかったからである。'),
('JPN', '民数记', 4, 26, 63, '以上が、エリコをのぞむヨルダン川のほとりのモアブの草原で、モーセと祭司エルアザルがイスラエルの子らを登録したときに登録された者たちである。'),
('JPN', '民数记', 4, 26, 64, 'しかし、この中には、シナイの荒野でモーセと祭司アロンがイスラエルの子らを登録したときに登録された者は、一人もいなかった。'),
('JPN', '民数记', 4, 26, 65, 'それは主がかつて彼らについて、「彼らは必ず荒野で死ぬ」と言われたからである。彼らのうち、ただエフンネの子カレブとヌンの子ヨシュアのほかには、だれも残っていなかった。'),
('JPN', '民数记', 4, 27, 1, 'さて、ヨセフの子マナセの一族のツェロフハデの娘たちが進み出た。ツェロフハデはヘフェルの子、ヘフェルはギルアデの子、ギルアデはマキルの子、マキルはマナセの子であり、その娘たちの名はマフラ、ノア、ホグラ、ミルカ、ティルツァであった。'),
('JPN', '民数记', 4, 27, 2, '彼女たちは、モーセの前、祭司エルアザルの前、また族長たちと全会衆の前、すなわち会見の天幕の入り口に立って言った。'),
('JPN', '民数记', 4, 27, 3, '「私たちの父は荒野で死にました。父は、コラの仲間と一緒になって、主に逆らったあの仲間たちには加わらず、自分の罪過によって死んだのです。しかし、父には息子がいませんでした。'),
('JPN', '民数记', 4, 27, 4, '息子がいなかったからといって、なぜ私たちの父の名がその氏族の間から削られるのでしょうか。私たちにも、父の兄弟たちの間で所有地を与えてください。」'),
('JPN', '民数记', 4, 27, 5, 'そこでモーセは、彼女たちの訴えを主の前に差し出した。'),
('JPN', '民数记', 4, 27, 6, 'すると主はモーセに告げられた。'),
('JPN', '民数记', 4, 27, 7, '「ツェロフハデの娘たちの言い分はもっともだ。あなたは必ず彼女たちに、その父の兄弟たちの間で、相続の所有地を与えよ。彼女たちに、その父の相続地を渡せ。'),
('JPN', '民数记', 4, 27, 8, 'あなたはイスラエルの子らに語れ。人が死に、その人に息子がいないときは、あなたがたはその相続地を娘に渡さなければならない。'),
('JPN', '民数记', 4, 27, 9, 'もし娘もいないときには、その相続地を彼の兄弟たちに与えよ。'),
('JPN', '民数记', 4, 27, 10, 'もし兄弟たちもいないときには、その相続地を彼の父の兄弟たちに与えよ。'),
('JPN', '民数记', 4, 27, 11, 'もしその父に兄弟がいないときには、その相続地を、彼の氏族の中で彼に一番近い血縁の者に与え、それを受け継がせよ。これは、主がモーセに命じられたとおり、イスラエルの子らにとってさばきの掟となる。」'),
('JPN', '民数记', 4, 27, 12, '主はモーセに言われた。「このアバリム山に登り、わたしがイスラエルの子らに与えた地を見よ。'),
('JPN', '民数记', 4, 27, 13, 'それを見て、あなたもまた、あなたの兄弟アロンが加えられたのと同じように、自分の民に加えられる。'),
('JPN', '民数记', 4, 27, 14, 'ツィンの荒野で会衆が争ったとき、あなたがたがわたしの命令に逆らい、彼らの見ている前で、あの水のところで、わたしが聖であることを現さなかったからである。」これはツィンの荒野のメリバテ・カデシュの水のことである。'),
('JPN', '民数记', 4, 27, 15, 'モーセは主に言った。'),
('JPN', '民数记', 4, 27, 16, '「すべての肉なるものの霊をつかさどる神、主よ。一人の人を会衆の上に定め、'),
('JPN', '民数记', 4, 27, 17, '彼が、彼らに先立って出て行き、先立って入り、また彼らを導き出し、導き入れるようにしてください。主の会衆を、羊飼いのいない羊の群れのようにしないでください。」'),
('JPN', '民数记', 4, 27, 18, '主はモーセに言われた。「あなたは、神の霊の宿っている人、ヌンの子ヨシュアを連れて来て、あなたの手を彼の上に置け。'),
('JPN', '民数记', 4, 27, 19, '彼を祭司エルアザルの前に、また全会衆の前に立たせ、彼らの目の前で彼を任命せよ。'),
('JPN', '民数记', 4, 27, 20, 'あなたは、自分の権威を彼に分け与え、イスラエルの全会衆を彼に聞き従わせよ。'),
('JPN', '民数记', 4, 27, 21, '彼は祭司エルアザルの前に立ち、エルアザルは主の前で、ウリムによるさばきを自分のために伺わなければならない。ヨシュアと彼とともにいるイスラエルの子らのすべての者、すなわち全会衆は、エルアザルの命令によって出、また、彼の命令によって入らなければならない。」'),
('JPN', '民数记', 4, 27, 22, 'モーセは主が命じられたとおりに行った。ヨシュアを連れて来て、彼を祭司エルアザルと全会衆の前に立たせ、'),
('JPN', '民数记', 4, 27, 23, '自分の手を彼の上に置いて、主がモーセを通して告げられたとおりに任命した。'),
('JPN', '民数记', 4, 28, 1, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 28, 2, '「イスラエルの子らに命じて彼らに言え。あなたがたは、わたしのための食物、わたしへのささげ物を、わたしへの食物のささげ物、芳ばしい香りとして、定められた時に確実にわたしに献げなければならない。'),
('JPN', '民数记', 4, 28, 3, '彼らに言え。これがあなたがたが主に献げる食物のささげ物である。傷のない一歳の雄の子羊を、毎日二匹、常供の全焼のささげ物として。'),
('JPN', '民数记', 4, 28, 4, '一方の子羊を朝献げ、もう一方の子羊を夕暮れに献げなければならない。'),
('JPN', '民数记', 4, 28, 5, '穀物のささげ物として、上質のオリーブ油四分の一ヒンを混ぜた小麦粉十分の一エパ。'),
('JPN', '民数记', 4, 28, 6, 'これはシナイ山で定められた、常供の全焼のささげ物であり、主への食物のささげ物、芳ばしい香りである。'),
('JPN', '民数记', 4, 28, 7, 'それに添える注ぎのささげ物は、子羊一匹につき四分の一ヒンとする。聖所で、主への注ぎのささげ物として強い酒を注ぎなさい。'),
('JPN', '民数记', 4, 28, 8, 'もう一方の子羊は夕暮れに献げなければならない。朝の穀物のささげ物、および、それに添える注ぎのささげ物と同じものを、これに添えて献げなければならない。これは主への食物のささげ物、芳ばしい香りである。'),
('JPN', '民数记', 4, 28, 9, '安息日には、傷のない一歳の雄の子羊二匹と、穀物のささげ物として油を混ぜた小麦粉十分の二エパと、それに添える注ぎのささげ物。'),
('JPN', '民数记', 4, 28, 10, 'これは、安息日ごとの全焼のささげ物で、常供の全焼のささげ物とそれに添える注ぎのささげ物に加えられる。'),
('JPN', '民数记', 4, 28, 11, 'あなたがたは月の最初の日に、次のものを献げなければならない。主への全焼のささげ物として、若い雄牛二頭、雄羊一匹、傷のない一歳の雄の子羊七匹。'),
('JPN', '民数记', 4, 28, 12, '雄牛一頭につき、穀物のささげ物として、油を混ぜた小麦粉十分の三エパ。雄羊一匹につき、穀物のささげ物として、油を混ぜた小麦粉十分の二エパ。'),
('JPN', '民数记', 4, 28, 13, '子羊一匹につき、穀物のささげ物として、油を混ぜた小麦粉十分の一エパ。これらが主への全焼のささげ物、芳ばしい香り、食物のささげ物である。'),
('JPN', '民数记', 4, 28, 14, 'それに添える注ぎのささげ物は、雄牛一頭につき二分の一ヒン、雄羊一匹につき三分の一ヒン、子羊一匹につき四分の一ヒンのぶどう酒でなければならない。これは一年を通して毎月の、新月祭の全焼のささげ物である。'),
('JPN', '民数记', 4, 28, 15, '主への罪のきよめのささげ物として、雄やぎ一匹。これは、常供の全焼のささげ物とそれに添える注ぎのささげ物に加えられる。'),
('JPN', '民数记', 4, 28, 16, '第一の月の十四日は、過越のいけにえを主に献げなければならない。'),
('JPN', '民数记', 4, 28, 17, 'この月の十五日は祭りである。七日間、種なしパンを食べなければならない。'),
('JPN', '民数记', 4, 28, 18, 'その最初の日には、聖なる会合を開く。いかなる労働もしてはならない。'),
('JPN', '民数记', 4, 28, 19, 'あなたがたは、主への食物のささげ物、全焼のささげ物として、若い雄牛二頭、雄羊一匹、一歳の雄の子羊七匹を献げなければならない。それはあなたがたにとって傷のないものでなければならない。'),
('JPN', '民数记', 4, 28, 20, 'それに添える穀物のささげ物として、油を混ぜた小麦粉を、雄牛一頭につき十分の三エパ、雄羊一匹につき十分の二エパとする。'),
('JPN', '民数记', 4, 28, 21, '子羊七匹については、一匹につき十分の一エパとする。'),
('JPN', '民数记', 4, 28, 22, 'あなたがたのために宥めを行うには、罪のきよめのささげ物として、雄やぎ一匹とする。'),
('JPN', '民数记', 4, 28, 23, '常供の全焼のささげ物である朝の全焼のささげ物のほかに、これらのものを献げなければならない。'),
('JPN', '民数记', 4, 28, 24, 'このように七日間、主への芳ばしい香り、食物のささげ物のパンを、毎日、献げなければならない。これは常供の全焼のささげ物とその注ぎのささげ物に加えて献げられなければならない。'),
('JPN', '民数记', 4, 28, 25, '七日目にあなたがたは聖なる会合を開かなければならない。いかなる労働もしてはならない。'),
('JPN', '民数记', 4, 28, 26, '初穂の日、すなわち七週の祭りに、新しい穀物のささげ物を主に献げるときには、聖なる会合を開かなければならない。いかなる労働もしてはならない。'),
('JPN', '民数记', 4, 28, 27, 'あなたがたは、主への芳ばしい香りとして、全焼のささげ物、すなわち、若い雄牛二頭、雄羊一匹、一歳の雄の子羊七匹を献げよ。'),
('JPN', '民数记', 4, 28, 28, 'さらに、それに添える穀物のささげ物として、油を混ぜた小麦粉を、雄牛一頭につき十分の三エパ、雄羊一匹につき十分の二エパ。'),
('JPN', '民数记', 4, 28, 29, '七匹の子羊については、一匹につき十分の一エパ。'),
('JPN', '民数记', 4, 28, 30, 'あなたがたのために宥めを行うには、雄やぎ一匹とする。'),
('JPN', '民数记', 4, 28, 31, '常供の全焼のささげ物とそれに添える穀物のささげ物とは別に、これらのものを、それらに添える注ぎのささげ物とともに献げなければならない。それらは傷のないものでなければならない。'),
('JPN', '民数记', 4, 29, 1, '第七の月には、その月の一日に聖なる会合を開かなければならない。あなたがたは、いかなる労働もしてはならない。これを、あなたがたにとって角笛が吹き鳴らされる日としなければならない。'),
('JPN', '民数记', 4, 29, 2, 'あなたがたは、次のものを献げよ。主への芳ばしい香りとして、全焼のささげ物、すなわち、若い雄牛一頭、雄羊一匹、傷のない一歳の雄の子羊七匹。'),
('JPN', '民数记', 4, 29, 3, 'それに添える穀物のささげ物として、油を混ぜた小麦粉を、雄牛一頭につき十分の三エパ、雄羊一匹につき十分の二エパ、'),
('JPN', '民数记', 4, 29, 4, '七匹の子羊については、一匹につき十分の一エパ。'),
('JPN', '民数记', 4, 29, 5, 'また、あなたがたのために宥めを行うには、罪のきよめのささげ物として、雄やぎ一匹。'),
('JPN', '民数记', 4, 29, 6, 'これとは別に、新月祭の全焼のささげ物とその穀物のささげ物、常供の全焼のささげ物とその穀物のささげ物、および、それらに添える注ぎのささげ物、すなわち、規定による、主への食物のささげ物、芳ばしい香り。'),
('JPN', '民数记', 4, 29, 7, 'この第七の月の十日には、あなたがたは聖なる会合を開き、自らを戒めなければならない。いかなる仕事もしてはならない。'),
('JPN', '民数记', 4, 29, 8, 'あなたがたは、主への芳ばしい香りとして、全焼のささげ物、すなわち、若い雄牛一頭、雄羊一匹、一歳の雄の子羊七匹を献げよ。それらはあなたがたにとって傷のないものでなければならない。'),
('JPN', '民数记', 4, 29, 9, 'それに添える穀物のささげ物については、油を混ぜた小麦粉を、雄牛一頭につき十分の三エパ、雄羊一匹につき十分の二エパとする。'),
('JPN', '民数记', 4, 29, 10, '七匹の子羊については、一匹につき十分の一エパ。'),
('JPN', '民数记', 4, 29, 11, 'さらに罪のきよめのささげ物として、雄やぎ一匹。これらは、宥めのための罪のきよめのささげ物、常供の全焼のささげ物とそれに添える穀物のささげ物、および、それらに添える注ぎのささげ物とは別である。'),
('JPN', '民数记', 4, 29, 12, '第七の月の十五日には、あなたがたは聖なる会合を開かなければならない。いかなる労働もしてはならない。あなたがたは七日間、主の祭りを祝え。'),
('JPN', '民数记', 4, 29, 13, 'あなたがたは、主への芳ばしい香り、食物のささげ物として、全焼のささげ物、すなわち、若い雄牛十三頭、雄羊二匹、一歳の雄の子羊十四匹を献げよ。これらは傷のないものでなければならない。'),
('JPN', '民数记', 4, 29, 14, 'それに添える穀物のささげ物としては、油を混ぜた小麦粉を、雄牛十三頭については雄牛一頭につき十分の三エパ、雄羊二匹については雄羊一匹につき十分の二エパ、'),
('JPN', '民数记', 4, 29, 15, '子羊十四匹については子羊一匹につき十分の一エパとする。'),
('JPN', '民数记', 4, 29, 16, 'さらに罪のきよめのささげ物として、雄やぎ一匹。これらは、常供の全焼のささげ物と、それに添える穀物のささげ物、および注ぎのささげ物とは別である。'),
('JPN', '民数记', 4, 29, 17, '二日目には、若い雄牛十二頭、雄羊二匹、傷のない一歳の雄の子羊十四匹、'),
('JPN', '民数记', 4, 29, 18, 'および、それらの雄牛、雄羊、子羊のための、それぞれの数に応じて定められた穀物のささげ物と注ぎのささげ物。'),
('JPN', '民数记', 4, 29, 19, 'さらに罪のきよめのささげ物として、雄やぎ一匹。これらは、常供の全焼のささげ物と、それに添える穀物のささげ物、および注ぎのささげ物とは別である。'),
('JPN', '民数记', 4, 29, 20, '三日目には、雄牛十一頭、雄羊二匹、傷のない一歳の雄の子羊十四匹、'),
('JPN', '民数记', 4, 29, 21, 'および、それらの雄牛、雄羊、子羊のための、それぞれの数に応じて定められた穀物のささげ物と注ぎのささげ物。'),
('JPN', '民数记', 4, 29, 22, 'さらに罪のきよめのささげ物として、雄やぎ一匹。これらは、常供の全焼のささげ物と、それに添える穀物のささげ物、および注ぎのささげ物とは別である。'),
('JPN', '民数记', 4, 29, 23, '四日目には、雄牛十頭、雄羊二匹、傷のない一歳の雄の子羊十四匹、'),
('JPN', '民数记', 4, 29, 24, 'および、それらの雄牛、雄羊、子羊のための、それぞれの数に応じて定められた穀物のささげ物と注ぎのささげ物。'),
('JPN', '民数记', 4, 29, 25, 'さらに罪のきよめのささげ物として、雄やぎ一匹。これらは、常供の全焼のささげ物と、それに添える穀物のささげ物、および注ぎのささげ物とは別である。'),
('JPN', '民数记', 4, 29, 26, '五日目には、雄牛九頭、雄羊二匹、傷のない一歳の雄の子羊十四匹、'),
('JPN', '民数记', 4, 29, 27, 'および、それらの雄牛、雄羊、子羊のための、それぞれの数に応じて定められた穀物のささげ物と注ぎのささげ物。'),
('JPN', '民数记', 4, 29, 28, 'さらに罪のきよめのささげ物として、雄やぎ一匹。これらは、常供の全焼のささげ物と、それに添える穀物のささげ物、および注ぎのささげ物とは別である。'),
('JPN', '民数记', 4, 29, 29, '六日目には、雄牛八頭、雄羊二匹、傷のない一歳の雄の子羊十四匹、'),
('JPN', '民数记', 4, 29, 30, 'および、それらの雄牛、雄羊、子羊のための、それぞれの数に応じて定められた穀物のささげ物と注ぎのささげ物。'),
('JPN', '民数记', 4, 29, 31, 'さらに罪のきよめのささげ物として、雄やぎ一匹。これらは、常供の全焼のささげ物と、それに添える穀物のささげ物、および注ぎのささげ物とは別である。'),
('JPN', '民数记', 4, 29, 32, '七日目には、雄牛七頭、雄羊二匹、傷のない一歳の雄の子羊十四匹、'),
('JPN', '民数记', 4, 29, 33, 'および、それらの雄牛、雄羊、子羊のための、それぞれの数に応じて定められた穀物のささげ物と注ぎのささげ物。'),
('JPN', '民数记', 4, 29, 34, 'さらに罪のきよめのささげ物として、雄やぎ一匹。これらは、常供の全焼のささげ物と、それに添える穀物のささげ物、および注ぎのささげ物とは別である。'),
('JPN', '民数记', 4, 29, 35, '八日目に、あなたがたはきよめの集会を開かなければならない。いかなる労働もしてはならない。'),
('JPN', '民数记', 4, 29, 36, 'あなたがたは、主への芳ばしい香り、食物のささげ物として、全焼のささげ物、すなわち、雄牛一頭、雄羊一匹、傷のない一歳の雄の子羊七匹を献げよ。'),
('JPN', '民数记', 4, 29, 37, 'それらの雄牛、雄羊、子羊のための、穀物のささげ物と注ぎのささげ物の数量は規定どおりである。'),
('JPN', '民数记', 4, 29, 38, 'さらに罪のきよめのささげ物として、雄やぎ一匹。これらは、常供の全焼のささげ物と、それに添える穀物のささげ物、および注ぎのささげ物とは別である。'),
('JPN', '民数记', 4, 29, 39, 'あなたがたは、あなたがたの例祭に、それらのものを主に献げなければならない。それらは、あなたがたの誓願のささげ物、または進んで献げるものとしての全焼のささげ物、穀物のささげ物、注ぎのささげ物および交わりのいけにえとは別である。」'),
('JPN', '民数记', 4, 29, 40, 'モーセは、主がモーセに命じられたとおりを、イスラエルの子らに告げた。'),
('JPN', '民数记', 4, 30, 1, 'モーセはイスラエルの諸部族のかしらたちに告げた。「これは主が命じられたことである。'),
('JPN', '民数记', 4, 30, 2, '男が主に誓願をするか、あるいは、物断ちをしようと誓う場合には、自分のことばを破ってはならない。すべて自分の口から出たとおりのことを実行しなければならない。'),
('JPN', '民数记', 4, 30, 3, '女が若くてまだ父の家にいるときに、主に誓願をするか、あるいは物断ちをする場合には、'),
('JPN', '民数记', 4, 30, 4, 'その父が彼女の誓願、あるいは物断ちを聞いて、彼女に何も言わなければ、彼女のすべての誓願は有効となる。彼女の物断ちもすべて有効となる。'),
('JPN', '民数记', 4, 30, 5, 'しかし、もし父がそれを聞いた日に彼女に反対するなら、彼女の誓願、あるいは物断ちはすべて無効としなければならない。彼女の父が彼女に反対するのであるから、主は彼女を赦される。'),
('JPN', '民数记', 4, 30, 6, 'もし彼女が、自分の誓願、あるいは物断ちをしようと軽率に言ったことが、まだその身にかかっているうちに嫁ぐ場合には、'),
('JPN', '民数记', 4, 30, 7, '夫がそれを聞き、聞いた日に彼女に何も言わなければ、彼女の誓願は有効である。彼女の物断ちも有効となる。'),
('JPN', '民数记', 4, 30, 8, 'もし夫がそれを聞いた日に彼女に反対すれば、夫は、彼女がかけている誓願や、物断ちをしようと軽率に言ったことを破棄することになる。そして主は彼女を赦される。'),
('JPN', '民数记', 4, 30, 9, 'しかし、やもめや離縁された女の誓願については、すべての物断ちが当人に対して有効となる。'),
('JPN', '民数记', 4, 30, 10, 'もし女が夫の家で誓願をするか、あるいは、誓って物断ちをする場合には、'),
('JPN', '民数记', 4, 30, 11, '夫がそれを聞いて、彼女に何も言わず、反対しないなら、彼女の誓願はすべて有効となる。彼女の物断ちもすべて有効となる。'),
('JPN', '民数记', 4, 30, 12, 'もし夫が、そのことを聞いた日にそれらを破棄してしまうなら、その誓願も物断ちも、彼女の口から出たすべてのことは無効となる。彼女の夫がそれを破棄したのだから、主は彼女を赦される。'),
('JPN', '民数记', 4, 30, 13, 'すべての誓願も、自らを戒めるための物断ちの誓いもみな、夫がそれを有効にすることができるし、それを破棄することもできる。'),
('JPN', '民数记', 4, 30, 14, 'もし夫が日々、その妻に全く何も言わなければ、夫は彼女のすべての誓願、あるいは、すべての物断ちを有効にする。夫がそれを聞いた日に彼女に何も言わなかったのだから、彼はそれを有効にしたのである。'),
('JPN', '民数记', 4, 30, 15, 'もし夫がそれを聞いた後、それを破棄するなら、夫が彼女の咎を負う。」'),
('JPN', '民数记', 4, 30, 16, 'これらは、夫とその妻との間、父とまだ父の家にいる若い娘の間とに関して、主がモーセに命じられた掟である。'),
('JPN', '民数记', 4, 31, 1, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 31, 2, '「あなたは、イスラエルの子らのために、ミディアン人に復讐を果たせ。その後で、あなたは自分の民に加えられる。」'),
('JPN', '民数记', 4, 31, 3, 'そこでモーセは民に告げた。「あなたがたのうち、男たちは戦のために武装せよ。ミディアン人を襲って、ミディアン人に主の復讐をするためである。'),
('JPN', '民数记', 4, 31, 4, 'イスラエルのすべての部族から、部族ごとに千人を戦に送らなければならない。」'),
('JPN', '民数记', 4, 31, 5, 'それで、イスラエルの分団から、部族ごとに千人、すなわち、合計一万二千人の、戦のために武装した者たちが選ばれた。'),
('JPN', '民数记', 4, 31, 6, 'モーセは部族ごとに千人を戦に送った。また彼らとともに、祭司エルアザルの子ピネハスを、聖なる用具と吹き鳴らすラッパをその手に持たせて、戦に送り出した。'),
('JPN', '民数记', 4, 31, 7, '彼らは主がモーセに命じられたとおりに、ミディアン人に戦いを挑み、その男子をすべて殺した。'),
('JPN', '民数记', 4, 31, 8, 'その殺された者のほかに、彼らはミディアンの王たち、すなわち、エウィ、レケム、ツル、フル、レバの五人のミディアンの王たちを殺した。また、ベオルの子バラムを剣で殺した。'),
('JPN', '民数记', 4, 31, 9, 'イスラエル人は、ミディアン人の女たちと子どもたちを捕らえ、またその動物、家畜、財産をことごとく奪い取り、'),
('JPN', '民数记', 4, 31, 10, '彼らの居住していた町々や陣営をすべて火で焼いた。'),
('JPN', '民数记', 4, 31, 11, 'そして人でも動物でも、略奪したものや分捕ったものすべてを取り、'),
('JPN', '民数记', 4, 31, 12, 'エリコをのぞむヨルダン川のほとりのモアブの草原の宿営にいる、モーセと祭司エルアザルとイスラエルの会衆のところに、その捕虜や分捕り物、略奪品を携えてやって来た。'),
('JPN', '民数记', 4, 31, 13, 'モーセと祭司エルアザル、およびすべての会衆の上に立つ族長たちは出て行って、宿営の外で彼らを迎えた。'),
('JPN', '民数记', 4, 31, 14, 'モーセは、軍勢の指揮官たち、すなわち戦いの任務から戻って来た千人の長や百人の長たちに対して激怒した。'),
('JPN', '民数记', 4, 31, 15, 'モーセは彼らに言った。「女たちをみな生かしておいたのか。'),
('JPN', '民数记', 4, 31, 16, 'よく聞け。この女たちが、バラムの事件の折に、ペオルの事件に関連してイスラエルの子らをそそのかし、主を冒瀆させたのだ。それで主の罰が主の会衆の上に下ったのだ。'),
('JPN', '民数记', 4, 31, 17, '今、子どもたちのうちの男子をみな殺せ。男と寝て男を知っている女もみな殺せ。'),
('JPN', '民数记', 4, 31, 18, '男と寝ることを知らない若い娘たちはみな、あなたがたのために生かしておけ。'),
('JPN', '民数记', 4, 31, 19, 'あなたがたは七日間、宿営の外にとどまれ。あなたがたでも、あなたがたの捕虜でも、人を殺した者、あるいは刺し殺された者に触れた者はだれでも、三日目と七日目に身の汚れを除かなければならない。'),
('JPN', '民数记', 4, 31, 20, '衣服、皮製品、やぎの毛で作ったもの、木製品はすべて汚れを除かなければならない。」'),
('JPN', '民数记', 4, 31, 21, '祭司エルアザルは、戦いに行った兵士たちに言った。「主がモーセに命じられたおしえの掟は次のとおりである。'),
('JPN', '民数记', 4, 31, 22, 'ただ、金、銀、青銅、鉄、すず、鉛など、'),
('JPN', '民数记', 4, 31, 23, 'すべて火に耐えるものは、火の中を通せば、きよくなる。ただし、それは汚れを除く水で汚れを除かなければならない。火に耐えないものはみな、水の中を通さなければならない。'),
('JPN', '民数记', 4, 31, 24, 'また、あなたがたは七日目に自分の衣服を洗うなら、きよくなる。その後で、宿営に入ることができる。」'),
('JPN', '民数记', 4, 31, 25, '主はモーセに言われた。'),
('JPN', '民数记', 4, 31, 26, '「あなたと祭司エルアザル、および会衆の氏族のかしらたちは、人でも家畜でも捕らえて分捕ったものの総数を調べ、'),
('JPN', '民数记', 4, 31, 27, 'その分捕ったものを、戦に出た者たちと全会衆の間で二分せよ。'),
('JPN', '民数记', 4, 31, 28, '戦に出た戦士たちからは、人、牛、ろば、羊の中からそれぞれ五百のうち一を、主への貢ぎとして徴収せよ。'),
('JPN', '民数记', 4, 31, 29, '彼らが受けるその半分の中から取って、主への奉納物として祭司エルアザルに渡さなければならない。'),
('JPN', '民数记', 4, 31, 30, 'イスラエルの子らが受けるもう半分の中から、人、また牛、ろば、羊、それぞれの家畜から、それぞれ五十のうち一を取り出して、主の幕屋の任務に当たるレビ人に与えなければならない。」'),
('JPN', '民数记', 4, 31, 31, 'そこでモーセと祭司エルアザルは、主がモーセに命じられたとおりに行った。'),
('JPN', '民数记', 4, 31, 32, '従軍した人たちが奪った戦利品を除く分捕り物は、羊六十七万五千匹、'),
('JPN', '民数记', 4, 31, 33, '牛七万二千頭、'),
('JPN', '民数记', 4, 31, 34, 'ろば六万一千頭、'),
('JPN', '民数记', 4, 31, 35, '人は、男と寝ることを知らない女が全部で三万二千人であった。'),
('JPN', '民数记', 4, 31, 36, 'この半分が戦に出た者たちの分け前で、羊の数は三十三万七千五百匹。'),
('JPN', '民数记', 4, 31, 37, 'その羊のうちから主への貢ぎは六百七十五匹。'),
('JPN', '民数记', 4, 31, 38, '牛は三万六千頭で、そのうちから主への貢ぎは七十二頭。'),
('JPN', '民数记', 4, 31, 39, 'ろばは三万五百頭で、そのうちから主への貢ぎは六十一頭。'),
('JPN', '民数记', 4, 31, 40, '人は一万六千人で、そのうちから主への貢ぎは三十二人であった。'),
('JPN', '民数记', 4, 31, 41, 'モーセは、主がモーセに命じられたとおりに、その貢ぎ、すなわち、主への奉納物を祭司エルアザルに渡した。'),
('JPN', '民数记', 4, 31, 42, 'モーセが戦に出た者たちに折半して与えた残り、すなわち、イスラエルの子らのものであるもう半分、'),
('JPN', '民数记', 4, 31, 43, 'すなわち会衆のものであるもう半分は、羊三十三万七千五百匹、'),
('JPN', '民数记', 4, 31, 44, '牛三万六千頭、'),
('JPN', '民数记', 4, 31, 45, 'ろば三万五百頭、'),
('JPN', '民数记', 4, 31, 46, '人は一万六千人であった。'),
('JPN', '民数记', 4, 31, 47, 'モーセは、イスラエルの子らのものであるもう半分から、人も家畜も、それぞれ五十のうち一を取り出して、主がモーセに命じられたとおりに、主の幕屋の任務に当たるレビ人に与えた。'),
('JPN', '民数记', 4, 31, 48, 'すると、軍団の指揮官たち、すなわち千人の長、百人の長たちがモーセのもとに進み出て、'),
('JPN', '民数记', 4, 31, 49, 'モーセに言った。「しもべどもは、部下の戦士たちの総数を数えました。私たちのうち一人も欠けていません。'),
('JPN', '民数记', 4, 31, 50, 'それで、私たちは、各自が手に入れた金の飾り物、すなわち腕飾り、腕輪、指輪、耳輪、首飾りなどを主へのささげ物として持って来ました。主の前で私たち自身のための宥めとしたいのです。」'),
('JPN', '民数记', 4, 31, 51, 'モーセと祭司エルアザルは、彼らから金を受け取った。それはあらゆる種類の細工を施した物であった。'),
('JPN', '民数记', 4, 31, 52, '千人の長や百人の長たちが主に献げた奉納物の金は、全部で一万六千七百五十シェケルであった。'),
('JPN', '民数记', 4, 31, 53, '従軍した人たちは、それぞれ、戦利品を自分のものとした。'),
('JPN', '民数记', 4, 31, 54, 'モーセと祭司エルアザルは、千人の長や百人の長たちから金を受け取り、それを会見の天幕に持って行き、主の前における、イスラエルの子らのための記念とした。'),
('JPN', '民数记', 4, 32, 1, 'ルベン族とガド族は、多くの家畜を持っていた。それは、おびただしい数であった。彼らがヤゼルの地とギルアデの地を見ると、その場所は家畜に適した場所であった。'),
('JPN', '民数记', 4, 32, 2, 'そこでガド族とルベン族は、モーセと祭司エルアザル、および会衆の上に立つ族長たちのところに来て、次のように言った。'),
('JPN', '民数记', 4, 32, 3, '「アタロテ、ディボン、ヤゼル、ニムラ、ヘシュボン、エルアレ、セバム、ネボ、ベオン、'),
('JPN', '民数记', 4, 32, 4, '主がイスラエルの会衆の前で打ち滅ぼされたこれらの地は、家畜に適した地です。そして、しもべどもには家畜がいます。」'),
('JPN', '民数记', 4, 32, 5, 'また言った。「もし、私たちの願いがかないますなら、どうか、しもべどもがこの地を所有地として賜りますように。私たちにヨルダン川を渡らせないでください。」'),
('JPN', '民数记', 4, 32, 6, 'モーセはガド族とルベン族に答えた。「あなたがたの兄弟たちは戦いに行くのに、あなたがたはここにとどまるというのか。'),
('JPN', '民数记', 4, 32, 7, 'どうして、イスラエルの子らの意気をくじいて、主が与えてくださった地へ渡らせないようにするのか。'),
('JPN', '民数记', 4, 32, 8, 'あなたがたの父たちも、私がカデシュ・バルネアからその地を調べるために遣わしたとき、そのようにふるまった。'),
('JPN', '民数记', 4, 32, 9, '彼らはエシュコルの谷まで上って行って、その地を見たとき、イスラエルの子らの意気をくじいて、主が与えてくださった地に入って行かないようにした。'),
('JPN', '民数记', 4, 32, 10, 'あの日、主は怒りに燃え、誓って言われた。'),
('JPN', '民数记', 4, 32, 11, '『エジプトから上って来た者たちで二十歳以上の者はだれも、わたしがアブラハム、イサク、ヤコブに誓った地を見ることはない。わたしに従い通さなかったからである。'),
('JPN', '民数记', 4, 32, 12, 'ただ、ケナズ人エフンネの子カレブと、ヌンの子ヨシュアは別である。彼らが主に従い通したからである。』'),
('JPN', '民数记', 4, 32, 13, '事実、主の怒りはイスラエルに向かって燃え上がり、主は彼らを四十年の間、荒野をさまよわせ、主の目に悪であることを行ったその世代の者たちは、ついに、みな死に絶えた。'),
('JPN', '民数记', 4, 32, 14, 'そして今、あなたがたが、罪人の子らとしてあなたがたの父たちに代わって立ち上がり、イスラエルに対する主の燃える怒りを増し加えようとしている。'),
('JPN', '民数记', 4, 32, 15, 'あなたがたが背いて主に従わないなら、主は再びこの民をこの荒野に見捨てられる。そしてあなたがたは、この民全体に滅びをもたらすことになるのだ。」'),
('JPN', '民数记', 4, 32, 16, '彼らはモーセに近寄って言った。「私たちはここに、家畜のために羊の囲い場を作り、子どもたちのために町々を建てます。'),
('JPN', '民数记', 4, 32, 17, 'しかし私たちは、イスラエルの子らを彼らの場所に導き入れるまで、武装して先頭に立って急ぎ進みます。子どもたちは、この地の住民の前で城壁のある町々に住みます。'),
('JPN', '民数记', 4, 32, 18, '私たちは、イスラエルの子らがそれぞれその相続地を受け継ぐまで、自分の家に帰りません。'),
('JPN', '民数记', 4, 32, 19, 'ヨルダン川の向こう側では、彼らとともに相続地を持ちません。私たちの相続地は、このヨルダンの川向こう、東の方になります。」'),
('JPN', '民数记', 4, 32, 20, 'モーセは彼らに言った。「もしあなたがたがそのことを実行するなら、すなわち、もし主の前で戦いのために武装し、'),
('JPN', '民数记', 4, 32, 21, 'あなたがたのうちの武装した者がみな主の前でヨルダン川を渡り、ついに主がその敵を御前から追い払い、'),
('JPN', '民数记', 4, 32, 22, 'その地が主の前に征服され、その後であなたがたが帰って来るなら、あなたがたは主に対してもイスラエルに対しても責任を解かれる。そして、この地は主の前であなたがたの所有地となる。'),
('JPN', '民数记', 4, 32, 23, 'しかし、もしそのように行わないなら、そのとき、あなたがたは主の前に罪ある者となり、自分たちの身に降りかかる罪の罰を思い知ることになる。'),
('JPN', '民数记', 4, 32, 24, 'あなたがたは、自分の子どもたちのために町々を建て、自分の羊のために囲い場を作るがよい。自分の口から出たことを実行しなさい。」'),
('JPN', '民数记', 4, 32, 25, 'ガド族とルベン族はモーセに答えた。「しもべどもは、あなたが命じられるとおりにします。'),
('JPN', '民数记', 4, 32, 26, '私たちの子どもたちや妻たち、家畜とすべての動物は、あそこ、ギルアデの町々にとどまります。'),
('JPN', '民数记', 4, 32, 27, 'しかし、しもべども、戦のために武装した者はみな、あなたがおっしゃるとおり、渡って行って、主の前で戦います。」'),
('JPN', '民数记', 4, 32, 28, 'そこで、モーセは彼らについて、祭司エルアザル、ヌンの子ヨシュア、イスラエルの諸部族の一族のかしらたちに命令を下した。'),
('JPN', '民数记', 4, 32, 29, 'モーセは彼らに言った。「もし、ガド族とルベン族の、戦いのために武装した者がみな、あなたがたとともにヨルダン川を渡り、主の前で戦い、その地があなたがたの前に征服されたなら、あなたがたはギルアデの地を所有地として彼らに与えなさい。'),
('JPN', '民数记', 4, 32, 30, 'しかし、もし彼らが武装してあなたがたとともに渡って行かなければ、彼らはカナンの地であなたがたの間に所有地を得なければならない。」'),
('JPN', '民数记', 4, 32, 31, 'ガド族とルベン族は答えた。「主があなたのしもべたちに語られたことを、私たちは実行いたします。'),
('JPN', '民数记', 4, 32, 32, '私たちは武装して主の前にカナンの地に渡って行き、私たちの相続の所有地を、このヨルダンの川向こうとします。」'),
('JPN', '民数记', 4, 32, 33, 'そこでモーセは、ガド族と、ルベン族と、ヨセフの子マナセの半部族に、アモリ人の王シホンの王国とバシャンの王オグの王国、すなわち町々がある地と、周辺の地の町々がある領土を与えた。'),
('JPN', '民数记', 4, 32, 34, 'そこでガド族は、ディボン、アタロテ、アロエル、'),
('JPN', '民数记', 4, 32, 35, 'アテロテ・ショファン、ヤゼル、ヨグボハ、'),
('JPN', '民数记', 4, 32, 36, 'ベテ・ニムラ、ベテ・ハランを城壁のある町々として、または羊の囲い場として建て直した。'),
('JPN', '民数记', 4, 32, 37, 'また、ルベン族は、ヘシュボン、エルアレ、キルヤタイム、'),
('JPN', '民数记', 4, 32, 38, 'および、後に名を改められたネボとバアル・メオン、またシブマを建て直した。彼らは、建て直した町々に新しい名をつけた。'),
('JPN', '民数记', 4, 32, 39, 'マナセの子マキルの子らはギルアデに行って、そこを攻め取り、そこにいたアモリ人を追い出した。'),
('JPN', '民数记', 4, 32, 40, 'モーセがギルアデをマナセの子マキルに与えたので、彼はそこに住んだ。'),
('JPN', '民数记', 4, 32, 41, 'マナセの子ヤイルは行って、彼らの町々を攻め取り、それらをハボテ・ヤイルと名づけた。'),
('JPN', '民数记', 4, 32, 42, 'ノバフは行って、ケナテとそれに属する村々を攻め取り、自分の名にちなんで、それをノバフと名づけた。'),
('JPN', '民数记', 4, 33, 1, 'モーセとアロンの指導のもとに、その軍団ごとにエジプトの地から出て来たイスラエルの子らの旅程は次のとおりである。'),
('JPN', '民数记', 4, 33, 2, 'モーセは主の命により、彼らの旅程の出発地点を書き記した。その旅程は、出発地点によると次のとおりである。'),
('JPN', '民数记', 4, 33, 3, '彼らは第一の月、その月の十五日に、ラメセスを旅立った。すなわち過越のいけにえの翌日、イスラエルの子らは、全エジプトが見ている前を臆することなく出て行った。'),
('JPN', '民数记', 4, 33, 4, 'エジプトは、彼らの間で主が打たれたすべての長子を埋葬していた。主は彼らの神々にもさばきを下された。'),
('JPN', '民数记', 4, 33, 5, 'イスラエルの子らはラメセスを旅立ってスコテに宿営し、'),
('JPN', '民数记', 4, 33, 6, 'スコテを旅立って荒野の端にあるエタムに宿営した。'),
('JPN', '民数记', 4, 33, 7, 'エタムを旅立ってバアル・ツェフォンの手前にあるピ・ハヒロテの方に向きを変え、ミグドルの前で宿営した。'),
('JPN', '民数记', 4, 33, 8, 'ピ・ハヒロテを旅立って海の真ん中を通って荒野に向かい、エタムの荒野を三日路ほど行ってマラに宿営した。'),
('JPN', '民数记', 4, 33, 9, 'マラを旅立ってエリムに行き、そこに宿営した。エリムには十二の泉と、七十本のなつめ椰子の木があった。'),
('JPN', '民数记', 4, 33, 10, 'それから、彼らはエリムを旅立って葦の海のほとりに宿営し、'),
('JPN', '民数记', 4, 33, 11, '葦の海を旅立ってシンの荒野に宿営した。'),
('JPN', '民数记', 4, 33, 12, 'シンの荒野を旅立ってドフカに宿営し、'),
('JPN', '民数记', 4, 33, 13, 'ドフカを旅立ってアルシュに宿営し、'),
('JPN', '民数记', 4, 33, 14, 'アルシュを旅立ってレフィディムに宿営した。そこには民の飲む水がなかった。'),
('JPN', '民数记', 4, 33, 15, 'それから、彼らはレフィディムを旅立ってシナイの荒野に宿営し、'),
('JPN', '民数记', 4, 33, 16, 'シナイの荒野を旅立ってキブロテ・ハ・タアワに宿営した。'),
('JPN', '民数记', 4, 33, 17, 'キブロテ・ハ・タアワを旅立ってハツェロテに宿営し、'),
('JPN', '民数记', 4, 33, 18, 'ハツェロテを旅立ってリテマに宿営した。'),
('JPN', '民数记', 4, 33, 19, 'リテマを旅立ってリンモン・ペレツに宿営し、'),
('JPN', '民数记', 4, 33, 20, 'リンモン・ペレツを旅立ってリブナに宿営した。'),
('JPN', '民数记', 4, 33, 21, 'リブナを旅立ってリサに宿営し、'),
('JPN', '民数记', 4, 33, 22, 'リサを旅立ってケヘラタに宿営し、'),
('JPN', '民数记', 4, 33, 23, 'ケヘラタを旅立ってシェフェル山に宿営した。'),
('JPN', '民数记', 4, 33, 24, 'シェフェル山を旅立ってハラダに宿営し、'),
('JPN', '民数记', 4, 33, 25, 'ハラダを旅立ってマクヘロテに宿営した。'),
('JPN', '民数记', 4, 33, 26, 'マクヘロテを旅立ってタハテに宿営し、'),
('JPN', '民数记', 4, 33, 27, 'タハテを旅立ってテラフに宿営し、'),
('JPN', '民数记', 4, 33, 28, 'テラフを旅立ってミテカに宿営した。'),
('JPN', '民数记', 4, 33, 29, 'ミテカを旅立ってハシュモナに宿営し、'),
('JPN', '民数记', 4, 33, 30, 'ハシュモナを旅立ってモセロテに宿営した。'),
('JPN', '民数记', 4, 33, 31, 'モセロテを旅立ってベネ・ヤアカンに宿営し、'),
('JPN', '民数记', 4, 33, 32, 'ベネ・ヤアカンを旅立ってホル・ハ・ギデガデに宿営し、'),
('JPN', '民数记', 4, 33, 33, 'ホル・ハ・ギデガデを旅立ってヨテバタに宿営し、'),
('JPN', '民数记', 4, 33, 34, 'ヨテバタを旅立ってアブロナに宿営し、'),
('JPN', '民数记', 4, 33, 35, 'アブロナを旅立ってエツヨン・ゲベルに宿営した。'),
('JPN', '民数记', 4, 33, 36, 'エツヨン・ゲベルを旅立ってツィンの荒野、すなわちカデシュに宿営し、'),
('JPN', '民数记', 4, 33, 37, 'カデシュを旅立ってエドムの国の端にあるホル山に宿営した。'),
('JPN', '民数记', 4, 33, 38, '祭司アロンは主の命によりホル山に登り、そこで死んだ。それは、イスラエルの子らがエジプトの地を出てから四十年目の第五の月の一日であった。'),
('JPN', '民数记', 4, 33, 39, 'アロンはホル山で死んだとき、百二十三歳であった。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '民数记', 4, 33, 40, 'カナンの地のネゲブに住んでいたカナン人、アラドの王は、イスラエル人がやって来るのを聞いた。'),
('JPN', '民数记', 4, 33, 41, 'それから、彼らはホル山を旅立ってツァルモナに宿営し、'),
('JPN', '民数记', 4, 33, 42, 'ツァルモナを旅立ってプノンに宿営し、'),
('JPN', '民数记', 4, 33, 43, 'プノンを旅立ってオボテに宿営し、'),
('JPN', '民数记', 4, 33, 44, 'オボテを旅立ってモアブの領土のイエ・ハ・アバリムに宿営した。'),
('JPN', '民数记', 4, 33, 45, 'イイムを旅立ってディボン・ガドに宿営し、'),
('JPN', '民数记', 4, 33, 46, 'ディボン・ガドを旅立ってアルモン・ディブラタイムに宿営した。'),
('JPN', '民数记', 4, 33, 47, 'アルモン・ディブラタイムを旅立って、ネボの手前にあるアバリムの山々に宿営し、'),
('JPN', '民数记', 4, 33, 48, 'アバリムの山々を旅立って、エリコをのぞむヨルダン川のほとりのモアブの草原に宿営した。'),
('JPN', '民数记', 4, 33, 49, 'すなわち、ヨルダン川のほとり、ベテ・ハ・エシモテからアベル・ハ・シティムに至るまでのモアブの草原に、彼らは宿営した。'),
('JPN', '民数记', 4, 33, 50, 'エリコをのぞむヨルダン川のほとりのモアブの草原で、主はモーセに告げられた。'),
('JPN', '民数记', 4, 33, 51, '「イスラエルの子らに告げよ。あなたがたがヨルダン川を渡ってカナンの地に入るときには、'),
('JPN', '民数记', 4, 33, 52, 'その地の住民をことごとくあなたがたの前から追い払って、彼らの石像をすべて粉砕し、彼らの鋳像をすべて粉砕し、彼らの高き所をすべて打ち壊さなければならない。'),
('JPN', '民数记', 4, 33, 53, 'あなたがたはその地を自分の所有とし、そこに住め。あなたがたが所有するように、わたしがそれを与えたからである。'),
('JPN', '民数记', 4, 33, 54, 'あなたがたは、氏族ごとに、くじを引いて、その地を相続地とせよ。大きい部族には、その相続地を大きくし、小さい部族には、その相続地を小さくしなければならない。くじで当たったその場所が、その部族のものとなる。あなたがたは、自分の父祖の部族ごとに相続地を受けなければならない。'),
('JPN', '民数记', 4, 33, 55, 'もしその地の住民をあなたがたの前から追い払わなければ、あなたがたが残しておく者たちは、あなたがたの目のとげとなり、脇腹の茨となり、彼らはあなたがたが住むその土地であなたがたを苦しめる。'),
('JPN', '民数记', 4, 33, 56, 'そしてわたしは、彼らに対してしようと計画したとおりを、あなたがたに対してすることになる。」'),
('JPN', '民数记', 4, 34, 1, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 34, 2, '「イスラエルの子らに命じて彼らに言え。あなたがたがカナンの地に入るときには、あなたがたへのゆずりとなる地、カナンの地とその境界は次のとおりである。'),
('JPN', '民数记', 4, 34, 3, 'あなたがたの南側は、エドムに接するツィンの荒野に始まる。南の境界線は、東の方の塩の海の端に始まる。'),
('JPN', '民数记', 4, 34, 4, 'その境界線は、アクラビムの坂の南から回ってツィンの方に進み、その終わりはカデシュ・バルネアの南である。またハツァル・アダルを出て、アツモンへと進む。'),
('JPN', '民数记', 4, 34, 5, 'さらに境界線は、アツモンから回ってエジプト川に向かい、その終わりは海である。'),
('JPN', '民数记', 4, 34, 6, 'あなたがたの西の境界線は、大海とその沿岸である。これをあなたがたの西の境界線としなければならない。'),
('JPN', '民数记', 4, 34, 7, 'あなたがたの北の境界線は、次のとおりにしなければならない。大海からホル山まで線を引き、'),
('JPN', '民数记', 4, 34, 8, 'さらにホル山からレボ・ハマテまで線を引く。その境界線の終わりはツェダデである。'),
('JPN', '民数记', 4, 34, 9, 'そして境界線はジフロンに延び、その終わりはハツァル・エナンである。これがあなたがたの北の境界線である。'),
('JPN', '民数记', 4, 34, 10, 'あなたがたの東の境界線としては、ハツァル・エナンからシェファムまで線を引け。'),
('JPN', '民数记', 4, 34, 11, 'その境界線は、シェファムからアインの東方のリブラに下り、それから境界線は、そこから下ってキネレテの海の東の傾斜地に達する。'),
('JPN', '民数记', 4, 34, 12, 'さらに境界線はヨルダン川を下り、その終わりは塩の海である。以上が境界線によって周囲を区切られた、あなたがたの地である。」'),
('JPN', '民数记', 4, 34, 13, 'モーセはイスラエルの子らに命じて言った。「これが、あなたがたがくじを引いて相続地とする地である。主がこれを与えよと命じられたのは、九部族と半部族に対してである。'),
('JPN', '民数记', 4, 34, 14, 'ルベン部族は一族ごとに、ガド部族も一族ごとに、そしてマナセの半部族も、自分たちの相続地を受け取っているからである。'),
('JPN', '民数记', 4, 34, 15, 'この二部族と半部族は、ヨルダン川の、エリコをのぞむ対岸、東の方、日の出る方に、自分たちの相続地を受け取っている。」'),
('JPN', '民数记', 4, 34, 16, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 34, 17, '「あなたがたにその地を相続地として受け継がせる者たちの名は、次のとおりである。すなわち、祭司エルアザルとヌンの子ヨシュア。'),
('JPN', '民数记', 4, 34, 18, 'あなたがたは、その地を受け継ぐため、それぞれの部族から族長一人ずつを選ばなければならない。'),
('JPN', '民数记', 4, 34, 19, 'その人たちの名は次のとおりである。ユダ部族からは、エフンネの子カレブ。'),
('JPN', '民数记', 4, 34, 20, 'シメオン部族からは、アミフデの子サムエル。'),
('JPN', '民数记', 4, 34, 21, 'ベニヤミン部族からは、キスロンの子エリダデ。'),
('JPN', '民数记', 4, 34, 22, 'ダン部族からは、族長として、ヨグリの子ブキ。'),
('JPN', '民数记', 4, 34, 23, 'ヨセフの子孫からは、マナセ部族から、族長として、エフォデの子ハニエル、'),
('JPN', '民数记', 4, 34, 24, 'またエフライム部族から、族長として、シフタンの子ケムエル。'),
('JPN', '民数记', 4, 34, 25, 'ゼブルン部族からは、族長として、パルナクの子エリツァファン。'),
('JPN', '民数记', 4, 34, 26, 'イッサカル部族からは、族長として、アザンの子パルティエル。'),
('JPN', '民数记', 4, 34, 27, 'アシェル部族からは、族長として、シェロミの子アヒフデ。'),
('JPN', '民数记', 4, 34, 28, 'ナフタリ部族からは、族長として、アミフデの子ペダフエル。'),
('JPN', '民数记', 4, 34, 29, 'これが、カナンの地でイスラエルの子らへの相続地を受け継がせるようにと、主が命じた人たちである。」'),
('JPN', '民数记', 4, 35, 1, 'エリコをのぞむヨルダン川のほとりのモアブの草原で、主はモーセに告げられた。'),
('JPN', '民数记', 4, 35, 2, '「イスラエルの子らに命じ、その所有となる相続地のうちから、居住のための町々をレビ人に与えよ。また、その町々の周りの放牧地はレビ人に与えなければならない。'),
('JPN', '民数记', 4, 35, 3, 'その町々は彼らが住むためのものであり、その放牧地は彼らの家畜、群れ、そしてすべての動物のためのものである。'),
('JPN', '民数记', 4, 35, 4, 'あなたがたがレビ人に与える町々の放牧地は、町の城壁から外側に向かって周囲一千キュビトである。'),
('JPN', '民数记', 4, 35, 5, 'あなたがたは、町の外側に、町を真ん中として東側に二千キュビト、南側に二千キュビト、西側に二千キュビト、北側に二千キュビトを測れ。これが彼らの町々の放牧地となる。'),
('JPN', '民数记', 4, 35, 6, 'レビ人に与える町々については、人を殺した者を逃れさせる六つの逃れの町がなければならない。また、このほかに、四十二の町を与えなければならない。'),
('JPN', '民数记', 4, 35, 7, 'レビ人に与える町は、全部で四十八の町で、放牧地付きである。'),
('JPN', '民数记', 4, 35, 8, 'あなたがたがイスラエルの子らの所有地のうちから与える町々は、大きい部族からは多く、小さい部族からは少なくしなければならない。それぞれ自分が受け継いだ相続地の大きさに応じて、自分の町々の一部をレビ人に与えなければならない。」'),
('JPN', '民数记', 4, 35, 9, '主はモーセに告げられた。'),
('JPN', '民数记', 4, 35, 10, '「イスラエルの子らに告げ、彼らに言え。ヨルダン川を渡ってカナンの地に入るとき、'),
('JPN', '民数记', 4, 35, 11, 'あなたがたは町々を定めて、自分たちのために逃れの町とし、誤って人を打ち殺してしまった殺人者がそこに逃れることができるようにしなければならない。'),
('JPN', '民数记', 4, 35, 12, 'この町々は、復讐する者からあなたがたが逃れる場所となる。殺人者が、さばきのために会衆の前に立たないうちに死ぬことのないようにするためである。'),
('JPN', '民数记', 4, 35, 13, 'あなたがたが与えるべき町は六つの逃れの町で、それらは、あなたがたのためのものである。'),
('JPN', '民数记', 4, 35, 14, 'このヨルダンの川向こうに三つの町を、カナンの地に三つの町を与えて、逃れの町としなければならない。'),
('JPN', '民数记', 4, 35, 15, 'イスラエルの子ら、または彼らの間に在住している寄留者のために、これら六つの町は逃れの場所となる。すべて誤って人を打ち殺してしまった者が、そこに逃れるためである。'),
('JPN', '民数记', 4, 35, 16, 'もし鉄の器具で人を打って死なせたなら、その人は殺人者である。その殺人者は必ず殺されなければならない。'),
('JPN', '民数记', 4, 35, 17, 'もし、人を殺せるほどの、手に持てる石で人を打って死なせたなら、その人は殺人者である。その殺人者は必ず殺されなければならない。'),
('JPN', '民数记', 4, 35, 18, 'あるいは、人を殺せるほどの、片手に持てる木製の器具で人を打って死なせたなら、その人は殺人者である。その殺人者は必ず殺されなければならない。'),
('JPN', '民数记', 4, 35, 19, '血の復讐をする者は、自分でその殺人者を殺してもよい。彼に出くわしたときに、殺してもよい。'),
('JPN', '民数记', 4, 35, 20, 'もし、人が憎しみをもって人を突き倒すか、あるいは悪意をもって人に物を投げつけて死なせたなら、'),
('JPN', '民数记', 4, 35, 21, 'または、敵意をもって人を手で打って死なせたなら、その打った者は必ず殺されなければならない。その人は殺人者である。その血の復讐をする者がその殺人者に出くわしたときには、彼を殺してもよい。'),
('JPN', '民数记', 4, 35, 22, 'もし敵意もなく突然人を突き倒し、あるいは悪意なしに何か物を投げつけ、'),
('JPN', '民数记', 4, 35, 23, 'または、人を死なせるほどの石を、よく見ないで人の上に落としてしまい、それによってその人が死んだなら、しかもその人が自分の敵ではなく、害を加えようとしたわけではないなら、'),
('JPN', '民数记', 4, 35, 24, '会衆は、打ち殺した者と、血の復讐をする者との間を、これらの定めに基づいてさばかなければならない。'),
('JPN', '民数记', 4, 35, 25, '会衆は、その殺人者を血の復讐をする者の手から救い出し、彼を、逃げ込んだその逃れの町に帰してやらなければならない。彼は、聖なる油を注がれた大祭司が死ぬまで、そこにいなければならない。'),
('JPN', '民数记', 4, 35, 26, 'もしも、その殺人者が、自分が逃げ込んだ逃れの町の境界から出て行き、'),
('JPN', '民数记', 4, 35, 27, '血の復讐をする者がその逃れの町の境界の外で彼を見つけて、その殺人者を殺すことがあっても、その人には血の責任はない。'),
('JPN', '民数记', 4, 35, 28, 'その殺人者は、大祭司が死ぬまでは、逃れの町に住んでいなければならないからである。大祭司の死後に、その殺人者は自分の所有地に帰ることができる。'),
('JPN', '民数记', 4, 35, 29, 'これらのことは、あなたがたがどこに住んでも、代々守るべき、あなたがたのさばきの掟となる。'),
('JPN', '民数记', 4, 35, 30, 'もしだれかが人を打ち殺したなら、証人たちの証言によってその殺人者を殺す。一人の証人の証言だけで、人を死刑にすることがあってはならない。'),
('JPN', '民数记', 4, 35, 31, 'あなたがたは、殺人者のいのちのために償い金を受け取ってはならない。彼は死ぬべき悪しき者なのである。彼は必ず殺されなければならない。'),
('JPN', '民数记', 4, 35, 32, '逃れの町に逃れさせる代わりに償い金を受け取り、祭司が死ぬ前に、彼を帰らせて国に住むようにさせてはならない。'),
('JPN', '民数记', 4, 35, 33, 'あなたがたは、自分たちのいる土地を汚してはならない。血は土地を汚すからである。土地にとって、そこで流された血は、その血を流した者の血以外によって宥められることはない。'),
('JPN', '民数记', 4, 35, 34, 'あなたがたは、自分たちの住む土地、わたし自身がそのただ中に宿る土地を汚してはならない。主であるわたしが、イスラエルの子らのただ中に宿るからである。」'),
('JPN', '民数记', 4, 36, 1, 'ヨセフ族の一つの氏族、マナセの子マキルの子ギルアデの氏族に属する一族のかしらたちが進み出て、モーセと、イスラエルの子らの一族のかしらである家長たちの前でこう語った。'),
('JPN', '民数记', 4, 36, 2, '「主は、くじによってあの地をイスラエルの子らに相続地として与えるように、あなたに命じられました。そしてまた、私たちの親類ツェロフハデの相続地を彼の娘たちに与えるように、あなたは主によって命じられています。'),
('JPN', '民数记', 4, 36, 3, 'もし彼女たちが、イスラエルの子らのうちのほかの部族の息子に嫁いだなら、彼女たちの相続地は、私たちの先祖の相続地から差し引かれて、彼女たちが嫁ぐ部族の相続地に加えられるでしょう。その結果、私たちが相続する割り当て地は減ることになります。'),
('JPN', '民数记', 4, 36, 4, 'イスラエルの子らにヨベルの年が来れば、彼女たちの相続地は、彼女たちが嫁ぐ部族の相続地に加えられ、彼女たちの相続地は、私たちの先祖の部族の相続地から取り去られることになります。」'),
('JPN', '民数记', 4, 36, 5, 'そこでモーセは、主の命により、イスラエルの子らに命じた。「ヨセフ部族の訴えはもっともである。'),
('JPN', '民数记', 4, 36, 6, '主がツェロフハデの娘たちについて命じられたことは次のとおりである。『彼女たちは、自分が良いと思う人に嫁いでよい。ただし、彼女たちの父の部族に属する氏族に嫁がなければならない。'),
('JPN', '民数记', 4, 36, 7, 'イスラエルの子らの相続地は、部族から部族に移してはならない。イスラエルの子らは、それぞれその父祖の部族の相続地を堅く守らなければならないからである。'),
('JPN', '民数记', 4, 36, 8, 'イスラエルの子らの部族のうち、相続地を受け継ぐ娘はみな、その父の部族に属する氏族の一人に嫁がなければならない。イスラエルの子らが、それぞれ、その父祖の相続地を受け継ぐようにするためである。'),
('JPN', '民数记', 4, 36, 9, 'このように、相続地は、部族からほかの部族に移してはならない。イスラエルの子らの部族は、それぞれ、自分たちの相続地を堅く守らなければならないからである。』」'),
('JPN', '民数记', 4, 36, 10, 'ツェロフハデの娘たちは、主がモーセに命じられたとおりに行った。'),
('JPN', '民数记', 4, 36, 11, 'ツェロフハデの娘たち、マフラ、ティルツァ、ホグラ、ミルカおよびノアは、おじの息子たちに嫁いだ。'),
('JPN', '民数记', 4, 36, 12, '彼女たちは、ヨセフの子マナセの子孫の氏族に嫁いだので、彼女たちの相続地は、彼女たちの父の氏族の部族に残った。'),
('JPN', '民数记', 4, 36, 13, 'これらは、エリコをのぞむヨルダン川のほとりのモアブの草原で、主がモーセを通してイスラエルの子らに命じられた命令と定めである。'),
('JPN', '申命记', 5, 1, 1, 'これは、モーセがイスラエルのすべての民に告げたことばである。ヨルダンの川向こう、パランと、トフェル、ラバン、ハツェロテ、ディ・ザハブとの間の、スフに面したアラバの荒野でのことであった。'),
('JPN', '申命记', 5, 1, 2, '──ホレブからセイル山を経てカデシュ・バルネアに至る道のりは、十一日である──'),
('JPN', '申命记', 5, 1, 3, '第四十年の第十一月の一日にモーセは、主がイスラエルの子らのために彼に命じられた、すべてのことにしたがって、彼らに語った。'),
('JPN', '申命记', 5, 1, 4, 'それはモーセが、ヘシュボンに住んでいたアモリ人の王シホン、およびアシュタロテに住んでいたバシャンの王オグを、エデレイで打ち破った後のことであった。'),
('JPN', '申命记', 5, 1, 5, 'ヨルダンの川向こう、モアブの地で、モーセは次のように、みおしえの確認を行うことにした。'),
('JPN', '申命记', 5, 1, 6, '私たちの神、主はホレブで私たちに告げられた。「あなたがたはこの山に十分長くとどまった。'),
('JPN', '申命记', 5, 1, 7, 'あなたがたは向きを変えて出発せよ。そしてアモリ人の山地に、またそのすべての近隣の者たちの地、すなわち、アラバ、山地、シェフェラ、ネゲブ、海辺、カナン人の地、レバノン、さらにあの大河ユーフラテス川にまで行け。'),
('JPN', '申命记', 5, 1, 8, '見よ、わたしはその地をあなたがたの手に渡している。行け。その地を所有せよ。これは主があなたがたの父祖アブラハム、イサク、ヤコブに対して、彼らとその後の子孫に与えると誓った地である。」'),
('JPN', '申命记', 5, 1, 9, '私はあのとき、あなたがたにこう言った。「私一人であなたがたを負うことはできない。'),
('JPN', '申命记', 5, 1, 10, 'あなたがたの神、主があなたがたを増やされたので、見よ、あなたがたは今日、空の星のように多い。'),
('JPN', '申命记', 5, 1, 11, 'どうか、あなたがたの父祖の神、主があなたがたを今の千倍にも増やしてくださるように。そして、あなたがたに約束されたとおり、あなたがたを祝福してくださるように。'),
('JPN', '申命记', 5, 1, 12, 'どのようにして、私一人であなたがたのもめごとと重荷と争いを負いきれるだろうか。'),
('JPN', '申命记', 5, 1, 13, 'あなたがたは部族ごとに、知恵があり判断力があり経験に富む人たちを出しなさい。彼らをあなたがたのかしらとして立てよう。」'),
('JPN', '申命记', 5, 1, 14, 'すると、あなたがたは私に答えて、「あなたがしようと言われたことは良いことです」と言った。'),
('JPN', '申命记', 5, 1, 15, 'そこで私は、あなたがたの部族のかしらで、知恵があり経験に富む人たちを選び取り、彼らをあなたがたの上に立つかしらとし、あなたがたの部族の千人の長、百人の長、五十人の長、十人の長、また、つかさたちとした。'),
('JPN', '申命记', 5, 1, 16, 'そのとき、私はあなたがたのさばき人たちに命じた。「あなたがたの同胞相互の言い分をよく聞き、ある人とその同胞との間、また寄留者との間を正しくさばきなさい。'),
('JPN', '申命记', 5, 1, 17, '裁判では人を偏って見てはならない。身分の低い人にも高い人にもみな、同じように聞かなければならない。人を恐れてはならない。さばきは神のものだからである。あなたがたにとって難しすぎる事柄は、私のところに持って来なさい。私がそれを聞こう。」'),
('JPN', '申命记', 5, 1, 18, '私はまた、そのとき、あなたがたが行うべきすべてのことを命じた。'),
('JPN', '申命记', 5, 1, 19, '私たちの神、主が私たちに命じられたとおりに私たちはホレブを旅立ち、あなたがたが見た、あの大きな恐ろしい荒野、すなわちアモリ人の山地への道を進み、カデシュ・バルネアまで来た。'),
('JPN', '申命记', 5, 1, 20, 'そのとき、私はあなたがたに言った。「あなたがたは、私たちの神、主が私たちに与えようとされるアモリ人の山地に来た。'),
('JPN', '申命记', 5, 1, 21, '見よ、あなたの神、主はこの地をあなたの手に渡してくださった。上れ。占領せよ。あなたの父祖の神、主があなたに告げられたとおりに。恐れてはならない。おののいてはならない。」'),
('JPN', '申命记', 5, 1, 22, 'すると、あなたがたはみな私のもとに近寄って来て言った。「私たちより先に人を遣わし、私たちのためにその地を探らせよう。そして、私たちが上って行く道や入って行く町々について、報告を持ち帰らせよう。」'),
('JPN', '申命记', 5, 1, 23, '私にはこのことが良いことと思われたので、私はあなたがたの中から各部族ごとに一人ずつ、十二人を選んだ。'),
('JPN', '申命记', 5, 1, 24, '彼らは出発し、山地に向かって上って行き、エシュコルの谷まで行き、そこを偵察した。'),
('JPN', '申命记', 5, 1, 25, '彼らはその地の果物を手に入れ、私たちのもとに持って帰って来た。そして報告をし、「私たちの神、主が私たちに与えようとしておられる地は良い地です」と言った。'),
('JPN', '申命记', 5, 1, 26, 'しかし、あなたがたは上って行こうとせず、あなたがたの神、主の命令に逆らった。'),
('JPN', '申命记', 5, 1, 27, 'そして天幕の中で不平を言った。「主は私たちを憎んでおられるので、私たちをエジプトの地から連れ出して、アモリ人の手に渡し、私たちを根絶やしにしようとしておられるのだ。'),
('JPN', '申命记', 5, 1, 28, '私たちはどこへ上って行くのか。私たちの兄弟たちは、『その民は私たちよりも大きくて背が高い。町々は大きく、城壁は高く天にそびえている。しかも、そこでアナク人を見た』と言って、私たちの心を萎えさせた。」'),
('JPN', '申命记', 5, 1, 29, 'それで私はあなたがたに言った。「おののいてはならない。彼らを恐れてはならない。'),
('JPN', '申命记', 5, 1, 30, 'あなたがたに先立って行かれるあなたがたの神、主があなたがたのために戦われる。エジプトで、あなたがたの目の前で、あなたがたのためにしてくださったのと同じように。'),
('JPN', '申命记', 5, 1, 31, 'また荒野では、この場所に来るまでの全道中、あなたの神、主が、人が自分の子を抱くようにあなたを抱いてくださったのを、あなたがたは見ているのだ。'),
('JPN', '申命记', 5, 1, 32, 'このようなことによっても、まだあなたがたはあなたがたの神、主を信じていない。'),
('JPN', '申命记', 5, 1, 33, '主はあなたがたが宿営する場所を探すために、道中あなたがたの先に立って行き、夜は火の中、昼は雲の中にあって、あなたがたが行くべき道を示されるのだ。」'),
('JPN', '申命记', 5, 1, 34, '主はあなたがたの不平の声を聞いて怒り、誓って言われた。'),
('JPN', '申命记', 5, 1, 35, '「この悪い世代の者たちのうちには、わたしがあなたがたの父祖たちに与えると誓った、あの良い地を見る者は一人もいない。'),
('JPN', '申命记', 5, 1, 36, 'ただエフンネの子カレブだけがそれを見ることができる。彼が踏んだ地を、わたしは彼とその子孫に与える。彼が主に従い通したからだ。」'),
('JPN', '申命记', 5, 1, 37, '主はあなたがたのゆえに、この私に対しても怒って言われた。「あなたも、そこに入れない。'),
('JPN', '申命记', 5, 1, 38, 'あなたに仕えているヌンの子ヨシュアは、そこに入ることができる。彼を力づけよ。彼がそこをイスラエルに受け継がせるからだ。'),
('JPN', '申命记', 5, 1, 39, 'あなたがたが略奪されるだろうと言ったあなたがたの幼子たちや、今はまだ善悪をわきまえないあなたがたの子どもたちが、そこに入る。わたしが彼らにそこを与えるので、彼らはそこを所有するようになる。'),
('JPN', '申命记', 5, 1, 40, 'あなたがたは向きを変え、葦の海の道を通って荒野に向かって旅立て。」'),
('JPN', '申命记', 5, 1, 41, 'すると、あなたがたは私に答えて言った。「私たちは主に対して罪を犯した。私たちの神、主が命じられたとおりに、私たちは上って行って戦おう。」そして、それぞれ武具を身に帯びて、無謀にも山地に上って行こうとした。'),
('JPN', '申命记', 5, 1, 42, '主は私に言われた。「彼らに言え。『上って行ってはならない。戦ってはならない。わたしはあなたがたのうちにいないからだ。あなたがたは敵に打ち負かされてはならない。』」'),
('JPN', '申命记', 5, 1, 43, '私があなたがたにこう告げたのに、あなたがたは聞かず、主の命に逆らい、不遜にも山地に上って行った。'),
('JPN', '申命记', 5, 1, 44, 'するとその山地に住んでいたアモリ人が出て来て、あなたがたを迎え撃ち、蜂が襲うようにあなたがたを追いかけ、あなたがたをセイルで打ち破り、ホルマにまで及んだ。'),
('JPN', '申命记', 5, 1, 45, 'あなたがたは戻って来て主の前で泣いたが、主はあなたがたの声を聞き入れず、耳を傾けられなかった。'),
('JPN', '申命记', 5, 1, 46, 'こうしてあなたがたは、実際にあなたがたがとどまったとおり、長い期間カデシュにとどまった。'),
('JPN', '申命记', 5, 2, 1, 'それから、私たちは向きを変え、主が私に告げられたように葦の海の道を荒野に向かって旅立ち、長らくセイル山の周りを移動していた。'),
('JPN', '申命记', 5, 2, 2, '主は私にこう言われた。'),
('JPN', '申命记', 5, 2, 3, '「あなたがたは長い間この山の周りを移動してきたが、北の方に向きを変えよ。'),
('JPN', '申命记', 5, 2, 4, '民に命じて言え。あなたがたは、セイルに住んでいるエサウの子ら、あなたがたの同族の領土内を通ろうとしている。彼らはあなたがたを恐れるであろう。ただし、あなたがたは十分に注意せよ。'),
('JPN', '申命记', 5, 2, 5, '彼らに戦いを仕掛けてはならない。わたしは彼らの地を、足の裏で踏むほどさえも、あなたがたには与えない。わたしはエサウにセイルの山を、彼の所有地として与えたからである。'),
('JPN', '申命记', 5, 2, 6, '食物は彼らから金で買って食べ、水も彼らから金で買って飲まなければならない。'),
('JPN', '申命记', 5, 2, 7, '事実、あなたの神、主はあなたのしたすべてのことを祝福し、この広大な荒野でのあなたの旅を見守っていたのだ。この四十年の間、あなたの神、主はあなたとともにいて、あなたには何一つ欠けたものがなかった。」'),
('JPN', '申命记', 5, 2, 8, 'それで私たちは、セイルに住むエサウの子孫である私たちの同族から離れ、アラバへの道から離れ、エイラトからも、またエツヨン・ゲベルからも離れて進んで行った。そして、私たちは向きを変えて、モアブの荒野への道を進んで行った。'),
('JPN', '申命记', 5, 2, 9, '主は私に言われた。「モアブに敵対してはならない。彼らに戦いを仕掛けてはならない。あなたには、その地を所有地として与えない。わたしはアルをロトの子孫に所有地として与えたからである。'),
('JPN', '申命记', 5, 2, 10, '──以前そこにはエミム人が住んでいた。アナク人のように大きくて背が高い民で、数も多かった。'),
('JPN', '申命记', 5, 2, 11, 'アナク人と同じく彼らもレファイムであると見なされていた。モアブ人は彼らをエミム人と呼んでいた。'),
('JPN', '申命记', 5, 2, 12, 'セイルには以前フリ人が住んでいたが、エサウの子孫がこれを追い払い、これを根絶やしにし、彼らに代わって住むようになった。ちょうど、イスラエルが主の下さった所有地に対してしたようにである──'),
('JPN', '申命记', 5, 2, 13, '今、立ってゼレデ川を渡れ。」そこで私たちはゼレデ川を渡った。'),
('JPN', '申命记', 5, 2, 14, 'カデシュ・バルネアを出てからゼレデ川を渡るまでの期間は、三十八年であった。それまでに、その世代の戦士たちはみな宿営のうちから絶えてしまっていた。主が彼らについて誓われたとおりであった。'),
('JPN', '申命记', 5, 2, 15, '確かに主の御手が彼らに下り、彼らをかき乱し、宿営のうちから絶やされたのである。'),
('JPN', '申命记', 5, 2, 16, '戦士たちがみな民の間から絶えたとき、'),
('JPN', '申命记', 5, 2, 17, '主は私に告げられた。'),
('JPN', '申命记', 5, 2, 18, '「あなたは今日、モアブの領土アルを通ろうとしている。'),
('JPN', '申命记', 5, 2, 19, 'アンモン人の近くに行くが、彼らに敵対してはならない。彼らに戦いを仕掛けてはならない。あなたにはアンモン人の地を所有地として与えない。わたしはそれをロトの子孫に所有地として与えたからである。'),
('JPN', '申命记', 5, 2, 20, '──そこもレファイムの地だと見なされていた。以前はレファイムがそこに住んでいて、アンモン人は彼らをザムズミム人と呼んでいた。'),
('JPN', '申命记', 5, 2, 21, '彼らは、アナク人のように大きくて背が高い民で、数も多かった。しかし主がこれを滅ぼされたので、アンモン人がこれを追い払い、彼らに代わって住んだ。'),
('JPN', '申命记', 5, 2, 22, 'それは、セイルに住んでいるエサウの子孫のために、主が彼らの前からフリ人を滅ぼされたのと同じである。彼らはフリ人を追い払い、彼らに代わって住み、今日に至っている。'),
('JPN', '申命记', 5, 2, 23, 'また、ガザ近郊の村々に住んでいたアビム人については、カフトルから出て来たカフトル人が根絶やしにし、彼らに代わって住んだのであった──'),
('JPN', '申命记', 5, 2, 24, '立ち上がって出発せよ。アルノン川を渡れ。見よ、わたしはヘシュボンの王アモリ人シホンとその国を、あなたの手に渡す。占領し始めよ。彼と戦いを交えよ。'),
('JPN', '申命记', 5, 2, 25, '今日から、わたしは天下のあらゆる民に、あなたに対するおののきと恐れを抱かせる。彼らはあなたのうわさを聞いて震え、あなたの前でもだえる。」'),
('JPN', '申命记', 5, 2, 26, 'そこで私は、ケデモテの荒野からヘシュボンの王シホンに使者たちを遣わし、次のような友好のことばを伝えた。'),
('JPN', '申命记', 5, 2, 27, '「あなたの土地を通らせてください。私は大路だけを通り、右にも左にもそれません。'),
('JPN', '申命记', 5, 2, 28, '食べ物は金で私に売ってください。それを食べます。水も金を取って私に与えてください。それを飲みます。徒歩で通らせてくださるだけでよいのです。'),
('JPN', '申命记', 5, 2, 29, 'セイルに住んでいるエサウの子孫や、アルに住んでいるモアブ人が私にしたようにしてください。そうして、私がヨルダン川を渡り、私たちの神、主が私たちに与えようとしておられる地に行けるようにしてください。」'),
('JPN', '申命记', 5, 2, 30, 'しかし、ヘシュボンの王シホンは、私たちをどうしても通らせようとはしなかった。それは今日見るとおり、彼をあなたの手に渡すために、あなたの神、主が彼の心を頑なにし、彼を強気にされたからである。'),
('JPN', '申命记', 5, 2, 31, '主は私に言われた。「見よ、わたしはシホンとその地とをあなたの手に渡し始めている。占領し始めよ。その地を所有せよ。」'),
('JPN', '申命记', 5, 2, 32, 'シホンとそのすべての兵が、私たちを迎え撃つためヤハツに出て来たとき、'),
('JPN', '申命记', 5, 2, 33, '私たちの神、主は彼を私たちの手に渡された。私たちは彼とその子たちとそのすべての兵を討った。'),
('JPN', '申命记', 5, 2, 34, 'そのとき、私たちは彼のすべての町を攻め取り、すべての町、男、女および子どもを聖絶し、一人の生存者も残さなかった。'),
('JPN', '申命记', 5, 2, 35, '私たちは、攻め取った町々での略奪物のほかは、家畜を分捕っただけであった。'),
('JPN', '申命记', 5, 2, 36, 'アルノンの渓谷の縁にあるアロエル、およびその渓谷の中の町からギルアデに至るまで、私たちの力が及ばない町は一つもなかった。私たちの神、主がそれらをみな私たちの手に渡されたのである。'),
('JPN', '申命记', 5, 2, 37, 'ただ、あなたはアンモン人の地、ヤボク川の全岸と山地の町々には、私たちの神、主が命じられたとおり近寄らなかった。'),
('JPN', '申命记', 5, 3, 1, '私たちはバシャンへの道を上って行った。するとバシャンの王オグとそのすべての兵は、エデレイで私たちを迎え撃つために出て来た。'),
('JPN', '申命记', 5, 3, 2, 'そのとき、主は私に言われた。「彼を恐れてはならない。わたしは、彼とそのすべての兵とその地を、あなたの手に渡している。あなたは彼に対して、ヘシュボンに住んでいたアモリ人の王シホンにしたように行わなければならない。」'),
('JPN', '申命记', 5, 3, 3, 'こうして私たちの神、主は、バシャンの王オグとそのすべての兵を私たちの手に渡されたので、私たちはこれを討ち、一人の生存者も残さなかった。'),
('JPN', '申命记', 5, 3, 4, 'そのとき、私たちは彼のすべての町を攻め取った。私たちが取らなかった町は一つもなかった。取った町は六十、アルゴブの全地域であり、バシャンのオグの王国であった。'),
('JPN', '申命记', 5, 3, 5, 'これらはみな、高い城壁と門とかんぬきのある要害の町であった。このほか、城壁のない村も非常に多かった。'),
('JPN', '申命记', 5, 3, 6, '私たちはヘシュボンの王シホンにしたように、これらを聖絶した。そのすべての町、男、女および子どもを聖絶した。'),
('JPN', '申命记', 5, 3, 7, 'ただし、すべての家畜と、町々での略奪物は私たちのものとした。'),
('JPN', '申命记', 5, 3, 8, 'このようにして、そのとき私たちは、二人のアモリ人の王の手からヨルダンの川向こうを、アルノン川からヘルモン山まで取った。'),
('JPN', '申命记', 5, 3, 9, '──シドン人はヘルモンをシルヨンと呼び、アモリ人はこれをセニルと呼んでいる──'),
('JPN', '申命记', 5, 3, 10, 'すなわち、高原のすべての町、ギルアデの全土、バシャンの全土、サルカおよびエデレイに及ぶ、バシャンのオグの王国の町々である。'),
('JPN', '申命记', 5, 3, 11, '──バシャンの王オグはレファイムの唯一の生き残りであった。見よ。彼の寝台は鉄の寝台で、それはアンモン人のラバにあるではないか。その長さは規準のキュビトで九キュビト、その幅は四キュビトである──'),
('JPN', '申命记', 5, 3, 12, 'この地を、そのとき私たちは占領した。アルノン川のほとりにあるアロエルの一部と、ギルアデの山地の半分と、その町々を私はルベン人とガド人に与えた。'),
('JPN', '申命记', 5, 3, 13, 'ギルアデの残りと、オグの王国であったバシャンの全土はマナセの半部族に与えた。それはアルゴブの全地域で、そのバシャンの全土はレファイムの地と呼ばれている。'),
('JPN', '申命记', 5, 3, 14, 'マナセの子ヤイルは、ゲシュル人とマアカ人との国境までのアルゴブの全地域を取り、自分の名にちなんでバシャンをハボテ・ヤイルと名づけて、今日に至っている。'),
('JPN', '申命记', 5, 3, 15, 'マキルには私はギルアデを与えた。'),
('JPN', '申命记', 5, 3, 16, 'ルベン人とガド人にはギルアデからアルノン川までを、谷の真ん中を国境として、またアンモン人との国境としてヤボク川までを与えた。'),
('JPN', '申命记', 5, 3, 17, 'またアラバも与えた。それはヨルダン川を境としてキネレテからアラバの海、すなわち、東の方はピスガの傾斜地のふもとにある塩の海までであった。'),
('JPN', '申命记', 5, 3, 18, '私はそのとき、あなたがたに命じて言った。「あなたがたの神、主は、あなたがたが所有するように、この地をあなたがたに与えられた。勇士たちはみな武装して、同族、イスラエルの子らの先頭に立って渡って行かなければならない。'),
('JPN', '申命记', 5, 3, 19, 'ただし、あなたがたの妻と子どもと家畜は、私が与えた町々にとどまっていてもよい。あなたがたには多くの家畜がいるのを、私はよく知っている。'),
('JPN', '申命记', 5, 3, 20, '主があなたがたの同族に、あなたがたと同じように安息を与え、彼らもまたヨルダン川の向こう側で、あなたがたの神、主が与えようとしておられる地を所有するようになったなら、そのとき、あなたがたは、それぞれ私が与えた自分の所有地に帰ることができる。」'),
('JPN', '申命记', 5, 3, 21, '私はそのとき、ヨシュアに命じた。「あなたは、あなたがたの神、主がこれら二人の王に対して行われたすべてのことを、自分の目で見た。主は、あなたがこれから渡って行くすべての国々にも同じようにされる。'),
('JPN', '申命记', 5, 3, 22, '彼らを恐れてはならない。あなたがたのために戦われるのは、あなたがたの神、主であるからだ。」'),
('JPN', '申命记', 5, 3, 23, '私はそのとき、主に懇願して言った。'),
('JPN', '申命记', 5, 3, 24, '「神、主よ。あなたは、あなたの偉大さとあなたの力強い御手を、このしもべに示し始められました。あなたのわざ、あなたの力あるわざのようなことができる神が、天あるいは地にいるでしょうか。'),
('JPN', '申命记', 5, 3, 25, 'どうか私が渡って行って、ヨルダン川の向こう側にある良い地、あの良い山地、またレバノンを見られるようにしてください。」'),
('JPN', '申命记', 5, 3, 26, 'しかし主はあなたがたのゆえに私に激しく怒り、私の願いを聞き入れてくださらなかった。主は私に言われた。「もう十分だ。このことについて二度とわたしに語ってはならない。'),
('JPN', '申命记', 5, 3, 27, 'ピスガの頂に登り、目を上げて西、北、南、東を見よ。あなたのその目でよく見よ。あなたがこのヨルダン川を渡ることはないからだ。'),
('JPN', '申命记', 5, 3, 28, 'ヨシュアに命じ、彼を力づけ、彼を励ませ。彼がこの民の先頭に立って渡って行き、あなたが見るあの地を彼らに受け継がせるからだ。」'),
('JPN', '申命记', 5, 3, 29, 'こうして私たちは、ベテ・ペオルの前にある谷にとどまった。'),
('JPN', '申命记', 5, 4, 1, '今、イスラエルよ、私が教える掟と定めを聞き、それらを行いなさい。それはあなたがたが生き、あなたがたの父祖の神、主があなたがたに与えようとしておられる地に入り、それを所有するためである。'),
('JPN', '申命记', 5, 4, 2, '私があなたがたに命じることばにつけ加えてはならない。また減らしてはならない。私があなたがたに命じる、あなたがたの神、主の命令を守らなければならない。'),
('JPN', '申命记', 5, 4, 3, 'あなたがたは、主がバアル・ペオルのことでなさったことを自分の目で見た。バアル・ペオルに従った者すべてを、あなたの神、主はあなたのうちから根絶やしにされたのである。'),
('JPN', '申命记', 5, 4, 4, 'しかし、あなたがたの神、主にすがってきたあなたがたはみな、今日生きている。'),
('JPN', '申命记', 5, 4, 5, '見なさい。私は、私の神、主が私に命じられたとおりに掟と定めをあなたがたに教えた。あなたがたが入って行き、所有しようとしているその地の真ん中で、そのとおりに行うためである。'),
('JPN', '申命记', 5, 4, 6, 'これを守り行いなさい。そうすれば、それは諸国の民にあなたがたの知恵と悟りを示すことになり、彼らはこれらすべての掟を聞いて、「この偉大な国民は確かに知恵と悟りのある民だ」と言うであろう。'),
('JPN', '申命记', 5, 4, 7, 'まことに、私たちの神、主は私たちが呼び求めるとき、いつも近くにおられる。このような神を持つ偉大な国民がどこにあるだろうか。'),
('JPN', '申命记', 5, 4, 8, 'また、今日私があなたがたの前に与えようとしている、このみおしえのすべてのように正しい掟と定めを持つ偉大な国民が、いったいどこにあるだろうか。'),
('JPN', '申命记', 5, 4, 9, 'ただ、あなたはよく気をつけ、十分に用心し、あなたが自分の目で見たことを忘れず、一生の間それらがあなたの心から離れることのないようにしなさい。そしてそれらを、あなたの子どもや孫たちに知らせなさい。'),
('JPN', '申命记', 5, 4, 10, 'あなたがホレブで、あなたの神、主の前に立った日に主は私に言われた。「民をわたしのもとに集めよ。わたしは彼らにわたしのことばを聞かせる。それによって、彼らが地上に生きている日の間わたしを恐れることを学び、また彼らがその子どもたちに教えることができるように。」'),
('JPN', '申命记', 5, 4, 11, 'そこであなたがたは近づいて来て、山のふもとに立った。山は燃え上がって火が中天に達し、闇と雲と暗黒があった。'),
('JPN', '申命记', 5, 4, 12, '主は火の中からあなたがたに語られた。あなたがたは語りかける声を聞いたが、御姿は見なかった。御声だけであった。'),
('JPN', '申命记', 5, 4, 13, '主はご自分の契約をあなたがたに告げて、それを行うように命じられた。十のことばである。主はそれを二枚の石の板に書き記された。'),
('JPN', '申命记', 5, 4, 14, '主はそのとき、あなたがたに掟と定めを教えるように私に命じられた。あなたがたが、渡って行って所有しようとしている地で、それらを行うためであった。'),
('JPN', '申命记', 5, 4, 15, 'あなたがたは自分自身に十分に気をつけなさい。主がホレブで火の中からあなたがたに語られた日に、あなたがたは何の姿も見なかったからである。'),
('JPN', '申命记', 5, 4, 16, '堕落して自分たちのために、どのような形の彫像も造らないようにしなさい。男の形も女の形も。'),
('JPN', '申命记', 5, 4, 17, '地上のどのような動物の形も、空を飛ぶ、翼のあるどのような鳥の形も。'),
('JPN', '申命记', 5, 4, 18, '地面を這うどのようなものの形も、地の下の水の中にいるどのような魚の形も。'),
('JPN', '申命记', 5, 4, 19, 'また、天に目を上げて、太陽、月、星など天の万象を見るとき、惑わされてそれらを拝み、それらに仕えることのないようにしなさい。それらのものは、あなたの神、主が天下のあらゆる民に分け与えられたものである。'),
('JPN', '申命记', 5, 4, 20, '主はあなたがたを取って、鉄の炉から、すなわちエジプトから導き出し、今日のようにゆずりの民とされたのである。'),
('JPN', '申命记', 5, 4, 21, 'しかし主は、あなたがたのゆえに私に向かって怒り、私がヨルダン川を渡ることも、またあなたの神、主があなたにゆずりの地として与える、良い地に入ることもないと誓われた。'),
('JPN', '申命记', 5, 4, 22, 'まことに私はこの地で死のうとしている。私はヨルダン川を渡らない。しかし、あなたがたは渡って、あの良い地を所有しようとしている。'),
('JPN', '申命记', 5, 4, 23, '気をつけて、あなたがたの神、主があなたがたと結ばれた契約を忘れることのないように、またあなたの神、主の命令に背いて、いかなる形の彫像も造ることがないようにしなさい。'),
('JPN', '申命记', 5, 4, 24, 'あなたの神、主は焼き尽くす火、ねたみの神である。'),
('JPN', '申命记', 5, 4, 25, 'あなたが子や孫をもうけ、あなたがたがその地に長く住むうちに堕落して、何かの形に刻んだ像を造り、あなたの神、主の目に悪であることを行い、御怒りを引き起こすようなことがあれば、'),
('JPN', '申命记', 5, 4, 26, '私は今日、次のことで、あなたがたに対して天と地を証人に立てる。あなたがたは、ヨルダン川を渡って所有しようとしているその地から追われ、たちまち滅び失せる。そこで、あなたがたは長く生きるどころか、すっかり根絶やしにされる。'),
('JPN', '申命记', 5, 4, 27, 'また、主はあなたがたを諸国の民の中に散らされ、あなたがたは主が追いやる国々の中で、ごくわずかな者として生き残ることになる。'),
('JPN', '申命记', 5, 4, 28, 'あなたがたはそこで、見ることも聞くこともできず、食べることも嗅ぐこともできない、人の手のわざである木や石の神々に仕える。'),
('JPN', '申命记', 5, 4, 29, 'しかしそこから、あなたがたがあなたの神、主を探し求め、心を尽くし、いのちを尽くして求めるとき、あなたは主にお会いする。'),
('JPN', '申命记', 5, 4, 30, 'こうして終わりの日に、これらすべてのことがあなたに臨み、あなたが苦しみのうちにあるとき、あなたは、あなたの神、主に立ち返り、御声に聞き従う。'),
('JPN', '申命记', 5, 4, 31, 'あなたの神、主はあわれみ深い神であり、あなたを捨てず、あなたを滅ぼさず、あなたの父祖たちに誓った契約を忘れないからである。'),
('JPN', '申命记', 5, 4, 32, 'さあ、あなたより前の過ぎ去った時代に尋ねてみるがよい。神が地上に人を創造された日からこのかた、天の果てから天の果てまで、これほど偉大なことが起こっただろうか。このようなことが聞かれただろうか。'),
('JPN', '申命记', 5, 4, 33, '火の中から語られる神の声を聞いて、あなたのようになお生きていた民があっただろうか。'),
('JPN', '申命记', 5, 4, 34, 'あるいは、あなたがたの神、主がエジプトにおいて、あなたの目の前であなたがたのためになさったように、試みと、しるしと不思議と、戦いをもって、また力強い御手と伸ばされた御腕と、恐ろしい力をもって、一つの国民をほかの国民の中から取り、ご自分のものにされた神がかつてあっただろうか。'),
('JPN', '申命记', 5, 4, 35, 'あなたにこのことが示されたのは、主だけが神であり、ほかに神はいないことを、あなたが知るためであった。'),
('JPN', '申命记', 5, 4, 36, '主はあなたを訓練するため、天から御声を聞かせ、地の上では大いなるご自分の火を見せられた。その火の中から、あなたはみことばを聞いた。'),
('JPN', '申命记', 5, 4, 37, '主はあなたの父祖たちを愛し、その後の子孫を選んでいたので、ご臨在の中、大いなる力をもってあなたをエジプトから導き出された。'),
('JPN', '申命记', 5, 4, 38, 'それは、あなたよりも大きくて強い国々をあなたの前から追い払い、あなたを彼らの地に導き入れ、今日見るとおり、彼らの地をゆずりの地としてあなたに与えるためであった。'),
('JPN', '申命记', 5, 4, 39, '今日あなたは、上は天、下は地において主だけが神であり、ほかに神はいないことを知り、心にとどめなさい。'),
('JPN', '申命记', 5, 4, 40, '今日、私が命じる主の掟と命令を守りなさい。あなたも、あなたの後の子孫も幸せになり、あなたの神、主が永久に与えようとしておられるその土地で、あなたの日々が長く続くようにするためである。'),
('JPN', '申命记', 5, 4, 41, 'それからモーセは、ヨルダンの川向こう、すなわち東の方に、三つの町を取り分けた。'),
('JPN', '申命记', 5, 4, 42, '前から憎んでいたわけではない隣人を意図せずに殺してしまった者が、そこに逃れるためであった。その者はこれらの町の一つに逃れて、生き延びることができる。'),
('JPN', '申命记', 5, 4, 43, 'それは、ルベン人には台地の荒野のベツェル、ガド人にはギルアデのラモテ、マナセ人にはバシャンのゴランであった。'),
('JPN', '申命记', 5, 4, 44, 'これは、モーセがイスラエルの子らに示したみおしえである。'),
('JPN', '申命记', 5, 4, 45, 'これらはさとしと掟と定めであり、イスラエルの子らがエジプトを出たとき、モーセが彼らに告げたものである。'),
('JPN', '申命记', 5, 4, 46, 'そこはヨルダンの川向こう、アモリ人の王シホンの地のベテ・ペオルの前にある谷であった。このシホンはヘシュボンに住んでいたが、モーセとイスラエルの子らがエジプトから出て来たときに、彼らは彼を討った。'),
('JPN', '申命记', 5, 4, 47, 'そして、シホンの地と、バシャンの王オグの地を占領した。そこはヨルダンの川向こう、東の方にいた二人のアモリ人の王の地で、'),
('JPN', '申命记', 5, 4, 48, 'アルノンの渓谷の縁にあるアロエルからシーオン山、すなわちヘルモンまで、'),
('JPN', '申命记', 5, 4, 49, 'またヨルダンの川向こう、東側のアラバの全土、ピスガの傾斜地のふもとにあるアラバの海までであった。'),
('JPN', '申命记', 5, 5, 1, 'モーセはイスラエルをみな呼び寄せて、彼らに言った。聞け、イスラエルよ。今日、私があなたがたの耳に語る掟と定めを。これを学び、守り行いなさい。'),
('JPN', '申命记', 5, 5, 2, '私たちの神、主はホレブで私たちと契約を結ばれた。'),
('JPN', '申命记', 5, 5, 3, '主はこの契約を私たちの先祖と結ばれたのではなく、今日ここに生きている私たち一人ひとりと結ばれたのである。'),
('JPN', '申命记', 5, 5, 4, '主はあの山で、火の中からあなたがたに顔と顔を合わせて語られた。'),
('JPN', '申命记', 5, 5, 5, 'あのとき、私は主とあなたがたとの間に立ち、主のことばをあなたがたに告げた。あなたがたが火を恐れて、山に登らなかったからである。主は言われた。'),
('JPN', '申命记', 5, 5, 6, '「わたしは、あなたをエジプトの地、奴隷の家から導き出したあなたの神、主である。'),
('JPN', '申命记', 5, 5, 7, 'あなたには、わたし以外に、ほかの神があってはならない。'),
('JPN', '申命记', 5, 5, 8, 'あなたは自分のために偶像を造ってはならない。上の天にあるものでも、下の地にあるものでも、地の下の水の中にあるものでも、いかなる形をも造ってはならない。'),
('JPN', '申命记', 5, 5, 9, 'それらを拝んではならない。それらに仕えてはならない。あなたの神、主であるわたしは、ねたみの神。わたしを憎む者には父の咎を子に報い、三代、四代にまで及ぼし、'),
('JPN', '申命记', 5, 5, 10, 'わたしを愛し、わたしの命令を守る者には、恵みを千代にまで施すからである。'),
('JPN', '申命记', 5, 5, 11, 'あなたは、あなたの神、主の名をみだりに口にしてはならない。主は、主の名をみだりに口にする者を罰せずにはおかない。'),
('JPN', '申命记', 5, 5, 12, '安息日を守って、これを聖なるものとせよ。あなたの神、主が命じたとおりに。'),
('JPN', '申命记', 5, 5, 13, '六日間働いて、あなたのすべての仕事をせよ。'),
('JPN', '申命记', 5, 5, 14, '七日目は、あなたの神、主の安息である。あなたはいかなる仕事もしてはならない。あなたも、あなたの息子や娘も、それにあなたの男奴隷や女奴隷、牛、ろば、いかなる家畜も、また、あなたの町囲みの中にいる寄留者も。そうすれば、あなたの男奴隷や女奴隷が、あなたと同じように休むことができる。'),
('JPN', '申命记', 5, 5, 15, 'あなたは自分がエジプトの地で奴隷であったこと、そして、あなたの神、主が力強い御手と伸ばされた御腕をもって、あなたをそこから導き出したことを覚えていなければならない。それゆえ、あなたの神、主は安息日を守るよう、あなたに命じたのである。'),
('JPN', '申命记', 5, 5, 16, 'あなたの父と母を敬え。あなたの神、主が命じたとおりに。それは、あなたの日々が長く続くようにするため、また、あなたの神、主があなたに与えようとしているその土地で幸せになるためである。'),
('JPN', '申命记', 5, 5, 17, '殺してはならない。'),
('JPN', '申命记', 5, 5, 18, '姦淫してはならない。'),
('JPN', '申命记', 5, 5, 19, '盗んではならない。'),
('JPN', '申命记', 5, 5, 20, 'あなたの隣人について、偽りの証言をしてはならない。'),
('JPN', '申命记', 5, 5, 21, 'あなたの隣人の妻を欲してはならない。あなたの隣人の家、畑、男奴隷、女奴隷、牛、ろば、すべてあなたの隣人のものを欲しがってはならない。」'),
('JPN', '申命记', 5, 5, 22, 'これらのことばを、主はあの山で火と雲と暗黒の中から、あなたがたの集会全体に大声で告げられた。ほかのことは言われなかった。そして主はそれを二枚の石の板に書いて、私に授けてくださった。'),
('JPN', '申命记', 5, 5, 23, 'あなたがたが闇の中からその御声を聞き、またその山が火で燃えていたときに、あなたがた、すなわち、あなたがたの部族のすべてのかしらたちと長老たちが私のもとに近づき、'),
('JPN', '申命记', 5, 5, 24, 'そして言った。「私たちの神、主は今、ご自分の栄光と偉大さを私たちに示されました。私たちは火の中から御声を聞きました。今日、私たちは、神が人に語られても人が生きているのを見ました。'),
('JPN', '申命记', 5, 5, 25, '今、なぜ私たちは死ななければならないのでしょうか。この大きい火は私たちを焼き尽くそうとしています。もしこの上なお私たちの神、主の御声を聞くなら、私たちは死んでしまいます。'),
('JPN', '申命记', 5, 5, 26, 'いったい肉なる者で、私たちのように、火の中から語られる生ける神の声を聞いて、なお生きている者があったでしょうか。'),
('JPN', '申命记', 5, 5, 27, 'あなたが近づいて行き、私たちの神、主が言われることをすべて聞き、私たちの神、主があなたにお告げになることをすべて私たちに告げてください。私たちは聞いて行います。」'),
('JPN', '申命记', 5, 5, 28, '主は、あなたがたが私に話していたとき、あなたがたのことばを聞かれた。主は私に言われた。「わたしは、この民があなたに話していることばを聞いた。彼らの言ったことはみな、もっともである。'),
('JPN', '申命记', 5, 5, 29, '彼らの心がこのようであって、いつまでも、わたしを恐れ、わたしのすべての命令を守るようになってほしい。そうすれば、彼らもその子孫も永久に幸せになる。'),
('JPN', '申命记', 5, 5, 30, 'さあ、彼らに『あなたがたは自分の天幕に帰りなさい』と言え。'),
('JPN', '申命记', 5, 5, 31, 'しかし、あなたは、わたしとともにここにとどまれ。わたしは、あなたが彼らに教えるすべての命令、すなわち掟と定めをあなたに告げよう。彼らは、わたしが与えて所有させようとしているその地で、それを行うのだ。」'),
('JPN', '申命记', 5, 5, 32, 'あなたがたは、あなたがたの神、主が命じられたとおりに守り行いなさい。右にも左にもそれてはならない。'),
('JPN', '申命记', 5, 5, 33, 'あなたがたの神、主が命じられた道をあくまで歩み続けなければならない。あなたがたが生き、幸せになり、あなたがたが所有するその地で、あなたの日々が長く続くようにするためである。'),
('JPN', '申命记', 5, 6, 1, 'これは、あなたがたの神、主があなたがたに教えよと命じられた命令、すなわち掟と定めである。あなたがたが渡って行って所有しようとしている地で、それらを行うようにするためである。'),
('JPN', '申命记', 5, 6, 2, 'それは、あなたの一生の間、あなたも、そしてあなたの子も孫も、あなたの神、主を恐れて、私が命じるすべての主の掟と命令を守るため、またあなたの日々が長く続くためである。'),
('JPN', '申命记', 5, 6, 3, 'イスラエルよ、聞いて守り行いなさい。そうすれば、あなたは幸せになり、あなたの父祖の神、主があなたに告げられたように、あなたは乳と蜜の流れる地で大いに増えるであろう。'),
('JPN', '申命记', 5, 6, 4, '聞け、イスラエルよ。主は私たちの神。主は唯一である。'),
('JPN', '申命记', 5, 6, 5, 'あなたは心を尽くし、いのちを尽くし、力を尽くして、あなたの神、主を愛しなさい。'),
('JPN', '申命记', 5, 6, 6, '私が今日あなたに命じるこれらのことばを心にとどめなさい。'),
('JPN', '申命记', 5, 6, 7, 'これをあなたの子どもたちによく教え込みなさい。あなたが家で座っているときも道を歩くときも、寝るときも起きるときも、これを彼らに語りなさい。'),
('JPN', '申命记', 5, 6, 8, 'これをしるしとして自分の手に結び付け、記章として額の上に置きなさい。'),
('JPN', '申命记', 5, 6, 9, 'これをあなたの家の戸口の柱と門に書き記しなさい。'),
('JPN', '申命记', 5, 6, 10, 'あなたの神、主は、あなたの父祖、アブラハム、イサク、ヤコブに誓われた地にあなたを導き入れ、あなたが建てたのではない、大きくてすばらしい町々、'),
('JPN', '申命记', 5, 6, 11, 'あなたが満たしたのではない、あらゆる良い物で満ちた家々、あなたが掘ったのではない掘り井戸、あなたが植えたのではない、ぶどう畑とオリーブ畑、これらをあなたに与えてくださる。それであなたは、食べて満ち足りるとき、'),
('JPN', '申命记', 5, 6, 12, '気をつけて、エジプトの地、奴隷の家からあなたを導き出された主を忘れないようにしなさい。'),
('JPN', '申命记', 5, 6, 13, 'あなたの神、主を恐れ、主に仕えなさい。また御名によって誓いなさい。'),
('JPN', '申命记', 5, 6, 14, 'ほかの神々に、すなわち、あなたがたの周りにいる諸国の民の神々に従って行ってはならない。'),
('JPN', '申命记', 5, 6, 15, 'あなたのうちにおられるあなたの神、主はねたみの神であるから、あなたの神、主の怒りがあなたに向かって燃え上がり、主があなたを大地の面から根絶やしにされることのないようにしなさい。'),
('JPN', '申命记', 5, 6, 16, 'あなたがたがマサで行ったように、あなたがたの神である主を試みてはならない。'),
('JPN', '申命记', 5, 6, 17, 'あなたがたの神である主の命令、主が命じられたさとしと掟を必ず守らなければならない。'),
('JPN', '申命记', 5, 6, 18, '主の目にかなう良いことをしなさい。そうすれば、あなたは幸せになり、主があなたの父祖たちに誓われた、あの良い地を所有することができる。'),
('JPN', '申命记', 5, 6, 19, '主が告げられたように、敵をことごとくあなたの前から追い払うことができる。'),
('JPN', '申命记', 5, 6, 20, '後になって、あなたの息子があなたに尋ねて、「私たちの神である主が命じられた、このさとしと掟と定めはどういうことですか」と言うなら、'),
('JPN', '申命记', 5, 6, 21, 'あなたは自分の息子にこう言いなさい。「私たちはエジプトでファラオの奴隷であったが、主が力強い御手をもって私たちをエジプトから導き出された。'),
('JPN', '申命记', 5, 6, 22, '主は私たちの目の前で、エジプトに対し、ファラオとその全家族に対して、大きくて害をもたらすしるしと不思議を行い、'),
('JPN', '申命记', 5, 6, 23, '私たちをそこから導き出された。それは、私たちの父祖たちに誓われた地に私たちを導き入れ、その地を私たちに与えるためであった。'),
('JPN', '申命记', 5, 6, 24, 'それで主は、私たちがこのすべての掟を行い、自分たちの神である主を恐れるように命じられたのである。今日のように、いつまでも私たちが幸せになり、私たちが生かされるためである。'),
('JPN', '申命记', 5, 6, 25, '私たちの神、主が命じられたように御前でこのすべての命令を守り行うとき、それは私たちの義となるのである。」'),
('JPN', '申命记', 5, 7, 1, 'あなたが入って行って所有しようとしている地に、あなたの神、主があなたを導き入れるとき、主は、あなたよりも数多くまた強い七つの異邦の民、すなわち、ヒッタイト人、ギルガシ人、アモリ人、カナン人、ペリジ人、ヒビ人、およびエブス人をあなたの前から追い払われる。'),
('JPN', '申命记', 5, 7, 2, 'あなたの神、主が彼らをあなたに渡し、あなたがこれを討つとき、あなたは彼らを必ず聖絶しなければならない。彼らと何の契約も結んではならない。また、彼らにあわれみを示してはならない。'),
('JPN', '申命记', 5, 7, 3, 'また、彼らと姻戚関係に入ってはならない。あなたの娘をその息子に嫁がせたり、その娘をあなたの息子の妻としたりしてはならない。'),
('JPN', '申命记', 5, 7, 4, 'というのは、彼らはあなたの息子を私から引き離し、ほかの神々に仕えさせ、こうして主の怒りがあなたがたに向かって燃え上がって、あなたをただちに根絶やしにするからである。'),
('JPN', '申命记', 5, 7, 5, 'むしろ彼らに対して、このようにしなければならない。彼らの祭壇を打ち壊し、石の柱を打ち砕き、彼らのアシェラ像を切り倒し、彼らの彫像を火で焼かなければならない。'),
('JPN', '申命记', 5, 7, 6, 'あなたは、あなたの神、主の聖なる民だからである。あなたの神、主は地の面のあらゆる民の中からあなたを選んで、ご自分の宝の民とされた。'),
('JPN', '申命记', 5, 7, 7, '主があなたがたを慕い、あなたがたを選ばれたのは、あなたがたがどの民よりも数が多かったからではない。事実あなたがたは、あらゆる民のうちで最も数が少なかった。'),
('JPN', '申命记', 5, 7, 8, 'しかし、主があなたがたを愛されたから、またあなたがたの父祖たちに誓った誓いを守られたから、主は力強い御手をもってあなたがたを導き出し、奴隷の家から、エジプトの王ファラオの手からあなたを贖い出されたのである。'),
('JPN', '申命记', 5, 7, 9, 'あなたは、あなたの神、主だけが神であることをよく知らなければならない。主は信頼すべき神であり、ご自分を愛し、ご自分の命令を守る者には恵みの契約を千代までも守られる。'),
('JPN', '申命记', 5, 7, 10, 'しかし、ご自分を憎む者には一人ひとりに報いて彼らを滅ぼされる。主はためらわず、ご自分を憎む者一人ひとりに報いられる。'),
('JPN', '申命记', 5, 7, 11, 'あなたは、私が今日あなたに命じる命令、すなわち掟と定めを守り行わなければならない。'),
('JPN', '申命记', 5, 7, 12, 'もしあなたがたがこれらの定めを聞き、これを守り行うなら、あなたの神、主は、あなたの父祖たちに誓われた恵みの契約をあなたのために守り、'),
('JPN', '申命记', 5, 7, 13, 'あなたを愛し、あなたを祝福し、あなたを増やす。主があなたに与えるとあなたの父祖たちに誓われた地で、あなたの胎の実も、穀物、新しいぶどう酒、油などの大地の実りも、またあなたの群れの中の子牛、群れの中の子羊も祝福される。'),
('JPN', '申命记', 5, 7, 14, 'あなたはあらゆる民の中で最も祝福される。あなたのうちには、子のいない男、子のいない女はいなくなる。あなたの家畜も同様である。'),
('JPN', '申命记', 5, 7, 15, '主はあらゆる病気をあなたから取り除き、あなたが経験したあのエジプトの悪疫を、一つもあなたにはもたらさず、あなたを憎むすべての者にこれを下される。'),
('JPN', '申命记', 5, 7, 16, 'あなたは、あなたの神、主があなたに与えるあらゆる民を滅ぼし尽くす。彼らにあわれみをかけてはならない。また彼らの神々に仕えてはならない。それがあなたへの罠となるからだ。'),
('JPN', '申命记', 5, 7, 17, 'あなたが、「これらの異邦の民は私よりも多い。どうして彼らを追い払うことができるだろうか」と考えるときにも、'),
('JPN', '申命记', 5, 7, 18, '彼らを恐れてはならない。あなたの神、主がファラオに、また全エジプトになされたことをよく覚えていなければならない。'),
('JPN', '申命记', 5, 7, 19, 'あなたが自分の目で見たあの大きな試みと、しるしと不思議と、力強い御手と伸ばされた御腕をもって、あなたの神、主はあなたを導き出された。あなたの神、主は、あなたが恐れているあらゆる民に対しても同じようにされる。'),
('JPN', '申命记', 5, 7, 20, 'また、あなたの神、主はスズメバチを彼らのうちに送り、生き残っている者たちや隠れている者たちを、あなたの前から滅ぼされる。'),
('JPN', '申命记', 5, 7, 21, '彼らの前でおびえてはならない。あなたのうちにおられるあなたの神、主は、大いなる恐るべき神だからである。'),
('JPN', '申命记', 5, 7, 22, 'あなたの神、主はこれらの異邦の民を徐々にあなたの前から追い払われる。あなたは彼らをすぐに絶ち滅ぼすことはできない。野の獣が増えて、あなたを襲うことのないようにするためである。'),
('JPN', '申命记', 5, 7, 23, 'あなたの神、主が彼らをあなたに渡し、彼らを大いにかき乱し、ついに彼らは根絶やしにされる。'),
('JPN', '申命记', 5, 7, 24, 'また、彼らの王たちをあなたの手に渡される。あなたは彼らの名を天の下から消し去る。だれ一人としてあなたの前に立ちはだかる者はなく、ついに、あなたは彼らを根絶やしにする。'),
('JPN', '申命记', 5, 7, 25, 'あなたがたは彼らの神々の彫像を火で焼かなければならない。それにかぶせた銀や金を欲しがってはならない。また自分のものとしてはならない。あなたが罠に陥らないようにするためである。それは、あなたの神、主が忌み嫌われるものである。'),
('JPN', '申命记', 5, 7, 26, '忌み嫌うべきものをあなたの家に持ち込んで、あなたもそれと同じように聖絶されたものとなってはならない。それをあくまで忌むべきものとし、あくまで忌み嫌わなければならない。それは聖絶の物だからである。'),
('JPN', '申命记', 5, 8, 1, '私が今日あなたに命じるすべての命令を、あなたがたは守り行わなければならない。そうすれば、あなたがたは生きて数を増やし、主があなたがたの父祖たちに誓われた地に入って、それを所有することができる。'),
('JPN', '申命记', 5, 8, 2, 'あなたの神、主がこの四十年の間、荒野であなたを歩ませられたすべての道を覚えていなければならない。それは、あなたを苦しめて、あなたを試し、あなたがその命令を守るかどうか、あなたの心のうちにあるものを知るためであった。'),
('JPN', '申命记', 5, 8, 3, 'それで主はあなたを苦しめ、飢えさせて、あなたも知らず、あなたの父祖たちも知らなかったマナを食べさせてくださった。それは、人はパンだけで生きるのではなく、人は主の御口から出るすべてのことばで生きるということを、あなたに分からせるためであった。'),
('JPN', '申命记', 5, 8, 4, 'この四十年の間、あなたの衣服はすり切れず、あなたの足は腫れなかった。'),
('JPN', '申命记', 5, 8, 5, 'あなたは、人がその子を訓練するように、あなたの神、主があなたを訓練されることを知らなければならない。'),
('JPN', '申命记', 5, 8, 6, 'あなたの神、主の命令を守って主の道に歩み、主を恐れなさい。'),
('JPN', '申命记', 5, 8, 7, 'あなたの神、主があなたを良い地に導き入れようとしておられるからである。そこは、谷間と山に湧き出る水の流れや、泉と深い淵のある地、'),
('JPN', '申命记', 5, 8, 8, '小麦、大麦、ぶどう、いちじく、ざくろのある地、オリーブ油と蜜のある地である。'),
('JPN', '申命记', 5, 8, 9, 'そこは、あなたが不自由なくパンを食べ、何一つ足りないものがない地であり、そこの石は鉄で、その山々からは銅を掘り出すことのできる地である。'),
('JPN', '申命记', 5, 8, 10, 'あなたが食べて満ち足りたとき、主がお与えくださった良い地について、あなたの神、主をほめたたえなければならない。'),
('JPN', '申命记', 5, 8, 11, '気をつけなさい。私が今日あなたに命じる、主の命令と主の定めと主の掟を守らず、あなたの神、主を忘れることがないように。'),
('JPN', '申命记', 5, 8, 12, 'あなたが食べて満ち足り、立派な家を建てて住み、'),
('JPN', '申命记', 5, 8, 13, 'あなたの牛や羊の群れが増え、銀や金が増し、あなたの所有物がみな豊かになって、'),
('JPN', '申命记', 5, 8, 14, 'あなたの心が高ぶり、あなたの神、主を忘れることがないように。主はあなたをエジプトの地、奴隷の家から導き出し、'),
('JPN', '申命记', 5, 8, 15, '燃える蛇やサソリのいるあの大きな恐ろしい荒野、水のない乾ききった地を通らせ、硬い岩からあなたのために水を流れ出させ、'),
('JPN', '申命记', 5, 8, 16, 'あなたの父祖たちが知らなかったマナを、荒野であなたに食べさせてくださった。それは、あなたを苦しめ、あなたを試し、ついにはあなたを幸せにするためだったのである。'),
('JPN', '申命记', 5, 8, 17, 'あなたは心のうちで、「私の力、私の手の力がこの富を築き上げたのだ」と言わないように気をつけなさい。'),
('JPN', '申命记', 5, 8, 18, 'あなたの神、主を心に据えなさい。主があなたに富を築き上げる力を与えるのは、あなたの父祖たちに誓った契約を今日のように果たされるためである。'),
('JPN', '申命记', 5, 8, 19, 'もしもあなたが、あなたの神、主を忘れ、ほかの神々に従って行き、それらに仕え、それらを拝むようなことがあれば、今日、私はあなたがたにこう警告する。あなたがたは必ず滅びる。'),
('JPN', '申命记', 5, 8, 20, '主があなたがたの前から滅ぼされる国々のように、あなたがたも滅びる。あなたがたが自分たちの神、主の御声に聞き従わないからである。'),
('JPN', '申命记', 5, 9, 1, '聞け、イスラエルよ。あなたは今日、ヨルダン川を渡って、あなたよりも大きくて強い国々を占領しようとしている。その町々は大きく、城壁は天に高くそびえている。'),
('JPN', '申命记', 5, 9, 2, 'あなたがよく知っているアナク人は、大きくて背が高い民である。あなたは「だれがアナク人に立ち向かえるだろうか」と言われるのを聞いたことがある。'),
('JPN', '申命记', 5, 9, 3, '今日、知りなさい。あなたの神、主ご自身が、焼き尽くす火としてあなたの前を進み、彼らを根絶やしにされる。主があなたの前で彼らを征服される。あなたは主が約束されたように、彼らをただちに追い払って滅ぼすのだ。'),
('JPN', '申命记', 5, 9, 4, 'あなたの神、主があなたの前から彼らを追い出されたとき、あなたは心の中で、「私が正しいから、主が私をこの地に導き入れ、所有させてくださったのだ」と言ってはならない。これらの国々の邪悪さのゆえに、主はあなたの前から彼らを追い出そうとしておられるのだ。'),
('JPN', '申命记', 5, 9, 5, 'あなたが彼らの地を所有することができるのは、あなたが正しいからではなく、またあなたの心が真っ直ぐだからでもない。これらの国々の邪悪さのゆえに、あなたの神、主があなたの前から彼らを追い出そうとしておられるのだ。また主があなたの父祖、アブラハム、イサク、ヤコブになさった誓いを果たすためである。'),
('JPN', '申命记', 5, 9, 6, '知りなさい。あなたの神、主は、あなたの正しさゆえに、この良い地をあなたに与えて所有させてくださるのではない。事実、あなたはうなじを固くする民なのだ。'),
('JPN', '申命记', 5, 9, 7, 'あなたは荒野であなたの神、主をどれほど怒らせたかを忘れずに覚えていなさい。エジプトの地を出た日からこの場所に来るまで、あなたがたは主に逆らい続けてきた。'),
('JPN', '申命记', 5, 9, 8, 'あなたがたはホレブで主を怒らせた。それで主はあなたがたに怒りを燃やし、あなたがたを根絶やしにしようとされたのである。'),
('JPN', '申命记', 5, 9, 9, '私が石の板、すなわち、主があなたがたと結んだ契約の板を受け取るために山に登ったとき、私は四十日四十夜、山にとどまり、パンも食べず水も飲まなかった。'),
('JPN', '申命记', 5, 9, 10, '主は、神の指で書き記された石の板二枚を私に授けてくださった。その上には、あの集まりの日に、主が山で火の中からあなたがたに告げられたことばが、すべてそのまま書かれていた。'),
('JPN', '申命记', 5, 9, 11, 'こうして四十日四十夜の終わりに、主はその二枚の石の板、すなわち契約の板を私に授けてくださった。'),
('JPN', '申命记', 5, 9, 12, 'そして主は私に言われた。「さあ、急いでここから下れ。あなたがエジプトから導き出したあなたの民は堕落してしまった。彼らはわたしが命じた道から早くも外れて、自分たちのために鋳物の像を造った。」'),
('JPN', '申命记', 5, 9, 13, 'さらに主は私にこう言われた。「わたしはこの民を見てきたが、実にうなじを固くする民である。'),
('JPN', '申命记', 5, 9, 14, 'わたしのするがままにさせよ。わたしは彼らを根絶やしにし、彼らの名を天の下から消し去る。しかし、わたしはあなたを、彼らよりも強くまた数の多い国民にする。」'),
('JPN', '申命记', 5, 9, 15, '私は向きを変えて山から下りた。山は火で燃えていた。二枚の契約の板は私の両手にあった。'),
('JPN', '申命记', 5, 9, 16, '私が見ると、見よ、あなたがたは自分たちの神、主の前に罪ある者となって、自分たちのために鋳物の子牛を造り、主があなたがたに命じられた道から早くも外れてしまっていた。'),
('JPN', '申命记', 5, 9, 17, 'それで私はその二枚の板をつかみ、両手でそれを投げつけ、あなたがたの目の前でそれを打ち砕いた。'),
('JPN', '申命记', 5, 9, 18, 'それから私は、前のように四十日四十夜、主の前にひれ伏して、パンも食べず水も飲まなかった。あなたがたが罪ある者となって、主の目に悪であることを行い、御怒りを引き起こした、そのすべての罪のゆえであった。'),
('JPN', '申命记', 5, 9, 19, 'こうしたのは、主が激しく怒ってあなたがたを根絶やしにしようとされたその怒りと憤りが、私には怖かったからであった。しかし、そのときも主は私の願いを聞き入れてくださった。'),
('JPN', '申命记', 5, 9, 20, '主はアロンに向かって激しく怒り、彼を滅ぼそうとされたが、そのとき私はアロンのためにもとりなしをした。'),
('JPN', '申命记', 5, 9, 21, '私はあなたがたの罪、あなたがたが造ったその子牛を取って火で焼き、打ち砕き、ちりになるまでよくすりつぶした。そして私はそのちりを、山から流れ下る川に投げ捨てた。'),
('JPN', '申命记', 5, 9, 22, 'また、あなたがたは、タブエラでもマサでもキブロテ・ハ・タアワでも主を怒らせた。'),
('JPN', '申命记', 5, 9, 23, '主は、あなたがたをカデシュ・バルネアから遣わしたとき、「上って行って、わたしがあなたがたに与えている地を占領せよ」と言われたが、あなたがたは自分たちの神、主の命令に逆らい、主を信頼せず、その御声に聞き従わなかった。'),
('JPN', '申命记', 5, 9, 24, '私があなたがたを知った日から、あなたがたは主に逆らい続けてきた。'),
('JPN', '申命记', 5, 9, 25, 'それで私は、その四十日四十夜、主の前にひれ伏していた。それは、主があなたがたを根絶やしにすると言われたからである。'),
('JPN', '申命记', 5, 9, 26, '私は主に祈って言った。「神、主よ、あなたのゆずりの民を滅ぼさないでください。彼らは、あなたが偉大な力をもって贖い出し、力強い御手をもってエジプトから導き出された民です。'),
('JPN', '申命记', 5, 9, 27, 'あなたのしもべ、アブラハム、イサク、ヤコブを思い起こしてください。そして、この民の頑なさと悪と罪に御顔を向けないでください。'),
('JPN', '申命记', 5, 9, 28, 'そうでないと、あなたがそこから私たちを導き出されたあの国では、こう言うでしょう。『主は、約束した地に彼らを導き入れることができなかったので、また彼らを憎んだので、彼らを荒野で死なせようとして連れ出したのだ。』'),
('JPN', '申命记', 5, 9, 29, 'しかし彼らは、あなたのゆずりの民です。あなたが、その大いなる力と伸ばされた御腕をもって導き出された民です。」'),
('JPN', '申命记', 5, 10, 1, 'そのとき、主は私に言われた。「前のような石の板を二枚切って作り、山に登り、わたしのもとに来い。また木の箱を一つ作れ。'),
('JPN', '申命记', 5, 10, 2, 'その板の上に、わたしは、あなたが砕いたあの最初の板にあったことばを書き記す。あなたはそれを箱の中に納めよ。」'),
('JPN', '申命记', 5, 10, 3, 'そこで私はアカシヤ材の箱を一つ作り、前のような石の板を二枚切り取り、その二枚の板を手にして山に登って行った。'),
('JPN', '申命记', 5, 10, 4, '主はそれらの板に、あの集まりの日に、山で火の中からあなたがたに告げた十のことばを、前と同じ文で書き記された。主はそれを私に与えられた。'),
('JPN', '申命记', 5, 10, 5, '私は向き直って山を下り、それらの板を、私が作った箱の中に納めた。主が私に命じられたとおり、それらはそこにある。'),
('JPN', '申命记', 5, 10, 6, '──イスラエルの子らは、ベエロテ・ベネ・ヤアカンからモセラに旅立った。アロンはそこで死に、そこに葬られた。それで彼の子エルアザルが彼に代わって祭司の職に任じられた。'),
('JPN', '申命记', 5, 10, 7, 'そこから彼らは旅立ってグデゴダに行き、またグデゴダから、川の流れる地ヨテバタに進んだ。'),
('JPN', '申命记', 5, 10, 8, 'そのとき、主はレビ部族を選り分けて、主の契約の箱を運び、主の前に立って仕え、また御名によって祝福するようにされた。今日までそうである。'),
('JPN', '申命记', 5, 10, 9, 'それゆえ、レビには兄弟たちと同じようには相続地が割り当てられなかった。あなたの神、主が彼について言われたように、主が彼へのゆずりなのである──'),
('JPN', '申命记', 5, 10, 10, '私は初めのときのように、四十日四十夜、山にとどまった。主はこのときもまた、私の願いを聞き入れ、主はあなたを滅ぼすことを思いとどまられた。'),
('JPN', '申命记', 5, 10, 11, 'そして主は私に、「民の先頭に立って進め。そうすれば彼らは、わたしが彼らに与えると父祖たちに誓った地に入り、その地を占領することができる」と言われた。'),
('JPN', '申命记', 5, 10, 12, 'イスラエルよ。今、あなたの神、主が、あなたに求めておられることは何か。それは、ただあなたの神、主を恐れ、主のすべての道に歩み、主を愛し、心を尽くし、いのちを尽くしてあなたの神、主に仕え、'),
('JPN', '申命记', 5, 10, 13, 'あなたの幸せのために私が今日あなたに命じる、主の命令と掟を守ることである。')
on conflict (version, book, chapter, verse) do nothing;
